    static isEmpty(arr) {
        return arr.length === 0;
    }
    static head(arr) {
        return arr[0];
    }
    static last(arr) {
        return arr[arr.length - 1];
    }
    static forEach(arr, call) {
        for (let i = 0; i < arr.length; i++) {
            call(arr[i], i);
        }
    }
    ;
    static forEachInverse(arr, call) {
        for (let i = arr.length - 1; i >= 0; i--) {
            call(arr[i], i);
        }
    }
    ;
