class StringEx {
    static format(text, ...args) {
        if (arguments.length > 1) {
            if (arguments.length == 2 && typeof (arguments[1]) == "object") {
                let obj = arguments[1];
                for (var key in obj) {
                    if (obj !== undefined) {
                        var reg = new RegExp("\\$({" + key + "})", "g");
                        text = text.replace(reg, function () { return obj[key]; });
                    }
                }
            }
            else {
                for (var i = 1; i < arguments.length; i++) {
                    if (arguments[i] !== undefined) {
                        var reg2 = new RegExp("\\$({)" + (i - 1) + "(})", "g");
                        text = text.replace(reg2, arguments[i]);
                    }
                }
            }
        }
        return text;
    }
    ;
}
