const DEFAULT_SYS_KEY = "DEFAULT_SYS_KEY_KBX";
class Base {
    constructor(key) {
        this._keyStore = null;
        this._data = {};
        this._keyStore = key;
        if (key) {
            this._loadData();
        }
    }
    setDelegate(delegate) {
        this._delegate = delegate;
    }
    setStoreKey(key) {
        this._keyStore = key;
        this._loadData();
    }
    getVar(key) {
        if (this._keyStore == null) {
            window["MyGame"].openLog && console.log("key 没有初始化");
            return null;
        }
        if (this._delegate) {
            return this._delegate.getVar(key);
        }
        return this._data[key];
    }
    setVar(key, value) {
        if (!key) {
            console.error("key is null");
            return;
        }
        if (this._delegate) {
            return this._delegate.setVar(key, value);
        }
        this._data[key] = value;
        this._saveData();
    }
    delVar(key) {
        if (this._delegate) {
            return this._delegate.delVar(key);
        }
        delete this._data[key];
        this._saveData();
    }
    _loadData() {
        let text = Laya.LocalStorage.getItem(this._keyStore);
        if (text && text !== "") {
            this._data = JSON.parse(text);
        }
    }
    _saveData() {
        let text = JSON.stringify(this._data);
        Laya.LocalStorage.setItem(this._keyStore, text);
    }
}
class VarMgr {
    constructor() {
        this._sysKey = DEFAULT_SYS_KEY;
        this._sysObj = new Base(this._sysKey);
        this._userObj = new Base();
        this._otherObjs = new Map();
        this._userInited = false;
    }
    setDelegate(delegate) {
        this._userObj.setDelegate(delegate);
    }
    getSysVar(key) {
        return this._sysObj.getVar(key);
    }
    setSysVar(key, value) {
        this._sysObj.setVar(key, value);
    }
    delSysVar(key) {
        this._sysObj.delVar(key);
    }
    setUserStoreKey(key) {
        if (typeof (key) == "number")
            key = key.toString();
        this._userInited = true;
        this._userObj.setStoreKey(key);
    }
    getUserVar(key) {
        if (typeof (key) == "number")
            key = key.toString();
        if (!this._userInited) {
            window["MyGame"].openLog && console.log("not login cann't use uservar!");
            return null;
        }
        return this._userObj.getVar(key);
    }
    setUserVar(key, value) {
        if (!this._userInited) {
            window["MyGame"].openLog && console.log("not login cann't use uservar!");
            return;
        }
        this._userObj.setVar(key, value);
    }
    delUserVar(key) {
        if (!this._userInited) {
            window["MyGame"].openLog && console.log("not login cann't use uservar!");
            return;
        }
        this._userObj.delVar(key);
    }
    getOtherVar(keyStore, key) {
        keyStore = keyStore + "_KBX";
        let obj = this._otherObjs.get(keyStore);
        if (!obj) {
            obj = new Base(keyStore);
            this._otherObjs.set(keyStore, obj);
        }
        return obj.getVar(key);
    }
    setOtherVar(keyStore, key, value) {
        keyStore = keyStore + "_KBX";
        let obj = this._otherObjs.get(keyStore);
        if (!obj) {
            obj = new Base(keyStore);
            this._otherObjs.set(keyStore, obj);
        }
        obj.setVar(key, value);
    }
    delOtherVar(keyStore, key) {
        keyStore = keyStore + "_KBX";
        let obj = this._otherObjs.get(keyStore);
        if (!obj) {
            return null;
        }
        obj.delVar(key);
    }
}

