class ViewBaseBtnClickPlugin extends ViewBaseClipPlugin {
    constructor() {
        super();
        this._clickTime = 300;
        this._clickMap = new Map();
        this._clickList = new Array();
    }
    set clickTime(value) {
        if (!isNaN(value) && value > 0) {
            this._clickTime = value;
        }
    }
    clear() {
        this.clearAllClick();
        super.clear();
    }
    onEnable() {
        super.onEnable();
    }
    onDisable() {
        super.onDisable();
    }
    onDestroy() {
        super.onDestroy();
        this.clearAllClick();
    }
    addClick(node, callback, caller, once = false, time = this._clickTime, eventType = Laya.Event.CLICK, ...args) {
        if (!node && this.hasClick(node)) {
            return;
        }
        this._clickMap.set(node.name, node);
        this._clickList.push(node);
        node["lastClickTime"] = Date.now();
        node[once ? "once" : "on"](eventType, caller, (evt) => {
            if (Date.now() - node["lastClickTime"] > time) {
                node["lastClickTime"] = Date.now();
                callback.apply(caller, [evt, args]);
            }
        });
    }
    hasClick(node) {
        return this._clickMap.has(node.name);
    }
    clearClick(node) {
        if (!node && this.hasClick(node)) {
            return;
        }
        this._clickMap.delete(node.name);
        let index = this._clickList.indexOf(node);
        if (index != -1) {
            this._clickList.splice(index, 1);
        }
        node.offAll(Laya.Event.CLICK);
        node.offAll(Laya.Event.MOUSE_DOWN);
        node.offAll(Laya.Event.MOUSE_UP);
    }
    clearAllClick() {
        this._clickMap.clear();
        this._clickList.forEach((node) => {
            if (node) {
                delete node["lastClickTime"];
                node.offAll(Laya.Event.CLICK);
                node.offAll(Laya.Event.MOUSE_DOWN);
                node.offAll(Laya.Event.MOUSE_UP);
            }
        });
        this._clickList.length = 0;
    }
}

