class UIMgrLayerBase {
    constructor(owner, type, rootNode) {
        this.type = -1;
        this.rootNode = null;
        this.owner = owner;
        this.type = type;
        this.rootNode = rootNode;
    }
    static createLayers(owner, rootNode) {
        let layers = new Map();
        let mapNode = rootNode.addChild(new Laya.Sprite());
        mapNode.name = "mapNode";
        let layerMap = new UIMgrLayerMap(owner, UIMGR_LAYER.UIMGR_LAYER_MAP, mapNode);
        layers.set(UIMGR_LAYER.UIMGR_LAYER_MAP, layerMap);
        let permBotmNode = rootNode.addChild(new Laya.Sprite());
        permBotmNode.name = "permanentBottom";
        let layePermBotm = new UIMgrLayerPermBottom(owner, UIMGR_LAYER.UIMGR_LAYER_PERMANENT_BOTTOM, permBotmNode);
        layers.set(UIMGR_LAYER.UIMGR_LAYER_PERMANENT_BOTTOM, layePermBotm);
        let rootUINode = rootNode.addChild(new Laya.Sprite());
        rootUINode.name = "rootUINode";
        let layerRootUI = new UIMgrLayerRootUI(owner, UIMGR_LAYER.UIMGR_LAYER_ROOTUI, rootUINode);
        layers.set(UIMGR_LAYER.UIMGR_LAYER_ROOTUI, layerRootUI);
        let permTopNode = rootNode.addChild(new Laya.Sprite());
        permTopNode.name = "permanentTop";
        let layePermTop = new UIMgrLayerPermTop(owner, UIMGR_LAYER.UIMGR_LAYER_PERMANENT_TOP, permTopNode);
        layers.set(UIMGR_LAYER.UIMGR_LAYER_PERMANENT_TOP, layePermTop);
        let rootSysNode = rootNode.addChild(new Laya.Sprite());
        rootSysNode.name = "rootSysNode";
        let layerRootsys = new UIMgrLayerRootSys(owner, UIMGR_LAYER.UIMGR_LAYER_ROOTSYS, rootSysNode);
        layers.set(UIMGR_LAYER.UIMGR_LAYER_ROOTSYS, layerRootsys);
        return layers;
    }
    showUI(configName, ...args) { return null; }
    getShowUI(configName) { return null; }
    closeUI(configName) { }
    closeByObj(ui) { }
    closeAllUI(except = []) { }
    isUIShow(configName) { return false; }
    isUILoaded(configName) { return false; }
    updateData(configName, types, ...arg) { }
    onUIAwake(ui) { }
    onUIEnable(ui) { }
    dealPosType(configName, ui) {
        let viewConfig = ViewBase.ViewConfig[configName];
        let UI_POS = UIDefine.UI_POS;
        let type = viewConfig.posType || UI_POS.TOP;
        if ((Laya.stage.height / Laya.stage.width) > (UIDefine.DESIGN_HEIGHT / UIDefine.DESIGN_WIDTH)) {
            type = viewConfig.posType || UI_POS.CENTER_BOTTOM;
        }
        let height = this.rootNode.height;
        let width = this.rootNode.width;
        if (ui.height == 1136 && type == UI_POS.FULL) {
            if (type == UI_POS.FULL) {
                ui.height = ui.parent.height;
            }
            else {
                ui.y = (Laya.stage.height - ui.height >> 1) - this.rootNode.y;
            }
        }
        let offx = 0;
        let offy = 0;
        switch (type) {
            case UI_POS.CENTER_BOTTOM:
                offy = (height - UIDefine.BOTTOM_TOOLBAR_H - ui.height) / 2;
                offy = Math.max(0, offy);
                break;
            case UI_POS.CENTER:
                offx = (width - ui.width) / 2;
                offy = height - ui.height >> 1;
                break;
            case UI_POS.BOTTOM:
                offy = height - ui.height - UIDefine.BOTTOM_TOOLBAR_H;
                break;
            default:
                break;
        }
        ui.x = offx;
        ui.y = offy;
    }
}

class UIMgrLayerMap extends UIMgrLayerBase {
    constructor(owner, type, rootNode) {
        super(owner, type, rootNode);
        this._sceneMap = new Map();
    }
    addMap(name, scene) {
        this._sceneMap.set(name, scene);
        this.rootNode.addChild(scene);
    }
    hasMap(name) {
        return !!this._sceneMap.get(name);
    }
    showMap(name) {
        this.hideMapAll();
        let scene = this._sceneMap.get(name);
        scene.visible = true;
    }
    hideMap(name) {
        let scene = this._sceneMap.get(name);
        if (scene)
            scene.visible = false;
    }
    hideMapAll() {
        this._sceneMap.forEach((scene, name) => {
            scene.visible = false;
        });
    }
}

class UIMgrLayerPermanent extends UIMgrLayerBase {
    constructor(owner, type, rootNode) {
        super(owner, type, rootNode);
        this._permanentUI = new Map();
    }
    showPermanentUI(configName, ...args) {
        let viewConfig = ViewBase.ViewConfig[configName];
        if (viewConfig.wtype != UIDefine.WIN_TYPE.PERMANENT_BOTTOM &&
            viewConfig.wtype != UIDefine.WIN_TYPE.PERMANENT_TOP) {
            sg.loge("窗口类型错误:" + configName);
            return;
        }
        let ui = this._permanentUI.get(configName);
        if (ui) {
            if (ui.destroyed) {
                this._permanentUI.delete(configName);
            }
            else {
                if (viewConfig.permShowNotRemove) {
                    ui.visible = true;
                    return ui;
                }
                ui.removeSelf();
                ui.visible = true;
                ui.init(configName, ...args);
                this.rootNode.addChild(ui);
                return ui;
            }
        }
        ui = new viewConfig.cls();
        this._permanentUI.set(configName, ui);
        ui.init(configName, ...args);
        this.rootNode.addChild(ui);
        return ui;
    }
    isPermanentLoaded(configName) {
        let ui = this.getPermanentUI(configName);
        if (!ui)
            return false;
        return ui.hasLoaded();
    }
    isPermanentVisible(configName) {
        let ui = this.getPermanentUI(configName);
        if (!ui)
            return false;
        return ui.visible;
    }
    getPermanentUI(configName) {
        return this._permanentUI.get(configName);
    }
    hidePermanentUI(configName) {
        let ui = this._permanentUI.get(configName);
        if (!ui)
            return;
        ui.visible = false;
    }
    setPermanentUIVisibleTrue(configName) {
        let ui = this._permanentUI.get(configName);
        if (!ui)
            return;
        ui.visible = true;
    }
    removePermanentUI(configName, isDestroy = true) {
        let ui = this._permanentUI.get(configName);
        if (!ui)
            return;
        if (isDestroy) {
            this._permanentUI.delete(configName);
            ui.destroy();
        }
        else {
            ui.removeSelf();
        }
    }
    removeAllPermanentUI() {
        this._permanentUI.forEach((ui) => {
            ui.destroy();
        });
        this._permanentUI.clear();
    }
    updateData(configName, types, ...args) {
        let ui = this.getPermanentUI(configName);
        if (ui) {
            ui.updateData(types, ...args);
        }
    }
    onUIAwake(ui) {
        super.onUIEnable(ui);
        if (!this.getPermanentUI(ui.configName))
            return;
        this.dealPosType(ui.configName, ui);
    }
    isUIShow(configName) {
        return this.isPermanentVisible(configName);
    }
}

