                    {
                        let datas = args[0];
                        if (datas.length == 0)
                            break;
                        let lines = [];
                        for (let v of datas) {
                            lines.push(this._makeBuffPlay(v));
                            lines.push(mgr.UIAssist.getHtmlSpace(1));
                        }
                        this._callUI("add_line", lines.join(""));
                    }
