        _dealErrorAD(err, plusMsg) {
            if (!err || !err.errMsg)
                return;
            if (/no advertisement/.test(err.errMsg)
                || /operateWXDataForAd:fail/.test(err.errMsg)) {
                this.qqSdk.showModal({
                    title: "",
                    content: "无适合广告推送，请稍后再试",
                    showCancel: false,
                });
                return;
            }
            if (/can't invoke load\(\) while video-ad is showed/.test(err.errMsg))
                return;
            let v1 = JSON.stringify(err);
            sg.loge(`${plusMsg} err:${v1}`);
        }
        showAD(cbk, src, params) {
            if (this._inShowAD)
                return;
            window["MyGame"].openLog && mgr.gplatform.log("showAD");
            this._inShowAD = true;
            this._showADCbk = cbk;
            let hasUploadErr = false;
            sg.timer.after(10000, this, this._cancelShowAD);
            if (!this._videoAd) {
                let sdkParams = mgr.gplatform.sdkParams;
                let adid = sdkParams["adunit_id"];
                if (sdkParams["adunit_id2"]) {
                    let idx = mgr.toolsMgr.randomInt(0, 1);
                    if (idx == 1) {
                        adid = sdkParams["adunit_id2"];
                    }
                }
                let videoAd = this.qqSdk.createRewardedVideoAd({
                    adUnitId: adid,
                });
                window["MyGame"].openLog && mgr.gplatform.log("showAD createAd", adid);
                this._videoAd = videoAd;
                videoAd.onClose(res => {
                    this._inShowAD = false;
                    sg.timer.clear(this, this._cancelShowAD);
                    window["MyGame"].openLog && mgr.gplatform.log('showAD onClose', res);
                    let cbk = this._showADCbk;
                    this._showADCbk = null;
                    if (res && res.isEnded) {
                        cbk && cbk(true);
                    }
                    else {
                        cbk && cbk(false);
                    }
                });
                videoAd.onError(err => {
                    this._inShowAD = false;
                    sg.timer.clear(this, this._cancelShowAD);
                    if (!hasUploadErr) {
                        this._dealErrorAD(err, `showAD onError src:${src}`);
                        hasUploadErr = true;
                    }
                    let cbk = this._showADCbk;
                    this._showADCbk = null;
                    cbk && cbk(false, err);
                });
            }
            this._videoAd.load()
                .then(() => this._videoAd.show())
                .catch((err) => {
                window["MyGame"].openLog && mgr.gplatform.log('激励视频 失败重试', err);
                this._videoAd.load()
                    .then(() => this._videoAd.show())
                    .catch(err => {
                    this._inShowAD = false;
                    sg.timer.clear(this, this._cancelShowAD);
                    if (!hasUploadErr) {
                        this._dealErrorAD(err, `showAD onError2 src:${src}`);
                        hasUploadErr = true;
                    }
                    let cbk = this._showADCbk;
                    this._showADCbk = null;
                    cbk && cbk(false, err);
                });
            });
        }
