        _writeBase64Img(base64Data) {
            let wx = this.wxRawSdk;
            const fs = wx.getFileSystemManager();
            var times = new Date().getTime();
            var imgPath = wx.env.USER_DATA_PATH + '/' + times + '.png';
            let data = base64Data.slice(22);
            window["MyGame"].openLog && console.log("_writeBase64Img", data.length, imgPath);
            try {
                const res = fs.writeFileSync(imgPath, data, 'base64');
                window["MyGame"].openLog && console.log("_writeBase64Img suc", res);
            }
            catch (e) {
                let msg = e.errMsg || e.message || e.toString();
                if (/the maximum size of the file storage limit is exceeded/.test(msg)) {
                    console.error("storage limit clearStorageSync");
                    wx.clearStorageSync();
                }
                console.error("_writeBase64Img failed", msg, e);
            }
            return imgPath;
        }
        _removeWxFile(path) {
            let wx = this.wxRawSdk;
            const fs = wx.getFileSystemManager();
            try {
                const res = fs.unlinkSync(path);
                window["MyGame"].openLog && console.log("_removeWxFile", res);
            }
            catch (e) {
                console.error("_removeWxFile", e);
            }
        }
        captureShareSdk(view = null, rect = null) {
            let tex = mgr.toolsMgr.captureView2(view, rect);
            let width = 500;
            let height = 400;
            let spr = new Laya.Sprite();
            spr.width = width;
            spr.height = height;
            spr.texture = tex;
            let canvas = spr.drawToCanvas(width, height, 0, 0);
            var base64Data = canvas.source.toDataURL("image/png");
            let tempPath = this._writeBase64Img(base64Data);
            this.wxRawSdk.shareAppMessage({
                imageUrl: tempPath,
                destWidth: width,
                destHeight: height,
            });
            sg.timer.after(1000, null, () => {
                this._removeWxFile(tempPath);
            });
        }
