        requestSubscribeMsg(ids, cbk = undefined) {
            if (!this.sdkGame.canSubscribeMsg()) {
                window["MyGame"].openLog && console.log("当前平台不支持消息订阅", ids);
                cbk(false);
                return;
            }
            let sdkParams = mgr.gplatform.sdkParams;
            if (!sdkParams["subscribe_msg"]) {
                console.error("sdk subscribe_msg参数没配置");
                return;
            }
            let templIds = [];
            for (let id of ids) {
                let str = sdkParams["subscribe_msg"][id];
                if (!str || str == "") {
                    window["MyGame"].openLog && console.log("subscribe_msg 缺少id");
                    continue;
                }
                templIds.push(sdkParams["subscribe_msg"][id]);
            }
            if (templIds.length == 0) {
                console.error("subscribe_msg 缺少id");
                return;
            }
            this.sdkGame.requestSubscribeMsg(templIds, cbk);
        }
