        createGameClubButton(btn, cbk = null) {
            if (btn.width == 0 || btn.height == 0) {
                console.error("createGameClubButton button size error");
                return;
            }
            let pt = new Laya.Point(0, 0);
            btn.localToGlobal(pt);
            let rectBtn = new Laya.Rectangle(pt.x, pt.y, btn.width, btn.height);
            let Browser = Laya.Browser;
            let ratex = Browser.clientWidth / 640;
            let ratey = Browser.clientHeight / 1136;
            let rate = Math.min(ratex, ratey);
            let rectWx = new Laya.Rectangle(rectBtn.x * rate, rectBtn.y * rate, rectBtn.width * rate, rectBtn.height * rate);
            if (false) {
                let spr = new Laya.Sprite();
                let rect = rectBtn;
                spr.graphics.drawRect(rect.x, rect.y, rect.width, rect.height, "#ff0000");
                Laya.stage.addChild(spr);
                window["MyGame"].openLog && console.log("-----------------------------");
                window["MyGame"].openLog && console.log(`size:[${Browser.clientWidth}, ${Browser.clientHeight}] ratio:${Browser.pixelRatio}`);
                window["MyGame"].openLog && console.log(`rate:${rate} [${ratex},${ratey}]`);
                window["MyGame"].openLog && console.log(`rectbtn:${rectBtn} pt:[${btn.x},${btn.y}]`);
                window["MyGame"].openLog && console.log(`rectWx:${rectWx}`);
                window["MyGame"].openLog && console.log(`btn anchor:[${btn.anchorX},${btn.anchorY}] pivot:[${btn.pivotX},${btn.pivotY}]`);
                window["MyGame"].openLog && console.log("-----------------------------");
            }
            return this.sdkGame.createGameClubButton(rectWx, cbk);
        }
