        init() {
            this._initSDK();
            this._initLang();
        }
        login(cbk) {
            this._sdkLoginCbk = cbk;
            let loginType = this._loginType;
            if (mgr.gplatform.gVo.isBgLogin) {
                loginType = 2;
            }
            switch (loginType) {
                case 0:
                    {
                        let params = { account: "test" };
                        let acc = sg.varmgr.getSysVar("login_user_account");
                        if (acc && acc.name) {
                            params.account = acc.name;
                        }
                        if (mgr.gplatform.gVo.isBgLogin) {
                            this._onSdkBgLogin(params);
                        }
                        else {
                            this._onSdkLoginEnd(params);
                        }
                    }
                    break;
                case 1:
                    this._loginSdk();
                    break;
                case 2:
                    {
                        if (mgr.gplatform.gVo.isBgLogin) {
                            this._onSdkBgLogin(mgr.gplatform.urlParams);
                        }
                        else {
                            this._onSdkLoginEnd(mgr.gplatform.urlParams);
                        }
                    }
                    break;
                default:
                    break;
            }
        }
        _onSdkBgLogin(params) {
            window["MyGame"].openLog && mgr.gplatform.log("_onLoginEnd", params);
            let gVo = mgr.gplatform.gVo;
            if (params.isbglogin) {
                if (params.isdebug)
                    gVo.isDebug = params.isdebug == "1";
                if (params.agentId)
                    gVo.agentId = parseInt(params.agintid);
                if (params.agentname)
                    gVo.agentName = params.agentname;
                if (params.httpstate)
                    gVo.httpState = parseInt(params.httpstate);
                if (params.usehttps)
                    gVo.useHttps = params.usehttps == "1";
                if (params.isverify)
                    gVo.isVerifyVersion = params.isverify == "1";
            }
            let account = params.account || "test";
            if (params.isreload) {
                account = params.isreload;
            }
            mgr.gplatform.gVo.isBgLogin = true;
            let phpVo = mgr.gplatform.accountPhpVo;
            phpVo.account = account;
            phpVo.fcm = 0;
            phpVo.extend = "";
            phpVo.time = Date.now();
            phpVo.sign = "";
            phpVo.isNew = false;
            this._sdkLoginCbk && this._sdkLoginCbk(null);
        }
        getDeviceInfo() {
            return null;
        }
        getDeviceInfoStr() {
            return "";
        }
