(function (sdk) {
    class SdkLoginDalan extends sdk.SdkLoginBase {
        constructor() {
            super();
            this._loginType = 2;
            this._sdkClassStr = '_hm';
        }
        getDeviceInfo() {
            if (this.rawSdk.getDeviceInfo) {
                return this.rawSdk.getDeviceInfo();
            }
            return null;
        }
        _initSDK() {
            mgr.gplatform.gVo.loginImgState = 2;
        }
        _onSdkLoginEnd(params) {
            window["MyGame"].openLog && mgr.gplatform.log("_onLoginEnd LoginDalan", params);
            let gVo = mgr.gplatform.gVo;
            let sdkParams = mgr.gplatform.sdkParams;
            let obj = {};
            obj['agent_id'] = gVo.agentId;
            obj['agent_flag'] = gVo.agentName;
            obj['source'] = gVo.sourceFrom;
            obj['game_id'] = sdkParams.game_id = params.game_id;
            obj['game_name'] = sdkParams.game_name = params.game_name;
            obj['game_ver'] = sdkParams.game_ver = params.game_ver;
            obj['game_channel_id'] = sdkParams.game_channel_id = params.game_channel_id;
            obj['channel_id'] = sdkParams.channel_id = params.channel_id;
            obj['uid'] = sdkParams.uid = params.uid;
            obj['session_id'] = sdkParams.session_id = params.session_id;
            if (params.isreload) {
                obj['agent_flag'] = "dev";
                obj['code'] = params.isreload;
            }
            this._sdkLoginCbk && this._sdkLoginCbk(obj);
        }
        onGetPhpAccount(data) {
            if (data.info) {
                let uid = mgr.gplatform.accountPhpVo.account;
                let token = data.info.access_token;
                let prefix = data.info.prefix;
                let obj = { uid: uid, token: token, prefix: prefix };
                window["MyGame"].openLog && mgr.gplatform.log("rawSdk.onLoginRsp LoginDalan", obj);
                this.rawSdk.onLoginRsp(obj);
            }
        }
        exitGame() {
            this.rawSdk.reloadGame();
            return;
            let hrefUrl = Laya.Browser.window.location.href;
            let vo = mgr.gplatform.accountPhpVo;
            if (vo.account) {
                if (hrefUrl && typeof hrefUrl === 'string') {
                    let params = this.getUrlParams();
                    let urlStr = hrefUrl.split('?');
                    params.isreload = vo.account;
                    if (params.isreload) {
                        hrefUrl = urlStr[0] + '?';
                        for (let key in params) {
                            hrefUrl = `${hrefUrl}${key}=${params[key]}&`;
                        }
                    }
                    else {
                        hrefUrl = hrefUrl + '?isreload=' + vo.account;
                    }
                }
                window.location.replace(hrefUrl);
            }
            else {
                location.reload();
            }
        }
    }
    sdk.SdkLoginDalan = SdkLoginDalan;
})(sdk || (sdk = {}));

