var mvc;
(function (mvc) {
    class UnitRedotIcon extends Laya.Sprite {
        constructor() {
            super();
            this.mouseEnabled = false;
        }
        onAwake() {
            super.onAwake();
            this._id = 0;
            this._isEvent = false;
        }
        set dataSource(v) {
            this.id = v;
        }
        get dataSource() {
            return this._id;
        }
        onEnable() {
            if (!this._isEvent && this._id > 0) {
                this._onEvent();
            }
            let num = mgr.redotMgr.getNum(this._id);
            this.visible = Boolean(num > 0);
        }
        onDisable() {
            if (this._id > 0 && this._isEvent) {
                this._offEvent();
            }
        }
        set id(v) {
            if (this._id > 0 && this._isEvent) {
                this._offEvent();
            }
            this._id = v;
            if (!v || v <= 0)
                return;
            this._onEvent();
            let num = mgr.redotMgr.getNum(v);
            this.visible = Boolean(num > 0);
        }
        get id() {
            return this._id;
        }
        onChange(id, num) {
            if (id == this._id) {
                this.visible = Boolean(num > 0);
            }
        }
        _onEvent() {
            mgr.redotMgr.on(mvc.RedotConst.EVT.REDOT_CHANGE + "_" + this._id, this, this.onChange);
            this._isEvent = true;
        }
        _offEvent() {
            mgr.redotMgr.off(mvc.RedotConst.EVT.REDOT_CHANGE + "_" + this._id, this, this.onChange);
            this._isEvent = false;
        }
    }
    mvc.UnitRedotIcon = UnitRedotIcon;
})(mvc || (mvc = {}));

var mvc;
(function (mvc) {
    class RedotCtrl extends sg.CtrlBase {
        initCtrl() {
            this.commRedMap = new Map();
        }
        registerMsg() {
            this.onMsg(Proto.RED_DOT_ALL, this._resAllRedot);
            this.onMsg(Proto.RED_DOT_ONE, this._resOneRedot);
        }
        reqAllRedot() {
            let req = this.createProto(Proto.red_dot_all_request);
            this.sendMsg(Proto.RED_DOT_ALL, req);
        }
        getCheckRed(id, index = -1) {
            let red = this.commRedMap.get(id);
            if (red) {
                if (red.param_list && red.param_list.length > 0) {
                    if (red.param_list[index]) {
                        return 1;
                    }
                    else {
                        return 0;
                    }
                }
                else {
                    return red.state;
                }
            }
            return 0;
        }
        changeCheckRed(id, stage, index = -1) {
            let red = this.commRedMap.get(id);
            if (red) {
                if (red.param_list && red.param_list.length > 0) {
                    if (red.param_list[index]) {
                        red.param_list[index] = stage;
                    }
                }
                else {
                    red.state = stage;
                }
                mgr.redotMgr.check(id);
            }
        }
        _resAllRedot(pb) {
            let list = pb.red_dot_list;
            for (let dot of list) {
                this.commRedMap.set(dot.id, dot);
                mgr.redotMgr.check(dot.id);
            }
        }
        _resOneRedot(pb) {
            let dot = pb.red_dot;
            this.commRedMap.set(dot.id, dot);
            mgr.redotMgr.check(dot.id);
        }
    }
    mvc.RedotCtrl = RedotCtrl;
})(mvc || (mvc = {}));

