var mvc;
(function (mvc) {
    class LayerUIMaskSys extends ui.view.common.layer_uiMaskUI {
        onAwake() {
            super.onAwake();
            this._uiChgTime = 0;
            this._needUpdateMaskTex = false;
            this._isEnableEffect = false;
            this._isEnableEffect = sg.UIMgr.USE_FULLSCREEN;
            if (this._isEnableEffect) {
                Laya.stage.on(Laya.Event.RESIZE, this, this._updateEffectPos);
                this.enableEffect();
                this._updateEffectPos();
            }
            this._initMask();
            sg.uimgr.on(mvc.UIMGR_EVT.MASK_UI_SYS, this, this._onMaskUIChged);
        }
        onEnable() {
            super.onEnable();
            this.imgBg.bottom = 0;
        }
        onDestroy() {
            super.onDestroy();
            sg.uimgr.off(mvc.UIMGR_EVT.MASK_UI_SYS, this, this._onMaskUIChged);
        }
        customRender(context, x, y) {
            if (!this._needUpdateMaskTex)
                return;
            this._needUpdateMaskTex = false;
            let cmd = Laya.SubmitCMD.create([], this._updateTex, this);
            context._addSubmit(cmd);
            context.breakNextMerge();
        }
        enableEffect() {
            this._isEnableEffect = true;
            this._sprBlurScreen = new Laya.Sprite();
            this._sprBlurScreen.size(Laya.stage.width, Laya.stage.height);
            this._imgBlur = new Laya.Image();
            this.addChildAt(this._imgBlur, 0);
            this._rt2dImg = new Laya.RenderTexture2D(Laya.stage.width, Laya.stage.height);
            this._texImg = new Laya.Texture(this._rt2dImg);
            this._imgBlur.source = this._texImg;
            this._tex2dPrintScreen = new Laya.Texture2D();
            this._texPrintScreen = new Laya.Texture(this._tex2dPrintScreen);
            this._sprBlurScreen.texture = this._texPrintScreen;
            let blur = new Laya.BlurFilter(4);
            this._sprBlurScreen.filters = [blur];
            if (this.maskBox) {
                this.maskBox.bgColor = mvc.MASK_COLOR_WITH_EFFECT;
                this.maskBox.alpha = mvc.MASK_ALPHA_WITH_EFFECT;
            }
            this.customRenderEnable = true;
        }
        disableEffect() {
            this.customRenderEnable = false;
            this._isEnableEffect = false;
            if (this._sprBlurScreen) {
                this._sprBlurScreen.destroy();
                this._sprBlurScreen = null;
                this._texPrintScreen.destroy(true);
                this._tex2dPrintScreen = null;
                this._texPrintScreen = null;
            }
            if (this._imgBlur) {
                this._texImg.destroy(true);
                this._imgBlur.destroy();
                this._rt2dImg = null;
                this._texImg = null;
                this._imgBlur = null;
            }
            if (this.maskBox) {
                this.maskBox.bgColor = mvc.MASK_COLOR;
                this.maskBox.alpha = mvc.MASK_ALPHA;
            }
        }
        _updateEffectPos() {
            if (!this._imgBlur)
                return;
            let pos = Laya.Point.TEMP;
            pos.setTo(0, 0);
            this.globalToLocal(pos);
            this._sprBlurScreen.size(Laya.stage.width, Laya.stage.height);
            this._rt2dImg.destroy();
            this._rt2dImg = new Laya.RenderTexture2D(Laya.stage.width, Laya.stage.height);
            this._texImg.setTo(this._rt2dImg);
            this._imgBlur.x = pos.x;
            this._imgBlur.height = Laya.stage.height;
            this._imgBlur.width = Laya.stage.width;
            this._needUpdateMaskTex = true;
        }
        _updateTex() {
            if (this._tex2dPrintScreen) {
                this._tex2dPrintScreen.loadImageSource(Laya.Render.canvas);
                let x = 0;
                let x2 = 1;
                this._texPrintScreen.setTo(this._tex2dPrintScreen, new Float32Array([x, 1, x2, 1, x2, 0, x, 0]));
                this._sprBlurScreen.repaint();
                this._sprBlurScreen.drawToTexture(Laya.stage.width, Laya.stage.height, 0, 0, this._rt2dImg);
            }
        }
        updateData(type, ...args) {
            if (!this.hasLoaded())
                return;
            switch (type) {
                case "alpha":
                    {
                        let [alpha] = args;
                        this.maskBox.alpha = alpha;
                    }
                    break;
                case "resetCurUI":
                    {
                        this._curUI = null;
                    }
                    break;
                default:
                    break;
            }
        }
        _initMask() {
            let maskBox = this.maskBox;
            this.maskBox.top = 0;
            this.maskBox.bottom = 0;
            this.maskBox.left = 0;
            this.maskBox.right = 0;
            this.maskBox.bgColor = mvc.MASK_COLOR;
            this.maskBox.alpha = 0;
            maskBox.mouseEnabled = true;
            maskBox.mouseThrough = false;
            maskBox.on(Laya.Event.CLICK, this, this._onClickMask);
        }
        _onClickMask() {
            if (this._curUI && this._curUI.onMask) {
                if (!this._curUI.hasLoaded())
                    return;
                if ((sg.time.getTime() - this._uiChgTime) < LayerUIMaskSys.CLICK_DELAY)
                    return;
                this._curUI.onMask();
            }
        }
        _onTopUILoaded() {
            this.maskBox.alpha = mvc.MASK_ALPHA;
        }
        _onMaskUIChged(ui) {
            this._curUI = ui;
            this._uiChgTime = sg.time.getTime();
            if (ui.hasLoaded()) {
                this._onTopUILoaded();
            }
            else {
                ui.once("onAwake", this, this._onTopUILoaded);
            }
            if (this._isEnableEffect) {
                this._needUpdateMaskTex = true;
            }
        }
    }
    LayerUIMaskSys.CLICK_DELAY = 500;
    mvc.LayerUIMaskSys = LayerUIMaskSys;
})(mvc || (mvc = {}));

