(function (mvc) {
    class PermLogView extends ui.view.common.perm_logViewUI {
        initView(...args) {
            this._showAll = true;
            this._tempLogs = [];
            this._isScrollEnd = true;
            this._dragRegion = new Laya.Rectangle(0, 0, 0, Laya.stage.height - this.height);
            this._logCache = { "i": [], "d": [], "w": [], "e": [] };
            this._showLogFlag = { "i": true, "d": true, "w": true, "e": true };
            this._textColor = { "i": "#ffffff", "d": "#0ad7ff", "w": "#ffeb0a", "e": "#ff3b0a" };
        }
        initSendMsg() { }
        initModelEvent() {
        }
        initCtrlEvent() {
            this.chkInfo.on(Laya.Event.CHANGE, this, this._onChkAutoFree, ["i", this.chkInfo]);
            this.chkDebug.on(Laya.Event.CHANGE, this, this._onChkAutoFree, ["d", this.chkDebug]);
            this.chkWarn.on(Laya.Event.CHANGE, this, this._onChkAutoFree, ["w", this.chkWarn]);
            this.chkError.on(Laya.Event.CHANGE, this, this._onChkAutoFree, ["e", this.chkError]);
            this.chkInfo.selected = this._showLogFlag["i"];
            this.chkDebug.selected = this._showLogFlag["d"];
            this.chkWarn.selected = this._showLogFlag["w"];
            this.chkError.selected = this._showLogFlag["e"];
            this.chkCloseLog.on(Laya.Event.CHANGE, this, this._onChkCloseLog);
            this.chkCloseLog.selected = sg.Logger.openLog;
            this.chkScrollEnd.on(Laya.Event.CHANGE, this, this._onChkScrollEnd);
            this.chkScrollEnd.selected = this._isScrollEnd;
            this.btnMinMax.on(Laya.Event.CLICK, this, this._onBtnMinMax);
            this.on(Laya.Event.MOUSE_DOWN, this, this._onMouseDown);
            this.listLog.renderHandler = this.createHandler(this, this._onRenderListLog, null, false);
            this.listLog.vScrollBarSkin = "";
            this.listLog.array = [];
            this.btnClear.on(Laya.Event.CLICK, this, this._onBtnClear);
        }
        updateData(types, ...args) { }
        onAwake() {
            super.onAwake();
            sg.Logger.setLogLisener("i", this._logLisener.bind(this, "i"));
            sg.Logger.setLogLisener("d", this._logLisener.bind(this, "d"));
            sg.Logger.setLogLisener("w", this._logLisener.bind(this, "w"));
            sg.Logger.setLogLisener("e", this._logLisener.bind(this, "e"));
            this.startRefreshLog();
        }
        startRefreshLog() {
            sg.timer.repeats(3000, this, this._refreshLogList, true);
        }
        stopRefreshLog() {
        }
        _logLisener(type, ...args) {
            let arrAll = this._logCache[type];
            let arr = [];
            for (var i = 0; i < args.length; i++) {
                let msg = args[i];
                msg = sg.any2str(msg);
                arr.push(msg);
            }
            arrAll.push({ msg: arr.concat("\t"), time: sg.time.getNow(), type: type });
            if (arrAll.length > 100) {
                arrAll.shift();
            }
        }
        _getLogsByFiler() {
            let all = [];
            let flags = ["i", "d", "w", "e"];
            for (let type of flags) {
                if (!this._showLogFlag[type])
                    continue;
                let arr = this._logCache[type];
                if (!arr)
                    continue;
                all = all.concat(arr);
            }
            all.sort((l, r) => {
                return l["time"] - r["time"];
            });
            return all;
        }
        _onBtnMinMax() {
            let showAll = !this._showAll;
            this._showAll = showAll;
            this.boxCheck.visible = showAll;
            this.listLog.visible = showAll;
            if (showAll) {
                this.startRefreshLog();
            }
            else {
                this.stopRefreshLog();
            }
        }
        _onMouseDown() {
            if (!this._showAll) {
                this.startDrag(this._dragRegion);
            }
        }
        _onChkAutoFree(type, chk) {
            this._showLogFlag[type] = chk.selected;
            this._refreshLogList();
        }
        _refreshLogList() {
            let logs = this._getLogsByFiler();
            this._tempLogs = logs;
            this.listLog.array = logs;
            if (this._isScrollEnd) {
                this.listLog.scrollTo(this._tempLogs.length - 1);
            }
        }
        _onRenderListLog(cell, index) {
            let data = this._tempLogs[index];
            if (!data)
                return;
            let lblText = cell.getChildByName("lblText");
            lblText.text = data["msg"];
            lblText.color = this._textColor[data["type"]];
        }
        _onChkCloseLog() {
            sg.Logger.openLog = this.chkCloseLog.selected;
        }
        _onChkScrollEnd() {
            this._isScrollEnd = this.chkScrollEnd.selected;
        }
        _onBtnClear() {
            let flags = ["i", "d", "w", "e"];
            for (let type of flags) {
                if (!this._showLogFlag[type])
                    continue;
                this._logCache[type] = [];
            }
            this._refreshLogList();
        }
    }
    mvc.PermLogView = PermLogView;
})(mvc || (mvc = {}));

