(function (mvc) {
    class PlatfromOpenViewer extends Laya.Box {
        constructor() {
            super();
            var tex = new Laya.Texture();
            let tex2d = new Laya.Texture2D();
            this.tex2dShare = tex2d;
            tex.bitmap = tex2d;
            this.texture = tex;
            this.tempPos = new Laya.Point();
            this.showMode = 1;
        }
        onEnable() {
            super.onEnable();
            this.on(Laya.Event.CLICK, this, this.onClick);
            this.open();
        }
        onDisable() {
            super.onDisable();
            this.off(Laya.Event.CLICK, this, this.onClick);
            this.close();
        }
        _onLoop() {
            if (this.tex2dShare)
                (this.tex2dShare).loadImageSource(window.sharedCanvas);
        }
        set width(value) {
            super.width = value;
            if (window.sharedCanvas)
                window.sharedCanvas.width = value;
            this.callLater(this._postMsg);
        }
        get width() {
            return super.width;
        }
        set height(value) {
            super.height = value;
            if (window.sharedCanvas)
                window.sharedCanvas.height = value;
            this.callLater(this._postMsg);
        }
        get height() {
            return super.height;
        }
        set x(value) {
            super.x = value;
            this.callLater(this._postMsg);
        }
        get x() {
            return super.x;
        }
        set y(value) {
            super.y = value;
            this.callLater(this._postMsg);
        }
        get y() {
            return super.y;
        }
        get visible() {
            return super.visible;
        }
        set visible(value) {
            super.visible = value;
            if (value) {
                this.open();
            }
            else {
                this.close();
            }
        }
        getSdk() {
            if (mgr.gplatform.isWx()) {
                return window["wx"];
            }
            else if (mgr.gplatform.isQQ()) {
                return window["qq"];
            }
        }
        open() {
            if (!this.getSdk()) {
                return;
            }
            this.showMode = 1;
            this.postMsg({ type: "display", rate: Laya.stage.frameRate });
            if (this.showMode == 1) {
                if (this.getSdk() && window.sharedCanvas)
                    Laya.timer.frameLoop(1, this, this._onLoop);
            }
            else if (this.showMode == 2) {
                this.postMsg({ "sharedTex2d": this.tex2dShare });
            }
        }
        close() {
            if (!this.getSdk()) {
                return;
            }
            this.postMsg({ type: "undisplay" });
            Laya.timer.clear(this, this._onLoop);
        }
        onClick() {
            this.postMsg({ type: "mouse", x: this.mouseX, y: this.mouseY });
        }
        _postMsg() {
            let mat = new Laya.Matrix();
            this.tempPos.x = this.x;
            this.tempPos.y = this.y;
            this.localToGlobal(this.tempPos);
            mat.translate(this.tempPos.x, this.tempPos.y);
            let stage = Laya.stage;
            let canvasT = stage["_canvasTransform"];
            mat.scale(canvasT.getScaleX() * this.globalScaleX * stage.transform.getScaleX(), canvasT.getScaleY() * this.globalScaleY * stage.transform.getScaleY());
            this.postMsg({ type: "changeMatrix", a: mat.a, b: mat.b, c: mat.c, d: mat.d, tx: mat.tx, ty: mat.ty, w: this.width, h: this.height });
        }
        postMsg(msg) {
            if (this.getSdk() && this.getSdk().getOpenDataContext) {
                var openDataContext = this.getSdk().getOpenDataContext();
                openDataContext.postMessage(msg);
            }
        }
    }
    mvc.PlatfromOpenViewer = PlatfromOpenViewer;
})(mvc || (mvc = {}));

