(function (mvc) {
    class PopAccess extends ui.view.common.pop_accessUI {
        initView(itemId, isGetBeast) {
            this.itemId = itemId;
            this._isGetBeast = isGetBeast;
        }
        initSendMsg() { }
        initModelEvent() { }
        initCtrlEvent() {
            this.lblGet.on(Laya.Event.CLICK, this, this.onGet);
            this.list.selectEnable = true;
            this.list.vScrollBarSkin = "";
            this.list.selectHandler = this.createHandler(this, this._onSelect, null, false);
            this.list.renderHandler = this.createHandler(this, this._rederListItem, null, false);
        }
        updateData(types, ...args) { }
        onAwake() {
            super.onAwake();
            this.lblGet.text = sg.translate("点我获取此道具");
            this.lblGet.visible = mgr.gplatform.isDebug;
        }
        onEnable() {
            super.onEnable();
            this.initData();
        }
        initData() {
            let cnf = sg.dbmgr.get("itemGet", this.itemId);
            if (!cnf)
                return;
            let func = cnf.func;
            let arr = [];
            for (let cn of func) {
                if (!mgr.gplatform.isShowRecharge(cn[3])) {
                    continue;
                }
                if (cn[3]) {
                    arr.push({ desc: cn[0], ui: cn[1], layer: cn[2], funId: cn[3] });
                }
                else
                    arr.push({ desc: cn[0], ui: cn[1], layer: cn[2], funId: 0 });
            }
            this.list.array = arr;
            let vo = new mvc.ItemVo();
            vo.id = this.itemId;
            vo.count = 0;
            this.item.initView(vo);
            this.item.setSelect(false);
            let item_cfg = sg.dbmgr.get("vitem", this.itemId);
            if (item_cfg) {
                this.itemName.text = item_cfg.name ? item_cfg.name : item_cfg.show_name;
                this.itemName.color = mgr.toolsMgr.getColor(item_cfg.quality);
                mgr.toolsMgr.setQualityStroke(item_cfg.quality, this.itemName);
            }
        }
        _rederListItem(cell) {
            let data = cell.dataSource;
            let lblCon = cell.getChildByName("lblCon");
            lblCon.text = data.desc;
        }
        _onSelect(index) {
            let cell = this.list.getCell(index);
            let data = cell.dataSource;
            if (data) {
                sg.uimgr.jumpUI(data.ui, { layer: data.layer, funId: data.funId });
            }
            this.closeSelf();
        }
        onGet() {
            let req = sg.netmgr.createProto(Proto.gm_command_request);
            req.msg = `add_item ${this.itemId} ${this.inputNum.text || 1}`;
            sg.netmsg.sendMsg(Proto.GM_COMMAND, req);
        }
    }
    mvc.PopAccess = PopAccess;
})(mvc || (mvc = {}));

