(function (mvc) {
    class PopItemTips02 extends ui.view.common.pop_itemTips02UI {
        initView(id = 0, vo = null) {
            this._id = id;
            this._vo = vo;
        }
        initCtrlEvent() {
            this.listItem.vScrollBarSkin = "";
            this.listItem.renderHandler = this.createHandler(this, this._onListItemRender, null, false);
        }
        onEnable() {
            super.onEnable();
            this._updateView();
        }
        _updateView() {
            if (!this._vo) {
                let cfg = sg.dbmgr.get("vitem", this._id);
                let arr = [];
                if (cfg.mainclass == mvc.BagConst.BagType.Bag_GIFT) {
                    let giftConfig = sg.dbmgr.get("backgroundActive_active10Gift", this._id);
                    if (giftConfig) {
                        arr = giftConfig.award;
                        this.lbName.text = giftConfig.name;
                    }
                }
                this.lblDescStroy.text = cfg.descStroy;
                this.listItem.array = arr.sort(this.sortFunc);
            }
            else {
                this.lbName.text = this._vo.getDbData().name;
                let cfg = sg.dbmgr.get("vitem", this._vo.getDbData().ID);
                this.lblDescStroy.text = cfg.descStroy;
                this.listItem.array = this._vo.surplusItem.sort(this.sortFunc);
            }
        }
        sortFunc(a, b) {
            let cfgA = sg.dbmgr.get("vitem", a[0]);
            let cfgB = sg.dbmgr.get("vitem", b[0]);
            if (cfgA.quality != cfgB.quality) {
                return cfgB.quality - cfgA.quality;
            }
            else if (cfgA.id != cfgB.id) {
                return cfgA.id - cfgB.id;
            }
            else {
                return b[1] - a[1];
            }
        }
        _onListItemRender(cell, index) {
            if (cell.dataSource == null) {
                return;
            }
            cell.initViewCfg(cell.dataSource, true);
        }
    }
    mvc.PopItemTips02 = PopItemTips02;
})(mvc || (mvc = {}));

