            this.parent["localToGlobal"](this._tempPoint);
            let _pos = this._tempPoint;
            let width = Laya.stage.width;
            let height = Laya.stage.height;
            if (_pos.x + this.width > Laya.stage.width)
                _pos.x = width - this.width;
            if (_pos.y + this.height > height)
                _pos.y = height - this.height;
