var mvc;
(function (mvc) {
    let EVT = mvc.PushStoryConst.EVT;
    class PushStoryModel extends sg.ModelBase {
        constructor() {
            super(...arguments);
            this._needPassLevel = 0;
            this._showChapterId = 1;
            this._canGetChapterReward = false;
        }
        initModel() {
        }
        registerEvents() {
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.PUSH_STORY, this.checkRed, this);
        }
        checkRed() {
            return this._canGetChapterReward ? 1 : 0;
        }
        updateInfo(data) {
            this.passId = data.pass_id;
            this.gotIds = data.received;
            this._updateChapterInfo();
            mgr.redotMgr.check(mvc.REDOT_ID.PUSH_STORY);
        }
        passLevel(id) {
            this.passId = id;
            this._updateChapterInfo();
            mgr.redotMgr.check(mvc.REDOT_ID.PUSH_STORY);
            this.fireEvent(EVT.UPDATE_LEVEL);
            mgr.redotMgr.check(mvc.REDOT_ID.SWORD_GAME_BATTLE);
        }
        getReward(data) {
            this.gotIds.push(data.chapter_id);
            sg.uimgr.showUI("pop_getReward", "", data.reward);
            this._updateChapterInfo();
            mgr.redotMgr.check(mvc.REDOT_ID.PUSH_STORY);
            this.fireEvent(EVT.UPDATE_CHAPTER);
        }
        getChapterLastLevel(id) {
            if (!this._chapterLastLevelMap) {
                let map = this._chapterLastLevelMap = {};
                let cfgs = sg.dbmgr.getDB("pushBattle_pushBattle");
                for (let key in cfgs) {
                    let cfg = cfgs[key];
                    if (!map[cfg.chapter] || map[cfg.chapter] < cfg.id) {
                        map[cfg.chapter] = cfg.id;
                    }
                }
            }
            return this._chapterLastLevelMap[id];
        }
        get showChapterId() {
            return this._showChapterId;
        }
        get canGetChapterReward() {
            return this._canGetChapterReward;
        }
        get needPassLevel() {
            return this._needPassLevel;
        }
        _updateChapterInfo() {
            let passId = this.passId;
            let passChapter = 0;
            let cfg = sg.dbmgr.get("pushBattle_pushBattle", passId);
            let nextLevelCfg = sg.dbmgr.get("pushBattle_pushBattle", passId + 1);
            if (cfg) {
                if (!nextLevelCfg || nextLevelCfg.chapter != cfg.chapter) {
                    passChapter = cfg.chapter;
                }
                else {
                    passChapter = cfg.chapter - 1;
                }
            }
            let getChapter = 0;
            let gotIds = this.gotIds;
            for (let i = 1; i <= passChapter; i++) {
                if (gotIds.indexOf(i) == -1) {
                    getChapter = i;
                    break;
                }
            }
            if (getChapter > 0) {
                this._canGetChapterReward = true;
                this._showChapterId = getChapter;
            }
            else {
                this._canGetChapterReward = false;
                this._needPassLevel = 0;
                if (nextLevelCfg) {
                    let lastCfg = nextLevelCfg;
                    let curChapter = this._showChapterId = lastCfg.chapter;
                    while (lastCfg && lastCfg.chapter == curChapter) {
                        this._needPassLevel = lastCfg.id;
                        lastCfg = sg.dbmgr.get("pushBattle_pushBattle", lastCfg.id + 1);
                    }
                }
            }
        }
    }
    mvc.PushStoryModel = PushStoryModel;
})(mvc || (mvc = {}));

