(function (mvc) {
    class ActivityVo extends sg.VoBase {
        constructor() {
            super();
            this.openState = this.cross_type = this._ex_time = this.show_time = this.end_time = this.start_time = this.act_id = 0;
            this.state = mvc.ActivityConst.STATE.NORMAL;
        }
        funcCfg() {
            return sg.dbmgr.get(mvc.ActivityConst.funcOpen, this.id);
        }
        activityCfg() {
            return sg.dbmgr.get(mvc.ActivityConst.activity, this.act_id);
        }
        get id() {
            if (this._id)
                return this._id;
            let cfg = this.activityCfg();
            this._id = cfg ? cfg.iconInfo : 0;
            return this._id;
        }
        set id(funcopenid) {
            this._id = funcopenid;
        }
        get bgPro() {
            return this._bgPro;
        }
        set bgPro(v) {
            this.cross_type = v.cross_type;
            this.show_time = v.show_time;
            this.end_time = v.stop_time;
            this.start_time = v.start_time;
            this._bgPro = v;
            this.setState();
        }
        isbgVo() {
            return this._bgPro != null;
        }
        setPropData(pb) {
            this.act_id = pb.id;
            this.start_time = pb.start_time;
            this.end_time = pb.stop_time;
            this.show_time = pb.show_time;
            this._ex_time = 0;
            this.cross_type = 0;
            this.setState();
        }
        setState() {
            let STATE = mvc.ActivityConst.STATE;
            if (this.state == STATE.PRE)
                return;
            if (this.show_time <= 0) {
                this.state = STATE.NORMAL;
            }
            else {
                this.state = sg.time.getSecondTime() >= this.show_time ? STATE.REWARD : STATE.NORMAL;
            }
        }
        getTime() {
            let time = 0;
            let STATE = mvc.ActivityConst.STATE;
            let ser_time = sg.time.getSecondTime();
            if (this._ex_time > 0)
                return this._ex_time - ser_time;
            switch (this.state) {
                case STATE.NORMAL:
                    time = this.show_time > 0 ? this.show_time - ser_time : this.end_time - ser_time;
                    break;
                case STATE.PRE:
                    time = this.start_time - ser_time;
                    break;
                case STATE.REWARD:
                    time = this.end_time - ser_time;
                    break;
            }
            return time < 0 ? -1 : time;
        }
        set ex_time(time) {
            this._ex_time = time;
        }
        getOpenDay() {
            let offse = (sg.time.getSecondTime() - this.start_time) / 86400;
            return Math.ceil(offse);
        }
    }
    mvc.ActivityVo = ActivityVo;
})(mvc || (mvc = {}));

