(function (mvc) {
    class PopBgActivityEnterTwo extends ui.view.acitvity.pop_bgActivityEnterTwoUI {
        constructor() {
            super(...arguments);
            this._redIds = [mvc.REDOT_ID.BG_ACT_LOTTERY, mvc.REDOT_ID.BG_ACT_STORE, mvc.REDOT_ID.BG_ACT_GIFTS];
            this._funIds = [mvc.FUNC_ID.BG_ACT_DRAW, mvc.FUNC_ID.BG_ACT_STORE, mvc.FUNC_ID.BG_ACT_GIFT];
        }
        initView() {
        }
        initSendMsg() {
        }
        initModelEvent() {
            this.bindModelEvent(mvc.activityModel, mvc.ActivityConst.EVT.END, this.initTabDatas);
        }
        initCtrlEvent() {
            this.redMarketTask.id = mvc.REDOT_ID.BG_ACT_STORE_TASK;
            this.btnMarketTask.on(Laya.Event.CLICK, this, this._onBtnTaskMarket);
        }
        updateData(types, ...args) { }
        onAwake() {
            super.onAwake();
            this.boxKrChargeTips.visible = mgr.gplatform.isIceBird();
            this._tabView = new mvc.TabView([mvc.UnitBgActLottery, mvc.PopBgMarket, mvc.UnitBgActivityGiftTwo], [this.boxContent]);
            this._tabTable = new mvc.TabTable(this.tab, this._tabView, this.tabChange.bind(this));
        }
        onEnable() {
            super.onEnable();
            this._initRedTips();
            this.initTabDatas();
            this.setItemOpen();
            this.tab.selectedIndex = 1;
            this._tabTable.setTabColor();
        }
        onDisable() {
            this._tabTable.onDisable();
            super.onDisable();
        }
        onJumpInit(jumpParams) {
            let tabIdx = jumpParams.layer[0];
            this.tab.selectedIndex = tabIdx;
        }
        _initRedTips() {
            for (let i = 0; i < this.tab.numChildren; i++) {
                let point = this.tab.getChildAt(i).getChildByName("redTips");
                if (point) {
                    point.id = this._redIds[i];
                }
            }
        }
        initTabDatas() {
            let arr = [];
            let last = 0;
            for (let i = 0; i < this._funIds.length; i++) {
                if (mgr.conditionMgr.checkFunc(this._funIds[i], false)) {
                    arr.push(i);
                    last = i;
                }
            }
            if (arr.length == 0) {
                this.closeSelf();
                return;
            }
            this._tabTable.resetPos(arr, true);
            let item = this.tab.getChildAt(last);
            this.imgTail.y = this.tab.y + item.y + item.height / 2 - 5;
            this.btnMarketTask.visible = mgr.conditionMgr.checkFunc(mvc.FUNC_ID.BG_ACT_STORE, false);
        }
        tabChange(index, lastIndex) {
            let data;
            switch (index) {
                case 0:
                    {
                    }
                    break;
                case 2:
                    {
                        data = [mvc.FUNC_ID.BG_ACT_GIFT, mvc.FUNC_ID.BG_ACT_ACCU_FIVE];
                    }
                    break;
                default:
                    {
                    }
                    break;
            }
            this._data = data;
            this._tabView.setViewData(index, data);
            this.updateView();
        }
        setItemOpen() {
        }
        updateView(isFresh = false) {
            if (isFresh) {
                this._tabView.updateViewData(this.tab.selectedIndex, true, this._data);
            }
        }
        _onBtnTaskMarket() {
            if (!mvc.activityModel.openActivityVo.get(mvc.FUNC_ID.BG_ACT_STORE)) {
                sg.uimgr.showNotice(sg.translate("活动已结束"));
                return;
            }
            sg.uimgr.showUI("pop_bgMarketTask");
        }
    }
    mvc.PopBgActivityEnterTwo = PopBgActivityEnterTwo;
})(mvc || (mvc = {}));

