var mvc;
(function (mvc) {
    class PushBattleTaskModel extends sg.ModelBase {
        constructor() {
            super(...arguments);
            this._all = [];
        }
        initModel() {
            this.vo = new mvc.PushBattleTaskVo();
        }
        registerEvents() {
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.PUSH_BATTLE_TASK, this._checkRedTask, this);
        }
        updateInfo(data) {
            this.vo.pass_id = data.pass_id;
            this.vo.task_received = data.task_received;
            this.vo.player_num = data.player_num;
            this.fireEvent(mvc.PushBattleTaskConst.EVT.UPDATE_VIEW);
            mgr.redotMgr.check(mvc.REDOT_ID.PUSH_BATTLE_TASK);
        }
        receive(data) {
            let cfg = sg.dbmgr.get("sevenActive_pushBattleTask", data.task_id);
            let str = sg.translate("闯关有礼\n");
            sg.uimgr.showUI("pop_getReward", str, cfg.reward, false, "", Laya.Handler.create(this, this._getReward));
            this.vo.task_received.push(data.task_id);
            this.fireEvent(mvc.PushBattleTaskConst.EVT.UPDATE_VIEW);
            mgr.redotMgr.check(mvc.REDOT_ID.PUSH_BATTLE_TASK);
        }
        _getReward(data) {
            if (data) {
                this._all = [];
                for (let i of data) {
                    this._all.push(i);
                }
            }
            if (this._all.length) {
                mvc.pushBattleTaskCtrl.reqReceive(this._all.shift());
            }
        }
        updataVo(id) {
            if (!mvc.activityModel.openActivityVo.has(mvc.FUNC_ID.PUSH_BATTLE_TASK)) {
                return 0;
            }
            this.vo.pass_id = id;
        }
        _checkRedTask() {
            if (!mvc.activityModel.openActivityVo.has(mvc.FUNC_ID.PUSH_BATTLE_TASK)) {
                return 0;
            }
            let arr = sg.dbmgr.getDB("sevenActive_pushBattleTask");
            if (this.vo.task_received.length == 0) {
                if (this.vo.pass_id >= arr[1].need) {
                    return 1;
                }
            }
            else {
                let num = Math.max(...this.vo.task_received) + 1;
                if (!arr[num]) {
                    return 0;
                }
                if (this.vo.pass_id >= arr[num].need) {
                    return 1;
                }
            }
            return 0;
        }
    }
    mvc.PushBattleTaskModel = PushBattleTaskModel;
})(mvc || (mvc = {}));

var mvc;
(function (mvc) {
    class PopPushBattleTask extends ui.view.pushBattleTask.pop_pushBattleTaskUI {
        initView() {
            this._model = mvc.pushBattleTaskModel;
        }
        initSendMsg() {
            mvc.pushBattleTaskCtrl.reqPushInfo();
        }
        initModelEvent() {
            this.bindModelEvent(this._model, mvc.PushBattleTaskConst.EVT.UPDATE_VIEW, this._updateView);
        }
        initCtrlEvent() {
            this.list.vScrollBarSkin = null;
            this.list.itemRender = mvc.UnitTaskItem;
            this.list.renderHandler = this.createHandler(this, this._onRenderList, null, false);
            this.on(Laya.Event.CLICK, this, this._onClick);
        }
        onEnable() {
            super.onEnable();
            this._endTime = 0;
            this._initTime();
            this._updateView();
            this._updateTime();
        }
        onDisable() {
            super.onDisable();
            this.stopTimer(this._onTimer);
        }
        _updateView() {
            this._vo = this._model.vo;
            this._cfg = [];
            this._reward = [];
            let arr = sg.dbmgr.getDB("sevenActive_pushBattleTask");
            for (let i in arr) {
                this._cfg.push(arr[i]);
            }
            this._rwdGet(this._cfg);
            this._cfg = this._sort(this._cfg);
            this.list.array = this._cfg;
            this.list.scrollTo(0);
            if (!this._model.vo.pass_id) {
                this.lblText.text = StringEx.format(sg.translate("当前您已到达：冒险1-0"));
            }
            else {
                let v1 = sg.dbmgr.get("pushBattle_pushBattle", this._model.vo.pass_id).name;
                this.lblText.text = StringEx.format(sg.translate("当前您已到达：${v1}"), {"v1":v1});
            }
            this.butRwd.visible = this.butRwd.gray = true;
            this.butRwd.mouseEnabled = false;
            if (this._reward.length) {
                this.butRwd.gray = false;
                this.butRwd.mouseEnabled = true;
            }
        }
        _sort(arr) {
            arr.reverse();
            let arr1 = [];
            let arr2 = [];
            let arr3 = [];
            for (let i = 0; i < arr.length; i++) {
                if (this._includes(this._vo.task_received, arr[i].id)) {
                    arr3.push(arr[i]);
                }
                else if (this._vo.pass_id >= arr[i].need) {
                    arr1.push(arr[i]);
                }
                else {
                    arr2.push(arr[i]);
                }
            }
            return arr1.concat(arr2, arr3);
        }
        _includes(arr, id) {
            let flg = false;
            for (let i in arr) {
                if (arr[i] == id) {
                    flg = true;
                }
            }
            return flg;
        }
        _rwdGet(arr) {
            for (let i = 0; i < arr.length; i++) {
                if (this._includes(this._vo.task_received, arr[i].id)) {
                }
                else if (this._vo.pass_id >= arr[i].need) {
                    this._reward.push(arr[i].id);
                }
                else {
                }
            }
        }
        _onRenderList(cell, index) {
            if (!cell.dataSource)
                return;
            cell.setData(cell.dataSource);
        }
        _initTime() {
            let actVo = mvc.activityModel.openActivityVo.get(mvc.FUNC_ID.PUSH_BATTLE_TASK);
            if (!actVo) {
                return;
            }
            this._endTime = actVo.end_time;
        }
        _updateTime() {
            this.repeats(1000, this._onTimer, true);
        }
        _onTimer() {
            let time = this._endTime - sg.time.getSecondTime();
            if (time <= 0) {
                this.stopTimer(this._onTimer);
                time = 0;
                sg.uimgr.closeUI("pop_pushBattleTask");
            }
            let v1 = sg.time.formatTimeStrT("F10", time);
            this.lblTime.text = StringEx.format(sg.translate("活动时间：${v1}后结束"), {"v1":v1});
        }
        _onClick(e) {
            switch (e.target) {
                case this.butRwd:
                    {
                        if (this._reward.length > 0) {
                            mvc.pushBattleTaskModel._getReward(this._reward);
                        }
                        else {
                            return;
                        }
                    }
                    break;
            }
        }
    }
    mvc.PopPushBattleTask = PopPushBattleTask;
})(mvc || (mvc = {}));

