                    if (msg && msg.length > 0) {
                        if (msg[1] == self._lastInfo[1]) {
                            self._cards.push([msg[0], msg[1]]);
                            self._cards.push([self._lastInfo[0], self._lastInfo[1]]);
                            self._flipPosArr.length = 0;
                        }
                        else {
                            self.after(500, () => {
                                self._findCard(msg[0] - 1, msg[1], null, 1);
                                self._findCard(self._lastInfo[0] - 1, self._lastInfo[1], null, 1);
                            });
                        }
                    }
                    else if (msg == -1) {
                        self._flipPosArr.length = 0;
                    }
