            this.redTIpsRecord.id = mvc.REDOT_ID.PLANT_RECORD;
            this.redTIpsBeInvite.id = mvc.REDOT_ID.PLANT_BE_INVITE;
            this.redtipsStore.id = mvc.REDOT_ID.PLANT_EXCHANGE;
            this.redTipsDIsturb.id = mvc.REDOT_ID.PLANT_DISTURB_COUNT;
