(function (mvc) {
    class UnitRFComboBox extends mvc.UnitComboBox {
        constructor() {
            super(...arguments);
            this.btnLabel1 = sg.translate("应用");
            this.btnGrayLabel = sg.translate("应用中");
        }
        onEnable() {
            super.onEnable();
        }
        onlistItemMouse(e, index) {
            let type = e.type;
            if (type === Laya.Event.MOUSE_OVER || type === Laya.Event.MOUSE_OUT) {
                let box = this._list.getCell(index);
                if (!box)
                    return;
                let label = box.getChildByName("lbl");
                if (label) {
                    if (type === Laya.Event.ROLL_OVER) {
                        label.bgColor = this._comboBox["_itemColors"][0];
                    }
                    else {
                        label.bgColor = null;
                    }
                }
            }
            else if (type === Laya.Event.CLICK) {
                this._comboBox.selectedIndex = index + 1;
                this.event(mvc.UnitComboBox.SELECT_CHANGE);
                this._comboBox.isOpen = false;
            }
        }
        renderItem(box, index) {
            let label = box.getChildByName("lbl");
            let btn = box.getChildByName("btn");
            let img = box.getChildByName("img");
            label.dataSource = box.dataSource;
            let index1 = index + 1;
            if (btn) {
                btn.gray = this.selectedIndex == index1;
                btn.label = btn.gray ? this.btnGrayLabel : this.btnLabel1;
            }
            img && (img.visible = this.selectedIndex == index1);
        }
        onButtonMouseDown(e) {
            sg.timer.after(50, this, () => {
                this._bgSkin.visible = this._comboBox.isOpen;
                this._bgSkin.height = this._comboBox["_listHeight"];
                this._bgSkin.width = this._bgSkin.width;
                if (this._bgSkin.skin == "" || !this._bgSkin.skin) {
                    let g = this._bgSkin.graphics;
                    g.clear(true);
                    g.drawRect(3, 0, this._comboBox.width - 6, 150, this._comboBox["_itemColors"][4], this._comboBox["_itemColors"][3]);
                }
            });
        }
    }
    UnitRFComboBox.SELECT_CHANGE = "SELECT_CHANGE";
    mvc.UnitRFComboBox = UnitRFComboBox;
})(mvc || (mvc = {}));

