var mvc;
(function (mvc) {
    class RedbagModel extends sg.ModelBase {
        registerEvents() {
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.REDBAG_RECEIVE, this.checkReceiveRed, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.REDBAG_SEND, this.checkSendRed, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.HF_ACTIVITY_REDBAG, this.checkFreeRed, this);
            this.bindEvent(mvc.roleModel, mvc.RoleConst.EVT.LEVEL_UP, this._checkFunData);
            this.bindEvent(mvc.mainModel, mvc.MainConst.EVT.ZERO_UPDATE, this._zeroTimeUpdate);
            this.bindEvent(mvc.bagModel, mvc.BagConst.EVT.ITEM_NUM_CHANGE, this._updateRed);
            this.bindEvent(mvc.bagModel, mvc.BagConst.EVT.UPDATE_BAG_INFO, this._updateRed);
        }
        dealRedbagList(data) {
            if (!this._recRedBag) {
                this._recRedBag = data;
            }
            else {
                let stringID;
                for (let i = 0; i < data.redbag_infos.length; i++) {
                    stringID = data.redbag_infos[i].only_id.toString();
                    for (let j = 0; j < this._recRedBag.redbag_infos.length; j++) {
                        if (stringID == this._recRedBag.redbag_infos[j].only_id.toString()) {
                            this._recRedBag.redbag_infos[j] = data.redbag_infos[i];
                            break;
                        }
                        if (j == this._recRedBag.redbag_infos.length - 1) {
                            this._recRedBag.redbag_infos.unshift(data.redbag_infos[i]);
                            break;
                        }
                    }
                }
                this._recRedBag.buy_info = data.buy_info;
                this._recRedBag.rob_day_infos = data.rob_day_infos;
            }
            this.fireEvent(mvc.RedbagConst.EVT.REDBAG_LIST, this._recRedBag);
            mgr.redotMgr.check(mvc.REDOT_ID.REDBAG_RECEIVE);
        }
        updateRec(data) {
            this._singleInfo = data;
            let recInfo = this._recRedBag;
            recInfo.rob_day_infos = data.rob_day_infos;
            let stringOnlyID = data.redbag_info.only_id.toString();
            for (let i = 0; i < recInfo.redbag_infos.length; i++) {
                if (recInfo.redbag_infos[i].only_id.toString() == stringOnlyID) {
                    this._recRedBag.redbag_infos[i].rob_infos = data.redbag_info.rob_infos;
                    break;
                }
            }
            this.fireEvent(mvc.RedbagConst.EVT.REDBAG_LIST, recInfo);
            this.fireEvent(mvc.RedbagConst.EVT.REDBAG_GET_SINGLE, data, data.flag);
            mgr.redotMgr.check(mvc.REDOT_ID.REDBAG_RECEIVE);
        }
        singleDeal(flag) {
            let data = this._singleInfo;
            sg.uimgr.showUI("pop_opened_Redbag", data.redbag_info.red_bag_type, data.redbag_info.only_id, true, this._singleInfo, flag);
            sg.uimgr.closeUI("pop_openRedbag");
        }
        updateContact(data) {
            let contact = "";
            switch (data.flag) {
                case 1:
                    contact = sg.translate("仙盟");
                    break;
                case 2:
                    contact = sg.translate("世界");
                    break;
                case 6:
                case 7:
                    contact = sg.translate("跨服");
                    break;
            }
            contact = mgr.UIAssist.$(sg.translate("发送到{1}频道"), contact);
            this.fireEvent(mvc.RedbagConst.EVT.CONTACT, contact, data.flag);
        }
        updateSingle(data) {
            let recRedbag = this._recRedBag;
            for (let i = 0; i < recRedbag.redbag_infos.length; i++) {
                if (data.redbag_info.only_id.toString() == recRedbag.redbag_infos[i].only_id.toString()) {
                    recRedbag.redbag_infos[i] = data.redbag_info;
                    break;
                }
                if (i == recRedbag.redbag_infos.length - 1) {
                    recRedbag.redbag_infos.unshift(data.redbag_info);
                    break;
                }
            }
            if (!recRedbag.redbag_infos.length) {
                recRedbag.redbag_infos.unshift(data.redbag_info);
            }
            if (data.sign == 1) {
                this.fireEvent(mvc.RedbagConst.EVT.SINGLE_INFO, data);
            }
            else {
                let flag = this._getState(data.redbag_info);
                let onlyID = data.redbag_info.only_id;
                switch (flag) {
                    case 1:
                        sg.uimgr.showUI("pop_openRedbag", data.redbag_info);
                        break;
                    case 3:
                    case 4:
                    case 2:
                    case 5:
                        let channel = sg.dbmgr.get("redbag_redbagGift", data.redbag_info.sys_id).type;
                        sg.uimgr.showUI("pop_opened_Redbag", channel, onlyID, false, data, flag);
                        break;
                    case 6:
                        sg.uimgr.showNotice(sg.translate("该红包已过期"));
                        break;
                }
            }
        }
        _getState(single) {
            let cfg;
            let channel;
            if (single.sys_id == 0) {
                return 6;
            }
            else {
                cfg = sg.dbmgr.get("redbag_redbagGift", single.sys_id);
                channel = cfg.type;
                let myID = mvc.roleModel.roleInfo.playerId;
                for (let i = 0; i < single.rob_infos.length; i++) {
                    if (single.rob_infos[i].player_id == myID) {
                        return 5;
                    }
                }
                if (channel == mvc.ChatConst.ChannelDefine.GUILD) {
                    let guideTime = mvc.roleModel.roleInfo.guildJoinTime;
                    if (guideTime > single.send_time && !cfg.item) {
                        return 4;
                    }
                    else {
                        if (cfg.number_s) {
                            if (cfg.number == single.rob_infos.length) {
                                return 2;
                            }
                        }
                        else {
                            if (single.receive_num == single.rob_infos.length) {
                                return 2;
                            }
                        }
                    }
                }
                else {
                    if (cfg.number == single.rob_infos.length) {
                        return 2;
                    }
                }
            }
            let maxLimit = mgr.toolsMgr.getGlobalVoById("redbag_max", 1);
            let canReceiveList = {};
            for (let i = 0; i < maxLimit.length; i++) {
                canReceiveList[maxLimit[i][0]] = {};
                canReceiveList[maxLimit[i][0]].num = maxLimit[i][1];
            }
            if (channel != mvc.ChatConst.ChannelDefine.PM) {
                let rob_day_infos = this._recRedBag.rob_day_infos;
                for (let i = 0; i < rob_day_infos.length; i++) {
                    if (rob_day_infos[i][0] == cfg.itemid) {
                        if (rob_day_infos[i][1] > canReceiveList[cfg.itemid].num) {
                            return 3;
                        }
                        break;
                    }
                }
            }
            return 1;
        }
        updateSendPrivateView(data) {
            this.fireEvent(mvc.RedbagConst.EVT.UPDATE_PRIVATE_VIEW, data);
        }
        updateAddRedbag(data) {
            this.pushNewMsg(data.redbag_info);
            let recRedbag = this._recRedBag;
            recRedbag.redbag_infos.unshift(data.redbag_info);
            this.fireEvent(mvc.RedbagConst.EVT.ADD_REDBAG, data);
            mgr.redotMgr.check(mvc.REDOT_ID.REDBAG_RECEIVE);
        }
        pushNewMsg(data) {
            if (!this.newRedbagMsg) {
                this.newRedbagMsg = [];
            }
            if (!this._personalMsg) {
                this._personalMsg = [];
            }
            this.newRedbagMsg.push(data);
            let cfg = sg.dbmgr.get("redbag_redbagGift", data.sys_id);
            if (cfg.type == 5) {
                if (!this.personalOpen) {
                    this.personalOpen = true;
                    sg.uimgr.showUI("pop_openRedbag", data);
                }
                else {
                    this._personalMsg.push(data);
                }
            }
        }
        updateTank(data) {
            let recRedbag = this._recRedBag;
            recRedbag.thank_redbag_ids.push(data.only_id);
        }
        checkPersonal() {
            if (!this.personalOpen) {
                if (this._personalMsg && this._personalMsg.length) {
                    this.personalOpen = true;
                    sg.uimgr.showUI("pop_openRedbag", this._personalMsg.shift());
                }
            }
        }
        changeChatToType(channel) {
            switch (channel) {
                case mvc.ChatConst.ChannelDefine.WORLD:
                    return 2;
                case mvc.ChatConst.ChannelDefine.CROSS:
                    return 1;
                case mvc.ChatConst.ChannelDefine.BITPLANES:
                    return 3;
                case mvc.ChatConst.ChannelDefine.GUILD:
                    return 4;
                case mvc.ChatConst.ChannelDefine.PM:
                    return 5;
                case mvc.ChatConst.ChannelDefine.SPECIAL_BC:
                    return 6;
                case mvc.ChatConst.ChannelDefine.TOP_ARENA_BARRAGE:
                    return 7;
                case mvc.ChatConst.ChannelDefine.SUPER_ARENA_BARRAGE:
                    return 8;
            }
        }
        changeTypeToChat(type) {
            switch (type) {
                case 2:
                    return mvc.ChatConst.ChannelDefine.WORLD;
                case 1:
                    return mvc.ChatConst.ChannelDefine.CROSS;
                case 3:
                    return mvc.ChatConst.ChannelDefine.BITPLANES;
                case 4:
                    return mvc.ChatConst.ChannelDefine.GUILD;
                case 5:
                    return mvc.ChatConst.ChannelDefine.PM;
                case 6:
                    return mvc.ChatConst.ChannelDefine.SPECIAL_BC;
                case 7:
                    return mvc.ChatConst.ChannelDefine.TOP_ARENA_BARRAGE;
                case 8:
                    return mvc.ChatConst.ChannelDefine.SUPER_ARENA_BARRAGE;
            }
        }
        getTitleByType(type) {
            if (!this._title) {
                this._title = ["", sg.translate("跨服"), sg.translate("世界"), sg.translate("位面"), sg.translate("仙盟"), sg.translate("个人"), sg.translate("特殊"), sg.translate("封神台"), sg.translate("成圣殿")];
            }
            return this._title[type];
        }
        getCfgByType(type) {
            if (!this._redbagCfg) {
                this._redbagCfg = sg.dbmgr.getDB("redbag_redbagGift");
            }
            let cfg = [];
            for (let key in this._redbagCfg) {
                if (type == this._redbagCfg[key].type && this._redbagCfg[key].set_id) {
                    cfg.push(this._redbagCfg[key]);
                }
            }
            return cfg;
        }
        changeTab() {
            this.fireEvent(mvc.RedbagConst.EVT.CHANGE_TAB);
        }
        getRedbagByID(onlyID) {
            let recRedbag = this._recRedBag;
            let stringOnlyID = onlyID.toString();
            if (recRedbag) {
                for (let i = 0; i < recRedbag.redbag_infos.length; i++) {
                    if (stringOnlyID == recRedbag.redbag_infos[i].only_id.toString()) {
                        return recRedbag.redbag_infos[i];
                    }
                }
            }
        }
        getRedbagState(onlyID, channel) {
            let recRedbag = this._recRedBag;
            let stringOnlyID = onlyID.toString();
            let tempRedbag;
            let curTime = sg.time.getSecondTime();
            let have = false;
            if (recRedbag) {
                for (let i = 0; i < recRedbag.redbag_infos.length; i++) {
                    tempRedbag = recRedbag.redbag_infos[i];
                    if (tempRedbag.only_id.toString() == stringOnlyID) {
                        have = true;
                        if (tempRedbag.sys_id == 0 || (tempRedbag.end_time != 0 && curTime >= tempRedbag.end_time)) {
                            return 0;
                        }
                        let maxCount;
                        let cfg = sg.dbmgr.get("redbag_redbagGift", tempRedbag.sys_id);
                        if (cfg.type == mvc.ChatConst.ChannelDefine.GUILD && cfg.number_s == 0) {
                            maxCount = tempRedbag.receive_num;
                        }
                        else {
                            maxCount = cfg.number;
                        }
                        if (tempRedbag.rob_infos.length == maxCount) {
                            return 1;
                        }
                        let myID = mvc.roleModel.roleInfo.playerId;
                        for (let j = 0; j < tempRedbag.rob_infos.length; j++) {
                            if (tempRedbag.rob_infos[j].player_id == myID) {
                                return 2;
                            }
                        }
                    }
                }
                if (!have) {
                    if (!this._chatReqList) {
                        this._chatReqList = {};
                    }
                    if (!this._chatReqList[onlyID.toString()]) {
                        this._chatReqList[onlyID.toString()] = true;
                        mvc.redbagCtrl.reqSingleInfo(channel, onlyID, 1);
                        return -2;
                    }
                }
            }
            return -1;
        }
        checkSendRedbagCount(cfg) {
            let cfgGear = sg.dbmgr.get("redbag_redbagGear", cfg.set_id);
            let maxTimes = cfgGear.dayTime;
            let countSetID = 0;
            if (this._recRedBag && this._recRedBag.buy_info) {
                let buyInfo = this._recRedBag.buy_info;
                if (buyInfo.length) {
                    for (let i = 0, len = buyInfo.length; i < len; i++) {
                        if (buyInfo[i][0] == cfg.set_id) {
                            countSetID += buyInfo[i][2];
                        }
                        if (countSetID >= maxTimes) {
                            return false;
                        }
                        if (i == len - 1) {
                            return true;
                        }
                    }
                }
                else {
                    return true;
                }
            }
        }
        getSendRedbagCount(cfg) {
            if (this._recRedBag && this._recRedBag.buy_info) {
                let buyInfo = this._recRedBag.buy_info;
                if (buyInfo.length) {
                    let times = 0;
                    for (let i = 0, len = buyInfo.length; i < len; i++) {
                        if (buyInfo[i][0] == cfg.set_id) {
                            times += buyInfo[i][2];
                        }
                        if (i == len - 1) {
                            return times;
                        }
                    }
                }
                else {
                    return 0;
                }
            }
        }
        checkReceiveRed() {
            let myID = mvc.roleModel.roleInfo.playerId;
            let canReceive;
            let canReceiveList = {};
            let maxLimit = mgr.toolsMgr.getGlobalVoById("redbag_max", 1);
            let guideJoinTime = mvc.roleModel.roleInfo.guildJoinTime;
            for (let i = 0; i < maxLimit.length; i++) {
                canReceiveList[maxLimit[i][0]] = {};
                canReceiveList[maxLimit[i][0]].num = maxLimit[i][1];
                canReceiveList[maxLimit[i][0]].red = true;
            }
            if (this._recRedBag && this._recRedBag.rob_day_infos) {
                let rob_day_infos = this._recRedBag.rob_day_infos;
                for (let i = 0; i < rob_day_infos.length; i++) {
                    if (rob_day_infos[i][1] > canReceiveList[rob_day_infos[i][0]].num) {
                        canReceiveList[rob_day_infos[i][0]].red = false;
                    }
                }
            }
            if (this._recRedBag && this._recRedBag.redbag_infos) {
                let dbmgr = sg.dbmgr;
                let tempInfo;
                let tempCfg;
                for (let i = 0; i < this._recRedBag.redbag_infos.length; i++) {
                    canReceive = false;
                    tempInfo = this._recRedBag.redbag_infos[i];
                    if (tempInfo.sys_id) {
                        tempCfg = dbmgr.get("redbag_redbagGift", tempInfo.sys_id);
                        if (tempCfg.type != mvc.ChatConst.ChannelDefine.PM) {
                            if (!canReceiveList[tempCfg.itemid].red) {
                                continue;
                            }
                            if (tempCfg.type == mvc.ChatConst.ChannelDefine.GUILD) {
                                if (tempCfg.number_s == 0) {
                                    if (tempInfo.rob_infos.length == tempInfo.receive_num) {
                                        continue;
                                    }
                                }
                                else {
                                    if (tempInfo.rob_infos.length == tempCfg.number) {
                                        continue;
                                    }
                                }
                                if (!tempCfg.item) {
                                    if (tempInfo.send_time < guideJoinTime) {
                                        continue;
                                    }
                                }
                            }
                            else {
                                if (tempInfo.rob_infos.length == tempCfg.number) {
                                    continue;
                                }
                            }
                        }
                        canReceive = true;
                        for (let j = 0; j < tempInfo.rob_infos.length; j++) {
                            if (tempInfo.rob_infos[j].player_id == myID) {
                                canReceive = false;
                                break;
                            }
                        }
                        if (canReceive) {
                            break;
                        }
                    }
                }
            }
            this._redReceiveState = canReceive;
            return canReceive ? 1 : 0;
        }
        checkSendRed() {
            this.intiItemFreeList();
            let tempCount = 0;
            for (let key in this._itemIDFree) {
                tempCount = mvc.bagModel.getItemNumById(+key);
                if (tempCount > 0) {
                    if (this._itemIDFree[key].cfg.type == mvc.ChatConst.ChannelDefine.TOP_ARENA_BARRAGE || this._itemIDFree[key].cfg.type == mvc.ChatConst.ChannelDefine.SUPER_ARENA_BARRAGE) {
                        if (mgr.conditionMgr.checkFunc(this._itemIDFree[key].cfg.view, false)) {
                            this._redSendState = true;
                            return 1;
                        }
                    }
                    else {
                        this._redSendState = true;
                        return 1;
                    }
                }
            }
            this._redSendState = false;
            return 0;
        }
        _checkFunData() {
            let openLevel = mgr.toolsMgr.getGlobalVoById("rebag_open", 1);
            let curLevel = mvc.roleModel.roleInfo.level;
            if (curLevel == openLevel || !this._recRedBag) {
                mvc.redbagCtrl.reqRedbagList(true);
            }
        }
        _zeroTimeUpdate() {
            mvc.redbagCtrl.reqRedbagList(true);
        }
        _updateRed() {
            mgr.redotMgr.check(mvc.REDOT_ID.REDBAG_SEND);
            mgr.redotMgr.check(mvc.REDOT_ID.HF_ACTIVITY_REDBAG);
        }
        getISBroadcast() {
            if (this._recRedBag) {
                return this._recRedBag.is_broadcast == 1;
            }
        }
        checkOpen() {
            let openLevel = mgr.toolsMgr.getGlobalVoById("rebag_open", 1);
            let myLevel = mvc.roleModel.roleInfo.level;
            return myLevel >= openLevel;
        }
        checkOpenFreeRedbag1() {
            this.intiItemFreeList();
            let tempCount = 0;
            let sendList = [];
            let tempView;
            for (let key in this._itemIDFree) {
                tempView = this._itemIDFree[key].cfg.view;
                if (tempView != 0) {
                    tempCount = mvc.bagModel.getItemNumById(+key);
                    if (tempCount > 0) {
                        if (this._itemIDFree[key].cfg.type == mvc.ChatConst.ChannelDefine.TOP_ARENA_BARRAGE || this._itemIDFree[key].cfg.type == mvc.ChatConst.ChannelDefine.SUPER_ARENA_BARRAGE) {
                            if (mgr.conditionMgr.checkFunc(tempView, false)) {
                                sendList.push(this._itemIDFree[key]);
                            }
                        }
                        else {
                            sendList.push(this._itemIDFree[key]);
                        }
                    }
                }
            }
            if (sendList.length > 0) {
                sendList.sort(this._sortFunc);
                sg.uimgr.showUI("pop_sendFreeRedbag1", sendList[0].cfg, 0);
            }
        }
        _sortFunc(a, b) {
            if (a.cfg.sort == b.cfg.sort) {
                return a.cfg.id - b.cfg.id;
            }
            else {
                return a.cfg.sort - b.cfg.sort;
            }
        }
        checkOpenFreeRedbagByScene(sceneID) {
            this.intiItemFreeList();
            let tempCount = 0;
            let sendList = [];
            let tempView;
            for (let key in this._itemIDFree) {
                tempView = this._itemIDFree[key].cfg.view;
                if (tempView == sceneID) {
                    tempCount = mvc.bagModel.getItemNumById(+key);
                    if (tempCount > 0) {
                        if (this._itemIDFree[key].cfg.type == mvc.ChatConst.ChannelDefine.TOP_ARENA_BARRAGE || this._itemIDFree[key].cfg.type == mvc.ChatConst.ChannelDefine.SUPER_ARENA_BARRAGE) {
                            if (mgr.conditionMgr.checkFunc(tempView, false)) {
                                sendList.push(this._itemIDFree[key]);
                            }
                        }
                        else {
                            sendList.push(this._itemIDFree[key]);
                        }
                    }
                }
            }
            if (sendList.length > 0) {
                sendList.sort(this._sortFunc);
                sg.uimgr.showUI("pop_sendFreeRedbag1", sendList[0].cfg, sceneID);
            }
        }
        intiItemFreeList() {
            if (!this._itemIDFree) {
                this._itemIDFree = {};
                let cfg = sg.dbmgr.getDB("redbag_redbagGift");
                for (let key in cfg) {
                    if (cfg[key].item && cfg[key].view) {
                        this._itemIDFree[cfg[key].item] = { isFree: true, cfg: cfg[key] };
                    }
                }
            }
        }
        isTankRedbag(onlyId) {
            let tankList = this._recRedBag.thank_redbag_ids;
            let isTank = false;
            let stringOnlyID = onlyId.toString();
            for (let i = 0; i < tankList.length; i++) {
                if (tankList[i].toString() == stringOnlyID) {
                    isTank = true;
                    break;
                }
            }
            return isTank;
        }
        openPersonRedbag() {
            if (!this._nonFirst) {
                this._nonFirst = true;
            }
        }
        getRedState() {
            return this._redReceiveState || this._redSendState;
        }
        dealChatTouch(channel, onlyID, redbagState) {
            switch (redbagState) {
                case 0:
                    sg.uimgr.showNotice(sg.translate("该红包已过期"));
                    break;
                case -2:
                case -1:
                    mvc.redbagCtrl.reqSingleInfo(channel, onlyID, 2);
                    break;
                case 1:
                case 2:
                    sg.uimgr.showUI("pop_opened_Redbag", channel, onlyID, false);
                    break;
            }
        }
        checkFreeRed() {
            if (!this._freeRedbagCfg) {
                this._freeRedbagCfg = {};
                let cfg = sg.dbmgr.getDB("redbag_redbagGift");
                for (let key in cfg) {
                    if (cfg[key].item && !cfg[key].view) {
                        this._freeRedbagCfg[key] = { cfg: cfg[key] };
                    }
                }
            }
            let num = 0;
            for (let key in this._freeRedbagCfg) {
                num = mvc.bagModel.getItemNumById(this._freeRedbagCfg[key].cfg.item);
                if (num > 0) {
                    if (this._freeRedbagCfg[key].cfg.type == mvc.ChatConst.ChannelDefine.TOP_ARENA_BARRAGE || this._freeRedbagCfg[key].cfg.type == mvc.ChatConst.ChannelDefine.SUPER_ARENA_BARRAGE) {
                        if (mgr.conditionMgr.checkFunc(this._freeRedbagCfg[key].view, false)) {
                            return 1;
                        }
                    }
                    else {
                        return 1;
                    }
                }
            }
            return 0;
        }
    }
    mvc.RedbagModel = RedbagModel;
})(mvc || (mvc = {}));

var mvc;
(function (mvc) {
    class PopExchangRedbag extends ui.view.redbag.pop_exchangRedbagUI {
        initView() {
            this._model = mvc.redbagModel;
            this._ctrl = mvc.redbagCtrl;
        }
        initModelEvent() {
            this.bindModelEvent(this._model, mvc.RedbagConst.EVT.UPDATE_LASTLY, this._updateLastList);
            this.bindModelEvent(mvc.guildModel, mvc.GuildConst.EVT.UPDATE_MEMBER_INFO, this._updateGuildList);
        }
        initCtrlEvent() {
            this.listPlayer.vScrollBarSkin = null;
            this.tab.selectHandler = this.createHandler(this, this._onTabTouch, null, false);
            this.listPlayer.renderHandler = this.createHandler(this, this._itemRenderPlayer, null, false);
            this.listPlayer.mouseHandler = this.createHandler(this, this._itemTouchPlayer, null, false);
            this.btnSearch.on(Laya.Event.CLICK, this, this._onBtnSearch);
        }
        onEnable() {
            super.onEnable();
            this.tab.selectedIndex = 0;
            this._onTabTouch();
        }
        _updateLastList(data) {
            let arrMember = [];
            let tempMember;
            let records = data.records;
            for (let i = 0; i < records.length; i++) {
                tempMember = new mvc.RedbagMemberVo();
                tempMember.icon = records[i].head_icon;
                tempMember.name = records[i].name;
                tempMember.playerID = records[i].player_id;
                tempMember.serverID = records[i].svr_id;
                tempMember.sex = records[i].sex;
                tempMember.head_frame_id = records[i].head_frame_id;
                tempMember.level = records[i].level;
                arrMember.push(tempMember);
            }
            this.listPlayer.array = arrMember;
            this.imgNull.visible = arrMember.length == 0;
        }
        _updateGuildList() {
            let list = mvc.guildModel.guildMemberList;
            let arrMember = [];
            let tempMember;
            let serverId = mvc.roleModel.roleInfo.serverId;
            for (let i = 0; i < list.length; i++) {
                tempMember = new mvc.RedbagMemberVo();
                tempMember.icon = list[i].head_icon;
                tempMember.name = list[i].name;
                tempMember.playerID = list[i].player_id;
                tempMember.serverID = serverId;
                tempMember.sex = list[i].sex;
                tempMember.head_frame_id = list[i].head_frame_id;
                tempMember.level = list[i].level;
                arrMember.push(tempMember);
            }
            this.listPlayer.array = arrMember;
        }
        _onTabTouch() {
            if (this.tab.selectedIndex == 0) {
                this.lblLastly.visible = true;
                mvc.redbagCtrl.reqGetLastly();
            }
            else {
                if (mvc.roleModel.roleInfo.guildId > 0) {
                    this.lblLastly.visible = false;
                    this.imgNull.visible = false;
                    mvc.guildCtrl.reqGuildMemberList();
                }
                else {
                    this.tab.selectedIndex == 0;
                    sg.uimgr.showNotice(StringEx.format(sg.translate("请先加入仙盟")));
                }
            }
        }
        _itemRenderPlayer(cell) {
            let dataSource = cell.dataSource;
            cell.getChildByName("lblName").text = dataSource.name;
            cell.getChildByName("lblServer").text = dataSource.serverID ? "s" + dataSource.serverID : "";
            cell.getChildByName("unitHead").initView({
                iconPath: mgr.ComFunMgr.getHeadIcon(dataSource.icon, dataSource.sex),
                headFrameId: dataSource.head_frame_id, level: dataSource.level
            }, dataSource.playerID);
        }
        _itemTouchPlayer(evt, idx) {
            if (evt.type != Laya.Event.CLICK)
                return;
            let data = this.listPlayer.getItem(idx);
            if (!data)
                return;
            sg.uimgr.closeUI("pop_exchangRedbag");
            mvc.redbagModel.updateSendPrivateView(data);
        }
        _onBtnSearch() {
            sg.uimgr.showUI("pop_searchFriend");
        }
    }
    mvc.PopExchangRedbag = PopExchangRedbag;
})(mvc || (mvc = {}));

