(function (mvc) {
    class PopOpenRedbag extends ui.view.redbag.pop_openRedbagUI {
        initView(...args) {
            this._model = mvc.redbagModel;
            this._ctrl = mvc.redbagCtrl;
        }
        onEnable() {
            super.onEnable();
            this.unitEff.visible = false;
            this.unitEff.ani1.on(Laya.Event.COMPLETE, this, this._onComplete);
            let [redbagInfo] = this.openParams;
            this._redbagInfo = redbagInfo;
            let cfg = sg.dbmgr.get("redbag_redbagGift", redbagInfo.sys_id);
            let iconPath = mgr.ComFunMgr.getHeadIcon(this._redbagInfo.head.head_icon, this._redbagInfo.head.sex);
            this.unitHead.initView({ iconPath: iconPath, headFrameId: this._redbagInfo.head.head_frame_id, level: 0 }, this._redbagInfo.head.player_id);
            this.lblName.text = redbagInfo.head.name;
            if (cfg.item && cfg.view) {
                this.lblMsg.text = mgr.UIAssist.$(sg.translate("恭喜{1}获得{2}"), this._redbagInfo.head.name, cfg.name);
            }
            else {
                this.lblMsg.text = redbagInfo.msg;
            }
            this._isSend = false;
            mgr.icon.drawTexture(mgr.icon.getIconPath(cfg.open_type), this.imgBG);
        }
        onMask() {
            if (this._isSend || this._isPlayEff) {
                return;
            }
            super.onMask();
        }
        initModelEvent() {
            this.bindModelEvent(mvc.redbagModel, mvc.RedbagConst.EVT.REDBAG_GET_SINGLE, this._onMsgGetSingle);
        }
        initCtrlEvent() {
            this.on(Laya.Event.CLICK, this, this._onTouch);
        }
        _onMsgGetSingle(data, flag) {
            this._singleGetInfo = data;
            this.flag = flag;
            this.unitEff.visible = true;
            this.unitEff.ani1.play(0, false);
            this._isPlayEff = true;
        }
        _onComplete() {
            mvc.redbagModel.singleDeal(this.flag);
            this._isSend = false;
            this._isPlayEff = false;
        }
        _onTouch() {
            let redbagInfo = this._redbagInfo;
            if (!this._isSend) {
                if (this._checkEndTimeLimit(redbagInfo.end_time)) {
                    this._isSend = true;
                    this._ctrl.reqGetRedbag(redbagInfo.red_bag_type, redbagInfo.only_id, redbagInfo.sys_id);
                }
            }
        }
        _checkEndTimeLimit(endTime) {
            if (endTime == 0) {
                return true;
            }
            let curTime = sg.time.getSecondTime();
            if (curTime > endTime) {
                sg.uimgr.showNotice(sg.translate("该红包已过期"));
            }
            else {
                return true;
            }
        }
        closeSelf() {
            super.closeSelf();
            mvc.redbagModel.personalOpen = false;
            mvc.redbagModel.checkPersonal();
        }
    }
    mvc.PopOpenRedbag = PopOpenRedbag;
})(mvc || (mvc = {}));

