(function (mvc) {
    class PopSendFreeRedbag extends ui.view.redbag.pop_sendFreeRedbagUI {
        getItemCfg() {
            if (!this._itemCfg) {
                this._itemCfg = [];
                let cfg = sg.dbmgr.getDB("redbag_redbagGift");
                for (let key in cfg) {
                    if (cfg[key].item && !cfg[key].view) {
                        this._itemCfg.push(cfg[key]);
                    }
                }
            }
            return this._itemCfg;
        }
        initCtrlEvent() {
            this.listRedbag.vScrollBarSkin = null;
            this.listRedbag.renderHandler = this.createHandler(this, this._itemRender, null, false);
        }
        initModelEvent() {
            this.bindModelEvent(mvc.redbagModel, mvc.RedbagConst.EVT.SUCCESS_SEND, this._successSend);
        }
        onAwake() {
            super.onAwake();
            this.lblTip.text = sg.translate("活动结束清空吉运红包!");
        }
        onEnable() {
            super.onEnable();
            this._initList();
        }
        _initList() {
            let bagModel = mvc.bagModel;
            let num = 0;
            let cfg = this.getItemCfg();
            let vos = [];
            let vo;
            for (let i = 0; i < cfg.length; i++) {
                num = bagModel.getItemNumById(cfg[i].item);
                if (num > 0) {
                    for (let j = 0; j < num; j++) {
                        vo = new mvc.RedbagItemVo();
                        vo.cfg = cfg[i];
                        vos.push(vo);
                    }
                }
            }
            this.listRedbag.array = vos;
            this.imgNull.visible = vos.length == 0;
            this.lblTip.visible = vos.length != 0;
        }
        _itemRender(cell, idx) {
            let data = cell.dataSource;
            let cfg = data.cfg;
            cell.getChildByName("unit_showRedbag").initView(cfg);
            cell.getChildByName("btnSend").on(Laya.Event.CLICK, this, this._onBtnTouch, [data, cell.getChildByName("unit_showRedbag")]);
            cell.getChildByName("lblName").text = cfg.name;
            let text01 = mgr.UIAssist.$(sg.translate("红包数量:{1}"), cfg.number);
            cell.getChildByName("lblCount").text = text01;
            let boxRedNum = cell.getChildByName("boxRedNum");
            let lblTotal = boxRedNum.getChildByName("lblTotal");
            let text0 = sg.translate("红包金额:{1}");
            let text1 = mgr.UIAssist.$(text0, cfg.singe_reward[0]);
            lblTotal.text = text1;
            let imgIcon = boxRedNum.getChildByName("imgIcon");
            mgr.icon.drawTexture(mgr.icon.getIconPath(mgr.toolsMgr.getIconById(cfg.itemid)), imgIcon);
            imgIcon.x = lblTotal.x + lblTotal.width;
        }
        _onBtnTouch(arg, obj) {
            this._sendItem = obj;
            let cfg = arg.cfg;
            let msg = cfg.name;
            mvc.redbagCtrl.sendRedbag(cfg.id, msg, 0, 1);
        }
        _successSend(data) {
            sg.uimgr.showNotice(sg.translate("已成功发送红包"), "green");
            let callback = () => {
                let redbagID = data.sys_id;
                let cfg = sg.dbmgr.get("redbag_redbagGift", redbagID);
                let channel = cfg.type;
                mvc.chatModel.inChannel = channel;
                mvc.redbagModel.sendRedbagEff = true;
                sg.uimgr.showUI("pop_chat");
                this._initList();
            };
            this._sendItem.playEff(callback);
        }
    }
    mvc.PopSendFreeRedbag = PopSendFreeRedbag;
})(mvc || (mvc = {}));

