            this.boxRedbag.on(Laya.Event.MOUSE_DOWN, this, this._onMoustDown);
            this.boxRedbag.on(Laya.Event.MOUSE_MOVE, this, this._onMoustMove);
            this.boxRedbag.on(Laya.Event.MOUSE_UP, this, this._onMoustUp);
            this.btnMius.on(Laya.Event.CLICK, this, this._onBtnMius);
            this.btnAdd.on(Laya.Event.CLICK, this, this._onBtnAdd);
