var mvc;
(function (mvc) {
    class RankVo extends sg.VoBase {
        constructor() {
            super();
            this.init();
        }
        init() {
            this.reqTime = 0;
            this._rankVos = [];
        }
        getRankItemVos(num) {
            if (!num) {
                return this._rankVos;
            }
            return this._rankVos.slice(0, num);
        }
        updateRank(data) {
            this.rankType = data.type;
            this.myRank = data.my_value.idx;
            this.reqTime = data.rank_change_time;
            if (!this.myValue) {
                this.myValue = new mvc.RankItemVo();
            }
            this.myValue.setRankItemVo(data.my_value);
            if (data.is_change) {
                let dataLength = data.data.length;
                if (dataLength) {
                    for (let key in data.data) {
                        let index = parseInt(key);
                        let vo = this._rankVos[index] || new mvc.RankItemVo();
                        vo.setRankItemVo(data.data[key]);
                        if (this._rankVos.length > index) {
                            this._rankVos[index] = vo;
                        }
                        else {
                            this._rankVos.push(vo);
                        }
                    }
                    if (!data.num) {
                        if (this._rankVos.length - dataLength > 0)
                            this._rankVos.splice(dataLength, this._rankVos.length - dataLength);
                    }
                }
                else {
                    this._rankVos = [];
                }
            }
        }
        getSelfVo() {
            if (this.myValue)
                return this.myValue;
            if (this.myRank = 0)
                return null;
            else
                return this._rankVos[this.myRank - 1];
        }
    }
    mvc.RankVo = RankVo;
})(mvc || (mvc = {}));

var mvc;
(function (mvc) {
    let imgRankRes = mvc.RankConst.RankImgRes;
    class RankModel extends sg.ModelBase {
        constructor() {
            super(...arguments);
            this.mConst = mvc.RankConst;
        }
        initModel() {
            this._rankVos = {};
            this.changeReward = [];
            this.isShowSelf = false;
            this._weekShareRed = false;
        }
        registerEvents() {
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.AREA_RANK, this.areaRankRed, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.FRIEND_RANK, this.friendRankRed, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.WEEK_SHARE, this.shareRed, this);
        }
        setRankData(info) {
            let rankVo = this._rankVos[info.type] || new mvc.RankVo();
            this._rankVos[info.type] = rankVo;
            rankVo.updateRank(info);
            window["MyGame"].openLog && console.log("排行榜数据：", info, rankVo);
            this.fireEvent(mvc.RankConst.EVT.UPDATE_RANK_INFO, info.type, rankVo);
        }
        getRankDataMap() {
            let tempArr = [];
            for (let k in this._rankVos) {
                tempArr.push(this._rankVos[k]);
            }
            return tempArr;
        }
        getRankVo(index) {
            return this._rankVos[index];
        }
        getRankItemsVo(type, num) {
            if (this._rankVos[type])
                return this._rankVos[type].getRankItemVos(num);
            else
                return [];
        }
        getLimitRankItemsVo(type, nums) {
            let vos = this.getRankItemsVo(type, nums);
            let num = 3;
            let arrRank = {};
            let delet = [];
            for (let key in vos) {
                let arr = vos[key];
                if (arr.idx < 4) {
                    arrRank[arr.idx] = arr;
                    delet.push(key);
                    num--;
                }
                if (parseInt(key) == 4)
                    break;
            }
            for (let i = delet.length - 1; i >= 0; i--) {
                vos.splice(i, 1);
            }
            if (num > 0) {
                let cfg = sg.dbmgr.get("rank_ranklist", type);
                for (let i = 3; i > 0; i--) {
                    if (!arrRank[i]) {
                        let vo = new mvc.RankItemVo();
                        vo.idx = i;
                        let value = cfg.fCondition ? cfg.fCondition[vo.idx - 1] : 0;
                        vo.setValue(0, value);
                        arrRank[vo.idx] = vo;
                    }
                }
            }
            let arr = [];
            for (let key in arrRank) {
                arr.push(arrRank[key]);
            }
            vos = arr.concat(vos);
            return vos;
        }
        getRankImgRes(data, img) {
            let url;
            switch (data) {
                case 1:
                    url = imgRankRes.RANK_FIRST;
                    break;
                case 2:
                    url = imgRankRes.RANK_SECOND;
                    break;
                case 3:
                    url = imgRankRes.RANK_THIRD;
                    break;
                default:
                    break;
            }
            mgr.icon.drawTexture(url, img);
        }
        getItemByCnfId(id) {
            return sg.dbmgr.get("rank_ranklist", id);
        }
        isCheckReward(type) {
            for (let key in this.changeReward) {
                if (this.changeReward[key][0] == type) {
                    return this.changeReward[key][1] == 0;
                }
            }
            return false;
        }
        areaRankRed() {
            if (!mvc.activityModel.checkFunOpenIdAndAllChild(mvc.FUNC_ID.AREA_RANK, false))
                return 0;
            return this.isCheckReward(mvc.RankConst.RANK_TYPE.area) ? 1 : 0;
        }
        friendRankRed() {
            if (!mvc.activityModel.checkFunOpenIdAndAllChild(mvc.FUNC_ID.FRIEND_OUT_RANK, false))
                return 0;
            return this.isCheckReward(mvc.RankConst.RANK_TYPE.friend_out) ? 1 : 0;
        }
        shareRed() {
            if (mgr.gplatform.isVietnam() || mgr.gplatform.isDalanTW() || mgr.gplatform.isIceBird() || mgr.gplatform.isXmt() || mgr.gplatform.isHonor() || mgr.gplatform.isJLGame() || mgr.gplatform.isDalanSource() || mgr.gplatform.isBaidu())
                return 0;
            return this.weekShareState != 2 ? 1 : 0;
        }
        checkFirend() {
            return mgr.gplatform.isQQ() || mgr.gplatform.isDev();
        }
        checkAreaRank() {
            return !mgr.gplatform.isDalanTW() && !mgr.gplatform.isIceBird() && !mgr.gplatform.isXmt();
        }
        get weekShareState() {
            if (mgr.gplatform.isOpenShareHead(7)) {
                return 2;
            }
            if (this._weekShareRed) {
                return 1;
            }
            else if (this.weeklyInfo) {
                return !this.weeklyInfo.receive_count ? 0 : 2;
            }
        }
        weekShare(view = null, rect = null) {
            if (mgr.gplatform.isCaptureShare()) {
                sg.timer.after(200, null, () => {
                    mgr.gplatform.captureShareSdk(view, rect);
                });
            }
            else {
                mgr.gplatform.shareSdk();
            }
            if (this.weekShareState == 0) {
                sg.timer.after(2000, this, () => {
                    this._weekShareRed = true;
                    mvc.rankModel.fireEvent(mvc.RankConst.EVT.WEEK_SHARE);
                });
            }
        }
        showInfoView(animal, id, x, y, parent) {
            if (!this._unitInfo || this._unitInfo.destroyed) {
                this._unitInfo = new mvc.UnitInfoView();
            }
            this._unitInfo.x = x;
            this._unitInfo.y = y;
            this._unitInfo.updateView(animal, id);
            parent.addChild(this._unitInfo);
        }
    }
    mvc.RankModel = RankModel;
})(mvc || (mvc = {}));

