(function (mvc) {
    class UnitWorldItem extends ui.view.platform.unit_teamUI {
        onAwake() {
            super.onAwake();
            this._isPossese = [];
            this._isPlay = false;
        }
        onEnable() {
            super.onEnable();
        }
        onDisable() {
            super.onDisable();
            this._isPlay = false;
        }
        updateView(data) {
            this._data = data;
            if (this._data == null) {
                mgr.icon.drawTexture("ui_langs/cn/ui/platform/img_wjzb_ad_fddsj.png", this.imgOne);
                this.imgOne.visible = true;
                this.boxData.visible = false;
            }
            else {
                let aCfg = sg.dbmgr.get("province", data.area);
                if (data.idx != 1) {
                    this.lblArea.color = "#ffffff";
                    this.lblArea.strokeColor = "#000000";
                    this.lblArea.stroke = 3;
                }
                this.lblArea.strokeColor.length;
                this.lblArea.text = aCfg ? aCfg.type : sg.translate("未选择");
                this.fcRank.value = data.idx.toString();
                this.imgShow.visible = data.idx <= 3;
                if (data.idx <= 3) {
                    mgr.icon.drawTexture(mgr.UIAssist.$("ui/common/image/img_com_tag_paiming0{1}.png", data.idx), this.imgShow);
                }
                this.lblEggNum.text = data.count.toString();
                this.setShow();
                this.imgOne.visible = false;
                this.boxData.visible = true;
                this.playAni();
            }
        }
        setShow() {
            let i = this.boxShow.numChildren - 1;
            for (; i >= 0; i--) {
                let item = this.boxShow.getChildAt(i);
                item.removeSelf();
                Laya.Pool.recover(mvc.MainConst.POOL_CONST.UNITWORLDAMITEM, item);
            }
            this.initPos();
            let len = this._data.animals.length;
            let arr = new Array(len);
            let arrPos = [];
            let posData = null;
            this._self = null;
            for (let v of this._data.animals) {
                if (v) {
                    posData = this.getPos(85);
                    let un = Laya.Pool.getItemByClass(mvc.MainConst.POOL_CONST.UNITWORLDAMITEM, mvc.UnitAAnimation);
                    un.updateView(v, this._data.area);
                    un.x = posData[0];
                    un.y = posData[1];
                    un.anchorX = 0.5;
                    un.anchorY = 0.5;
                    arr[posData[2]] = un;
                    arrPos.push(posData[3]);
                    if (v.head && v.head.player_id == mvc.roleModel.roleInfo.playerId) {
                        this._self = un;
                    }
                }
            }
            arr.sort((a, b) => {
                return a.y - b.y;
            });
            for (let v of arr) {
                if (v)
                    this.boxShow.addChild(v);
            }
        }
        initPos() {
            this._isPossese.length = 0;
            for (let i = 0; i < this._data.animals.length; i++) {
                this._isPossese.push(i);
            }
        }
        showSelf() {
            if (this._self) {
                this._self.onClick();
            }
        }
        playAni() {
            if (this._isPlay)
                return;
            this._isPlay = true;
            for (let i = 0; i < this.boxShow.numChildren; i++) {
                let item = this.boxShow.getChildAt(i);
                item.scale(0, 0);
                if (i == this.boxShow.numChildren - 1) {
                    this.tweenTo(item, { scaleX: 1, scaleY: 1 }, 500, null, this.createHandler(this, () => {
                        this._isPlay = false;
                    }), i * 20 + 300);
                }
                else {
                    this.tweenTo(item, { scaleX: 1, scaleY: 1 }, 500, null, null, i * 20 + 300);
                }
            }
        }
        getPos(width) {
            let rand = Math.floor(Math.random() * this._isPossese.length);
            let sarr = this._isPossese.splice(rand, 1);
            let data = sarr[0];
            let num = 0;
            let last = 0;
            if (data >= 8) {
                last = last + 7;
                num = 13;
            }
            else {
                num = 8;
            }
            let r = width * num / 6.28;
            let d = 360 / num * (data - last);
            return [Math.cos(d / 180 * 3.14) * r, Math.sin(d / 180 * 3.14) * r, data, data - last];
        }
    }
    mvc.UnitWorldItem = UnitWorldItem;
})(mvc || (mvc = {}));

