var mvc;
(function (mvc) {
    let EVT = mvc.RechargeLimitConst.EVT;
    class RechargeLimitModel extends sg.ModelBase {
        initModel() {
            this.giftList = [];
        }
        registerEvents() {
        }
        getGiftInfo(data) {
            let gift_list = data.gift_list;
            this.giftList = [];
            for (let i = 0; i < gift_list.length; i++) {
                let gift = gift_list[i];
                if (gift.remaining > 0) {
                    this.giftList.push(gift);
                }
            }
            if (this.giftList.length > 0) {
                this.giftList.sort((a, b) => {
                    return a.end_time - b.end_time;
                });
                mvc.activityModel.createAndAddIcon(mvc.FUNC_ID.RECHARGELIMIT);
                this.updateRechargeIcon();
            }
            else {
                mvc.activityModel.removeActivityVo(mvc.FUNC_ID.RECHARGELIMIT, false);
            }
            this.fireEvent(EVT.GIFT_UPDATE);
        }
        getNewGift(data) {
            let idx = this.giftIsHave(data.gift_info.id);
            if (idx >= 0) {
                this.giftList[idx] = data.gift_info;
            }
            else {
                this.giftList.push(data.gift_info);
            }
            this.giftList.sort((a, b) => {
                return a.end_time - b.end_time;
            });
            let index = 0;
            for (let i = 0; i < this.giftList.length; i++) {
                let id = this.giftList[i].id;
                if (id == data.gift_info.id) {
                    index = i;
                    break;
                }
            }
            if (this.giftList.length == 1)
                mvc.activityModel.createAndAddIcon(mvc.FUNC_ID.RECHARGELIMIT);
            this.updateRechargeIcon();
            if (mgr.gplatform.isVietnam() && mgr.gplatform.isVerifyVersion) {
                return;
            }
            if (!mgr.gplatform.isViVeVersion()) {
                this.after(2000, () => {
                    if (mgr.gplatform.isShowRecharge(mvc.FUNC_ID.RECHARGELIMIT)) {
                        sg.uimgr.showUI("pop_rechargeLimite", index);
                    }
                });
            }
        }
        getGiftListByIndex(idx) {
            let arr = [];
            let isEven = idx == 0;
            for (let i = 0; i < this.giftList.length; i++) {
                if (isEven) {
                    if (i % 2 == 0)
                        arr.push(this.giftList[i]);
                }
                else {
                    if (i % 2 != 0)
                        arr.push(this.giftList[i]);
                }
            }
            return arr;
        }
        getGiftIdByIndex(idx) {
            return this.giftList[idx] && this.giftList[idx].id;
        }
        getGiftEndTimeByIndex(idx) {
            return this.giftList[idx] && this.giftList[idx].end_time;
        }
        giftTimeEnd(data) {
            for (let i = 0; i < this.giftList.length; i++) {
                let id = this.giftList[i].id;
                if (id == data.id) {
                    this.giftList.splice(i, 1);
                    break;
                }
            }
            this.updateRechargeIcon();
            this.fireEvent(EVT.GIFT_UPDATE);
        }
        getGiftReward(data) {
            let cfg = sg.dbmgr.get("rechargeLimit_rechargeGift", data.gift_info.id);
            sg.uimgr.showUI("pop_getReward", cfg.name, data.reward);
            for (let i = 0; i < this.giftList.length; i++) {
                let id = this.giftList[i].id;
                if (id == data.gift_info.id) {
                    if (data.gift_info.remaining == 0) {
                        this.giftList.splice(i, 1);
                        this.fireEvent(EVT.GIFT_UPDATE);
                        this.updateRechargeIcon();
                    }
                    else {
                        this.giftList[i].remaining--;
                    }
                    break;
                }
            }
        }
        updateRechargeIcon() {
            if (this.giftList.length == 0) {
                mvc.activityModel.removeActivityVo(mvc.FUNC_ID.RECHARGELIMIT, false);
            }
            else {
                if (mvc.activityModel.tempVos.get(mvc.FUNC_ID.RECHARGELIMIT))
                    mvc.activityModel.tempVos.get(mvc.FUNC_ID.RECHARGELIMIT).end_time = this.giftList[0].end_time;
            }
        }
        giftIsHave(id) {
            let idx = -1;
            for (let i = 0; i < this.giftList.length; i++) {
                let gift = this.giftList[i];
                if (gift.id == id) {
                    idx = i;
                    break;
                }
            }
            return idx;
        }
    }
    mvc.RechargeLimitModel = RechargeLimitModel;
})(mvc || (mvc = {}));

