            let vos = mvc.ItemVo.createItemVos(cfg.reward);
            this.rewardList.array = vos;
            this.rewardList.width = 68 * vos.length + 10 * (vos.length - 1);
            this.tabList1.array = this._model.getGiftListByIndex(0);
            this.tabList2.array = this._model.getGiftListByIndex(1);
            this.tabList1.height = 135 * this.tabList1.array.length - 5 * (this.tabList1.array.length - 1);
            this.tabList2.height = 135 * this.tabList2.array.length - 5 * (this.tabList2.array.length - 1);
            this.imgTail1.y = this.tabList1.y + this.tabList1.height;
            this.imgTail2.y = this.tabList2.y + this.tabList2.height;
            this.imgTail1.visible = this.tabList1.array.length > 0;
            this.imgTail2.visible = this.tabList2.array.length > 0;
            this.lblTitle.text = cfg.name;
            this.lblPrice.text = `${cfg.cheap}` + sg.translate("元");
            this.btnBuy.label = mgr.gplatform.showPriceByGearId(cfg.set_id);
            let time = this._model.getGiftEndTimeByIndex(this._selectIndex) - sg.time.getSecondTime();
            if (time <= 0)
                time = 0;
            let v1 = sg.time.formatTimeStrT("F0", time);
