(function (mvc) {
    class RechargeModel extends sg.ModelBase {
        constructor() {
            super(...arguments);
            this.firstProIds = [];
            this.firstCouponIds = [];
        }
        initModel() {
            this.curIndexByMap = new Map();
        }
        registerEvents() {
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.RECHARGE_VIDEO, this._redVideoRecharge, this);
        }
        getRechargeUIData() {
            return sg.dbmgr.getDB("recharge_recharge", true);
        }
        getRechargeTokenUIData() {
            return sg.dbmgr.getDB("recharge_rechargeCoupon", true);
        }
        isVideoGoods(proId) {
            return proId == mvc.RechargeConst.VIDEO_GEAR_ID;
        }
        isProHasBuyed(idCfg) {
            return this.firstProIds.indexOf(idCfg) != -1;
        }
        isCouponHasBuyed(idCfg) {
            return this.firstCouponIds.indexOf(idCfg) != -1;
        }
        setPhpOrderResult(data) {
            if (data.code == 1) {
                mgr.gplatform.sdkGame.rechargeSdk(data.data);
            }
            else if (data.code == 3) {
            }
            else if (data.code == -13) {
                if (data.msg) {
                    sg.uimgr.showTip(data.msg);
                }
            }
            else {
                window["MyGame"].openLog && mgr.gplatform.log("php order failed:", data);
            }
        }
        setRechargeData(info) {
            this.firstProIds = info.first_ids;
            this.firstCouponIds = info.first_coupon;
            this.videoVo = this.videoVo || new mvc.RechargeVideoVo();
            this.videoVo.update(info);
            let now = sg.time.getTime();
            if (this.videoVo.nextReceiveTime >= now) {
                sg.timer.after(this.videoVo.nextReceiveTime - now, this, this.checkRedot);
            }
            this.checkRedot();
            this.fireEvent(mvc.RechargeConst.EVT.RECHARGE_UPDATE);
        }
        checkRedot() {
            mgr.redotMgr.check(mvc.REDOT_ID.RECHARGE_VIDEO);
        }
        _redVideoRecharge() {
            if (this.videoVo.canReceive)
                return 1;
            return 0;
        }
        getGiftCfgByType(type) {
            if (!this._getCfgByType) {
                this._getCfgByType = new Map();
                let cfgs = sg.dbmgr.getDB("recharge_growthGift");
                for (let key in cfgs) {
                    let cfg = cfgs[key];
                    let arr = this._getCfgByType.get(cfg.type) || [];
                    arr.push(cfg.id);
                    this._getCfgByType.set(cfg.type, arr);
                }
            }
            return this._getCfgByType.get(type);
        }
        getCurSubGiftCfgByType(type) {
            let maxId = this.curIndexByMap.get(type) || 0;
            if (!maxId) {
                let arr = this.getGiftCfgByType(type);
                return sg.dbmgr.get("recharge_growthGift", arr[0]);
            }
            else {
                return sg.dbmgr.get("recharge_growthGift", maxId + 1);
            }
        }
        getCanBuyGiftType() {
            if (!mgr.gplatform.isShowRecharge(0, 7101)) {
                return 0;
            }
            let type = 0;
            this.getGiftCfgByType(1);
            if (this._getCfgByType) {
                this._getCfgByType.forEach((value, key) => {
                    if (type == 0) {
                        let maxId = this.curIndexByMap.get(key) || 0;
                        if (maxId) {
                            let cfg = sg.dbmgr.get("recharge_growthGift", maxId + 1);
                            if (cfg) {
                                type = key;
                            }
                        }
                        else {
                            type = key;
                        }
                    }
                });
            }
            return type;
        }
        getGiftTypesByTab(tab) {
            let arr = [];
            if (this._getCfgByType) {
                this._getCfgByType.forEach((value) => {
                    let cfg = sg.dbmgr.get("recharge_growthGift", value[0]);
                    if (cfg.tab == tab) {
                        arr.push(cfg);
                    }
                });
            }
            return arr;
        }
    }
    mvc.RechargeModel = RechargeModel;
})(mvc || (mvc = {}));

