            mgr.icon.drawTexture(cfg.slogan, this.imgTitle);
            mgr.icon.drawTexture(cfg.giftPhoto, this.imgBg);
            this.rewardList.array = cfg.reward;
            this.rewardList.width = 68 * cfg.reward.length + 10 * (cfg.reward.length - 1);
            this.lblTitle.text = cfg.name;
            this.lblPrice.text = `${cfg.originalPrice}` + sg.translate("元");
            this.btnBuy.label = mgr.gplatform.showPriceByGearId(cfg.set_id);
            let nextCfg = sg.dbmgr.get("recharge_growthGift", cfg.id + 1);
