(function (mvc) {
    class PopChoicePet extends ui.view.pet.pop_choicePetUI {
        constructor() {
            super(...arguments);
            this._type = 1;
            this._isShowArrChange = false;
            this._nowPetVo = null;
        }
        initView(petvo, nextPetvo, type = 1) {
            this._curPetvo = petvo;
            this._nextPetvo = nextPetvo;
            this._type = type;
        }
        updateData(type, petvos) {
            this._curPetvo = petvos[0];
            this._nextPetvo = petvos[1];
            this.updateView();
        }
        initModelEvent() {
            this.bindModelEvent(mvc.petModel, mvc.PetConst.EVT.PET_EGG_SET_CHANGE, this.updateHeightView);
            this.bindModelEvent(mvc.islandModel, mvc.IslandConst.EVT.NEXT_PET, this.nextPetForIsland);
            this.bindModelEvent(mvc.petModel, mvc.PetConst.EVT.AUTO_SELL_PET, this._autoSellPet);
        }
        initCtrlEvent() {
        }
        onAwake() {
            super.onAwake();
            this.listCurProp.renderHandler = Laya.Handler.create(this, this.renderCurList, null, false);
            this.listNextProp.renderHandler = Laya.Handler.create(this, this.renderNextList, null, false);
            this.boxCheck.selected = mvc.petModel.getPetHandle();
            this.boxCheck.on(Laya.Event.CLICK, this, this.onClickSell);
            this.on(Laya.Event.CLICK, this, this._onClick);
        }
        onEnable() {
            super.onEnable();
            this.updateView();
            this._isShowArrChange = false;
            this._nowPetVo = new mvc.PetVo();
        }
        onDisable() {
            super.onDisable();
            if (this._tempVo)
                this._tempVo = null;
            this.listCurProp.array = null;
            this.listNextProp.array = null;
            this._isShowArrChange && mvc.mainCtrl.onArrChange();
            if (this._nowPetVo) {
                mvc.mainCtrl.onPetFly(this._nowPetVo);
            }
            this._isShowArrChange = false;
        }
        nextPetForIsland(petVo, nextPetVo, type) {
            this._curPetvo = petVo;
            this._nextPetvo = nextPetVo;
            this._type = type;
            this.updateView();
        }
        updateView() {
            this.updateCurView();
            this.updatNextView();
            this.updateHeightView();
        }
        updateHeightView() {
            this.btnRelease.label = mvc.petModel.eggInfo.handle_type == Proto.PET_HANDLE.RELEASE ? sg.translate("放生") : sg.translate("出售");
            if (this._type == 2) {
                this.btnRelease.label = mvc.islandModel.hatchVo.handle_type == Proto.PET_HANDLE.RELEASE ? sg.translate("放生") : sg.translate("出售");
            }
            if (!this.boxCur.visible) {
                this.boxBg.y = this.boxNext.y - 18;
                this.boxBg.height = this.boxNext.height + 25;
                this.ButtonClose.y = this.boxBg.y + 6;
            }
            else {
                this.boxBg.y = 0;
                this.ButtonClose.y = 21;
                this.boxBg.height = 800;
            }
        }
        updateCurView() {
            this.boxBtnOne.visible = !this._curPetvo;
            this.boxBtnTwo.visible = !this.boxBtnOne.visible;
            this.boxCheck.visible = false;
            if (this._curPetvo) {
                this.boxCur.visible = true;
                this.boxCheck.visible = this._type != 2 ? true : false;
                this.btnAutoSet.visible = mgr.toolsMgr.getGlobalVoById("egg_recovery_limite", 1) <= mvc.roleModel.roleInfo.level;
                let prop = mvc.PropertyModel.praseProp(this._curPetvo.attr, false);
                this.listCurProp.array = prop.filed;
                mvc.petModel.updatePetProp(this.boxCurPorp, prop.towProp);
                let text = mgr.UIAssist.$("[{1}] {2}", this._curPetvo.getQualityStr(), this._curPetvo.cfg.name);
                this.petCurName.changeText(text);
                this.lblCurDecs.visible = !mvc.petModel.isLockCfg();
                this.lblCurDecs.text = mvc.petModel.getLockStr();
                this.skillCurDecs.visible = !this.lblCurDecs.visible;
                mgr.toolsMgr.setQualityStroke(this._curPetvo.quality, this.petCurName);
                this.petCurName.color = mgr.toolsMgr.getColor(this._curPetvo.quality);
                this.boxCurSkill.visible = false;
                text = this._curPetvo.getLevelName();
                this.petCurLv.changeText(text);
                this.modelCur.changeShowMode(false, this._curPetvo.cfg.model);
                this.modelCur.loadRole(this._curPetvo.cfg.model, "pop_choicePet");
                this.clipCur.index = this._curPetvo.quality - 1;
                text = mvc.petModel.getRaceName(this._curPetvo.type);
                this.lblCurPetType.changeText(text);
                if (this._curPetvo.cfg.skill) {
                    this.boxCurSkill.visible = true;
                    let skillcfg = sg.dbmgr.get("skill_skill", mvc.SkillVo.getSkillId(this._curPetvo.cfg.skill, 1));
                    text = mgr.UIAssist.$("{1}{2}", sg.translate("天赋技能："), skillcfg.name);
                    this.skillCurName.changeText(text);
                    this.skillCurDecs.text = skillcfg.desc;
                }
            }
            else {
                this.btnAutoSet.visible = this.boxCur.visible = false;
            }
        }
        updatNextView() {
            let prop = mvc.PropertyModel.praseProp(this._nextPetvo.attr, true);
            this.listNextProp.array = prop.filed;
            mvc.petModel.updatePetProp(this.boxNextPorp, prop.towProp);
            let text = mgr.UIAssist.$("[{1}] {2}", this._nextPetvo.getQualityStr(), this._nextPetvo.cfg.name);
            this.petNextName.changeText(text);
            mgr.toolsMgr.setQualityStroke(this._nextPetvo.quality, this.petNextName);
            this.boxNextSkill.visible = false;
            this.petNextName.color = mgr.toolsMgr.getColor(this._nextPetvo.quality);
            text = this._nextPetvo.getLevelName();
            this.petNextLv.changeText(text);
            this.modelNext.changeShowMode(false, this._nextPetvo.cfg.model);
            this.modelNext.loadRole(this._nextPetvo.cfg.model, "pop_choicePet");
            this.clipNext.index = this._nextPetvo.quality - 1;
            this.lblNextDecs.visible = !mvc.petModel.isLockCfg();
            this.lblNextDecs.text = mvc.petModel.getLockStr();
            this.skillNextDecs.visible = !this.lblNextDecs.visible;
            text = mvc.petModel.getRaceName(this._nextPetvo.type);
            this.lblNextPetType.changeText(text);
            let url = this._tempVo && this._tempVo.isEqual(this._nextPetvo) ? "ui_langs/cn/ui/pet/img_font_pet_dcl.png" : "ui_langs/cn/ui/pet/img_pet_xhys.png";
            mgr.icon.drawTexture(url, this.imgNext);
            if (this._nextPetvo.cfg.skill) {
                this.boxNextSkill.visible = true;
                let skillcfg = sg.dbmgr.get("skill_skill", mvc.SkillVo.getSkillId(this._nextPetvo.cfg.skill, 1));
                text = mgr.UIAssist.$("{1}{2}", sg.translate("天赋技能："), skillcfg.name);
                this.skillNextName.changeText(text);
                this.skillNextDecs.text = skillcfg.desc;
            }
        }
        renderCurList(item, index) {
            mvc.petModel.renderList(item);
        }
        renderNextList(item, index) {
            let cur = this.listCurProp.array;
            let curArr = cur && cur[index] ? cur[index] : [0, 0];
            mvc.petModel.renderList(item, curArr[1] < item.dataSource[1], curArr[1] > item.dataSource[1]);
        }
        _onClick(event) {
            let target = event.target;
            switch (target.name) {
                case "btnConquer":
                    {
                        if (this._nextPetvo) {
                            this._nowPetVo.cloneProtoData(this._nextPetvo);
                            this._isShowArrChange = true;
                            if (this._type == 2) {
                                mvc.islandCtrl.reqIslandPetMake(Proto.PET_HANDLE.EQUIP);
                                if (this._curPetvo) {
                                    if (!this._tempVo)
                                        this._tempVo = new mvc.PetVo();
                                    this._tempVo.quality = this._curPetvo.quality;
                                    this._tempVo.level = this._curPetvo.level;
                                    this._tempVo.id = this._curPetvo.id;
                                    this._tempVo.type = this._curPetvo.type;
                                }
                                this.updateView();
                            }
                            else {
                                mvc.petCtrl.reqPetHandling(Proto.PET_HANDLE.EQUIP, this._nextPetvo.id);
                                if (this._curPetvo) {
                                    if (!this._tempVo)
                                        this._tempVo = new mvc.PetVo();
                                    this._tempVo.quality = this._curPetvo.quality;
                                    this._tempVo.level = this._curPetvo.level;
                                    this._tempVo.id = this._curPetvo.id;
                                    this._tempVo.type = this._curPetvo.type;
                                }
                                if (!this._curPetvo) {
                                    this.closeSelf();
                                }
                            }
                        }
                    }
                    break;
                case "btnRelease":
                    {
                        let fun = () => {
                            if (this._nextPetvo) {
                                if (this._type == 2)
                                    mvc.islandCtrl.reqIslandPetMake(mvc.islandModel.hatchVo.handle_type);
                                else {
                                    mvc.petCtrl.reqPetHandling(mvc.petModel.eggInfo.handle_type, this._nextPetvo.id);
                                    this.closeSelf();
                                }
                            }
                        };
                        if (this._nextPetvo.cfg.type == mvc.PetConst.PET_SOURCE.Recharge) {
                            sg.uimgr.showConfirm({
                                enterFunc: fun, content: sg.translate("这只异兽十分强大，确定出售吗？"), btnCancelVisible: true
                            });
                        }
                        else {
                            if (mvc.petModel.showTip && mvc.petModel.comparPet(this._nextPetvo, mvc.petModel.getCurPetByType(this._nextPetvo.type))) {
                                sg.uimgr.showConfirm({
                                    content: sg.translate("出售的异兽生命、攻击、防御、速度都不低于当前异兽，是否确定出售？"), enterFunc: fun, btnCancelVisible: true, sacrificeTipVisible: true,
                                    sacrificeTipFunc: () => {
                                        mvc.petModel.showTip = false;
                                    }
                                });
                            }
                            else {
                                fun();
                            }
                        }
                    }
                    break;
                case "btnAutoSet":
                    sg.uimgr.showUI("pop_choicePetTip", this._type);
                    break;
            }
        }
        onClickSell() {
            mvc.petModel.setPetHandle(this.boxCheck.selected);
        }
        _autoSellPet() {
            let pet = null;
            if (mvc.petModel.getPetHandle()) {
                let id = this._tempVo ? this._tempVo.id : 0;
                for (let key in mvc.petModel.eggInfo.hatch_pet) {
                    let p = mvc.petModel.eggInfo.hatch_pet[key];
                    if (p && p.id == id) {
                        pet = p;
                    }
                }
            }
            if (pet) {
                this._tempVo.cloneProtoData(pet);
                let fun = () => {
                    mvc.petCtrl.reqPetHandling(mvc.petModel.eggInfo.handle_type, pet.id);
                    this.closeSelf();
                };
                if (this._tempVo.cfg.type == mvc.PetConst.PET_SOURCE.Recharge) {
                    sg.uimgr.showConfirm({
                        enterFunc: fun, content: sg.translate("这只异兽十分强大，确定出售吗？"), btnCancelVisible: true
                    });
                }
                else {
                    if (mvc.petModel.showTip && mvc.petModel.comparPet(this._tempVo, mvc.petModel.getCurPetByType(this._tempVo.type))) {
                        sg.uimgr.showConfirm({
                            content: sg.translate("出售的异兽生命、攻击、防御、速度都不低于当前异兽，是否确定出售？"), enterFunc: fun, btnCancelVisible: true, sacrificeTipVisible: true,
                            sacrificeTipFunc: () => {
                                mvc.petModel.showTip = false;
                            }
                        });
                    }
                    else {
                        fun();
                    }
                }
            }
        }
    }
    mvc.PopChoicePet = PopChoicePet;
})(mvc || (mvc = {}));

