(function (mvc) {
    class PopChoicePetTip extends ui.view.pet.pop_choiceTipsUI {
        constructor() {
            super(...arguments);
            this._type = 1;
        }
        initView(type = 1) {
            this._type = type;
        }
        onAwake() {
            super.onAwake();
            this.checkSell.on(Laya.Event.CLICK, this, this._onClickSellCheckBox);
            this.checkRelease.on(Laya.Event.CLICK, this, this._onClickCheckBox);
        }
        onEnable() {
            super.onEnable();
            this.checkRelease.selected = mvc.petModel.eggInfo.handle_type == Proto.PET_HANDLE.RELEASE;
            this.checkSell.selected = !this.checkRelease.selected;
        }
        onDisable() {
            super.onDisable();
            if (this._type == 1) {
                mvc.petModel.eggInfo.handle_type = this.checkSell.selected ? Proto.PET_HANDLE.SELL : Proto.PET_HANDLE.RELEASE;
                let info = mvc.petModel.eggInfo;
                mvc.petModel.setAutoEggCfg(info.handle_type, info.quality_limit, info.attr_limit, info.full_stop ? true : false, info.hatch_multiple);
                mvc.petModel.fireEvent(mvc.PetConst.EVT.PET_EGG_SET_CHANGE);
            }
            else {
                mvc.islandModel.hatchVo.handle_type = this.checkSell.selected ? Proto.PET_HANDLE.SELL : Proto.PET_HANDLE.RELEASE;
            }
        }
        _onClickSellCheckBox() {
            this.checkRelease.selected = !this.checkSell.selected;
        }
        _onClickCheckBox() {
            this.checkSell.selected = !this.checkRelease.selected;
        }
    }
    mvc.PopChoicePetTip = PopChoicePetTip;
})(mvc || (mvc = {}));

var mvc;
(function (mvc) {
    class PopEggAutoSet extends ui.view.pet.pop_eggAutoSetUI {
        initView() {
        }
        onAwake() {
            super.onAwake();
            this.btnEnter.on(Laya.Event.CLICK, this, this._onBtnEnter);
            this.comHatchNum.on(Laya.Event.CHANGE, this, this._onSelectHatchNum);
        }
        onEnable() {
            super.onEnable();
            this.updateView();
        }
        updateView() {
            let vo = mvc.petModel.eggInfo;
            let strs = this.getThreeProp();
            let lblVos = this.getQualityStr();
            this.unitBox.updateView(lblVos.str, lblVos.arr);
            this.comDealWith.labels = sg.translate("出售,放生");
            let type = Proto.PET_HANDLE;
            this.comTwoKeyOneCon.list.vScrollBarSkin = null;
            this.comOnekeyTwoCon.list.vScrollBarSkin = this.comOnekeyOneCon.list.vScrollBarSkin = this.comTwoKeyTwoCon.list.vScrollBarSkin = null;
            this.comDealWith.disabled = mgr.toolsMgr.getGlobalVoById("egg_recovery_limite", 1) > mvc.roleModel.roleInfo.level;
            if (type.RELEASE == vo.handle_type) {
                this.comDealWith.selectedIndex = 1;
            }
            else {
                this.comDealWith.selectedIndex = 0;
            }
            this.comTwoKeyOneCon.labels = this.comOnekeyOneCon.labels = strs[0];
            this.comTwoKeyTwoCon.labels = this.comOnekeyTwoCon.labels = strs[1];
            this.boxNegationKey.selected = vo.attr_limit[4] == 1;
            this.boxChallengeKey.selected = vo.full_stop == 1;
            this.unitBox.selectedIndex = vo.quality_limit;
            let fun = (index, box) => {
                let cfg = sg.dbmgr.get("attribute", vo.attr_limit[index]);
                if (cfg) {
                    box.selectedLabel = cfg.show_name;
                }
                else {
                    box.selectedIndex = 0;
                }
            };
            fun(0, this.comOnekeyOneCon);
            fun(1, this.comOnekeyTwoCon);
            fun(2, this.comTwoKeyOneCon);
            fun(3, this.comTwoKeyTwoCon);
            this.comHatchNum.labels = this.getEggLevelStr();
            this.comHatchNum.selectedIndex = mvc.petModel.eggInfo.hatch_multiple - 1;
        }
        getQualityStr() {
            let cfgs = sg.dbmgr.getDB("pet_qualityBonus");
            let str = sg.translate("无");
            let one = 0;
            let arr = [];
            for (let key in cfgs) {
                str = str + "," + cfgs[key].type;
                let color = mgr.toolsMgr.getColor(cfgs[key].quality);
                let strokeColor = mgr.toolsMgr.getStrokeColor(cfgs[key].quality);
                if (one == 0) {
                    one = 1;
                    arr.push({ color, strokeColor, stroke: 3, text: sg.translate("无") });
                }
                arr.push({ color, strokeColor, stroke: 3, text: cfgs[key].type });
            }
            return { str, arr };
        }
        getEggLevelStr() {
            let cfgs = sg.dbmgr.getDB("pet_eggMultiple");
            let str;
            for (let key in cfgs) {
                if (str) {
                    str = str + "," + cfgs[key].id + sg.translate("倍孵蛋");
                }
                else {
                    str = cfgs[key].id + sg.translate("倍孵蛋");
                }
            }
            return str;
        }
        getThreeProp() {
            this.propMap = { towProp: [], threeProp: [] };
            let strs = [sg.translate("无"), sg.translate("无")];
            let cfgs = sg.dbmgr.getDB("attribute");
            for (let key in cfgs) {
                let num = cfgs[key].egg_show;
                if (num == 1) {
                    this.propMap.towProp.push(cfgs[key]);
                    strs[0] = strs[0] + "," + cfgs[key].show_name;
                }
                else if (num == 2) {
                    this.propMap.threeProp.push(cfgs[key]);
                    strs[1] = strs[1] + "," + cfgs[key].show_name;
                }
            }
            return strs;
        }
        _onBtnEnter() {
            let arr = [];
            let fun = (box, isTwo = 1) => {
                let cfgArr = isTwo == 1 ? this.propMap.towProp : this.propMap.threeProp;
                let index = box.selectedIndex;
                let cfg = index == 0 ? null : cfgArr[index - 1];
                if (cfg) {
                    arr.push(cfg.id);
                }
                else {
                    arr.push(0);
                }
            };
            fun(this.comOnekeyOneCon);
            fun(this.comOnekeyTwoCon, 0);
            fun(this.comTwoKeyOneCon);
            fun(this.comTwoKeyTwoCon, 0);
            arr.push(this.boxNegationKey.selected ? 1 : 0);
            let handle = this.comDealWith.selectedIndex == 1 ? Proto.PET_HANDLE.RELEASE : 0;
            mvc.petModel.setAutoEggCfg(handle, this.unitBox.selectedIndex, arr, this.boxChallengeKey.selected, this.comHatchNum.selectedIndex + 1);
            this.closeSelf();
            if (mvc.petModel.checkCanAutoHatch(true)) {
                mvc.petModel.autoHatch = mvc.PetConst.PET_HATCH_ST.hatch;
                if (mvc.petModel.eggInfo.hatch_pet.length > 0) {
                    mvc.petModel.hacthComplate(false);
                }
                else {
                    mvc.petCtrl.reqPetEggHatch(mvc.petModel.curGetHatchCom());
                }
            }
            else {
                mvc.petModel.autoHatch = mvc.PetConst.PET_HATCH_ST.idle;
            }
        }
        _onSelectHatchNum() {
            let num = this.comHatchNum.selectedIndex;
            if (mvc.petModel.eggInfo.hatch_multiple != num + 1) {
                let cfg = sg.dbmgr.get("pet_eggMultiple", num + 1);
                if (!cfg || !mgr.conditionMgr.check(cfg.eggLevel, true)) {
                    this.comHatchNum.selectedIndex = mvc.petModel.eggInfo.hatch_multiple - 1;
                }
            }
        }
    }
    mvc.PopEggAutoSet = PopEggAutoSet;
})(mvc || (mvc = {}));

