(function (mvc) {
    class PopOpenActiveTask extends ui.view.openActive.pop_taskUI {
        initView(...args) {
            this._model = mvc.openActiveTaskModel;
            let cfg = sg.dbmgr.getDB("openActive_pointsReward", true);
            this._boxMaxPoint = cfg[cfg.length - 1].point;
        }
        initModelEvent() {
            this.bindModelEvent(this._model, mvc.OpenActiveTaskConst.EVT.UPDATE_VIEW, this._updateView);
            this.bindModelEvent(this._model, mvc.OpenActiveTaskConst.EVT.UPDATE_BOX, this._updateBox);
            this.bindModelEvent(this._model, mvc.OpenActiveTaskConst.EVT.UPDATE_TASK, this._updateTask);
        }
        initCtrlEvent() {
            this.taskList.vScrollBarSkin = "";
            this.taskList.renderHandler = this.createHandler(this, this._onTaskList, null, false);
            this.boxList.renderHandler = this.createHandler(this, this._onBoxList, null, false);
            this.tab.selectHandler = this.createHandler(this, this._onTabSelect, null, false);
        }
        updateWhenNetReConn() {
            this._updateView();
        }
        onEnable() {
            super.onEnable();
            this._selectIndex = 0;
            this._updateView();
            this._updateTime();
        }
        onDisable() {
            super.onDisable();
            this.stopTimer(this._onTimer);
        }
        _updateTime() {
            this.repeats(1000, this._onTimer, true);
        }
        _onTimer() {
            let activity = mvc.activityModel.openActivityVo.get(mvc.FUNC_ID.OPEN_ACTIVE);
            if (activity) {
                let time = activity.end_time - sg.time.getSecondTime();
                let v1 = sg.time.formatTimeStrT("F9", time);
                this.lblTime.text = StringEx.format(sg.translate("活动时间：${v1}后结束"), {"v1":v1});
            }
        }
        _onTaskList(cell, idx) {
            let data = cell.dataSource;
            if (!data)
                return;
            cell.initView(data);
        }
        _onBoxList(cell, idx) {
            let data = cell.dataSource;
            if (!data)
                return;
            let clipLight = cell.getChildByName("clipLight");
            let clipBox = cell.getChildByName("clipBox");
            let lblIntegral = cell.getChildByName("lblIntegral");
            let boxRedot = cell.getChildByName("boxRedot");
            let proIntegral = cell.getChildByName("proIntegral");
            boxRedot.visible = false;
            clipLight.visible = false;
            clipBox.index = 1;
            clipBox.offAll(Laya.Event.CLICK);
            let point = data.point;
            let curPoint = Math.min(this._model.vo.integral, this._boxMaxPoint);
            let lastPoint = data.lastPoint;
            let canGet = false;
            lblIntegral.text = point + "";
            if (curPoint >= point) {
                proIntegral.value = 1;
                if (this._model.vo.reward.indexOf(data.id) == -1) {
                    boxRedot.visible = true;
                    clipLight.visible = true;
                    canGet = true;
                }
                else {
                    clipBox.index = 0;
                }
            }
            else {
                proIntegral.value = curPoint <= lastPoint ? 0 : (curPoint - lastPoint) / (point - lastPoint);
            }
            clipBox.on(Laya.Event.CLICK, this, this._onBoxClick, [data, canGet]);
        }
        _onTabSelect(idx) {
            if (idx + 1 > this._model.vo.day) {
                this.tab.selectedIndex = this._selectIndex;
                sg.uimgr.showNotice(sg.translate("请等待至对应天数"));
                return;
            }
            this._selectIndex = idx;
            let cfg = sg.dbmgr.getArray("openActive_activeTask", { day: this._selectIndex + 1 });
            this._model.vo.sortTaskList(cfg);
            this.taskList.array = cfg;
        }
        _updateView() {
            this._updateTask();
            this._updateBox();
            this._updateTab();
        }
        _updateBox() {
            this.lblAllIntergral.value = this._model.vo.integral + "";
            this.boxList.array = this._model.vo.boxList;
        }
        _updateTask() {
            let cfg = sg.dbmgr.getArray("openActive_activeTask", { day: this._selectIndex + 1 });
            this._model.vo.sortTaskList(cfg);
            this.taskList.array = cfg;
            for (let i = 0; i < this._model.vo.day; i++) {
                let redot = this.tab.getChildAt(i).getChildByName("redot");
                redot.visible = this._model.vo.todayHaveReward(i + 1);
            }
        }
        _updateTab() {
            for (let i = 0, len = this.tab.numChildren; i < len; i++) {
                let lock = this.tab.getChildAt(i).getChildByName("lock");
                lock.visible = i + 1 > this._model.vo.day;
            }
        }
        _onBoxClick(data, canGet) {
            if (this._model.isPassAct) {
                sg.uimgr.showNotice(sg.translate("活动已结束"));
                return;
            }
            if (canGet) {
                mvc.openActiveTaskCtrl.reqTaskReward(data.id);
            }
            else {
                sg.uimgr.showUI("pop_guildRewardPre", data.reward, sg.translate("仙路历练"));
            }
        }
    }
    mvc.PopOpenActiveTask = PopOpenActiveTask;
})(mvc || (mvc = {}));

