(function (mvc) {
    class OpenActiveGiftVo extends sg.VoBase {
        updateData(data) {
            if (!data)
                return;
            this._setBuyInfo(data.bought);
            this.giftList = sg.dbmgr.getDB("openActive_activeGift", true);
            this.updateRewardState();
        }
        _setBuyInfo(data) {
            this.buyInfo = {};
            for (let i = 0, len = data.length; i < len; i++) {
                this.buyInfo[data[i][0]] = data[i][1];
            }
        }
        updateRewardState() {
            for (let i = 0, len = this.giftList.length; i < len; i++) {
                let gift = this.giftList[i];
                if (gift.gold == 0 && this.getBuyNumById(gift.id) < gift.timeLimit) {
                    this.haveReward = true;
                    return;
                }
            }
            this.haveReward = false;
        }
        getBuyNumById(id) {
            return this.buyInfo[id] ? this.buyInfo[id] : 0;
        }
        getRewardInfo(data) {
            this._setBuyInfo(data.bought);
            this.updateRewardState();
        }
        sortList() {
            if (this.giftList) {
                this.giftList.sort((a, b) => {
                    let canBuyA = this.getBuyNumById(a.id) < a.timeLimit || a.timeLimit == 0;
                    let canBuyB = this.getBuyNumById(b.id) < b.timeLimit || b.timeLimit == 0;
                    if ((canBuyA && canBuyB) || (!canBuyA && !canBuyB)) {
                        return a.id - b.id;
                    }
                    else {
                        return canBuyA ? -1 : 1;
                    }
                });
            }
        }
    }
    mvc.OpenActiveGiftVo = OpenActiveGiftVo;
})(mvc || (mvc = {}));

