            let secStr = date.getSeconds().toString();
            monthStr = monthStr[1] ? monthStr : '0' + monthStr[0];
            dayStr = dayStr[1] ? dayStr : '0' + dayStr[0];
            hourStr = hourStr[1] ? hourStr : '0' + hourStr[0];
