                let hour = Math.floor(((lastTime - day * (24 * 60 * 60)) / (60 * 60)));
                let minute = Math.floor(((lastTime - day * (24 * 60 * 60)) - hour * (60 * 60)) / 60);
                let sec = Math.floor((((lastTime - day * (24 * 60 * 60)) - hour * (60 * 60)) - minute * 60));
