        _itemSelect(index) {
            this.getGameBoard(this.listTitle.selectedItem);
        }
        _itemRender(box, index) {
            let data = box.dataSource;
            let btn = box.getChildAt(0);
            let img = box.getChildAt(1);
            btn.label = data.title;
            btn.selected = index == this.listTitle.selectedIndex;
            img.visible = Date.now() - data.time * 1000 < 86400000;
        }
