                            let day = date.getDate();
                            day = day < 10 ? "0" + day : day;
                            let hours = date.getHours();
                            hours = hours < 10 ? "0" + hours : hours;
                            let minutes = date.getMinutes();
                            minutes = minutes < 10 ? "0" + minutes : minutes;
                            let str = StringEx.format(sg.translate("Server sẽ mở vào lúc ${hours}:${minutes} ngày ${day}-${month}-${year},<br>xin hãy đón chờ!"), {"hours":hours,"minutes":minutes,"day":day,"month":month,"year":year});
