var mvc;
(function (mvc) {
    class MailModel extends sg.ModelBase {
        initModel() {
            this.vos = [];
        }
        registerEvents() {
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.MAIL, this._checkRed, this);
        }
        updateInfo(data) {
            this.vos.length = 0;
            for (let m of data.mails) {
                let vo = new mvc.MailVo();
                vo.updateData(m);
                this.vos.push(vo);
            }
            mgr.redotMgr.check(mvc.REDOT_ID.MAIL);
        }
        _checkRed() {
            if (!this.vos)
                return 0;
            for (let vo of this.vos) {
                if (!vo.isRead)
                    return 1;
            }
            return 0;
        }
        getMailReward(ids) {
            let rewardMap = {};
            for (let id of ids) {
                for (let vo of this.vos) {
                    if (vo.id == id) {
                        vo.isGet = true;
                        vo.isRead = true;
                        if (vo.haveItems) {
                            for (let r of vo.items) {
                                if (rewardMap[r[0]]) {
                                    rewardMap[r[0]] += r[1];
                                }
                                else {
                                    rewardMap[r[0]] = r[1];
                                }
                            }
                        }
                        break;
                    }
                }
            }
            this.fireEvent(mvc.MailConst.EVT.UPDATE_MAIL);
            let arr = [];
            for (let key in rewardMap) {
                arr.push([Number(key), rewardMap[key]]);
            }
            sg.uimgr.showUI("pop_getReward", "", arr);
            mgr.redotMgr.check(mvc.REDOT_ID.MAIL);
        }
        readMail(id) {
            for (let vo of this.vos) {
                if (vo.id == id) {
                    vo.isRead = true;
                    break;
                }
            }
            this.fireEvent(mvc.MailConst.EVT.UPDATE_MAIL);
            mgr.redotMgr.check(mvc.REDOT_ID.MAIL);
        }
        newMail(data) {
            let vo = new mvc.MailVo();
            vo.updateData(data);
            this.vos.push(vo);
            this.fireEvent(mvc.MailConst.EVT.UPDATE_LIST);
            mgr.redotMgr.check(mvc.REDOT_ID.MAIL);
        }
        deleteMail(ids) {
            for (let id of ids) {
                for (let i = 0; i < this.vos.length; i++) {
                    if (this.vos[i].id == id) {
                        this.vos.splice(i, 1);
                        break;
                    }
                }
            }
            this.fireEvent(mvc.MailConst.EVT.UPDATE_LIST);
            mgr.redotMgr.check(mvc.REDOT_ID.MAIL);
        }
        mailContentParse(text, params) {
            let out = text.replace(/\{([0-9]):\s*(\w+)\}/g, (...args) => {
                let idx = (args[1]) - 1;
                let data = params[idx];
                switch (args[2]) {
                    case "int":
                    case "string":
                        {
                            if (!data || data.length == 0) {
                                console.error(text, params);
                                return "error";
                            }
                            return data[0];
                        }
                    case "name":
                        return mvc.mainModel.configNameParse(data);
                    case "configName":
                    case "itemName":
                        return mvc.mainModel.configNameParse(data);
                    case "playerName":
                        return data[0];
                    default:
                        return "error";
                }
            });
            return out;
        }
        showMailNotice() {
            if (this.state == 1 || this.state == 4)
                sg.uimgr.showNotice(sg.translate("一键删除信件成功"), "green");
            else if (this.state == 2 || this.state == 0)
                sg.uimgr.showNotice(sg.translate("当前无信件可以删除"), "green");
            else if (this.state == 3)
                sg.uimgr.showNotice(sg.translate("还有尚未领取的奖励"), "green");
            this.state = 0;
        }
        setMailState() {
            if (this.vos.length == 0) {
                this.state = 0;
                return;
            }
            let isAllRead = true;
            let isAllNotRead = true;
            let readMailHaveReward = false;
            for (let vo of this.vos) {
                if (vo.isRead) {
                    isAllNotRead = false;
                    if (vo.items.length > 0 && !vo.isGet) {
                        readMailHaveReward = true;
                    }
                }
                else {
                    isAllRead = false;
                }
            }
            if (isAllRead) {
                this.state = 1;
                if (readMailHaveReward)
                    this.state = 3;
            }
            else if (isAllNotRead)
                this.state = 2;
            else {
                if (readMailHaveReward)
                    this.state = 3;
                else
                    this.state = 4;
            }
        }
    }
    mvc.MailModel = MailModel;
})(mvc || (mvc = {}));

