(function (mvc) {
    class SysMail extends ui.view.email.sys_emailUI {
        initView() {
            this._model = mvc.mailModel;
            this._ctrl = mvc.mailCtrl;
        }
        initSendMsg() {
        }
        initModelEvent() {
            this.bindModelEvent(this._model, mvc.MailConst.EVT.UPDATE_LIST, this._updateView);
            this.bindModelEvent(this._model, mvc.MailConst.EVT.UPDATE_MAIL, this._updateView);
        }
        initCtrlEvent() {
            this.btnGet.on(Laya.Event.CLICK, this, this._onBtnGet);
            this.btnDel.on(Laya.Event.CLICK, this, this._onBtnDel);
            this.list.showAniType = 2;
            this.list.vScrollBarSkin = "";
        }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            this._updateView();
        }
        onDisable() {
            super.onDisable();
        }
        _updateView() {
            this._model.vos.sort((a, b) => {
                if (a.isRead != b.isRead) {
                    return a.isRead ? 1 : -1;
                }
                if (a.haveItems != b.haveItems) {
                    return a.haveItems ? -1 : 1;
                }
                if (a.isGet != b.isGet) {
                    return a.isGet ? 1 : -1;
                }
                return b.sendTime - a.sendTime;
            });
            this.list.array = this._model.vos;
            this.lblNum.text = this.list.length + "/100";
        }
        _onBtnGet() {
            for (let vo of this._model.vos) {
                if (vo.haveItems && !vo.isGet) {
                    this._ctrl.reqOneKeyGetMailItems();
                    return;
                }
            }
            sg.uimgr.showNotice(sg.translate("没有可领取的道具"));
        }
        _onBtnDel() {
            this._model.setMailState();
            this._ctrl.reqOneKeyDelete();
        }
    }
    mvc.SysMail = SysMail;
})(mvc || (mvc = {}));

