(function (mvc) {
    class PopIslandRoom extends ui.view.island.pop_islandRoomUI {
        constructor() {
            super(...arguments);
            this.masterId = 0;
        }
        initView(id) {
            this.masterId = id;
        }
        initSendMsg() {
        }
        initModelEvent() {
            this.bindModelEvent(mvc.islandModel, mvc.IslandConst.EVT.UPDATE_ROOM, this._updateView);
            this.bindModelEvent(mvc.islandModel, mvc.IslandConst.EVT.JOIN, this._joinRoom);
            this.bindModelEvent(mvc.islandModel, mvc.IslandConst.EVT.CLOSE_ROOM, this._closeRoom);
            this.bindModelEvent(mvc.islandModel, mvc.IslandConst.EVT.SHARE, this._sendInviteAll);
            this.bindModelEvent(mvc.islandModel, mvc.IslandConst.EVT.SHOW_ASSECC_ANI, this._showAsseccAni);
        }
        initCtrlEvent() {
            this.on(Laya.Event.CLICK, this, this._onClick);
            this.listRole.itemRender = mvc.UnitIslandRoleItem;
        }
        updateData(types, ...args) { }
        onAwake() {
            super.onAwake();
            this._point = new Laya.Point();
            this._poss = new Laya.Point();
            this.redTips.id = mvc.REDOT_ID.ISLAND_PET;
            this.btnLog.text = sg.translate("秘境记录");
        }
        onEnable() {
            super.onEnable();
            this.imgBuffTips.mouseEnabled = true;
            this.unit.visible = false;
            if (this._spine)
                this._spine.visible = false;
            this._updateView();
            mvc.islandCtrl.reqIslandRoomEnter(this.masterId);
        }
        onJumpInit(jumpParams) {
        }
        onDisable() {
            this.masterId = 0;
            mvc.islandCtrl.reqIslandRoomExit();
            super.onDisable();
        }
        onClosed() {
            mvc.islandCtrl.reqIslandRoomExit();
            super.onClosed();
        }
        _closeRoom(id) {
            if (this.masterId > 0 && id == this.masterId) {
                this.closeSelf();
            }
        }
        _joinRoom(pos) {
            if (mvc.islandModel.vo && mvc.islandModel.vo.guide == 0) {
                this.unit.visible = true;
                this.unit.ani1.play(0, true);
            }
            else
                this.unit.visible = false;
            if (mvc.islandModel.vo.guide == 0)
                mvc.islandCtrl.reqIslandGuide();
            let cell = this.listRole.getCell(pos - 1);
            if (cell) {
                if (!this._spine) {
                    this._spine = sg.SpineSprite.create("9038", true, false, false, "stand");
                    this.addChild(this._spine);
                }
                else {
                    this._spine.play("stand", false);
                }
                this._spine.visible = true;
                this._poss.setTo(cell.width / 2, cell.height / 2);
                cell.localToGlobal(this._poss, false, this);
                this._spine.x = this._poss.x;
                this._spine.y = this._poss.y;
            }
        }
        _updateView() {
            this.btnShare.visible = this.btnExit.visible = this.boxState.visible = false;
            let vo = mvc.islandModel.getRoomVo(this.masterId);
            if (vo) {
                this.vo = vo;
                let pVo = vo.getPlayerVo(this.masterId);
                if (pVo) {
                    this.lblMasterName.text = `[s${pVo.head.svr_id}]${pVo.head.name}`;
                    let cfg = sg.dbmgr.get("fashion_title", pVo.titileId);
                    if (cfg) {
                        this.title.updateTitle(pVo.titileId);
                        let effic = mgr.toolsMgr.getGlobalVoById("island_owner_efficiency", 1);
                        let v1 = cfg.baseNum;
                        let v2 = effic[0];
                        let v3 = Math.floor(cfg.efficiency / 10000 * 100);
                        let v4 = Math.floor(effic[1] / 10000 * 100);
                        this.lblEff.text = sg.translate("孵蛋效率:") + StringEx.format(sg.translate("${v1}个/每分钟(主人额外+${v2})"), {"v1":v1,"v2":v2});
                        this.lblAsse.text = sg.translate("货币获得加成:") + StringEx.format(sg.translate("${v3}%(主人额外+${v4}%)"), {"v3":v3,"v4":v4});
                    }
                    this.boxState.visible = mvc.islandModel.isShowStop(this.masterId);
                    this._updatePlayerModel(this.unitMaster, pVo.head);
                }
                let islandVo = mvc.islandModel.vo;
                if (this.masterId > 0 && vo && this.masterId == islandVo.roomId) {
                    if (mvc.roleModel.roleInfo.playerId == this.masterId) {
                        this.btnShare.visible = true;
                    }
                    else {
                        this.btnExit.visible = true;
                    }
                }
                let dataArr = [];
                let idx = 1;
                let max = mgr.toolsMgr.getGlobalVoById("island_room_member_limit", 1);
                while (idx <= max) {
                    dataArr.push({ vo: vo, pos: idx });
                    idx++;
                }
                this.listRole.array = dataArr;
                this.repeats(1000, this._onOffseTime, true);
                let eggMax = mgr.toolsMgr.getGlobalVoById("island_save_pet_mun", 1);
                this.lblPetNum.text = islandVo.petNum + "/" + eggMax;
                let aniStr = mvc.islandModel.isShowStop(this.masterId) ? "stand2" : "stand";
                let spine = this.eggSp.getChildByName("item");
                let spineId = mvc.shellModel.getPoolEggSkin(this.vo.egg_fashion_Id);
                if (!spine) {
                    spine = sg.SpineSprite.create(spineId, true, true, true, aniStr);
                    spine.name = "item";
                    this.eggSp.addChild(spine);
                }
                else {
                    spine.loadSpine(spineId);
                    spine.play(aniStr, true);
                }
                this.spEff.changeShowMode(false, 9047);
                this.spEff.loadedHandle = () => {
                    this.spEff.play("stand", true);
                };
                this.spEff.loadRole(9047, "PopIslandRoom");
                this.spEff.visible = true;
                this.imgBuffTips.visible = this.masterId == mvc.islandModel.vo.roomId;
                this._showTips();
            }
        }
        _updatePlayerModel(model, info) {
            let skinCfg = sg.dbmgr.get("fashion_fashion", info.skin_id);
            let role = skinCfg.avatar[info.sex];
            let artifact = 0;
            model.updateView(role, 0, artifact, 0);
        }
        _onOffseTime() {
            if (this.vo) {
                let targetTime = this.vo.close_time;
                let lastTime = targetTime - sg.time.getSecondTime();
                if (lastTime > 0) {
                    this.lblLastTime.text = sg.translate("秘境倒计时:") + sg.time.formatTimeStr(lastTime);
                }
                else {
                    this.lblLastTime.text = "";
                    this.stopTimer(this._onOffseTime);
                }
            }
            else {
                this.lblLastTime.text = "";
                this.stopTimer(this._onOffseTime);
            }
        }
        _sendInviteAll() {
            if (mvc.roleModel.roleInfo.guildId == 0) {
                sg.uimgr.showNotice(sg.translate("加入仙盟才可以分享房间哦"));
                return;
            }
            let vo = mvc.islandModel.getRoomVo(this.masterId);
            if (vo) {
                let cfg = sg.dbmgr.get("chat_notice", 26);
                let param = [[vo.master_id, mvc.FUNC_ID.ISLAND]];
                mvc.chatCtrl.reqSend(mvc.ChatConst.ChannelDefine.GUILD, cfg.value, param, 1, mvc.GuildConst.HELP_TYPE.ISLAND_INVITE);
                sg.uimgr.showNotice(sg.translate("仙盟频道发送邀请成功"), "green");
            }
        }
        _showAsseccAni(reward) {
            let id = mvc.roleModel.roleInfo.playerId;
            if (id == this.masterId) {
                this._point.setTo(this.eggSp.x, this.eggSp.y - 40);
                this.localToGlobal(this._point, false);
                mvc.PopItemEffect.showEff(reward, null, this._point, this);
            }
            else {
                let member = this.vo.getMemberArr();
                let pos = -1;
                for (let i = 0; i < member.length; i++) {
                    if (member[i].playerId == id) {
                        pos = member[i].pos;
                        break;
                    }
                }
                if (pos != -1) {
                    let item = this.listRole.getCell(pos - 1);
                    this._point.setTo(item.eggSp.x, item.eggSp.y - 30);
                    item.localToGlobal(this._point, false);
                    mvc.PopItemEffect.showEff(reward, null, this._point, this);
                }
            }
        }
        _showTips() {
            let vo = this.vo.getPlayerVo(mvc.roleModel.roleInfo.playerId);
            if (vo) {
                let v1 = vo.eggNum;
                this.lblTips.text = StringEx.format(sg.translate("本次修炼已孵蛋${v1}个"), {"v1":v1});
            }
        }
        _onClick(e) {
            if (this.imgTips.visible) {
                this.imgTips.visible = false;
                return;
            }
            switch (e.target) {
                case this.btnExit:
                    {
                        mvc.islandCtrl.reqIslandRoomLeave();
                    }
                    break;
                case this.btnShare:
                    {
                        mvc.islandCtrl.reqIslandShare();
                    }
                    break;
                case this.btnHatchSet:
                    {
                        sg.uimgr.showUI("pop_islandHatchSet");
                        mvc.islandModel.fireEvent(mvc.IslandConst.EVT.JOIN);
                    }
                    break;
                case this.btnPetPool:
                    {
                        if (mvc.islandModel.vo.petNum > 0) {
                            mvc.islandCtrl.reqIslandPetPool();
                        }
                        else
                            sg.uimgr.showNotice(sg.translate("暂无异兽"));
                    }
                    break;
                case this.btnLog:
                    {
                        sg.uimgr.showUI("pop_islandRoomRecord", this.masterId);
                    }
                    break;
                case this.boxMClick:
                    {
                        let vo = mvc.islandModel.getRoomVo(this.masterId);
                        let pVo = vo.getPlayerVo(this.masterId);
                        if (pVo && pVo.playerId > 0 && pVo.playerId != mvc.roleModel.roleInfo.playerId)
                            mvc.mainCtrl.reqPlayerInfo(pVo.playerId);
                    }
                    break;
                case this.imgBuffTips:
                    {
                        this.imgTips.visible = true;
                    }
                    break;
            }
        }
    }
    mvc.PopIslandRoom = PopIslandRoom;
})(mvc || (mvc = {}));

