(function (mvc) {
    class OpenLotteryVo extends sg.VoBase {
        updateData(info) {
            if (!info)
                return;
            this.free_count = info.free_count;
            this.lucky = info.lucky;
            this.buy_count = info.buy_count;
            this.reward_record = info.reward_record;
            this.notice_record = info.notice_record;
        }
        getItemGetNumById(id) {
            let getNum = 0;
            if (this.reward_record) {
                for (let i = 0, len = this.reward_record.length; i < len; i++) {
                    let info = this.reward_record[i];
                    if (id == info[0]) {
                        getNum = info[1];
                        break;
                    }
                }
            }
            return getNum;
        }
        isGetAllReward() {
            let isGetAll = false;
            let arr = sg.dbmgr.getArray("openActive_activeReward", { guarantees: 1 });
            for (let i = 0, len = arr.length; i < len; i++) {
                let info = arr[i];
                isGetAll = this.getItemGetNumById(info.id) == info.numLimit;
                if (!isGetAll)
                    break;
            }
            return isGetAll;
        }
        getIndexByReward(reward) {
            let idx = 1;
            let arr = sg.dbmgr.getDB("openActive_activeReward", true);
            for (let i = 0, len = arr.length; i < len; i++) {
                let info = arr[i].item[0];
                if (info.toString() == reward.toString()) {
                    idx = i + 1;
                    break;
                }
            }
            return idx;
        }
        isGuaranteeById(id) {
            let arr = sg.dbmgr.getArray("openActive_activeReward", { guarantees: 1 });
            for (let i = 0, len = arr.length; i < len; i++) {
                if (id == arr[i].item[0][0])
                    return true;
            }
            return false;
        }
    }
    mvc.OpenLotteryVo = OpenLotteryVo;
})(mvc || (mvc = {}));

