(function (mvc) {
    let EVT = mvc.OpenActiveLotteryConst.EVT;
    class OpenActiveLotteryModel extends sg.ModelBase {
        constructor() {
            super(...arguments);
            this.isInAni = false;
            this.isTenAni = false;
            this.isSkipAni = false;
        }
        get isPassAct() {
            let activity = mvc.activityModel.openActivityVo.get(mvc.FUNC_ID.OPEN_ACTIVE);
            if (activity) {
                return activity.end_time - sg.time.getSecondTime() <= 0;
            }
            else {
                return false;
            }
        }
        ;
        initModel() {
            this.vo = new mvc.OpenLotteryVo();
        }
        registerEvents() {
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.OPEN_ACTIVE_LOTTERY, this._checkRedLottery, this);
        }
        setLotteryInfo(data) {
            if (this.vo) {
                this.vo.updateData(data);
                mgr.redotMgr.check(mvc.REDOT_ID.OPEN_ACTIVE_LOTTERY);
                this.fireEvent(EVT.UPDATE_VIEW);
            }
        }
        _checkRedLottery() {
            let haveReward = false;
            if (this.vo) {
                let free_count = mgr.toolsMgr.getGlobalVoById("active_kfhd_free", 1);
                let consume = mgr.toolsMgr.getGlobalVoById("active_kfhd_item_one", 1);
                if (this.vo.free_count < free_count || mgr.toolsMgr.checkConsume(consume, false, false)) {
                    haveReward = true;
                }
            }
            return haveReward ? 1 : 0;
        }
        getReward(data) {
            if (this.vo) {
                this.vo.lucky = data.lucky;
                this.vo.free_count = data.free_count;
                this.vo.buy_count = data.buy_count;
                this.vo.reward_record = data.reward_record;
                this.fireEvent(EVT.PLAY_ANI, data.reward);
                mgr.redotMgr.check(mvc.REDOT_ID.OPEN_ACTIVE_LOTTERY);
            }
        }
    }
    mvc.OpenActiveLotteryModel = OpenActiveLotteryModel;
})(mvc || (mvc = {}));

