(function (mvc) {
    class PopOpenLotteryPool extends ui.view.openActive.pop_openLotterPoolUI {
        initView(...args) {
            this._model = mvc.openActiveLotteryModel;
        }
        initModelEvent() {
        }
        initCtrlEvent() {
            this.listLotterItem2.vScrollBarSkin = "";
            this.listLotterItem1.renderHandler = this.createHandler(this, this._onRenderList, null, false);
            this.listLotterItem2.renderHandler = this.createHandler(this, this._onRenderList, null, false);
        }
        onEnable() {
            super.onEnable();
            this._updateView();
        }
        _updateView() {
            let arr = sg.dbmgr.getArray("openActive_activeReward", { guarantees: 1 });
            this.lblProbability1.text = sg.translate("综合出货概率:") + this._getProbability(arr);
            this.listLotterItem1.array = arr;
            arr = sg.dbmgr.getArray("openActive_activeReward", { guarantees: 0 });
            this.lblProbability2.text = sg.translate("综合出货概率:") + this._getProbability(arr);
            this.listLotterItem2.array = arr;
        }
        _getProbability(arr) {
            let probability = 0;
            for (let i = 0; i < arr.length; i++) {
                probability += arr[i].showpro;
            }
            if (probability > 0)
                return (probability / 100).toFixed(1) + "%";
            else
                return "";
        }
        _onRenderList(cell, index) {
            if (!cell.dataSource)
                return;
            let item = cell.getChildByName("item");
            let probability = cell.getChildByName("lblProbability");
            let data = cell.dataSource;
            if (item) {
                item.initViewCfg(data.item[0]);
            }
            if (probability) {
                probability.text = (data.showpro / 100).toFixed(2) + "%";
            }
            let lblLimit = cell.getChildByName("lblLimit");
            if (lblLimit) {
                lblLimit.visible = true;
                let getNum = this._model.vo.getItemGetNumById(data.id);
                lblLimit.text = sg.translate("限量:") + (data.numLimit - getNum) + "/" + data.numLimit;
                lblLimit.color = getNum < data.numLimit
                    ? mgr.toolsMgr.getColor3("green").stringColor
                    : mgr.toolsMgr.getColor3("red").stringColor;
            }
        }
    }
    mvc.PopOpenLotteryPool = PopOpenLotteryPool;
})(mvc || (mvc = {}));

