        analyzeNotic(notic, params, ischeck = true) {
            if (notic == "" || !notic)
                return notic;
            this._tempParams = params;
            if (ischeck) {
                this.checkParams(params);
            }
            notic = notic.replace(MainModel.RELACE_REGEXP, !this._reFun ? this._reFun = this.replaceFunc.bind(this) : this._reFun);
            return notic;
        }
        checkParams(params) {
            if (params instanceof Array) {
                let arr = [params];
                while (arr.length > 0) {
                    let p = arr.pop();
                    for (let key in p) {
                        let v = p[key];
                        if (v instanceof Array) {
                            arr.push(v);
                        }
                        else if (typeof (v) == "string") {
                            p[key] = mgr.UIAssist.limmitStrCutError(v);
                        }
                    }
                }
            }
        }
