(function (mvc) {
    class UnitTimeGift extends ui.view.main.unit_timeGiftUI {
        onAwake() {
            super.onAwake();
            this._isFirst = true;
            let id = mgr.toolsMgr.getGlobalVoById("pet_show", 1);
            this.unitModel.changeShowMode(false, id);
            this.unitModel.loadedHandle = () => {
                if (this.visible) {
                    this.unitModel.play("stand", true);
                }
                else {
                    this.unitModel.stop();
                }
            };
            this.unitModel.loadRole(id, "UnitRoleShow");
        }
        onEnable() {
            super.onEnable();
            this.bindModelEvent(mvc.timeGiftModel, mvc.TimeGiftConst.EVT.UPDATE_TIME_GIFT, this._updateVisible);
            this.bindModelEvent(mvc.roleModel, mvc.RoleConst.EVT.LEVEL_UP, this._updateVisible);
            this.boxClick.on(Laya.Event.CLICK, this, this._onBoxClick);
            this._updateVisible();
        }
        onDisable() {
            this.boxClick.off(Laya.Event.CLICK, this, this._onBoxClick);
            super.onDisable();
        }
        pauseSpine() {
            if (!this.visible)
                return;
            this.unitModel.pause();
            this.ani1.pause();
        }
        resumeSpine() {
            if (!this.visible)
                return;
            this.unitModel.resume();
            this.ani1.resume();
        }
        _updateVisible() {
            this.stopTimer(this._updateVisible);
            if (!mgr.conditionMgr.checkShowCondition(mvc.FUNC_ID.TIME_GIFT, false)
                || !mgr.conditionMgr.checkFunc(mvc.FUNC_ID.TIME_GIFT, false)) {
                this.visible = false;
                this.ani1.stop();
                this.unitModel.stop();
                return;
            }
            if (mvc.timeGiftModel.lastNum > 0) {
                let now = sg.time.getSecondTime();
                if (now >= mvc.timeGiftModel.nextTime) {
                    if (this._isFirst) {
                        this.visible = false;
                        this.ani1.stop();
                        this.unitModel.stop();
                        let loginTime = mgr.toolsMgr.getGlobalVoById("tg_login_time", 1);
                        this.after(loginTime * 1000, this._updateVisible);
                        this._isFirst = false;
                    }
                    else {
                        this.visible = true;
                        this.ani1.play(0, true);
                        this.unitModel.play("stand", true);
                    }
                }
                else {
                    this.visible = false;
                    this.ani1.stop();
                    this.unitModel.stop();
                    let last = mvc.timeGiftModel.nextTime - now;
                    if (this._isFirst) {
                        let loginTime = mgr.toolsMgr.getGlobalVoById("tg_login_time", 1);
                        last = Math.max(last, loginTime);
                        this._isFirst = false;
                    }
                    this.after(last * 1000, this._updateVisible);
                }
            }
            else {
                this.visible = false;
                this.ani1.stop();
                this.unitModel.stop();
            }
        }
        _onBoxClick() {
            sg.uimgr.showUI("pop_timeGift");
        }
    }
    mvc.UnitTimeGift = UnitTimeGift;
})(mvc || (mvc = {}));

