var mvc;
(function (mvc) {
    class PopMineSweepEnter extends ui.view.bgActivity5.pop_mineSweepEnterUI {
        initView() {
        }
        initSendMsg() {
            mvc.mineSweepCtrl.reqMineSweepRewardInfo();
            this._curLevel = mvc.mineSweepModel.curLevel;
            mvc.mineSweepCtrl.reqMineSweepInfo(this._curLevel);
            mvc.rankCtrl.reqRankInfo(mvc.RankConst.RANK_TYPE.mine_sweep);
        }
        initModelEvent() {
            this.bindModelEvent(mvc.mineSweepModel, mvc.MineSweepConst.EVT.UPDATE_INFO, this._updateView);
            this.bindModelEvent(mvc.mineSweepModel, mvc.MineSweepConst.EVT.GO_NEXT_LEVEL, this._goNextLevel);
            this.bindModelEvent(mvc.rankModel, mvc.RankConst.EVT.UPDATE_RANK_INFO, this._udpateRank);
        }
        initCtrlEvent() {
            this.on(Laya.Event.CLICK, this, this._onClick);
        }
        updateData(types, ...args) { }
        onAwake() {
            super.onAwake();
            this.redTips.visible = false;
        }
        onEnable() {
            super.onEnable();
            if (!sg.varmgr.getUserVar("mine_sweep_first")) {
                sg.varmgr.setUserVar("mine_sweep_first", true);
                mgr.redotMgr.check(mvc.REDOT_ID.ACT_MINE_SWEEP);
            }
            this.repeats(1000, this._onTime, true);
        }
        onJumpInit(jumpParams) {
        }
        onDisable() {
            super.onDisable();
        }
        onClosed() {
            super.onClosed();
        }
        _goNextLevel(level) {
            let cfg = sg.dbmgr.get("backgroundActive_active5Level", level);
            if (cfg) {
                let day = mvc.activityModel.openActivityVo.get(mvc.FUNC_ID.ACT_MINE_SWEEP).getOpenDay();
                if (day < cfg.dayLimit) {
                    return;
                }
                mvc.mineSweepCtrl.reqMineSweepInfo(level);
                this._curLevel = level;
            }
        }
        _udpateRank(type, rankVo) {
            mvc.mineSweepModel.myLastRank = rankVo.myRank;
        }
        _updateView() {
            this._vo = mvc.mineSweepModel.getLevelMap(this._curLevel);
            if (this._vo) {
                let cfg = sg.dbmgr.get("backgroundActive_active5Level", this._vo.level_id);
                if (cfg) {
                    this.lblTips.text = cfg.name;
                    mgr.icon.drawTexture(`ui/${cfg.image}`, this.imgDi);
                }
                this.btnStart.label = this._vo.state == 1 ? sg.translate("继续") : sg.translate("开始");
                this.redTips.visible = this._showRedTips(this._curLevel);
                this.redTipsL.visible = this._showRedTips2(this._curLevel, false);
                this.redTipsR.visible = this._showRedTips2(this._curLevel, true);
                let day = mvc.activityModel.openActivityVo.get(mvc.FUNC_ID.ACT_MINE_SWEEP).getOpenDay();
                if (this._vo.history_min_sec > 0) {
                    this.lblPass.visible = true;
                    this.lblPass.text = StringEx.format(sg.translate("最快通关时间:")) + sg.time.formatTimeStr(this._vo.history_min_sec);
                }
                else if (day < cfg.dayLimit) {
                    this.lblPass.text = sg.translate("活动第") + cfg.dayLimit + sg.translate("天开启");
                }
                else
                    this.lblPass.visible = false;
                let cfgs = mvc.mineSweepModel.getCfgs(this._vo.level_id);
                if (cfgs && cfgs.length > 0) {
                    for (let i = 0; i < cfgs.length; i++) {
                        if (this[`imgStart${i + 1}`]) {
                            this[`imgStart${i + 1}`].gray = (!this._vo.award_ids) || this._vo.award_ids.indexOf(cfgs[i].id) == -1;
                        }
                    }
                }
                cfg = sg.dbmgr.get("backgroundActive_active5Level", this._vo.level_id - 1);
                if (!cfg)
                    this.btnLast.visible = false;
                else
                    this.btnLast.visible = true;
                cfg = sg.dbmgr.get("backgroundActive_active5Level", this._vo.level_id + 1);
                if (!cfg) {
                    this.btnNext.visible = false;
                }
                else
                    this.btnNext.visible = true;
            }
            this.lblHadNum.text = "" + mvc.mineSweepModel.planNum;
            if (mvc.mineSweepModel.planNum > 0)
                this.lblHadNum.color = mgr.toolsMgr.getColor2("green");
            else
                this.lblHadNum.color = mgr.toolsMgr.getColor2("red");
        }
        _showRedTips(level) {
            let cfgs = mvc.mineSweepModel.getCfgs(level);
            this._vo = mvc.mineSweepModel.getLevelMap(level);
            if (cfgs && cfgs.length > 0) {
                for (let i = 0; i < cfgs.length; i++) {
                    if (this._vo.award_ids && this._vo.history_min_sec > 0 && this._vo.history_min_sec <= cfgs[i].needTime && this._vo.award_ids.indexOf(cfgs[i].id) == -1)
                        return true;
                }
            }
            return false;
        }
        _showRedTips2(level, isAdd) {
            while (level > 0) {
                if (isAdd)
                    level += 1;
                else {
                    level -= 1;
                }
                let cfg = sg.dbmgr.get("backgroundActive_active5Level", level);
                if (!cfg)
                    break;
                let cfgs = mvc.mineSweepModel.getCfgs(level);
                let vo = mvc.mineSweepModel.getLevelMap(level);
                if (cfgs && cfgs.length > 0 && vo) {
                    for (let i = 0; i < cfgs.length; i++) {
                        if (this._vo.award_ids && vo.history_min_sec > 0 && vo.history_min_sec <= cfgs[i].needTime && vo.award_ids.indexOf(cfgs[i].id) == -1)
                            return true;
                    }
                }
            }
            return false;
        }
        _onTime() {
            let actVo = mvc.activityModel.openActivityVo.get(mvc.FUNC_ID.ACT_MINE_SWEEP);
            if (actVo) {
                let endTime = actVo.end_time;
                let curTime = sg.time.getSecondTime();
                let lastTime = endTime - curTime;
                if (lastTime <= 0) {
                    this.stopTimer(this._onTime);
                    this.closeSelf();
                }
            }
            else {
                this.stopTimer(this._onTime);
                this.closeSelf();
            }
        }
        _onClick(e) {
            switch (e.target) {
                case this.btnLast:
                    {
                        this._curLevel--;
                        if (this._curLevel < mvc.MineSweepConst.CONST.INIT_LEVEL)
                            this._curLevel = mvc.MineSweepConst.CONST.INIT_LEVEL;
                        mvc.mineSweepCtrl.reqMineSweepInfo(this._curLevel);
                    }
                    break;
                case this.btnNext:
                    {
                        if (this._vo.history_min_sec <= 0) {
                            sg.uimgr.showNotice(sg.translate("需要通关当前关卡"));
                            return;
                        }
                        this._curLevel++;
                        let cfg = sg.dbmgr.get("backgroundActive_active5Level", this._vo.level_id);
                        if (!cfg) {
                            this._curLevel--;
                        }
                        mvc.mineSweepCtrl.reqMineSweepInfo(this._curLevel);
                    }
                    break;
                case this.btnReward:
                    {
                        sg.uimgr.showUI("pop_mineSweepReward", this._curLevel);
                    }
                    break;
                case this.btnStart:
                    {
                        let cfg = sg.dbmgr.get("backgroundActive_active5Level", this._curLevel);
                        if (cfg) {
                            let lv = cfg.levelLimit;
                            let lastLvVo = mvc.mineSweepModel.getLevelMap(lv);
                            if (lv > 0 && (!lastLvVo || lastLvVo.history_min_sec <= 0)) {
                                sg.uimgr.showNotice(sg.translate("请先通关上一关卡"));
                                return;
                            }
                            let day = mvc.activityModel.openActivityVo.get(mvc.FUNC_ID.ACT_MINE_SWEEP).getOpenDay();
                            if (day < cfg.dayLimit) {
                                let str = sg.translate("活动第") + cfg.dayLimit + sg.translate("天开启");
                                sg.uimgr.showNotice(str);
                                return;
                            }
                            if (this._vo && this._vo.state == 1) {
                                sg.uimgr.showUI("pop_mineSweepLevel", this._curLevel);
                            }
                            else {
                                mvc.mineSweepCtrl.reqMineSweepBegin(this._curLevel);
                            }
                        }
                    }
                    break;
                case this.btnRank:
                    {
                        sg.uimgr.showUI("pop_mineSweepRank", this._curLevel);
                    }
                    break;
                case this.btnGuildHelp:
                    {
                        if (mvc.roleModel.roleInfo.guildId > 0) {
                            mvc.guildCtrl.reqGuildSeekHelp(mvc.GuildConst.HELP_TYPE.MINE_SWEEP);
                        }
                        else
                            sg.uimgr.showNotice(sg.translate("请先加入仙盟"));
                    }
                    break;
                case this.btnDesc:
                    {
                        sg.uimgr.showUI("pop_mineSweepDesc");
                    }
                    break;
            }
        }
    }
    mvc.PopMineSweepEnter = PopMineSweepEnter;
})(mvc || (mvc = {}));

