var mvc;
(function (mvc) {
    class UnitMineSweepGrid extends ui.view.bgActivity5.unit_MineSweepGridUI {
        onAwake() {
            super.onAwake();
            this.img1.on(Laya.Event.MOUSE_DOWN, this, this._onMouseHandle);
            this.img1.on(Laya.Event.MOUSE_OUT, this, this._onMouseHandle);
            this.img1.on(Laya.Event.MOUSE_UP, this, this._onMouseHandle);
        }
        set dataSource(data) {
            if (!data)
                return;
            super.dataSource = data;
            this._myPosition = data.pos;
            this._vo = data.posData;
            this._level = data.level;
            this.imgMonster.visible = this.imgCheck.visible = this.imgBridge.visible = this.fClipNum.visible = false;
            this.img1.visible = this.imgStart.visible = this.imgEnd.visible = this.eff.visible = false;
            this.img1.alpha = 1;
            this.lbl.text = `(${this._myPosition[0]},${this._myPosition[1]})`;
            if (this._vo) {
                if (this._vo.isOhter != 0) {
                    this.imgStart.visible = this._vo.isOhter == 1;
                    this.imgEnd.visible = this._vo.isOhter == 2;
                }
                else if (this._vo.flag == 3) {
                    this.imgMonster.visible = true;
                    this.img1.visible = true;
                    this.img1.alpha = 0.7;
                }
                else if (this._vo.flag == 1) {
                    this.fClipNum.visible = true;
                    this.fClipNum.value = this._vo.param[0];
                }
                else if (this._vo.flag == 2) {
                    this.fClipNum.visible = true;
                    this.fClipNum.value = this._vo.param[0];
                    this.img1.visible = true;
                    this.img1.alpha = 0.7;
                }
                else if (this._vo.flag == 4) {
                    this.imgMonster.visible = true;
                }
            }
            else {
                this.img1.visible = true;
                let msVo = mvc.mineSweepModel.getLevelMap(this._level);
                if (msVo && msVo.getBannerGrid(this._myPosition)) {
                    this.imgCheck.visible = true;
                }
            }
        }
        get gridPos() {
            return this._myPosition;
        }
        showBridge(show, time) {
            if (show) {
                let self = this;
                let fun = () => {
                    this.eff.visible = true;
                    this.eff.ani1.play(0, false);
                    let showFunc = () => {
                        self.eff.visible = false;
                    };
                    this.eff.on(Laya.Event.COMPLETE, null, showFunc);
                    this.imgBridge.visible = true;
                };
                this.after(time, fun);
            }
            else
                this.imgBridge.visible = false;
        }
        _onMouseHandle(e) {
            switch (e.type) {
                case Laya.Event.MOUSE_DOWN:
                    {
                        this._downTime = Date.now();
                    }
                    break;
                case Laya.Event.MOUSE_OUT:
                    {
                        this._downTime = 0;
                        this._upTime = 0;
                    }
                    break;
                case Laya.Event.MOUSE_UP:
                    {
                        if (this._downTime > 0) {
                            this._upTime = Date.now();
                            this.onPress();
                        }
                    }
                    break;
            }
        }
        onPress() {
            let model = mvc.mineSweepModel;
            let state = model.levelClickState;
            switch (state) {
                case 1:
                    {
                        if (!mvc.mineSweepModel.checkPeripheralGrids(this._level, this._myPosition)) {
                            sg.uimgr.showNotice(sg.translate("请按顺序探索"));
                            return;
                        }
                        mvc.mineSweepCtrl.reqMineSweepGridOpen(this._level, this._myPosition);
                    }
                    break;
                case 2:
                    {
                        let vo = model.getLevelMap(this._level);
                        if (vo && this._myPosition && this._myPosition.length > 0) {
                            let isAdd = vo.getBannerGrid(this._myPosition) ? 2 : 1;
                            mvc.mineSweepCtrl.reqMineSweepBanner(this._level, this._myPosition, isAdd);
                        }
                    }
                    break;
                case 3:
                    {
                        let cfg = sg.dbmgr.get("backgroundActive_active5Level", this._level);
                        let vo = model.getLevelMap(this._level);
                        if (cfg && vo && vo.use_silk_num >= cfg.tipsLimit) {
                            sg.uimgr.showNotice(sg.translate("本关您使用的锦囊的次数已上限"));
                            return;
                        }
                        if (model.planNum <= 0) {
                            sg.uimgr.showNotice(sg.translate("您的锦囊不足,快去找盟友获取吧~"));
                            return;
                        }
                        mvc.mineSweepCtrl.reqMineSweepMakeIdea(this._level, this._myPosition);
                    }
                    break;
            }
        }
    }
    mvc.UnitMineSweepGrid = UnitMineSweepGrid;
})(mvc || (mvc = {}));

