var mvc;
(function (mvc) {
    class ManorModel extends sg.ModelBase {
        initModel() {
            this.curShowSelf = true;
            this.isCrossReset = false;
        }
        registerEvents() {
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.MANOR_RECORD, this.checkRecord, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.MANOR_BUY_BOY, this.checkBoy, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.MANOR_BOY_FREE, this.checkBoyFree, this);
        }
        countCollectionTime(id, child) {
            let cfg = sg.dbmgr.get("manor_resource", id);
            let ecfg = sg.dbmgr.get("manor_fatigue", this.selfInfo.fatigue + 1);
            if (cfg && ecfg) {
                return cfg.collectionTime / (child * ecfg.efficiency / 10000);
            }
            return 0;
        }
        getManorRefreshCd() {
            return mgr.toolsMgr.getGlobalVoById("manor_refresh_cd", 1) * 60;
        }
        getCurShowManorInfo() {
            if (this.curShowSelf) {
                return this.selfManorInfo;
            }
            else {
                return this.otherManorInfo;
            }
        }
        getCurShowPid() {
            if (!this.curShowSelf && this.otherManorInfo) {
                return this.otherManorInfo.head.player_id;
            }
            else {
                return mvc.roleModel.roleInfo.playerId;
            }
        }
        getChildIdleNum() {
            if (this.selfInfo) {
                let c = 0;
                for (let v of this.selfInfo.rob_info) {
                    c += v.boy_num;
                }
                return this.selfInfo.boy_num - c;
            }
            return 0;
        }
        getInitChildNum() {
            return mgr.toolsMgr.getGlobalVoById("initial_boy_num", 1);
        }
        checkRecord() {
            return mvc.redotCtrl.getCheckRed(mvc.REDOT_ID.MANOR_RECORD);
        }
        checkBoy() {
            if (!mvc.manorModel.selfInfo)
                return 0;
            let curTimes = mvc.manorModel.selfInfo.boy_num - mvc.manorModel.getInitChildNum() + 1;
            let cfg = sg.dbmgr.get("manor_price", curTimes);
            if (cfg && mgr.toolsMgr.checkConsume(cfg.price)) {
                return 1;
            }
            return 0;
        }
        checkSelfProtectByPos(pos) {
            if (this.selfManorInfo) {
                for (let key in this.selfManorInfo.resources) {
                    let v = this.selfManorInfo.resources[key];
                    if (v && v.pos == pos && v.is_protected) {
                        return true;
                    }
                }
            }
            return false;
        }
        getCanCollectTime(pid) {
            if (mvc.roleModel.isSelf(pid)) {
                return 0;
            }
            else if (this.otherManorInfo && pid == this.otherManorInfo.head.player_id) {
                for (let key in this.otherManorInfo.rob_cd) {
                    let v = this.otherManorInfo.rob_cd[key];
                    if (v && v[0] == mvc.roleModel.roleInfo.playerId) {
                        return v[1];
                    }
                }
            }
            return 0;
        }
        checkBoyFree() {
            if (!mvc.manorModel.selfInfo || !mgr.conditionMgr.checkFunc(mvc.FUNC_ID.MANOR, false))
                return 0;
            let curTimes = this.getChildIdleNum();
            if (curTimes > 0 && mvc.manorModel.selfInfo.fatigue <= 30) {
                return 1;
            }
            return 0;
        }
        isCross() {
            return mvc.crossActiveModel.is_open_activity && mvc.crossActiveModel.is_cross_succeed;
        }
        crossShowInfo() {
            if (mvc.crossActiveModel.is_open_activity) {
                this.isCrossReset = true;
                mvc.manorCtrl.reqManorDetails();
                this.closeALLManorUI();
            }
        }
        closeALLManorUI() {
            this.otherManorInfo = null;
            this.curShowSelf = true;
            sg.uimgr.closeUI("sys_manor");
            sg.uimgr.closeUI("pop_manorRob");
            sg.uimgr.closeUI("pop_refreshComfirm");
            sg.uimgr.closeUI("pop_manorRecoder");
            sg.uimgr.closeUI("pop_manorFightEnter");
            sg.uimgr.closeUI("pop_fatigue");
            sg.uimgr.closeUI("pop_collectionManor");
        }
    }
    mvc.ManorModel = ManorModel;
})(mvc || (mvc = {}));

