(function (mvc) {
    class PopKFOpenEff extends ui.view.manor.pop_kfOpenUI {
        initView() {
            this.isCloudLoad = false;
        }
        initModelEvent() { }
        initCtrlEvent() {
            this.uiEff.setEndHandle("", this._aniComplte.bind(this));
            this.uiEff.loadedHandle = this._loadComplte.bind(this);
            this.effShow.setEndHandle("", this._aniCloudComplte.bind(this));
            this.effShow.loadedHandle = this._loadCloudComplte.bind(this);
            this.effShow.lableHandle = this._lableComplte.bind(this);
            this.ani1.on(Laya.Event.COMPLETE, this, this.onAniShow);
        }
        onEnable() {
            super.onEnable();
            mvc.manorCtrl.reqEnterManorCross();
            this.uiEff.loadRole(mvc.ManorConst.DOORID, "pop_kFOpenEff", false);
            this.effShow.loadRole(mvc.ManorConst.CLOUDID, "pop_kFOpenEff", false);
            this.effShow.visible = false;
        }
        onDisable() {
            sg.uimgr.showUI("sys_manor", mvc.manorModel.getCurShowPid());
            super.onDisable();
        }
        _aniComplte(sLoop, curAniName) {
            if (!sLoop && curAniName == "open") {
                if (this.destroyed)
                    return;
                this.uiEff.play("stand", true);
                this.ani1.play(0, false);
            }
        }
        _lableComplte(eventData) {
            if (!eventData) {
                sg.Logger.openLog && sg.log("事件错误");
                return;
            }
            if (eventData.name == "end") {
                this.uiEff.visible = false;
                this.boxEff.visible = false;
            }
        }
        _loadComplte() {
            this.uiEff.play("open", false);
        }
        _aniCloudComplte(sLoop, curAniName) {
            if (!sLoop && curAniName == "end") {
                if (!this.destroyed)
                    this.closeSelf();
            }
        }
        playCloud() {
            if (this.isCloudLoad && this.isLblEnd) {
                this.effShow.visible = true;
                this.effShow.play("end", false);
            }
        }
        _loadCloudComplte() {
            this.isCloudLoad = true;
            this.playCloud();
        }
        onAniShow() {
            this.isLblEnd = true;
            this.playCloud();
        }
    }
    mvc.PopKFOpenEff = PopKFOpenEff;
})(mvc || (mvc = {}));

