(function (mvc) {
    class UnitSourceItem extends ui.view.manor.unit_sourceItemUI {
        onAwake() {
            super.onAwake();
            this.on(Laya.Event.CLICK, this, this.onClick);
            this.lblTime.useAsNumber = true;
        }
        onDisable() {
            super.onDisable();
            if (this.unitTip && !this.unitTip.parent) {
                this.unitTip.destroy();
                this.unitTip = null;
            }
        }
        updateView(id, time = -1, isClick = true, tipParent = null) {
            this.id = id;
            this.time = time;
            this.isClick = isClick;
            this.tipParent = tipParent;
            let cfg = sg.dbmgr.get("manor_resource", this.id);
            this.lblLevel.text = mgr.UIAssist.$("Lv.{1}", cfg.level);
            if (time == -1) {
                this.lblLevel.y = this.lblTime.y;
            }
            else {
                this.lblLevel.y = this.lblTime.y - this.lblLevel.height;
            }
            mgr.icon.drawTexture(mgr.icon.getIconPath(cfg.icon), this.imgIcon);
            this.updateTime();
        }
        updateTime() {
            let time = this.time - sg.time.getSecondTime();
            this.lblTime.visible = time > 0;
            if (time > 0) {
                let text = sg.time.formatTimeStrT("F0", time);
                this.lblTime.changeText(text);
            }
        }
        onClick() {
            if (this.isClick) {
                if (!this.unitTip) {
                    this.unitTip = new mvc.UnitSourceTip();
                    this.unitTip.updateView(this.id);
                }
                if (!this.unitTip.parent) {
                    if (this.tipParent) {
                        this.tipParent.addChild(this.unitTip);
                        this.unitTip.x = this.tipParent.width - this.unitTip.width >> 1;
                        this.unitTip.y = this.tipParent.height - this.unitTip.height >> 1;
                    }
                    else {
                        this.addChild(this.unitTip);
                        this.unitTip.x = this.width - this.unitTip.width >> 1;
                    }
                }
            }
        }
    }
    mvc.UnitSourceItem = UnitSourceItem;
})(mvc || (mvc = {}));

