var mvc;
(function (mvc) {
    class PopFeastQuestion extends ui.view.bgActivity6.pop_feastQuestionUI {
        constructor() {
            super(...arguments);
            this._changeing = false;
            this._isFinish = true;
        }
        initSendMsg() {
        }
        initModelEvent() {
            this.bindModelEvent(mvc.moonFeastivalModel, mvc.MoonFeastivalConst.EVT.ANSWER_QUESTION, this._answer);
        }
        initCtrlEvent() {
            this.imgCopy.on(Laya.Event.CLICK, this, this._onClick);
            this.btnLeft.on(Laya.Event.CLICK, this, this._onBtnLeft);
            this.btnRight.on(Laya.Event.CLICK, this, this._onBtnRight);
            this.listAnswer.selectEnable = true;
            this.listAnswer.selectHandler = this.createHandler(this, this._onSelectList, null, false);
            this.listAnswer.renderHandler = this.createHandler(this, this._onRenderList, null, false);
        }
        updateData(types, ...args) { }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            this._myAnswer = -1;
            this._isAnser = false;
            let data = this.openParams[0];
            this._idx = data.curAnswerIdx;
            this._result = data.result;
            this._dinnerInfo = data.data;
            this._questions = this._dinnerInfo.data;
            this._pos = data.curPos;
            this._isFinish = data.isFinish;
            if (this._isFinish) {
                this._curIndex = 1;
            }
            else {
                this._curIndex = data.curAnswerIdx;
            }
            this._updateBtn();
            this._updateView();
        }
        onJumpInit(jumpParams) {
        }
        onDisable() {
            mvc.plantModel.eventInfo = null;
            this._changeing = false;
            super.onDisable();
        }
        onClosed() {
            mvc.plantModel.eventInfo = null;
            this._changeing = false;
            super.onClosed();
        }
        _updateView() {
            if (this._questions && this._questions.length > 0 && this._idx > 0) {
                let id = this._getCurQuestionID();
                let cfg = sg.dbmgr.get("backgroundActive_active6Question", id);
                if (cfg) {
                    this._rightAnswer = cfg.rightKey;
                    this.lblQuestion.text = cfg.question;
                    this.lblIdx.text = sg.translate("第") + mgr.toolsMgr.changeToChinese(this._curIndex) + sg.translate("题");
                    this.lblCount.text = sg.translate("问答题数") + `(${this._curIndex}/${this._questions.length})`;
                    this.lblQuestionInfo.text = mgr.UIAssist.$("{1}/{2}", this._curIndex, this._questions.length);
                    this.listAnswer.array = cfg.answer;
                }
            }
        }
        _getCurQuestionID() {
            for (let i = 0; i < this._questions.length; i++) {
                if (this._questions[i][0] == this._curIndex) {
                    return this._questions[i][1];
                }
            }
        }
        _end(reward) {
            this.after(200, () => {
                sg.uimgr.closeUI("pop_feastQuestion");
                sg.uimgr.showUI("pop_questionResult", reward);
            });
        }
        _answer(msg) {
            if (this._idx > 0) {
                this._isAnser = true;
                this._updateView();
                let self = this;
                if (msg.is_finished) {
                    this._end(msg.reward);
                }
                this.after(1500, () => {
                    if (!msg.is_finished) {
                        this._isAnser = false;
                        self._curIndex = self._idx = msg.now_pos;
                        self._myAnswer = -1;
                        self._updateView();
                    }
                });
                this.after(1700, () => {
                    self._changeing = false;
                });
            }
        }
        _onSelectList(index) {
            if (index == -1 || this._isFinish)
                return;
            let id = this.listAnswer.array[index];
            this._myAnswer = id;
            if (id > 0 && this._changeing == false) {
                this._changeing = true;
                mvc.moonFeastivalCtrl.reqBGDinnerAnswer(this._dinnerInfo.id, this._idx, id);
            }
        }
        _onRenderList(cell, index) {
            let cfg = sg.dbmgr.get("backgroundActive_active6Answer", cell.dataSource);
            if (cfg) {
                let lblAnswer = cell.getChildByName("lblAnswer");
                let img = cell.getChildByName("img");
                let imgSelect = cell.getChildByName("imgSelect");
                if (lblAnswer) {
                    lblAnswer.text = this.idx2ABC(index + 1) + cfg.answer;
                }
                if (this._isFinish) {
                    let myResult = this._getResultAnser();
                    if (this._rightAnswer == myResult) {
                        img.visible = cell.dataSource == myResult;
                        mgr.icon.drawTexture("ui/slgActivity/img_zt_gou.png", img);
                    }
                    else {
                        img.visible = cell.dataSource == myResult || cell.dataSource == this._rightAnswer;
                        if (cell.dataSource == myResult) {
                            mgr.icon.drawTexture("ui/slgActivity/img_zt_x.png", img);
                        }
                        else if (cell.dataSource == this._rightAnswer) {
                            mgr.icon.drawTexture("ui/slgActivity/img_zt_gou.png", img);
                        }
                    }
                    imgSelect.visible = cell.dataSource == myResult;
                }
                else {
                    if (img) {
                        if (this._isAnser) {
                            img.visible = cell.dataSource == this._myAnswer || cell.dataSource == this._rightAnswer;
                            if (cell.dataSource == this._myAnswer && this._myAnswer == this._rightAnswer || cell.dataSource == this._rightAnswer) {
                                mgr.icon.drawTexture("ui/slgActivity/img_zt_gou.png", img);
                            }
                            else if (img.visible) {
                                mgr.icon.drawTexture("ui/slgActivity/img_zt_x.png", img);
                            }
                        }
                        else {
                            img.visible = false;
                        }
                    }
                    if (imgSelect)
                        imgSelect.visible = this._isAnser && this._myAnswer == cell.dataSource;
                }
            }
        }
        _getResultAnser() {
            for (let i = 0; i < this._result.length; i++) {
                if (this._curIndex == this._result[i][0]) {
                    return this._result[i][1];
                }
            }
        }
        idx2ABC(idx) {
            switch (idx) {
                case 1:
                    {
                        return "A.";
                    }
                case 2:
                    {
                        return "B.";
                    }
                case 3:
                    {
                        return "C.";
                    }
            }
            return "";
        }
        _onClick() {
            if (this._questions && this._questions.length > 0 && this._idx > 0 && this._idx == this._curIndex) {
                let id = this._getCurQuestionID();
                let cfg = sg.dbmgr.get("backgroundActive_active6Question", id);
                if (cfg) {
                    let str = cfg.question;
                    str += "\n";
                    for (let i = 0; i < cfg.answer.length; i++) {
                        let cfgAnswer = sg.dbmgr.get("backgroundActive_active6Answer", cfg.answer[i]);
                        str += this.idx2ABC(i + 1) + cfgAnswer.answer + ";";
                    }
                    sg.uimgr.showUI("pop_chat", mvc.ChatConst.ChannelDefine.WORLD, str);
                }
            }
        }
        _updateBtn() {
            this._updateLeftBtn();
            this._updateRightBtn();
        }
        _updateLeftBtn() {
            this.btnLeft.visible = this._isFinish && this._curIndex != 1;
        }
        _updateRightBtn() {
            this.btnRight.visible = this._isFinish && this._curIndex < this._questions.length;
        }
        _onBtnLeft() {
            this._curIndex--;
            this._updateView();
            this._updateBtn();
        }
        _onBtnRight() {
            this._curIndex++;
            this._updateView();
            this._updateBtn();
        }
    }
    mvc.PopFeastQuestion = PopFeastQuestion;
})(mvc || (mvc = {}));

var mvc;
(function (mvc) {
    class PopFeastRecord extends ui.view.bgActivity6.pop_feastRecordUI {
        initSendMsg() {
        }
        initCtrlEvent() {
            this.listRecord.vScrollBarSkin = null;
            this.listRecord.renderHandler = this.createHandler(this, this._renderListRecord, null, false);
        }
        initModelEvent() {
            this.bindModelEvent(mvc.moonFeastivalModel, mvc.MoonFeastivalConst.EVT.ENDTIME, this.closeSelf);
        }
        onAwake() {
            super.onAwake();
            this.lblContent.text = sg.translate("暂未参加宴会");
        }
        onEnable() {
            super.onEnable();
            this._updateList();
        }
        _updateList() {
            let arr = [];
            let posInfo = this.openParams[0][0];
            posInfo.sort(this._sort);
            let tempJoin = 0;
            let tempQuestion = 0;
            for (let i = 0; i < posInfo.length; i++) {
                tempJoin = 0;
                tempQuestion = 0;
                for (let j = 0; j < posInfo[i].cake_rewards.length; j++) {
                    tempJoin += posInfo[i].cake_rewards[j][1];
                }
                for (let j = 0; j < posInfo[i].question_rewards.length; j++) {
                    tempQuestion += posInfo[i].question_rewards[j][1];
                }
                arr.push({ index: i + 1, data: posInfo[i], tempJoin: tempJoin, tempQuestion: tempQuestion, joinSec: posInfo[i].join_sec });
            }
            this.listRecord.array = arr;
            this.lblContent.visible = !arr.length;
        }
        _sort(a, b) {
            return a.join_sec - b.join_sec;
        }
        _renderListRecord(cell) {
            let data = cell.dataSource;
            cell.initView(data);
        }
    }
    mvc.PopFeastRecord = PopFeastRecord;
})(mvc || (mvc = {}));

