(function (mvc) {
    class PopFeastShare extends ui.view.bgActivity6.pop_shareUI {
        initCtrlEvent() {
            this.btnConfirm.on(Laya.Event.CLICK, this, this._onBtnConfirm);
            this.boxChannel0.on(Laya.Event.CLICK, this, this._onBoxChannel, [0]);
            this.boxChannel1.on(Laya.Event.CLICK, this, this._onBoxChannel, [1]);
            this.boxChannel2.on(Laya.Event.CLICK, this, this._onBoxChannel, [2]);
        }
        onEnable() {
            super.onEnable();
            this._initOpenFlag();
            this._initChannelInfo();
            this._curSel = -1;
            this.imgSel1.visible = this.imgSel2.visible = this.imgSel0.visible = false;
        }
        _onBtnConfirm() {
            if (this._curSel != -1) {
                let type = this.openParams[0];
                let id = this.openParams[1];
                sg.uimgr.closeUI("pop_feastShare");
                if (mvc.chatCtrl.reqSendNotic(58, this._channelInfo[this._curSel].type, [[mvc.roleModel.roleInfo.name], type, id, mvc.moonFeastivalCtrl.type], 4)) {
                    sg.uimgr.showNotice(mgr.UIAssist.$(sg.translate("已成功分享到{1}聊天"), this._channelInfo[this._curSel].title), "green");
                }
            }
            else {
                sg.uimgr.showNotice(sg.translate("请选择频道"));
            }
        }
        _onBoxChannel(selIndex) {
            if (this._curSel != selIndex) {
                if (this._openFlag[selIndex]) {
                    if (this._curSel != -1) {
                        this["imgSel" + this._curSel].visible = false;
                    }
                    this._curSel = selIndex;
                    this["imgSel" + selIndex].visible = true;
                }
                else {
                    sg.uimgr.showNotice(this._openFlagTip[selIndex]);
                }
            }
        }
        _initOpenFlag() {
            this._openFlag = [];
            let myLevel = mvc.roleModel.roleInfo.level;
            let lvToCross = mgr.toolsMgr.getGlobalVoById("chat_level_crosschannel").info;
            let isOpenCross = lvToCross <= myLevel;
            let info = mgr.toolsMgr.getGlobalVoById("chat_level_worldchannel", 1);
            let isOpenWrold = myLevel >= info;
            let isOpenGuide = mvc.roleModel.roleInfo.guildId > 0;
            this._openFlag.push(isOpenCross, isOpenWrold, isOpenGuide);
            this._openFlagTip = [];
            this._pushTipBySysID(mvc.FUNC_ID.CROSS_ARENA);
            this._openFlagTip.push(mgr.UIAssist.$(StringEx.format(sg.translate("达到{1}才能发言")), mgr.toolsMgr.getLevelName(info)));
            this._openFlagTip.push(sg.translate("暂未加入仙盟"));
        }
        _pushTipBySysID(sysID) {
            let cfg = sg.dbmgr.get("funcOpen", sysID);
            this._openFlagTip.push(mgr.UIAssist.$(sg.translate("{1}开启"), cfg.openError));
        }
        _initChannelInfo() {
            if (!this._channelInfo) {
                this._channelInfo = [
                    { type: mvc.ChatConst.ChannelDefine.CROSS, title: sg.translate("跨服") },
                    { type: mvc.ChatConst.ChannelDefine.WORLD, title: sg.translate("世界") },
                    { type: mvc.ChatConst.ChannelDefine.GUILD, title: sg.translate("仙盟") },
                ];
            }
        }
    }
    mvc.PopFeastShare = PopFeastShare;
})(mvc || (mvc = {}));

