var mvc;
(function (mvc) {
    class PopKitchen extends ui.view.bgActivity6.pop_kitchenUI {
        initView() {
            this._model = mvc.moonFeastivalModel;
            this._ctrl = mvc.moonFeastivalCtrl;
        }
        initCtrlEvent() {
            this.btnMake.on(Laya.Event.CLICK, this, this._onBtnMake);
            this.btnMakeBetter.on(Laya.Event.CLICK, this, this._onBtnMakeBetter);
            this.imgIcon3.on(Laya.Event.CLICK, this, this._onImgIcon);
            this.unitType1.on(Laya.Event.CLICK, this, this._onUnitType);
            this.unitType2.on(Laya.Event.CLICK, this, this._onUnitType);
            this.unitType3.on(Laya.Event.CLICK, this, this._onUnitType);
            this.unitType4.on(Laya.Event.CLICK, this, this._onUnitType);
            this.unitType5.on(Laya.Event.CLICK, this, this._onUnitType);
        }
        initModelEvent() {
            this.bindModelEvent(mvc.moonFeastivalModel, mvc.MoonFeastivalConst.EVT.ENDTIME, this.closeSelf);
            this.bindModelEvent(mvc.moonFeastivalModel, mvc.MoonFeastivalConst.EVT.KITCHEN_MAKE, this._playAni);
            this.bindModelEvent(mvc.moonFeastivalModel, mvc.MoonFeastivalConst.EVT.PHP_INFO_UPDATE, this._zeroTimeUpdate);
        }
        onEnable() {
            super.onEnable();
            this._initData();
            this._playModel();
        }
        _onBtnMake() {
            let data = this._curSel.data;
            let canMake = mvc.bagModel.getItemNumById(data.makeData.cost[0][0]) >= data.makeData.cost[0][1];
            if (canMake) {
                this._isDouble = 0;
                this._ctrl.reqBGDinnerMakeCake(this._curSel.data.id, 0);
            }
            else {
                sg.uimgr.showNotice(sg.translate("材料不足"));
                sg.uimgr.showUI("pop_ItemGet");
            }
        }
        _onBtnMakeBetter() {
            let data = this._curSel.data;
            let canMake = mvc.bagModel.getItemNumById(data.makeData.cost[0][0]) >= data.makeData.cost[0][1];
            if (canMake) {
                let dinner = mvc.moonFeastivalModel.feastDinnerInfo;
                let level = dinner.reqData.dinner_level;
                let cfg = sg.dbmgr.get("backgroundActive_active6CookLevel", level);
                let useTime = dinner.reqData.double_time;
                if (cfg.cookNum - useTime > 0) {
                    this._isDouble = 1;
                    this._ctrl.reqBGDinnerMakeCake(this._curSel.data.id, 1);
                }
                else {
                    sg.uimgr.showNotice(sg.translate("精心制作次数不足"));
                }
            }
            else {
                sg.uimgr.showNotice(sg.translate("材料不足"));
                sg.uimgr.showUI("pop_ItemGet");
            }
        }
        _onImgIcon() {
            let id = this._curSel.data.makeData.cost[0][0];
            sg.uimgr.showUI("pop_itemTips", id);
        }
        _onUnitType(e) {
            let target = e.currentTarget;
            if (this._curSel == target) {
                return;
            }
            this._curSel.setSel(false);
            target.setSel(true);
            this._curSel = target;
            this._updateMaterial();
        }
        _initData() {
            if (this._curSel) {
                this._curSel.setSel(false);
            }
            this._curSel = this.unitType1;
            this._updateMaterialData();
            this.unitType1.setSel(true);
            this._updateMaterial();
            this._updateLevel();
        }
        _updateMaterialData() {
            let dinnerInfo = this._model.feastDinnerInfo;
            let index = 0;
            for (let key in dinnerInfo.dealData) {
                this["unitType" + (index + 1)].initView(dinnerInfo.dealData[key]);
                index++;
            }
        }
        _updateMaterial() {
            let data = this._curSel.data;
            mgr.icon.drawTexture(mgr.icon.getIconPath(mgr.toolsMgr.getIconById(data.makeData.cost[0][0])), this.imgIcon3);
            let have = mvc.bagModel.getItemNumById(data.makeData.cost[0][0]);
            this.lblCount3.text = mgr.UIAssist.$("{1}/{2}", have, data.makeData.cost[0][1]);
            if (have >= data.makeData.cost[0][1]) {
                this.lblCount3.color = mgr.toolsMgr.getColor3("green").stringColor;
            }
            else {
                this.lblCount3.color = mgr.toolsMgr.getColor3("red").stringColor;
            }
        }
        _zeroTimeUpdate() {
            this._updateLevel();
        }
        _playAni(data) {
            this._curRewards = data.reward;
            if (this.checkBox.selected) {
                this._updateKitchen();
            }
            else {
                let isDouble = this._isDouble;
                let all_cake_ids = mvc.moonFeastivalModel.feastDinnerInfo.reqData.all_cake_ids;
                let index = all_cake_ids.indexOf(this._curSel.data.id);
                if (index != -1) {
                    this.unitModel.play(this.getNameList()[index + isDouble * all_cake_ids.length]);
                }
            }
        }
        _updateKitchen() {
            sg.uimgr.showUI("pop_getReward", sg.translate("恭喜获得"), this._curRewards);
            this._updateMaterialData();
            this._updateMaterial();
            this._updateLevel();
            this._curSel.setSel(true);
        }
        _updateLevel() {
            let dinner = mvc.moonFeastivalModel.feastDinnerInfo;
            let level = dinner.reqData.dinner_level;
            this.clipLevel.value = level + "";
            let cfg = sg.dbmgr.get("backgroundActive_active6CookLevel", level);
            let useTime = dinner.reqData.double_time;
            let laveTimes = cfg.cookNum - useTime;
            this.lblMakeCount.text = mgr.UIAssist.$("{1}/{2}", laveTimes, cfg.cookNum);
            if (laveTimes <= 0) {
                this.lblMakeCount.color = mgr.toolsMgr.getColor3("red").stringColor;
            }
            if (cfg.needExp) {
                let curExp = dinner.reqData.dinner_exp;
                this.lblExp.text = mgr.UIAssist.$("{1}/{2}", curExp, cfg.needExp);
                this.proIntegral.value = curExp / cfg.needExp;
            }
            else {
                this.lblExp.text = sg.translate("已满级");
                this.proIntegral.value = 1.0;
            }
        }
        _playModel() {
            this.unitModel.changeShowMode(false, 9095);
            this.unitModel.loadedHandle = () => {
                this.unitModel.play("stand");
                this.unitModel.visible = true;
            };
            this.unitModel.setEndHandle("", (isLoop, name) => {
                if (this.getNameList().indexOf(name) != -1) {
                    this.unitModel.play("stand", true);
                }
            });
            this.unitModel.lableHandle = (obj) => {
                if (obj.name == "tan") {
                    this._onAniLabel();
                }
            };
            this.unitModel.loadRole(9095, "PopFeast");
        }
        _onAniLabel() {
            if (this._curRewards) {
                this._updateKitchen();
            }
        }
        getNameList() {
            if (!this._nameList) {
                this._nameList = [
                    "stand1_dh", "stand1_ds", "stand1_ll", "stand1_rs", "stand1_wr",
                    "stand2_dh", "stand2_ds", "stand2_ll", "stand2_rs", "stand2_wr"
                ];
            }
            return this._nameList;
        }
    }
    mvc.PopKitchen = PopKitchen;
})(mvc || (mvc = {}));

var mvc;
(function (mvc) {
    class PopMoonChoose extends ui.view.bgActivity6.pop_moonChooseUI {
        initCtrlEvent() {
            this.btnSure.on(Laya.Event.CLICK, this, this._onBtnSure);
            this.btnCancel.on(Laya.Event.CLICK, this, this._onBtnCancel);
            this.listChoose.vScrollBarSkin = null;
            this.listChoose.renderHandler = this.createHandler(this, this._rederListChoose, null, false);
            this.listSelected.renderHandler = this.createHandler(this, this._rederListSelected, null, false);
        }
        onEnable() {
            super.onEnable();
            this._maxSelected = mvc.moonFeastivalModel.getDinnerCount(1);
            this._updateListSelected();
            this._updateListChoose();
        }
        _updateListSelected() {
            this._selectedCount = 0;
            this._selectedData = mvc.moonFeastivalModel.selectedData;
            let data = mvc.moonFeastivalModel.feastDinnerInfo;
            if (data.reqData.all_cake_ids) {
                if (this._selectedData.length == 0) {
                    for (let i = 0; i < data.reqData.all_cake_ids.length; i++) {
                        this._selectedData.push({ item: null });
                    }
                }
            }
            this._selectedIndex = {};
            for (let i = 0; i < this._selectedData.length; i++) {
                if (this._selectedData[i].item) {
                    this._selectedCount++;
                }
            }
            this.listSelected.array = this._selectedData;
        }
        _updateListChoose() {
            let ids = mvc.moonFeastivalModel.feastDinnerInfo.reqData.all_cake_ids;
            ids.sort(this._sort);
            this._chooseData = [];
            let tempCount = 0;
            let tempCFG;
            let tempItem;
            let selectCount = {};
            this._selectedData = mvc.moonFeastivalModel.selectedData;
            for (let i = 0; i < this._selectedData.length; i++) {
                if (this._selectedData[i].item) {
                    if (!selectCount[this._selectedData[i].item.id]) {
                        selectCount[this._selectedData[i].item.id] = 0;
                    }
                    selectCount[this._selectedData[i].item.id]++;
                }
            }
            for (let i = 0; i < ids.length; i++) {
                tempCFG = sg.dbmgr.get("item_consumeable", ids[i]);
                tempCount = mvc.bagModel.getItemNumById(ids[i]) - (selectCount[ids[i]] ? selectCount[ids[i]] : 0);
                tempItem = new mvc.ItemVo();
                tempItem.id = ids[i];
                tempItem.count = 1;
                this._chooseData.push({ item: tempItem, name: tempCFG.name, quality: tempCFG.quality, count: tempCount });
            }
            this.listChoose.array = this._chooseData;
        }
        _sort(a, b) {
            return a - b;
        }
        _onBtnSure() {
            if (this._selectedCount < 5) {
                sg.uimgr.showNotice(sg.translate("月饼数量不足"));
            }
            else {
                sg.uimgr.closeUI("pop_moonChoose");
                mvc.moonFeastivalModel.selectedData = this._selectedData;
                mvc.moonFeastivalModel.fireEvent(mvc.MoonFeastivalConst.EVT.CHOOSE_FULL);
            }
        }
        _onBtnCancel() {
            this.listSelected.array = [];
            sg.uimgr.closeUI("pop_moonChoose");
        }
        _rederListChoose(cell, idx) {
            let data = cell.dataSource;
            let itemSelected = cell.getChildByName("itemSelected");
            let lblName = cell.getChildByName("lblName");
            let lblNum = cell.getChildByName("lblNum");
            mgr.toolsMgr.setLabelByQua(data.quality, lblName);
            lblName.text = data.name;
            lblNum.text = data.count;
            itemSelected.mouseEnabled = false;
            cell.on(Laya.Event.CLICK, this, this._onListChoose, [cell, idx]);
            itemSelected.initView(data.item);
        }
        _onListChoose(...args) {
            let [cell, idx] = args;
            let data = cell.dataSource;
            if (data) {
                if (this._selectedCount >= this._maxSelected) {
                    return;
                }
                else if (data.count <= 0) {
                    sg.uimgr.showNotice(sg.translate("数量不足"));
                    return;
                }
                let tempItem = this.getItem(idx);
                for (let i = 0; i < this._selectedData.length; i++) {
                    if (!this._selectedData[i].item) {
                        tempItem.id = data.item.id;
                        tempItem.count = 1;
                        this._selectedData[i] = { item: tempItem };
                        this._selectedCount++;
                        break;
                    }
                }
                data.count--;
            }
            this.listSelected.array = this._selectedData;
            this.listChoose.array = this._chooseData;
        }
        _rederListSelected(cell, idx) {
            let data = cell.dataSource;
            let imgAdd = cell.getChildByName("imgAdd");
            let itemSelected = cell.getChildByName("itemSelected");
            itemSelected.mouseEnabled = false;
            cell.on(Laya.Event.CLICK, this, this._selectListSelected, [data]);
            if (data.item) {
                imgAdd.visible = false;
                itemSelected.visible = true;
                itemSelected.initView(data.item);
            }
            else {
                imgAdd.visible = true;
                itemSelected.visible = false;
            }
        }
        _selectListSelected(...args) {
            let [data] = args;
            if (data.item) {
                let chooseData = this._chooseData;
                for (let i = 0; i < chooseData.length; i++) {
                    if (chooseData[i].item.id == data.item.id) {
                        this._selectedCount--;
                        break;
                    }
                }
                for (let i = 0; i < this._chooseData.length; i++) {
                    if (this._chooseData[i].item.id == data.item.id) {
                        this._chooseData[i].count++;
                        break;
                    }
                }
                this.listChoose.array = chooseData;
                data.id = -1;
                data.item = null;
                this.listSelected.array = this._selectedData;
            }
        }
        getItem(idx) {
            if (!this._itemPool) {
                let dinner = mvc.moonFeastivalModel.feastDinnerInfo;
                this._itemPool = [];
                for (let i = 0; i < dinner.reqData.all_cake_ids.length; i++) {
                    this._itemPool.push({ item: new mvc.ItemVo(), use: false });
                }
            }
            return this._itemPool[idx].item;
        }
    }
    mvc.PopMoonChoose = PopMoonChoose;
})(mvc || (mvc = {}));

