(function (mvc) {
    class PopMyFeast extends ui.view.bgActivity6.pop_myFeastUI {
        initView() {
            this._model = mvc.moonFeastivalModel;
            this._ctrl = mvc.moonFeastivalCtrl;
        }
        initCtrlEvent() {
            this.listFeast.renderHandler = this.createHandler(this, this._renderListFeast, null, false);
        }
        initModelEvent() {
            this.bindModelEvent(mvc.moonFeastivalModel, mvc.MoonFeastivalConst.EVT.ENDTIME, this.closeSelf);
            this.bindModelEvent(mvc.moonFeastivalModel, mvc.MoonFeastivalConst.EVT.CHOOSE_FULL, this._updateList);
            this.bindModelEvent(mvc.moonFeastivalModel, mvc.MoonFeastivalConst.EVT.HOLD_DINNER, this._onMsgHoldDinner);
        }
        onEnable() {
            super.onEnable();
            this._model.selectedData = [];
            this._updateList();
        }
        _updateList() {
            let commonDinner = false;
            let extraDinner = true;
            let countCommon = this._model.getDinnerCount(1);
            let countExtra = this._model.getDinnerCount(2);
            let data = this._model.feastDinnerInfo.dealData;
            let totalType = this._model.feastDinnerInfo.reqData.all_cake_ids.length;
            let tempCount = 0;
            for (let key in data) {
                tempCount = mvc.bagModel.getItemNumById(data[key].id);
                if (tempCount < countExtra / totalType) {
                    extraDinner = false;
                }
            }
            let arr = [];
            let commonItems = [];
            if (!this._model.selectedData.length) {
                commonDinner = false;
                for (let key in data) {
                    commonItems.push({ item: null });
                }
            }
            else {
                commonItems = this._model.selectedData;
                commonDinner = true;
            }
            arr.push({
                type: 1, title: this._model.getDinnerTitle(1),
                count: countCommon, canMake: commonDinner, items: commonItems
            });
            let extraItems = [];
            for (let key in data) {
                extraItems.push({ item: mvc.ItemVo.createItemVo([[+key, 1]]) });
            }
            arr.push({
                type: 2, title: this._model.getDinnerTitle(2),
                count: countExtra, canMake: extraDinner, items: extraItems
            });
            this.listFeast.array = arr;
        }
        _renderListFeast(cell, index) {
            let data = cell.dataSource;
            cell.initView(data);
        }
        _onMsgHoldDinner(data) {
            mvc.moonFeastivalModel.selectedData = [];
            sg.uimgr.closeUI("pop_myFeast");
            sg.uimgr.showUI("pop_feast", data.info);
        }
    }
    mvc.PopMyFeast = PopMyFeast;
})(mvc || (mvc = {}));

