var mvc;
(function (mvc) {
    class SysFeastEntrance extends ui.view.bgActivity6.sys_feastEntranceUI {
        initView() {
            this._model = mvc.moonFeastivalModel;
            this._ctrl = mvc.moonFeastivalCtrl;
        }
        initSendMsg() {
            this._ctrl.reqBGDinnerInfo(1);
            this._ctrl.reqBGDinnerFinishedPanel();
        }
        initCtrlEvent() {
            this.imgRed.id = mvc.REDOT_ID.BG_ACT_MOON_FEAST_KITCHEN;
            this.redMyFeast.id = mvc.REDOT_ID.BG_ACT_MOON_FEAST_MYSELF;
            this.btnKichen.on(Laya.Event.CLICK, this, this._onBtnKichen);
            this.btnMyself.on(Laya.Event.CLICK, this, this._onBtnMyself);
            this.btnOther.on(Laya.Event.CLICK, this, this._onBtnOther);
            this.btnGet.on(Laya.Event.CLICK, this, this._onBtnGet);
            this.btnShop.on(Laya.Event.CLICK, this, this._onBtnShop);
            this.btnHoldRecord.on(Laya.Event.CLICK, this, this._onBtnHoldRecord);
            this.btnJoinRecord.on(Laya.Event.CLICK, this, this._onBtnJoinRecord);
            this.btnHelp.on(Laya.Event.CLICK, this, this._onBtnHelp);
        }
        initModelEvent() {
            this.bindModelEvent(mvc.moonFeastivalModel, mvc.MoonFeastivalConst.EVT.ENDTIME, this.closeSelf);
            this.bindModelEvent(mvc.moonFeastivalModel, mvc.MoonFeastivalConst.EVT.HOLD_DINNER, this._onMsgHoldDinner);
            this.bindModelEvent(mvc.moonFeastivalModel, mvc.MoonFeastivalConst.EVT.SINGLE_INFO, this._onMsgSingleInfo);
            this.bindModelEvent(mvc.moonFeastivalModel, mvc.MoonFeastivalConst.EVT.DINNER_INFO, this._updatetBarrage);
            this.bindModelEvent(mvc.moonFeastivalModel, mvc.MoonFeastivalConst.EVT.FINISHED_PANEL, this._updateFinished);
            this.bindModelEvent(mvc.moonFeastivalModel, mvc.MoonFeastivalConst.EVT.MY_DINNER_END, this._updateMyDinnerEnd);
        }
        onEnable() {
            super.onEnable();
            this._isOpen = true;
            this._listCross = this._listLocal = null;
            this._showBattage = true;
            this._playModel();
            this._updateFeast();
            this._unitBarrage = mvc.UnitBarrage.getIns(this.boxLog, "SysFeastEntrance");
            this.boxLog.visible = false;
        }
        onDisable() {
            super.onDisable();
            this.timer.clear(this, this._loopTime);
            if (this._unitBarrage) {
                this._unitBarrage.stopAni();
            }
        }
        _initPopBarrage(loglist) {
            if (this._unitBarrage) {
                this._unitBarrage.setParams(loglist, "SysFeastEntrance", this.parmaDataInfo.bind(this), 1500, 8000, 1, 20);
                this._unitBarrage.starAni();
            }
        }
        parmaDataInfo(data) {
            let str = "";
            let cfg;
            let v1 = `[S${data.head.svr_id}]`;
            switch (data.type) {
                case 1:
                    {
                        cfg = sg.dbmgr.get("chat_notice", 62);
                        if (cfg)
                            str = mvc.mainModel.analyzeNotic(cfg.value, [[`${v1}${data.head.name}`], +data.dinnerType]);
                    }
                    break;
                case 2:
                    {
                        let v2 = `[S${data.otherHead.svr_id}]`;
                        cfg = sg.dbmgr.get("chat_notice", 63);
                        if (cfg)
                            str = mvc.mainModel.analyzeNotic(cfg.value, [[`${v1}${data.head.name}`], [`${v2}${data.otherHead.name}`], +data.dinnerType]);
                    }
                    break;
            }
            return str;
        }
        _playModel() {
            this.unitModel.changeShowMode(false, "9094");
            this.unitModel.loadedHandle = () => {
                this.unitModel.visible = true;
                this.unitModel.play("stand");
            };
            this.unitModel.loadRole("9094", "SysFeastEntrance");
        }
        _updateFeast() {
            let dinner = mvc.moonFeastivalModel.feastDinnerInfo;
            this._endTime = dinner.reqData.dinner_end_sec;
            let curTime = sg.time.getSecondTime();
            let laveTime = this._endTime - curTime;
            if (laveTime > 0) {
                this._isOpen = false;
                mvc.moonFeastivalCtrl.reqBGDinnerSingleInfo(dinner.reqData.recent_only_id);
                this._loopTime();
                this.timer.loop(1000, this, this._loopTime);
                this.boxMyself.visible = true;
            }
            else {
                this.boxMyself.visible = false;
                this.timer.clear(this, this._loopTime);
            }
            if (!dinner.reqData.first_enter) {
                sg.uimgr.showUI("pop_helpTips");
            }
        }
        _loopTime() {
            let curTime = sg.time.getSecondTime();
            let laveTime = this._endTime - curTime - 1;
            if (laveTime > 0) {
                this.lblTime.text = sg.time.formatTimeStrT("F2", laveTime);
            }
            else {
                this.boxMyself.visible = false;
                this.timer.clear(this, this._loopTime);
            }
        }
        _onMsgHoldDinner() {
            this._updateFeast();
        }
        _onMsgSingleInfo(data) {
            if (!this._isOpen) {
                this._isOpen = true;
                this._loopTime();
                this.timer.loop(1000, this, this._loopTime);
                this.boxMyself.visible = true;
            }
            else {
                sg.uimgr.showUI("pop_feast", data.info);
            }
            this.lblName.text = mvc.moonFeastivalModel.getDinnerTitle(data.info.dinner_type);
            this.lblCount.text = mgr.UIAssist.$("{1}/{2}", data.info.pos_infos.length, mvc.moonFeastivalModel.getDinnerCount(data.info.dinner_type));
        }
        _onBtnKichen() {
            sg.uimgr.showUI("pop_kitchen");
        }
        _onBtnMyself() {
            let dinner = mvc.moonFeastivalModel.feastDinnerInfo;
            if (dinner.reqData.dinner_end_sec > sg.time.getSecondTime()) {
                mvc.moonFeastivalCtrl.reqBGDinnerSingleInfo(dinner.reqData.recent_only_id);
            }
            else {
                let activeData = mvc.activityModel.openActivityVo.get(mvc.FUNC_ID.BG_ACT_FEAST);
                let endTime = activeData.end_time;
                if (endTime - sg.time.getSecondTime() < 7200) {
                    sg.uimgr.showNotice(sg.translate("活动结束前2小时内无法再开启宴会"));
                }
                else {
                    sg.uimgr.showUI("pop_myFeast");
                }
            }
        }
        _updateTotalCount() {
            this.clipLuck.value = this._localNum + this._crossNum + "";
        }
        _updatetBarrage(data) {
            let temp = new Proto.bg_dinner_info_reply();
            temp.type = data.type;
            temp.is_world = data.is_world;
            temp.infos = data.infos;
            if (this._showBattage) {
                if (temp.is_world == 1) {
                    this._listLocal = temp.infos;
                    this._ctrl.reqBGDinnerInfo(2);
                }
                else {
                    this._listCross = temp.infos;
                    this._showBattage = false;
                    this._checkPlayBarrage();
                }
            }
            if (temp.is_world == 1) {
                this._localNum = temp.infos.length;
            }
            else {
                this._crossNum = temp.infos.length;
            }
            this._updateTotalCount();
        }
        _checkPlayBarrage() {
            let localInfo = this._listLocal;
            let crossInfo = this._listCross;
            let maxSize = 10;
            let arrBarrageType1 = [];
            let arrBarrageType2 = [];
            for (let i = 0; i < crossInfo.length; i++) {
                arrBarrageType1.push({ type: 1, head: crossInfo[i].head, dinnerType: crossInfo[i].dinner_type });
                for (let j = 0; j < crossInfo[i].pos_infos.length; j++) {
                    arrBarrageType2.push({ type: 2, head: crossInfo[i].head, otherHead: crossInfo[i].pos_infos[j].head, dinnerType: crossInfo[i].dinner_type });
                }
            }
            for (let i = 0; i < localInfo.length; i++) {
                arrBarrageType1.push({ type: 1, head: localInfo[i].head, dinnerType: localInfo[i].dinner_type });
                for (let j = 0; j < localInfo[i].pos_infos.length; j++) {
                    arrBarrageType2.push({ type: 2, head: localInfo[i].head, otherHead: localInfo[i].pos_infos[j].head, dinnerType: localInfo[i].dinner_type });
                }
            }
            arrBarrageType1.sort(this._sortRandom);
            arrBarrageType2.sort(this._sortRandom);
            arrBarrageType1.length = arrBarrageType1.length > maxSize ? maxSize : arrBarrageType1.length;
            arrBarrageType2.length = arrBarrageType2.length > maxSize ? maxSize : arrBarrageType2.length;
            let endDatat = arrBarrageType1.concat(arrBarrageType2);
            if (endDatat) {
                this.boxLog.visible = true;
                this._initPopBarrage(endDatat);
            }
        }
        _sortRandom() {
            return Math.random() - 0.5;
        }
        _updateFinished(data) {
            if (data.info && data.info.id) {
                sg.uimgr.showUI("pop_feastResult", data.info, data.reward, data.return);
            }
        }
        _updateMyDinnerEnd() {
            this._ctrl.reqBGDinnerFinishedPanel();
        }
        _onBtnOther() {
            sg.uimgr.showUI("pop_otherFeast");
        }
        _onBtnGet() {
            sg.uimgr.showUI("pop_ItemGet");
        }
        _onBtnShop() {
            sg.uimgr.showUI("pop_bgStoreAutumn", mvc.FUNC_ID.BG_ACT_STORE_FIVE);
        }
        _onBtnHoldRecord() {
            sg.uimgr.showUI("pop_feastHistory");
        }
        _onBtnJoinRecord() {
            sg.uimgr.showUI("pop_myRecord");
        }
        _onBtnHelp() {
            sg.uimgr.showUI("pop_helpTips");
        }
    }
    mvc.SysFeastEntrance = SysFeastEntrance;
})(mvc || (mvc = {}));

