(function (mvc) {
    class UnitMyFeastItem extends ui.view.bgActivity6.unit_myFeastItemUI {
        initView(...args) {
            this.data = args[0];
            this.lblCount.text = mgr.UIAssist.$(sg.translate("{1}席位"), this.data.count);
            this.btnMake.gray = !this.data.canMake;
            this.btnMake.mouseEnabled = this.data.canMake;
            if (this.data.type == 1) {
                this.listRewardExtra.visible = false;
                this.listRewardCommon.visible = true;
                this.listRewardCommon.array = this.data.items;
                this.redMyFeast.visible = false;
                mgr.icon.drawTexture("ui_langs/cn/ui/bgActivity6/img_zq_ad01.png", this.imgBG);
            }
            else {
                this.listRewardExtra.visible = true;
                this.listRewardCommon.visible = false;
                this.listRewardExtra.array = this.data.items;
                this.redMyFeast.visible = this.data.canMake;
                mgr.icon.drawTexture("ui_langs/cn/ui/bgActivity6/img_zq_ad02.png", this.imgBG);
            }
        }
        onEnable() {
            super.onEnable();
            this.listRewardExtra.hScrollBarSkin = null;
            this.listRewardExtra.renderHandler = this.createHandler(this, this._renderListExtra, null, false);
            this.listRewardCommon.renderHandler = this.createHandler(this, this._renderRewardList, null, false);
            this.listRewardCommon.on(Laya.Event.CLICK, this, this._mouseRewardList);
            this.btnMake.on(Laya.Event.CLICK, this, this._onBtnMake);
        }
        _renderListExtra(cell) {
            let item = cell.getChildByName("unitExtraItem");
            let lblNum = cell.getChildByName("lblNum");
            let data = cell.dataSource;
            lblNum.text = mgr.UIAssist.$("{1}/{2}", mvc.bagModel.getItemNumById(data.item.id), 3);
            item.initView(data.item);
        }
        _renderRewardList(cell, idx) {
            let data = cell.dataSource;
            let imgAdd = cell.getChildByName("imgAdd");
            let item = cell.getChildByName("item");
            item.mouseEnabled = false;
            if (data.item) {
                imgAdd.visible = false;
                item.visible = true;
                item.initView(data.item);
            }
            else {
                imgAdd.visible = true;
                item.visible = false;
            }
        }
        _mouseRewardList() {
            sg.uimgr.showUI("pop_moonChoose");
        }
        _onBtnMake() {
            let endTime = mvc.moonFeastivalModel.feastDinnerInfo.reqData.dinner_end_sec;
            let curTime = sg.time.getSecondTime();
            if (curTime > endTime) {
                let activeData = mvc.activityModel.openActivityVo.get(mvc.FUNC_ID.BG_ACT_FEAST);
                let activeEndTime = activeData.end_time;
                if (activeEndTime - sg.time.getSecondTime() < 7200) {
                    sg.uimgr.showNotice(sg.translate("活动结束前2小时内无法再开启宴会"));
                }
                else {
                    let tempCount = 0;
                    if (this.data.type == 1) {
                        tempCount = 1;
                    }
                    else {
                        tempCount = 3;
                    }
                    let items = this.data.items;
                    let arr = [];
                    for (let i = 0; i < items.length; i++) {
                        arr.push([items[i].item.id, tempCount]);
                    }
                    let msg = sg.translate("花好月圆，共庆中秋！");
                    mvc.moonFeastivalCtrl.reqBGHoldDinner(this.data.type, arr, msg);
                }
            }
            else {
                sg.uimgr.showNotice(sg.translate("当前有正在举办的宴会"));
            }
        }
    }
    mvc.UnitMyFeastItem = UnitMyFeastItem;
})(mvc || (mvc = {}));

