var mvc;
(function (mvc) {
    class SwordGameVo extends sg.VoBase {
        constructor() {
            super();
        }
        updateData(data) {
            this.level = data.level;
            this.perfect = data.perfect;
            this.received = data.received;
            this.atlasCanActive = data.atlas_can_active;
            this.atlasActived = data.atlas_active;
            this.skin = data.skin;
            let nc = sg.varmgr.getUserVar("sword_game_new_chatper");
            if (nc) {
                this.newChatper = nc;
            }
            else {
                this.newChatper = [];
            }
            this._updateChapterInfo();
        }
        gameOver(data) {
            if (data.is_pass && data.level > this.level) {
                this.level = data.level;
                let old = this.curChatper;
                this._updateChapterInfo();
                if (old != this.curChatper) {
                    this.newChatper.push(this.curChatper);
                    sg.varmgr.setUserVar("sword_game_new_chatper", this.newChatper);
                    mgr.redotMgr.check(mvc.REDOT_ID.SWORD_GAME_NEW_CHAPTER);
                }
            }
            if (data.is_perfect && this.perfect.indexOf(data.level) == -1) {
                this.perfect.push(data.level);
            }
            this.atlasCanActive = data.atlas_can_active;
        }
        activeAtlas(data) {
            let idx = this.atlasCanActive.indexOf(data.id);
            if (idx >= 0) {
                this.atlasCanActive.splice(idx, 1);
                this.atlasActived.push(data.id);
            }
        }
        _updateChapterInfo() {
            let chapter;
            let lv = this.level;
            let cfgs = sg.dbmgr.getDB("swordGame_levelSet");
            for (let key in cfgs) {
                let cfg = cfgs[key];
                chapter = cfg.chapter;
                if (cfg.id > lv)
                    break;
            }
            this.curChatper = chapter;
        }
    }
    mvc.SwordGameVo = SwordGameVo;
})(mvc || (mvc = {}));

var mvc;
(function (mvc) {
    let TYPE = mvc.MiniGameConst.type;
    class MiniGameModel extends sg.ModelBase {
        constructor() {
            super(...arguments);
            this._vos = [];
        }
        initModel() {
            this._resultMap = new Map();
            this.swordVo = new mvc.SwordGameVo();
            this.beatVo = new mvc.BeatGameVo();
        }
        registerEvents() {
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.SWORD_GAME_NEW_CHAPTER, this.checkSwordRedNew, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.SWORD_GAME_ATLAS, this.checkSwordRedAtlas, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.SWORD_GAME_BATTLE, this.checkSwordRedBattle, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.SWORD_GAME_REWARD, this.checkSwordRedReward, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.BEAT_GAME_ATLAS_BUFF, this.checkBeatRedAtlasBuff, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.BEAT_GAME_ATLAS_WEAPON, this.checkBeatRedAtlasWeapon, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.BEAT_GAME_NEW_LEVEL, this.checkBeatRedNew, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.BEAT_GAME_LEVEL_UP, this.checkBeatRedLvUp, this);
            this.bindEvent(mvc.mainModel, mvc.MainConst.EVT.ZERO_UPDATE, this._onZeroTime);
        }
        checkSwordRedAtlas() {
            for (let id of this.swordVo.atlasCanActive) {
                let cfg = sg.dbmgr.get("swordGame_swordAtlas", id);
                if (cfg.type == 2) {
                    return 1;
                }
            }
            return 0;
        }
        checkSwordRedNew() {
            return this.swordVo.newChatper.length;
        }
        checkSwordRedReward() {
            let cfgs = sg.dbmgr.getDB("swordGame_levelReward");
            let vo = mvc.miniGameModel.swordVo;
            let cur = vo.received;
            let next;
            for (let key in cfgs) {
                let cfg = cfgs[key];
                if (cfg.id > cur) {
                    next = cfg;
                }
            }
            if (!next)
                return 0;
            let isPass = next.level <= vo.level;
            let canGet = isPass && next.id > vo.received;
            return canGet ? 1 : 0;
        }
        checkSwordRedBattle() {
            let next = mvc.miniGameModel.swordVo.level + 1;
            let cfg = sg.dbmgr.get("swordGame_levelSet", next);
            if (!cfg) {
                return 0;
            }
            let vo = mvc.miniGameModel.swordVo;
            let need = cfg.openCondition[0][1];
            let cur = mvc.pushStoryModel.passId;
            let time = mvc.miniGameModel.checkLevelOpen(cfg.timeCondition);
            if (cur >= need && time <= 0) {
                return 1;
            }
            return 0;
        }
        checkBeatRedAtlasWeapon() {
            for (let id of this.beatVo.atlasCanActive) {
                let cfg = sg.dbmgr.get("beatGame_weaponAtlas", id);
                if (cfg.type == 2) {
                    return 1;
                }
            }
            return 0;
        }
        checkBeatRedAtlasBuff() {
            for (let id of this.beatVo.atlasCanActive) {
                let cfg = sg.dbmgr.get("beatGame_weaponAtlas", id);
                if (cfg.type == 1) {
                    return 1;
                }
            }
            return 0;
        }
        checkBeatRedNew() {
            let cfgs = sg.dbmgr.getDB("beatGame_barrierSet");
            for (let key in cfgs) {
                let cfg = cfgs[key];
                let isLock = this.checkIsLock(cfg);
                if (!isLock) {
                    if (cfg.id == this.beatVo.level + 1) {
                        return 1;
                    }
                    else {
                        let nextCfg = sg.dbmgr.get("beatGame_barrierSet", cfg.id + 1);
                        if (nextCfg) {
                            let nextIsLock = mvc.miniGameModel.checkIsLock(nextCfg);
                            if (nextIsLock) {
                                if (this.beatVo.getSweepNum() > 0)
                                    return 1;
                            }
                        }
                        else {
                            if (this.beatVo.getSweepNum() > 0)
                                return 1;
                        }
                    }
                }
            }
            return 0;
        }
        get vos() {
            let now = sg.time.getSecondTime();
            let end = [];
            for (let vo of this._vos) {
                if (vo.endTime <= now) {
                    end.push(vo);
                }
            }
            for (let e of end) {
                this._vos.splice(this._vos.indexOf(e), 1);
            }
            return this._vos;
        }
        updateInfo(data) {
            this._vos.length = 0;
            for (let d of data.inner_game_infos) {
                let vo = new mvc.MiniGameVo();
                vo.updateData(d);
                this._vos.push(vo);
            }
            this.fireEvent(mvc.MiniGameConst.EVT.UPDATE);
        }
        getReward(data) {
            let type;
            for (let [idx, vo] of this._vos.entries()) {
                if (vo.onlyId == data.only_id) {
                    this._vos.splice(idx, 1);
                    type = vo.type;
                    break;
                }
            }
            this.fireEvent(mvc.MiniGameConst.EVT.UPDATE);
            let uiName;
            let isSucc = true;
            let rst = this._resultMap.get(data.only_id);
            switch (type) {
                case mvc.MiniGameConst.type.FISH:
                    uiName = "sys_miniGameFish";
                    break;
                case mvc.MiniGameConst.type.BARRIER:
                    uiName = "sys_miniGameBarrier";
                    if (rst) {
                        let cfg = sg.dbmgr.get("innerGame_barrierSet", rst[0]);
                        isSucc = !cfg.time;
                    }
                    break;
                case mvc.MiniGameConst.type.BEAT:
                    uiName = "sys_miniGameBeat";
                    isSucc = rst[0] == 1;
                    break;
                default:
                    sg.loge("预想外的小游戏类型: " + type);
                    break;
            }
            sg.uimgr.showUI("pop_getReward", sg.translate("结算奖励"), data.reward, undefined, undefined, Laya.Handler.create(this, () => {
                if (uiName) {
                    sg.uimgr.closeUI(uiName);
                }
                sg.uimgr.showUI("sys_treasure");
            }), isSucc ? "gxhd" : "sb");
        }
        newGame(data) {
            let vo = new mvc.MiniGameVo();
            vo.updateData(data);
            this._vos.push(vo);
            this.fireEvent(mvc.MiniGameConst.EVT.UPDATE);
        }
        saveRst(id, rst) {
            this._resultMap.set(id, rst);
        }
        updateSwordGameInfo(data) {
            this.swordVo.updateData(data);
            mgr.redotMgr.check(mvc.REDOT_ID.SWORD_GAME_NEW_CHAPTER);
            mgr.redotMgr.check(mvc.REDOT_ID.SWORD_GAME_ATLAS);
            mgr.redotMgr.check(mvc.REDOT_ID.SWORD_GAME_REWARD);
            mgr.redotMgr.check(mvc.REDOT_ID.SWORD_GAME_BATTLE);
        }
        swordGameOver(data) {
            this.swordVo.gameOver(data);
            let str = "";
            let title;
            let str2;
            if (data.is_perfect) {
                if (data.reward && data.reward.length > 0) {
                    str = sg.translate("完美通关");
                }
                else {
                    str2 = sg.translate("您已完美通关重复挑战不能获得奖励");
                }
            }
            else if (data.is_pass) {
                if (data.reward && data.reward.length > 0) {
                    str = sg.translate("成功通关");
                }
                else {
                    str2 = sg.translate("您已通关重复挑战不能获得通关奖励");
                }
            }
            else {
                str2 = sg.translate("游戏结束");
                title = "sb";
            }
            sg.uimgr.closeUI("sys_miniGameSword");
            sg.uimgr.showUI("pop_getReward", str, data.reward, undefined, str2, undefined, title);
            this.fireEvent(mvc.MiniGameConst.EVT.UPDATE_SWORD);
            mgr.redotMgr.check(mvc.REDOT_ID.SWORD_GAME_ATLAS);
            mgr.redotMgr.check(mvc.REDOT_ID.SWORD_GAME_REWARD);
            mgr.redotMgr.check(mvc.REDOT_ID.SWORD_GAME_BATTLE);
        }
        activeAtlas(data) {
            this.swordVo.activeAtlas(data);
            this.fireEvent(mvc.MiniGameConst.EVT.UPDATE_SWORD);
            let cfg = sg.dbmgr.get("swordGame_swordAtlas", data.id);
            if (cfg.type == 2) {
                sg.uimgr.showNotice(sg.translate("激活成功"), "green");
            }
            mgr.redotMgr.check(mvc.REDOT_ID.SWORD_GAME_ATLAS);
        }
        useSkin(data) {
            this.swordVo.skin = data.id;
            this.fireEvent(mvc.MiniGameConst.EVT.UPDATE_SWORD);
        }
        getChapterReward(data) {
            this.swordVo.received = data.id;
            sg.uimgr.showUI("pop_getReward", sg.translate("领取成功"), data.reward);
            this.fireEvent(mvc.MiniGameConst.EVT.GET_SWORD_BOX_REWARD);
            mgr.redotMgr.check(mvc.REDOT_ID.SWORD_GAME_REWARD);
        }
        viewNewChapter(chapter) {
            let idx = this.swordVo.newChatper.indexOf(chapter);
            if (idx != -1) {
                this.swordVo.newChatper.splice(idx, 1);
                sg.varmgr.setUserVar("sword_game_new_chatper", this.swordVo.newChatper);
                mgr.redotMgr.check(mvc.REDOT_ID.SWORD_GAME_NEW_CHAPTER);
            }
        }
        getSwordGameCondStr(cond) {
            let num = cond[1];
            switch (cond[0]) {
                case "boss":
                    return StringEx.format(sg.translate("击败${num}个怪物"), {"num":num});
                case "level":
                    let cfg = sg.dbmgr.get("swordGame_barrierLevelUp", num);
                    let name = cfg.level;
                    return StringEx.format(sg.translate("游戏内境界达到${name}"), {"name":name});
                default:
                    sg.loge("不支持的类型" + cond[0]);
                    return "";
            }
        }
        checkLevelOpen(time) {
            if (!this._tempDate) {
                this._tempDate = new Date();
            }
            let t = time.split("/");
            let date = this._tempDate;
            date.setFullYear(Number(t[0]), Number(t[1]) - 1, Number(t[2]));
            date.setHours(0, 0, 0, 0);
            let openT = date.getTime() - sg.time.getUtcOff();
            return Math.ceil((openT - sg.time.getTime()) / 1000);
        }
        checkIsLock(cfg) {
            let isLock = false;
            let time = this.checkLevelOpen(cfg.timeCondition);
            if (cfg.id <= this.beatVo.level + 1 && time <= 0) {
                isLock = false;
            }
            else {
                isLock = true;
            }
            return isLock;
        }
        getChapterLastLv(chapter) {
            if (!this._lastLvMap) {
                let map = this._lastLvMap = {};
                let cfgs = sg.dbmgr.getDB("swordGame_levelSet");
                for (let key in cfgs) {
                    let cfg = cfgs[key];
                    map[cfg.chapter] = cfg.id;
                }
            }
            return this._lastLvMap[chapter];
        }
        _onZeroTime() {
            mgr.redotMgr.check(mvc.REDOT_ID.SWORD_GAME_BATTLE);
            mvc.miniGameCtrl.reqBeatGameInfo();
        }
        updateBeatGameInfo(data) {
            this.beatVo.updateData(data);
            mgr.redotMgr.check(mvc.REDOT_ID.BEAT_GAME_ATLAS_BUFF);
            mgr.redotMgr.check(mvc.REDOT_ID.BEAT_GAME_ATLAS_WEAPON);
            mgr.redotMgr.check(mvc.REDOT_ID.BEAT_GAME_NEW_LEVEL);
            mgr.redotMgr.check(mvc.REDOT_ID.BEAT_GAME_LEVEL_UP);
        }
        beatGameOver(data) {
            this.beatVo.gameOver(data);
            let str = "";
            let title;
            let str2;
            if (data.is_pass) {
                if (data.reward && data.reward.length > 0) {
                    str = sg.translate("成功通关");
                }
                else {
                    str2 = sg.translate("您已通关重复挑战不能获得通关奖励");
                }
            }
            else {
                str2 = sg.translate("未击败异兽之王，请再接再厉~");
                title = "sb";
            }
            sg.uimgr.closeUI("sys_miniGameBeat");
            sg.uimgr.showUI("pop_getReward", str, data.reward, undefined, str2, undefined, title);
            this.fireEvent(mvc.MiniGameConst.EVT.UPDATE_BEAT);
            mgr.redotMgr.check(mvc.REDOT_ID.BEAT_GAME_ATLAS_BUFF);
            mgr.redotMgr.check(mvc.REDOT_ID.BEAT_GAME_ATLAS_WEAPON);
            mgr.redotMgr.check(mvc.REDOT_ID.BEAT_GAME_NEW_LEVEL);
            mgr.redotMgr.check(mvc.REDOT_ID.BEAT_GAME_LEVEL_UP);
        }
        beatActiveAtlas(data) {
            this.beatVo.activeAtlas(data);
            this.fireEvent(mvc.MiniGameConst.EVT.UPDATE_BEAT);
            let cfg = sg.dbmgr.get("beatGame_weaponAtlas", data.id);
            if (cfg.type == 2) {
                sg.uimgr.showNotice(sg.translate("激活成功"), "green");
            }
            mgr.redotMgr.check(mvc.REDOT_ID.BEAT_GAME_ATLAS_BUFF);
            mgr.redotMgr.check(mvc.REDOT_ID.BEAT_GAME_ATLAS_WEAPON);
        }
        beatUseSkin(data) {
            this.beatVo.skin = data.id;
            this.fireEvent(mvc.MiniGameConst.EVT.UPDATE_BEAT);
        }
        viewBeatNewLevel(level) {
            let idx = this.beatVo.newLevel.indexOf(level);
            if (idx != -1) {
                this.beatVo.newLevel.splice(idx, 1);
                sg.varmgr.setUserVar("beat_game_new_level", this.beatVo.newLevel);
                mgr.redotMgr.check(mvc.REDOT_ID.BEAT_GAME_NEW_LEVEL);
                this.fireEvent(mvc.MiniGameConst.EVT.UPDATE_BEAT);
            }
        }
        beatSweep(data) {
            sg.uimgr.showUI("pop_getReward", sg.translate("扫荡奖励"), data.reward);
            this.beatVo.sweepNum = data.sweep_num;
            sg.uimgr.closeUI("sys_miniGameBeat");
            this.fireEvent(mvc.MiniGameConst.EVT.UPDATE_SWEEP_NUM);
            this.fireEvent(mvc.MiniGameConst.EVT.UPDATE_BEAT);
            mgr.redotMgr.check(mvc.REDOT_ID.BEAT_GAME_ATLAS_BUFF);
            mgr.redotMgr.check(mvc.REDOT_ID.BEAT_GAME_ATLAS_WEAPON);
            mgr.redotMgr.check(mvc.REDOT_ID.BEAT_GAME_LEVEL_UP);
            mgr.redotMgr.check(mvc.REDOT_ID.BEAT_GAME_NEW_LEVEL);
        }
        beatUpgrade(data) {
            this.beatVo.typeInfos = data.type_infos;
            this.fireEvent(mvc.MiniGameConst.EVT.UPDATE_UPGRADE_VIEW);
            mgr.redotMgr.check(mvc.REDOT_ID.BEAT_GAME_LEVEL_UP);
        }
        checkBeatRedLvUp() {
            let cfgs = sg.dbmgr.getDB("beatGame_roleAttributeList", true);
            for (let cfg of cfgs) {
                let lv = this.beatVo.getTypeLv(cfg.type);
                let attrCfg = sg.dbmgr.getArray("beatGame_roleAttribute", { type: cfg.type, level: lv })[0];
                if (attrCfg.consume) {
                    if (mgr.toolsMgr.checkConsume(attrCfg.consume)) {
                        return 1;
                    }
                }
            }
            return 0;
        }
    }
    mvc.MiniGameModel = MiniGameModel;
})(mvc || (mvc = {}));

