(function (mvc) {
    class PopMiniGameBeatChoose extends ui.view.beatGame.pop_itemChooseUI {
        initView(type, choose, haveWeapon, haveBuff, callback) {
            this._type = type;
            this._choose = choose;
            this._haveWeapon = haveWeapon;
            this._haveBuff = haveBuff;
            this._callback = callback;
        }
        initSendMsg() {
        }
        initModelEvent() {
        }
        initCtrlEvent() {
            this.listRelic.renderHandler = this.createHandler(this, this._listWeaponRender, undefined, false);
            this.listRelic.mouseHandler = this.createHandler(this, this._onListWeaponClick, undefined, false);
            this.btnCancel.on(Laya.Event.CLICK, this, this._onBtnCancel);
        }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            this._isSelect = false;
            let url = this._type == 1 ? "ui_langs/cn/ui/innerGame/img_title_xzmb.png" : "ui_langs/cn/ui/innerGame/img_title_xzxq.png";
            mgr.icon.drawTexture(url, this.imgTitle);
            this.listRelic.array = this._choose;
            let arr = [];
            for (let b of this._haveBuff) {
                arr.push({ type: 1, id: b });
            }
            while (arr.length < 5) {
                arr.push(null);
            }
            this.listBuff.array = arr;
            arr = [];
            for (let w of this._haveWeapon) {
                arr.push({ type: 2, id: w });
            }
            while (arr.length < 5) {
                arr.push(null);
            }
            this.listWeapon.array = arr;
        }
        onDisable() {
            this.listWeapon.array = null;
            super.onDisable();
        }
        _listWeaponRender(cell) {
            let data = cell.dataSource;
            if (!data)
                return;
            let cfgName = this._type == 1 ? "beatGame_treasure" : "beatGame_weapon";
            let cfg = sg.dbmgr.get(cfgName, data.id);
            let acfg = sg.dbmgr.get("beatGame_weaponAtlas", cfg.type);
            let imgIcon = cell.getChildByName("imgIcon");
            let lblName = cell.getChildByName("lblName");
            let lblDesc = cell.getChildByName("lblDesc");
            let imgLvUp = cell.getChildByName("imgLvUp");
            let lblLvUp = cell.getChildByName("lblLvUp");
            let url = mgr.icon.getIconPath(acfg.icon);
            mgr.icon.drawTexture(url, imgIcon);
            lblName.text = cfg.name;
            mgr.toolsMgr.setLabelByQua(acfg.quality, lblName);
            lblDesc.text = cfg.desc;
            if (data.isMax) {
                mgr.icon.drawTexture("ui/innerGame/img_hmhj_biaoqian  .png", imgLvUp);
                imgLvUp.gray = true;
                lblLvUp.text = sg.translate("已满级");
            }
            else if (data.isNew) {
                mgr.icon.drawTexture("ui/innerGame/img_hmhj_biaoqian02.png", imgLvUp);
                imgLvUp.gray = false;
                if (this._type == 1) {
                    lblLvUp.text = sg.translate("新秘宝");
                }
                else {
                    lblLvUp.text = sg.translate("新仙器");
                }
            }
            else {
                mgr.icon.drawTexture("ui/innerGame/img_hmhj_biaoqian  .png", imgLvUp);
                imgLvUp.gray = false;
                lblLvUp.text = sg.translate("可升级");
            }
        }
        _onListWeaponClick(evt, idx) {
            if (evt.type != Laya.Event.CLICK)
                return;
            let data = this.listRelic.getItem(idx);
            if (!data || this._isSelect)
                return;
            let cfgName = this._type == 1 ? "beatGame_treasure" : "beatGame_weapon";
            let cfg = sg.dbmgr.get(cfgName, data.id);
            if (data.isMax) {
                sg.uimgr.showNotice(sg.translate("已满级"));
                return;
            }
            this._isSelect = true;
            this._callback(data.id);
            let list = this._type == 1 ? this.listBuff : this.listWeapon;
            if (data.isNew) {
                for (let i = 0; i < list.array.length; i++) {
                    if (!list.array[i]) {
                        list.array[i] = { id: data.id, type: this._type };
                        break;
                    }
                }
                list.refresh();
            }
            for (let i = 0; i < list.length; i++) {
                let item = list.getItem(i);
                let cfg2 = sg.dbmgr.get(cfgName, item.id);
                if (item && cfg.type == cfg2.type) {
                    let cell = list.getCell(i);
                    item.id = cfg.id;
                    cell.playEff();
                    list.changeItem(i, item);
                    break;
                }
            }
            this.after(1000, this.closeSelf);
        }
        _onBtnCancel() {
            this.closeSelf();
            this._callback(0);
        }
    }
    mvc.PopMiniGameBeatChoose = PopMiniGameBeatChoose;
})(mvc || (mvc = {}));

