(function (mvc) {
    class SysMiniGameBeat extends ui.view.beatGame.sys_miniGameBeatUI {
        constructor() {
            super(...arguments);
            this.beatClipId = [];
        }
        initView(type, id) {
            this._type = type;
            this.id = id;
            this._isEnd = false;
        }
        initSendMsg() {
        }
        initModelEvent() {
            this.bindModelEvent(mvc.mainModel, mvc.MainConst.EVT.STAGE_VISIBLE_CHANGED, this._onStageVisibleChange);
            this.bindModelEvent(mvc.miniGameModel, mvc.MiniGameConst.EVT.QUIT_BEAT_MINI_GAME, this._onBtnQuit);
            this.bindModelEvent(mvc.miniGameModel, mvc.MiniGameConst.EVT.SHOW_PAUSE_UI, this._showPauseUI);
        }
        initCtrlEvent() {
            this.btnPause.on(Laya.Event.CLICK, this, this._showPauseUI);
        }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            this.boxGame.visible = false;
            this.boxLoad.visible = true;
            this._pauseCount = 0;
            let cfg = sg.dbmgr.get("beatGame_barrierSet", 1);
            let atlas = miniGame.MiniGameConst.resCfg[miniGame.MiniGameConst.type.BEAT].atlas;
            atlas.length = 0;
            this.beatClipId.length = 0;
            atlas.push("res/uidata/innerGame/role/6007/run.atlas");
            let mcfgs = sg.dbmgr.getDB("beatGame_monsterLevel");
            for (let key in mcfgs) {
                let mcfg = mcfgs[key];
                if (this.beatClipId.indexOf(mcfg.pic) == -1) {
                    this.beatClipId.push(mcfg.pic);
                    atlas.push("res/uidata/innerGame/role/" + mcfg.pic + "/run.atlas");
                    atlas.push("res/uidata/innerGame/role/" + mcfg.pic + "/attack.atlas");
                }
            }
            miniGame.MiniGameResMgr.load(miniGame.MiniGameConst.type.BEAT, Laya.Handler.create(this, this._onResLoaded));
            sg.uimgr.on(mvc.UIMGR_EVT.SHOW_UI, this, this._onShowUI);
            sg.uimgr.on(mvc.UIMGR_EVT.CLOSE_UI, this, this._onCloseUI);
        }
        onDisable() {
            if (!this._isEnd) {
                this._mgr && this._mgr.stopGame();
            }
            this._mgr && this._mgr.clearScene();
            miniGame.MiniGameResMgr.clearRes(miniGame.MiniGameConst.type.BEAT);
            this._mgr = null;
            sg.uimgr.off(mvc.UIMGR_EVT.SHOW_UI, this, this._onShowUI);
            sg.uimgr.off(mvc.UIMGR_EVT.CLOSE_UI, this, this._onCloseUI);
            Laya.Animation.clearCache("beatGame_player_run");
            for (let id of this.beatClipId) {
                Laya.Animation.clearCache("beatGame_monster_run_" + id);
                Laya.Animation.clearCache("beatGame_monster_atk_" + id);
            }
            super.onDisable();
        }
        _onResLoaded(isSucc) {
            if (!isSucc) {
                sg.uimgr.showNotice(sg.translate("资源加载失败，请稍后再试"));
                this.closeSelf();
                return;
            }
            Laya.Animation.createFrames("res/uidata/innerGame/role/6007/run.atlas", "beatGame_player_run");
            for (let id of this.beatClipId) {
                Laya.Animation.createFrames("res/uidata/innerGame/role/" + id + "/run.atlas", "beatGame_monster_run_" + id);
                Laya.Animation.createFrames("res/uidata/innerGame/role/" + id + "/attack.atlas", "beatGame_monster_atk_" + id);
            }
            this.boxLoad.visible = false;
            this.boxGame.visible = true;
            this._mgr = new miniGame.beat.MiniGameBeatMgr();
            let lv = this._type == 1 ? 1 : this.id;
            let initWeapon;
            let lvCfg;
            if (this._type == 1) {
                initWeapon = 2001;
                lvCfg = sg.dbmgr.get("innerGame_beatBarrier", 1);
                this.lblName.text = lvCfg.chapterName;
            }
            else {
                initWeapon = mvc.miniGameModel.beatVo.skin;
                lvCfg = sg.dbmgr.get("beatGame_barrierSet", lv);
                this.lblName.text = lvCfg.chapterName;
            }
            this._mgr.startGame(lvCfg, initWeapon, this, this._onEnd.bind(this));
        }
        _onEnd(score) {
            this._isEnd = true;
            if (this.id) {
                if (this._type == 1) {
                    mvc.miniGameCtrl.reqReward(this.id, [score[0]]);
                }
                else {
                    if (score[0] == 1 && this.id <= mvc.miniGameModel.beatVo.level && mvc.miniGameModel.beatVo.getSweepNum() > 0) {
                        mvc.miniGameCtrl.reqBeatSweep(this.id);
                    }
                    else {
                        mvc.miniGameCtrl.reqBeatGameOver(this.id, score[0], score[1]);
                    }
                }
            }
            else {
                sg.uimgr.showUI("pop_getReward", sg.translate("结算奖励"), [[2, 100]], undefined, undefined, Laya.Handler.create(this, () => {
                    sg.uimgr.closeUI("sys_miniGameBeat");
                }), "gxhd");
            }
        }
        _onBtnQuit() {
            let score = this._mgr ? this._mgr.getScore() : 0;
            if (!mvc.mainModel.getSacrificeTip(mvc.FirstTipsID.MINI_GAME_FISH_QUIT)) {
                if (this._mgr) {
                    this._mgr.pause();
                    this._pauseCount++;
                }
                sg.uimgr.showConfirm({
                    btnCancelVisible: true,
                    content: sg.translate("确认是否退出当前关卡，退出无法获得全部奖励"),
                    sacrificeTipVisible: true,
                    sacrificeTipFunc: () => {
                        mvc.mainModel.showSacrificeTip = mvc.FirstTipsID.MINI_GAME_FISH_QUIT;
                    },
                    enterFunc: () => {
                        if (this.id) {
                            if (this._type == 1) {
                                mvc.miniGameCtrl.reqReward(this.id, [score[0]]);
                            }
                            else {
                                mvc.miniGameCtrl.reqBeatGameOver(this.id, score[0], score[1]);
                            }
                        }
                        this.closeSelf();
                    },
                    cancelFunc: () => {
                        this._pauseCount--;
                        this._pauseCount = Math.max(0, this._pauseCount);
                        if (this._mgr && this._pauseCount == 0) {
                            this._mgr.resume();
                        }
                    }
                });
            }
            else {
                if (this.id) {
                    if (this._type == 1) {
                        mvc.miniGameCtrl.reqReward(this.id, [score[0]]);
                    }
                    else {
                        mvc.miniGameCtrl.reqBeatGameOver(this.id, score[0], score[1]);
                    }
                }
                this.closeSelf();
            }
        }
        _onShowUI(cfgName) {
            if (mvc.MiniGameConst.excludeUI.indexOf(cfgName) != -1)
                return;
            if (this._mgr) {
                this._mgr.pause();
                this._pauseCount++;
            }
        }
        _onCloseUI(cfgName) {
            if (mvc.MiniGameConst.excludeUI.indexOf(cfgName) != -1)
                return;
            this._pauseCount--;
            this._pauseCount = Math.max(0, this._pauseCount);
            if (this._mgr && this._pauseCount == 0) {
                this._mgr.resume();
            }
        }
        _onStageVisibleChange(isVisible) {
            if (!this._mgr)
                return;
            if (isVisible) {
                this._pauseCount--;
                this._pauseCount = Math.max(0, this._pauseCount);
                if (this._mgr && this._pauseCount == 0) {
                    this._mgr.resume();
                }
            }
            else {
                this._mgr.pause();
                this._pauseCount++;
            }
        }
        _showPauseUI() {
            this._mgr && this._mgr.showPauseUI();
        }
    }
    mvc.SysMiniGameBeat = SysMiniGameBeat;
})(mvc || (mvc = {}));

