            super.dataSource = data;
            if (!data)
                return;
            let vo = mvc.miniGameModel.beatVo;
            let isActive = vo.atlasActived.indexOf(data.id) != -1;
            let isShow = isActive;
            this.clipQua.index = data.quality - 1;
            this.lblWay.text = data.way;
            let url = mgr.icon.getIconPath(data.icon);
