(function (mvc) {
    class UnitMiniGameBeatChapterItem extends ui.view.beatGame.unit_chapterItemUI {
        initView() {
        }
        initSendMsg() {
        }
        initModelEvent() {
        }
        initCtrlEvent() {
            this.on(Laya.Event.CLICK, this, this._onClick);
        }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
        }
        onDisable() {
            super.onDisable();
        }
        set dataSource(data) {
            super.dataSource = data;
            if (!data)
                return;
            let url = mgr.icon.getIconPath(data.miniMap);
            mgr.icon.drawTexture(url, this.imgBg);
            let vo = mvc.miniGameModel.beatVo;
            let isLock = false;
            let time = mvc.miniGameModel.checkLevelOpen(data.timeCondition);
            if (data.id <= vo.level + 1 && time <= 0) {
                isLock = false;
            }
            else {
                isLock = true;
                if (time <= 0) {
                    this.lblLock.text = sg.translate("通关上一个难度解锁");
                }
                else {
                    if (data.id > vo.level + 1) {
                        this.lblLock.text = sg.translate("通关上一个难度解锁");
                    }
                    else {
                        let lastT = sg.time.formatTimeStrT("F12", time);
                        this.lblLock.text = StringEx.format(sg.translate("${lastT}后开启"), {"lastT":lastT});
                    }
                }
            }
            this.boxLock.visible = isLock;
            this.imgClear.visible = data.id <= vo.level;
            this.imgRed.visible = false;
            if (!isLock) {
                if (data.id == vo.level + 1) {
                    this.imgRed.visible = true;
                }
                else {
                    let nextCfg = sg.dbmgr.get("beatGame_barrierSet", data.id + 1);
                    if (nextCfg) {
                        let nextIsLock = mvc.miniGameModel.checkIsLock(nextCfg);
                        if (nextIsLock) {
                            this.imgRed.visible = vo.getSweepNum() > 0;
                        }
                        else {
                            this.imgRed.visible = false;
                        }
                    }
                    else {
                        this.imgRed.visible = vo.getSweepNum() > 0;
                    }
                }
            }
            let arr = [];
            let starNum = ((data.id - 1) % 3) + 1;
            for (let i = 0; i < starNum; i++) {
                arr.push({});
            }
            this.listStar.array = arr;
            this.listStar.width = 34 * starNum - 10;
        }
        get dataSource() {
            return super.dataSource;
        }
        _onClick() {
            let data = this.dataSource;
            if (!data)
                return;
            let vo = mvc.miniGameModel.beatVo;
            let isLock = false;
            if (data.id > vo.level + 1) {
                isLock = true;
            }
            else {
                isLock = !mgr.conditionMgr.check(data.openCondition, false);
            }
            if (isLock)
                return;
            let time = mvc.miniGameModel.checkLevelOpen(data.timeCondition);
            if (time > 0) {
                let lastT = sg.time.formatTimeStrT("F12", time);
                sg.uimgr.showNotice(StringEx.format(sg.translate("${lastT}后开启"), {"lastT":lastT}));
                return;
            }
            sg.uimgr.showUI("pop_miniGameBeatEnter", data.id);
            mvc.miniGameModel.viewBeatNewLevel(data.id);
        }
    }
    mvc.UnitMiniGameBeatChapterItem = UnitMiniGameBeatChapterItem;
})(mvc || (mvc = {}));

