(function (mvc) {
    class SysMiniGameBarrier extends ui.view.innerGame.sys_miniGameBarrierUI {
        initView(id) {
            this.id = id;
        }
        initSendMsg() {
        }
        initModelEvent() {
            this.bindModelEvent(mvc.mainModel, mvc.MainConst.EVT.STAGE_VISIBLE_CHANGED, this._onStageVisibleChange);
        }
        initCtrlEvent() {
            this.btnQuit.on(Laya.Event.CLICK, this, this._onBtnQuit);
        }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            let arr = miniGame.MiniGameConst.resCfg[miniGame.MiniGameConst.type.BARRIER].skels;
            if (arr.length == 0) {
                arr.push(9022);
                arr.push(9023);
                arr.push(9024);
                arr.push(9025);
                let cfgs = sg.dbmgr.getDB("innerGame_barrierTask");
                for (let key in cfgs) {
                    let cfg = cfgs[key];
                    if (cfg.model && arr.indexOf(cfg.model) == -1) {
                        arr.push(cfg.model);
                    }
                }
            }
            this.boxLoad.visible = true;
            this.boxGame.visible = false;
            this._pauseCount = 0;
            this._isEnd = false;
            miniGame.MiniGameResMgr.load(miniGame.MiniGameConst.type.BARRIER, Laya.Handler.create(this, this._onResLoaded));
            sg.uimgr.on(mvc.UIMGR_EVT.SHOW_UI, this, this._onShowUI);
            sg.uimgr.on(mvc.UIMGR_EVT.CLOSE_UI, this, this._onCloseUI);
            sg.sound.playMusic("res/sound/bg/bg_fj.mp3");
        }
        onDisable() {
            if (!this._isEnd) {
                this._mgr && this._mgr.stopGame();
                if (this.id)
                    Laya.timer.callLater(sg.uimgr, sg.uimgr.showUI, ["sys_treasure"]);
            }
            this._mgr && this._mgr.clearScene();
            miniGame.MiniGameResMgr.clearRes(miniGame.MiniGameConst.type.BARRIER);
            this._mgr = null;
            sg.uimgr.off(mvc.UIMGR_EVT.SHOW_UI, this, this._onShowUI);
            sg.uimgr.off(mvc.UIMGR_EVT.CLOSE_UI, this, this._onCloseUI);
            this.boxGame.off(Laya.Event.MOUSE_DOWN, this, this._onMouseDown);
            this.boxGame.off(Laya.Event.MOUSE_MOVE, this, this._onMouseMove);
            this.boxGame.off(Laya.Event.MOUSE_UP, this, this._onMouseUp);
            this.boxGame.off(Laya.Event.MOUSE_OUT, this, this._onMouseUp);
            sg.sound.playMusic("res/sound/bg/bg_main.mp3");
            super.onDisable();
        }
        _onResLoaded(isSucc) {
            if (!isSucc) {
                sg.uimgr.showNotice(sg.translate("资源加载失败，请稍后再试"));
                this.closeSelf();
                return;
            }
            this.boxLoad.visible = false;
            this.boxGame.visible = true;
            this._mgr = new miniGame.barrier.MiniGameBarrierMgr();
            this._mgr.startGame(this.boxBg, this.boxMap, this.lblCur, this.lblMax, this._onEnd.bind(this), this.id ? 1 : 2);
            this.boxGame.on(Laya.Event.MOUSE_DOWN, this, this._onMouseDown);
        }
        _onEnd(score) {
            this._isEnd = true;
            if (this.id) {
                mvc.miniGameCtrl.reqReward(this.id, score);
            }
            else {
                sg.uimgr.showUI("pop_getReward", sg.translate("结算奖励"), [[2, 100]], undefined, undefined, Laya.Handler.create(this, () => {
                    sg.uimgr.closeUI("sys_miniGameBarrier");
                }), "gxhd");
            }
        }
        _onBtnQuit() {
            let score = this._mgr ? this._mgr.getScore() : 0;
            if (!mvc.mainModel.getSacrificeTip(mvc.FirstTipsID.MINI_GAME_FISH_QUIT)) {
                this._mgr && this._mgr.pause();
                sg.uimgr.showConfirm({
                    btnCancelVisible: true,
                    content: sg.translate("退出视为游戏失败，您确定要退出吗？"),
                    sacrificeTipVisible: true,
                    sacrificeTipFunc: () => {
                        mvc.mainModel.showSacrificeTip = mvc.FirstTipsID.MINI_GAME_FISH_QUIT;
                    },
                    enterFunc: () => {
                        if (this.id) {
                            mvc.miniGameCtrl.reqReward(this.id, score);
                        }
                        this.closeSelf();
                    },
                    cancelFunc: () => {
                        this._mgr && this._mgr.resume();
                    }
                });
            }
            else {
                if (this.id) {
                    mvc.miniGameCtrl.reqReward(this.id, score);
                }
                this.closeSelf();
            }
        }
        _onShowUI(cfgName) {
            if (mvc.MiniGameConst.excludeUI.indexOf(cfgName) != -1)
                return;
            if (this._mgr) {
                this._mgr.pause();
                this._pauseCount++;
            }
        }
        _onCloseUI(cfgName) {
            if (mvc.MiniGameConst.excludeUI.indexOf(cfgName) != -1)
                return;
            this._pauseCount--;
            this._pauseCount = Math.max(0, this._pauseCount);
            if (this._mgr && this._pauseCount == 0) {
                this._mgr.resume();
            }
        }
        _onStageVisibleChange(isVisible) {
            if (!this._mgr)
                return;
            if (isVisible) {
                this._pauseCount--;
                this._pauseCount = Math.max(0, this._pauseCount);
                if (this._mgr && this._pauseCount == 0) {
                    this._mgr.resume();
                }
            }
            else {
                this._mgr.pause();
                this._pauseCount++;
            }
        }
        _onMouseDown(evt) {
            this.boxGame.on(Laya.Event.MOUSE_MOVE, this, this._onMouseMove);
            this.boxGame.on(Laya.Event.MOUSE_UP, this, this._onMouseUp);
            this.boxGame.on(Laya.Event.MOUSE_OUT, this, this._onMouseUp);
            this._lastX = evt.stageX;
        }
        _onMouseMove(evt) {
            if (this._mgr) {
                this._mgr.playerMove(evt.stageX - this._lastX);
            }
            this._lastX = evt.stageX;
        }
        _onMouseUp(evt) {
            this.boxGame.off(Laya.Event.MOUSE_MOVE, this, this._onMouseMove);
            this.boxGame.off(Laya.Event.MOUSE_UP, this, this._onMouseUp);
            this.boxGame.off(Laya.Event.MOUSE_OUT, this, this._onMouseUp);
        }
    }
    mvc.SysMiniGameBarrier = SysMiniGameBarrier;
})(mvc || (mvc = {}));

