var mvc;
(function (mvc) {
    class SysSwordGame extends ui.view.swordGame.sys_swordGameUI {
        initView() {
        }
        initSendMsg() {
        }
        initModelEvent() {
            this.bindModelEvent(mvc.miniGameModel, mvc.MiniGameConst.EVT.UPDATE_SWORD, this._update);
            this.bindModelEvent(mvc.miniGameModel, mvc.MiniGameConst.EVT.GET_SWORD_BOX_REWARD, this._updateChapter);
        }
        initCtrlEvent() {
            this.tabChapter.selectHandler = this.createHandler(this, this._onTab, undefined, false);
            this.listLevel.vScrollBarSkin = "";
            this.listChapter.renderHandler = this.createHandler(this, this._listChapterRender, undefined, false);
            this.listChapter.mouseHandler = this.createHandler(this, this._listChapterMouseEvt, undefined, false);
            this.btnAtlas.on(Laya.Event.CLICK, this, this._onBtnAtlas);
            this.panelTab.hScrollBarSkin = "";
            this.unitRed.id = mvc.REDOT_ID.SWORD_GAME_ATLAS;
        }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            let labels = "";
            let cfgs = sg.dbmgr.getDB("swordGame_chapterSet");
            for (let key in cfgs) {
                if (labels.length > 0) {
                    labels += ",";
                }
                let cfg = cfgs[key];
                labels += cfg.name;
            }
            this.tabChapter.labels = labels;
            this.tabChapter.selectedIndex = mvc.miniGameModel.swordVo.curChatper - 1;
            this._updateChapter();
            this._updateChapterRed();
        }
        onDisable() {
            this.tabChapter.selectedIndex = -1;
            super.onDisable();
        }
        _update() {
            this._onTab(this.tabChapter.selectedIndex);
            this._updateChapter();
            this._updateChapterRed();
        }
        _updateChapterRed() {
            let cfgs = sg.dbmgr.getDB("swordGame_chapterSet");
            let newC = mvc.miniGameModel.swordVo.newChatper;
            for (let key in cfgs) {
                let cfg = cfgs[key];
                let img = this["imgRed" + cfg.id];
                if (img) {
                    img.visible = newC.indexOf(cfg.id) != -1;
                }
            }
        }
        _onTab(idx) {
            if (idx < 0)
                return;
            let chapter = idx + 1;
            if (chapter > mvc.miniGameModel.swordVo.curChatper) {
                sg.uimgr.showNotice(sg.translate("通关上一章开启"));
                this.tabChapter.selectedIndex = this._lastIndex;
                return;
            }
            this._lastIndex = idx;
            mvc.miniGameModel.viewNewChapter(chapter);
            let levelCfgs = sg.dbmgr.filter("swordGame_levelSet", (id, item) => {
                return item.chapter == chapter;
            });
            let curLv = mvc.miniGameModel.swordVo.level;
            let arr = [];
            let stop = (Math.floor(curLv / 10) + 1) * 10;
            for (let i = 0; i < levelCfgs.length; i++) {
                if (levelCfgs[i].id > stop)
                    break;
                arr.push({
                    isLast: i == levelCfgs.length - 1,
                    idx: i + 1,
                    cfg: levelCfgs[i]
                });
            }
            arr.sort((a, b) => {
                return b.cfg.id - a.cfg.id;
            });
            let jump = arr.length - 1;
            for (let i = 0; i < arr.length; i++) {
                if (arr[i].cfg.id == stop - 10) {
                    jump = Math.max(0, i - 10);
                    break;
                }
            }
            this.listLevel.array = arr;
            this.listLevel.scrollTo(jump);
        }
        _updateChapter() {
            let first;
            let second;
            let progStart = 0;
            let cfgs = sg.dbmgr.getDB("swordGame_levelReward");
            let cur = mvc.miniGameModel.swordVo.received;
            if (cur > 0) {
                let curCfg = sg.dbmgr.get("swordGame_levelReward", cur);
                cur = curCfg.level;
            }
            for (let key in cfgs) {
                let cfg = cfgs[key];
                if (second)
                    progStart = second.level;
                second = first;
                first = cfg;
                if (second && cfg.level > cur)
                    break;
            }
            this.listChapter.array = [first, second];
            let curLv = mvc.miniGameModel.swordVo.level;
            this.progChapter.value = Math.min(1, (curLv - progStart) / (first.level - progStart)) * 0.7;
        }
        _listChapterRender(cell) {
            let data = cell.dataSource;
            if (!data)
                return;
            let vo = mvc.miniGameModel.swordVo;
            let isPass = data.level <= vo.level;
            let canGet = isPass && data.id > vo.received;
            let lblLevel = cell.getChildByName("lblLevel");
            let lv = data.level;
            lblLevel.text = StringEx.format(sg.translate("${lv}关"), {"lv":lv});
            let imgActive = cell.getChildByName("imgActive");
            let unitBox = cell.getChildByName("unitBox");
            let imgRed = cell.getChildByName("imgRed");
            imgActive.visible = isPass;
            if (canGet) {
                unitBox.ani1.play(0, true);
                unitBox.clip.index = 1;
                imgRed.visible = true;
            }
            else {
                unitBox.ani1.gotoAndStop(0);
                unitBox.clip.index = 0;
                imgRed.visible = false;
            }
        }
        _listChapterMouseEvt(evt, idx) {
            if (evt.type != Laya.Event.CLICK)
                return;
            let data = this.listChapter.getItem(idx);
            if (!data)
                return;
            let vo = mvc.miniGameModel.swordVo;
            if (vo.level >= data.level && data.id > vo.received) {
                mvc.miniGameCtrl.reqGetChapterReward(data.id);
            }
            else {
                sg.uimgr.showUI("pop_swordGameRewardPerview", data);
            }
        }
        _onBtnAtlas() {
            sg.uimgr.showUI("pop_swordGameAtlas");
        }
    }
    mvc.SysSwordGame = SysSwordGame;
})(mvc || (mvc = {}));

