(function (mvc) {
    let EVT = mvc.InviteConst.EVT;
    class InviteModel extends sg.ModelBase {
        constructor() {
            super(...arguments);
            this.inviteNum = 0;
            this.canGetReward = false;
            this.isGetAllReward = false;
        }
        initModel() {
        }
        registerEvents() {
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.INVITE, this._checInviteRed, this);
        }
        getInvitationInfo(data) {
            this.inviteNum = data.num;
            this.receiveId = data.received;
            this.updateRewardState();
            mgr.redotMgr.check(mvc.REDOT_ID.INVITE);
            this.fireEvent(EVT.UPDATE_LIST);
        }
        getReward(data) {
            this.receiveId = data.received;
            sg.uimgr.showUI("pop_getReward", sg.translate("邀请奖励"), data.reward);
            this.updateRewardState();
            mgr.redotMgr.check(mvc.REDOT_ID.INVITE);
            this.fireEvent(EVT.UPDATE_LIST);
        }
        getRewardIsGetById(id) {
            return this.receiveId.indexOf(id) != -1;
        }
        updateRewardState() {
            let canGetReward = false;
            if (!this._cfg) {
                this._cfg = sg.dbmgr.getDB("invite_invite", true);
            }
            for (let i = 0, len = this._cfg.length; i < len; i++) {
                let num = this._cfg[i].id;
                if (this.inviteNum >= num && this.receiveId.indexOf(num) == -1) {
                    canGetReward = true;
                    break;
                }
            }
            this.canGetReward = canGetReward;
            if (this.receiveId.length == this._cfg.length) {
                this.isGetAllReward = true;
                mvc.activityModel.removeActivityVo(mvc.FUNC_ID.INVITE, false);
            }
            else {
                this.isGetAllReward = false;
            }
        }
        _checInviteRed() {
            return this.canGetReward ? 1 : 0;
        }
        setInviteCode(data) {
            this.inviteCode = data.invite_code;
            this.inviteInfo = data.invite_info;
            this.inviteMsg = data.invite_msg;
            this.hasInvite = data.has_invite;
        }
    }
    mvc.InviteModel = InviteModel;
})(mvc || (mvc = {}));

