(function (mvc) {
    class PopInvite extends ui.view.invite.pop_InviteUI {
        initView() {
            this._model = mvc.inviteModel;
        }
        initModelEvent() {
            this.bindModelEvent(this._model, mvc.InviteConst.EVT.UPDATE_LIST, this._updateList);
        }
        initCtrlEvent() {
            this.inviteList.vScrollBarSkin = "";
            this.inviteList.renderHandler = this.createHandler(this, this._onInviteList, null, false);
            this.btnInvite.on(Laya.Event.CLICK, this, this._onBtnInvite);
        }
        updateWhenNetReConn() {
            this._updateList();
        }
        onAwake() {
            super.onAwake();
            this.btnInvite.visible = mgr.gplatform.isOpenShareHead(5);
        }
        onEnable() {
            super.onEnable();
            this._cfg = sg.dbmgr.getDB("invite_invite", true);
            this._sort();
            this.inviteList.array = this._cfg;
            if (mgr.gplatform.isOpenShareHead(5)) {
                if (!this._model.inviteCode) {
                    mvc.inviteCtrl.getInviteCode();
                }
            }
        }
        _onInviteList(cell, idx) {
            let data = cell.dataSource;
            if (!data)
                return;
            cell.initView(data);
        }
        _updateList() {
            this._sort();
            this.inviteList.array = this._cfg;
        }
        _sort() {
            this._cfg.sort((a, b) => {
                let isGetA = this._model.getRewardIsGetById(a.id);
                let isGetB = this._model.getRewardIsGetById(b.id);
                if ((isGetA && isGetB) || (!isGetA && !isGetB)) {
                    return a.id - b.id;
                }
                else {
                    return isGetA ? 1 : -1;
                }
            });
        }
        _onBtnInvite() {
            if (!this._model.inviteCode) {
                mvc.inviteCtrl.getInviteCode();
                sg.uimgr.showNotice(sg.translate("出现网络错误，请重试"));
            }
            else {
                sg.uimgr.showUI("pop_inviteCode");
            }
        }
    }
    mvc.PopInvite = PopInvite;
})(mvc || (mvc = {}));

