            this.btn2.on(Laya.Event.CLICK, this, this._onTabType, [2]);
            this.btn3.on(Laya.Event.CLICK, this, this._onTabType, [3]);
            this.btn4.on(Laya.Event.CLICK, this, this._onTabType, [4]);
            this.btn5.on(Laya.Event.CLICK, this, this._onTabType, [5]);
