(function (mvc) {
    class PopReturnChoice extends ui.view.returnActivity.pop_returnChoice1UI {
        initView(...args) {
        }
        initModelEvent() {
        }
        initCtrlEvent() {
            this.rewardList.renderHandler = this.createHandler(this, this._onRenderList, null, false);
            this.reward2List.renderHandler = this.createHandler(this, this._onRender2List, null, false);
            this.rewardList.mouseHandler = this.createHandler(this, this._onMouseList, null, false);
            this.reward2List.mouseHandler = this.createHandler(this, this._onMouse2List, null, false);
            this.btnSure.on(Laya.Event.CLICK, this, this._onBtnSure);
        }
        onEnable() {
            super.onEnable();
            this._isPassRoundOne = mvc.returnActivityModel.lottoVo.isGetAllGuaranteeByRound(1);
            this._updateView();
        }
        _updateView() {
            let round = mvc.returnActivityModel.mainVo.round;
            this._selectId = mvc.returnActivityModel.lottoVo.select_guarantee_id;
            this._updateSelectItem();
            let cfg1 = sg.dbmgr.getArray("return_returnLotteryNormalRe", { round: 1, turn: round });
            this.rewardList.array = cfg1;
            let cfg2 = sg.dbmgr.getArray("return_returnLotteryNormalRe", { round: 2, turn: round });
            this.reward2List.array = cfg2;
        }
        _updateSelectItem() {
            if (!this._selectId) {
                this.itemChoice.visible = false;
            }
            else {
                this.itemChoice.visible = true;
                let round = mvc.returnActivityModel.mainVo.round;
                let cfg = sg.dbmgr.getArray("return_returnLotteryNormalRe", { ID: this._selectId, turn: round })[0];
                let vos = mvc.ItemVo.createItemVos([[cfg.reward_id, cfg.reward]]);
                this.itemChoice.initView(vos[0]);
            }
        }
        _onRenderList(cell, idx) {
            let data = cell.dataSource;
            if (!data)
                return;
            let itemReward = cell.getChildByName("item");
            let select = cell.getChildByName("imgSelect");
            let lblNum = cell.getChildByName("lblNum");
            let vos = mvc.ItemVo.createItemVos([[data.reward_id, data.reward]]);
            itemReward.initView(vos[0]);
            itemReward.mouseEnabled = false;
            select.visible = data.ID == this._selectId;
            let count = mvc.returnActivityModel.lottoVo.getRewardCount(data.ID);
            lblNum.text = sg.translate("限购") + `${data.getLimit - count}/${data.getLimit}`;
            lblNum.color = data.getLimit - count > 0 ? mvc.COLOR.GREEN : mvc.COLOR.RED;
            cell.disabled = data.getLimit - count == 0;
        }
        _onRender2List(cell, idx) {
            let data = cell.dataSource;
            if (!data)
                return;
            let itemReward = cell.getChildByName("item");
            let select = cell.getChildByName("imgSelect");
            let imgBg = cell.getChildByName("imgBg");
            let imgMask = cell.getChildByName("imgMask");
            let lblNum = cell.getChildByName("lblNum");
            let vos = mvc.ItemVo.createItemVos([[data.reward_id, data.reward]]);
            itemReward.initView(vos[0]);
            itemReward.mouseEnabled = false;
            select.visible = data.ID == this._selectId;
            if (!this._isPassRoundOne) {
                imgBg.visible = lblNum.visible = false;
                imgMask.visible = true;
                cell.mouseEnabled = false;
            }
            else {
                imgBg.visible = lblNum.visible = true;
                imgMask.visible = false;
                cell.mouseEnabled = true;
                let count = mvc.returnActivityModel.lottoVo.getRewardCount(data.ID);
                lblNum.text = sg.translate("限购") + `${data.getLimit - count}/${data.getLimit}`;
                lblNum.color = data.getLimit - count > 0 ? mvc.COLOR.GREEN : mvc.COLOR.RED;
                cell.disabled = data.getLimit - count == 0;
            }
        }
        _onMouseList(evt, idx) {
            if (evt.type != Laya.Event.CLICK)
                return;
            let item = this.rewardList.getCell(idx);
            let data = item.dataSource;
            if (!data)
                return;
            this._selectId = data.ID;
            this.rewardList.refresh();
            this._updateSelectItem();
        }
        _onMouse2List(evt, idx) {
            if (evt.type != Laya.Event.CLICK)
                return;
            let item = this.reward2List.getCell(idx);
            let data = item.dataSource;
            if (!data)
                return;
            this._selectId = data.ID;
            this.reward2List.refresh();
            this._updateSelectItem();
        }
        _onBtnSure() {
            if (!this._selectId) {
                sg.uimgr.showNotice(sg.translate("请选择保底奖励"));
                return;
            }
            mvc.returnActivityCtrl.reqSelectGua(this._selectId);
            this.closeSelf();
        }
    }
    mvc.PopReturnChoice = PopReturnChoice;
})(mvc || (mvc = {}));

