(function (mvc) {
    class PopReturnLotteryPool extends ui.view.bgActivity2.pop_bgLotterPool2UI {
        initView(...args) {
            this._model = mvc.returnActivityModel;
        }
        initModelEvent() {
        }
        initCtrlEvent() {
            this.listLotterItem2.vScrollBarSkin = "";
            this.listLotterItem1.renderHandler = this.createHandler(this, this._onRenderList, null, false);
            this.listLotterItem2.renderHandler = this.createHandler(this, this._onRenderList, null, false);
            this.listLotterItem3.renderHandler = this.createHandler(this, this._onRenderList, null, false);
        }
        onEnable() {
            super.onEnable();
            this._updateView();
            this._isGetRoundOne = this._model.lottoVo.isGetAllGuaranteeByRound(1);
        }
        _updateView() {
            let arr = sg.dbmgr.getArray("return_returnLotteryNormalRe", { turn: this._model.mainVo.round, isGuarant: 1, round: 1 });
            this.lblProbability1.text = sg.translate("综合出货概率:") + this._getProbability(arr);
            this.listLotterItem1.array = arr;
            arr = sg.dbmgr.getArray("return_returnLotteryNormalRe", { turn: this._model.mainVo.round, isGuarant: 0 });
            this.lblProbability2.text = sg.translate("综合出货概率:") + this._getProbability(arr);
            this.listLotterItem2.array = arr;
            arr = sg.dbmgr.getArray("return_returnLotteryNormalRe", { turn: this._model.mainVo.round, isGuarant: 1, round: 2 });
            this.listLotterItem3.array = arr;
        }
        _getProbability(arr) {
            let probability = 0;
            for (let i = 0; i < arr.length; i++) {
                probability += this._isGetRoundOne ? arr[i].secOdd : arr[i].odd;
            }
            if (probability > 0)
                return probability.toFixed(2) + "%";
            else
                return "";
        }
        _onRenderList(cell, index) {
            if (!cell.dataSource)
                return;
            let item = cell.getChildByName("item");
            let probability = cell.getChildByName("lblProbability");
            let data = cell.dataSource;
            if (item) {
                item.initViewCfg([data.reward_id, data.reward]);
            }
            if (probability) {
                probability.text = this._isGetRoundOne ? data.secOdd.toFixed(2) : data.odd.toFixed(2) + "%";
            }
            let lblLimit = cell.getChildByName("lblLimit");
            if (lblLimit) {
                lblLimit.visible = true;
                let getNum = this._model.lottoVo.getRewardCount(data.ID);
                lblLimit.text = sg.translate("限量:") + (data.getLimit - getNum) + "/" + data.getLimit;
                lblLimit.color = getNum < data.getLimit
                    ? mgr.toolsMgr.getColor3("green").stringColor
                    : mgr.toolsMgr.getColor3("red").stringColor;
            }
        }
    }
    mvc.PopReturnLotteryPool = PopReturnLotteryPool;
})(mvc || (mvc = {}));

