var mvc;
(function (mvc) {
    class PopSeniorChoiceView extends ui.view.returnActivity.pop_seniorChoiceUI {
        initModelEvent() {
            this.bindModelEvent(mvc.returnActivityModel, mvc.ReturnActivityConst.EVT.SENIOR_LOTTERY_SELECT_UPDTE, this._updateLotterySelect);
        }
        initCtrlEvent() {
            this.rewardList.renderHandler = this.createHandler(this, this._onRenderListReward, null, false);
            this.rewardList.selectHandler = this.createHandler(this, this._onSelectListReward, null, false);
            this.rewardList.vScrollBarSkin = "";
            this.rewardList.selectEnable = true;
            this.btnSure.on(Laya.Event.CLICK, this, this._onBtnSure);
        }
        onEnable() {
            super.onEnable();
            let vo = mvc.returnActivityModel.seniorLotteryVo;
            let select_guarantee_id = vo.select_guarantee_id == 0 ? vo.getSupremeRewardId() : vo.select_guarantee_id;
            this._selsectId = select_guarantee_id;
            this._updateView();
        }
        onDisable() {
            super.onDisable();
            this.unitRoleSkin.clear();
        }
        _updateView() {
            let vo = mvc.returnActivityModel.seniorLotteryVo;
            let arr = vo.guaranteeItems.concat();
            arr.sort((a, b) => {
                let cfga = sg.dbmgr.get("vitem", a.reward_id);
                let cfgb = sg.dbmgr.get("vitem", b.reward_id);
                let haveA = vo.getHaveSkin(cfga.fashionId);
                let haveB = vo.getHaveSkin(cfgb.fashionId);
                if (haveA == haveB) {
                    return a.ID - b.ID;
                }
                if (haveA) {
                    return 1;
                }
                return -1;
            });
            if (this._selsectId == 0) {
                this._selsectId = arr[0].ID;
            }
            this.rewardList.array = arr;
            this._updateRoleSkin();
        }
        _updateRoleSkin() {
            if (this._selsectId == null || this._selsectId == 0) {
                this.unitRoleSkin.visible = false;
                return;
            }
            let config = sg.dbmgr.get("return_seniorReturnLotteryNormalRe", this._selsectId);
            let cfg = sg.dbmgr.get("vitem", config.reward_id);
            if (cfg.fashionId > 0) {
                this.unitRoleSkin.visible = true;
                this._updateSkinModel(cfg.fashionId);
            }
            else {
                this.unitRoleSkin.visible = false;
            }
        }
        _updateSkinModel(id) {
            let skinCfg = sg.dbmgr.get("fashion_fashion", id);
            if (skinCfg == null) {
                this.lbDesc.visible = this.unitRoleSkin.visible = false;
                return;
            }
            this.unitRoleSkin.visible = true;
            let config = mvc.equipModel.getLimitFashionConfig(id);
            if (config) {
                this.lbDesc.visible = true;
                this.lbDesc.text = config.des;
            }
            let role = skinCfg.avatar[mvc.roleModel.roleInfo.sex];
            let sword = 0;
            let swordVo = mvc.swordModel.getSwordVo();
            if (swordVo.equip) {
                sword = mvc.swordModel.getSwordModelId(swordVo.equip);
            }
            let artifact = 0;
            let artifactVo = mvc.artifactModel.vo;
            if (artifactVo.equipped) {
                let bagVo = mvc.bagModel.getVoById(artifactVo.equipped);
                artifact = bagVo.getCfg().model;
            }
            this.unitRoleSkin.updateView(role, sword, artifact);
        }
        _onSelectListReward(index) {
            if (this.rewardList.array && this.rewardList.array[index]) {
                let data = this.rewardList.array[index];
                let cfg = sg.dbmgr.get("vitem", data.reward_id);
                if (mvc.returnActivityModel.seniorLotteryVo.getHaveSkin(cfg.fashionId)) {
                    sg.uimgr.showNotice(sg.translate("已拥有"));
                    return;
                }
                if (!mvc.returnActivityModel.seniorLotteryVo.getHaveReward(data.ID)) {
                    sg.uimgr.showNotice(sg.translate("已抽完"));
                    return;
                }
                this._selsectId = data.ID;
                this._updateSkinModel(cfg.fashionId);
            }
            this.rewardList.refresh();
        }
        _onRenderListReward(cell, index) {
            let data = cell.dataSource;
            if (data == null) {
                return;
            }
            let imgSelect = cell.getChildByName("imgSelect");
            let item = cell.getChildByName("item");
            let boxHave = cell.getChildByName("boxHave");
            let lbName = cell.getChildByName("lbName");
            let count = mvc.returnActivityModel.seniorLotteryVo.getHaveReward(data.ID);
            imgSelect.visible = data.ID == this._selsectId;
            let cfg = sg.dbmgr.get("vitem", data.reward_id);
            let have = !count || mvc.returnActivityModel.seniorLotteryVo.getHaveSkin(cfg.fashionId);
            boxHave.visible = have;
            if (cfg && cfg.fashionId > 0) {
                let config = mvc.equipModel.getLimitFashionConfig(cfg.fashionId);
                lbName.text = config.name;
                item.initViewCfg([data.reward_id, data.reward], false);
            }
            else {
                lbName.text = mgr.toolsMgr.getNameById(data.reward_id);
                item.initViewCfg([data.reward_id, data.reward], true);
            }
            item.setGray(have);
        }
        _updateLotterySelect() {
            this.closeSelf();
        }
        _onBtnSure() {
            let vo = mvc.returnActivityModel.seniorLotteryVo;
            if (this._selsectId != vo.select_guarantee_id) {
                let config = sg.dbmgr.get("return_seniorReturnLotteryNormalRe", this._selsectId);
                let cfg = sg.dbmgr.get("vitem", config.reward_id);
                if (config && config.getLimit > 0 && vo.getHaveReward(this._selsectId) && cfg && mvc.returnActivityModel.seniorLotteryVo.getHaveSkin(cfg.fashionId) == false) {
                    mvc.returnActivityCtrl.reqSelectGuarantee(config.ID);
                    return;
                }
            }
            this.closeSelf();
        }
    }
    mvc.PopSeniorChoiceView = PopSeniorChoiceView;
})(mvc || (mvc = {}));

