(function (mvc) {
    class PopSeniorLogin extends ui.view.returnActivity.pop_seniorLoginUI {
        initModelEvent() {
            this.bindModelEvent(mvc.returnActivityModel, mvc.ReturnActivityConst.EVT.SENIOR_LOGIN_UPDTE_INFO, this._updateLoginInfo);
        }
        initCtrlEvent() {
            this.listReward.renderHandler = this.createHandler(this, this._onRenderListReward, null, false);
            this.listReward.selectHandler = this.createHandler(this, this._onSelectListReward, null, false);
            this.listReward.vScrollBarSkin = "";
            this.listReward.selectEnable = true;
        }
        onEnable() {
            super.onEnable();
            this._updateView();
            this.timerLoop(1000, this, this._updateActRemainTime);
            this._updateActRemainTime();
        }
        onDisable() {
            super.onDisable();
            this.clearTimer(this, this._updateActRemainTime);
        }
        _updateView() {
            let vo = mvc.returnActivityModel.seniorLoginVo;
            let configs = sg.dbmgr.getArray("return_seniorReturnLogin", { trun: vo.round });
            this.listReward.array = configs;
        }
        _updateActRemainTime() {
            let vo = mvc.returnActivityModel.seniorLotteryVo;
            let tiem = sg.time.getTime() / 1000;
            if (vo) {
                let interval = vo.end_time - tiem;
                if (interval) {
                    this.lblTime.changeText(mgr.UIAssist.$(sg.translate("活动时间：{1}后结束"), sg.time.formatTimeStrT("F10", interval)));
                    return;
                }
            }
            this.lblTime.text = sg.translate("活动已结束");
            this.clearTimer(this, this._updateActRemainTime);
        }
        _updateLoginInfo() {
            this.listReward.refresh();
        }
        _onSelectListReward(index) {
            if (this.listReward.array && this.listReward.array[index]) {
                let day = this.listReward.array[index].day;
                let vo = mvc.returnActivityModel.seniorLoginVo;
                if (day > vo.login_day || day <= vo.received) {
                    return;
                }
                if (day > vo.received + 1) {
                    sg.uimgr.showNotice(sg.translate("请先领取前面的奖励"));
                    return;
                }
                mvc.returnActivityCtrl.reqBigbackLoginReward(day);
            }
        }
        _onRenderListReward(cell, index) {
            if (cell.dataSource == null) {
                return;
            }
            cell.initView(cell.dataSource);
        }
    }
    mvc.PopSeniorLogin = PopSeniorLogin;
})(mvc || (mvc = {}));

