(function (mvc) {
    class SysSeniorLottery extends ui.view.returnActivity.sys_seniorLotteryUI {
        initModelEvent() {
            this.bindModelEvent(mvc.returnActivityModel, mvc.ReturnActivityConst.EVT.SENIOR_LOGIN_UPDTE_INFO, this._updateView);
            this.bindModelEvent(mvc.returnActivityModel, mvc.ReturnActivityConst.EVT.SENIOR_LOTTERY_RESULT, this._updateLotteryResult);
            this.bindModelEvent(mvc.returnActivityModel, mvc.ReturnActivityConst.EVT.SENIOR_LOTTERY_SELECT_UPDTE, this._updateBoxGuarantee);
        }
        initCtrlEvent() {
            this.btnLottery.on(Laya.Event.CLICK, this, this._onbtnLottery);
            this.btnSginUp.on(Laya.Event.CLICK, this, this._onbtnSginUp);
            this.boxGuarantee.on(Laya.Event.CLICK, this, this._onbtnGuarantee);
            this.checkBox.on(Laya.Event.CLICK, this, this._oncheckBox);
        }
        onEnable() {
            super.onEnable();
            this._tempData = null;
            this.checkBox.selected = mvc.returnActivityModel.seniorLotteryVo.selected;
            this.redSginUp.id = mvc.REDOT_ID.SENIOR_LOGIN;
            this.redLottery.id = mvc.REDOT_ID.SENIOR_LOTTERY;
            this._isLottery = false;
            this._showModel();
            this._updateView();
            this.timerLoop(1000, this, this._updateActRemainTime);
            this._updateActRemainTime();
        }
        onDisable() {
            super.onDisable();
            this.clearTimer(this, this._updateActRemainTime);
            this._tempData = null;
        }
        _updateView() {
            let vo = mvc.returnActivityModel.seniorLotteryVo;
            this.btnLottery.disabled = vo.free_count > 0;
            for (let i = 0; i <= 12; i++) {
                let imgbg = this["imgbg" + i];
                let reward = this["reward" + i];
                if (imgbg && reward) {
                    imgbg.visible = false;
                    let config = vo.normalReItems[i];
                    if (config) {
                        reward.initViewCfg([config.reward_id, config.reward], true);
                        reward.showBg(false);
                        imgbg.visible = vo.getRewardCount(config.ID) > 0;
                        reward.setGray(vo.getRewardCount(config.ID) > 0);
                    }
                }
            }
            this._updateBoxGuarantee();
            if (vo.isGetAllGuaranteeByRound()) {
                this.boxLottery.visible = false;
                this.imgTips.visible = true;
            }
            else {
                this.boxLottery.visible = true;
                this.imgTips.visible = false;
            }
        }
        _updateBoxGuarantee() {
            let vo = mvc.returnActivityModel.seniorLotteryVo;
            this.imgGuaranteeHave.visible = false;
            let select_guarantee_id = vo.select_guarantee_id == 0 ? vo.getSupremeRewardId() : vo.select_guarantee_id;
            if (select_guarantee_id > 0) {
                let config = sg.dbmgr.get("return_seniorReturnLotteryNormalRe", select_guarantee_id);
                if (config) {
                    let id = config.reward_id;
                    let cfg = sg.dbmgr.get("vitem", id);
                    if (cfg) {
                        this.btnGuarantee.visible = false;
                        this.imgItem.visible = true;
                        mgr.icon.drawTexture(mgr.icon.getIconPath(cfg.icon), this.imgItem);
                    }
                    this.lblNum.visible = config.reward > 1;
                    if (this.lblNum.visible) {
                        this.lblNum.text = config.reward;
                    }
                    this.imgGuaranteeHave.visible = vo.getHaveReward(config.ID) == false;
                }
            }
            else {
                this.imgItem.visible = false;
                this.btnGuarantee.visible = true;
            }
        }
        _showModel() {
            let modeId = 9169;
            this.unitModel.mouseEnabled = false;
            this.unitModel.visible = true;
            this.unitModel.lableHandle = (obj) => {
                if (obj.name == "tan") {
                    this._shouLotteryResult();
                }
            };
            this.unitModel.setEndHandle(null, (obj) => {
                this._playAniStand();
            });
            this.unitModel.loadedHandle = () => {
                this._playAniStand();
            };
            this.unitModel.loadRole(modeId, "PopSlgAvtivitylotteryShowView", false);
        }
        _playAniStand() {
            this.unitModel.play("stand", false);
        }
        _updateLotteryResult(data) {
            this._tempData = data;
            if (this.checkBox.selected) {
                this._shouLotteryResult();
            }
            else {
                this._playLotteryAni();
            }
        }
        _playLotteryAni() {
            this.unitModel.play("run", false);
        }
        _shouLotteryResult() {
            this._isLottery = false;
            if (this._tempData && this._tempData.length > 0) {
                sg.uimgr.showUI("pop_getReward", sg.translate("恭喜获得"), this._tempData);
            }
            this._updateView();
        }
        _updateActRemainTime() {
            let vo = mvc.returnActivityModel.seniorLotteryVo;
            let tiem = sg.time.getTime() / 1000;
            if (vo) {
                let interval = vo.end_time - tiem;
                if (interval) {
                    this.lblTime.changeText(mgr.UIAssist.$(sg.translate("活动时间：{1}后结束"), sg.time.formatTimeStrT("F10", interval)));
                    return;
                }
            }
            this.lblTime.text = sg.translate("活动已结束");
            this.clearTimer(this, this._updateActRemainTime);
        }
        _onbtnLottery() {
            let vo = mvc.returnActivityModel.seniorLotteryVo;
            let select_guarantee_id = vo.select_guarantee_id == 0 ? vo.getSupremeRewardId() : vo.select_guarantee_id;
            if (select_guarantee_id == 0) {
                sg.uimgr.showNotice(sg.translate("请先选择限时至尊奖励"));
                return;
            }
            if (vo.free_count == 0) {
                if (this._isLottery) {
                    sg.uimgr.showNotice(sg.translate("正在抽奖中"));
                    return;
                }
                this._isLottery = true;
                mvc.returnActivityCtrl.reqBigbackLottery(1);
            }
            else {
            }
        }
        _oncheckBox() {
            mvc.returnActivityModel.seniorLotteryVo.selected = this.checkBox.selected;
        }
        _onImgBGClick(idx) {
            let vo = mvc.returnActivityModel.seniorLotteryVo;
            if (vo && vo.items && vo.items[idx]) {
                mvc.returnActivityCtrl.reqSelectGuarantee(vo.items[idx].ID);
            }
        }
        _onbtnSginUp() {
            sg.uimgr.showUI("pop_seniorLogin");
        }
        _onbtnGuarantee() {
            let vo = mvc.returnActivityModel.seniorLotteryVo;
            let select_guarantee_id = vo.select_guarantee_id == 0 ? vo.getSupremeRewardId() : vo.select_guarantee_id;
            if (select_guarantee_id == 0 || vo.getHaveReward(select_guarantee_id)) {
                sg.uimgr.showUI("pop_seniorChoiceView");
            }
            else {
                let config = sg.dbmgr.get("return_seniorReturnLotteryNormalRe", select_guarantee_id);
                if (config == null)
                    return;
                let id = config.reward_id;
                let cfg = sg.dbmgr.get("vitem", id);
                if (!cfg)
                    return;
                let type = mvc.BagConst.BagType;
                if (cfg.mainclass == type.SKIN || cfg.fashionId > 0) {
                    let cfgF = sg.dbmgr.get("fashion_fashion", cfg.fashionId);
                    if (cfgF)
                        sg.uimgr.showUI("pop_skinTips", cfgF);
                }
                else if (cfg.mainclass == 9) {
                    sg.uimgr.showUI("pop_swordAttrTips", cfg.id);
                }
                else if (cfg.mainclass == type.Artifact) {
                    sg.uimgr.showUI("pop_artifactTips", cfg.id);
                }
                else if (cfg.mainclass == type.Title) {
                    let cfgT = sg.dbmgr.get("fashion_title", id);
                    if (cfgT)
                        sg.uimgr.showUI("pop_titleTips", cfgT, type.Title);
                }
                else if (cfg.mainclass == type.Head_Frame) {
                    let cfgT = sg.dbmgr.get("fashion_headFrame", id);
                    if (cfgT)
                        sg.uimgr.showUI("pop_titleTips", cfgT, type.Head_Frame);
                }
                else if (cfg.mainclass == type.Chat_Frame) {
                    let cfgT = sg.dbmgr.get("fashion_chatFrame", id);
                    if (cfgT)
                        sg.uimgr.showUI("pop_titleTips", cfgT, type.Chat_Frame);
                }
                else if (cfg.mainclass == type.GOD_FASHION) {
                    let cfgs = sg.dbmgr.getDB("god_godFashion");
                    for (let key in cfgs) {
                        if (cfgs[key].consume[0][0] == id) {
                            sg.uimgr.showUI("pop_godFashionTips", cfgs[key].id);
                            break;
                        }
                    }
                }
                else if (cfg.mainclass == type.Egg_Shell) {
                    sg.uimgr.showUI("pop_shellTips", cfg.id);
                }
                else
                    sg.uimgr.showUI("pop_itemTips", id);
            }
        }
    }
    mvc.SysSeniorLottery = SysSeniorLottery;
})(mvc || (mvc = {}));

