(function (mvc) {
    class UnitReturnLotto extends ui.view.returnActivity.unit_returnLotteryUI {
        onAwake() {
            super.onAwake();
            this._model = mvc.returnActivityModel;
            this.on(Laya.Event.CLICK, this, this._onClick);
        }
        onEnable() {
            super.onEnable();
            this._model.playing = false;
            this.updateView();
            this._initModel();
            this.cboxNotAni.selected = this._model.skipAni;
        }
        onDisable() {
            super.onDisable();
        }
        closeSelf() {
            if (this._model.playing) {
                sg.uimgr.showNotice(sg.translate("正在抽奖中"));
                return;
            }
            super.closeSelf();
        }
        _initModel() {
            this.unitModel.setEndHandle(null, () => {
                this.unitModel.visible = false;
                this.rewardBg.visible = true;
            });
            this.unitModel.lableHandle = (obj) => {
                if (obj.name == "tan") {
                    this._endAni();
                }
            };
            this.unitModel.loadRole(9073, "UnitReturnLotto", false);
            this.unitModel.visible = false;
        }
        updateView() {
            this._vo = this._model.lottoVo;
            if (this._vo) {
                mgr.icon.drawTexture(mgr.icon.getIconPath(mgr.toolsMgr.getIconById(this._vo.item_id)), this.imgIcon);
                this.lblItemNum.text = mgr.toolsMgr.getCountById(this._vo.item_id) + "";
                this.imgGetAllTip.visible = this.imgNotCount.visible = false;
                if (this._vo.isGetAllGuaranteeByRound(1) && this._vo.isGetAllGuaranteeByRound(2)) {
                    this.boxLuck.visible = false;
                    if (this._vo.isGetSupremeReward()) {
                        this.imgGetAllTip.visible = true;
                    }
                    else {
                        this.imgNotCount.visible = true;
                    }
                }
                else {
                    this.boxLuck.visible = true;
                    this.fontClipCount.value = this._vo.total_guarantee_count - this._vo.guarantee_count + "";
                }
                this._updateBtn();
                this.updateGuaReward();
            }
        }
        _updateBtn() {
            if (!this._vo)
                return;
            this.imgIcon1.visible = true;
            this.redTipsOne.visible = this.redTipsTen.visible = false;
            let green = mgr.toolsMgr.getColor3("green").stringColor;
            let red = mgr.toolsMgr.getColor3("red").stringColor;
            this.lblLotterNum1.x = 67;
            this._cost1 = [];
            this._cost2 = [];
            this._cost1 = [[this._vo.item_id, this._vo.one_item]];
            this._cost2 = [[this._vo.item_id, this._vo.ten_item]];
            mgr.icon.drawTexture(mgr.icon.getIconPath(mgr.toolsMgr.getIconById(this._cost1[0][0])), this.imgIcon1);
            mgr.icon.drawTexture(mgr.icon.getIconPath(mgr.toolsMgr.getIconById(this._cost2[0][0])), this.imgIcon2);
            this.lblLotterNum1.text = this._cost1[0][1] + "";
            this.lblLotterNum2.text = this._cost2[0][1] + "";
            this.lblLotterNum1.color = mgr.toolsMgr.checkConsume(this._cost1) ? green : red;
            this.lblLotterNum2.color = mgr.toolsMgr.checkConsume(this._cost2) ? green : red;
            this.redTipsOne.visible = mgr.toolsMgr.checkConsume(this._cost1);
            this.redTipsTen.visible = mgr.toolsMgr.checkConsume(this._cost2);
            if (this._vo.free_count == 0) {
                this.imgIcon1.visible = false;
                this.lblLotterNum1.x = 46;
                this.lblLotterNum1.text = sg.translate("免费");
                this.lblLotterNum1.color = green;
                this.redTipsOne.visible = true;
            }
        }
        updateGuaReward() {
            let id = this._model.lottoVo.select_guarantee_id;
            if (!id) {
                this.itemChoice.visible = false;
                this.lblOwn.text = sg.translate("选择保底奖励");
                this.unitFinger.visible = true;
                this.unitFinger.ani1.play(0, true);
            }
            else {
                this.itemChoice.visible = true;
                let cfg = sg.dbmgr.getArray("return_returnLotteryNormalRe", { ID: id, turn: mvc.returnActivityModel.mainVo.round })[0];
                let vos = mvc.ItemVo.createItemVos([[cfg.reward_id, cfg.reward]]);
                this.itemChoice.initView(vos[0]);
                this.lblOwn.text = mgr.toolsMgr.getNameById(cfg.reward_id);
                this.unitFinger.visible = false;
                this.unitFinger.ani1.stop();
            }
            this.boxChoice.visible = !this._vo.isGetAllGuaranteeByRound(2);
        }
        onLottery(time) {
            if (!this._vo.isGetAllGuaranteeByRound(2) && !this._vo.select_guarantee_id) {
                sg.uimgr.showNotice(sg.translate("请先选择保底奖励"));
                return;
            }
            if (this._vo && this._vo.free_count == 0 && time == 1) {
                mvc.returnActivityCtrl.reqLotto(1);
                return;
            }
            let cost = time == 10 ? this._cost2 : this._cost1;
            if ((cost && cost.length > 0)) {
                if (cost[0][0] == 1 && this._vo && this._vo.total_buy_count - this._vo.buy_count < time) {
                    let str = mgr.toolsMgr.getGlobalVoById("bgActivity_gold_tips", 1)[0];
                    sg.uimgr.showNotice(str);
                    return;
                }
                if (mgr.toolsMgr.checkConsume(cost, true)) {
                    mvc.returnActivityCtrl.reqLotto(time);
                }
            }
        }
        playAni(rewards) {
            if (this.cboxNotAni.selected) {
                sg.uimgr.showUI("pop_returnLotteryResult", rewards);
            }
            else {
                mvc.returnActivityModel.playing = true;
                this._curRewards = rewards;
                this.unitModel.visible = true;
                this.rewardBg.visible = false;
                if (rewards.length == 1)
                    this.unitModel.play("stand1", false);
                else
                    this.unitModel.play("stand10", false);
            }
        }
        _endAni() {
            sg.uimgr.showUI("pop_returnLotteryResult", this._curRewards);
        }
        _onClick(e) {
            switch (e.target) {
                case this.btnDetails:
                    {
                        sg.uimgr.showUI("pop_returnLotteryPool");
                    }
                    break;
                case this.btnLotterOne:
                    {
                        this.onLottery(1);
                    }
                    break;
                case this.btnLotterTen:
                    {
                        this.onLottery(10);
                    }
                    break;
                case this.btnAdd:
                    {
                        if (this._vo)
                            sg.uimgr.showAccess(this._vo.item_id);
                    }
                    break;
                case this.cboxNotAni:
                    {
                        this._model.skipAni = this.cboxNotAni.selected;
                    }
                    break;
                case this.boxChoice:
                    {
                        sg.uimgr.showUI("pop_returnChoice");
                    }
                    break;
            }
        }
    }
    mvc.UnitReturnLotto = UnitReturnLotto;
})(mvc || (mvc = {}));

