(function (mvc) {
    class UnitReturnNormlltem extends ui.view.returnActivity.unit_returnNormlltemUI {
        initView(config, buyInfo) {
            this._config = config;
            this._buyInfo = buyInfo;
            this._updateView();
            this.btnBuy.on(Laya.Event.CLICK, this, this._onBtnClick);
        }
        onEnable() {
            this.listReward.itemRender = mvc.UnitItemBox;
            this.listReward.renderHandler = this.createHandler(this, this._onListRewardRender, null, false);
        }
        _updateView() {
            if (this._config == null) {
                return;
            }
            let data = this._config;
            let info = this._buyInfo;
            let buyCount = 0;
            let limit = 0;
            let limitStr = "";
            this.lblName.text = data.name;
            if (data.dayTime > 0) {
                buyCount = info ? info.dayCount : buyCount;
                limit = data.dayTime;
                limitStr = sg.translate("每日限购");
            }
            else {
                if (data.limitTime > 0) {
                    limitStr = sg.translate("限购");
                    buyCount = info ? info.count : buyCount;
                    limit = data.limitTime;
                }
                else {
                    limitStr = sg.translate("无限购");
                }
            }
            this.imgIcon.visible = false;
            this.btnBuy.label = "";
            if (data.set_id == 0) {
                if (data.gold == 0) {
                    this.btnBuy.label = sg.translate("免费");
                    this.redTips.visible = buyCount < limit;
                }
                else {
                    this.imgIcon.visible = true;
                    this.redTips.visible = buyCount < limit && mgr.toolsMgr.getCountById(1) >= data.gold;
                    let goldNum = data.gold;
                    this.btnBuy.label = `${goldNum}`;
                    mgr.icon.drawTexture(mgr.icon.getIconPath(mgr.toolsMgr.getIconById(1)), this.imgIcon);
                }
            }
            else {
                this.redTips.visible = false;
                this.btnBuy.label = mgr.gplatform.showPriceByGearId(data.set_id);
            }
            this._isCanGet = limit == 0 || buyCount < limit;
            let str = limit == 0 ? limitStr : (limitStr + (limit - buyCount) + "/" + limit);
            this.lblLimit.text = str;
            this.lblLimit.color = (limit == 0 || limit - buyCount > 0) ? mgr.toolsMgr.getColor2("green") : mgr.toolsMgr.getColor2("red");
            this.btnBuy.disabled = (limit > 0 && limit - buyCount <= 0);
            this.listReward.array = data.reward;
        }
        _onListRewardRender(item, index) {
            if (item.dataSource == null) {
                return;
            }
            item.initViewCfg(item.dataSource);
        }
        _onBtnClick(event) {
            let data = this._config;
            if (!data || !this._isCanGet) {
                return;
            }
            if (data) {
                if ((sg.time.getSecondTime() - mvc.returnActivityModel.mainVo.end_time) > 0) {
                    sg.uimgr.showNotice(sg.translate("活动已结束"));
                    return;
                }
                if (data.set_id == 0) {
                    if (data.money == 0 || mgr.toolsMgr.checkConsume([[1, data.gold]], true)) {
                        mvc.mainModel.consumeJade([[1, data.gold]], 1, () => {
                            mvc.returnActivityCtrl.reqBackGiftReceiveReward(data.id);
                        });
                    }
                }
                else {
                    mvc.rechargeCtrl.reqRechargeByPhpEx(data.set_id);
                }
            }
        }
    }
    mvc.UnitReturnNormlltem = UnitReturnNormlltem;
})(mvc || (mvc = {}));

