(function (mvc) {
    class UnitReturnNormlltemNew extends ui.view.returnActivity.unit_returnNormlltemNewUI {
        initView(data, info, isGet) {
            this._config = data;
            this._info = info;
            this._isGet = isGet;
            this._updateView();
        }
        onEnable() {
            super.onEnable();
            this.btnGet.on(Laya.Event.CLICK, this, this._onBtnClick);
            this.btnGo.on(Laya.Event.CLICK, this, this._onBtnClick);
            this.listReward.renderHandler = this.createHandler(this, this._onListRewardRender, null, false);
        }
        _updateView() {
            if (this._config == null) {
                return;
            }
            this.lblName.text = this._config.name;
            this.listReward.array = this._config.rewards;
            this.prog.maxValue = this._config.progress;
            if (this._isGet) {
                this.btnGo.visible = false;
                this.redTips.visible = false;
                this.btnGet.visible = true;
                this.btnGet.disabled = true;
                this.prog.value = this._config.progress;
            }
            else {
                if (this._info) {
                    this.prog.value = this._info.progress;
                }
                else {
                    this.prog.value = 0;
                }
                this._complete = this.prog.value >= this.prog.maxValue;
                this.btnGet.visible = this._complete;
                this.btnGo.visible = !this._complete;
                this.redTips.visible = this.btnGet.visible;
                this.btnGet.disabled = false;
            }
            this.prog.label = this.prog.value + '/' + this.prog.maxValue;
        }
        _onListRewardRender(item, index) {
            if (item.dataSource == null) {
                return;
            }
            item.initViewCfg(item.dataSource);
        }
        _onBtnClick(event) {
            if (this._config == null) {
                return;
            }
            switch (event.target) {
                case this.btnGet:
                    mvc.returnActivityCtrl.reqBackTaskSubmit(this._config.id);
                    break;
                case this.btnGo:
                    if (this._config.tips.length > 0) {
                        sg.uimgr.showNotice(this._config.tips);
                    }
                    else {
                        if (this._config.link == "pop_guildHunting") {
                            if (mvc.roleModel.roleInfo.guildId == 0) {
                                sg.uimgr.showNotice(sg.translate("请先加入仙盟"));
                                return;
                            }
                        }
                        sg.uimgr.jumpUI(this._config.link[1], { layer: this._config.link[2], funId: this._config.link[3] });
                    }
                    break;
            }
        }
    }
    mvc.UnitReturnNormlltemNew = UnitReturnNormlltemNew;
})(mvc || (mvc = {}));

