var mvc;
(function (mvc) {
    class UnitReturnTaskPanel extends ui.view.returnActivity.unit_returnTaskUI {
        initView() {
            this._model = mvc.returnActivityModel;
            this._vo = this._model.taskVo;
        }
        initModelEvent() {
            this.bindModelEvent(this._model, mvc.ReturnActivityConst.EVT.RETURN_ACT_TASK_INIT, this._updateView);
            this.bindModelEvent(this._model, mvc.ReturnActivityConst.EVT.RETURN_ACT_TASK_BOX_UPDATE, this._updateView);
            this.bindModelEvent(this._model, mvc.ReturnActivityConst.EVT.RETURN_ACT_TASK_UPDATE, this._updateView);
        }
        initCtrlEvent() {
            this.listTask.vScrollBarSkin = "";
            this.listTask.itemRender = mvc.UnitReturnNormlltemNew;
            this.listTask.renderHandler = this.createHandler(this, this._onTaskList, null, false);
            this.listReward.selectEnable = true;
            this.listReward.selectHandler = this.createHandler(this, this._onBoxSelectClick, null, false);
            this.listReward.renderHandler = this.createHandler(this, this._onBoxList, null, false);
            this.listTab.hScrollBarSkin = null;
            this.listTab.renderHandler = this.createHandler(this, this._onListTabRender, null, false);
            this.listTab.selectHandler = this.createHandler(this, this._onTabSelect, null, false);
            this.listTab.spaceX = 4;
            this.listTab.selectEnable = true;
        }
        updateWhenNetReConn() {
            this._updateView();
        }
        onEnable() {
            super.onEnable();
            this._selectDay = 1;
            this.initView();
            this.initModelEvent();
            this.initCtrlEvent();
            this._boxPointConfig = this._vo.getBoxConfig();
            this.listReward.array = this._boxPointConfig;
            this._maxIntegral = this._boxPointConfig[this._boxPointConfig.length - 1].point;
            this.proTask.value = Math.min(this._vo.integral / this._maxIntegral, 1);
            this._updateView();
            this._onTabSelect(0);
        }
        _onTaskList(cell, idx) {
            let data = cell.dataSource;
            if (!data)
                return;
            cell.initView(data, this._vo.getAccepted(data.id), this._vo.getTaskStateById(data.id));
        }
        _onBoxList(cell, idx) {
            let data = cell.dataSource;
            if (!data)
                return;
            let on = cell.getChildByName("on");
            let item = cell.getChildByName("item");
            let popNum = cell.getChildByName("popNum");
            on.visible = this._vo.integral >= data.point;
            popNum.text = data.point;
            item.initViewCfg(data.reward[0], false);
            item.setRedTips(this._vo.isGetBoxReward(data));
        }
        _onListTabRender(btn, index) {
            if (btn.dataSource == null) {
                return;
            }
            let day = btn.dataSource;
            btn.label = StringEx.format(sg.translate("第${day}天"), {"day":day});
            let lock = btn.getChildByName('lock');
            let redot = btn.getChildByName('redot');
            if (lock) {
                lock.visible = day > this._vo.day;
            }
            if (redot && day <= this._vo.day) {
                redot.visible = this._vo.taskRedNumToDay(day) == 1;
            }
            btn.selected = btn.dataSource == this._selectDay;
        }
        _onTabSelect(idx) {
            let day = this.listTab.array[idx];
            if (day > this._vo.day) {
                sg.uimgr.showNotice(sg.translate("请等待至对应天数"));
                return;
            }
            this._selectDay = day;
            let cfg = this._vo.getConfigToday(day);
            this._vo.sortTaskList(cfg);
            this.listTask.array = cfg;
            this.listTab.refresh();
        }
        _updateView() {
            this._updateTask();
            this._updateBox();
            this._updateTab();
        }
        _updateBox() {
            this.proTask.value = Math.min(this._vo.integral / this._maxIntegral, 1);
            this.listReward.array = this._boxPointConfig;
        }
        _updateTask() {
            let day = this._selectDay;
            let cfg = this._vo.getConfigToday(day);
            this._vo.sortTaskList(cfg);
            this.listTask.array = cfg;
        }
        _updateTab() {
            let config = this._vo.getConfig();
            let dayInfo = [];
            if (config) {
                let day = 1;
                for (let k in config.config) {
                    dayInfo.push(day++);
                }
            }
            this.listTab.array = dayInfo;
        }
        _onBoxSelectClick(index) {
            let data = this.listReward.array[index];
            if (data == null)
                return;
            if (this._vo.isGetBoxReward(data)) {
                mvc.returnActivityCtrl.reqBackTaskReward(data.id);
            }
            else {
                sg.uimgr.showUI("pop_guildRewardPre", data.reward, sg.translate("重聚豪礼"));
            }
        }
    }
    mvc.UnitReturnTaskPanel = UnitReturnTaskPanel;
})(mvc || (mvc = {}));

