(function (mvc) {
    class UnitSeniorLoginItem extends ui.view.returnActivity.unit_seniorLoginItemUI {
        initView(vo) {
            this._vo = vo;
            this._isCanGet = false;
            this._updateView();
        }
        initCtrlEvent() {
        }
        _updateView() {
            let v1 = this._vo.day;
            if (sg.langMgr.getCode() == "ko")
                v1 = this._vo.day;
            this.lbDay.value = v1;
            let vo = mvc.returnActivityModel.seniorLoginVo;
            let vos = mvc.ItemVo.createItemVos(this._vo.reward);
            let cfg = vos[0].getCfg();
            if (cfg.id < 100) {
                this.lblName.text = cfg.show_name;
            }
            else {
                this.lblName.text = cfg.name;
            }
            let received = vo.received;
            let isClickEvt = true;
            this.imgState.visible = this.imgGrey.visible = this.alreadyGet.visible = false;
            if (this._vo.day <= vo.login_day) {
                if (this._vo.day > vo.received) {
                    this.imgState.visible = true;
                    isClickEvt = false;
                }
                else {
                    this.imgGrey.visible = this.alreadyGet.visible = true;
                }
            }
            this.itemReward.initView(vos[0], isClickEvt);
            this.itemReward.setRedTips(this._vo.day > received && this._vo.day <= vo.login_day);
            let isGet = this._vo.day <= received;
            this._isCanGet = this._vo.day <= vo.login_day && !isGet;
        }
        _onClick() {
            if (!this._isCanGet)
                return;
            let vo = mvc.returnActivityModel.seniorLoginVo;
            if (vo.end_time < sg.time.getTime() / 1000) {
                sg.uimgr.showNotice(sg.translate("活动已结束"));
                return;
            }
            let day = vo.received + 1;
            if (day != this._vo.day) {
                sg.uimgr.showNotice(sg.translate("请先领取前面的签到奖励"));
                return;
            }
            mvc.sevenDaysCtrl.reqLoginReward(day);
        }
    }
    mvc.UnitSeniorLoginItem = UnitSeniorLoginItem;
})(mvc || (mvc = {}));

