var mvc;
(function (mvc) {
    class RoleInfoVo extends sg.VoBase {
        constructor() {
            super(...arguments);
            this.lastLv = 0;
            this.exp = 0;
            this.serverId = 0;
            this.assestMap = new Map();
        }
        updateData(data) {
            let basic = data.basic;
            if (basic) {
                this.playerId = basic.player_id;
                this.account = basic.account;
                this.sex = basic.sex;
                this.wxHeadIconUrl = basic.head_icon;
                if (this.lastLv)
                    this.lastLv = this.level;
                else
                    this.lastLv = basic.level;
                this.level = basic.level;
                this.name = basic.name;
                this.serverId = basic.svr_id;
                this.openDayServer = data.days_to_open;
                this.area = basic.area;
                this.division = basic.division;
                sg.varmgr.setUserStoreKey(this.playerId);
            }
            if (data.create_time) {
                this.createTime = data.create_time;
            }
            this.mergeServeTime = data.merge_time;
        }
        updateRoleAttrInfo(data) {
            this.updateAttr(data.attr);
        }
        changeRoleInfo(pb, source) {
            let BaseInfoID = mvc.RoleConst.BaseInfoID;
            let changeLvOrExp = false;
            for (let key in pb) {
                let info = pb[key];
                let baseCfg = sg.dbmgr.get("player_base", info[0]);
                if (!baseCfg) {
                    console.error("player_base id lost", info[0]);
                    continue;
                }
                switch (info[0]) {
                    case BaseInfoID.LEVEL:
                        if (this.level && this.level < info[1]) {
                            this.lastLv = this.level;
                            this[baseCfg.c_name] = info[1];
                            mvc.roleModel.fireEvent(mvc.RoleConst.EVT.LEVEL_UP);
                            mvc.roleModel.clearBreakTaskInfo();
                            changeLvOrExp = true;
                            mgr.gplatform.sdkUploadUserData(sdk.UPLOAD_STATUS.ROLE_LV_UP);
                        }
                        mgr.redotMgr.check(mvc.REDOT_ID.ACT_MINE_SWEEP);
                        break;
                    case BaseInfoID.EXP:
                        {
                            let num = info[1] - this.exp;
                            if (num && num > 0) {
                                let assGetArr = [];
                                let obj = {
                                    "id": mvc.AssetsID.EXP,
                                    "addNum": num,
                                };
                                assGetArr.push(obj);
                            }
                            this.exp = info[1];
                            mvc.roleModel.fireEvent(mvc.RoleConst.EVT.EXP_CHANGE);
                            changeLvOrExp = true;
                        }
                        break;
                    case BaseInfoID.HEAD_FRAME_CHANGE:
                        this[baseCfg.c_name] = info[1];
                        mvc.roleModel.fireEvent(mvc.RoleConst.EVT.UPDATE_HEAD_FRAME);
                        break;
                    case BaseInfoID.SEX:
                        this[baseCfg.c_name] = info[1];
                        mvc.roleModel.fireEvent(mvc.RoleConst.EVT.CHANGE_SEX);
                        break;
                    case BaseInfoID.CHARGE:
                        this[baseCfg.c_name] = info[1];
                        mvc.roleModel.fireEvent(mvc.RoleConst.EVT.CHANGE_CHARGE);
                        break;
                    case BaseInfoID.GUILD:
                        {
                            this.guildId = info[1][0];
                            this.guildJoinTime = info[1][1];
                        }
                        break;
                }
                this[baseCfg.c_name] = info[1];
            }
            if (changeLvOrExp) {
                let cfg = sg.dbmgr.get("role_roleLevel", this.level);
                if (cfg && cfg.experience && this.exp >= cfg.experience) {
                    mvc.roleModel.fireEvent(mvc.RoleConst.EVT.PO_JING, true);
                }
                else {
                    mvc.roleModel.fireEvent(mvc.RoleConst.EVT.PO_JING, false);
                }
            }
            mvc.roleModel.fireEvent(mvc.RoleConst.EVT.CREATE_ROLE);
        }
        changeAssest(pb, source) {
            let assGetArr = [];
            for (let info of pb) {
                let id = info[0];
                let num = info[1];
                let cfg = sg.dbmgr.get("vitem", id);
                if (!cfg) {
                    console.error("物品id不存在:" + id);
                    continue;
                }
                let assestNum = this.assestMap.has(id) ? this.assestMap.get(id) : 0;
                if (assestNum < num) {
                    let addNum = num - assestNum;
                    assGetArr.push({
                        id: id,
                        addNum: addNum
                    });
                }
                this.assestMap.set(id, num);
                switch (id) {
                    case mvc.AssetsID.GOLD:
                        mgr.redotMgr.check(mvc.REDOT_ID.RULE_WORLD_SKILL);
                        break;
                    case mvc.AssetsID.PILL:
                        mgr.redotMgr.check(mvc.REDOT_ID.MANOR_BUY_BOY);
                        break;
                    case mvc.AssetsID.MERIT:
                        {
                            mgr.redotMgr.check(mvc.REDOT_ID.BLOOD);
                        }
                        break;
                    case mvc.AssetsID.EGG:
                        {
                            mgr.redotMgr.check(mvc.REDOT_ID.ISLAND_PET);
                        }
                        break;
                }
            }
            mvc.roleModel.fireEvent(mvc.RoleConst.EVT.CHANGE_ASSTE);
        }
        getAssestNum(id) {
            if (this.assestMap.has(id)) {
                return this.assestMap.get(id);
            }
            else {
                return 0;
            }
        }
        updateAttr(data) {
            let arr = mvc.PropertyModel.praseProp(data, false, 1, true).filed;
            this.props = mvc.PropertyModel.prasePropByCfg(arr);
            this.props.sort((a, b) => {
                return a.id - b.id;
            });
        }
        getAttrByLv(lv, isNew = false) {
            let ret = [];
            for (let p of this.props) {
                if (mvc.PropertyModel.propLv(p.name) == lv) {
                    if (isNew) {
                        let info = new mvc.PropertyVo();
                        info.id = p.id;
                        info.isPer = p.isPer;
                        info.nameStr = p.nameStr;
                        info.value = p.value;
                        info.is_per = p.is_per;
                        ret.push(info);
                    }
                    else
                        ret.push(p);
                }
            }
            return ret;
        }
    }
    mvc.RoleInfoVo = RoleInfoVo;
})(mvc || (mvc = {}));

