                return;
            sg.uimgr.showUI("pop_wxGet");
            mgr.gplatform.getUserHeadInfo((suc, userInfo) => {
                sg.uimgr.closeUI("pop_wxGet");
                if (suc && userInfo && userInfo.avatarUrl) {
                    mvc.roleModel.setRoleWxHead(userInfo.avatarUrl, userInfo.nickName);
                    mgr.gplatform.checkImg(userInfo.avatarUrl, Laya.Handler.create(this, (suc, trace_id) => {
                        window["MyGame"].openLog && mgr.gplatform.log(suc, sg.translate("=检查图片="), trace_id);
                    }));
                }
                cbk && cbk(suc, userInfo);
            }, forceNew);
