(function (mvc) {
    class UnitBreakTaskItem extends ui.view.role.unit_breakTaskItemUI {
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            this.btnGo.on(Laya.Event.CLICK, this, this._onBtnGo);
        }
        onDisable() {
            super.onDisable();
            this.off(Laya.Event.CLICK, this, this._onBtnGo);
        }
        get dataSource() {
            return super.dataSource;
        }
        set dataSource(id) {
            super.dataSource = id;
            if (!id)
                return;
            let cfg = sg.dbmgr.get("role_brokenTask", id);
            let cur = mvc.roleModel.breakTask.get(id) || 0;
            let need = cfg.condition[cfg.condition.length - 1];
            let isComplete = cur >= need;
            if (cfg.condition[0] == "broken_boss") {
                this.lblTask.text = cfg.name;
                this.lblProg.text = "";
                this.imgPerfact.visible = mvc.roleModel.isPerfact;
            }
            else {
                this.imgPerfact.visible = false;
                this.lblTask.text = cfg.name;
                this.lblProg.text = "(" + cur + "/" + need + ")";
                this.lblProg.color = isComplete ? mvc.COLOR.GREEN : "#ce0f0f";
            }
            this.imgOK.visible = isComplete;
            this.btnGo.visible = !isComplete;
            let url = isComplete ? "ui/common/pannel/img_bf_com_list_l.png" : "ui/common/pannel/img_bf_xl_1.png";
            mgr.icon.drawTexture(url, this.imgBg);
        }
        _onBtnGo() {
            let id = this.dataSource;
            if (!id)
                return;
            let cfg = sg.dbmgr.get("role_brokenTask", id);
            if (cfg.condition[0] == "broken_boss") {
                sg.uimgr.showUI("pop_dungeonBreak", id, cfg.condition[1]);
            }
            else {
                sg.uimgr.closeUI("pop_breakTask");
                sg.uimgr.jumpUI(cfg.jump[0], { layer: 0, funId: cfg.jump[1] });
            }
        }
    }
    mvc.UnitBreakTaskItem = UnitBreakTaskItem;
})(mvc || (mvc = {}));

