var mvc;
(function (mvc) {
    class PopgodChangeSkillTop extends ui.view.god.pop_wuxingChangeUI {
        constructor() {
            super();
            this._model = mvc.godModel;
            this._ctrl = mvc.godCtrl;
        }
        initView() {
            this._myFormation = mvc.topArenaModel.vo.myFormation;
        }
        initModelEvent() {
            this.bindModelEvent(mvc.battleModel, mvc.BattleConst.EVT.FORMATION_INFO_SAVE, this._updateView);
            this.bindModelEvent(mvc.battleModel, mvc.BattleConst.EVT.FORMATION_INFO_SAVE_UPDATE, this._updateView);
        }
        initCtrlEvent() {
            this.list.renderHandler = this.createHandler(this, this._listRenderer, undefined, false);
            this.list.selectHandler = this.createHandler(this, this._listSelectHandle, undefined, false);
            this.list.vScrollBarSkin = "";
            this.btnSwitch.on(Laya.Event.CLICK, this, this._onBtnSwitch);
            this.btnPreview.on(Laya.Event.CLICK, this, this._onBtnSkillPre);
        }
        onAwake() {
            super.onAwake();
            this.lblSkillEmpty.text = sg.translate("无激活魂技");
        }
        onEnable() {
            super.onEnable();
            this._updateView();
        }
        _updateView() {
            if (this._myFormation == null) {
                return;
            }
            let gods1 = this._myFormation.gods;
            let gods = [];
            let skillMap = {};
            for (let pos = 0; pos < 2; pos++) {
                let id = gods1[pos].god_id;
                if (id) {
                    let vo = this._model.godMap.get(id);
                    if (vo)
                        gods.push(vo);
                }
            }
            let cur;
            if (gods.length == 2) {
                this.lblSkillEmpty.visible = false;
                this.boxSkill.visible = true;
                let id1 = gods[0].getSlotWuxing(gods1[0].combat_element);
                let id2 = gods[1].getSlotWuxing(gods1[1].combat_element);
                cur = this._model.getWuxingSkill(id1, id2);
                if (cur) {
                    let cfgSkill = sg.dbmgr.get("skill_skill", cur.skill);
                    let skillName = cfgSkill.name;
                    this.lblCurSkill.text = StringEx.format(sg.translate("当前魂技：${skillName}"), {"skillName":skillName});
                    this.lblSkillDesc.text = cfgSkill.desc;
                    let wuxingCfg = sg.dbmgr.get("god_element", cur.group[0]);
                    this.lblWuxing1.text = wuxingCfg.name;
                    this.lblWuxing1.color = wuxingCfg.stringColor;
                    this.lblWuxing1.strokeColor = wuxingCfg.strokeColor;
                    wuxingCfg = sg.dbmgr.get("god_element", cur.group[1]);
                    this.lblWuxing2.text = wuxingCfg.name;
                    this.lblWuxing2.color = wuxingCfg.stringColor;
                    this.lblWuxing2.strokeColor = wuxingCfg.strokeColor;
                }
                else {
                    this.lblCurSkill.text = StringEx.format(sg.translate("当前魂技：无"));
                    this.boxSkill.visible = false;
                    this.lblSkillEmpty.visible = true;
                }
                for (let ele1 of gods[0].cfg.soulElement) {
                    for (let ele2 of gods[1].cfg.soulElement) {
                        let skill = this._model.getWuxingSkill(ele1[1], ele2[1]);
                        if (!skill)
                            continue;
                        let isUnlock = true;
                        let slot1 = gods[0].soulMap.get(ele1[0]);
                        if (!slot1 || !slot1.is_unlock) {
                            isUnlock = false;
                        }
                        let slot2 = gods[1].soulMap.get(ele2[0]);
                        if (!slot2 || !slot2.is_unlock) {
                            isUnlock = false;
                        }
                        if (skillMap[skill.id] && skillMap[skill.id].isUnlock == true)
                            continue;
                        skillMap[skill.id] = {
                            god1: gods[0],
                            god2: gods[1],
                            slot1: ele1,
                            slot2: ele2,
                            skill: skill,
                            isUnlock: isUnlock
                        };
                    }
                }
            }
            else {
                this.lblCurSkill.text = StringEx.format(sg.translate("当前魂技：无"));
                this.boxSkill.visible = false;
                this.lblSkillEmpty.visible = true;
            }
            let arr = [];
            let cfgs = sg.dbmgr.getDB("god_elementGroup");
            for (let key in cfgs) {
                let cfg = cfgs[key];
                if (cur && cfg.id == cur.id)
                    continue;
                let sort = 2;
                let gInfo = skillMap[cfg.id];
                if (gInfo) {
                    sort = gInfo.isUnlock ? 0 : 1;
                }
                arr.push({
                    cfg: cfg,
                    godInfo: gInfo,
                    sort: sort
                });
            }
            arr.sort((a, b) => {
                return a.sort - b.sort;
            });
            this.list.array = arr;
            this.list.selectedIndex = -1;
        }
        onDisable() {
            super.onDisable();
        }
        _listRenderer(cell) {
            let data = cell.dataSource;
            if (!data)
                return;
            let boxMain = cell.getChildByName("boxMain");
            let lblWuxing1 = boxMain.getChildByName("lblWuxing1");
            let lblWuxing2 = boxMain.getChildByName("lblWuxing2");
            let lblDesc = boxMain.getChildByName("lblDesc");
            let cfgWuxing = sg.dbmgr.get("god_element", data.cfg.group[0]);
            lblWuxing1.text = cfgWuxing.name;
            lblWuxing1.color = cfgWuxing.stringColor;
            lblWuxing1.strokeColor = cfgWuxing.strokeColor;
            cfgWuxing = sg.dbmgr.get("god_element", data.cfg.group[1]);
            lblWuxing2.text = cfgWuxing.name;
            lblWuxing2.color = cfgWuxing.stringColor;
            lblWuxing2.strokeColor = cfgWuxing.strokeColor;
            let skillCfg = sg.dbmgr.get("skill_skill", data.cfg.skill);
            lblDesc.text = skillCfg.desc;
            boxMain.gray = !data.godInfo || !data.godInfo.isUnlock;
        }
        _listSelectHandle(idx) {
            if (idx == -1) {
                this.btnSwitch.disabled = true;
                this.lblSwitch.text = sg.translate("选择五行组合方案切换后，神仙会自动设置相应的出战五行属性");
            }
            let data = this.list.getItem(idx);
            if (!data)
                return;
            if (!data.godInfo) {
                this.btnSwitch.disabled = true;
                this.lblSwitch.text = sg.translate("当前上阵神仙无法激活本技能");
            }
            else if (!data.godInfo.isUnlock) {
                this.btnSwitch.disabled = true;
                this.lblSwitch.text = sg.translate("神仙解锁更高阶命魂后，获得新五行属性可激活本技能");
            }
            else {
                this.btnSwitch.disabled = false;
                this.lblSwitch.text = sg.translate("选择五行组合方案切换后，神仙会自动设置相应的出战五行属性");
            }
        }
        _onBtnSwitch() {
            let data = this.list.selectedItem;
            if (!data || !data.godInfo || !data.godInfo.isUnlock)
                return;
            let godInfo = data.godInfo;
            let gods1 = this._myFormation.gods;
            let last = 0;
            if (gods1[0] && gods1[0].combat_element != godInfo.slot1[0]) {
                mvc.topArenaModel.reqChangeGodUseSlot(godInfo.god1.id, godInfo.slot1[0]);
                last = godInfo.god1.id;
            }
            if (gods1[1] && godInfo.slot2[0] != gods1[1].combat_element) {
                mvc.topArenaModel.reqChangeGodUseSlot(godInfo.god2.id, godInfo.slot2[0]);
                last = godInfo.god2.id;
            }
            this._model.lastSlot = last;
        }
        _onBtnSkillPre() {
            sg.uimgr.showUI("pop_godSkillPre");
        }
    }
    mvc.PopgodChangeSkillTop = PopgodChangeSkillTop;
})(mvc || (mvc = {}));

var mvc;
(function (mvc) {
    class PopTopArenaAddBet extends ui.view.topArena.pop_addCoinsUI {
        initView(site) {
            this._model = mvc.topArenaModel;
            this._ctrl = mvc.topArenaCtrl;
            this._site = site;
        }
        initSendMsg() {
        }
        initModelEvent() {
        }
        initCtrlEvent() {
            this.btnOk.on(Laya.Event.CLICK, this, this._onBtnOK);
            this.btnAddTen.on(Laya.Event.CLICK, this, this._onBtnAddTen);
            this.btnSubTen.on(Laya.Event.CLICK, this, this._onBtnSubTen);
        }
        onAwake() {
            super.onAwake();
            let icon = mgr.toolsMgr.getIconById(mvc.MainConst.ITEM_ID.TOP_ARENA_COIN);
            icon = mgr.icon.getIconPath(icon);
            mgr.icon.drawTexture(icon, this.imgCoinIcon);
        }
        onEnable() {
            super.onEnable();
            let vo = this._model.vo;
            this.lblCoin.text = vo.coin + "";
            let head = this._site == 1 ? vo.betInfo.group.head1 : vo.betInfo.group.head2;
            this._pid = head.player_id;
            this.lblName.text = `[S${head.svr_id}]${head.name}`;
            this.unitNum.minValue = 0;
            this.unitNum.maxValue = vo.coin;
            this.unitNum.openEditable(vo.coin);
            this.unitNum.textFunc = this._onValueChange.bind(this);
            let br = mgr.toolsMgr.getGlobalVoById("toparena_lossper_basics", 1);
            let f = mgr.toolsMgr.getGlobalVoById("toparena_lossper_coefficient", 1);
            let info = vo.betInfo;
            let c1 = info.bet_count1;
            let c2 = info.bet_count2;
            if (this._site == 1) {
                c1 += 1;
                this._radio = br - (c1 - c2) / Math.max(c1 + c2, 1) * f;
            }
            else {
                c2 += 1;
                this._radio = br + (c1 - c2) / Math.max(c1 + c2, 1) * f;
            }
            this.unitNum.value = 1;
        }
        onDisable() {
            super.onDisable();
        }
        _onBtnAddTen() {
            this.unitNum.value = this.unitNum.value + 10;
        }
        _onBtnSubTen() {
            this.unitNum.value = this.unitNum.value - 10;
        }
        _onValueChange(v) {
            this.lblAll.text = Math.floor(v + this._model.vo.betNum) + "";
            this.lblGet.text = Math.floor((v + this._model.vo.betNum) * this._radio) + "";
            return v + "";
        }
        _onBtnOK() {
            let v = this.unitNum.value;
            if (v <= 0) {
                sg.uimgr.showNotice(sg.translate("请选择确认数量"));
                return;
            }
            this._ctrl.reqBet(this._pid, v);
            this.closeSelf();
        }
    }
    mvc.PopTopArenaAddBet = PopTopArenaAddBet;
})(mvc || (mvc = {}));

