(function (mvc) {
    class PopTopArenaAutoBet extends ui.view.topArena.pop_autoBetUI {
        initView() {
            this._model = mvc.topArenaModel;
            this._ctrl = mvc.topArenaCtrl;
        }
        initSendMsg() {
        }
        initModelEvent() {
        }
        initCtrlEvent() {
            this.cbBet.scrollBarSkin = "";
            this.btnOK.on(Laya.Event.CLICK, this, this._onBtnOK);
        }
        onAwake() {
            super.onAwake();
            this.cbRule.labels = sg.translate("无,左侧,右侧,收益比高,收益比低");
            let betCfg = mgr.toolsMgr.getGlobalVoById("topArena_auto_bet_percent", 1);
            let strs = "";
            for (let rate of betCfg) {
                if (strs.length > 0) {
                    strs += ",";
                }
                let r = (rate / 100);
                strs += StringEx.format(sg.translate("已有竞猜币的${r}%"), {"r":r});
            }
            this.cbBet.labels = strs;
        }
        onEnable() {
            super.onEnable();
            let vo = this._model.vo;
            let aCfg = sg.dbmgr.get("activity", vo.type);
            let round = vo.curRound;
            this.boxRound.visible = true;
            if (round == 0 || vo.curState == mvc.TopArenaConst.RaceState.Battle || vo.curState == mvc.TopArenaConst.RaceState.End) {
                round++;
            }
            if (round >= aCfg.param["max_round"]) {
                if (vo.type == mvc.TopArenaConst.RaceType.Race4) {
                    this.boxRound.visible = false;
                }
                else {
                    round = 1;
                    aCfg = sg.dbmgr.get("activity", aCfg.param["next_id"]);
                    this.lblRound.text = this._model.getRaceName(aCfg.id, round);
                }
            }
            else {
                this.lblRound.text = this._model.getRaceName(aCfg.id, round);
            }
            this.cbRule.selectedIndex = vo.autoRule;
            let idx = 0;
            let betCfg = mgr.toolsMgr.getGlobalVoById("topArena_auto_bet_percent", 1);
            for (let i = 0; i < betCfg.length; i++) {
                if (betCfg[i] == vo.autoRate) {
                    idx = i;
                    break;
                }
            }
            this.cbBet.selectedIndex = idx;
            let maxNum = mgr.toolsMgr.getGlobalVoById("topArena_auto_bet_times", 1);
            this.lblNum.text = (maxNum - vo.autoNum) + "";
            this.lblNum.color = vo.autoNum < maxNum ? mvc.COLOR.GREEN : mvc.COLOR.RED;
        }
        onDisable() {
            super.onDisable();
        }
        _onBtnOK() {
            let betCfg = mgr.toolsMgr.getGlobalVoById("topArena_auto_bet_percent", 1);
            this._ctrl.reqSetAutoBet(this.cbRule.selectedIndex, betCfg[this.cbBet.selectedIndex]);
        }
    }
    mvc.PopTopArenaAutoBet = PopTopArenaAutoBet;
})(mvc || (mvc = {}));

