(function (mvc) {
    class PopTopArenaBetStart extends ui.view.topArena.pop_gambleShowUI {
        initView(info) {
            this._model = mvc.topArenaModel;
            this._ctrl = mvc.topArenaCtrl;
            this._info = info;
        }
        initSendMsg() {
        }
        initModelEvent() {
        }
        initCtrlEvent() {
            this.btnGo.on(Laya.Event.CLICK, this, this._onBtnGo);
        }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            let data = this._info.group;
            let head = data.head1;
            let iconPath = mgr.ComFunMgr.getHeadIcon(head.head_icon, head.sex);
            this.unitHead1.initView({ iconPath: iconPath, headFrameId: head.head_frame_id, level: head.level }, head.player_id);
            this.lblName1.text = `[S${head.svr_id}]${head.name}`;
            this.lblGuild1.text = head.guild_id ? head.guild_name : "";
            head = data.head2;
            iconPath = mgr.ComFunMgr.getHeadIcon(head.head_icon, head.sex);
            this.unitHead2.initView({ iconPath: iconPath, headFrameId: head.head_frame_id, level: head.level }, head.player_id);
            this.lblName2.text = `[S${head.svr_id}]${head.name}`;
            this.lblGuild2.text = head.guild_id ? head.guild_name : "";
            this._closeTime = 5;
            this.repeats(1000, this._onTimer, true);
        }
        onDisable() {
            super.onDisable();
        }
        _onTimer() {
            let t = this._closeTime;
            if (t > 0) {
                this.lblTime.text = StringEx.format(sg.translate("${t}秒后自动关闭"), {"t":t});
                this._closeTime--;
            }
            else {
                this.closeSelf();
            }
        }
        _onBtnGo() {
            this.closeSelf();
            sg.uimgr.showUI("pop_topArenaMain", 1);
        }
    }
    mvc.PopTopArenaBetStart = PopTopArenaBetStart;
})(mvc || (mvc = {}));

var mvc;
(function (mvc) {
    class PopTopArenaChangeArtifact extends ui.view.topArena.pop_artifactArrangeUI {
        initView() {
            this._model = mvc.topArenaModel;
            this._ctrl = mvc.topArenaCtrl;
        }
        initSendMsg() {
        }
        initModelEvent() {
        }
        initCtrlEvent() {
            this.list.renderHandler = this.createHandler(this, this._listRender, undefined, false);
            this.list.selectHandler = this.createHandler(this, this._onListSelect, undefined, false);
            this.list.vScrollBarSkin = "";
            this.btnEquip.on(Laya.Event.CLICK, this, this._onBtnEquip);
        }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            let f = this._model.vo.myFormation;
            this._cur = f.artifact.unique_id;
            let vos = mvc.bagModel.getItemsByType(mvc.BagConst.BagType.Artifact);
            vos.sort((a, b) => {
                let acfg = a.getCfg();
                let bcfg = b.getCfg();
                if (acfg.quality != bcfg.quality) {
                    return bcfg.quality - acfg.quality;
                }
                if (a.level != b.level) {
                    return b.level - a.level;
                }
                return a.id - b.id;
            });
            this.list.array = vos;
            if (vos.length > 0) {
                let idx = 0;
                for (let i = 0; i < vos.length; i++) {
                    if (vos[i].bagId == f.artifact.unique_id) {
                        idx = i;
                        break;
                    }
                }
                this.list.selectedIndex = idx;
            }
            else {
                this.list.selectedIndex = -1;
            }
        }
        onDisable() {
            this.list.selectedIndex = -1;
            this.list.array = undefined;
            super.onDisable();
            mvc.topArenaModel.fireEvent(mvc.TopArenaConst.EVT.FORMATION_NUM_CLEAR);
        }
        _onListSelect() {
            let data = this.list.selectedItem;
            if (!data) {
                this.unitIcon.visible = false;
                this.listAttr.array = undefined;
                this.imgSecret.visible = false;
                return;
            }
            this.unitIcon.visible = true;
            this.listAttr.array = mvc.PropertyModel.generateListData(data.attr);
            this.unitIcon.initView(data, false);
            if (data.level >= 0) {
                this.unitIcon.lblNum.text = "Lv." + data.level;
            }
            if (mvc.artifactModel.getIsInSecret(data.bagId)) {
                this.imgSecret.visible = true;
                let id = mvc.artifactModel.getSecretIdByBagId(data.bagId);
                let cfg = sg.dbmgr.get("artifact_secret", id);
                mgr.icon.drawTexture(mgr.icon.getIconPath(cfg.icon), this.imgSecret);
            }
            else {
                this.imgSecret.visible = false;
            }
            if (data.bagId == this._cur) {
                this.btnEquip.label = sg.translate("已装备");
                this.btnEquip.disabled = true;
            }
            else {
                this.btnEquip.label = sg.translate("更换");
                this.btnEquip.disabled = false;
            }
        }
        _listRender(cell) {
            let data = cell.dataSource;
            if (!data)
                return;
            let icon = cell.getChildByName("icon");
            let imgSecret = cell.getChildByName("imgSecret");
            icon.initView(data, false);
            if (data.level >= 0) {
                icon.lblNum.text = "Lv." + data.level;
            }
            if (mvc.artifactModel.getIsInSecret(data.bagId)) {
                imgSecret.visible = true;
                let id = mvc.artifactModel.getSecretIdByBagId(data.bagId);
                let cfg = sg.dbmgr.get("artifact_secret", id);
                mgr.icon.drawTexture(mgr.icon.getIconPath(cfg.icon), imgSecret);
            }
            else {
                imgSecret.visible = false;
            }
        }
        _onBtnEquip() {
            let item = this.list.selectedItem;
            if (!item || item.bagId == this._cur)
                return;
            this._model.reqSetArtifact(item.bagId);
            this.closeSelf();
        }
    }
    mvc.PopTopArenaChangeArtifact = PopTopArenaChangeArtifact;
})(mvc || (mvc = {}));

