var mvc;
(function (mvc) {
    class PopTopArenaChangeSword extends ui.view.topArena.pop_swordArrangeUI {
        initView() {
            this._model = mvc.topArenaModel;
            this._ctrl = mvc.topArenaCtrl;
        }
        initSendMsg() {
        }
        initModelEvent() {
        }
        initCtrlEvent() {
            this.listAttr.vScrollBarSkin = "";
            this.list.vScrollBarSkin = "";
            this.list.renderHandler = this.createHandler(this, this._listRender, undefined, false);
            this.list.selectHandler = this.createHandler(this, this._onListSelect, undefined, false);
            this.btnEquip.on(Laya.Event.CLICK, this, this._onBtnEquip);
        }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            this._cur = this._model.vo.myFormation.sword.id;
            let arr = [];
            let cfgs = sg.dbmgr.getDB("sword_sword");
            let vo = mvc.swordModel.getSwordVo();
            let swords = vo.swords;
            let idx = 0;
            for (let key in cfgs) {
                let cfg = cfgs[key];
                if (swords.indexOf(cfg.swordId) != -1) {
                    arr.push(cfg);
                    if (cfg.swordId == this._cur) {
                        idx = arr.length - 1;
                    }
                }
            }
            let attrs = vo.getShowAttr();
            let swordCfg = sg.dbmgr.get("sword_sword", vo.equip);
            if (swordCfg.secProp) {
                for (let a of swordCfg.secProp) {
                    let id = mvc.PropertyModel._getCfg(a[0]).id;
                    for (let ba of attrs) {
                        if (ba[0] == id) {
                            ba[1] -= a[1];
                            break;
                        }
                    }
                }
            }
            if (swordCfg.grdArr) {
                let grd = vo.grade;
                for (let a of swordCfg.grdArr) {
                    let id = mvc.PropertyModel._getCfg(a[0]).id;
                    for (let ba of attrs) {
                        if (ba[0] == id) {
                            ba[1] -= a[1] * grd;
                            break;
                        }
                    }
                }
            }
            this._basicAttrs = [];
            for (let a of attrs) {
                if (a[1] > 0) {
                    this._basicAttrs.push(a);
                }
            }
            this.list.array = arr;
            this.list.selectedIndex = idx;
        }
        onDisable() {
            this.list.array = null;
            this.list.selectedIndex = -1;
            super.onDisable();
            mvc.topArenaModel.fireEvent(mvc.TopArenaConst.EVT.FORMATION_NUM_CLEAR);
        }
        _listRender(cell) {
            let data = cell.dataSource;
            if (!data)
                return;
            let clipQua = cell.getChildByName("clipQua");
            let imgIcon = cell.getChildByName("imgIcon");
            clipQua.index = data.quality - 1;
            let url = mgr.icon.getIconPath(data.resMain);
            mgr.icon.drawTexture(url, imgIcon);
        }
        _onListSelect(idx) {
            let data = this.list.selectedItem;
            if (!data) {
                this.clipQua.index = 0;
                this.imgIcon.skin = "";
                this.lblName.text = "";
                this.lblLevel.text = "";
                this.listAttr.array = [];
                this.btnEquip.visible = false;
                return;
            }
            let vo = mvc.swordModel.getSwordVo();
            this.btnEquip.visible = true;
            this.clipQua.index = data.quality - 1;
            let url = mgr.icon.getIconPath(data.resMain);
            mgr.icon.drawTexture(url, this.imgIcon);
            let grade = vo.grade;
            let lv = vo.level;
            let v1 = grade;
            let v2 = lv;
            this.lblLevel.text = StringEx.format(sg.translate("${v1}阶${v2}级"), {"v1":v1,"v2":v2});
            this.lblName.text = data.name;
            mgr.toolsMgr.setLabelByQua(data.quality, this.lblName);
            let attrs = JSON.parse(JSON.stringify(this._basicAttrs));
            if (data.secProp) {
                for (let a of data.secProp) {
                    let isFind = false;
                    let id = mvc.PropertyModel._getCfg(a[0]).id;
                    for (let attr of attrs) {
                        if (attr[0] == id) {
                            isFind = true;
                            attr[1] += a[1];
                            break;
                        }
                    }
                    if (!isFind) {
                        attrs.push([id, a[1]]);
                    }
                }
            }
            if (data.grdArr) {
                let grd = vo.grade;
                for (let a of data.grdArr) {
                    let id = mvc.PropertyModel._getCfg(a[0]).id;
                    let isFind = false;
                    for (let attr of attrs) {
                        if (attr[0] == id) {
                            attr[1] += a[1] * grd;
                            isFind = true;
                            break;
                        }
                    }
                    if (!isFind) {
                        attrs.push([id, a[1]]);
                    }
                }
            }
            this.listAttr.array = mvc.PropertyModel.generateListData(attrs);
            if (this._cur == data.swordId) {
                this.btnEquip.label = sg.translate("已装备");
                this.btnEquip.disabled = true;
            }
            else {
                this.btnEquip.label = sg.translate("更换");
                this.btnEquip.disabled = false;
            }
        }
        _onBtnEquip() {
            let data = this.list.selectedItem;
            if (!data || data.swordId == this._cur)
                return;
            this._model.reqSetSword(data.swordId);
            this.closeSelf();
        }
    }
    mvc.PopTopArenaChangeSword = PopTopArenaChangeSword;
})(mvc || (mvc = {}));

var mvc;
(function (mvc) {
    let RaceState = mvc.TopArenaConst.RaceState;
    class PopTopArenaEnter extends ui.view.topArena.pop_topArenaEntranceUI {
        initView() {
            this._model = mvc.topArenaModel;
            this._ctrl = mvc.topArenaCtrl;
        }
        initSendMsg() {
        }
        initModelEvent() {
            this.bindModelEvent(this._model, mvc.TopArenaConst.EVT.UPDATE_RACE_INFO, this._updateView);
            this.bindModelEvent(this._model, mvc.TopArenaConst.EVT.UPDATE_LIKE_INFO, this._updateLikeInfo);
        }
        initCtrlEvent() {
            this.btnGo.on(Laya.Event.CLICK, this, this._onBtnEnter);
            this.btnRank.on(Laya.Event.CLICK, this, this._onBtnRank);
            this.btnDeifyOrder.on(Laya.Event.CLICK, this, this._onDeifyOrder);
            this.boxRole1.on(Laya.Event.CLICK, this, this._onBoxRole, [1]);
            this.boxRole2.on(Laya.Event.CLICK, this, this._onBoxRole, [2]);
            this.boxRole3.on(Laya.Event.CLICK, this, this._onBoxRole, [3]);
            this.btnLike1.on(Laya.Event.CLICK, this, this._onBtnLike, [1]);
            this.btnLike2.on(Laya.Event.CLICK, this, this._onBtnLike, [2]);
            this.btnLike3.on(Laya.Event.CLICK, this, this._onBtnLike, [3]);
        }
        onAwake() {
            super.onAwake();
            this.redTipsDeify.id = mvc.REDOT_ID.DEIFY_ORDER;
            this.btnDeifyOrder.visible = mgr.gplatform.isShowRecharge(0, 7502);
            if (mgr.gplatform.isViVeVersion()) {
                this.btnDeifyOrder.visible = false;
            }
        }
        onEnable() {
            super.onEnable();
            this._updateView();
            this._checkOpenRedbag();
        }
        onDisable() {
            super.onDisable();
        }
        _updateView() {
            let vo = this._model.vo;
            for (let i = 1; i <= 3; i++) {
                let p = vo.top3.get(i);
                let unitShowRole = this["unitShowRole" + i];
                let lblPlayerName = this["lblPlayerName" + i];
                let unitTitle = this["unitTitle" + i];
                let imgNo = this["imgNo" + i];
                if (p) {
                    let head = p.head;
                    unitShowRole.visible = true;
                    let skinCfg = sg.dbmgr.get("fashion_fashion", head.skin_id || 1);
                    let role = skinCfg.avatar[head.sex];
                    unitShowRole.updateRole(role);
                    lblPlayerName.text = `[S${head.svr_id}]${head.name}`;
                    let cfg = sg.dbmgr.filterLine("arena_rankReward", (id, data) => {
                        return data.type == 3 && data.resultType == 2 && data.beginIdx == i;
                    });
                    unitTitle.visible = true;
                    unitTitle.updateTitle(cfg.title);
                    imgNo.visible = false;
                }
                else {
                    unitShowRole.visible = false;
                    lblPlayerName.text = "";
                    unitTitle.visible = false;
                    imgNo.visible = true;
                }
            }
            this.stopTimer(this._onTimer);
            this.lblTime.visible = false;
            if (vo.curState == RaceState.None) {
                if (vo.type == mvc.TopArenaConst.RaceType.Race128) {
                    if (vo.isRaceOpen() && !this._model.isShowResult()) {
                        this._nextTime = this._model.getNextTime();
                    }
                    else {
                        let cfg = sg.dbmgr.get("activity", 1107);
                        this._nextTime = this._model.getNextTimeByCfg(cfg);
                    }
                    this.lblTime.visible = true;
                    this.repeats(1000, this._onTimer, true);
                }
            }
            if (vo.isRaceOpen() && !this._model.isShowResult()) {
                this.lblRace.text = this._model.getRaceName(vo.type, 0, false);
            }
            else {
                this.lblRace.text = sg.translate("未开始");
            }
            let rank = vo.rank;
            if (rank) {
                this.lblRank.text = this._getRankName(rank);
            }
            else {
                this.lblRank.text = sg.translate("未上榜");
            }
            this.lblTop.text = this._getRankName(vo.topRank);
            this._updateLikeInfo();
        }
        _getRankName(rank) {
            if (rank) {
                if (rank == 1) {
                    return StringEx.format(sg.translate("冠军"));
                }
                else if (rank == 2) {
                    return StringEx.format(sg.translate("亚军"));
                }
                else if (rank == 3) {
                    return StringEx.format(sg.translate("季军"));
                }
                else if (rank == 4) {
                    return StringEx.format(sg.translate("殿军"));
                }
                else if (rank <= 8) {
                    return StringEx.format(sg.translate("8强"));
                }
                else if (rank <= 16) {
                    return StringEx.format(sg.translate("16强"));
                }
                else if (rank <= 32) {
                    return StringEx.format(sg.translate("32强"));
                }
                else {
                    return StringEx.format(sg.translate("128强"));
                }
            }
            else {
                return sg.translate("未上榜");
            }
        }
        _onTimer() {
            let last = this._nextTime - sg.time.getSecondTime();
            if (last > 0) {
                let str = sg.time.formatTimeStrT("F10", last);
                this.lblTime.text = StringEx.format(sg.translate("(倒计时${str})"), {"str":str});
            }
            else {
                this.stopTimer(this._onTimer);
                this._ctrl.reqRaceInfo();
            }
        }
        _updateLikeInfo() {
            let vo = this._model.vo;
            for (let r = 1; r <= 3; r++) {
                let p = vo.top3.get(r);
                if (p) {
                    this["boxLike" + r].visible = true;
                    this["btnLike" + r].disabled = vo.isLike(r);
                    this["lblLike" + r].text = p.like;
                }
                else {
                    this["boxLike" + r].visible = false;
                }
            }
        }
        _onBtnEnter() {
            sg.uimgr.showUI("pop_topArenaMain");
            this.closeSelf();
        }
        _onDeifyOrder() {
            if (mgr.conditionMgr.checkFunc(mvc.FUNC_ID.DEIFY_ORDER, true)) {
                sg.uimgr.showUI("pop_deifyOrder", mvc.DeifyOrderConst.TYPE.DEIFY_ORDER);
            }
        }
        _onBtnRank() {
            sg.uimgr.showUI("pop_topArenaMain", 3);
            this.closeSelf();
        }
        _onBtnLike(rank) {
            if (this._model.vo.isLike(rank))
                return;
            this._ctrl.reqLike(rank);
        }
        _onBoxRole(idx) {
            let vo = this._model.vo;
            let p = vo.top3.get(idx);
            if (p && p.head.player_id != mvc.roleModel.roleInfo.playerId) {
                mvc.mainCtrl.reqPlayerInfo(p.head.player_id);
            }
        }
        _checkOpenRedbag() {
            mvc.redbagModel.checkOpenFreeRedbagByScene(mvc.FUNC_ID.TOP_ARENA);
        }
    }
    mvc.PopTopArenaEnter = PopTopArenaEnter;
})(mvc || (mvc = {}));

var mvc;
