var mvc;
(function (mvc) {
    class UnitTopArenaAttr extends ui.view.topArena.unit_topArenaMyRaceAttrUI {
        constructor() {
            super();
        }
        initSendMsg() {
        }
        initModelEvent() {
        }
        initCtrlEvent() {
            this.listPet.renderHandler = this.createHandler(this, this._renderPetItem, undefined, false);
        }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
        }
        onDisable() {
            super.onDisable();
        }
        setData(data) {
            this.itemArtifact.visible = this.imgArtifact.visible = false;
            if (data == null) {
                return;
            }
            let art = data.artifact;
            if (art && art.id > 0) {
                if (!this._tempArtifact) {
                    this._tempArtifact = new mvc.BagItemVo();
                    this._tempArtifact.attrVo = new mvc.EquipAttrVo();
                }
                this._tempArtifact.count = 1;
                this._tempArtifact.attr = art.attr;
                this._tempArtifact.id = art.id;
                this._tempArtifact.level = art.level;
                this._tempArtifact.attrVo.updateDataByArray(art.attr);
                this.itemArtifact.visible = true;
                this.itemArtifact.initView(this._tempArtifact, false);
            }
            else {
                this.imgArtifact.visible = true;
            }
            let clipQua = this.boxFormation.getChildByName("clipQua");
            let imgIcon = this.boxFormation.getChildByName("imgIcon");
            let imgNull = this.boxFormation.getChildByName("imgNull");
            imgIcon.visible = clipQua.visible = imgNull.visible = false;
            let formation = data.formation;
            if (formation && formation.id > 0) {
                let cfg = sg.dbmgr.get("formation_formation", formation.id);
                imgIcon.visible = clipQua.visible = true;
                clipQua.index = cfg.quality - 1;
                mgr.icon.drawTexture(mgr.icon.getIconPath(cfg.icon), imgIcon);
            }
            else {
                imgNull.visible = true;
            }
            let posInfo = data.rule_pos_infos;
            let map = {};
            for (let data of posInfo) {
                map[data[0]] = data[1];
            }
            let isFind = false;
            for (let pos = 2; pos >= 1; pos--) {
                if (map[pos]) {
                    isFind = true;
                    let cfg = sg.dbmgr.get("rule_rule", map[pos]);
                    this.clipQuaRule.index = cfg.quality - 1;
                    mgr.icon.drawTexture(mgr.icon.getIconPath(cfg.icon), this.imgIconRule);
                    break;
                }
            }
            this.boxRuleItem.visible = isFind;
            let swordInfo = data.sword;
            if (swordInfo) {
                if (!this._tempSwordVo)
                    this._tempSwordVo = new mvc.SwordVo();
                this._tempSwordVo.level = swordInfo.level;
                this._tempSwordVo.grade = swordInfo.stage;
                this._tempSwordVo.equip = swordInfo.id;
                this._tempSwordVo.attr = swordInfo.attr;
                this._tempSwordVo.gasLv = swordInfo.qi_level;
                this._tempSwordVo.gasStateId = swordInfo.qi_stage;
                this.itemSword.visible = true;
                this.imgSword.visible = false;
                this.itemSword.setData(this._tempSwordVo, false, false);
            }
            else {
                this.itemSword.visible = false;
                this.imgSword.visible = true;
            }
            let pets = [];
            for (let type of data.pet.combat_type) {
                let pet;
                let skill;
                for (let p of data.pet.pets) {
                    if (p.type == type) {
                        pet = p;
                        break;
                    }
                }
                for (let s of data.pet.skills) {
                    if (s[0] == type) {
                        skill = s;
                        break;
                    }
                }
                pets.push({ pet: pet, skill: skill });
            }
            while (pets.length < 3) {
                pets.push(null);
            }
            this.listPet.array = pets;
            if (data.gods && data.gods.length > 0) {
                let idx = 0, sIdx = 0, godId = 0;
                while (godId <= 0 && idx < data.gods.length) {
                    godId = data.gods[idx].god_id;
                    sIdx = idx;
                    idx++;
                }
                if (godId == 0) {
                    this.boxGodItem.visible = false;
                }
                else {
                    this.boxGodItem.visible = true;
                    let cfg = sg.dbmgr.get("god_god", godId);
                    this.clipGod.index = cfg.quality;
                    if (data.gods[sIdx].fashion) {
                        let faCfg = sg.dbmgr.get("god_godFashion", data.gods[0].fashion);
                        let url = mgr.icon.getIconPath(faCfg.icon);
                        mgr.icon.drawTexture(url, this.imgGodIcon);
                    }
                    else {
                        let url = mgr.icon.getIconPath(cfg.icon);
                        mgr.icon.drawTexture(url, this.imgGodIcon);
                    }
                }
            }
            else {
                this.boxGodItem.visible = false;
            }
        }
        _renderPetItem(cell) {
            let itemPet = cell.getChildByName("itemPet");
            let imgLineup = cell.getChildByName("imgLineup");
            let data = cell.dataSource;
            if (data) {
                itemPet.directUpdateByPetP(data.pet, false, data.skill[1]);
                imgLineup.visible = true;
            }
            else {
                imgLineup.visible = false;
                itemPet.dataSource = null;
                itemPet.updatePet();
            }
        }
    }
    mvc.UnitTopArenaAttr = UnitTopArenaAttr;
})(mvc || (mvc = {}));

