(function (mvc) {
    class UnitTopArenaRank extends ui.view.topArena.unit_RankUI {
        constructor() {
            super();
            this._needReqFight = true;
            this._needReqGamble = true;
        }
        initSendMsg() {
        }
        initView(idx = 0) {
            this._model = mvc.topArenaModel;
            this._ctrl = mvc.topArenaCtrl;
            this._startIndex = idx;
        }
        initModelEvent() {
            this.bindModelEvent(mvc.rankModel, mvc.RankConst.EVT.UPDATE_RANK_INFO, this._updateRank);
        }
        initCtrlEvent() {
            this.listFight.vScrollBarSkin = "";
            this.listGamble.vScrollBarSkin = "";
            this.tab.selectHandler = this.createHandler(this, this._onTabChange, undefined, false);
        }
        onAwake() {
            super.onAwake();
            let rInfo = mvc.roleModel.roleInfo;
            let iconPath = mgr.ComFunMgr.getHeadIcon(rInfo.wxHeadIconUrl, rInfo.sex);
            let frameId = rInfo.head_frame_id;
            let lv = rInfo.level;
            this.unitHeadFight.initView({ iconPath: iconPath, headFrameId: frameId, level: lv });
            this.unitHeadGamble.initView({ iconPath: iconPath, headFrameId: frameId, level: lv });
            let name = `[S${rInfo.serverId}]${rInfo.name}`;
            this.lblNameFight.text = name;
            this.lblNameGamble.text = name;
            let gname = mvc.guildModel.GuildName;
            this.lblMemPosGamble.text = gname;
            this.lblMemPostFight.text = gname;
            let url = mgr.toolsMgr.getIconById(mvc.MainConst.ITEM_ID.TOP_ARENA_COIN);
            url = mgr.icon.getIconPath(url);
            mgr.icon.drawTexture(url, this.imgCoin);
            this.title.updateTitle(rInfo.title_id);
            this.lblEmpty.text = sg.translate("暂无人上榜");
        }
        onEnable() {
            super.onEnable();
            this.updateData();
        }
        onDisable() {
            this._needReqFight = true;
            this._needReqGamble = true;
            this.tab.selectedIndex = -1;
            super.onDisable();
        }
        updateData() {
            this.tab.selectedIndex = this._startIndex;
        }
        _onTabChange(idx) {
            this.listFight.visible = false;
            this.listGamble.visible = false;
            this.boxMyFight.visible = false;
            this.boxMyGamble.visible = false;
            if (idx < 0)
                return;
            if (idx == 0) {
                this.listFight.visible = true;
                this.boxMyFight.visible = true;
                if (this._needReqFight) {
                    this._needReqFight = false;
                    mvc.rankCtrl.reqRankInfo(mvc.RankConst.RANK_TYPE.top_arena_rank);
                }
                else {
                    this.lblEmpty.visible = this.listFight.length == 0;
                }
            }
            else {
                this.listGamble.visible = true;
                this.boxMyGamble.visible = true;
                if (this._needReqGamble) {
                    this._needReqGamble = false;
                    mvc.rankCtrl.reqRankInfo(mvc.RankConst.RANK_TYPE.top_arena_bet);
                }
                else {
                    this.lblEmpty.visible = this.listGamble.length == 0;
                }
            }
        }
        _updateRank(type, vo) {
            if (type == mvc.RankConst.RANK_TYPE.top_arena_bet) {
                this.listGamble.array = vo.getRankItemVos();
                if (vo.myRank) {
                    this.imgNoMyGamble.visible = false;
                    this.fcRankMyGamble.visible = true;
                    this.fcRankMyGamble.value = vo.myRank + "";
                }
                else {
                    this.imgNoMyGamble.visible = true;
                    this.fcRankMyGamble.visible = false;
                }
                if (vo.myValue) {
                    this.lblCoin.text = vo.myValue.getValue(0) + "";
                    this.lblSuccNum.text = vo.myValue.getValue(1) + "";
                }
                else {
                    this.lblCoin.text = "0";
                    this.lblSuccNum.text = "0";
                }
                if (this.tab.selectedIndex == 1) {
                    this.lblEmpty.visible = this.listGamble.length == 0;
                }
            }
            else if (type == mvc.RankConst.RANK_TYPE.top_arena_rank) {
                let tVo = this._model.vo;
                let arr = vo.getRankItemVos();
                while (arr.length < tVo.playerNum) {
                    let rVo = new mvc.RankItemVo();
                    rVo.idx = tVo.playerNum - arr.length;
                    arr.unshift(rVo);
                }
                this.listFight.array = arr;
                if (this.tab.selectedIndex == 0) {
                    let url = tVo.isJoin ? "ui_langs/cn/ui/topArena/img_font_yjrxyl.png" : "ui_langs/cn/ui/common/image/img_com_wsb.png";
                    let scale = 1;
                    if (vo.myRank) {
                        let rank = vo.myValue.getValue(0);
                        this.imgRankBg.visible = false;
                        scale = 0.5;
                        if (rank) {
                            if (rank <= 4) {
                                switch (rank) {
                                    case 1:
                                        this.imgRankBg.visible = true;
                                        mgr.icon.drawTexture("ui/topArena/img_dfdfc_guanjun.png", this.imgRankBg);
                                        url = "ui_langs/cn/ui/topArena/img_font_dfdfc_guanjun02.png";
                                        break;
                                    case 2:
                                        this.imgRankBg.visible = true;
                                        mgr.icon.drawTexture("ui/topArena/img_dfdfc_yajun.png", this.imgRankBg);
                                        url = "ui_langs/cn/ui/topArena/img_font_dfdfc_yajun02.png";
                                        break;
                                    case 3:
                                        this.imgRankBg.visible = true;
                                        mgr.icon.drawTexture("ui/topArena/img_dfdfc_jijun.png", this.imgRankBg);
                                        url = "ui_langs/cn/ui/topArena/img_font_dfdfc_jijun02.png";
                                        break;
                                    case 4:
                                        this.imgRankBg.visible = true;
                                        mgr.icon.drawTexture("ui/common/image/img_com_mcn.png", this.imgRankBg);
                                        url = "ui_langs/cn/ui/topArena/img_font_dfdfc_dianjun.png";
                                        break;
                                }
                            }
                            else if (rank <= 8) {
                                url = "ui_langs/cn/ui/topArena/img_font_dfdfc_8q.png";
                            }
                            else if (rank <= 16) {
                                url = "ui_langs/cn/ui/topArena/img_font_dfdfc_16q.png";
                            }
                            else if (rank <= 32) {
                                url = "ui_langs/cn/ui/topArena/img_font_dfdfc_32q.png";
                            }
                            else {
                                url = "ui_langs/cn/ui/topArena/img_font_dfdfc_128q.png";
                            }
                        }
                    }
                    mgr.icon.drawTexture(url, this.imgRank);
                    this.lblEmpty.visible = this.listFight.length == 0;
                    this.imgRank.scale(scale, scale);
                }
            }
        }
    }
    mvc.UnitTopArenaRank = UnitTopArenaRank;
})(mvc || (mvc = {}));

