            this.onMsg(Proto.PEAK_FIGHT_BET, this._onMsgBet);
            this.onMsg(Proto.PEAK_FIGHT_BET_LIST_INFO, this._onMsgBetRecord);
            this.onMsg(Proto.PEAK_FIGHT_COMBAT_LIST_INFO, this._onMsgFightRecord);
            this.onMsg(Proto.PEAK_FIGHT_BET_STAGE, this._onMsgBetStart);
            this.onMsg(Proto.PEAK_FIGHT_SETTLE, this._onMsgLastResult);
            this.onMsg(Proto.PEAK_FIGHT_REFRESH, this._onMsgRaceRefresh);
            this.onMsg(Proto.PEAK_FIGHT_LIKE, this._onMsgLike);
            this.onMsg(Proto.ABOVE_GROUP_LIST, this._onMsgSeverList);
            this.onMsg(Proto.PEAK_BET_RESULT, this._onMsgGuestResult);
