(function (mvc) {
    class TowerVo extends sg.VoBase {
        updateData(info) {
            if (!info)
                return;
            this.current_id = info.current_id;
            this.relic_list = info.relic_list;
            this.grid_num = info.grid_num;
            this.fast_fight_count = info.fast_fight_count;
            this.fast_fight_count_time = info.fast_fight_count_time;
            this.relic_result = info.relic_result;
            this.selected_num = info.selected_num;
            this.to_id = info.to_id;
            this.can_fast = info.can_fast;
            this.history_max_id = info.history_max_id;
            this.max_id = info.max_id;
        }
        addRelic(relic) {
            if (!relic || relic.length == 0)
                return;
            if (!this.relic_list) {
                this.relic_list = [];
            }
            let idx = this.indexOfRelicList(relic[0]);
            if (idx != -1) {
                this.relic_list[idx][1] = relic[1];
            }
            else
                this.relic_list.push([relic[0], relic[1]]);
        }
        forgetRelic(relicId) {
            let idx = -1;
            for (let i = 0; i < this.relic_list.length; i++) {
                if (this.relic_list[i][0] == relicId) {
                    idx = i;
                    break;
                }
            }
            if (idx != -1) {
                this.relic_list.splice(idx, 1);
            }
        }
        indexOfRelicList(id) {
            for (let i = 0; i < this.relic_list.length; i++) {
                if (this.relic_list[i][0] == id) {
                    return i;
                }
            }
            return -1;
        }
        getRelic(id) {
            for (let i = 0; i < this.relic_list.length; i++) {
                if (this.relic_list[i][0] == id) {
                    return this.relic_list[i];
                }
            }
            return null;
        }
        removeRelicForResult(id) {
            for (let i = 0; i < this.relic_result.length; i++) {
                if (this.relic_result[i] == id) {
                    this.relic_result[i] = 0;
                    break;
                }
            }
        }
        getAllRelicsProps() {
            let propertys = [];
            for (let i = 0; i < this.relic_list.length; i++) {
                let c = sg.dbmgr.get("tower_towerRelic", this.relic_list[i][0]);
                if (c) {
                    let pVos = mvc.PropertyModel.prasePropByCfg(c.attr, this.relic_list[i][1]);
                    propertys = mvc.PropertyModel.getMixPropertysMerge(propertys, pVos, true);
                }
            }
            return propertys;
        }
    }
    mvc.TowerVo = TowerVo;
})(mvc || (mvc = {}));

var mvc;
(function (mvc) {
    class TowerModel extends sg.ModelBase {
        initModel() {
        }
        registerEvents() {
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.DUNGEON_TOWER_FAST, this.redTipsFast, this);
        }
        initInfo() {
            if (!this.vo) {
                this.vo = new mvc.TowerVo();
            }
        }
        setInfo(info) {
            this.initInfo();
            this.vo.updateData(info);
            this.fireEvent(mvc.TowerConst.EVT.UPDATE_INFO);
            mgr.redotMgr.check(mvc.REDOT_ID.DUNGEON_TOWER_FAST);
        }
        towerChallenge(msg) {
            this._lastReport = msg.combat_notify;
            mvc.battleModel.startBattle(msg.combat_notify, Proto.COMBAT_TYPE.TOWER, () => {
                mvc.towerCtrl.reqTowerFinishCombat();
            });
        }
        towerFinishCombat(msg) {
            this.initInfo();
            this.vo.can_fast = msg.can_fast;
            this.vo.relic_result = msg.relic_result;
            this.vo.current_id = msg.current_id;
            if (msg.result == 1)
                sg.uimgr.showUI("pop_towerRelicChoose");
            if (msg.result == 1 && msg.reward.length == 0) {
                mvc.battleModel.clearBattle();
                sg.uimgr.showUI("pop_getReward", "", [], false, sg.translate("本期该层试炼奖励您已领取过啦~"));
            }
            else {
                sg.uimgr.showFbResult({ result: msg.result, desc: sg.translate("通天塔"), reward: msg.reward }, this._lastReport);
                this._lastReport = null;
            }
            this.fireEvent(mvc.TowerConst.EVT.UPDATE_INFO);
            mgr.redotMgr.check(mvc.REDOT_ID.DUNGEON_TOWER_FAST);
        }
        selectRelic(msg) {
            this.initInfo();
            let arr = null;
            if (msg.relic.length == 0) {
                this.vo.relic_result = [];
            }
            else {
                arr = [];
                for (let i = 0; i < this.vo.relic_list.length; i++) {
                    arr.push([this.vo.relic_list[i][0], this.vo.relic_list[i][1]]);
                }
                this.vo.addRelic(msg.relic);
                this.vo.removeRelicForResult(msg.relic[0]);
            }
            let idx = this.getChangeIdxForRelic(arr, this.vo.relic_list);
            this.fireEvent(mvc.TowerConst.EVT.UPDATE_INFO);
            this.fireEvent(mvc.TowerConst.EVT.SELECT_RELIC, idx);
        }
        fastRestart(msg) {
            this.initInfo();
            this.vo.updateData(msg.info);
            sg.uimgr.showUI("pop_towerRelicFast");
            if (msg.reward.length > 0) {
                sg.uimgr.showUI("pop_getReward", "", msg.reward);
            }
            this.fireEvent(mvc.TowerConst.EVT.UPDATE_INFO);
            mgr.redotMgr.check(mvc.REDOT_ID.DUNGEON_TOWER_FAST);
        }
        fastSelect(msg) {
            this.initInfo();
            let arr = null;
            if (msg.relic.length > 0) {
                arr = [];
                for (let i = 0; i < this.vo.relic_list.length; i++) {
                    arr.push([this.vo.relic_list[i][0], this.vo.relic_list[i][1]]);
                }
                this.vo.addRelic(msg.relic);
            }
            this.vo.relic_result = msg.relic_result;
            this.vo.selected_num = msg.selected_num;
            this.vo.to_id = msg.to_id;
            let idx = this.getChangeIdxForRelic(arr, this.vo.relic_list);
            this.fireEvent(mvc.TowerConst.EVT.UPDATE_INFO);
            this.fireEvent(mvc.TowerConst.EVT.SELECT_RELIC, idx);
        }
        forgetRelic(relicId) {
            this.initInfo();
            this.vo.forgetRelic(relicId);
            this.fireEvent(mvc.TowerConst.EVT.UPDATE_INFO);
            this.fireEvent(mvc.TowerConst.EVT.FORGET_RELIC);
        }
        gridNum(num) {
            this.initInfo();
            this.vo.grid_num = num;
            this.fireEvent(mvc.TowerConst.EVT.UPDATE_INFO);
        }
        buyRelicNotify(relicInfo) {
            this.initInfo();
            this.vo.addRelic(relicInfo);
            sg.uimgr.showNotice(sg.translate("购买成功"), "green");
            this.fireEvent(mvc.TowerConst.EVT.UPDATE_INFO);
        }
        getRelicsData() {
            let dataArr = [];
            let data = {};
            let max = mgr.toolsMgr.getGlobalVoById("tower_bag_num", 1);
            for (let i = 0; i < max; i++) {
                let relic = this.vo.relic_list[i];
                if (relic) {
                    let c = sg.dbmgr.get("tower_towerRelic", relic[0]);
                    data = { cfg: c, level: relic[1], lock: false };
                }
                else if (i < this.vo.grid_num) {
                    data = { cfg: null, level: 0, lock: false };
                }
                else {
                    data = { cfg: null, level: 0, lock: true };
                }
                dataArr.push(data);
            }
            return dataArr;
        }
        getChangeIdxForRelic(a, b) {
            if (a && b) {
                if (a.length == 0)
                    return 0;
                if (a.length != b.length)
                    return a.length;
                for (let i = 0; i < b.length; i++) {
                    for (let n = 0; n < a.length; n++) {
                        if (b[i][0] == a[n][0] && b[i][1] > a[n][1])
                            return i;
                    }
                }
            }
            return -1;
        }
        getNextextraReward(curLevel) {
            if (!this._extraRewardCfgs || this._extraRewardCfgs.length == 0) {
                this._extraRewardCfgs = sg.dbmgr.getArray("tower_tower", { extraReward: 1 });
                this._extraRewardCfgs.sort(function (a, b) {
                    return a.id - b.id;
                });
            }
            for (let i = 0; i < this._extraRewardCfgs.length; i++) {
                if (curLevel < this._extraRewardCfgs[i].id)
                    return this._extraRewardCfgs[i];
            }
            return null;
        }
        redTipsFast() {
            if (!mgr.conditionMgr.checkFunc(mvc.FUNC_ID.TOWER, false))
                return 0;
            return mvc.mainModel.checkTipsRed(mvc.TipsRedId.Tower) ? 1 : 0;
        }
    }
    mvc.TowerModel = TowerModel;
})(mvc || (mvc = {}));

