(function (mvc) {
    class PopTowerMain extends ui.view.tower.pop_towerMainUI {
        initView() {
        }
        initSendMsg() {
            mvc.rankCtrl.reqRankInfo(mvc.RankConst.RANK_TYPE.tower);
            mvc.towerCtrl.reqTowerInfo();
        }
        initModelEvent() {
            this.bindModelEvent(mvc.rankModel, mvc.RankConst.EVT.UPDATE_RANK_INFO, this._updateRank);
        }
        initCtrlEvent() {
            this.btnEnter.on(Laya.Event.CLICK, this, this._onBtnEnter);
            this.btnReward.on(Laya.Event.CLICK, this, this._onBtnReward);
            this.listTower.vScrollBarSkin = "";
            this.listTower.itemRender = mvc.UnitTowerRankItem;
            this.listTower.renderHandler = this.createHandler(this, this._renderList, null, false);
        }
        updateData(types, ...args) { }
        onAwake() {
            super.onAwake();
            mvc.mainModel.hideTipsRed(mvc.TipsRedId.Tower);
            this.redTips.id = mvc.REDOT_ID.DUNGEON_TOWER_FAST;
            this.lblTimeDesc.text = sg.translate("本期试炼剩余时间:");
            this.lblNot.text = sg.translate("暂无排名");
        }
        onEnable() {
            super.onEnable();
            this._updateView();
        }
        onDisable() {
            super.onDisable();
        }
        onClosed() {
            this.stopTimer(this.timeOffse);
            super.onClosed();
        }
        static checkCanOpen() {
            let actVo = mvc.activityModel.openActivityVo.get(mvc.FUNC_ID.TOWER);
            if (actVo)
                return true;
            sg.uimgr.showNotice(sg.translate("活动未开启"));
            return false;
        }
        _updateRank(type, rankVo) {
            this.listTower.array = rankVo.getRankItemVos();
            this.lblNot.visible = this.listTower.array.length == 0;
            let item = this.boxPlayer.getChildByName("item");
            if (!item) {
                item = new mvc.UnitTowerRankItem();
                item.name = "item";
                this.boxPlayer.addChild(item);
            }
            item.setData(rankVo.myValue);
        }
        _updateView() {
            let actVo = mvc.activityModel.openActivityVo.get(mvc.FUNC_ID.TOWER);
            if (actVo) {
                this.lblTimeDesc2.visible = false;
                this.lblTimeDesc.visible = this.lblTime.visible = true;
                this.repeats(1000, this.timeOffse, true);
            }
            else {
                this.lblTimeDesc2.visible = true;
                this.lblTimeDesc.visible = this.lblTime.visible = false;
            }
        }
        timeOffse() {
            let actVo = mvc.activityModel.openActivityVo.get(mvc.FUNC_ID.TOWER);
            let curTime = sg.time.getTime();
            let lastTime = actVo.end_time - (curTime / 1000);
            if (lastTime > 0) {
                this.lblTime.text = sg.time.formatTimeStrT("F10", lastTime);
            }
            else {
                this.stopTimer(this.timeOffse);
                this.lblTime.visible = false;
                this.lblTimeDesc.visible = false;
                this.lblTimeDesc2.visible = true;
            }
        }
        _renderList(cell, index) {
            cell.setData(cell.dataSource);
        }
        _onBtnEnter() {
            sg.uimgr.showUI("pop_towerChallenge");
            this.closeSelf();
        }
        _onBtnReward() {
            sg.uimgr.showUI("pop_towerRewardTips");
        }
    }
    mvc.PopTowerMain = PopTowerMain;
})(mvc || (mvc = {}));

var mvc;
(function (mvc) {
    class PopTowerRelicChoose extends ui.view.tower.pop_towerRelicChooseUI {
        initView() {
        }
        initSendMsg() {
        }
        initModelEvent() {
            this.bindModelEvent(mvc.towerModel, mvc.TowerConst.EVT.UPDATE_INFO, this._updateView);
            this.bindModelEvent(mvc.towerModel, mvc.TowerConst.EVT.SELECT_RELIC, this._updateSelectInfo);
            this.bindModelEvent(mvc.towerModel, mvc.TowerConst.EVT.FORGET_RELIC, this._updateForget);
        }
        initCtrlEvent() {
            this.listMyRelic.renderHandler = this.createHandler(this, this._renderList, null, false);
            this.listRelic.selectEnable = true;
            this.listRelic.selectHandler = this.createHandler(this, this._selectListRelic, null, false);
            this.listRelic.renderHandler = this.createHandler(this, this._renderListRelic, null, false);
            this.on(Laya.Event.CLICK, this, this._onClick);
        }
        updateData(types, ...args) { }
        onAwake() {
            super.onAwake();
            this.boxResultSuc.skin = "slcg";
        }
        onEnable() {
            super.onEnable();
            this._updateView();
            this.listRelic.selectedIndex = 0;
        }
        onDisable() {
            super.onDisable();
        }
        onClosed() {
            super.onClosed();
        }
        _updateForget() {
            let idx = this.listRelic.selectedIndex;
            this.listRelic.selectedIndex = idx;
        }
        _updateSelectInfo(idx) {
            for (let i = 0; i < this._vo.relic_result.length; i++) {
                if (this._vo.relic_result[i] != 0) {
                    this.listRelic.selectedIndex = i;
                    break;
                }
            }
            if (idx == -1)
                return;
            let box = this.listMyRelic.getChildAt(0);
            let item = box.getChildAt(idx);
            if (item) {
                let unit = item.getChildByName("item");
                if (unit)
                    unit.playAni();
            }
        }
        _updateView() {
            this._vo = mvc.towerModel.vo;
            if (this._vo) {
                this._cfg = sg.dbmgr.get("tower_tower", this._vo.current_id);
                this.listRelic.array = this._vo.relic_result;
                this.listMyRelic.array = mvc.towerModel.getRelicsData();
                mgr.icon.drawTexture(mgr.icon.getIconPath(mgr.toolsMgr.getIconById(8)), this.sprPriceIcon);
                this.lblPrice.text = mgr.toolsMgr.getCountById(8) + "";
                if (this._vo.relic_result.indexOf(0) != -1) {
                    this.btnGo.visible = this.btnQuit.visible = false;
                    this.btnClose.visible = true;
                    this.closeSelf();
                }
                else {
                    this.btnGo.visible = this.btnQuit.visible = true;
                    this.btnClose.visible = false;
                }
            }
        }
        _renderList(cell, index) {
            let item = cell.getChildByName("item");
            cell.dataSource[`type`] = 1;
            if (item)
                item.setData(cell.dataSource);
        }
        _selectListRelic(index) {
            let relic = this.listRelic.array[index];
            if (relic) {
                let cfg = sg.dbmgr.get("tower_towerRelic", relic);
                if (cfg) {
                    this.lblRelickEff.text = cfg.desc;
                    this.lblRelickEff.color = mgr.toolsMgr.getColor(cfg.quality);
                    mgr.toolsMgr.setQualityStroke(cfg.quality, this.lblRelickEff);
                    if (this._vo.relic_result.indexOf(0) != -1) {
                        this.lblSelectTips.visible = false;
                        return;
                    }
                    this.lblSelectTips.visible = true;
                    let relicInfo = this._vo.getRelic(relic);
                    if (relicInfo) {
                        if (relicInfo[1] >= cfg.maxlevel) {
                            this.lblSelectTips.text = "[" + sg.translate("宝物已满级") + "]";
                        }
                        else {
                            this.lblSelectTips.text = "[" + sg.translate("宝物可升级") + "]";
                        }
                    }
                    else if (this._vo.relic_list.length == this._vo.grid_num) {
                        this.lblSelectTips.text = "[" + sg.translate("宝物已满,请点击已有宝物进行丢弃") + "]";
                    }
                    else {
                        this.lblSelectTips.visible = false;
                    }
                }
            }
        }
        _renderListRelic(cell, index) {
            if (cell.dataSource == 0) {
                cell.visible = false;
                return;
            }
            cell.visible = true;
            let boxItem = cell.getChildByName("boxItem");
            let item = boxItem.getChildByName("item");
            if (!item) {
                item = new mvc.UnitTowerRelicItem();
                item.name = "item";
                boxItem.addChild(item);
            }
            let lblName = cell.getChildByName("lblName");
            let imgSelect = cell.getChildByName("imgSelect");
            if (imgSelect)
                imgSelect.visible = this.listRelic.selectedIndex == index;
            let cfg = sg.dbmgr.get("tower_towerRelic", cell.dataSource);
            if (cfg) {
                lblName.text = cfg.name;
                lblName.color = mgr.toolsMgr.getColor(cfg.quality);
                mgr.toolsMgr.setQualityStroke(cfg.quality, lblName);
                item.setData({ cfg: cfg, level: 1, lock: false, type: 2 }, false);
                item.setLevlVisible();
            }
        }
        _onClick(e) {
            switch (e.target) {
                case this.btnClose:
                    {
                        this.closeSelf();
                    }
                    break;
                case this.btnGo:
                    {
                        let id = this.listRelic.array[this.listRelic.selectedIndex];
                        if (id) {
                            let cfg = sg.dbmgr.get("tower_towerRelic", id);
                            if (cfg) {
                                if (this._vo.relic_result.indexOf(0) != -1) {
                                    this.lblSelectTips.visible = false;
                                    return;
                                }
                                this.lblSelectTips.visible = true;
                                let relicInfo = this._vo.getRelic(id);
                                if (relicInfo) {
                                    if (relicInfo[1] >= cfg.maxlevel) {
                                        sg.uimgr.showNotice(sg.translate("该宝物已达最大等级"));
                                    }
                                    else {
                                        mvc.towerCtrl.reqTowerSelectRelic(id);
                                    }
                                }
                                else if (this._vo.relic_list.length == this._vo.grid_num) {
                                    sg.uimgr.showNotice(sg.translate("格子已满,请点击已有宝物进行丢弃"));
                                }
                                else {
                                    mvc.towerCtrl.reqTowerSelectRelic(id);
                                }
                            }
                        }
                    }
                    break;
                case this.btnQuit:
                    {
                        mvc.towerCtrl.reqTowerSelectRelic(0);
                        this.closeSelf();
                    }
                    break;
            }
        }
    }
    mvc.PopTowerRelicChoose = PopTowerRelicChoose;
})(mvc || (mvc = {}));

