            this.sprDi.visible = this.imgLock.visible = false;
            this.clipQua.visible = this.sprIcon.visible = this.lblNum.visible = false;
            if (this._lock) {
                this.sprDi.visible = this.imgLock.visible = true;
            }
            else if (this._cfg) {
                this.clipQua.visible = this.sprIcon.visible = this.lblNum.visible = true;
                this.clipQua.index = this._cfg.quality - 1;
                this.setIcon(this._cfg.icon);
                this.lblNum.text = "Lv" + this._level;
            }
            else {
            }
