var mvc;
(function (mvc) {
    let EVT = mvc.TitleConst.EVT;
    class TitleModel extends sg.ModelBase {
        constructor() {
            super(...arguments);
            this.selectTitleId = 0;
            this.isHaveNewTitle = false;
            this.newTitleId = [];
        }
        initModel() {
            this.vo = new mvc.TitleVo();
        }
        registerEvents() {
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.ROLE_TITLE_ACHIEVEMENT, this._checkAchievementRed, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.ROLE_TITLE_ACTIVITY, this._checkActivityRed, this);
        }
        updateTitleInfo(pb) {
            this.vo.title_id = mvc.roleModel.roleInfo.title_id;
            this.vo.title = {};
            let allTitle = pb.title;
            for (let title of allTitle) {
                this.vo.title[title.id] = title;
            }
            this.updateBagTitleInfo();
            this.fireEvent(EVT.UPDATE_TITLE_INFO);
            mgr.redotMgr.check(mvc.REDOT_ID.ROLE_TITLE_ACHIEVEMENT);
            mgr.redotMgr.check(mvc.REDOT_ID.ROLE_TITLE_ACTIVITY);
        }
        updateBagTitleInfo() {
            this.vo.notActiveId = [];
            this.vo.title_num = {};
            let titleItem = mvc.bagModel.getItemsByType(mvc.BagConst.BagType.Title);
            for (let i = 0; i < titleItem.length; i++) {
                let titleId = titleItem[i].id;
                if (!this.vo.title[titleId]) {
                    if (this.vo.notActiveId.indexOf(titleId) == -1)
                        this.vo.notActiveId.push(titleId);
                }
                else {
                    if (!this.vo.title_num[titleId])
                        this.vo.title_num[titleId] = titleItem[i].count;
                    else
                        this.vo.title_num[titleId] += titleItem[i].count;
                }
            }
        }
        changeTitle(pb) {
            if (pb.is_active) {
                this.vo.title = {};
                let allTitle = pb.title;
                for (let title of allTitle) {
                    this.vo.title[title.id] = title;
                }
                this.vo.title_id = pb.title_id;
                this.updateBagTitleInfo();
                mgr.redotMgr.check(mvc.REDOT_ID.ROLE_TITLE_ACHIEVEMENT);
                mgr.redotMgr.check(mvc.REDOT_ID.ROLE_TITLE_ACTIVITY);
            }
            else {
                this.vo.title_id = pb.title_id;
                this.selectTitleId = pb.title_id;
            }
            mvc.roleModel.fireEvent(mvc.RoleConst.EVT.UPDATE_TITLE);
            this.fireEvent(EVT.UPDATE_TITLE_INFO);
        }
        moveTitle() {
            this.vo.title_id = 0;
            this.selectTitleId = 0;
            this.fireEvent(EVT.UPDATE_TITLE_INFO);
            mvc.roleModel.fireEvent(mvc.RoleConst.EVT.UPDATE_TITLE);
        }
        getNewTitle(pb) {
            this.vo.title_id = pb.new_title.id;
            this.updateBagTitleInfo();
            if (!this.vo.title[pb.new_title.id]) {
                this.vo.title[pb.new_title.id] = pb.new_title;
                if (this.selectTitleId != pb.new_title.id) {
                    this.isHaveNewTitle = true;
                    this.newTitleId.push(pb.new_title.id);
                }
            }
            this.fireEvent(EVT.UPDATE_TITLE_INFO);
            mvc.roleModel.fireEvent(mvc.RoleConst.EVT.UPDATE_TITLE);
            mgr.redotMgr.check(mvc.REDOT_ID.ROLE_TITLE_ACHIEVEMENT);
            mgr.redotMgr.check(mvc.REDOT_ID.ROLE_TITLE_ACTIVITY);
        }
        titleEnd(pb) {
            let end_title_id = pb.end_title_id;
            for (let i = 0; i < end_title_id.length; i++) {
                if (this.vo.title_id == end_title_id[i]) {
                    this.vo.title_id = mvc.roleModel.roleInfo.title_id;
                    mvc.roleModel.fireEvent(mvc.RoleConst.EVT.UPDATE_TITLE);
                }
                delete this.vo.title[end_title_id[i]];
            }
            this.fireEvent(EVT.UPDATE_TITLE_INFO);
        }
        titleLvUp(pb) {
            this.vo.title[pb.title_id].level = pb.title_level;
            this.updateBagTitleInfo();
            this.fireEvent(EVT.UPDATE_TITLE_INFO);
            mgr.redotMgr.check(mvc.REDOT_ID.ROLE_TITLE_ACHIEVEMENT);
            mgr.redotMgr.check(mvc.REDOT_ID.ROLE_TITLE_ACTIVITY);
        }
        getTitleLvById(title_id) {
            return this.vo.title[title_id] ? this.vo.title[title_id].level : 1;
        }
        getTitleConditionById(title_id) {
            let condition = "";
            if (this.vo.title[title_id])
                condition = sg.translate("已激活");
            else {
                let titleCfg = sg.dbmgr.get("fashion_title", title_id);
                condition = titleCfg.condition_show;
            }
            return condition;
        }
        getTitleEndTimeById(title_id) {
            let time = 0;
            let cfg = sg.dbmgr.get("fashion_title", title_id);
            if (this.vo.title[title_id]) {
                time = this.vo.title[title_id].end_time;
                if (time == 0)
                    return sg.translate("永久");
            }
            if (!time) {
                if (!cfg) {
                    return "";
                }
                if (cfg.keeptime) {
                    return sg.time.formatTimeStrT("F9", cfg.keeptime);
                }
                else {
                    return sg.translate("永久");
                }
            }
            let remainTime = time - sg.time.getSecondTime();
            if (remainTime <= 0)
                return "";
            else
                return sg.time.formatTimeStrT("F9", remainTime);
        }
        getTitleAttributeById(title_id) {
            let baseProp = [];
            let titleCfg = sg.dbmgr.get("fashion_title", title_id);
            if (!titleCfg)
                return baseProp;
            baseProp = mvc.PropertyModel.prasePropByCfg(titleCfg.prop);
            if (titleCfg.lvup == 1) {
                let addLevel = this.getTitleLvById(title_id) - 1;
                if (addLevel > 0) {
                    let levelCfg = sg.dbmgr.get("fashion_titleLevel", title_id);
                    let levelAttributeArr = levelCfg.prop;
                    let addProp = mvc.PropertyModel.prasePropByCfg(levelAttributeArr, addLevel);
                    baseProp = mvc.PropertyModel.getMixPropertysMerge(baseProp, addProp, true);
                }
            }
            return baseProp;
        }
        getAllTitleAttribute() {
            let baseProp = [];
            let title = this.vo.title;
            for (let title_id in title) {
                if (baseProp.length == 0) {
                    baseProp = this.getTitleAttributeById(+title_id);
                }
                else {
                    let addProp = this.getTitleAttributeById(+title_id);
                    baseProp = mvc.PropertyModel.getMixPropertysMerge(baseProp, addProp, true);
                }
            }
            return baseProp;
        }
        changeSelectItem(title_id) {
            this.selectTitleId = title_id;
            this.fireEvent(EVT.UPDATE_TITLE_INFO);
        }
        addTitle(title_id) {
            if (!this.vo.title[title_id]) {
                mvc.titleCtrl.reqTitleList();
                this.isHaveNewTitle = true;
                this.newTitleId.push(title_id);
            }
            else {
                this.updateBagTitleInfo();
                this.fireEvent(EVT.UPDATE_TITLE_INFO);
                mgr.redotMgr.check(mvc.REDOT_ID.ROLE_TITLE_ACHIEVEMENT);
                mgr.redotMgr.check(mvc.REDOT_ID.ROLE_TITLE_ACTIVITY);
            }
        }
        selectNewTitle(title_id) {
            this.newTitleId.splice(this.newTitleId.indexOf(title_id), 1);
            if (this.newTitleId.length == 0)
                this.isHaveNewTitle = false;
            mgr.redotMgr.check(mvc.REDOT_ID.ROLE_TITLE_ACHIEVEMENT);
            mgr.redotMgr.check(mvc.REDOT_ID.ROLE_TITLE_ACTIVITY);
        }
        _checkAchievementRed() {
            return this._getRedState(1);
        }
        _checkActivityRed() {
            return this._getRedState(2);
        }
        _getRedState(tabType) {
            let isHave = false;
            if (this.vo.notActiveId) {
                let cfg = sg.dbmgr.getArray("fashion_title", { tabType: tabType });
                for (let i = 0; i < cfg.length; i++) {
                    let time = new Date(cfg[i].timeShow).getTime();
                    let passTime = sg.time.getTime() - time >= 0;
                    if (this.vo.notActiveId.indexOf(cfg[i].id) != -1 && mgr.gplatform.checkChannel(cfg[i].condition) && passTime) {
                        isHave = true;
                        break;
                    }
                }
            }
            let isCanLvUp = false;
            let title_num = this.vo.title_num;
            if (Object.keys(title_num).length > 0) {
                for (let title_id in title_num) {
                    let cfg = sg.dbmgr.get("fashion_title", title_id);
                    if (cfg.lvup == 1 && cfg.tabType == tabType) {
                        let levelCfg = sg.dbmgr.get("fashion_titleLevel", title_id);
                        if (levelCfg) {
                            if (title_num[title_id] >= levelCfg.consume[0][1] && this.vo.title[title_id].level < levelCfg.lvLimit) {
                                isCanLvUp = true;
                                break;
                            }
                        }
                    }
                }
            }
            let isHaveNewTitle = false;
            if (this.newTitleId.length > 0) {
                for (let i = 0; i < this.newTitleId.length; i++) {
                    let title_id = this.newTitleId[i];
                    let cfg = sg.dbmgr.get("fashion_title", title_id);
                    if (cfg.tabType == tabType) {
                        isHaveNewTitle = true;
                        break;
                    }
                }
            }
            return isHave || isCanLvUp || isHaveNewTitle ? 1 : 0;
        }
        getAllTitleNum() {
            if (this._allTitleNum == null || this._allTitleNum <= 0) {
                let cfg = sg.dbmgr.getDB("fashion_title");
                this._allTitleNum = 0;
                for (let k in cfg) {
                    if (cfg[k].collectExp == 0) {
                        this._allTitleNum++;
                    }
                }
            }
            return this._allTitleNum;
        }
    }
    mvc.TitleModel = TitleModel;
})(mvc || (mvc = {}));

var mvc;
(function (mvc) {
    class PopTitle extends ui.view.fashion.pop_titleUI {
        initView() {
            this._model = mvc.titleModel;
            this._ctrl = mvc.titleCtrl;
        }
        initModelEvent() {
            this.bindModelEvent(this._model, mvc.TitleConst.EVT.UPDATE_TITLE_INFO, this._updateTitleInfo);
            this.bindModelEvent(mvc.collectorModel, mvc.CollectorConst.EVT.COLLECTOR_LV_UP, this._updateCollectIcon);
        }
        initCtrlEvent() {
            this.attrList.vScrollBarSkin = "";
            this.titleList.vScrollBarSkin = "";
            this.tab.selectHandler = this.createHandler(this, this._updateTab, null, false);
            this.titleList.renderHandler = this.createHandler(this, this._onTitleList, null, false);
            this.attrList.renderHandler = this.createHandler(this, this._onAttrList, null, false);
            this.btnAttribute.on(Laya.Event.CLICK, this, this._onBtnAttribute);
            this.btnActivation.on(Laya.Event.CLICK, this, this._onBtnActivation);
            this.btnChange.on(Laya.Event.CLICK, this, this._onBtnChange);
            this.btnCollect.on(Laya.Event.CLICK, this, this._onBtnCollect);
            this.unitRedotAch.id = mvc.REDOT_ID.ROLE_TITLE_ACHIEVEMENT;
            this.unitRedotAct.id = mvc.REDOT_ID.ROLE_TITLE_ACTIVITY;
        }
        onEnable() {
            super.onEnable();
            mgr.UIAssist.initHtml(this.lblTitleNum, { size: 18, color: "#323232", wordWrap: true, align: "left" });
            let title_id = this._model.vo.title_id;
            this._updateTab(title_id == 0 ? 0 : sg.dbmgr.get("fashion_title", title_id).tabType - 1);
            this._updateSelectId();
            this._updateSelectInfo();
            this._updateTitleNum();
            this._updateBtn();
            this._updateTime();
            this._updateCollectIcon();
        }
        onDisable() {
            super.onDisable();
            this.stopTimer(this._updateTime);
        }
        updateData(types, ...args) {
        }
        updateWhenNetReConn() {
            this._updateTitleInfo();
        }
        _updateTab(idx) {
            this.tab.selectedIndex = idx;
            this._curTabCfg = sg.dbmgr.getArray("fashion_title", { tabType: idx + 1 });
            this._sort();
            this.titleList.array = this._curTabCfg;
        }
        _onTitleList(cell, idx) {
            let data = cell.dataSource;
            if (!data)
                return;
            cell.initView(data);
        }
        _onAttrList(cell, idx) {
            let data = cell.dataSource;
            if (!data)
                return;
            let lblAttr = cell.getChildByName("lblAttr");
            let lblVal = cell.getChildByName("lblVal");
            let propCfg = mvc.PropertyModel._getCfg(data.nameStr);
            lblAttr.text = propCfg.show_name;
            lblVal.text = data.is_per ? (data.value / 100) + "%" : data.value + "";
        }
        _updateTitleInfo() {
            this.titleList.refresh();
            this._updateSelectInfo();
            this._updateTitleNum();
            this._updateBtn();
        }
        _updateSelectId() {
            if (this._model.vo.title_id == 0)
                this._model.selectTitleId = 0;
            else
                this._model.selectTitleId = this._model.vo.title_id;
        }
        _updateSelectInfo() {
            let selectTitleId = this._model.selectTitleId;
            this.title.updateTitle(selectTitleId);
            this.lblLv.text = `lv ${this._model.getTitleLvById(selectTitleId)}`;
            this.lblMode.text = this._model.selectTitleId == 0 ? "" : this._model.getTitleConditionById(selectTitleId);
            this.lblTime.text = this._model.getTitleEndTimeById(selectTitleId);
            let attributeArr = this._model.getTitleAttributeById(selectTitleId);
            this.attrList.array = attributeArr;
            let cfg = sg.dbmgr.get("fashion_title", selectTitleId);
            let exp = (cfg && cfg.collectExp) || 0;
            if (exp == 0) {
                this.expText.text = sg.translate('不提供收藏经验');
            }
            else {
                this.expText.text = StringEx.format(sg.translate("激活获取${exp}点收藏经验"), {"exp":exp});
            }
        }
        _updateTitleNum() {
            if (!this.allTitleNum) {
                let cfg = sg.dbmgr.getDB("fashion_title");
                this.allTitleNum = Object.keys(cfg).length;
            }
            let titleNum = Object.keys(this._model.vo.title).length;
            this.lblTitleNum.innerHTML = mgr.UIAssist.setColor(titleNum + "", '#268e5e') + mgr.UIAssist.setColor('/' + this.allTitleNum, '#323232');
        }
        _updateBtn() {
            this.btnActivation.disabled = false;
            this.unitRedotBtn.visible = false;
            let selectTitleId = this._model.selectTitleId;
            if (selectTitleId == 0) {
                this.btnActivation.visible = this.btnChange.visible = false;
            }
            else {
                if (this._model.vo.title[selectTitleId]) {
                    this.btnChange.visible = true;
                    this.btnActivation.visible = true;
                    if (this._model.vo.title_id == selectTitleId)
                        this.btnChange.visible = false;
                    else {
                        if (this._model.vo.title_id == 0)
                            this.btnChange.label = sg.translate("穿戴");
                        else
                            this.btnChange.label = sg.translate("更换");
                    }
                    let cfg = sg.dbmgr.get("fashion_title", selectTitleId);
                    if (cfg.lvup == 0) {
                        this.btnActivation.label = sg.translate("已满级");
                        this.btnActivation.disabled = true;
                    }
                    else {
                        let level = this._model.getTitleLvById(selectTitleId);
                        let levelCfg = sg.dbmgr.get("fashion_titleLevel", selectTitleId);
                        if (level == levelCfg.lvLimit) {
                            this.btnActivation.label = sg.translate("已满级");
                            this.btnActivation.disabled = true;
                        }
                        else {
                            this.btnActivation.label = sg.translate("升级称号");
                            let titleNum = this._model.vo.title_num[selectTitleId] ? this._model.vo.title_num[selectTitleId] : 0;
                            this.btnActivation.disabled = titleNum < levelCfg.consume[0][1];
                            this.unitRedotBtn.visible = !this.btnActivation.disabled;
                        }
                    }
                }
                else {
                    this.btnChange.visible = false;
                    this.btnActivation.visible = true;
                    if (this._model.vo.notActiveId && this._model.vo.notActiveId.indexOf(selectTitleId) != -1) {
                        this.btnActivation.label = sg.translate("解锁称号");
                        this.unitRedotBtn.visible = true;
                    }
                    else
                        this.btnActivation.label = sg.translate("前往激活");
                }
            }
        }
        _onBtnAttribute() {
            sg.uimgr.showUI("pop_titleAttribute", this._model.getAllTitleAttribute());
        }
        _onBtnActivation() {
            if (this.btnActivation.label == sg.translate("前往激活")) {
                let cfg = sg.dbmgr.get("fashion_title", this._model.selectTitleId);
                if (cfg.tips_show) {
                    sg.uimgr.showNotice(cfg.tips_show);
                }
                else {
                    sg.uimgr.showAccess(this._model.selectTitleId);
                }
            }
            else if (this.btnActivation.label == sg.translate("解锁称号"))
                this._ctrl.reqTitleChange(this._model.selectTitleId);
            else if (this.btnActivation.label == sg.translate("升级称号"))
                this._ctrl.reqTitleLvUp(this._model.selectTitleId);
        }
        _onBtnChange() {
            if (this.btnChange.label == sg.translate("卸下"))
                this._ctrl.reqTitleRemove();
            else if (this.btnChange.label == sg.translate("穿戴") || this.btnChange.label == sg.translate("更换"))
                this._ctrl.reqTitleChange(this._model.selectTitleId);
        }
        _onBtnCollect(event) {
            mvc.collectorCtrl.shouCollectorMainView();
        }
        _updateCollectIcon() {
            let configs = mvc.collectorModel.getCollectorVo().getConfigToLevel();
            mgr.icon.drawTexture("ui_langs/cn/ui/" + configs.btnImage + '.png', this.btnCollect);
        }
        _sort() {
            let titleArr = [];
            this._curTabCfg.forEach((title, index, arr) => {
                let time = new Date(title.timeShow).getTime();
                let passTime = sg.time.getTime() - time >= 0;
                if (mgr.conditionMgr.check([title.showlock], false) && mgr.gplatform.checkChannel(title.condition) && passTime) {
                    titleArr.push(title);
                }
            });
            this._curTabCfg = titleArr;
            this._curTabCfg.sort((a, b) => {
                let isGetA = this._model.vo.title[a.id] ? true : false;
                let isGetB = this._model.vo.title[b.id] ? true : false;
                if (isGetA && isGetB) {
                    let isUseA = this._model.vo.title_id == a.id;
                    let isUseB = this._model.vo.title_id == b.id;
                    if (isUseA)
                        return -1;
                    else if (isUseB)
                        return 1;
                    else
                        return a.id - b.id;
                }
                else if (!isGetA && !isGetB) {
                    let isCanActA = this._model.vo.notActiveId && this._model.vo.notActiveId.indexOf(a.id) != -1;
                    let isCanActB = this._model.vo.notActiveId && this._model.vo.notActiveId.indexOf(b.id) != -1;
                    if ((isCanActA && isCanActB) || (!isCanActA && !isCanActB))
                        return a.id - b.id;
                    else
                        return isCanActA ? -1 : 1;
                }
                else {
                    return isGetA ? -1 : 1;
                }
            });
        }
        _updateTime() {
            this.repeats(1000, this._onTimer, true);
        }
        _onTimer() {
            this.lblTime.text = this._model.getTitleEndTimeById(this._model.selectTitleId);
        }
    }
    mvc.PopTitle = PopTitle;
})(mvc || (mvc = {}));

