(function (mvc) {
    class PopTaobaoRedbag extends ui.view.taobao.pop_taobaoRedbagUI {
        constructor() {
            super(...arguments);
            this.selectedIndex = 0;
            this.jumpUrl = mgr.gplatform.sdkParams.redbagUrl || "";
        }
        initView(...args) {
            this.model = mvc.taobaoRedbagModel;
            this.ctrl = mvc.taobaoRedbagCtrl;
        }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            this.tab.selectedIndex = this.selectedIndex;
            this.showBox();
            this.ctrl.getRedbagInfo();
        }
        initCtrlEvent() {
            this.tab.selectHandler = this.createHandler(this, this.tabSelectHandler, undefined, false);
            this.on(Laya.Event.CLICK, this, this.onClick);
            this.tabR1.id = mvc.REDOT_ID.TAOBAO_REDBAG_TAB1;
            this.tabR2.id = mvc.REDOT_ID.TAOBAO_REDBAG_TAB2;
            this.tabR3.id = mvc.REDOT_ID.TAOBAO_REDBAG_TAB3;
            this.btnR1.id = mvc.REDOT_ID.TAOBAO_REDBAG_TAB1_BTNR1;
            this.btnR2.id = mvc.REDOT_ID.TAOBAO_REDBAG_TAB2_BTNR2;
            this.btnR3.id = mvc.REDOT_ID.TAOBAO_REDBAG_TAB2_BTNR3;
            this.btnR4.id = mvc.REDOT_ID.TAOBAO_REDBAG_TAB2_BTNR4;
            this.btnR5.id = mvc.REDOT_ID.TAOBAO_REDBAG_TAB3_BTNR5;
            this.btnR6.id = mvc.REDOT_ID.TAOBAO_REDBAG_TAB3_BTNR6;
            this.btnR7.id = mvc.REDOT_ID.TAOBAO_REDBAG_TAB3_BTNR7;
        }
        initModelEvent() {
            this.bindModelEvent(this.model, mvc.TaobaoRedbagConst.EVT.UPDATE_VIEW, this.updateView);
        }
        tabSelectHandler(index) {
            this.selectedIndex = index;
            this.showBox();
        }
        showBox() {
            this.box1.visible = false;
            this.box2.visible = false;
            this.box3.visible = false;
            if (this.selectedIndex == 0) {
                this.box1.visible = true;
            }
            else if (this.selectedIndex == 1) {
                this.box2.visible = true;
            }
            else if (this.selectedIndex == 2) {
                this.box3.visible = true;
            }
        }
        updateView() {
            if (this.model.isShowIcon()) {
                let tasks = this.model.redbagVo.task_infos;
                for (let i = 0; i < tasks.length; i++) {
                    let task = tasks[i];
                    if (this["btnGet" + (i + 1)] && this["lbl" + (i + 1)]) {
                        if (task.code == 1) {
                            this["btnGet" + (i + 1)].label = sg.translate("已领取");
                            this["btnGet" + (i + 1)].disabled = true;
                            this["lbl" + (i + 1)].text = sg.translate("剩余：") + (task.left / 10000).toFixed(2) + "%";
                        }
                        else if (task.code == 0) {
                            if (task.progress >= this.model.taobaoRedbagData[i].condition[1]) {
                                this["btnGet" + (i + 1)].label = sg.translate("立即领取");
                                this["btnGet" + (i + 1)].disabled = false;
                                this["lbl" + (i + 1)].text = sg.translate("剩余：") + (task.left / 10000).toFixed(2) + "%";
                            }
                            else {
                                this["btnGet" + (i + 1)].label = sg.translate("未达成");
                                this["btnGet" + (i + 1)].disabled = true;
                                this["lbl" + (i + 1)].text = sg.translate("剩余：") + (task.left / 10000).toFixed(2) + "%";
                            }
                        }
                        else if (task.code == 5) {
                            this["btnGet" + (i + 1)].label = sg.translate("红包已领完");
                            this["btnGet" + (i + 1)].disabled = true;
                            this["lbl" + (i + 1)].text = sg.translate("剩余：0%");
                        }
                        if (this["lblP" + (i + 1)]) {
                            let all = this.model.taobaoRedbagData[i].condition[1];
                            this["lblP" + (i + 1)].text = "(" + (task.progress > all ? (all + "/" + all) : (task.progress + "/" + all)) + ")";
                        }
                    }
                    else {
                        console.warn("某个控件为空");
                        console.warn(this["btnGet" + (i + 1)]);
                        console.warn(this["lbl" + (i + 1)]);
                    }
                }
            }
        }
        onClick(e) {
            let target = e.target;
            switch (target) {
                case this.btnGo:
                    this.jumpUrl && mgr.gplatform.navigateLimitUrl(this.jumpUrl);
                    break;
                case this.btnGet1:
                    this.ctrl.getRedbag(0);
                    break;
                case this.btnGet2:
                    this.ctrl.getRedbag(1);
                    break;
                case this.btnGet3:
                    this.ctrl.getRedbag(2);
                    break;
                case this.btnGet4:
                    this.ctrl.getRedbag(3);
                    break;
                case this.btnGet5:
                    this.ctrl.getRedbag(4);
                    break;
                case this.btnGet6:
                    this.ctrl.getRedbag(5);
                    break;
                case this.btnGet7:
                    this.ctrl.getRedbag(6);
                    break;
            }
        }
    }
    mvc.PopTaobaoRedbag = PopTaobaoRedbag;
})(mvc || (mvc = {}));

