(function (mvc) {
    class TaobaoRedbagCtrl extends sg.CtrlBase {
        constructor() {
            super(...arguments);
            this.lockClick = 0;
        }
        initCtrl() {
            this.model = mvc.taobaoRedbagModel;
        }
        registerMsg() {
            this.onMsg(Proto.TB_REDBAG_INFO, this.onGetRedbagInfo);
            this.onMsg(Proto.TB_REDBAG_TASK_PROGRESS_CHANGE, this.onProgressChange);
            this.onMsg(Proto.TB_REDBAG_REWARD, this.onGetRedbag);
        }
        getRedbagInfo() {
            if (mgr.gplatform.isTaobao()) {
                let data = new Proto.tb_redbag_info_request();
                this.sendMsg(Proto.TB_REDBAG_INFO, data);
            }
        }
        onGetRedbagInfo(data) {
            this.model.changeRedbagInfo(data);
        }
        getRedbag(id) {
            if (mgr.gplatform.isTaobao()) {
                if (Date.now() - this.lockClick > 3000) {
                    if (this.model.checkCanGet(id)) {
                        let data = new Proto.tb_redbag_reward_request();
                        data.id = this.model.taobaoRedbagData[id].typeId;
                        this.sendMsg(Proto.TB_REDBAG_REWARD, data);
                    }
                    else {
                        sg.uimgr.showNotice(sg.translate("未达到领取条件"));
                    }
                    this.lockClick = Date.now();
                }
                else {
                    sg.uimgr.showNotice(sg.translate("操作过于频繁，请稍后再试"));
                }
            }
        }
        onGetRedbag(data) {
            this.model.getRedbag(data);
        }
        onProgressChange(data) {
            this.model.changeRedbagProgress(data);
        }
    }
    mvc.TaobaoRedbagCtrl = TaobaoRedbagCtrl;
})(mvc || (mvc = {}));

