(function (mvc) {
    class TreasureCourtVo extends sg.VoBase {
        constructor() {
            super();
            this.treasureMap = new Map();
        }
        init(data) {
            this.level = data.level;
            this.progress = data.progress;
            this.endTime = data.end_time;
            let adCfg = mgr.toolsMgr.getGlobalVoById("ad_pavilion_upLv_set", 1);
            this.nextAdTime = data.last_ad_time + adCfg[1] * 60;
            this.treasureMap.clear();
            for (let item of data.treasures) {
                let arr = [];
                for (let t of item.treasure) {
                    let vo = new mvc.TreasureItemVo();
                    vo.init(t);
                    arr.push(vo);
                }
                this.treasureMap.set(item.type, arr);
            }
        }
        updateCourt(data) {
            if (this.treasureMap.has(data.type)) {
                this.treasureMap.delete(data.type);
            }
            let arr = [];
            for (let t of data.treasure) {
                let vo = new mvc.TreasureItemVo();
                vo.init(t);
                arr.push(vo);
            }
            this.treasureMap.set(data.type, arr);
        }
        getCurNum(type) {
            if (!this.treasureMap.has(type)) {
                return 0;
            }
            return this.treasureMap.get(type).length;
        }
    }
    mvc.TreasureCourtVo = TreasureCourtVo;
})(mvc || (mvc = {}));

