var mvc;
(function (mvc) {
    class PopTreasureMap extends ui.view.treasure.pop_regionUI {
        initView() {
            this._model = mvc.treasureModel;
            this._ctrl = mvc.treasureCtrl;
            this._maxX = 159;
            this._minX = 59;
            this._zeroX = 109;
            this._activeDis = 30;
        }
        initSendMsg() {
            this._ctrl.reqMapInfo();
        }
        initModelEvent() {
            this.bindModelEvent(this._model, mvc.TreasureConst.EVT.UPDATE_MAP_INFO, this._initMapInfo);
            this.bindModelEvent(this._model, mvc.TreasureConst.EVT.ENTER_MAP, this._updateMapInfo);
        }
        initCtrlEvent() {
            this.list.renderHandler = this.createHandler(this, this._listRenderer, undefined, false);
            this.btnGo.on(Laya.Event.CLICK, this, this._onBtnGo);
            this.btnLeft.on(Laya.Event.CLICK, this, this._onBtnLeft);
            this.btnRight.on(Laya.Event.CLICK, this, this._onBtnRight);
            this.boxMap.on(Laya.Event.MOUSE_DOWN, this, this._onBoxMapMouseDown);
        }
        onAwake() {
            super.onAwake();
            this.lblLock.text = sg.translate("请先解锁上一个地域");
        }
        onEnable() {
            super.onEnable();
        }
        onDisable() {
            super.onDisable();
        }
        _initMapInfo(data) {
            this._maps = data;
            let idx = 0;
            for (let i = 0; i < data.length; i++) {
                let map = data[i];
                if (map.id == this._model.treasureVo.mapId) {
                    idx = i;
                    break;
                }
            }
            this._selectIdx = idx;
            this._updateMapInfo();
        }
        _updateMapInfo() {
            let map = this._maps[this._selectIdx];
            mgr.icon.drawTexture(map.bg, this.imgBg);
            mgr.icon.drawTexture(map.title, this.imgTitle);
            this.list.visible = true;
            this.lblLock.visible = false;
            this.boxLock.visible = false;
            this.list.array = map.tasks;
            this.btnLeft.visible = this._selectIdx != 0;
            this.btnRight.visible = this._selectIdx < this._maps.length - 1;
            if (map.id == this._model.treasureVo.mapId) {
                this.btnGo.label = sg.translate("当前区域");
                this.btnGo.disabled = true;
            }
            else if (map.isOpen) {
                this.btnGo.label = sg.translate("前往区域");
                this.btnGo.disabled = false;
            }
            else {
                this.btnGo.label = sg.translate("暂未解锁");
                this.btnGo.disabled = true;
                let bef = this._maps[this._selectIdx - 1];
                if (bef && !bef.isOpen) {
                    this.list.visible = false;
                    this.lblLock.visible = true;
                }
                this.boxLock.visible = true;
            }
            this.redTips.visible = this._model.isNewMap(map.id);
        }
        _listRenderer(cell, idx) {
            let data = cell.dataSource;
            if (!data)
                return;
            let cfg = sg.dbmgr.get("treasureHunt_mapTask", data.id);
            let imgBg = cell.getChildByName("imgBg");
            let lblCond = cell.getChildByName("lblCond");
            let lblProg = cell.getChildByName("lblProg");
            let imgOk = cell.getChildByName("imgOk");
            imgBg.alpha = idx % 2 == 0 ? 0.75 : 1;
            lblCond.text = cfg.name;
            let max = cfg.condition[cfg.condition.length - 1];
            let cur = data.progress;
            lblProg.text = `(${cur}/${max})`;
            imgOk.visible = max <= cur;
            lblProg.visible = max > cur;
        }
        _onBoxMapMouseDown(evt) {
            this._startX = evt.stageX;
            this.boxMap.on(Laya.Event.MOUSE_MOVE, this, this._onBoxMapMouseMove);
            this.boxMap.on(Laya.Event.MOUSE_UP, this, this._onBoxMapMouseUp);
            this.boxMap.on(Laya.Event.MOUSE_OUT, this, this._onBoxMapMouseUp);
        }
        _onBoxMapMouseMove(evt) {
            let delta = evt.stageX - this._startX;
            this.imgBg.x = Math.max(this._minX, Math.min(this._maxX, this._zeroX + delta));
        }
        _onBoxMapMouseUp(evt) {
            let delta = evt.stageX - this._startX;
            if (Math.abs(delta) >= this._activeDis) {
                if (delta > 0) {
                    this._onBtnLeft();
                }
                else {
                    this._onBtnRight();
                }
            }
            this.imgBg.x = this._zeroX;
            this.boxMap.off(Laya.Event.MOUSE_MOVE, this, this._onBoxMapMouseMove);
            this.boxMap.off(Laya.Event.MOUSE_UP, this, this._onBoxMapMouseUp);
            this.boxMap.off(Laya.Event.MOUSE_OUT, this, this._onBoxMapMouseUp);
        }
        _onBtnLeft() {
            if (!this._maps || this._selectIdx == 0)
                return;
            this._selectIdx--;
            this._updateMapInfo();
        }
        _onBtnRight() {
            if (!this._maps || this._selectIdx >= this._maps.length - 1)
                return;
            this._selectIdx++;
            this._updateMapInfo();
        }
        _onBtnGo() {
            let map = this._maps[this._selectIdx];
            if (!map || !map.isOpen)
                return;
            this._ctrl.reqEnterMap(map.id);
            this._model.clearNewMap(map.id);
            this.closeSelf();
        }
    }
    mvc.PopTreasureMap = PopTreasureMap;
})(mvc || (mvc = {}));

