(function (mvc) {
    class PopTreasureShop extends ui.view.treasure.pop_treasureShopUI {
        initView(type) {
            this._model = mvc.storeModel;
            this._ctrl = mvc.storeCtrl;
        }
        initSendMsg() {
            mvc.storeCtrl.reqStoreAllInfo();
        }
        initModelEvent() {
            this.bindModelEvent(mvc.storeModel, mvc.StoreConst.EVT.REFRESH_RANDOM_STORE, this._refreshShop);
            this.bindModelEvent(mvc.storeModel, mvc.StoreConst.EVT.REFRESH_COMMODITY, this._refreshShop);
            this.bindModelEvent(mvc.storeModel, mvc.StoreConst.EVT.REFRESH_STORE, this._refreshShop);
            this.bindModelEvent(mvc.bagModel, mvc.BagConst.EVT.ITEM_NUM_CHANGE, this._refreshShop);
            this.bindModelEvent(mvc.roleModel, mvc.RoleConst.EVT.CHANGE_ASSTE, this._refreshShop);
        }
        initCtrlEvent() {
            this.list.vScrollBarSkin = "";
            this.tabType.selectHandler = this.createHandler(this, this._onTabSelect, undefined, false);
            this.btnRefresh.on(Laya.Event.CLICK, this, this._onBtnRefresh);
        }
        onAwake() {
            super.onAwake();
            let shopCfgs = this._shopCfgs = sg.dbmgr.getArray("shop_shop", { funcOpen: mvc.FUNC_ID.COURT });
            let tabs = "";
            let isFirst = true;
            for (let shop of shopCfgs) {
                if (!isFirst) {
                    tabs += ",";
                }
                isFirst = false;
                tabs += shop.name;
            }
            this.tabType.labels = tabs;
            this.tabType.selectedIndex = 0;
            this.lblRefreshTips.text = sg.translate("今日刷新次数已用尽");
        }
        onEnable() {
            super.onEnable();
        }
        onDisable() {
            super.onDisable();
        }
        _refreshShop() {
            this._onTabSelect(this.tabType.selectedIndex);
        }
        _onTabSelect(idx) {
            if (idx < 0)
                return;
            let cfg = this._shopCfgs[idx];
            this.list.array = mvc.storeModel.getStoreCommodity(cfg.id, cfg.random);
            let url = mgr.toolsMgr.getIconById(cfg.asset[0]);
            mgr.icon.drawTexture(mgr.icon.getIconPath(url), this.imgCoin);
            this.lblCoin.text = mgr.toolsMgr.getCountById(cfg.asset[0]).toString();
            if (cfg.random) {
                this.boxRefresh.visible = true;
                let shopVo = mvc.storeModel.getStoreItemMapById(cfg.id);
                if (!shopVo)
                    return;
                let max = cfg.refreshLimit + cfg.refreshTime;
                let num = shopVo.free_count == 1 ? 0 : 1;
                let curNum = max - shopVo.refresh_times - num;
                if (curNum <= 0) {
                    this.lblRefreshNum.visible = false;
                    this.lblRefreshTips.visible = true;
                }
                else {
                    this.lblRefreshNum.visible = true;
                    this.lblRefreshTips.visible = false;
                    this.lblRefreshNum.text = `${curNum}/${max}`;
                    this.lblRefreshNum.color = shopVo.free_count == 0 ? mvc.COLOR.RED : mvc.COLOR.GREEN;
                }
            }
            else {
                this.boxRefresh.visible = false;
            }
        }
        _onBtnRefresh() {
            if (!this._shopCfgs)
                return;
            let shop = this._shopCfgs[this.tabType.selectedIndex];
            let shopVo = mvc.storeModel.getStoreItemMapById(shop.id);
            if (!shop || !shopVo)
                return;
            let max = shop.refreshLimit + shop.refreshTime;
            let num = shopVo.free_count == 1 ? 0 : 1;
            let curNum = max - shopVo.refresh_times - num;
            if (curNum <= 0) {
                sg.uimgr.showNotice(sg.translate("今日刷新次数已用尽，请明日再来"));
                return;
            }
            mvc.storeCtrl.reqRefreStore(shop.id);
        }
    }
    mvc.PopTreasureShop = PopTreasureShop;
})(mvc || (mvc = {}));

