(function (mvc) {
    class PopTreasureToolStrengthen extends ui.view.treasure.pop_strengthenUI {
        initView(tooType) {
            this._model = mvc.treasureModel;
            this._ctrl = mvc.treasureCtrl;
            this._toolType = tooType;
        }
        initSendMsg() {
        }
        initModelEvent() {
            this.bindModelEvent(mvc.bagModel, mvc.BagConst.EVT.ITEM_NUM_CHANGE, this._onItemNumChange);
            this.bindModelEvent(this._model, mvc.TreasureConst.EVT.UPDATE_TOOL_WASH_INFO, this._updateWashInfo);
            this.bindModelEvent(this._model, mvc.TreasureConst.EVT.UPDATE_TOOL_LV_INFO, this._onLvUp);
        }
        initCtrlEvent() {
            this.tabType.selectHandler = this.createHandler(this, this._onTabSelect, undefined, false);
            this.cbUseGold.on(Laya.Event.CHANGE, this, this._onCbUseGoldChange);
            this.btnLvUp.on(Laya.Event.CLICK, this, this._onBtnLvUp);
            this.btnWash.on(Laya.Event.CLICK, this, this._onBtnWash);
            this.btnSave.on(Laya.Event.CLICK, this, this._onBtnSave);
            this.unitCurrent.updateData("", [mvc.AssetsID.GOLD, mvc.MainConst.ITEM_ID.TREASURE_GOLD], true);
        }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            this.tabType.selectedIndex = 0;
            this._updateIcon();
        }
        onDisable() {
            this.tabType.selectedIndex = -1;
            super.onDisable();
        }
        _onLvUp() {
            this._updateIcon();
            this._updateLvInfo();
        }
        _onItemNumChange() {
            this._onCbUseGoldChange();
            this._updateLvUpCost();
        }
        _updateIcon() {
            let vo = this._model.treasureVo.getToolVoByType(this._toolType);
            if (!vo)
                return;
            this.clipQua.index = vo.clipQua;
            mgr.icon.drawTexture(vo.imgIcon, this.imgIcon);
            this.lblName.text = vo.cfg.name;
            let grade = vo.grade;
            let lv = vo.lv;
            let v1 = grade;
            let v2 = lv;
            this.lblState.text = StringEx.format(sg.translate("${v1}阶${v2}级"), {"v1":v1,"v2":v2});
        }
        _updateLvInfo() {
            if (this.tabType.selectedIndex != 0)
                return;
            let vo = this._model.treasureVo.getToolVoByType(this._toolType);
            if (!vo)
                return;
            this.listLvUp.array = vo.getLevelAttrList();
            this.lblTask.text = vo.getTaskStr();
            this._updateLvUpCost();
            if (vo.isMaxLv()) {
                this.btnLvUp.label = sg.translate("已满级");
                this.btnLvUp.disabled = true;
            }
            else {
                this.btnLvUp.disabled = false;
                if (vo.cfg.break == 1) {
                    this.btnLvUp.label = sg.translate("突破");
                }
                else {
                    this.btnLvUp.label = sg.translate("升级");
                }
            }
        }
        _updateLvUpCost() {
            let vo = this._model.treasureVo.getToolVoByType(this._toolType);
            if (!vo)
                return;
            if (!vo.cfg.consume) {
                this.boxLvUpCost.visible = false;
                return;
            }
            this.boxLvUpCost.visible = true;
            let cost = vo.cfg.consume[0];
            mgr.icon.drawTexture(mgr.icon.getIconPath(mgr.toolsMgr.getIconById(cost[0])), this.imgLvUpCost);
            this.lblLvUpCost.text = cost[1].toString();
            this.lblLvUpCost.color = mgr.toolsMgr.getCountById(cost[0]) >= cost[1] ? "#63AE43" : "#B02121";
        }
        _updateWashInfo() {
            if (this.tabType.selectedIndex != 1)
                return;
            let vo = this._model.treasureVo.getToolVoByType(this._toolType);
            if (!vo)
                return;
            this.listPropBef.array = vo.getWashAttrBef();
            this.listPropAft.array = vo.getWashAttrAft();
            if (this.listPropAft.length == 0) {
                this.btnWash.x = 78;
                this.btnSave.visible = false;
            }
            else {
                this.btnWash.x = -22;
                this.btnSave.visible = true;
            }
            this._onCbUseGoldChange();
        }
        _onTabSelect(idx) {
            if (idx == 0) {
                this.boxRecast.visible = false;
                this.boxLvUp.visible = true;
                this._updateLvInfo();
            }
            else if (idx == 1) {
                this.boxRecast.visible = true;
                this.boxLvUp.visible = false;
                this._updateWashInfo();
            }
        }
        _onCbUseGoldChange() {
            let cfgId = this.cbUseGold.selected ? "treasure_recast_gold" : "treasure_recast_cystal";
            let costCfg = mgr.toolsMgr.getGlobalVoById(cfgId, 1)[0];
            mgr.icon.drawTexture(mgr.icon.getIconPath(mgr.toolsMgr.getIconById(costCfg[0])), this.imgWashCost);
            this.lblWashCost.text = costCfg[1].toString();
            this.lblWashCost.color = mgr.toolsMgr.getCountById(costCfg[0]) >= costCfg[1] ? "#63AE43" : "#B02121";
        }
        _onBtnLvUp() {
            let vo = this._model.treasureVo.getToolVoByType(this._toolType);
            if (!vo)
                return;
            if (vo.cfg.break == 1) {
                if (vo.task.progress < vo.cfg.task[vo.cfg.task.length - 1]) {
                    sg.uimgr.showNotice(sg.translate("突破任务尚未完成！"));
                    return;
                }
                this._ctrl.reqToolBreak(this._toolType);
            }
            else {
                if (!mgr.toolsMgr.checkConsume(vo.cfg.consume)) {
                    sg.uimgr.showNotice(sg.translate("材料不足，升级失败！"));
                    return;
                }
                this._ctrl.reqToolLvUp(this._toolType);
            }
        }
        _onBtnWash() {
            let cfgId = this.cbUseGold.selected ? "treasure_recast_gold" : "treasure_recast_cystal";
            let costCfg = mgr.toolsMgr.getGlobalVoById(cfgId, 1);
            if (!mgr.toolsMgr.checkConsume(costCfg, false)) {
                sg.uimgr.showNotice(sg.translate("材料不足，洗练失败！"));
                return;
            }
            if (this.cbUseGold.selected) {
                mvc.mainModel.consumeJade(costCfg, 1, () => {
                    this._ctrl.reqToolWash(this._toolType, this.cbUseGold.selected ? 2 : 1);
                });
            }
            else {
                this._ctrl.reqToolWash(this._toolType, this.cbUseGold.selected ? 2 : 1);
            }
        }
        _onBtnSave() {
            if (this.listPropAft.length == 0)
                return;
            this._ctrl.reqReplaceToolWash(this._toolType);
        }
    }
    mvc.PopTreasureToolStrengthen = PopTreasureToolStrengthen;
})(mvc || (mvc = {}));

