            super.dataSource = data;
            if (!data)
                return;
            this.lblName.text = data.name;
            let vos = mvc.ItemVo.createItemVos(data.reward);
            this.listReward.array = vos;
            let limit = data.limitTime;
            let cur = mvc.dailyGiftModel.dailyGiftVo.getBuyTime(data.id);
            let last = limit - cur;
            let v1 = last;
            let v2 = limit;
            this.lblLimit.text = StringEx.format(sg.translate("每日限购: ${v1}/${v2}"), {"v1":v1,"v2":v2});
            this.lblLimit.color = last == 0 ? mvc.COLOR.RED : mvc.COLOR.GREEN;
