(function (mvc) {
    class UnitTreasureMap extends Laya.Box {
        onAwake() {
            super.onAwake();
            this._content = new Laya.Box();
            this.addChild(this._content);
            this._cells = [];
            this._clipTreasure = new Laya.Clip();
            this._clipTreasure.autoPlay = true;
            this._clipTreasure.visible = false;
            this._clipTreasure.clipX = 4;
            this._clipTreasure.clipY = 2;
            this._clipTreasure.anchorX = this._clipTreasure.anchorY = 0.5;
            this.addChild(this._clipTreasure);
            this._initParam();
        }
        onEnable() {
            super.onEnable();
        }
        _initParam() {
            this._scrollX = 0;
            this._scrollY = 0;
            this._offsetX = 0;
            this._offsetY = 0;
            this._treasureX = 0;
            this._treasureY = 0;
        }
        onDisable() {
            super.onDisable();
        }
        get scrollX() {
            return this._scrollX;
        }
        set scrollX(x) {
            this._scrollX = x;
            this.callLater(this._updateItems);
        }
        get scrollY() {
            return this._scrollY;
        }
        set scrollY(y) {
            this._scrollY = y;
            this.callLater(this._updateItems);
        }
        setOffset(x, y) {
            this._offsetX = x;
            this._offsetY = y;
            this.callLater(this._updateItems);
        }
        initMapCfg(numX, numY, cellW, cellH, sources) {
            this._numX = numX;
            this._numY = numY;
            this._cellW = cellW;
            this._cellH = cellH;
            this._mapSources = sources;
            this.callLater(this.onResize);
        }
        showTreasure(x, y, skin) {
            this._treasureX = x;
            this._treasureY = y;
            mgr.icon.drawTexture(skin, this._clipTreasure);
            this._clipTreasure.visible = true;
            this.callLater(this._updateTreasurePos);
        }
        hideTreasure() {
            this._clipTreasure.visible = false;
        }
        onResize() {
            this.scrollRect = new Laya.Rectangle(0, 0, this.width, this.height);
            this._cellX = Math.ceil(this.width / this._cellW) + 1;
            this._cellY = Math.ceil(this.height / this._cellH) + 1;
            let total = this._cellX * this._cellY;
            for (let i = 0; i < total; i++) {
                let img;
                if (i < this._cells.length) {
                    img = this._cells[i];
                }
                else {
                    img = new Laya.Image();
                    this._cells.push(img);
                    this._content.addChild(img);
                }
                img.size(this._cellW, this._cellH);
                img.x = i % this._cellX * this._cellW;
                img.y = Math.floor(i / this._cellX) * this._cellH;
            }
            this._updateItems();
        }
        _updateItems() {
            let self = this;
            let px = self._scrollX - self._offsetX;
            let py = self._scrollY - self._offsetY;
            self._content.x = -(px % self._cellW);
            self._content.y = -(py % self._cellH);
            let startX = px >= 0 ? Math.floor(px / self._cellW) : Math.ceil(px / self._cellW);
            let startY = py >= 0 ? Math.floor(py / self._cellH) : Math.ceil(py / self._cellH);
            for (let i = 0; i < self._cells.length; i++) {
                let cx = startX + i % self._cellX;
                let cy = startY + Math.floor(i / self._cellX);
                let idx = (cy % self._numY) * self._numX + (cx % self._numX);
                let url = mgr.icon.getIconPath(self._mapSources[idx]);
                mgr.icon.drawTexture(url, self._cells[i]);
            }
            this._updateTreasurePos();
        }
        _updateTreasurePos() {
            this._clipTreasure.x = this._treasureX - this._scrollX + this._offsetX;
            this._clipTreasure.y = this._treasureY - this._scrollY + this._offsetY;
        }
    }
    mvc.UnitTreasureMap = UnitTreasureMap;
})(mvc || (mvc = {}));

