            mgr.redotMgr.check(mvc.REDOT_ID.CONSTELLATION_QINGLONG_UP_GRADE);
            mgr.redotMgr.check(mvc.REDOT_ID.CONSTELLATION_BAIHU_UP_LEVEL);
            mgr.redotMgr.check(mvc.REDOT_ID.CONSTELLATION_BAIHU_UP_GRADE);
            mgr.redotMgr.check(mvc.REDOT_ID.CONSTELLATION_QINGLONG_POST);
