            this.btn2.on(Laya.Event.CLICK, this, this._onbtnLvUpClick, [2]);
            this.btn3.on(Laya.Event.CLICK, this, this._onbtnLvUpClick, [3]);
            this.btn4.on(Laya.Event.CLICK, this, this._onbtnLvUpClick, [6]);
            this.btn5.on(Laya.Event.CLICK, this, this._onbtnLvUpClick, [9]);
