(function (mvc) {
    class PopSiftView extends ui.view.origin.pop_siftUI {
        initView() {
            this._changeBefore = this._deepClone(mvc.yinYangModel.selectConditions);
        }
        _deepClone(obj) {
            if (obj === null || typeof obj !== 'object') {
                return obj;
            }
            if (obj instanceof Array) {
                return obj.reduce((arr, item, i) => {
                    arr[i] = this._deepClone(item);
                    return arr;
                }, []);
            }
            if (obj instanceof Object) {
                return Object.keys(obj).reduce((newObj, key) => {
                    newObj[key] = this._deepClone(obj[key]);
                    return newObj;
                }, {});
            }
        }
        initCtrlEvent() {
            this.listType.renderHandler = this.createHandler(this, this._onListTypeRender, null, false);
            this.listLv.renderHandler = this.createHandler(this, this._onListLvRender, null, false);
            this.listQuilty.renderHandler = this.createHandler(this, this._onListQuiltyRender, null, false);
            this.listType.selectHandler = this.createHandler(this, this._onListTypeSelected, null, false);
            this.listLv.selectHandler = this.createHandler(this, this._onListLvSelected, null, false);
            this.listQuilty.selectHandler = this.createHandler(this, this._onListQuiltySelected, null, false);
            this.listType.selectEnable = this.listLv.selectEnable = this.listQuilty.selectEnable = true;
            this.btnConfirm.on(Laya.Event.CLICK, this, this._onBtnConfirm);
        }
        onEnable() {
            super.onEnable();
            this._updateView();
        }
        _updateView() {
            this.listType.array = mgr.toolsMgr.objectToArray(this._changeBefore[1].configs);
            this.listLv.array = mgr.toolsMgr.objectToArray(this._changeBefore[2].configs);
            this.listQuilty.array = mgr.toolsMgr.objectToArray(this._changeBefore[3].configs);
        }
        _onListTypeRender(cell, index) {
            let data = cell.dataSource;
            if (data == null) {
                return;
            }
            cell.label = mvc.yinYangModel.vo.getOriginTypeName(data.id);
            cell.selected = !!this._changeBefore[1].slected[data.id];
        }
        _onListLvRender(cell, index) {
            let data = cell.dataSource;
            if (data == null) {
                return;
            }
            cell.label = data.start + "~" + data.end;
            cell.selected = !!this._changeBefore[2].slected[data.start];
        }
        _onListQuiltyRender(cell, index) {
            let data = cell.dataSource;
            if (data == null) {
                return;
            }
            let scfg = sg.dbmgr.get("color", data.quality);
            cell.label = scfg.qualityName;
            cell.labelColors = scfg.stringColor + "," + scfg.stringColor + "," + scfg.stringColor + "," + scfg.stringColor;
            cell.selected = !!this._changeBefore[3].slected[data.quality];
        }
        _onListTypeSelected(index) {
            if (this.listType.array && this.listType.array[index]) {
                let data = this.listType.array[index];
                let slected = this._changeBefore[1].slected[data.id];
                if (!!slected) {
                    this._changeBefore[1].count--;
                    this._changeBefore[1].slected[data.id] = 0;
                }
                else {
                    this._changeBefore[1].count++;
                    this._changeBefore[1].slected[data.id] = 1;
                }
                this.listType.refresh();
            }
        }
        _onListLvSelected(index) {
            if (this.listLv.array && this.listLv.array[index]) {
                let data = this.listLv.array[index];
                let slected = this._changeBefore[2].slected[data.start];
                if (!!slected) {
                    this._changeBefore[2].count--;
                    for (let i = data.start; i <= data.end; i++) {
                        this._changeBefore[2].slected[i] = 0;
                    }
                }
                else {
                    this._changeBefore[2].count++;
                    for (let i = data.start; i <= data.end; i++) {
                        this._changeBefore[2].slected[i] = 1;
                    }
                }
                this.listLv.refresh();
            }
        }
        _onListQuiltySelected(index) {
            if (this.listQuilty.array && this.listQuilty.array[index]) {
                let quilty = this.listQuilty.array[index];
                let slected = this._changeBefore[3].slected[quilty.quality];
                if (!!slected) {
                    this._changeBefore[3].count--;
                    this._changeBefore[3].slected[quilty.quality] = 0;
                }
                else {
                    this._changeBefore[3].count++;
                    this._changeBefore[3].slected[quilty.quality] = 1;
                }
                this.listQuilty.refresh();
            }
        }
        _onBtnConfirm() {
            mvc.yinYangModel.selectConditions = this._changeBefore;
            mvc.yinYangModel.fireEvent(mvc.YinYangConst.EVT.FILTER_BAG_LIST);
            this.closeSelf();
        }
    }
    mvc.PopSiftView = PopSiftView;
})(mvc || (mvc = {}));

