            if (this._currVo == null || this._nextvo == null) {
                return;
            }
            this.lbCurrLv.text = sg.translate("等级") + this._currVo.grade;
            this.lbNextLv.text = sg.translate("等级") + this._nextvo.grade;
            let lblName = this.boxProp.getChildByName("lblName");
            let lblValue = this.boxProp.getChildByName("lblValue");
            let lblValue1 = this.boxProp.getChildByName("lblValue1");
            let imgUp = this.boxProp.getChildByName("imgUp");
            let curUpConfig = this._currVo.getUpConfig();
            let nextUpConfig = this._currVo.getUpConfig(this._nextvo.id, this._nextvo.grade);
