(function (mvc) {
    class WxRechargeModel extends sg.ModelBase {
        constructor() {
            super(...arguments);
            this.haveAuthority = true;
        }
        initModel() {
        }
        willEnterGame() {
            mgr.gplatform.checkPopupActivity();
        }
        setRechargeInfo(data) {
            this.endTime = data.end_time;
            this.isAllBought = data.is_all_bought == 1;
            this.boughtProducts = data.bought_products;
            if (!this.haveAuthority || this.endTime == 0 || this.endTime < sg.time.getSecondTime() || this.isAllBought)
                mvc.activityModel.removeActivityVo(mvc.FUNC_ID.WX_RECHARGE_GIFT, false);
            else {
                if (mvc.activityModel.tempVos.get(mvc.FUNC_ID.WX_RECHARGE_GIFT))
                    mvc.activityModel.tempVos.get(mvc.FUNC_ID.WX_RECHARGE_GIFT).end_time = this.endTime;
            }
        }
        isPassTime() {
            if (!mgr.gplatform.isWx() || mgr.gplatform.gVo.osPlatform == 2 || !this.haveAuthority || this.isAllBought)
                return false;
            if (this.endTime == undefined)
                return true;
            let nowTime = sg.time.getSecondTime();
            return this.endTime > nowTime;
        }
        rechargeTrigger(data) {
            this.endTime = data.end_time;
            mvc.activityModel.createAndAddIcon(mvc.FUNC_ID.WX_RECHARGE_GIFT);
            this.triggerGift();
        }
        rechargeBought(data) {
            this.isAllBought = data.is_all_bought == 1;
            this.boughtProducts = data.bought_products;
            sg.uimgr.showUI("pop_getReward", sg.translate("专享福利"), data.reward, false, "", Laya.Handler.create(this, this._getReward));
        }
        rechargeTimeOut(data) {
            this.endTime = 0;
            mvc.activityModel.removeActivityVo(mvc.FUNC_ID.WX_RECHARGE_GIFT, false);
        }
        triggerGift() {
            if (!mgr.gplatform.isWx() || mgr.gplatform.gVo.osPlatform == 2 || !this.haveAuthority)
                return;
            mvc.rechargeCtrl.reqWxRechargeByPhp();
        }
        _getReward() {
            if (!this.isAllBought)
                this.triggerGift();
            else
                mvc.activityModel.removeActivityVo(mvc.FUNC_ID.WX_RECHARGE_GIFT, false);
        }
    }
    mvc.WxRechargeModel = WxRechargeModel;
})(mvc || (mvc = {}));

