(function (mvc) {
    class GhostHuntModel extends sg.ModelBase {
        registerEvents() {
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.BG_ACT_GhostHunt_PLAY_NEW_LEVEL, this.checkNewLevelRed, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.BG_ACT_GhostHunt_PLAY_REWARD, this.checkRewardRed, this);
        }
        beginGame(data) {
            this.fireEvent(mvc.GhostHuntConst.EVT.BEGING_GAME, data);
        }
        pauseGame(data) {
            this.fireEvent(mvc.GhostHuntConst.EVT.PAUSE_GAME, data);
        }
        reliveGame(data) {
            this.fireEvent(mvc.GhostHuntConst.EVT.RELIVE_GAME, data);
        }
        helpChange(data) {
            this.allLevelInfo.silk_num = data.silk_num;
        }
        endGame(data) {
            let levels = this.allLevelInfo.bg_ghost_infos;
            this.allLevelInfo.is_cheat = data.is_cheat;
            if (!levels.length) {
                this._pushNewTask(data, levels);
            }
            else {
                for (let i = 0; i < levels.length; i++) {
                    if (levels[i].level_id == data.level_id) {
                        this.allLevelInfo.bg_ghost_infos[i].task_infos = data.task_infos;
                        this.allLevelInfo.bg_ghost_infos[i].history_value = data.history_value;
                        break;
                    }
                    if (i == levels.length - 1) {
                        this._pushNewTask(data, levels);
                    }
                }
            }
            this.fireEvent(mvc.GhostHuntConst.EVT.END_GAME, data);
        }
        _pushNewTask(data, levels) {
            let vo = new Proto.bg_ghost_info_p();
            vo.level_id = data.level_id;
            vo.history_value = data.history_value;
            vo.task_infos = data.task_infos;
            levels.push(vo);
            this.newLevel = vo.level_id + 1;
            mgr.redotMgr.check(mvc.REDOT_ID.BG_ACT_GhostHunt_PLAY_NEW_LEVEL);
        }
        levelInfo(data) {
            this.allLevelInfo = data;
            mgr.redotMgr.check(mvc.REDOT_ID.BG_ACT_GhostHunt_PLAY_REWARD);
            mgr.redotMgr.check(mvc.REDOT_ID.BG_ACT_GhostHunt_PLAY_NEW_LEVEL);
            this.fireEvent(mvc.GhostHuntConst.EVT.LEVEL_INFO, data);
        }
        waveCom(data) {
            this.fireEvent(mvc.GhostHuntConst.EVT.WAVE_COM, data);
        }
        award(data) {
            if (this.allLevelInfo && this.allLevelInfo.bg_ghost_infos) {
                let infos = this.allLevelInfo.bg_ghost_infos;
                for (let i = 0; i < infos.length; i++) {
                    if (infos[i].level_id == data.level_id) {
                        for (let j = 0; j < infos[i].task_infos.length; j++) {
                            if (infos[i].task_infos[j].task_id == data.task_info.task_id) {
                                this.allLevelInfo.bg_ghost_infos[i].task_infos[j].task_status = data.task_info.task_status;
                                this.allLevelInfo.bg_ghost_infos[i].task_infos[j].task_value = data.task_info.task_value;
                            }
                        }
                        break;
                    }
                }
            }
            sg.uimgr.showUI("pop_getReward", sg.translate("恭喜获得"), data.reward);
            this.fireEvent(mvc.GhostHuntConst.EVT.AWARD);
            mgr.redotMgr.check(mvc.REDOT_ID.BG_ACT_GhostHunt_PLAY_REWARD);
        }
        checkNewLevelRed() {
            if (this.newLevel) {
                if (this.isUnlockLevel(this.newLevel)) {
                    return 1;
                }
                else {
                    return 0;
                }
            }
            return 0;
        }
        checkRewardRed() {
            let allLevelInfo = this.allLevelInfo;
            let canGet = 0;
            if (allLevelInfo && allLevelInfo.bg_ghost_infos) {
                for (let i = 0; i < allLevelInfo.bg_ghost_infos.length; i++) {
                    for (let j = 0; j < allLevelInfo.bg_ghost_infos[i].task_infos.length; j++) {
                        if (allLevelInfo.bg_ghost_infos[i].task_infos[j].task_status == 2) {
                            canGet = 1;
                            break;
                        }
                    }
                    if (canGet) {
                        break;
                    }
                }
            }
            return canGet;
        }
        isUnlockLevel(levelID, isTips = false) {
            let actId = 243;
            let cfgGlobal = this.cfgGlobal()[levelID];
            if (!cfgGlobal) {
                return;
            }
            let vo = mvc.activityModel.openActivityVo.get(actId);
            let limitTime = vo.start_time + (cfgGlobal.date - 1) * 86400;
            let curTime = sg.time.getSecondTime();
            if (curTime >= limitTime) {
                if (levelID == 1) {
                    return 1;
                }
                else {
                    let allLevel = this.allLevelInfo;
                    for (let i = 0; i < allLevel.bg_ghost_infos.length; i++) {
                        if (levelID - 1 == allLevel.bg_ghost_infos[i].level_id) {
                            if (allLevel.bg_ghost_infos[i].history_value) {
                                return 1;
                            }
                            else {
                                if (isTips) {
                                    sg.uimgr.showNotice(sg.translate("请先通关上一关"));
                                }
                                return 0;
                            }
                        }
                        if (i == allLevel.bg_ghost_infos.length - 1) {
                            if (isTips) {
                                sg.uimgr.showNotice(sg.translate("请先通关上一关"));
                            }
                            return 0;
                        }
                    }
                }
            }
            else {
                if (isTips) {
                    sg.uimgr.showNotice(mgr.UIAssist.$(sg.translate("下一关将于{1}后解锁"), sg.time.formatTimeStrT("F14", limitTime - curTime)));
                }
                return 0;
            }
        }
        cfgGlobal() {
            if (!this._cfgGlobal) {
                this._cfgGlobal = sg.dbmgr.getDB("backgroundActive_active8Global");
            }
            return this._cfgGlobal;
        }
        getSymbol() {
            if (!this._symbolPool || !this._symbolPool.length) {
                this._symbolPool = [];
                return new Laya.Image();
            }
            return this._symbolPool.pop();
        }
        pushSymbol(img) {
            if (!this._symbolPool) {
                this._symbolPool = [];
            }
            if (this._symbolPool.length < 30) {
                this._symbolPool.push(img);
            }
        }
        closeAllGhostUI() {
            sg.uimgr.closeUI("pop_GhostHuntLevel");
            sg.uimgr.closeUI("pop_GhostHuntEnter");
            sg.uimgr.closeUI("pop_GhostHuntResult");
            sg.uimgr.closeUI("pop_GhostHuntConfirm");
        }
    }
    mvc.GhostHuntModel = GhostHuntModel;
})(mvc || (mvc = {}));

var mvc;
