(function (mvc) {
    class PopGhostHuntResult extends ui.view.bgActivity7.pop_GhostHuntResultUI {
        onAwake() {
            super.onAwake();
            this.lblDesc.text = sg.translate("通过波数:");
        }
        initModelEvent() {
            this.bindModelEvent(mvc.ghostHuntModel, mvc.GhostHuntConst.EVT.AWARD, this._setResult);
        }
        initCtrlEvent() {
            this.listReward.vScrollBarSkin = null;
            this.listReward.renderHandler = this.createHandler(this, this._renderReward, null, false);
        }
        onEnable() {
            super.onEnable();
            this._setResult();
        }
        _setResult() {
            let data = this.openParams[0];
            this.lblFightCount.text = this.openParams[1];
            this.lblHightScore.text = data.history_value + (data.score > 0 && data.history_value == data.score ? sg.translate("新纪录!") : "");
            this.lblScore.text = data.score + "";
            let cfg = sg.dbmgr.get("backgroundActive_active8Global", data.level_id);
            this.lblLevelName.text = cfg.title;
            if (cfg.isInfinite) {
                this.lblDesc.visible = true;
                this.lblWave.text = data.turn + "";
            }
            else {
                this.lblDesc.visible = false;
                this.lblWave.text = "";
            }
            if (data.is_win == 2) {
                if (cfg.isInfinite) {
                    this.boxResultSuc.skin = "tzjs";
                }
                else {
                    this.boxResultSuc.skin = "cg";
                }
            }
            else {
                this.boxResultSuc.skin = "sb";
            }
            let allLevel = mvc.ghostHuntModel.allLevelInfo.bg_ghost_infos;
            let curTask;
            for (let i = 0; i < allLevel.length; i++) {
                if (allLevel[i].level_id == data.level_id) {
                    curTask = allLevel[i].task_infos;
                    break;
                }
            }
            let arrTask = [];
            let tempCFG;
            let tempData;
            for (let i = 0; i < cfg.target.length; i++) {
                tempCFG = sg.dbmgr.get("backgroundActive_active8Target", cfg.target[i]);
                tempData = new mvc.GhostHuntTargetVO();
                tempData.title = tempCFG.title;
                tempData.reward = mvc.ItemVo.createItemVos(tempCFG.reward);
                tempData.levelId = data.level_id;
                tempData.taskId = cfg.target[i];
                tempData.status = 1;
                if (curTask) {
                    for (let j = 0; j < curTask.length; j++) {
                        if (curTask[j].task_id == cfg.target[i]) {
                            tempData.status = curTask[j].task_status;
                            break;
                        }
                    }
                }
                arrTask.push(tempData);
            }
            this.listReward.array = arrTask;
        }
        _renderReward(unit) {
            unit.initView(unit.dataSource);
        }
        onDisable() {
            super.onDisable();
            sg.uimgr.closeUI("pop_GhostHuntLevel");
        }
    }
    mvc.PopGhostHuntResult = PopGhostHuntResult;
})(mvc || (mvc = {}));

