(function (mvc) {
    class UnitGhostHuntRole extends ui.view.bgActivity7.unit_GhostHuntRoleUI {
        initView(id, sign) {
            if (!this._model) {
                this._model = mvc.ghostHuntModel;
            }
            this.unitRole.changeShowMode(false, id);
            this.unitRole.loadedHandle = () => {
                this.unitRole.play("stand");
            };
            this.unitRole.loadRole(id, "UnitGhostHuntRole");
            this.unitHit.changeShowMode(false, "9109");
            this.unitHit.loadedHandle = () => {
                this.unitHit.visible = false;
            };
            this.unitHit.loadRole("9109", "UnitGhostHuntRole", false);
            for (let i = 0; i < this.sprImg.numChildren; i++) {
                this._model.pushSymbol(this.sprImg.getChildAt(i));
            }
            this.sprImg.removeChildren();
            this._setSignImg(sign);
            this.hp = sign.length;
        }
        _setSignImg(sign) {
            let src = "";
            let iconSrc = "";
            let img;
            for (let i = 0; i < sign.length; i++) {
                switch (sign[i]) {
                    case 1:
                    case 6:
                        src = "img_xx_symbol_1.png";
                        break;
                    case 2:
                    case 7:
                        src = "img_xx_symbol_2.png";
                        break;
                    case 3:
                    case 8:
                        src = "img_xx_symbol_3.png";
                        break;
                    case 4:
                    case 9:
                        src = "img_xx_symbol_4.png";
                        break;
                    case 5:
                        src = "img_xx_symbol_5.png";
                        break;
                }
                iconSrc = mgr.UIAssist.$("ui/bgActivity7/{1}", src);
                img = this._model.getSymbol();
                img.alpha = 1;
                img.scaleX = img.scaleY = 0.5;
                mgr.icon.drawTexture(iconSrc, img);
                this.sprImg.addChild(img);
            }
            this.resetSeat();
        }
        updateSign(sign) {
            let offest = this.sprImg.numChildren - sign.length;
            for (let i = 0; i < offest; i++) {
                this._model.pushSymbol(this.sprImg.getChildAt(0));
                this.sprImg.removeChildAt(0);
            }
            this.resetSeat();
            this.hp = sign.length;
        }
        resetSeat() {
            this.sprImg.width = 30 * this.sprImg.numChildren;
            this.sprImg.x = -this.sprImg.width / 2;
            for (let i = 0; i < this.sprImg.numChildren; i++) {
                this.sprImg.getChildAt(i).x = 30 * i;
            }
        }
        playHit(hitFunc) {
            this.unitHit.play("stand", false);
            this.unitHit.visible = true;
        }
        setRole(isBoss) {
            if (isBoss) {
                this.unitRole.scaleX = 0.6;
                this.unitRole.scaleY = 0.6;
                this.unitRole.y = 80;
            }
            else {
                this.unitRole.scaleX = 0.3;
                this.unitRole.scaleY = 0.3;
                this.unitRole.y = 50;
            }
        }
        setRoleScaleX(scale) {
            this.unitRole.scaleX = scale * Math.abs(this.unitRole.scaleX);
        }
        clear() {
            this.alpha = 0;
        }
        onDisable() {
            super.onDisable();
            this.sprImg.removeChildren();
            this.unitHit.stop();
            this.unitHit.clearRole();
            this._model = null;
        }
    }
    mvc.UnitGhostHuntRole = UnitGhostHuntRole;
})(mvc || (mvc = {}));

