(function (mvc) {
    class PopTbDesk extends ui.view.taobao.pop_tbDeskUI {
        initView(...args) {
            this._model = mvc.tbDeskModel;
            this._ctrl = mvc.tbDeskCtrl;
        }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            this.listReward.array = mvc.ItemVo.createItemVos(this._model.reward);
            if (this._model.checkCanGetReward()) {
                this.btnEnter.disabled = false;
                this.btnEnter.label = sg.translate("领取奖励");
            }
            else {
                let pr = mgr.gplatform.isCollectSdk();
                this.btnEnter.disabled = true;
                this.btnEnter.label = sg.translate("不支持添加");
                if (pr instanceof Promise) {
                    pr.then((res) => {
                        if (res.code == 0) {
                            this.btnEnter.disabled = true;
                            this.btnEnter.label = sg.translate("不支持添加");
                        }
                        else if (res.code == 1) {
                            this.btnEnter.disabled = false;
                            this.btnEnter.label = sg.translate("立即添加");
                        }
                        else if (res.code == 2) {
                            this.btnEnter.disabled = true;
                            this.btnEnter.label = sg.translate("桌面进入");
                        }
                        else {
                            this.btnEnter.disabled = true;
                            this.btnEnter.label = sg.translate("不支持添加");
                        }
                    });
                }
            }
        }
        initCtrlEvent() {
            this.listReward.renderHandler = this.createHandler(this, this._listRenderer, undefined, false);
            this.btnEnter.on(Laya.Event.CLICK, this, this._onBtnEnterClick);
        }
        initModelEvent() {
            this.bindModelEvent(this._model, mvc.TbDeskConst.EVT.GETREWARD, this.onGetReward);
        }
        onGetReward() {
            sg.uimgr.showNotice(sg.translate("设置成功,奖励已发放至邮箱"), "green");
            this.closeSelf();
        }
        _listRenderer(cell, index) {
            let data = cell.dataSource;
            if (!data)
                return;
            cell.initView(data);
        }
        _onBtnEnterClick() {
            if (this._model.checkCanGetReward()) {
                this._ctrl.getReward();
            }
            else {
                mgr.gplatform.collectSdk();
            }
        }
    }
    mvc.PopTbDesk = PopTbDesk;
})(mvc || (mvc = {}));

