var mvc;
(function (mvc) {
    class SwordGasModel extends sg.ModelBase {
        registerEvents() {
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.SWORD_GAS, this.checkRed, this);
        }
        isCheckTask() {
            let vo = mvc.swordModel.getSwordVo();
            let cfgs = sg.dbmgr.getDB("sword_swordTask");
            if (vo && vo.gasTaskInfo) {
                for (let key in cfgs) {
                    let cfg = cfgs[key];
                    let task = null;
                    for (let key2 in vo.gasTaskInfo) {
                        let taskvo = vo.gasTaskInfo[key2];
                        if (taskvo.id == cfg.id) {
                            task = taskvo;
                            break;
                        }
                    }
                    if (!task || cfg.condition[1] > task.progress) {
                        return false;
                    }
                }
                return true;
            }
            else {
                return false;
            }
        }
        isCanUpGrade(stateId, level) {
            let cfg = sg.dbmgr.get("sword_swordGas", stateId);
            let nextCfg = sg.dbmgr.get("sword_swordGas", stateId + 1);
            if (!cfg)
                return false;
            if (level != cfg.level) {
                return false;
            }
            if (nextCfg) {
                if (nextCfg.multiId == cfg.multiId) {
                    return nextCfg.grd > cfg.grd;
                }
            }
            return false;
        }
        isCanUpMultiId(stateId, level) {
            let cfg = sg.dbmgr.get("sword_swordGas", stateId);
            let nextCfg = sg.dbmgr.get("sword_swordGas", stateId + 1);
            if (!cfg)
                return false;
            if (level != cfg.level) {
                return false;
            }
            if (nextCfg && nextCfg.grd >= cfg.grd) {
                return false;
            }
            if (nextCfg) {
                return nextCfg.multiId > cfg.multiId;
            }
            return false;
        }
        isMaxLevel(stateId, level) {
            let cfg = sg.dbmgr.get("sword_swordGas", stateId);
            let nextCfg = sg.dbmgr.get("sword_swordGas", stateId + 1);
            if (!cfg)
                return true;
            if (level < cfg.level) {
                return false;
            }
            if (!nextCfg) {
                return true;
            }
            return false;
        }
        getCurLvProp(stateId, curlv) {
            let prop = {};
            let cfg = sg.dbmgr.get("sword_swordGas", stateId);
            if (!cfg)
                return null;
            for (let key in cfg.levelUpArr) {
                if (!prop[cfg.levelUpArr[key][0]])
                    prop[cfg.levelUpArr[key][0]] = 0;
                prop[cfg.levelUpArr[key][0]] += cfg.levelUpArr[key][1];
            }
            for (let key in cfg.levelUpProp) {
                if (!prop[cfg.levelUpProp[key][0]])
                    prop[cfg.levelUpProp[key][0]] = 0;
                prop[cfg.levelUpProp[key][0]] += cfg.levelUpProp[key][1] * curlv;
            }
            return prop;
        }
        getAddLvProp(stateId, curlv) {
            let prop = null;
            let cfg = sg.dbmgr.get("sword_swordGas", stateId);
            if (curlv == cfg.level) {
                cfg = sg.dbmgr.get("sword_swordGas", stateId + 1);
                if (cfg)
                    prop = this.getCurLvProp(stateId + 1, 0);
                else
                    prop = this.getCurLvProp(stateId, curlv);
            }
            else {
                prop = this.getCurLvProp(stateId, curlv + 1);
            }
            return prop;
        }
        getChangeAddProp(stateId, curlv) {
            let prop = this.getCurLvProp(stateId, curlv);
            let addProp = this.getAddLvProp(stateId, curlv);
            let arr = [];
            for (let key in addProp) {
                arr.push([key, prop[key] ? prop[key] : 0, addProp[key]]);
            }
            let fun = (a, b) => {
                let aCfg = mvc.PropertyModel._getCfg(a[0]);
                let bCfg = mvc.PropertyModel._getCfg(b[0]);
                if (aCfg.show_priority == bCfg.show_priority) {
                    return aCfg.id - bCfg.id;
                }
                return aCfg.show_priority - bCfg.show_priority;
            };
            arr.sort(fun);
            return arr;
        }
        getMulProp(stateId, prop = null) {
            let curCfg = sg.dbmgr.get("sword_swordGas", stateId);
            prop = prop || {};
            for (let key in curCfg.multiArr) {
                if (!prop[curCfg.multiArr[key][0]])
                    prop[curCfg.multiArr[key][0]] = 0;
                prop[curCfg.multiArr[key][0]] += curCfg.multiArr[key][1];
            }
            return prop;
        }
        getStateProp(stateId, prop = null) {
            let curCfg = sg.dbmgr.get("sword_swordGas", stateId);
            prop = prop || {};
            for (let key in curCfg.grdArr) {
                if (!prop[curCfg.grdArr[key][0]])
                    prop[curCfg.grdArr[key][0]] = 0;
                prop[curCfg.grdArr[key][0]] += curCfg.grdArr[key][1];
            }
            return prop;
        }
        getChangeStateAddProp(stateId, isShow = false) {
            let cfg = sg.dbmgr.get("sword_swordGas", stateId);
            let nextcfg = sg.dbmgr.get("sword_swordGas", stateId + 1);
            if (!nextcfg) {
                nextcfg = cfg;
            }
            let prop = {};
            for (let key in cfg.grdArr) {
                if (!prop[cfg.grdArr[key][0]])
                    prop[cfg.grdArr[key][0]] = [];
                prop[cfg.grdArr[key][0]].push(cfg.grdArr[key][1]);
            }
            for (let key in nextcfg.grdArr) {
                if (!prop[nextcfg.grdArr[key][0]])
                    prop[nextcfg.grdArr[key][0]] = [];
                prop[nextcfg.grdArr[key][0]].push(nextcfg.grdArr[key][1]);
            }
            let arr = [];
            let index = 0;
            for (let key in prop) {
                let cfg = mvc.PropertyModel._getCfg(key);
                if (isShow && cfg && cfg.show_priority == 3) {
                    if (index == 0) {
                        arr.push([key, prop[key][0], prop[key][1], true]);
                        index++;
                    }
                }
                else {
                    arr.push([key, prop[key][0], prop[key][1]]);
                }
            }
            return arr;
        }
        getChangeMulAddProp(stateId, isShow = false) {
            let curCfg = sg.dbmgr.get("sword_swordGas", stateId);
            let nextcfg = this.getNextMulCfg(stateId, true);
            if (!nextcfg) {
                nextcfg = curCfg;
            }
            let prop = {};
            for (let key in curCfg.multiArr) {
                if (!prop[curCfg.multiArr[key][0]])
                    prop[curCfg.multiArr[key][0]] = [];
                prop[curCfg.multiArr[key][0]].push(curCfg.multiArr[key][1]);
            }
            for (let key in nextcfg.multiArr) {
                if (!prop[nextcfg.multiArr[key][0]])
                    prop[nextcfg.multiArr[key][0]] = [];
                prop[nextcfg.multiArr[key][0]].push(nextcfg.multiArr[key][1]);
            }
            let arr = [];
            let index = 0;
            for (let key in prop) {
                let cfg = mvc.PropertyModel._getCfg(key);
                if (isShow && cfg && cfg.show_priority == 3) {
                    if (index == 0) {
                        arr.push([key, prop[key][0], prop[key][1], true]);
                        index++;
                    }
                }
                else {
                    arr.push([key, prop[key][0], prop[key][1]]);
                }
            }
            return arr;
        }
        getNextMulCfg(stateId, isMul = false) {
            let curCfg = sg.dbmgr.get("sword_swordGas", stateId);
            let cfg = curCfg;
            let i = 1;
            while (cfg) {
                cfg = sg.dbmgr.get("sword_swordGas", stateId + i);
                if (cfg && curCfg.multiId < cfg.multiId) {
                    if (isMul)
                        return cfg;
                    else
                        return sg.dbmgr.get("sword_swordGas", stateId + i - 1);
                }
                i++;
            }
            return cfg ? cfg : curCfg;
        }
        getDownMulCfg(stateId) {
            let curCfg = sg.dbmgr.get("sword_swordGas", stateId);
            let curId = mvc.swordModel.getSwordVo().gasStateId;
            let cfg = sg.dbmgr.get("sword_swordGas", curId);
            if (!curCfg)
                return cfg;
            for (let i = stateId; i > 0; i--) {
                let scfg = sg.dbmgr.get("sword_swordGas", i);
                if (scfg && curCfg.multiId > scfg.multiId) {
                    if (scfg.multiId == cfg.multiId) {
                        return cfg;
                    }
                    else {
                        return scfg;
                    }
                }
            }
            return cfg;
        }
        checkRed() {
            if (!mgr.conditionMgr.checkFunc(mvc.FUNC_ID.SWORD_GAS, false)) {
                return 0;
            }
            let vo = mvc.swordModel.getSwordVo();
            let num = this.isActiveState();
            if (num == 1)
                return 1;
            if (num == 2) {
                if (this.isMaxLevel(vo.gasStateId, vo.gasLv)) {
                    return 0;
                }
                let curCfg = sg.dbmgr.get("sword_swordGas", vo.gasStateId);
                if (this.isCanUpMultiId(vo.gasStateId, vo.gasLv) || this.isCanUpGrade(vo.gasStateId, vo.gasLv)) {
                    if (mgr.toolsMgr.checkConsume(curCfg.grdConsume, false)) {
                        return 1;
                    }
                }
                else {
                    if (mgr.toolsMgr.checkConsume(curCfg.levelConsume, false)) {
                        return 1;
                    }
                }
            }
            return 0;
        }
        isActiveState() {
            let vo = mvc.swordModel.getSwordVo();
            if (vo.gasStateId > 0)
                return 2;
            if (this.isCheckTask()) {
                return 1;
            }
            else {
                return 0;
            }
        }
    }
    mvc.SwordGasModel = SwordGasModel;
})(mvc || (mvc = {}));

