(function (mvc) {
    class ShareCollectModel extends sg.ModelBase {
        initModel() {
            this._collectState = 0;
            this._addSignState = this._shareState = 0;
        }
        registerEvents() {
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.COLLECT_RED, this.redCollect, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.SHARE, this.redShare, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.ADD_SIGN, this.redAddSign, this);
        }
        set shareState(v) {
            this._shareState = v;
            mgr.redotMgr.check(mvc.REDOT_ID.SHARE);
        }
        get shareState() {
            return this._shareState;
        }
        set addSignState(v) {
            this._addSignState = v;
            if (!this.isAddSignShow()) {
                mvc.activityModel.removeActivityVo(mvc.FUNC_ID.ADD_SIGN, false);
            }
            mgr.redotMgr.check(mvc.REDOT_ID.ADD_SIGN);
        }
        get addSignState() {
            return this._addSignState;
        }
        set collectState(v) {
            this._collectState = v;
            if (!this.isCollectIconShow()) {
                mvc.activityModel.removeActivityVo(mvc.FUNC_ID.COLLECT_VIEW, false);
            }
            mgr.redotMgr.check(mvc.REDOT_ID.COLLECT_RED);
        }
        get collectState() {
            return this._collectState;
        }
        isFristShare() {
            if (!mgr.gplatform.isFristShare()) {
                return false;
            }
            return this.shareState == 0;
        }
        isFristCollect() {
            if (!mgr.gplatform.isFristCollect()) {
                return false;
            }
            return this.collectState == 0;
        }
        getCollectState() {
            if (this.collectState == 0) {
                let cfg = mgr.toolsMgr.getGlobalVoById("tab_Scence", 1);
                return cfg && cfg.indexOf(mgr.gplatform.sdkParams.gameSceneId) != -1 ? 2 : 0;
            }
            return this.collectState;
        }
        getAddSignState() {
            if (this.addSignState == 0) {
                let cfg = mgr.toolsMgr.getGlobalVoById("tab_Scence_Sign", 1);
                return cfg && cfg.indexOf(mgr.gplatform.sdkParams.gameSceneId) != -1 ? 2 : 0;
            }
            return this.addSignState;
        }
        share() {
            mgr.gplatform.shareSdk();
            sg.timer.after(2000, this, () => {
                if (this.shareState == 0) {
                    this.shareState = 2;
                }
                this.fireEvent(mvc.ShareCollectConst.EVT.SHARE_STATE);
            });
        }
        redCollect() {
            if (this.getCollectState() == 2) {
                return 1;
            }
            return 0;
        }
        redShare() {
            if (this.shareState == 2) {
                return 1;
            }
            return 0;
        }
        redAddSign() {
            if (this.getAddSignState() == 2) {
                return 1;
            }
            return 0;
        }
        isShareIconShow() {
            return mgr.gplatform.isFristShare();
        }
        isCollectIconShow() {
            if (mgr.gplatform.isFristCollect()) {
                return this.collectState != 1;
            }
            return false;
        }
        isAddSignShow() {
            if (mgr.gplatform.isAddSignShow()) {
                return this.addSignState != 1;
            }
            return false;
        }
    }
    mvc.ShareCollectModel = ShareCollectModel;
})(mvc || (mvc = {}));

