(function (mvc) {
    class UnitSevenGift extends ui.view.sevenActive.unit_sevenGiftUI {
        initView() {
        }
        initSendMsg() {
        }
        initModelEvent() {
        }
        initCtrlEvent() {
            this.tab.selectHandler = this.createHandler(this, this._updateTab, null, false);
            this.tab.selectedIndex = 0;
            this.listReward.vScrollBarSkin = "";
            this.listReward.renderHandler = this.createHandler(this, this._onListReward, null, false);
            this.listAccu.vScrollBarSkin = "";
            this.listAccu.renderHandler = this.createHandler(this, this._onListReward2, null, false);
            this.redAccu.id = mvc.REDOT_ID.SEVEN_DAY_ACCU_REWARD;
        }
        updateData(types, ...args) {
        }
        _hideAll() {
            this.listReward.visible = false;
            this.listAccu.visible = false;
        }
        _updateTab(index) {
            this._hideAll();
            this._onTimer();
            switch (index) {
                case 0:
                    this.listReward.visible = true;
                    break;
                case 1:
                    this.listAccu.visible = true;
                    break;
            }
        }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            this.updateAll();
            this.updateTime();
            this.updateAllAccu();
        }
        updateAll() {
            if (!this._cfg) {
                let cfg = sg.dbmgr.getDB("sevenActive_sevenGift", true);
                this._cfg = cfg;
            }
            this.giftSort();
            this.listReward.array = this._cfg;
        }
        updateAllAccu() {
            if (!this._cfg2) {
                let cfg = sg.dbmgr.getDB("sevenActive_accuReward", true);
                this._cfg2 = cfg;
            }
            this._taskSort();
            this.listAccu.array = this._cfg2;
        }
        _taskSort() {
            let model = mvc.sevenDaysModel;
            this._cfg2.sort((a, b) => {
                let isFinishA = model.getAccuStateById(a.id);
                let isFinishB = model.getAccuStateById(b.id);
                if (isFinishA && isFinishB) {
                    return a.id - b.id;
                }
                else if (!isFinishA && !isFinishB) {
                    return a.id - b.id;
                }
                return isFinishA ? 1 : -1;
            });
        }
        giftSort() {
            let model = mvc.sevenDaysModel;
            this._cfg.sort((a, b) => {
                let gitNumA = model.getGiftNumById(a.id);
                let gitNumB = model.getGiftNumById(b.id);
                let isFullA = gitNumA >= a.timeLimit;
                let isFullB = gitNumB >= a.timeLimit;
                if ((isFullA && isFullB) || (!isFullA && !isFullB))
                    return a.id - b.id;
                return isFullA ? 1 : -1;
            });
        }
        updateTime() {
            this.repeats(1000, this._onTimer, true);
        }
        _onListReward(cell, idx) {
            let data = cell.dataSource;
            if (!data)
                return;
            cell.initView(data);
        }
        _onListReward2(cell, idx) {
            let data = cell.dataSource;
            if (!data)
                return;
            cell.initView(data);
        }
        _onTimer() {
            if (this.tab.selectedIndex == 0) {
                let last = Math.max(0, mvc.sevenDaysModel.vo.end_time - sg.time.getSecondTime());
                if (last == 0) {
                    this.lblTime.text = sg.translate("活动已结束");
                    this.stopTimer(this._onTimer);
                }
                else
                    this.lblTime.text = sg.time.formatTimeStrT("F10", last);
            }
            else {
                let last = Math.max(0, mvc.sevenDaysModel.accuRewardVo.end_time - sg.time.getSecondTime());
                if (last == 0) {
                    this.lblTime.text = sg.translate("活动已结束");
                    this.stopTimer(this._onTimer);
                }
                else {
                    this.lblTime.text = sg.time.formatTimeStrT("F10", last);
                }
            }
        }
        onDisable() {
            super.onDisable();
        }
    }
    mvc.UnitSevenGift = UnitSevenGift;
})(mvc || (mvc = {}));

