var mvc;
(function (mvc) {
    let EVT = mvc.RuleConst.EVT;
    class PopRule extends ui.view.rule.pop_ruleUI {
        initView(pos = 0) {
            this._model = mvc.ruleModel;
            this._ctrl = mvc.ruleCtrl;
            this._startPos = pos;
            this._lastSelect = [-1, -1];
        }
        initSendMsg() {
        }
        initModelEvent() {
            this.bindModelEvent(this._model, EVT.UPDATE_ALL, this._onTypeSelect);
            this.bindModelEvent(this._model, EVT.UPDATE_POS, this._onTypeSelect);
            this.bindModelEvent(this._model, EVT.UPDATE_LEVEL, this._lvUp);
        }
        initCtrlEvent() {
            this.listResonace.renderHandler = this.createHandler(this, this._listResonanceRender, undefined, false);
            this.tabType.selectHandler = this.createHandler(this, this._onTypeSelect, undefined, false);
            this.list.renderHandler = this.createHandler(this, this._listRenderer, undefined, false);
            this.list.selectHandler = this.createHandler(this, this._listSelected, undefined, false);
            this.btnResonance.on(Laya.Event.CLICK, this, this._onBtnResonance);
            this.btnUse.on(Laya.Event.CLICK, this, this._onBtnUse);
            this.btnLvUp.on(Laya.Event.CLICK, this, this._onBtnLvUp);
            this.unitCurrency.updateData("", [this._model.universalId], true);
        }
        onAwake() {
            super.onAwake();
            this._typeArr = [];
            for (let i = 1; i <= 2; i++) {
                let cfgs = sg.dbmgr.getArray("rule_rule", { battleType: i });
                let arr = [];
                for (let cfg of cfgs) {
                    arr.push({
                        id: cfg.id,
                        lblName: cfg.name,
                        lblType: cfg.typeName,
                        clipQua: cfg.quality - 1,
                        imgIcon: mgr.icon.getIconPath(cfg.icon),
                        itemId: cfg.itemId,
                        maxLv: cfg.maxLv,
                        desc: cfg.desc
                    });
                }
                arr.sort((a, b) => {
                    return b.clipQua - a.clipQua;
                });
                this._typeArr.push(arr);
            }
        }
        onEnable() {
            super.onEnable();
            this._lastSelect = [-1, -1];
            this.tabType.selectedIndex = this._startPos;
            this._updateResonance();
            this._updateLvRed();
        }
        onDisable() {
            this.tabType.selectedIndex = -1;
            super.onDisable();
        }
        _lvUp(isActive) {
            if (isActive) {
                this._playActiveAni();
            }
            else {
                this._playLvUpAni();
            }
            this._onTypeSelect();
            this._updateResonance();
            this._updateLvRed();
        }
        _playLvUpAni() {
            let eff = sg.Effect2D.create("eff_ui_shenjichengong", true, false, true);
            eff.x = 103;
            eff.y = 256;
            eff.scale(2, 2);
            eff.name = "eff_ui_shenjichengong";
            eff.on(Laya.Event.STOPPED, this, this._lvUpAniEnd);
            this.addChild(eff);
        }
        _lvUpAniEnd() {
            this.removeChildByName("eff_ui_shenjichengong");
        }
        _playActiveAni() {
            let eff = sg.Effect2D.create("eff_ui_shenjietiandao", true, false, true);
            eff.x = -99;
            eff.y = 58;
            eff.name = "eff_ui_shenjietiandao";
            eff.on(Laya.Event.STOPPED, this, this._activeAniEnd);
            this.addChild(eff);
        }
        _activeAniEnd() {
            this.removeChildByName("eff_ui_shenjietiandao");
        }
        _updateLvRed() {
            let items = mvc.bagModel.getItemsByType(mvc.BagConst.BagType.Rule);
            for (let pos = 1; pos <= 2; pos++) {
                let isRed = false;
                for (let item of items) {
                    let id = this._model.itemToRule[item.id];
                    let ruleCfg = sg.dbmgr.get("rule_rule", id);
                    if (!ruleCfg || ruleCfg.battleType != pos)
                        continue;
                    let lv = this._model.getRuleLv(id);
                    let lvCfg = sg.dbmgr.getUnique("rule_ruleLvUp", id, lv);
                    if (lvCfg && lvCfg.consume) {
                        if (item.count >= lvCfg.consume[0][1]) {
                            isRed = true;
                            break;
                        }
                    }
                }
                this["redPos" + pos].visible = isRed;
            }
        }
        _updateResonance() {
            let arr = [];
            let infos = this._model.resonaceInfo;
            for (let key in infos) {
                arr.push({
                    max: infos[key].max,
                    cur: this._model.getResonanceLv(Number(key))
                });
            }
            this.listResonace.array = arr;
        }
        _onTypeSelect() {
            let idx = this.tabType.selectedIndex;
            if (idx < 0)
                return;
            this.list.array = this._typeArr[idx];
            if (this._lastSelect[idx] < 0) {
                let id = this._model.posMap.get(idx + 1);
                if (id) {
                    for (let [i, v] of this.list.array.entries()) {
                        if (v.id == id) {
                            this._lastSelect[idx] = i;
                        }
                    }
                }
                else {
                    this._lastSelect[idx] = 0;
                }
            }
            this.list.selectedIndex = this._lastSelect[idx];
        }
        _listRenderer(cell) {
            let data = cell.dataSource;
            if (!data)
                return;
            let imgWear = cell.getChildByName("imgWear");
            imgWear.visible = this._model.isUse(data.id);
            let lblNum = cell.getChildByName("lblNum");
            let lblLv = cell.getChildByName("lblLv");
            let imgMask = cell.getChildByName("imgMask");
            let red = cell.getChildByName("redTips");
            let lv = this._model.getRuleLv(data.id);
            lblLv.text = lv ? "Lv." + lv : "";
            imgMask.visible = lv == 0;
            let cur = mvc.bagModel.getItemNumById(data.itemId);
            if (lv == data.maxLv) {
                lblNum.text = cur + "/0";
                red.visible = false;
            }
            else {
                let lvCfg = sg.dbmgr.getUnique("rule_ruleLvUp", data.id, lv);
                if (!lvCfg) {
                    sg.loge("找不到配置rule_ruleLvUp, id: " + data.id + ", lv: " + lv);
                    return;
                }
                let need = lvCfg.consume[0][1];
                lblNum.text = cur + "/" + need;
                red.visible = cur >= need;
            }
        }
        _listSelected() {
            let data = this.list.selectedItem;
            if (!data)
                return;
            this._lastSelect[this.tabType.selectedIndex] = this.list.selectedIndex;
            let lv = this._model.getRuleLv(data.id);
            this.lblLevel.text = "Lv." + lv;
            let lvCfg = sg.dbmgr.getUnique("rule_ruleLvUp", data.id, lv);
            if (!lvCfg) {
                sg.loge("找不到配置rule_ruleLvUp, id: " + data.id + ", lv: " + lv);
                return;
            }
            this.lblName.text = data.lblName;
            this.lblType.text = data.lblType;
            this.lblDesc.text = data.desc;
            let qua = data.clipQua + 1;
            mgr.icon.drawTexture(`ui/rule/img_wd_pz_lv_${qua}.png`, this.imgQua);
            mgr.toolsMgr.setLabelByQua(qua, this.lblName);
            mgr.icon.drawTexture(data.imgIcon, this.imgIcon);
            if (lvCfg.skillId) {
                let skillCfg = sg.dbmgr.get("skill_skill", lvCfg.skillId);
                this.lblEff.text = skillCfg.desc;
            }
            else {
                let nextLvCfg = sg.dbmgr.getUnique("rule_ruleLvUp", data.id, 1);
                let skillCfg = sg.dbmgr.get("skill_skill", nextLvCfg.skillId);
                this.lblEff.text = skillCfg.desc;
            }
            let isNotActive = lv == 0;
            let isMax = data.maxLv == lv;
            this.btnLvUp.label = isNotActive ? sg.translate("激活") : isMax ? sg.translate("已满级") : sg.translate("升级");
            this.btnLvUp.disabled = lv >= data.maxLv;
            let isUse = this._model.isUse(data.id);
            this.btnUse.label = isUse ? sg.translate("卸下") : sg.translate("运用");
        }
        _listResonanceRender(cell, idx) {
            let data = cell.dataSource;
            if (!data)
                return;
            let imgBg = cell.getChildByName("imgBg");
            let prog = cell.getChildByName("prog");
            let lblProg = cell.getChildByName("lblProg");
            mgr.icon.drawTexture("ui/rule/img_wd_pz0" + (idx + 1) + ".png", imgBg);
            mgr.icon.drawTexture("ui/rule/progress_pz0" + (idx + 1) + ".png", prog);
            prog.value = data.cur / data.max;
            lblProg.text = data.cur;
        }
        _onBtnUse() {
            let data = this.list.selectedItem;
            if (!data)
                return;
            let isUse = this._model.isUse(data.id);
            if (isUse) {
                this._ctrl.reqUnEquip(this.tabType.selectedIndex + 1);
            }
            else {
                let lv = this._model.getRuleLv(data.id);
                if (lv > 0) {
                    let cfg = sg.dbmgr.get("rule_rule", data.id);
                    this._ctrl.reqUse(data.id, cfg.battleType);
                }
            }
        }
        _onBtnLvUp() {
            let data = this.list.selectedItem;
            if (!data)
                return;
            let lv = this._model.getRuleLv(data.id);
            if (lv >= data.maxLv) {
                return;
            }
            let cfg = sg.dbmgr.getUnique("rule_ruleLvUp", data.id, lv);
            let cur = mvc.bagModel.getItemNumById(cfg.consume[0][0]);
            let need = cfg.consume[0][1];
            let func = () => {
                if (lv == 0) {
                    this._ctrl.reqActive(data.id);
                }
                else {
                    this._ctrl.reqLvUp(data.id);
                }
            };
            if (cur >= need) {
                func();
            }
            else {
                let uniNum = mvc.bagModel.getItemNumById(this._model.universalId);
                let needUni = need - cur;
                if (lv > 0 && needUni <= uniNum) {
                    let needName = sg.dbmgr.get("vitem", cfg.consume[0][0]).name;
                    let uniName = sg.dbmgr.get("vitem", this._model.universalId).name;
                    if (!mvc.mainModel.getSacrificeTip(mvc.FirstTipsID.RULE_LV_UP)) {
                        let v1 = needName;
                        let v2 = needUni;
                        let v3 = uniName;
                        sg.uimgr.showConfirm({
                            btnCancelVisible: true,
                            content: StringEx.format(sg.translate("${v1}不足，是否消耗${v2}个${v3}代替升级"), {"v1":v1,"v2":v2,"v3":v3}),
                            sacrificeTipVisible: true,
                            sacrificeTipFunc: () => {
                                mvc.mainModel.showSacrificeTip = mvc.FirstTipsID.RULE_LV_UP;
                            },
                            enterFunc: func
                        });
                    }
                    else {
                        func();
                    }
                }
                else {
                    let str = lv == 0 ? sg.translate("碎片不足无法激活") : sg.translate("碎片不足无法升级");
                    sg.uimgr.showNotice(str);
                }
            }
        }
        _onBtnResonance() {
            sg.uimgr.showUI("pop_ruleResonace");
        }
    }
    mvc.PopRule = PopRule;
})(mvc || (mvc = {}));

