(function (mvc) {
    class PopRuleWorldSkill extends ui.view.rule.pop_worldSkillUI {
        initView() {
            this._model = mvc.ruleModel;
            this._ctrl = mvc.ruleCtrl;
        }
        initSendMsg() {
        }
        initModelEvent() {
            this.bindModelEvent(this._model, mvc.RuleConst.EVT.UPTATE_WORLD_SKILL, this._update);
        }
        initCtrlEvent() {
            for (let i = 0; i < this.boxSkills.numChildren; i++) {
                let unitSkill = this.boxSkills.getChildAt(i);
                unitSkill.on(Laya.Event.CLICK, this, this._onSkillSelect, [unitSkill]);
            }
            this.listGet.renderHandler = this.createHandler(this, this._listGetRender, undefined, false);
            this.btnLvUp.on(Laya.Event.CLICK, this, this._onBtnLvUp);
        }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            let cfgs = sg.dbmgr.getDB("rule_worldHalo", true);
            for (let key in cfgs) {
                let unit = this["unitSkill" + cfgs[key].id];
                if (unit) {
                    unit.dataSource = cfgs[key];
                }
            }
            this._onSkillSelect(this.unitSkill1);
            this.unitCurrency.updateData("", [mvc.MainConst.ITEM_ID.GOLD], true);
        }
        onDisable() {
            if (this._curSelect) {
                this._curSelect.imgSelect.visible = false;
                this._curSelect = null;
            }
            super.onDisable();
        }
        _update(type) {
            for (let i = 0; i < this.boxSkills.numChildren; i++) {
                let unitSkill = this.boxSkills.getChildAt(i);
                unitSkill.dataSource = unitSkill.dataSource;
                if (type == unitSkill.dataSource.id) {
                    unitSkill.playEff();
                }
            }
            this._onSkillSelect(this._curSelect);
        }
        _updateCost() {
            if (!this._curSelect)
                return;
            let data = this._curSelect.dataSource;
            if (!data)
                return;
            let lv = this._model.getWorldSkillLv(data.id);
            let lvCfg = sg.dbmgr.getUnique("rule_worldSkill", data.id, lv);
            this.listGet.array = lvCfg.cost;
        }
        _onSkillSelect(unitItem) {
            if (this._curSelect) {
                this._curSelect.imgSelect.visible = false;
            }
            this._curSelect = unitItem;
            this._curSelect.imgSelect.visible = true;
            let data = unitItem.dataSource;
            if (!data)
                return;
            this.lblName.text = data.haloName;
            let lv = this._model.getWorldSkillLv(data.id);
            this.lblLevel.text = "Lv." + lv;
            let lvCfg = sg.dbmgr.getUnique("rule_worldSkill", data.id, lv);
            if (lvCfg.skillId) {
                let skillCfg = sg.dbmgr.get("skill_skill", lvCfg.skillId);
                this.lblEff.text = skillCfg.desc;
            }
            else {
                this.lblEff.text = sg.translate("未激活");
            }
            this.btnLvUp.label = sg.translate("升级");
            this._updateCost();
            if (!lvCfg.cost) {
                this.btnLvUp.visible = false;
                this.boxNext.visible = false;
                this.lblMax.visible = true;
            }
            else {
                this.lblMax.visible = false;
                this.btnLvUp.visible = true;
                this.boxNext.visible = true;
                this.lblCond.color = mgr.conditionMgr.check(lvCfg.condition, false) ? mvc.COLOR.GREEN : mvc.COLOR.RED;
                let strs = ["", sg.translate("一"), sg.translate("二"), sg.translate("三"), sg.translate("四"), sg.translate("五"), sg.translate("六"), sg.translate("七"), sg.translate("八"), sg.translate("九")];
                let stage = strs[lvCfg.condition[0][1]];
                this.lblCond.text = StringEx.format(sg.translate("创世达到第${stage}阶段后开启"), {"stage":stage});
                this.boxNext.visible = true;
                let nextLvCfg = sg.dbmgr.getUnique("rule_worldSkill", data.id, lv + 1);
                this.lblLvNext.text = "Lv." + nextLvCfg.haloLevel;
                let skillCfg = sg.dbmgr.get("skill_skill", nextLvCfg.skillId);
                this.lblEffNext.text = skillCfg.desc;
            }
        }
        _listGetRender(cell) {
            let data = cell.dataSource;
            if (!data)
                return;
            let imgIcon = cell.getChildByName("imgIcon");
            let lblNum = cell.getChildByName("lblNum");
            let url = mgr.toolsMgr.getIconById(data[0]);
            url = mgr.icon.getIconPath(url);
            mgr.icon.drawTexture(url, imgIcon);
            lblNum.text = data[1].toString();
            let num = mgr.toolsMgr.getCountById(data[0]);
            lblNum.color = num >= data[1] ? mvc.COLOR.GREEN : mvc.COLOR.RED;
        }
        _onBtnLvUp() {
            if (!this._curSelect)
                return;
            let data = this._curSelect.dataSource;
            if (!data)
                return;
            let lv = this._model.getWorldSkillLv(data.id);
            let lvCfg = sg.dbmgr.getUnique("rule_worldSkill", data.id, lv);
            if (mgr.conditionMgr.check(lvCfg.condition, true)) {
                if (mgr.toolsMgr.checkConsume(lvCfg.cost, true)) {
                    mvc.mainModel.consumeJade(lvCfg.cost, 1, () => {
                        this._ctrl.reqSkillLvUp(data.id);
                    });
                }
            }
            else {
                return;
            }
        }
    }
    mvc.PopRuleWorldSkill = PopRuleWorldSkill;
})(mvc || (mvc = {}));

