            this.btnLvUp.on(Laya.Event.CLICK, this, this._onBtnLvUp);
            this.btnBreak.on(Laya.Event.CLICK, this, this._onBtnBreak);
            this.btnUnionHelp.on(Laya.Event.CLICK, this, this._onBtnHelp);
            this.btnLookAd.on(Laya.Event.CLICK, this, this._onBtnLookAd);
            this.btnAcc.on(Laya.Event.CLICK, this, this._onBtnAcc);
            this.btnEvolution.on(Laya.Event.CLICK, this, this._onBtnEvolution);
            this.btnAttr.on(Laya.Event.CLICK, this, this._onBtnAttr);
            this.btnSkill.on(Laya.Event.CLICK, this, this._onBtnSkill);
            this.unitEffLvUp.ani1.on(Laya.Event.COMPLETE, this, this._ruleEffEnd);
