(function (mvc) {
    class TbGiftModel extends sg.ModelBase {
        constructor() {
            super(...arguments);
            this.funOpenId = 278;
            this._isGetReward = true;
        }
        get reward() {
            if (!this._reward) {
                this._reward = mgr.toolsMgr.getGlobalVoById("tb_huifang_reward", 1);
            }
            return this._reward;
        }
        get isGetReward() {
            return this._isGetReward;
        }
        set isGetReward(value) {
            if (!this._isGetReward && value) {
                this.fireEvent(mvc.TbGiftConst.EVT.GETREWARD);
            }
            this._isGetReward = value;
            this.fireEvent(mvc.TbGiftConst.EVT.UPDATE_ADD, this.funOpenId);
        }
        checkCanShowIcon() {
            let isShow = false;
            if (mgr.gplatform.isTaobao()) {
                let obj = mgr.gplatform.getChannelTag();
                if (obj && obj.type === "MINIAPP" && obj.tag === "ceiling") {
                    isShow = true;
                }
            }
            return !this.isGetReward && isShow;
        }
        initModel() {
            this.bindEvent(mvc.mainModel, mvc.MainConst.EVT.ZERO_UPDATE, this.zeroUpdate);
        }
        zeroUpdate() {
            if (this._isGetReward) {
                this.isGetReward = false;
            }
        }
        registerEvents() {
        }
    }
    mvc.TbGiftModel = TbGiftModel;
})(mvc || (mvc = {}));

