(function (mvc) {
    class SlgBDStoreVo extends sg.VoBase {
        constructor() {
            super();
            this._stroreInfo = new Map();
        }
        getFuncId(type) {
            return mvc.activityModel.getFunIdByActType(type);
        }
        getActOpenVo(type) {
            return mvc.activityModel.openActivityVo.get(this.getFuncId(type));
        }
        isActOpen(type) {
            let activity = mvc.activityModel.openActivityVo.get(this.getFuncId(type));
            if (activity && this._stroreInfo.has(type)) {
                return (activity.end_time - sg.time.getSecondTime()) > 0;
            }
            else {
                return false;
            }
        }
        getActOpenTime(type) {
            let activity = mvc.activityModel.openActivityVo.get(this.getFuncId(type));
            if (activity) {
                return activity.start_time;
            }
            return 0;
        }
        updataInfos(data) {
            let buyInfo = new Map();
            let stroreData = { type: data.type, round: data.round, itemId: data.item_id, buyInfo: buyInfo, goods: undefined };
            for (let i = 0; i < data.buy_info.length; i++) {
                let info = data.buy_info[i];
                let vo = buyInfo.get(info[0]);
                if (vo == undefined) {
                    vo = { id: info[0], buyTime: info[1] };
                    buyInfo.set(vo.id, vo);
                }
                else {
                    vo.buyTime = info[1];
                }
            }
            stroreData.buyInfo = buyInfo;
            this._stroreInfo.set(data.type, stroreData);
            this.getGoods(data.type);
        }
        updataInfo(data) {
            if (this._stroreInfo.has(data.type)) {
                let info = this._stroreInfo.get(data.type);
                if (info.buyInfo.has(data.id)) {
                    info.buyInfo.get(data.id).buyTime = data.bought_count;
                }
                else {
                    info.buyInfo.set(data.id, { id: data.id, buyTime: data.bought_count });
                }
            }
        }
        getItemId(type) {
            if (this._stroreInfo.has(type)) {
                return this._stroreInfo.get(type).itemId;
            }
            return 1;
        }
        getGoodBuyNum(type, id) {
            if (this._stroreInfo.has(type)) {
                let info = this._stroreInfo.get(type);
                if (info.buyInfo.has(id)) {
                    return info.buyInfo.get(id).buyTime;
                }
            }
            return 0;
        }
        getGoods(type, tab = 0) {
            if (this._stroreInfo.has(type)) {
                let info = this._stroreInfo.get(type);
                let goods = [];
                let goodConfigs = sg.dbmgr.getDB("slg_lotteryStore");
                let actVo = mvc.activityModel.openActivityVo.get(this.getFuncId(info.type));
                let time = sg.time.getSecondTime();
                let openTime = actVo ? actVo.start_time : time;
                let day = (time - openTime) / 86400 + 1;
                for (let i in goodConfigs) {
                    let config = goodConfigs[i];
                    if (config.type == type && config.round == info.round && day >= config.show && config.tab == tab) {
                        goods.push(config);
                    }
                }
                info.goods = goods;
                this.sortGoods(info.goods);
                return info.goods;
            }
            return [];
        }
        getRedNum(type) {
            if (this.isActOpen(type) == false || mgr.conditionMgr.checkFunc(this.getFuncId(type), false) == false) {
                return 0;
            }
            let goods = this.getGoods(type);
            for (let k in goods) {
                let v = goods[k];
                if (this.getGoodBuyNum(type, v.id) < v.limit && mgr.toolsMgr.checkConsume(v.cost, false, false)) {
                    return 1;
                }
            }
            return 0;
        }
        dailyLimitGoodsGetRedNum(type) {
            if (this.isActOpen(type) == false || mgr.conditionMgr.checkFunc(this.getFuncId(type), false) == false) {
                return 0;
            }
            let goods = this.getGoods(type);
            for (let k in goods) {
                let v = goods[k];
                if (v.cost[0][1] == 0 && this.getGoodBuyNum(type, v.id) < v.dailyLimit) {
                    return 1;
                }
            }
            return 0;
        }
        sortGoods(goods) {
            if (goods == null || goods.length == 0) {
                return;
            }
            goods.sort((a, b) => {
                if (a.sort == b.sort) {
                    return a.id - b.id;
                }
                return a.sort - b.sort;
            });
            return goods;
        }
        getConfigToId(id) {
            return sg.dbmgr.get("slg_lotteryStore", id);
        }
    }
    mvc.SlgBDStoreVo = SlgBDStoreVo;
})(mvc || (mvc = {}));

