(function (mvc) {
    class PopSlgActiveBpLvUpView extends ui.view.slgActivity.pop_activeBpLvUpUI {
        initView(vo, config, maxLv, needConfig) {
            this._vo = vo;
            this._minLv = 1;
            this._currLv = this._vo.level;
            this._config = config;
            this._needConfig = needConfig;
            let maxConfig = this._config[this._config.length - 1];
            this._maxLv = maxLv - this._vo.level;
            this._type = maxConfig.type;
            this._buyLv = 0;
        }
        initModelEvent() {
            this.bindModelEvent(mvc.slgActivityModel, mvc.SlgActivityConst.EVT.SLG_SKY_BOOK_VERTICAL_LEVEL, this.closeSelf);
        }
        initCtrlEvent() {
            this.btnDown.on(Laya.Event.CLICK, this, this._onBtnClick);
            this.btnAdd.on(Laya.Event.CLICK, this, this._onBtnClick);
            this.btnBuy.on(Laya.Event.CLICK, this, this._onBtnClick);
            this.hSlider.changeHandler = this.createHandler(this, this._onSliderChenge, null, false);
            this.listItem.hScrollBarSkin = '';
            this.listItem.renderHandler = this.createHandler(this, this._onListItemRender, null, false);
        }
        onEnable() {
            super.onEnable();
            this.hSlider.min = this._minLv;
            this.hSlider.max = this._maxLv;
            this.lblMaxLv.text = this._maxLv.toString();
            this.lblMinLv.text = this._minLv.toString();
            mgr.icon.drawTexture(mgr.icon.getIconPath(mgr.toolsMgr.getIconById(1)), this.imgIcon);
            this._changeBuyNum(this._buyLv);
            this._updateView();
        }
        _updateView() {
            this._chuangeMoney();
            this._updateLblToLv();
            this._updateReward();
        }
        _changeBuyNum(num) {
            this._buyLv = num;
            this._limitBuyLv();
            this._chuangeMoney();
            this.lblBuyLv.text = this._buyLv.toString();
        }
        _chuangeMoney() {
            let need = this._vo.getBuyLevelExpNeeConsumption(this._buyLv, this._currLv, this._needConfig);
            if (mgr.toolsMgr.checkConsume([[1, need]], false)) {
                this.lblCostNum.color = mgr.toolsMgr.getColor3("green").stringColor;
            }
            else {
                this.lblCostNum.color = mgr.toolsMgr.getColor3("red").stringColor;
            }
            this.lblCostNum.text = need.toString();
        }
        _updateReward() {
            let arr = this._vo.getBuyLevelReward(this._buyLv + this._currLv, this._config);
            this.listItem.array = arr;
            if (arr.length > 5) {
                this.listItem.width = 378;
            }
            else {
                this.listItem.width = arr.length * (68 + this.listItem.spaceX) - this.listItem.spaceX;
            }
        }
        _updateLblToLv() {
            this.lblToLv.text = (this._currLv + this._buyLv).toString();
        }
        _limitBuyLv() {
            if (this._buyLv > this._maxLv) {
                this._buyLv = this._maxLv;
            }
            if (this._buyLv < this._minLv) {
                this._buyLv = this._minLv;
            }
        }
        _onListItemRender(item, index) {
            if (item.dataSource == null) {
                return;
            }
            item.initViewCfg(item.dataSource);
        }
        _onBuy() {
            let need = this._vo.getBuyLevelExpNeeConsumption(this._buyLv, this._currLv, this._needConfig);
            if (mgr.toolsMgr.checkConsume([[1, need]], true)) {
                mvc.mainModel.consumeJade([[1, need]], 1, () => {
                    mvc.slgActivityCtrl.reqSkyBookVerticalLv(this._type, this._buyLv + this._currLv);
                });
            }
        }
        _onSliderChenge(value) {
            this._changeBuyNum(value);
            this._updateView();
        }
        _onBtnClick(evnet) {
            switch (evnet.target) {
                case this.btnDown:
                    this._changeBuyNum(this._buyLv - 1);
                    this._updateView();
                    break;
                case this.btnAdd:
                    this._changeBuyNum(this._buyLv + 1);
                    this._updateView();
                    break;
                case this.btnBuy:
                    this._onBuy();
                    break;
            }
        }
    }
    mvc.PopSlgActiveBpLvUpView = PopSlgActiveBpLvUpView;
})(mvc || (mvc = {}));

