var mvc;
(function (mvc) {
    class PopSlgActivityExchangeStoreView extends ui.view.slgActivity.pop_exchangeStoreUI {
        initView(funId) {
            this._funId = funId;
            this._model = mvc.slgActivityModel;
        }
        initModelEvent() {
            this.bindModelEvent(this._model, mvc.SlgActivityConst.EVT.STORE_UPDATE_INFO, this._updateView);
        }
        initCtrlEvent() {
            this.lsitStore.vScrollBarSkin = "";
            this.lsitStore.itemRender = mvc.UnitSlgActivirtExStoreItem;
            this.lsitStore.renderHandler = this.createHandler(this, this._onRenderList, null, false);
            this.btnBuy.on(Laya.Event.CLICK, this, this._onBuyClick);
        }
        onEnable() {
            super.onEnable();
            this._endTime = 0;
            this._actVo = mvc.activityModel.openActivityVo.get(this._funId);
            if (!this._actVo) {
                return;
            }
            this._endTime = this._actVo.end_time;
            this._type = mvc.activityModel.getActTypeByFunId(this._funId);
            let time = this._endTime - sg.time.getSecondTime();
            if (time < 0)
                time = 0;
            let v1 = sg.time.formatTimeStrT("F9", time);
            this.lblTIme.text = StringEx.format(sg.translate("活动时间：${v1}后结束"), {"v1":v1});
            this._updateView();
            this._initAssets();
            this._updateTime();
        }
        onJumpInit(jumpParams) {
            this._funId = jumpParams.funId;
            this.onEnable();
        }
        _initAssets() {
            if (this._currency == null) {
                this._currency = this.createUnit("unit_currency", mvc.UnitCurrency, [this._model.getSLGStoreData().getItemId(this._type), 1]);
                this.addChild(this._currency);
                this._currency.x = 80;
                this._currency.y = 422;
            }
        }
        _updateView() {
            if (this._goods == null) {
                let data = this._model.getSLGStoreData();
                let goods = data.getGoods(this._type);
                let actVo = mvc.activityModel.openActivityVo.get(data.getFuncId(this._type));
                let time = sg.time.getSecondTime();
                let openTime = actVo ? actVo.start_time : time;
                let day = (time - openTime) / 86400 + 1;
                for (let i = 0; i < goods.length; i++) {
                    let g = goods[i];
                    if (g.showFashion > 0 && day >= g.show) {
                        this._good = goods.slice(i, i + 1)[0];
                        break;
                    }
                }
                this._goods = goods;
            }
            this.lsitStore.array = this._goods;
            if (this._good) {
                mgr.icon.drawTexture(mgr.icon.getIconPath(mgr.toolsMgr.getIconById(this._good.commodity[0][0])), this.imgIcon);
                this.lblPrice.text = this._good.commodity[0][1].toString();
                let buyCount = this._model.getSLGStoreData().getGoodBuyNum(this._type, this._good.id);
                this.lblLimit.text = sg.translate('限购:') + buyCount.toString() + '/' + this._good.limit.toString();
                if (buyCount < this._good.limit) {
                    this.lblLimit.color = mgr.toolsMgr.getColor3("green").stringColor;
                    this.btnBuy.disabled = false;
                    this.btnBuy.label = sg.translate('兑换');
                }
                else {
                    this.lblLimit.color = mgr.toolsMgr.getColor3("red").stringColor;
                    this.btnBuy.disabled = true;
                    this.btnBuy.label = sg.translate('已兑换');
                }
                this._showSkin(this._good.showFashion);
            }
        }
        _showSkin(fashionId) {
            let cfgF = sg.dbmgr.get("fashion_fashion", fashionId);
            if (cfgF) {
                let sex = mvc.roleModel.roleInfo.sex;
                let modelId = cfgF.avatar[sex];
                this.unitRoleSkin.updateView(modelId, 0, 0, 0);
                if (cfgF.voice) {
                    this.unitRoleSkin.playVoice(cfgF.voice[mvc.roleModel.roleInfo.sex]);
                }
            }
        }
        _updateTime() {
            this.repeats(1000, this._onTimer, true);
        }
        _onRenderList(cell, index) {
            if (!cell.dataSource)
                return;
            let itemNum = this._model.getSLGStoreData().getGoodBuyNum(this._type, cell.dataSource.id);
            cell.setData(cell.dataSource, itemNum, this.getRefreshDay(cell.dataSource, sg.time.getSecondTime()));
        }
        _onTimer() {
            let time = this._endTime - sg.time.getSecondTime();
            if (time <= 0) {
                this.stopTimer(this._onTimer);
                time = 0;
            }
            let v1 = sg.time.formatTimeStrT("F9", time);
            this.lblTIme.text = StringEx.format(sg.translate("活动时间：${v1}后结束"), {"v1":v1});
        }
        getRefreshDay(data, time) {
            if (data.refresh == null || !data.refresh.length || time == 0) {
                return 0;
            }
            let day = this._actVo.getOpenDay();
            let resDay = 0;
            for (let i = 0; i < data.refresh.length; i++) {
                let refresh = data.refresh[i];
                if (refresh > day) {
                    resDay = refresh - day;
                    break;
                }
            }
            return resDay;
        }
        _onBuyClick(event) {
            if (!this._good) {
                return;
            }
            let buyLimit = this._good.limit || 0;
            let buyCount = this._model.getSLGStoreData().getGoodBuyNum(this._type, this._good.id);
            if ((buyLimit == 0 || buyCount < buyLimit) && mgr.toolsMgr.checkConsume(this._good.cost, true)) {
                let itemVo = new mvc.BgStoreVo();
                itemVo.id = this._good.id;
                itemVo.max_count = this._good.limit;
                itemVo.bought_count = buyCount;
                itemVo.shop_item = this._good.commodity;
                itemVo.cost_item = this._good.cost;
                sg.uimgr.showUI("pop_StoreBuyTipsCommon", itemVo, this._good.type, mvc.slgActivityCtrl.reqBgStoreBuy.bind(mvc.slgActivityCtrl));
            }
        }
    }
    mvc.PopSlgActivityExchangeStoreView = PopSlgActivityExchangeStoreView;
})(mvc || (mvc = {}));

