(function (mvc) {
    class PopSlgActivityGiftChooseView extends ui.view.slgActivity.pop_giftChooseUI {
        ;
        initView(selectData, config, selectIndex, maxCount) {
            this._selectData = selectData;
            this._config = config;
            this._maxCount = maxCount;
            this._selectIndex = selectIndex;
            this._setSelectData = {};
            this._isAddPostion = selectData && selectData.item_list && selectData.item_list.length > 0;
        }
        initCtrlEvent() {
            this.rewardList.selectEnable = true;
            this.rewardList.hScrollBarSkin = null;
            this.rewardList.vScrollBarSkin = '';
            this.rewardList.renderHandler = this.createHandler(this, this._onRewardListRender, null, false);
            this.rewardList.selectHandler = this.createHandler(this, this._onRewardListSelect, null, false);
            this.btnSure.on(Laya.Event.CLICK, this, this._onButtonClick);
            this.btnCancel.on(Laya.Event.CLICK, this, this._onButtonClick);
        }
        onEnable() {
            super.onEnable();
            this.btnSure.label = this._isAddPostion ? sg.translate('确定') : sg.translate('下一个');
            this._updateView();
        }
        _updateView() {
            this.itemSelect.dataSource = null;
            if (this._selectData && this._selectData.item_list[this._selectIndex]) {
                let itemData = this._selectData.item_list[this._selectIndex];
                this.itemSelect.visible = true;
                this.itemSelect.initViewCfg([itemData.item_id, itemData.item_num]);
                this.itemSelect.dataSource = [itemData.item_id, itemData.item_num];
            }
            else {
                this.itemSelect.visible = false;
            }
            let arr;
            if (this._selectIndex == 0) {
                arr = this._config.rewardOne;
            }
            else if (this._selectIndex == 1) {
                arr = this._config.rewardTwo;
            }
            else if (this._selectIndex == 2) {
                arr = this._config.rewardThree;
            }
            else {
                arr = [];
            }
            this.rewardList.array = arr;
        }
        _setListSize(count) {
            this.rewardList.width = Math.min(258, count * 86 - 10);
        }
        _onRewardListRender(box, index) {
            if (box.dataSource == null) {
                return;
            }
            let select = box.getChildByName('imgSelect');
            let item = box.getChildByName('item');
            item.initViewCfg(box.dataSource, false);
            select.visible = false;
            if (this.itemSelect.dataSource) {
                let data = this.itemSelect.dataSource;
                select.visible = data[0] == box.dataSource[0] && data[1] == box.dataSource[1];
            }
            else {
                if (this._selectData && this._selectData.item_list && this._selectData.item_list[this._selectIndex]) {
                    let itemData = this._selectData.item_list[this._selectIndex];
                    select.visible = itemData.item_id == box.dataSource[0] && itemData.item_num == box.dataSource[1];
                }
            }
        }
        _onRewardListSelect(index) {
            if (this.rewardList.array[index]) {
                this.itemSelect.visible = true;
                this.itemSelect.dataSource = this.rewardList.array[index];
                this.itemSelect.initViewCfg(this.rewardList.array[index]);
            }
            this.rewardList.refresh();
        }
        _onButtonClick(event) {
            switch (event.target) {
                case this.btnSure:
                    if (this._selectData == null && this.itemSelect.dataSource == null) {
                        sg.uimgr.showNotice(sg.translate('请先选择物品'));
                        break;
                    }
                    if (this._selectIndex < this._maxCount) {
                        let data = this.itemSelect.dataSource;
                        this._setSelectData[this._selectIndex] = { pos: this._selectIndex + 1, item_id: data[0], item_num: data[1] };
                    }
                    if (this._selectData && this._selectData.item_list.length > 0) {
                        for (let i = 0; i < this._selectData.item_list.length; i++) {
                            let item = this._selectData.item_list[i];
                            let index = item.pos - 1;
                            if (!this._setSelectData[index]) {
                                this._setSelectData[index] = { pos: item.pos, item_id: item.item_id, item_num: item.item_num };
                            }
                        }
                        mvc.slgActivityCtrl.reqSelectGiftSelect(this._config.type, this._config.id, this._setSelectData);
                        this.closeSelf();
                        break;
                    }
                    this._selectIndex++;
                    this.btnSure.label = this._selectIndex >= (this._maxCount - 1) ? sg.translate('确定') : sg.translate('下一个');
                    if (this._selectIndex >= this._maxCount) {
                        mvc.slgActivityCtrl.reqSelectGiftSelect(this._config.type, this._config.id, this._setSelectData);
                        this.closeSelf();
                    }
                    else {
                        this._updateView();
                    }
                    break;
                case this.btnCancel:
                    this.closeSelf();
                    break;
            }
        }
    }
    mvc.PopSlgActivityGiftChooseView = PopSlgActivityGiftChooseView;
})(mvc || (mvc = {}));

