var mvc;
(function (mvc) {
    class PopStoreBuyTipsCommon extends ui.view.bgActivityCommon.pop_bgBuyTipsUI {
        initView(cfg, type, call) {
            if (!cfg) {
                return;
            }
            this._cfg = cfg;
            this._type = type;
            this._buyCallFunc = call;
            this._totalPrice = 0;
            this._commodityNum = 1;
        }
        initCtrlEvent() {
            this.on(Laya.Event.CLICK, this, this._onBtnClick);
            this.steper.on(Laya.Event.CLICK, this, this._onSteperChange);
        }
        onEnable() {
            super.onEnable();
            this._updateView();
        }
        _updateView() {
            let item = sg.dbmgr.get("vitem", this._cfg.shop_item[0][0]);
            let name = item.name ? item.name : item.show_name;
            this.lblItemName.text = name;
            let itemVo = new mvc.ItemVo();
            itemVo.initData(this._cfg.shop_item[0][0], this._cfg.shop_item[0][1]);
            let iconGoldUrl = mgr.toolsMgr.getIconById(this._cfg.cost_item[0][0]);
            let box = this.boxItem2;
            box.initView(itemVo);
            this.lblItemDesc2.text = item.descEffect;
            mgr.icon.drawTexture(mgr.icon.getIconPath(iconGoldUrl), this.sprTotalPrice);
            this._setCommodityNum(0);
            this.steper.value = 1;
        }
        _onSteperChange() {
            let offseNum = this.steper.value - this._commodityNum;
            this._setCommodityNum(offseNum);
        }
        _onBtnClick(event) {
            let target = event.target;
            switch (target.name) {
                case "btnCancel":
                    this.closeSelf();
                    break;
                case "btnToBuy":
                    this._matchBuyCondition();
                    this.closeSelf();
                    break;
                case "btnReduceTen":
                    this.steper.value = this.steper.value - 10;
                    this._onSteperChange();
                    break;
                case "btnAddTen":
                    this.steper.value = this.steper.value + 10;
                    this._onSteperChange();
                    break;
            }
        }
        _setCommodityNum(num) {
            this._commodityNum += num;
            let selectNum = this._selectMinNum();
            if (this._commodityNum > selectNum) {
                sg.uimgr.showNotice(sg.translate("已达限购上限"));
                this._commodityNum = selectNum;
                this.steper.value = selectNum;
            }
            if (this._commodityNum < 1) {
                sg.uimgr.showNotice(sg.translate("已达限购下限"));
                this._commodityNum = 1;
                this.steper.value = 1;
            }
            this._totalPrice = this._cfg.cost_item[0][1] * this._commodityNum;
            this.lblTotalPrice.text = this._totalPrice + "";
            let haveCount = this._cfg.haveCount == undefined ? mgr.toolsMgr.getCountById(this._cfg.cost_item[0][0]) : this._cfg.haveCount;
            if (this._totalPrice > haveCount) {
                this.lblTotalPrice.color = mvc.COLOR.RED;
            }
            else {
                this.lblTotalPrice.color = mvc.COLOR.GREEN;
            }
        }
        _matchBuyCondition() {
            if (!this._cfg)
                return;
            if (this._selectMinNum() <= 0) {
                sg.uimgr.showTip(sg.translate("没有购买次数啦,购买失败"));
                return;
            }
            if (this._cfg.haveCount == undefined || this._totalPrice > this._cfg.haveCount) {
                if (mgr.toolsMgr.checkConsume([[this._cfg.cost_item[0][0], this._totalPrice]], true)) {
                    mvc.mainModel.consumeJade(this._cfg.cost_item, 1, () => {
                        if (this._buyCallFunc && this._buyCallFunc instanceof Function) {
                            this._buyCallFunc(this._cfg.id, this._type, this._commodityNum);
                        }
                    });
                }
            }
            else {
                mvc.mainModel.consumeJade(this._cfg.cost_item, 1, () => {
                    if (this._buyCallFunc && this._buyCallFunc instanceof Function) {
                        this._buyCallFunc(this._cfg.id, this._type, this._commodityNum);
                    }
                });
            }
        }
        _selectMinNum() {
            if (this._cfg.max_count == 0) {
                return 9999;
            }
            else {
                return this._cfg.max_count - this._cfg.bought_count;
            }
        }
    }
    mvc.PopStoreBuyTipsCommon = PopStoreBuyTipsCommon;
})(mvc || (mvc = {}));

