            this.itemReward.initView(vos[0]);
            let received = this._info.received;
            let isGet = this._vo.day <= received;
            this.alreadyGet.visible = isGet;
            this['_isCanGet'] = (this._info.login_day >= this._vo.day) && !isGet;
