(function (mvc) {
    class UnitSlgActivitydiyGiftItem extends ui.view.slgActivity.unit_diyGiftItemUI {
        onEnable() {
            super.onEnable();
            this.initEvent();
        }
        initEvent() {
            this.rewardList.renderHandler = this.createHandler(this, this._onRewardListRender, null, false);
            this.rewardList.selectHandler = this.createHandler(this, this._onRewardListSelect, null, false);
            this.rewardList.selectEnable = true;
            this.btnBuy.on(Laya.Event.CLICK, this, this._onButtonClick);
        }
        setData(data, selectInfo, buyInfo) {
            if (!data == null) {
                return;
            }
            this._config = data;
            this._selectInfo = selectInfo;
            this._buyInfo = buyInfo;
            let buyCount = 0;
            let limit;
            let limitStr;
            this.lblTitle.text = data.name;
            if (data.limitTime == 0) {
                if (data.dayTime == 0) {
                    buyCount = buyInfo ? buyInfo.time : 0;
                    limit = 0;
                    limitStr = sg.translate("无限购");
                }
                else {
                    buyCount = buyInfo ? buyInfo.dayTime : 0;
                    limit = data.dayTime;
                    limitStr = sg.translate("每日限购");
                }
            }
            else {
                if (data.dayTime > 0) {
                    buyCount = buyInfo ? buyInfo.dayTime : 0;
                    limit = data.dayTime;
                    limitStr = sg.translate("每日限购");
                }
                else {
                    buyCount = buyInfo ? buyInfo.time : 0;
                    limit = data.limitTime;
                    limitStr = sg.translate("限购");
                }
            }
            this.imgIcon.visible = this.lblOldPrice.visible = this.imgLine.visible = false;
            this.btnBuy.label = "";
            this.redotBuy.visible = false;
            if (data.set_id == 0) {
                if (data.money == 0) {
                    this.btnBuy.label = sg.translate("免费");
                    this.redotBuy.visible = buyCount < limit;
                }
                else {
                    this.imgIcon.visible = true;
                    mgr.icon.drawTexture(mgr.icon.getIconPath(mgr.toolsMgr.getIconById(1)), this.imgIcon);
                    this.redotBuy.visible = buyCount < data.limitTime && mgr.toolsMgr.getCountById(1) >= data.money;
                }
            }
            else {
                if (sg.langMgr.getCode() == "cn") {
                    this.lblOldPrice.visible = true;
                    this.imgLine.visible = true;
                }
                let v1 = data.originalPrice;
                this.lblOldPrice.text = StringEx.format(sg.translate("原价${v1}元"), {"v1":v1});
                this.btnBuy.label = mgr.gplatform.showPriceByGearId(data.set_id);
            }
            let str = limit == 0 ? limitStr : (limitStr + (limit - buyCount) + "/" + limit);
            this._canBuy = limit == 0 || limit > buyCount;
            this.lblLimit.text = str;
            this.lblLimit.color = (limit == 0 || limit - buyCount > 0) ? mgr.toolsMgr.getColor2("green") : mgr.toolsMgr.getColor2("red");
            this.btnBuy.disabled = (limit > 0 && limit - buyCount <= 0);
            let reward = [];
            if (data.rewardOne != null) {
                reward.push(data.rewardOne);
            }
            if (data.rewardTwo != null) {
                reward.push(data.rewardTwo);
            }
            if (data.rewardThree != null) {
                reward.push(data.rewardThree);
            }
            this.item0.initViewCfg(data.comReward[0]);
            this.rewardList.array = reward;
        }
        _onRewardListRender(box, index) {
            if (box.dataSource == null) {
                return;
            }
            let imgAdd = box.getChildByName('imgAdd');
            let item = box.getChildByName('item');
            if (this._selectInfo && this._selectInfo.item_list[index]) {
                let itemData = this._selectInfo.item_list[index];
                item.visible = true;
                item.initViewCfg([itemData.item_id, itemData.item_num], !this._canBuy);
            }
            else {
                item.visible = false;
            }
            imgAdd.visible = !item.visible;
        }
        _onRewardListSelect(selectIndex) {
            if (this._config == null || !this._canBuy) {
                return;
            }
            let index = (this._selectInfo && this._selectInfo.item_list.length >= selectIndex && selectIndex < this.rewardList.array.length) ? selectIndex : 0;
            sg.uimgr.showUI("Pop_SlgActivityGiftChooseView", this._selectInfo, this._config, index, this.rewardList.array.length);
        }
        _onButtonClick(event) {
            switch (event.target) {
                case this.btnBuy:
                    let data = this._config;
                    if (data) {
                        if (mvc.slgActivityCtrl.getActIsOpen(data.type) == false) {
                            sg.uimgr.showNotice(sg.translate("活动已结束"));
                            return;
                        }
                        if (this._selectInfo == null) {
                            sg.uimgr.showNotice(sg.translate("请先选择礼包内容"));
                            return;
                        }
                        if (!this._canBuy) {
                            sg.uimgr.showNotice(sg.translate("限购次数不足"));
                            return;
                        }
                        if (data.set_id == 0) {
                            if (data.money == 0 || mgr.toolsMgr.checkConsume([[1, data.money]], true)) {
                                mvc.slgActivityCtrl.reqSelectReciveGiftInfo(data.id, data.type);
                            }
                        }
                        else {
                            mvc.rechargeCtrl.reqRechargeByPhpEx(data.set_id);
                        }
                    }
                    break;
            }
        }
    }
    mvc.UnitSlgActivitydiyGiftItem = UnitSlgActivitydiyGiftItem;
})(mvc || (mvc = {}));

