var mvc;
(function (mvc) {
    class StoreModel extends sg.ModelBase {
        constructor() {
            super(...arguments);
            this.shopState = 0;
        }
        initModel() {
            this.storeItemMap = {};
            this.commodityBuyRecMap = {};
            this._showRefresh = false;
        }
        registerEvents() {
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.STORE_REFRESH, this._checkRed, this);
        }
        _checkRed() {
            if (!mgr.conditionMgr.checkFunc(mvc.FUNC_ID.STORE, false)) {
                return 0;
            }
            let vo = this.storeItemMap[1];
            if (vo && vo.free_count > 0) {
                return 1;
            }
            return this.shopState;
        }
        showShopRed() {
            this.shopState = 0;
        }
        getStoreNameByType(type) {
            let name = "";
            let arr = mgr.toolsMgr.getGlobalVoById("store_type_name", 1);
            if (arr && arr[type - 1]) {
                return arr[type - 1];
            }
            return name;
        }
        setStoreMap(store_id, storeVo) {
            this.storeItemMap[store_id] = storeVo;
        }
        set showRefresh(show) {
            this._showRefresh = show;
        }
        get showRefresh() {
            return this._showRefresh;
        }
        setCommodityBuyRecMap(commodity_id, commodityVo) {
            this.commodityBuyRecMap[commodity_id] = commodityVo;
        }
        updateRandomStoreInfo(commodity_id) {
            for (let key in this.storeItemMap) {
                this.storeItemMap[key].addBuyCount(commodity_id);
            }
            this.fireEvent(mvc.StoreConst.EVT.REFRESH_STORE);
        }
        setStoreInfos(msg) {
            mvc.storeModel.commodityBuyRecMap = {};
            for (let key in msg.rand_list) {
                let storeItem = msg.rand_list[key];
                let vo = new mvc.StoreVo();
                vo.updateData(storeItem);
                this.setStoreMap(storeItem.store_id, vo);
            }
            for (let key in msg.buy_recs) {
                let buy_recs = msg.buy_recs[key];
                let vo = new mvc.CommodityBuyRecVo();
                vo.updateData(buy_recs);
                this.setCommodityBuyRecMap(buy_recs.commodity_id, vo);
            }
            this.fireEvent(mvc.StoreConst.EVT.REFRESH_STORE);
        }
        getStoreCommodity(store_id, isRandom = 0) {
            let commodityList = [];
            if (isRandom) {
                let tempStore = this.storeItemMap[store_id];
                if (tempStore) {
                    for (let i in tempStore.rand_ids) {
                        let commodId = tempStore.rand_ids[i][0];
                        let config = sg.dbmgr.get("shop_commodity", commodId);
                        if (!config) {
                            sg.Logger.openLog && sg.log(`id:${commodId}找不到配表数据`);
                            continue;
                        }
                        ;
                        let isOpen = mgr.conditionMgr.check(config.show, false);
                        if (isOpen)
                            commodityList.push(config);
                    }
                }
            }
            else {
                let arr = sg.dbmgr.getArray("shop_commodity", { shopId: store_id });
                for (let i = 0, len = arr.length; i < len; i++) {
                    let isOpen = mgr.conditionMgr.check(arr[i].show, false);
                    if (isOpen)
                        commodityList.push(arr[i]);
                }
            }
            commodityList = this._sortCommodity(commodityList);
            return commodityList;
        }
        _sortCommodity(list) {
            return list.sort((aCommodity, bCommodity) => {
                if (aCommodity.sort == bCommodity.sort) {
                    return aCommodity.id - bCommodity.id;
                }
                return bCommodity.sort - aCommodity.sort;
            });
        }
        getStoreCommodityCfg(commodity_id) {
            let config = sg.dbmgr.get("shop_commodity", commodity_id);
            return config;
        }
        getCommodityRecById(commodityId) {
            return this.commodityBuyRecMap[commodityId];
        }
        refreshStore() {
            this.fireEvent(mvc.StoreConst.EVT.REFRESH_RANDOM_STORE);
        }
        refreshCommodity() {
            this.fireEvent(mvc.StoreConst.EVT.REFRESH_COMMODITY);
        }
        showGetReward(id, num) {
            let cfg = this.getStoreCommodityCfg(id);
            if (cfg && cfg.shopId != 5)
                sg.uimgr.showUI("pop_getReward", sg.translate("购买成功"), [[cfg.itemID, (cfg.number * num)]]);
        }
        getStoreItemMapById(shopId) {
            return this.storeItemMap[shopId];
        }
        editFreeCount(shopId) {
            this.storeItemMap[shopId].free_count += 1;
        }
        editSurTime(shopId, time) {
            this.storeItemMap[shopId].sur_time = sg.time.getNextTime(time);
        }
    }
    mvc.StoreModel = StoreModel;
})(mvc || (mvc = {}));

