(function (mvc) {
    class SwordVo extends sg.VoBase {
        constructor() {
            super(...arguments);
            this.grade = 0;
            this.swords = [];
        }
        updateData(info) {
            if (!info)
                return;
            this.level = info.level;
            this.grade = info.grade;
            this.process = info.process;
            this.equip = info.equip;
            this.swords = info.swords;
            this.attr = info.attr;
            this.swordAttachInfoMap = new Map();
            let cfg = sg.dbmgr.getDB("sword_attachType", true);
            for (let i = 0, len = cfg.length; i < len; i++) {
                let attachInfo = new Proto.sword_attach_info_p();
                attachInfo.type = cfg[i].id;
                attachInfo.grade = 0;
                attachInfo.level = 0;
                this.swordAttachInfoMap.set(attachInfo.type, attachInfo);
            }
            for (let i = 0; i < info.sword_attach_infos.length; i++) {
                let attachInfo = info.sword_attach_infos[i];
                if (this.swordAttachInfoMap.get(attachInfo.type)) {
                    this.swordAttachInfoMap.set(attachInfo.type, attachInfo);
                }
            }
            this.gasTaskInfo = info.qi_tasks;
            this.gasLv = info.qi_level;
            this.gasStateId = info.qi_stage;
            this.gasExp = info.qi_exp;
            this.lossTimes = info.qi_stage_up_fail_cnt;
        }
        getGasTaskById(id) {
            for (let v of this.gasTaskInfo) {
                if (v.id == id) {
                    return v;
                }
            }
            return null;
        }
        getShowAttr(defaultArr = null) {
            let prop = this.gasStateId > 0 ? this.getGasSwordAttr() : {};
            if (defaultArr) {
                for (let i = 0; i < defaultArr.length; i++) {
                    let cfg = sg.dbmgr.get("attribute", defaultArr[i][0]);
                    if (!prop[cfg.name])
                        prop[cfg.name] = 0;
                }
            }
            for (let v of this.attr) {
                let cfg = sg.dbmgr.get("attribute", v[0]);
                if (!prop[cfg.name])
                    prop[cfg.name] = 0;
                prop[cfg.name] += v[1];
            }
            let arr = [];
            for (let key in prop) {
                let cfg = mvc.PropertyModel._getCfg(key);
                arr.push([cfg.id, prop[key]]);
            }
            return arr;
        }
        getGasSwordAttr() {
            let prop = mvc.swordGasModel.getCurLvProp(this.gasStateId, this.gasLv);
            prop = mvc.swordGasModel.getMulProp(this.gasStateId, prop);
            prop = mvc.swordGasModel.getStateProp(this.gasStateId, prop);
            return prop;
        }
    }
    mvc.SwordVo = SwordVo;
})(mvc || (mvc = {}));

var mvc;
(function (mvc) {
    class SwordModel extends sg.ModelBase {
        constructor() {
            super(...arguments);
            this.newSwordIds = [];
        }
        set selectAttach(index) {
            this._selectAttach = index;
            sg.varmgr.setSysVar("select_attach_index", this.selectAttach);
        }
        get selectAttach() {
            return this._selectAttach;
        }
        initModel() {
            let selectAttach = sg.varmgr.getSysVar("select_attach_index");
            if (!selectAttach) {
                this._selectAttach = 1;
                sg.varmgr.setSysVar("select_attach_index", this._selectAttach);
            }
            else {
                this._selectAttach = selectAttach;
            }
        }
        registerEvents() {
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.SWORD_GRADE_UP, this.redTipsGradeUp, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.SWORD_LEVEL_UP, this.redTipsLevelUp, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.SWORD_NEW, this.redTipsSwordNew, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.SWORD_ATTACH_TAB, this.redTipsAttachTab, this);
        }
        setSwordInfo(info) {
            if (!this._vo) {
                this._vo = new mvc.SwordVo();
            }
            this._vo.updateData(info);
            this.fireEvent(mvc.SwordConst.EVT.UPDATE_INFO);
            mgr.redotMgr.check(mvc.REDOT_ID.SWORD_GRADE_UP);
            mgr.redotMgr.check(mvc.REDOT_ID.SWORD_LEVEL_UP);
            mgr.redotMgr.check(mvc.REDOT_ID.SWORD_ATTACH_TAB);
            mgr.redotMgr.check(mvc.REDOT_ID.SWORD_GAS);
        }
        getSwordVo() {
            return this._vo;
        }
        addSword(id) {
            if (this._vo) {
                this._vo.swords.push(id);
                this.fireEvent(mvc.SwordConst.EVT.UPDATE_INFO);
                sg.uimgr.showNotice(sg.translate("购买成功"), "green");
            }
        }
        equipSword(id, attr) {
            if (this._vo) {
                this._vo.equip = id;
                this._vo.attr = attr;
                this.fireEvent(mvc.SwordConst.EVT.UPDATE_INFO);
                sg.uimgr.showNotice(sg.translate("更换成功"), "green");
            }
        }
        swordUp(level, process, attr) {
            if (this._vo) {
                let lastLv = this._vo.level;
                let lastExp = this._vo.process;
                let exp = 0;
                if (process - lastExp > 0)
                    exp = process - lastExp;
                else {
                    let cfg = sg.dbmgr.getArray("sword_swordLv", { level: lastLv, grade: this._vo.grade })[0];
                    if (cfg)
                        exp = cfg.exp - lastExp;
                }
                this.fireEvent(mvc.SwordConst.EVT.UPDATE_EXP, exp);
                if (lastLv < level) {
                    this.fireEvent(mvc.SwordConst.EVT.LEVEL_UP);
                }
                this._vo.level = level;
                this._vo.process = process;
                this._vo.attr = attr;
                this.fireEvent(mvc.SwordConst.EVT.UPDATE_INFO);
            }
        }
        swordGradeUp(grade, attr) {
            if (this._vo) {
                this._vo.grade = grade;
                this._vo.attr = attr;
                this._vo.level = 0;
                sg.uimgr.showUI("pop_swordGradeProp", true);
                this.fireEvent(mvc.SwordConst.EVT.GRADE_UP);
            }
        }
        swordAttachUp(data) {
            if (this._vo) {
                if (data.is_success == 0) {
                    sg.uimgr.showNotice(StringEx.format(sg.translate("附灵失败")));
                }
                else {
                    sg.uimgr.showNotice(StringEx.format(sg.translate("附灵成功")), "green");
                }
                this._vo.attr = data.attr;
                this._vo.swordAttachInfoMap.get(data.type).level = data.level;
                this._vo.swordAttachInfoMap.get(data.type).grade = data.grade;
                this.fireEvent(mvc.SwordConst.EVT.ATTACH_AUTO);
                this.fireEvent(mvc.SwordConst.EVT.UPDATE_INFO);
            }
            mgr.redotMgr.check(mvc.REDOT_ID.SWORD_ATTACH_TAB);
            this.fireEvent(mvc.SwordConst.EVT.ATTACH_LEVEL_UP, [data.type, data.is_success]);
        }
        swordAttachGrade(data) {
            if (this._vo) {
                this._vo.attr = data.attr;
                this._vo.swordAttachInfoMap.get(data.type).level = data.level;
                this._vo.swordAttachInfoMap.get(data.type).grade = data.grade;
                this.fireEvent(mvc.SwordConst.EVT.ATTACH_GRADE_UP);
                this.fireEvent(mvc.SwordConst.EVT.UPDATE_INFO);
                mgr.redotMgr.check(mvc.REDOT_ID.SWORD_ATTACH_TAB);
            }
        }
        getNeedLvToGrade() {
            let lv = 0;
            if (this._vo) {
                let cfgs = sg.dbmgr.getArray("sword_swordLv", { grade: this._vo.grade });
                cfgs.sort(function (a, b) {
                    return a.level - b.level;
                });
                let cfg = cfgs[cfgs.length - 1];
                if (cfg) {
                    lv = cfg.level - this._vo.level;
                }
            }
            return lv;
        }
        getSwordModelId(swordId) {
            let swordCfg = sg.dbmgr.get("sword_sword", swordId);
            let modelId = 0;
            if (!swordCfg) {
                modelId = 1001;
            }
            else {
                modelId = swordCfg.model;
            }
            return modelId;
        }
        redTipsGradeUp() {
            if (!mgr.conditionMgr.checkFunc(mvc.FUNC_ID.SWORD, false))
                return 0;
            if (this._vo) {
                let cfg = sg.dbmgr.getArray("sword_swordGrd", { grade: this._vo.grade })[0];
                let cfgNex = sg.dbmgr.getArray("sword_swordGrd", { grade: this._vo.grade + 1 })[0];
                let cfgLv = sg.dbmgr.getArray("sword_swordLv", { level: this._vo.level, grade: this._vo.grade })[0];
                if (cfgNex && cfg && cfgLv && cfgLv.break == 1 && mgr.toolsMgr.checkConsume(cfg.consume, false))
                    return 1;
            }
            return 0;
        }
        redTipsLevelUp() {
            if (!mgr.conditionMgr.checkFunc(mvc.FUNC_ID.SWORD, false))
                return 0;
            if (this._vo) {
                let cfg = sg.dbmgr.getArray("sword_swordLv", { level: this._vo.level, grade: this._vo.grade })[0];
                let cfgNex = sg.dbmgr.get("sword_swordLv", cfg.id + 1);
                if (cfgNex && cfg && cfg.break != 1 && mgr.toolsMgr.checkConsume(cfg.consume, false))
                    return 1;
            }
            return 0;
        }
        redTipsAttachTab() {
            if (!mgr.conditionMgr.checkFunc(mvc.FUNC_ID.SWORD_ATTACH, false))
                return 0;
            if (this._vo) {
                let canLvUp = false;
                let cfg = sg.dbmgr.getDB("sword_attachType", true);
                for (let i = 0; i < cfg.length; i++) {
                    let attachInfo = this._vo.swordAttachInfoMap.get(cfg[i].id);
                    let attachCfg = sg.dbmgr.getArray("sword_swordAttach", { type: attachInfo.type, level: attachInfo.level, grade: attachInfo.grade })[0];
                    if (attachCfg) {
                        let attachCfgNex = attachCfg.next;
                        if (attachCfgNex && mgr.toolsMgr.checkConsume(attachCfg.consume, false)) {
                            canLvUp = true;
                            break;
                        }
                    }
                }
                return canLvUp ? 1 : 0;
            }
            return 0;
        }
        redTipsSwordNew() {
            if (!mgr.conditionMgr.checkFunc(mvc.FUNC_ID.SWORD, false))
                return 0;
            let num = this.newSwordIds.length > 0 ? 1 : 0;
            return num;
        }
    }
    mvc.SwordModel = SwordModel;
})(mvc || (mvc = {}));

