var mvc;
(function (mvc) {
    class PopSwordChange extends ui.view.sword.pop_swordChangeUI {
        initView() {
            this._idx = 0;
        }
        initSendMsg() {
        }
        initModelEvent() {
            this.bindModelEvent(mvc.swordModel, mvc.SwordConst.EVT.UPDATE_INFO, this._updateView);
            this.bindModelEvent(mvc.swordGasModel, mvc.SwordGasConst.EVT.SWORD_DEC, this.updateBtnDec);
        }
        initCtrlEvent() {
            this.listProp.renderHandler = this.createHandler(this, this._onRenderListProp, null, false);
            this.listSword.selectEnable = true;
            this.listSword.selectHandler = this.createHandler(this, this._onSelectListSword, null, false);
            this.listSword.renderHandler = this.createHandler(this, this._onRenderListSword, null, false);
            this.listSword.vScrollBarSkin = "";
            this.btnBuy.on(Laya.Event.CLICK, this, this._onBtnBuy);
            this.btnChange.on(Laya.Event.CLICK, this, this._onBtnChange);
            this.btnDec.on(Laya.Event.CLICK, this, this._onBtnDec);
        }
        updateData(types, ...args) { }
        onAwake() {
            super.onAwake();
            this.lblNotProp.text = sg.translate("无特殊属性加成");
        }
        onEnable() {
            super.onEnable();
            this._updateView();
            this.getIndex();
            this.listSword.selectedIndex = this._idx;
        }
        onDisable() {
            super.onDisable();
        }
        _updateView() {
            let cfgs = sg.dbmgr.getDB("sword_sword", true);
            let arr = [];
            for (let sword of cfgs) {
                let time = new Date(sword.timeShow).getTime();
                let passTime = sg.time.getTime() - time >= 0;
                if (passTime)
                    arr.push(sword);
            }
            this.listSword.array = arr;
            let cfg = this.listSword.array[this.listSword.selectedIndex];
            if (cfg) {
                this._showSwordInfo(cfg);
            }
        }
        getIndex() {
            let vo = mvc.swordModel.getSwordVo();
            for (let index = 0; index < this.listSword.array.length; index++) {
                if (this.listSword.array[index].swordId == vo.equip) {
                    this._idx = index;
                    break;
                }
            }
        }
        _showSwordInfo(cfg) {
            let vo = mvc.swordModel.getSwordVo();
            if (cfg && vo) {
                this._cfg = cfg;
                this.lblName.text = cfg.name;
                this.lblName.color = mgr.toolsMgr.getColor(this._cfg.quality);
                this.lblName.strokeColor = mgr.toolsMgr.getStrokeColor(this._cfg.quality);
                this.swordModel.changeShowMode(false, cfg.model);
                this.swordModel.loadedHandle = () => {
                    this.swordModel.play("stand", true);
                };
                this.swordModel.loadRole(this._cfg.model, "PopSwordChange");
                let prop = mvc.PropertyModel.prasePropByCfg(cfg.secProp);
                this.listProp.array = prop;
                this.lblNotProp.visible = (!prop || prop.length == 0);
                this.boxDec.visible = false;
                let arr = vo.swords;
                if (arr.indexOf(cfg.swordId) == -1) {
                    this.boxBuy.visible = true;
                    this.btnChange.visible = false;
                    this._cost = cfg.price;
                    this.lblCostNum.text = "" + this._cost[0][1];
                    let color = "";
                    if (mgr.toolsMgr.checkConsume(this._cost, false)) {
                        color = mvc.COLOR.GREEN;
                    }
                    else {
                        color = mvc.COLOR.RED;
                    }
                    this.lblCostNum.color = color;
                    let url = mgr.toolsMgr.getIconById(this._cost[0][0]);
                    mgr.icon.drawTexture(mgr.icon.getIconPath(url), this.sprCostIcon);
                }
                else {
                    this.boxBuy.visible = false;
                    this.btnChange.visible = vo.equip != cfg.swordId;
                    this.updateBtnDec();
                }
            }
        }
        updateBtnDec() {
            let cfg = this.listSword.array[this.listSword.selectedIndex];
            if (cfg) {
                if (cfg.price) {
                    let itemCfg = sg.dbmgr.get("vitem", cfg.price[0][0]);
                    if (itemCfg && itemCfg.decompose) {
                        let num = mvc.bagModel.getItemNumById(cfg.price[0][0]);
                        this.boxDec.visible = num > 0;
                        this.redDec.visible = num > 0;
                        this.lblDecNum.text = num.toString();
                    }
                }
            }
            this.listSword.refresh();
        }
        _onRenderListProp(cell, index) {
            let propVo = cell.dataSource;
            let lblPropName = cell.getChildByName("lblPropName");
            let lblPropCurValue = cell.getChildByName("lblPropCurValue");
            let lblAddNum = cell.getChildByName("lblAddNum");
            if (lblPropName) {
                let c = propVo.getCfg();
                lblPropName.text = c && c.show_name;
            }
            if (lblPropCurValue)
                lblPropCurValue.text = propVo.showValue(1) + "";
            let cfg = this.listSword.array[this.listSword.selectedIndex];
            if (lblAddNum && cfg) {
                let addNum = "";
                let props = mvc.PropertyModel.prasePropByCfg(cfg.grdArr);
                for (let key in props) {
                    if (props[key].nameStr == propVo.nameStr) {
                        addNum = props[key].showValue(1);
                        break;
                    }
                }
                lblAddNum.text = addNum;
            }
        }
        _onSelectListSword(index) {
            let cfg = this.listSword.array[index];
            if (cfg) {
                this._showSwordInfo(cfg);
                let arr = mvc.swordModel.newSwordIds;
                let id = cfg.price && cfg.price[0][0];
                if (id && arr.indexOf(id) != -1) {
                    arr.splice(arr.indexOf(id), 1);
                    mgr.redotMgr.check(mvc.REDOT_ID.SWORD_NEW);
                }
            }
        }
        _onRenderListSword(cell, index) {
            let item = cell.getChildByName("item");
            let equiped = cell.getChildByName("equiped");
            let cfg = sg.dbmgr.getArray("sword_swordItem", { swordId: cell.dataSource.swordId })[0];
            let red = cell.getChildByName("redTips");
            if (cfg && item) {
                let id = cfg.id;
                let itemVo = new mvc.ItemVo();
                itemVo.initData(id, 1);
                item.initView(itemVo, false);
                item.setSelect(this.listSword.selectedIndex == index);
                item.setIcon(cell.dataSource.res);
            }
            if (equiped) {
                let vo = mvc.swordModel.getSwordVo();
                equiped.visible = vo.equip == cell.dataSource.swordId;
            }
            if (red && cfg) {
                let id = cfg.id;
                red.visible = mvc.swordModel.newSwordIds.indexOf(id) != -1 || mvc.bagModel.getItemNumById(id) > 0;
            }
        }
        _onBtnBuy() {
            if (this._cfg && this._cost && mgr.toolsMgr.checkConsume(this._cost, true)) {
                mvc.mainModel.consumeJade(this._cost, 1, () => {
                    mvc.swordCtrl.reqSwordBuy(this._cfg.swordId);
                });
            }
        }
        _onBtnChange() {
            if (this._cfg) {
                mvc.swordCtrl.reqSwordEquip(this._cfg.swordId);
                this.closeSelf();
            }
        }
        _onBtnDec() {
            sg.uimgr.showUI("pop_swordDecompose", this._cfg.swordId);
        }
    }
    mvc.PopSwordChange = PopSwordChange;
})(mvc || (mvc = {}));

