(function (mvc) {
    class SpringCollectVo extends sg.VoBase {
        initPhpInfo(data) {
            this.collectList = data.fu_list;
            this.specNeedNum = data.special_need_num;
            this.specItemId = data.special_item_id;
            this.lotteryList = data.lottery;
            this.lotteryCost = data.lottery_cost;
            this.shopList = data.shop;
            this.daySellMax = data.day_sell;
            this.dayBuyMax = data.day_buy;
        }
        initInfo(data) {
            this.lotteryGetList = data.lottery;
            this.buyInfos = data.buy_infos;
            this.dayBuy = data.day_buy;
            this.daySell = data.day_sell;
            this.sellItemId = data.sell_item_id;
            this.wantItemId = data.want_item_id;
        }
        getLotteryNum() {
            let num = 0;
            for (let id of this.collectList) {
                if (mgr.toolsMgr.getCountById(id) > 0)
                    num++;
            }
            return num;
        }
        getItemList() {
            let list = [];
            let itemList = mvc.bagModel.getItemsByType(mvc.BagConst.BagType.SPRING_COLLECT);
            for (let item of itemList) {
                if (item.count > 1) {
                    for (let i = 0; i < item.count - 1; i++) {
                        list.push(mvc.ItemVo.createItemVo([[item.id, 1]]));
                    }
                }
            }
            return list;
        }
        getItemCollection() {
            let list = [];
            let itemList = mvc.bagModel.getItemsByType(mvc.BagConst.BagType.SPRING_COLLECT);
            for (let item of itemList) {
                if (item.count > 1) {
                    list.push(mvc.ItemVo.createItemVo([[item.id, item.count]]));
                }
            }
            return list;
        }
        getRewardIsGet(info) {
            for (let lottery of this.lotteryGetList) {
                if (info[0] == lottery[0] && info[1] == lottery[1] && info[2] == lottery[2])
                    return true;
            }
            return false;
        }
        getRewardCount(id) {
            for (let info of this.buyInfos) {
                if (info[0] == id)
                    return info[1];
            }
            return 0;
        }
        delTrade(playerId) {
            if (!this.tradeList)
                return;
            for (let i = 0; i < this.tradeList.length; i++) {
                let info = this.tradeList[i];
                if (info.player_id == playerId) {
                    this.tradeList.splice(i, 1);
                    break;
                }
            }
        }
    }
    mvc.SpringCollectVo = SpringCollectVo;
})(mvc || (mvc = {}));

