(function (mvc) {
    class SpringMonsterVo extends sg.VoBase {
        initPhpInfo(data) {
            this.one_item = data.one_item;
            this.ten_item = data.ten_item;
            this.item_id = data.item_id;
            this.free_item = data.free_item;
            this.stage = data.stage;
            this.targetAdd = data.stage_target_add;
        }
        initInfo(data) {
            this.free_count = data.free_count;
            this.total_point = data.total_point;
            this.reward_stage = data.reward_stage;
        }
        isGetStageRwd(target) {
            if (!this.reward_stage)
                return false;
            return this.reward_stage.indexOf(target) != -1;
        }
        getStageNum() {
            let maxNum = this.stage[this.stage.length - 1][2];
            let maxStage = Math.floor(this.total_point / maxNum);
            let stage = 0;
            stageFor: for (let i = 0; i < maxStage; i++) {
                for (let info of this.stage) {
                    let target = info[2] + stage * this.targetAdd;
                    if (!this.isGetStageRwd(target)) {
                        break stageFor;
                    }
                }
                stage++;
            }
            return stage;
        }
        getStageAdd() {
            return this.getStageNum() * this.targetAdd;
        }
    }
    mvc.SpringMonsterVo = SpringMonsterVo;
})(mvc || (mvc = {}));

