            this.collectVo.buyInfos = data.buy_infos;
            this.fireEvent(EVT.UPDATE_COLLECT_VIEW);
            this.fireEvent(EVT.UPDATE_COLLECT_REWARD_VIEW);
            mgr.redotMgr.check(mvc.REDOT_ID.BG_ACT_SPRING_COLLECT_LOTTERY);
            mgr.redotMgr.check(mvc.REDOT_ID.BG_ACT_SPRING_COLLECT_REWARD);
