            let listReward = cell.getChildByName("listReward");
            let lblNum = cell.getChildByName("lblNum");
            let btnGet = cell.getChildByName("btnGet");
            let redot = btnGet.getChildByName("redot");
            listWord.hScrollBarSkin = "";
            listWord.renderHandler = this.createHandler(this, this._renderItem, null, false);
