(function (mvc) {
    class PopSpringMonster extends ui.view.slgActivity2.pop_cjMonsterUI {
        initView(...args) {
        }
        initModelEvent() {
            this.bindModelEvent(mvc.springModel, mvc.SpringConst.EVT.UPDATE_MONSTER_VIEW, this._updateView);
            this.bindModelEvent(mvc.springModel, mvc.SpringConst.EVT.PLAY_MONSTER_ANI, this._playAni);
            this.bindModelEvent(mvc.springModel, mvc.SpringConst.EVT.UPDATE_MONSTER_NOTICE, this._playNotice);
        }
        initSendMsg() {
            mvc.springCtrl.reqMonsterInfo();
            mvc.springCtrl.reqMonsterNoticeInfo();
        }
        initCtrlEvent() {
            this.on(Laya.Event.CLICK, this, this._onClick);
            this.listReward.renderHandler = this.createHandler(this, this._renderReward, null, false);
        }
        onEnable() {
            super.onEnable();
            this._unitBarrage = mvc.UnitBarrage.getIns(this.boxLogMove, "PopSpringMonster");
            this._isPlay = false;
            this._initModel();
            this.repeats(1000, this._onTime, true);
        }
        onDisable() {
            super.onDisable();
            this.stopTimer(this._onTime);
            if (this._unitBarrage) {
                this._unitBarrage.stopAni();
            }
        }
        _updateView() {
            this._vo = mvc.springModel.monsterVo;
            if (!this._vo)
                return;
            mgr.icon.drawTexture(mgr.icon.getIconPath(mgr.toolsMgr.getIconById(this._vo.item_id)), this.imgIcon);
            this.lblItemNum.text = mgr.toolsMgr.getCountById(this._vo.item_id) + "";
            this._updateBtn();
            this._updateReward();
        }
        _initModel() {
            this.unitModel.setEndHandle(null, (isLoop, name) => {
                if (name == "hit") {
                    this.unitModel.play("stand", true);
                }
            });
            this.unitModel.loadedHandle = () => {
                this.unitModel.play("stand", true);
            };
            this.unitModel.loadRole(9135, "PopSpringMonster");
            this.unitHitModel.setEndHandle(null, (isLoop, name) => {
                this.unitHitModel.visible = false;
                this._showReward();
            });
            this.unitHitModel.loadRole(10138, "PopSpringMonster", false);
            this.unitHitModel.visible = false;
        }
        _playNotice() {
            this._initPopBarrage(mvc.springModel.monsterVo.notice_infos);
        }
        _initPopBarrage(loglist) {
            if (this._unitBarrage) {
                this._unitBarrage.setParams(loglist, "PopSpringMonster", this.parmaDataInfo.bind(this), 1500, 8000, 1, 20);
                this._unitBarrage.starAni();
            }
        }
        parmaDataInfo(data) {
            let str = "";
            let v1 = `[S${data.svr_id}]`;
            let cfg = sg.dbmgr.get("backgroundActive_cjMonsterMsg", data.notice_id);
            if (cfg)
                str = mvc.mainModel.analyzeNotic(cfg.Msg, [[`${v1}${data.player_name}`], [data.point]]);
            return str;
        }
        _updateBtn() {
            this.redTipsOne.visible = false;
            this._cost1 = [[this._vo.item_id, this._vo.one_item]];
            this.redTipsOne.visible = mgr.toolsMgr.checkConsume(this._cost1);
            this.btnLotterOne.label = sg.translate("投掷鞭炮");
            if (this._vo.free_item - this._vo.free_count > 0) {
                this.btnLotterOne.label = sg.translate("免费投掷");
                this.redTipsOne.visible = true;
            }
        }
        _updateReward() {
            this.lblAllIntergral.value = this._vo.total_point.toString();
            this.listReward.array = this._vo.stage;
        }
        onLottery(num) {
            if (this._isPlay)
                return;
            mvc.springCtrl.reqMonsterFight(num);
        }
        _playAni(reward) {
            this._isPlay = true;
            this._curReward = reward;
            this.unitHitModel.visible = true;
            this.unitHitModel.play("stand1");
            this.unitModel.play("hit");
        }
        _showReward() {
            sg.uimgr.showUI("pop_getReward", sg.translate('恭喜获得'), this._curReward);
            this._isPlay = false;
        }
        _onClick(e) {
            switch (e.target) {
                case this.btnLotterOne:
                    {
                        if (this._vo.free_item - this._vo.free_count > 0) {
                            this.onLottery(1);
                        }
                        else {
                            if (mgr.toolsMgr.checkConsume(this._cost1, true)) {
                                this.onLottery(1);
                            }
                        }
                    }
                    break;
                case this.btnAdd:
                    {
                        if (this._vo)
                            sg.uimgr.showAccess(this._vo.item_id);
                    }
                    break;
                case this.btnTask:
                    {
                        sg.uimgr.showUI("pop_SlgActiveTaskView");
                    }
                    break;
            }
        }
        _renderReward(cell, idx) {
            let data = cell.dataSource;
            if (!data)
                return;
            let lastTarget;
            let stageAdd = mvc.springModel.monsterVo.getStageAdd();
            if (idx == 0)
                lastTarget = 0;
            else
                lastTarget = mvc.springModel.monsterVo.stage[idx - 1][2] + stageAdd;
            cell.updateView(data, lastTarget, idx);
        }
        _onTime() {
            let actVo = mvc.activityModel.openActivityVo.get(mvc.FUNC_ID.BG_SPRING_MONSTER);
            this.lblTime.text = sg.translate("活动未开启");
            if (actVo) {
                let endTime = actVo.end_time;
                let curTime = sg.time.getSecondTime();
                let lastTime = endTime - curTime;
                if (lastTime > 0) {
                    this.lblTime.text = sg.translate("活动时间:") + sg.time.formatTimeStrT("F9", lastTime) + sg.translate("后结束");
                }
                else {
                    sg.uimgr.showNotice(sg.translate("活动结束"));
                    this.closeSelf();
                }
            }
        }
    }
    mvc.PopSpringMonster = PopSpringMonster;
})(mvc || (mvc = {}));

