(function (mvc) {
    class UnitSpringMonsterRwdItem extends ui.view.slgActivity2.unit_cjMonster_itemUI {
        onAwake() {
            super.onAwake();
            this.on(Laya.Event.CLICK, this, this._click);
        }
        onEnable() {
            super.onEnable();
        }
        updateView(data, lastTarget, idx) {
            let stageAdd = mvc.springModel.monsterVo.getStageAdd();
            let rewards = data[1];
            let target = data[2] + stageAdd;
            let curPoint = mvc.springModel.monsterVo.total_point;
            this._target = target;
            this.lblIntegral2.text = target.toString();
            let vo = mvc.ItemVo.createItemVo(rewards);
            this.item2.initView(vo);
            this.imgReceive.visible = this.imgShade.visible = this.imgGot.visible = false;
            this.item2.mouseEnabled = true;
            this._canGet = false;
            this.boxItem.rotation = 0;
            this.clearTweenByTarget(this.boxItem);
            if (mvc.springModel.monsterVo.isGetStageRwd(target)) {
                this.imgShade.visible = this.imgGot.visible = true;
            }
            else {
                if (curPoint >= target) {
                    this.imgReceive.visible = true;
                    this.imgReceive.play(0, -1);
                    this.item2.mouseEnabled = false;
                    this._canGet = true;
                    this.boxItem.rotation = 0;
                    this._onItemtweenTo1(this.boxItem);
                }
            }
            if (curPoint >= target) {
                this.proIntegral.value = 1;
            }
            else if (curPoint <= lastTarget) {
                this.proIntegral.value = 0;
            }
            else {
                this.proIntegral.value = (curPoint - lastTarget) / (target - lastTarget);
            }
            if (idx == mvc.springModel.monsterVo.stage.length - 1)
                this.boxItem.scale(1.5, 1.5);
            else
                this.boxItem.scale(1, 1);
        }
        _click() {
            if (!this._canGet)
                return;
            mvc.springCtrl.reqMonsterStageRwd(this._target);
        }
        _onItemtweenTo1(target) {
            this.clearTweenByTarget(target);
            this.tweenTo(target, { rotation: 13 }, 200, null, Laya.Handler.create(this, this._onItemtweenTo2, [target]));
        }
        _onItemtweenTo2(target) {
            this.clearTweenByTarget(target);
            this.tweenTo(target, { rotation: -14 }, 400, null, Laya.Handler.create(this, this._onItemtweenTo3, [target]));
        }
        _onItemtweenTo3(target) {
            this.clearTweenByTarget(target);
            this.tweenTo(target, { rotation: 13 }, 600, null, Laya.Handler.create(this, this._onItemtweenTo4, [target]));
        }
        _onItemtweenTo4(target) {
            this.clearTweenByTarget(target);
            this.tweenTo(target, { rotation: 0 }, 200, null, Laya.Handler.create(this, this._onItemtweenTo5, [target]));
        }
        _onItemtweenTo5(target) {
            this.clearTweenByTarget(target);
            this.tweenTo(target, { rotation: 0 }, 400, null, Laya.Handler.create(this, this._onItemtweenTo1, [target]));
        }
    }
    mvc.UnitSpringMonsterRwdItem = UnitSpringMonsterRwdItem;
})(mvc || (mvc = {}));

