(function (mvc) {
    class PopSuitDecompose extends ui.view.equipment.pop_suitDecomposeUI {
        initView() {
        }
        initModelEvent() {
            this.bindModelEvent(mvc.suitEquipModel, mvc.SuitEquipConst.EVT.UPDATE_BAG_SUIT, this.updateView);
        }
        initCtrlEvent() {
            this.listEquip.vScrollBarSkin = null;
            this.listEquip.selectEnable = true;
            this.listQuilty.selectEnable = true;
            this.listEquip.renderHandler = this.createHandler(this, this.renderSuitTypeItem, null, false);
            this.listQuilty.renderHandler = this.createHandler(this, this.renderQuilityTypeItem, null, false);
            this.listEquip.selectHandler = this.createHandler(this, this.selectSuitTypeItem, null, false);
            this.listQuilty.selectHandler = this.createHandler(this, this.selectQuilityTypeItem, null, false);
            this.listQuilty.vScrollBarSkin = null;
            this.listItem.selectEnable = true;
            this.listItem.vScrollBarSkin = null;
            this.listItem.renderHandler = this.createHandler(this, this.renderItem, null, false);
            this.listItem.selectHandler = this.createHandler(this, this.selectItem, null, false);
            this.listGet.renderHandler = this.createHandler(this, this.renderIcon, null, false);
            this.isCheck.on(Laya.Event.CHANGE, this, this.onClickHeight);
            this.handler = this.createHandler(this, this.recoverItem, null, false);
            this.btnDec.on(Laya.Event.CLICK, this, this.onClickDec);
        }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            this.initData();
            this.rejectArr = [];
            this.isCheck.selected = sg.varmgr.getSysVar("suitEquip") ? true : false;
            this.updateView();
        }
        onDisable() {
            super.onDisable();
            if (this.quality) {
                sg.varmgr.setSysVar("SuitDecompose_q", this.quality);
            }
            if (this.suitId) {
                sg.varmgr.setSysVar("SuitDecompose_s", this.suitId);
            }
            this.quality = null;
            this.suitId = null;
            this.rejectArr = null;
            this.listItem.array = null;
            this.listEquip.array = null;
            this.listQuilty.array = null;
        }
        onDestroy() {
            super.onDestroy();
            this.handler.recover();
        }
        initData() {
            let map = mvc.suitEquipModel.getSuitDecoMap();
            let data = sg.varmgr.getSysVar("SuitDecompose_q");
            if (!data) {
                this.quality = {};
                for (let v of map.quality) {
                    this.quality[v] = 0;
                }
            }
            else {
                this.quality = data;
            }
            data = sg.varmgr.getSysVar("SuitDecompose_s");
            if (!data) {
                this.suitId = {};
                for (let v of map.suitId) {
                    this.suitId[v] = 0;
                }
            }
            else {
                this.suitId = data;
            }
            this.listEquip.array = map.suitId;
            this.listQuilty.array = map.quality;
        }
        updateView() {
            let map = mvc.suitEquipModel.getDecItems(this.suitId, null, this.quality, this.isCheck.selected, this.rejectArr);
            this.listItem.array = map.re;
            let decompose = map.decompose;
            let arr = [];
            for (let key in decompose) {
                arr.push([parseInt(key), decompose[key]]);
            }
            this.listGet.array = arr;
        }
        renderItem(item, index) {
            let vo = mvc.bagModel.getItem(item.dataSource);
            item.initView(vo, false);
            item.isShowUp(mvc.suitEquipModel.comparCurEquip(vo));
        }
        selectItem(index) {
            let vo = mvc.bagModel.getItem(this.listItem.selectedItem);
            if (vo) {
                sg.uimgr.showUI("pop_suitEquipTip", vo, 1, this.handler);
            }
        }
        recoverItem(itemvo) {
            if (itemvo) {
                this.rejectArr.push(itemvo.bagId);
                this.updateView();
            }
        }
        renderIcon(box) {
            let data = box.dataSource;
            let imgIcon = box.getChildByName("imgIcon");
            let lblNum = box.getChildByName("lblNum");
            lblNum.text = data[1].toString();
            mgr.icon.drawTexture(mgr.icon.getIconPath(mgr.toolsMgr.getIconById(data[0])), imgIcon);
        }
        renderSuitTypeItem(box, index) {
            let cfg = sg.dbmgr.get("suit_forgeSuitUp", box.dataSource);
            box.selected = !!this.suitId[box.dataSource];
            box.label = cfg.name;
        }
        renderQuilityTypeItem(box, index) {
            let color = sg.dbmgr.get("color", box.dataSource);
            box.label = color.qualityName;
            box.selected = !!this.quality[box.dataSource];
        }
        selectSuitTypeItem(index) {
            if (index == -1) {
                return;
            }
            let item = this.listEquip.getCell(index);
            if (!item)
                return;
            this.suitId[item.dataSource] = item["selected"] ? item.dataSource : 0;
            this.updateView();
        }
        selectQuilityTypeItem(index) {
            if (index == -1) {
                return;
            }
            let item = this.listQuilty.getCell(index);
            if (!item)
                return;
            this.quality[item.dataSource] = item["selected"] ? item.dataSource : 0;
            this.updateView();
        }
        onClickHeight() {
            sg.varmgr.setSysVar("suitEquip", this.isCheck.selected ? 1 : 0);
            this.updateView();
        }
        onClickDec() {
            let arr = this.listItem.array;
            if (arr && arr.length > 0) {
                mvc.suitEquipCtrl.reqSuitDecompose(arr);
            }
        }
    }
    mvc.PopSuitDecompose = PopSuitDecompose;
})(mvc || (mvc = {}));

var mvc;
(function (mvc) {
    class PopSuitEquipTip extends ui.view.equipment.pop_suitInfoUI {
        initView(vo, showType, handler) {
            this._vo = vo;
            this._handler = handler;
            this._showType = showType;
        }
        initCtrlEvent() {
            this.btnDec.on(Laya.Event.CLICK, this, this._onDecompose);
            this.btnEuipe.on(Laya.Event.CLICK, this, this._onEquipSuit);
            this.btnRecode.on(Laya.Event.CLICK, this, this._onBtnRecode);
            this.btnLock.on(Laya.Event.CLICK, this, this._onBtnLock);
            this.panelShow.vScrollBarSkin = null;
        }
        initModelEvent() {
            this.bindModelEvent(mvc.suitEquipModel, mvc.SuitEquipConst.EVT.UPDATE_BAG_SUIT, this.lockShow);
        }
        onEnable() {
            super.onEnable();
            this.updateInfo();
        }
        onDisable() {
            super.onDisable();
            this._handler = null;
        }
        updateInfo() {
            let vo = this._vo;
            if (!vo)
                return;
            let cfg = vo.getCfg();
            this.unitItem.initView(vo, false);
            let scfg = sg.dbmgr.get("color", cfg.quality);
            this.lblEquipNam.text = scfg.qualityName;
            this.lblQuilty.text = cfg.name;
            this.lblEquipNam.color = this.lblQuilty.color = scfg.stringColor;
            mgr.toolsMgr.setQualityStroke(cfg.quality, this.lblEquipNam);
            mgr.toolsMgr.setQualityStroke(cfg.quality, this.lblQuilty);
            this.panelShow.vScrollBar.max = this.boxDesc.height - this.panelShow.height;
            this.btnLock.visible = this.imgLineup.visible = false;
            this.btnRecode.visible = this.btnEuipe.visible = this.btnDec.visible = false;
            let isColor = false;
            let isComper = false;
            switch (this._showType) {
                case 0:
                    {
                        this.btnLock.visible = true;
                        this.btnLock.index = this._vo.isLock;
                        this.btnEuipe.visible = this.btnDec.visible = true;
                    }
                    break;
                case 1: {
                    this.btnRecode.visible = true;
                    this.btnLock.visible = true;
                    this.btnLock.index = this._vo.isLock;
                }
                default:
                    {
                        isColor = true;
                        isComper = true;
                        let curVo = mvc.suitEquipModel.partShowMap.get(this._vo.getCfg().part);
                        this.imgLineup.visible = curVo && curVo.bagId == this._vo.bagId;
                    }
                    break;
            }
            mvc.suitEquipModel.showInfoDesc(this.boxDesc, mvc.suitEquipModel.getShowSuitCfg(vo), isColor, true, isComper);
            this._updateBoxProp();
        }
        lockShow() {
            this.btnLock.index = this._vo.isLock;
        }
        _updateBoxProp() {
            let lblName = this.boxProp.getChildByName("lblName");
            let lblValue = this.boxProp.getChildByName("lblValue");
            let imgUp = this.boxProp.getChildByName("imgUp");
            if (this._showType <= 1) {
                let curVo = mvc.suitEquipModel.partShowMap.get(this._vo.getCfg().suitType);
                if (curVo && this._vo) {
                    imgUp.visible = this._vo.attr[0][1] > curVo.attr[0][1];
                }
                else if (curVo) {
                    imgUp.visible = true;
                }
                else {
                    imgUp.visible = false;
                }
            }
            else {
                imgUp.visible = false;
            }
            if (this._vo.attr && this._vo.attr.length > 0) {
                let cfg = sg.dbmgr.get("attribute", this._vo.attr[0][0]);
                lblName.text = cfg.show_name;
                lblValue.text = cfg.is_per ? this._vo.attr[0][1] / 100 + "%" : this._vo.attr[0][1];
            }
        }
        _onDecompose() {
            let vo = this._vo;
            if (!vo)
                return;
            if (vo.isLock) {
                sg.uimgr.showNotice(sg.translate("该装备已上锁"));
                return;
            }
            mvc.suitEquipCtrl.reqSuitDecompose([this._vo.bagId]);
            this.closeSelf();
        }
        _onEquipSuit() {
            let vo = this._vo;
            if (!vo)
                return;
            mvc.suitEquipCtrl.reqWearSuitEquip(this._vo.bagId);
            this.closeSelf();
        }
        _onBtnRecode() {
            let vo = this._vo;
            if (!vo)
                return;
            if (this._handler) {
                this._handler.runWith(this._vo);
            }
            this.closeSelf();
        }
        _onBtnLock() {
            let vo = this._vo;
            if (!vo)
                return;
            mvc.suitEquipCtrl.reqSuitLock(vo.bagId, this._vo.isLock);
        }
    }
    mvc.PopSuitEquipTip = PopSuitEquipTip;
})(mvc || (mvc = {}));

