var mvc;
(function (mvc) {
    class PopSuitFurnaceLevelUp extends ui.view.equipment.pop_furnaceLevelUpUI {
        initView() {
        }
        initModelEvent() {
            this.bindModelEvent(mvc.suitEquipModel, mvc.SuitEquipConst.EVT.UPDATE_LV, this.updateLVChange);
            this.bindModelEvent(mvc.suitEquipModel, mvc.SuitEquipConst.EVT.UPDATE_LV_INFO, this.updatView);
            this.bindModelEvent(mvc.bagModel, mvc.BagConst.EVT.ITEM_NUM_CHANGE, this.renderUpLVBox);
        }
        initCtrlEvent() {
        }
        onAwake() {
            super.onAwake();
            this.listPerc.renderHandler = Laya.Handler.create(this, this.renderList, null, false);
            this.listEquip.renderHandler = Laya.Handler.create(this, this.renderSuitList, null, false);
            this.listEquip.selectHandler = Laya.Handler.create(this, this.selectSuitList, null, false);
            this.listEquip.selectEnable = true;
            this.listEff.renderHandler = Laya.Handler.create(this, this.renderEff, null, false);
            this.listEquip.hScrollBarSkin = "";
            this.on(Laya.Event.CLICK, this, this._onClick);
        }
        onEnable() {
            super.onEnable();
            this.listEff.visible = false;
            this.updatView();
            if (mvc.suitEquipModel.isCanPlayLv) {
                this.after(200, () => {
                    this.playEff();
                });
            }
        }
        updatView() {
            let cfg = sg.dbmgr.get("suit_forgeSuitLevel", mvc.suitEquipModel.level);
            if (!cfg)
                return;
            let scfg = sg.dbmgr.getUnique("suit_forgingFurnace", mvc.suitEquipModel.level, 0);
            this.listPerc.array = scfg.quality_weight;
            let arr = this.getEggLvLockPet(mvc.suitEquipModel.level + 1);
            if (this._furnaceLv == mvc.suitEquipModel.level + 1) {
                this.listEquip.array = arr;
                this.listEquip.visible = true;
                this.boxNone.visible = false;
            }
            else {
                this.listEquip.visible = false;
                this.boxNone.visible = true;
                if (arr.length <= 0) {
                    this.lblPet.text = sg.translate("套装已全部解锁");
                }
                else {
                    this.lblPet.text = mgr.UIAssist.$(sg.translate("{1}级可解锁新套装"), this._furnaceLv);
                }
            }
            this.lblCur.text = mgr.UIAssist.$(sg.translate("当前等级：{1}"), mvc.suitEquipModel.level);
            this.lblNext.text = mgr.UIAssist.$(sg.translate("下一等级：{1}"), mvc.suitEquipModel.level + 1);
            if (!cfg.upConsume) {
                this.boxMax.visible = true;
                this.boxUpState.visible = false;
                this.boxUpLv.visible = false;
            }
            else {
                this.boxMax.visible = false;
                if (mvc.suitEquipModel.endTime > 0) {
                    this.boxUpState.visible = false;
                    this.boxUpLv.visible = true;
                    this.renderUpLVBox();
                }
                else {
                    this.boxUpState.visible = true;
                    this.boxUpLv.visible = false;
                    this.renderStateBox();
                }
            }
        }
        getEggLvLockPet(lv) {
            let cfg = sg.dbmgr.get("suit_forgeSuitLevel", lv);
            let arr = [];
            if (cfg) {
                if (cfg.Unlock && cfg.Unlock.length > 0) {
                    this._furnaceLv = lv;
                    for (let key in cfg.Unlock) {
                        arr.push(cfg.Unlock[key]);
                    }
                }
                else {
                    this._furnaceLv = lv + 1;
                    cfg = sg.dbmgr.get("suit_forgeSuitLevel", this._furnaceLv);
                    while (cfg) {
                        if (cfg.Unlock && cfg.Unlock.length > 0) {
                            arr.push(1);
                            cfg = null;
                        }
                        else {
                            this._furnaceLv = this._furnaceLv + 1;
                            cfg = sg.dbmgr.get("suit_forgeSuitLevel", this._furnaceLv);
                        }
                    }
                }
            }
            return arr;
        }
        renderList(item, index) {
            let lblCur = item.getChildByName("lblCur");
            let lblNext = item.getChildByName("lblNext");
            let arr = item.dataSource;
            lblCur.text = arr[1] / 100 + "%";
            let nextcfg = sg.dbmgr.getUnique("suit_forgingFurnace", mvc.suitEquipModel.level + 1, 0);
            lblNext.text = nextcfg ? nextcfg.quality_weight[index][1] / 100 + "%" : "";
        }
        renderSuitList(item, index) {
            let lblSuit = item.getChildByName("lblSuit");
            let imgSuit = item.getChildByName("imgSuit");
            let id = item.dataSource;
            let cfg = sg.dbmgr.get("suit_forgeSuitUp", id);
            lblSuit.text = cfg.name;
            mgr.icon.drawTexture(mgr.icon.getIconPath(cfg.icon), imgSuit);
        }
        selectSuitList(index) {
            sg.uimgr.showUI("pop_suitTip", this.listEquip.selectedItem);
        }
        renderStateBox() {
            let cfg = sg.dbmgr.get("suit_forgeSuitLevel", mvc.suitEquipModel.level);
            mgr.icon.drawTexture(mgr.icon.getIconPath(mgr.toolsMgr.getIconById(cfg.upConsume[0][0])), this.imgCoin);
            this.lblCoinNum.text = cfg.upConsume[0][1];
            let isE = mgr.toolsMgr.checkConsume(cfg.upConsume);
            this.lblCoinNum.color = isE ? "#0b7d13" : "#ea3e09";
            this.lblUpLimit.text = cfg.limitDesc;
            this.lblUpLimit.visible = !mgr.conditionMgr.check(cfg.uplimit, false);
            this.sprUpState.visible = isE && !this.lblUpLimit.visible;
            this.lblUpTime.text = mgr.UIAssist.$(sg.translate("时间：{1}"), sg.time.formatTimeStr(cfg.time));
            this.redUp.visible = cfg.stage == mvc.suitEquipModel.state;
            this.btnUpState.visible = this.btnUpLv.disabled = cfg.stage != mvc.suitEquipModel.state;
            this.cellProgress.updateView(mvc.suitEquipModel.state / cfg.stage, cfg.stage);
        }
        renderUpLVBox() {
            let gcfg = mgr.toolsMgr.getGlobalVoById("speed_up_furnace_item", 1);
            mgr.icon.drawTexture(mgr.icon.getIconPath(mgr.toolsMgr.getIconById(gcfg[0])), this.lblAccIcon);
            let num = mgr.toolsMgr.getCountById(gcfg[0]);
            this.lblAccNum.text = mgr.toolsMgr.getCountById(gcfg[0]).toString();
            this.lblAccNum.color = num > 0 ? "#0b7d13" : "#ea3e09";
            if (mvc.suitEquipModel.endTime - sg.time.getSecondTime() > 0) {
                this.repeats(1000, this.updateTime, true);
            }
            else {
                this.stopTimer(this.updateTime);
            }
            if (!this.btnAcc.visible)
                this.btnAcc.x = (this.width - this.btnAcc.width) / 2;
        }
        updateTime() {
            let time = mvc.suitEquipModel.addCdTime - sg.time.getSecondTime();
            this.lookVidoTime.visible = time > 0;
            if (time > 0) {
                this.lookVidoTime.text = sg.time.formatTimeStr(time);
            }
            time = mvc.suitEquipModel.endTime - sg.time.getSecondTime();
            if (time > 0) {
                this.lblUpCountTime.text = sg.time.formatTimeStr(time);
            }
        }
        updateLVChange() {
            this.playEff();
            this.updatView();
        }
        playEff() {
            let cfg = sg.dbmgr.getUnique("suit_forgingFurnace", mvc.suitEquipModel.level, 0);
            if (!cfg)
                return;
            this.listEff.array = cfg.quality_weight;
            mvc.suitEquipModel.isCanPlayLv = false;
            this.listEff.visible = true;
        }
        renderEff(box, index) {
            let eff = box.getChildAt(0);
            if (eff) {
                eff.visible = false;
                this.after(200 * index, () => {
                    eff.play(0, eff.total);
                    eff.visible = true;
                });
                if (index == this.listEff.array.length - 1) {
                    eff.on(Laya.Event.COMPLETE, this, () => {
                        this.listEff.visible = false;
                    });
                }
            }
        }
        _onClick(event) {
            let target = event.target;
            let cfg = sg.dbmgr.get("suit_forgeSuitLevel", mvc.suitEquipModel.level);
            switch (target.name) {
                case "btnUpState":
                    {
                        if (mgr.conditionMgr.check(cfg.uplimit, true) && mgr.toolsMgr.checkConsume(cfg.upConsume, true)) {
                            mvc.suitEquipCtrl.reqFurnaceUpLv();
                        }
                    }
                    break;
                case "btnUpLv":
                    {
                        let cfg = sg.dbmgr.get("suit_forgeSuitLevel", mvc.suitEquipModel.level);
                        if (cfg && cfg.stage == mvc.suitEquipModel.state) {
                            mvc.suitEquipCtrl.reqFurnaceUpLv();
                        }
                    }
                    break;
                case "btnAcc":
                    {
                        sg.uimgr.showUI("pop_accComplate", mvc.suitEquipModel.endTime, 3);
                    }
                    break;
                case "btnUnionHelp":
                    if (mvc.roleModel.roleInfo.guildId <= 0) {
                        sg.uimgr.showNotice(sg.translate("您还没加入仙盟"));
                        return;
                    }
                    if (mvc.suitEquipModel.endTime > 0) {
                        mvc.guildCtrl.reqGuildSeekHelp(mvc.GuildConst.HELP_TYPE.SUIT_FURNACE, mvc.suitEquipModel.level + 1);
                    }
                    break;
                case "btnLookAd":
                    {
                        if (mvc.suitEquipModel.addCdTime - sg.time.getSecondTime() > 0) {
                            sg.uimgr.showNotice(sg.translate("太勤劳了，过会再来"));
                            return;
                        }
                        if (mgr.gplatform.isDebug) {
                            mvc.suitEquipCtrl.reqFurnaceSpeedTime(0);
                        }
                        else {
                            mgr.gplatform.showAdvertVideo(sdk.ADVERT_VIDEO_SRC.SUIT, (suc) => {
                                if (suc) {
                                    mvc.suitEquipCtrl.reqFurnaceSpeedTime(0);
                                }
                            });
                        }
                    }
                    break;
            }
        }
    }
    mvc.PopSuitFurnaceLevelUp = PopSuitFurnaceLevelUp;
})(mvc || (mvc = {}));

