(function (mvc) {
    class UnitMainSuitItem extends ui.view.equipment.unit_mainSuitItemUI {
        initView(vos, suitId, isOpen, handler) {
            this.isOpen = isOpen;
            this.bagVos = vos;
            this._handler = handler;
            this._suitId = suitId;
        }
        initModelEvent() {
        }
        initCtrlEvent() {
            this.listSuit.vScrollBarSkin = null;
            this.listSuit.itemRender = mvc.UntiSuitEquipItem;
            this.listSuit.renderHandler = this.createHandler(this, this.renderList, null, false);
            this.boxTitle.on(Laya.Event.CLICK, this, this._clickShow);
        }
        onAwake() {
            super.onAwake();
            this._oHeight = this.imgBg.height;
        }
        onEnable() {
            super.onEnable();
            this.updateView();
        }
        onDisable() {
            super.onDisable();
        }
        updateView() {
            this.updateTitleBox();
        }
        updateTitleBox() {
            let cfg = sg.dbmgr.get("suit_forgeSuitUp", this._suitId);
            if (!cfg)
                return;
            if (this._suitId) {
                this.lblSuit.text = cfg.name;
                this.lblDesc.text = cfg.suitInfo;
                this.redSuit.visible = mvc.suitEquipModel.isNewSuitEquipBySuit(this._suitId);
                mgr.icon.drawTexture(mgr.icon.getIconPath(cfg.icon), this.imgIcon);
                if (this.bagVos && this.bagVos.length > 0) {
                    this.listSuit.array = this.bagVos;
                    let box = this.listSuit.getCell(0);
                    let width = Math.ceil(this.listSuit.width / (box.width + this.listSuit.spaceX));
                    let h = Math.ceil(this.bagVos.length / width);
                    let hight = h * (box.height + this.listSuit.spaceY) - this.listSuit.spaceY;
                    this.listSuit.height = hight;
                    this.boxList.height = this.imgBg.height = hight + 30;
                    this.listSuit.visible = true;
                    this.boxNull.visible = false;
                    this.lblValue.text = this.bagVos.length.toString();
                }
                else {
                    this.listSuit.visible = false;
                    this.boxNull.visible = true;
                    this.boxList.height = this.imgBg.height = this._oHeight;
                    let cfg1 = mvc.suitEquipModel.getSuitCfgId(this._suitId, 2, mvc.SuitEquipConst.showHei);
                    let cfg2 = mvc.suitEquipModel.getSuitCfgId(this._suitId, 4, mvc.SuitEquipConst.showHei);
                    mvc.suitEquipModel.showInfoDesc(this.boxDesc, [cfg1, cfg2]);
                    this.lblValue.text = "0";
                }
            }
            this.realityHeight();
        }
        renderList(item) {
            if (!item.dataSource)
                return;
            item.initView(item.dataSource);
            item.isShowNew(mvc.suitEquipModel.isNewSuitEquip(item.dataSource.getCfg(), item.dataSource.bagId));
            item.isShowUp(mvc.suitEquipModel.comparCurEquip(item.dataSource));
        }
        realityHeight(isOpen = -1) {
            if (isOpen != -1) {
                this.isOpen = this._suitId == isOpen ? true : false;
            }
            if (!this.boxList)
                return 100;
            if (!this.isOpen) {
                this.height = this.boxTitle.height;
                mgr.icon.drawTexture("ui/common/image/img_xmboss_zjlb_fy2.png", this.btnTip);
                this.boxList.visible = false;
            }
            else {
                this.height = this.boxTitle.height + this.boxList.height;
                mgr.icon.drawTexture("ui/common/image/img_xmboss_zjlb_fy1.png", this.btnTip);
                this.boxList.visible = true;
            }
            return this.height;
        }
        _clickShow() {
            if (this._handler)
                this._handler.runWith(this.isOpen ? 0 : this._suitId);
        }
        clearView() {
            this.isOpen = false;
            this.bagVos = null;
            this.removeSelf();
        }
    }
    mvc.UnitMainSuitItem = UnitMainSuitItem;
})(mvc || (mvc = {}));

