(function (mvc) {
    class UnitSuitShow extends ui.view.equipment.unit_suitShowUI {
        onAwake() {
            super.onAwake();
            this.openSuitId = -1;
        }
        initView(arr, height) {
            this.suitMap = arr;
            if (!this._handler) {
                this._handler = this.createHandler(this, this.changePosView, null, false);
            }
            this.updateView();
        }
        initCtrlEvent() {
            this.panelShow.vScrollBarSkin = null;
            let bar = this.panelShow.vScrollBar;
            bar.isVertical = true;
            bar.elasticBackTime = 600;
            bar.elasticDistance = 200;
        }
        onEnable() {
            super.onEnable();
            this.updateView();
        }
        onDisable() {
            super.onDisable();
            this.suitMap = null;
            this.clearView();
        }
        onDestroy() {
            super.onDestroy();
            this.clearPool();
            this._handler.recover();
            this._handler = null;
        }
        updateView() {
            if (!this.suitMap)
                return;
            this.clearView();
            let y = 0;
            let cfgs = mvc.suitEquipModel.getUnlockSuit();
            for (let key in cfgs) {
                let suitId = cfgs[key];
                let item = Laya.Pool.getItemByClass(mvc.MainConst.POOL_CONST.UNTISUITEQUIPITEM, mvc.UnitMainSuitItem);
                item.init("", this.suitMap[suitId], suitId, suitId == this.openSuitId, this._handler);
                this.panelShow.addChild(item);
                item.y = y;
                y = y + item.realityHeight();
            }
            this.panelShow.vScrollBar.max = y - this.panelShow.height;
        }
        changePosView(suitId) {
            if (suitId) {
                this.openSuitId = suitId;
            }
            else {
                this.openSuitId = 0;
            }
            let y = 0;
            let numChildren = this.panelShow.numChildren;
            for (let i = 0; i < numChildren; i++) {
                let item = this.panelShow.getChildAt(i);
                if (item) {
                    item.y = y;
                    y = y + item.realityHeight(this.openSuitId);
                }
            }
            this.panelShow.vScrollBar.max = y - this.panelShow.height;
        }
        clearView() {
            let numChildren = this.panelShow.numChildren;
            for (let i = numChildren; i >= 0; i--) {
                let item = this.panelShow.getChildAt(i);
                if (item && !item.destroyed) {
                    item.clearView();
                    Laya.Pool.recover(mvc.MainConst.POOL_CONST.UNTISUITEQUIPITEM, item);
                }
            }
        }
        clearPool() {
            let pool = Laya.Pool.getPoolBySign(mvc.MainConst.POOL_CONST.UNTISUITEQUIPITEM);
            for (let key in pool) {
                let item = pool[key];
                if (!item.destroyed) {
                    item.destroy();
                }
            }
            Laya.Pool.clearBySign(mvc.MainConst.POOL_CONST.UNTISUITEQUIPITEM);
        }
    }
    mvc.UnitSuitShow = UnitSuitShow;
})(mvc || (mvc = {}));

