(function (mvc) {
    let EVT = mvc.SubScribeConst.EVT;
    class SubscribeModel extends sg.ModelBase {
        initModel() {
            this.subscribeInfo = new Map();
        }
        registerEvents() {
        }
        setSubscribeInfo(data) {
            this.subscribeInfo = new Map();
            for (let i = 0, len = data.info.length; i < len; i++) {
                let info = data.info[i];
                this.subscribeInfo.set(info.id, info);
            }
            this.fireEvent(EVT.UPDATE_VIEW);
        }
        changeSubscribeInfo(data) {
            if (this.subscribeInfo.get(data.id) != undefined) {
                this.subscribeInfo.get(data.id).is_open = data.is_open;
            }
            this.fireEvent(EVT.UPDATE_VIEW);
        }
        changeSubSubscribeInfo(data) {
            if (this.subscribeInfo.get(data.sub_info.id) != undefined) {
                this.subscribeInfo.set(data.sub_info.id, data.sub_info);
            }
        }
        getSubSubscribeInfoState(id, sub_id) {
            if (this.subscribeInfo.get(id) != undefined) {
                let sub_info = this.subscribeInfo.get(id).sub_info;
                for (let i = 0, len = sub_info.length; i < len; i++) {
                    let info = sub_info[i];
                    if (info.sub_id == sub_id) {
                        return info.is_open == 1;
                    }
                }
            }
            else {
                return false;
            }
        }
        getSubSubscribeInfoParam(id, sub_id) {
            if (this.subscribeInfo.get(id) != undefined) {
                let sub_info = this.subscribeInfo.get(id).sub_info;
                for (let i = 0, len = sub_info.length; i < len; i++) {
                    let info = sub_info[i];
                    if (info.sub_id == sub_id) {
                        return info.param;
                    }
                }
            }
            else {
                return 0;
            }
        }
        _sendSubscribe(id, type) {
            if (this.subscribeInfo.get(id) != undefined) {
                if (this.subscribeInfo.get(id).is_open) {
                    mgr.gplatform.requestSubscribeMsg([type], (suc, data) => {
                        if (suc) {
                            mvc.subscribeCtrl.reqSendSubscribe(data.game_id, data.open_id, data.template_id);
                        }
                    });
                    window["MyGame"].openLog && console.log(`订阅${id}事件, 事件类型为${type}`);
                }
            }
        }
        checkCanSendSubscribe(id, type) {
            let last_time = sg.varmgr.getSysVar(`subscribe_message_${type}`);
            let now_time = sg.time.getSecondTime();
            if (!last_time) {
                this._sendSubscribe(id, type);
                sg.varmgr.setSysVar(`subscribe_message_${type}`, now_time);
            }
            else {
                let time = mgr.toolsMgr.getGlobalVoById("subscribe_cd", 1);
                if (now_time - last_time >= time) {
                    this._sendSubscribe(id, type);
                    sg.varmgr.setSysVar(`subscribe_message_${type}`, now_time);
                }
            }
        }
        openSendSubscribe(id, type) {
            mgr.gplatform.requestSubscribeMsg([type], (suc, data) => {
                if (suc) {
                    mvc.subscribeCtrl.reqSendSubscribe(data.game_id, data.open_id, data.template_id);
                }
            });
            window["MyGame"].openLog && console.log(`订阅${id}事件, 事件类型为${type}`);
        }
    }
    mvc.SubscribeModel = SubscribeModel;
})(mvc || (mvc = {}));

