var mvc;
(function (mvc) {
    class InvestModel extends sg.ModelBase {
        initModel() {
            this.typeInfo = {};
            let type = mvc.InvestConst.InvestType;
            this._typeIndex = [type.LEVEL, type.EGG_LV, type.TOWER_LV];
        }
        registerEvents() {
            let type = mvc.InvestConst.InvestType;
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.INVEST_ONE, this.checkRedByType.bind(this, type.LEVEL), this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.INVEST_TWO, this.checkRedByType.bind(this, type.EGG_LV), this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.INVEST_THREE, this.checkRedByType.bind(this, type.TOWER_LV), this);
        }
        getChangeIndex(index) {
            return this._typeIndex[index];
        }
        getShowCfgByType(type) {
            if (!this.showCfgs) {
                this.showCfgs = {};
                let cfgs = sg.dbmgr.getDB("investmentPlan_growUpFundReward");
                for (let key in cfgs) {
                    let arr = this.showCfgs[cfgs[key].type] || [];
                    arr.push(cfgs[key]);
                    this.showCfgs[cfgs[key].type] = arr;
                }
            }
            return this.showCfgs[type];
        }
        isGotFreeByType(type, id) {
            let info = this.typeInfo[type];
            for (let v of info.reward) {
                if (v[0] == id && v[1] == 1) {
                    return true;
                }
            }
            return false;
        }
        getTaskAccepted(type, id) {
            let info = this.typeInfo[type];
            for (let v of info.accepted) {
                if (v.id == id) {
                    return v;
                }
            }
            return null;
        }
        getCurShowIndex(type) {
            let cfgs = this.getShowCfgByType(type);
            let info = this.typeInfo[type];
            let maxId = 0;
            let rewardMin = Infinity;
            for (let v of info.finished) {
                let reward = this.getRewardStateByType(type, v);
                if (!reward || (reward[1] != 1 || (reward[2] != 1 && info.is_unlock))) {
                    if (v <= rewardMin) {
                        rewardMin = v;
                    }
                }
                else {
                    if (v > maxId) {
                        maxId = v;
                    }
                }
            }
            maxId = rewardMin != Infinity ? rewardMin : maxId;
            for (let key in cfgs) {
                let cfg = cfgs[key];
                if (cfg.id == maxId) {
                    return parseInt(key);
                }
            }
            return 0;
        }
        isCanRewardByType(type, id) {
            let info = this.typeInfo[type];
            let index = info.finished.indexOf(id);
            if (index != -1) {
                return 1;
            }
            return 0;
        }
        getRewardStateByType(type, id) {
            let info = this.typeInfo[type];
            for (let v of info.reward) {
                if (v[0] == id) {
                    return v;
                }
            }
            return null;
        }
        checkRedByType(type) {
            let info = this.typeInfo[type];
            for (let key in info.finished) {
                let reward = this.getRewardStateByType(type, info.finished[key]);
                if (!reward || (reward[1] != 1 || (reward[2] != 1 && info.is_unlock))) {
                    return 1;
                }
            }
            return 0;
        }
        checkRedUpdate(type) {
            let constType = mvc.InvestConst.InvestType;
            switch (type) {
                case constType.LEVEL:
                    mgr.redotMgr.check(mvc.REDOT_ID.INVEST_ONE);
                    break;
                case constType.EGG_LV:
                    mgr.redotMgr.check(mvc.REDOT_ID.INVEST_TWO);
                    break;
                case constType.LEVEL:
                    mgr.redotMgr.check(mvc.REDOT_ID.INVEST_THREE);
                    break;
                default:
                    mgr.redotMgr.check(mvc.REDOT_ID.INVEST_ONE);
                    mgr.redotMgr.check(mvc.REDOT_ID.INVEST_THREE);
                    mgr.redotMgr.check(mvc.REDOT_ID.INVEST_TWO);
                    break;
            }
        }
    }
    mvc.InvestModel = InvestModel;
})(mvc || (mvc = {}));

