            cell.getChildByName("lblName").text = cfg.name;
            cell.getChildByName("lblCount").text = mgr.UIAssist.$(sg.translate("红包数量:{1}"), cfg.number);
            let lblTotal = cell.getChildByName("lblTotal");
            lblTotal.text = mgr.UIAssist.$(sg.translate("红包金额:{1}"), cfg.singe_reward[0]);
            let imgIcon = cell.getChildByName("imgIcon");
