            this.btnDanmu.on(Laya.Event.CLICK, this, this._onClick);
            this.cboxNotAni.on(Laya.Event.CLICK, this, this._onClick);
            this.btnRedBag.on(Laya.Event.CLICK, this, this._onClick);
