(function (mvc) {
    class UnitHFTaskItem extends ui.view.hfActivity.unit_hftask_itemUI {
        initView(vo, model) {
            this._vo = vo;
            this._model = model;
            this._updateView();
        }
        initCtrlEvent() {
            this.btnGet.on(Laya.Event.CLICK, this, this._onBtnGet);
        }
        _updateView() {
            this.lblTitle.text = this._vo.name;
            this.lblNum.text = sg.translate('×') + this._vo.point;
            let isGet = this._model.finished.indexOf(this._vo.id) != -1;
            let pro = this._model.getTaskProById(this._vo.id);
            let maxPro = this._vo.condition[1];
            this.proTask.value = Math.min(1, pro / maxPro);
            this.lblPro.text = `${pro}/${maxPro}`;
            let vos = mvc.ItemVo.createItemVos(this._vo.rewards);
            this.viewReward.initView(vos[0]);
            this.viewReward2.initView(vos[1]);
            this.btnGet.disabled = false;
            this.redotTask.visible = false;
            let isComplete = pro >= maxPro;
            if (isComplete) {
                if (isGet) {
                    this.btnGet.label = sg.translate("已领取");
                    this.btnGet.disabled = true;
                }
                else {
                    this.btnGet.label = sg.translate("领取");
                    this.redotTask.visible = true;
                }
            }
            else {
                this.btnGet.label = sg.translate("前往");
            }
        }
        _onBtnGet() {
            if (!this._model.isActOpen()) {
                sg.uimgr.showNotice(sg.translate("活动已结束"));
                return;
            }
            if (this.btnGet.label == sg.translate("前往")) {
                if (this._vo.tips.length > 0) {
                    sg.uimgr.showNotice(this._vo.tips);
                }
                else {
                    if (this._vo.link == "pop_guildHunting") {
                        if (mvc.roleModel.roleInfo.guildId == 0) {
                            sg.uimgr.showNotice(sg.translate("请先加入仙盟"));
                            return;
                        }
                    }
                    sg.uimgr.jumpUI(this._vo.link[1], { layer: this._vo.link[2], funId: this._vo.link[3] });
                }
            }
            else if (this.btnGet.label == sg.translate("领取")) {
                mvc.slgActivityCtrl.reqBgTaskSubmit(this._vo.id, this._model.type);
            }
        }
    }
    mvc.UnitHFTaskItem = UnitHFTaskItem;
})(mvc || (mvc = {}));

