(function (mvc) {
    class PopDsqqSpeedView extends ui.view.bgActivity10.pop_dsqq_speedUI {
        initView(speedInfo) {
            this._speedInfo = this._speedMetadata = speedInfo.concat();
        }
        initCtrlEvent() {
            this.listRedbag.renderHandler = this.createHandler(this, this._onListRedBagClick, null, false);
            this.listRedbag.vScrollBarSkin = "";
        }
        onEnable() {
            super.onEnable();
            this._updateView();
        }
        onDisable() {
            super.onDisable();
            this.clearTimer(this, this._onChangeTimeText);
        }
        _updateView() {
            if (this._speedInfo == null) {
                return;
            }
            this.clearTimer(this, this._onChangeTimeText);
            this._onChangeTimeItemData(true);
            if (this._speedInfo.length > 0) {
                this.timerLoop(1000, this, this._onChangeTimeText);
            }
        }
        _onChangeTimeText() {
            this._onChangeTimeItemData(false);
        }
        _onChangeTimeItemData(changeData = false) {
            let timeNow = sg.time.getNow() / 1000;
            let speedInfo = [];
            for (let n = 0; n < this._speedInfo.length; n++) {
                let info = this._speedInfo[n];
                let timeNum = info.end_sec - timeNow;
                if (timeNum > 0) {
                    speedInfo.push(info);
                }
            }
            if (changeData || this._speedInfo.length == 0 || this._speedInfo.length != speedInfo.length) {
                this._speedInfo = speedInfo;
                this.listRedbag.array = this._speedInfo;
            }
            else {
                for (let i = 0; i < this.listRedbag.content.numChildren; i++) {
                    let item = this.listRedbag.content.getChildAt(i);
                    let data = item.dataSource;
                    let time = item.getChildByName("time");
                    if (data && time && time.visible) {
                        let timeNum = data.end_sec - timeNow;
                        this._updateTimeLb(time, timeNum);
                    }
                }
            }
            this.lbSpeed.text = mgr.UIAssist.$(sg.translate("速度总加成: {1}里/时"), mvc.bgLotteryModel.getActVo10().getShowSpeed(this._speedInfo, true));
            this.lbTips.visible = this._speedInfo.length <= 0;
        }
        _onListRedBagClick(cell, index) {
            let data = cell.dataSource;
            if (data == null) {
                return;
            }
            let boxDec = cell.getChildByName("boxDec");
            let detail = boxDec.getChildByName("detail");
            let time = cell.getChildByName("time");
            let speed = boxDec.getChildByName("speed");
            let icon = cell.getChildByName("icon");
            let config = sg.dbmgr.get("backgroundActive_active10Speed", data.type);
            time.visible = true;
            if (config) {
                detail.text = config.desc;
                speed.text = "+" + data.c_speed + "";
                mgr.icon.drawTexture(config.res, icon);
                if (config.ID == 5) {
                    time.visible = false;
                    let timeNum = data.end_sec - sg.time.getNow() / 1000;
                    this._updateTimeLb(time, timeNum);
                }
            }
        }
        _updateTimeLb(text, time) {
            text.text = mgr.UIAssist.$(sg.translate("剩余时间：{1}"), sg.time.formatTimeStrT("F2", time));
        }
    }
    mvc.PopDsqqSpeedView = PopDsqqSpeedView;
})(mvc || (mvc = {}));

