        parmaDataInfo(data) {
            let str = "";
            let cfg = sg.dbmgr.get("chat_notice", 11);
            str = mvc.mainModel.analyzeNotic(cfg.value, [[data[0]], [data[1], data[2]]]);
            return str;
        }
        _onRenderList(cell, index) {
            if (!cell.dataSource)
                return;
            let data = cell.dataSource;
            let item = cell.getChildByName("item");
            let lblLimit = cell.getChildByName("lblLimit");
            if (item) {
                let itemVo = new mvc.ItemVo();
                itemVo.initData(data.item_id, data.num);
                item.initView(itemVo);
            }
            if (lblLimit) {
                if (data.max_get_count != 0) {
                    lblLimit.text = sg.translate("限量:") + (data.max_get_count - data.get_count) + "/" + data.max_get_count;
                    lblLimit.color = data.get_count < data.max_get_count
                        ? mgr.toolsMgr.getColor3("green").stringColor
                        : mgr.toolsMgr.getColor3("red").stringColor;
                }
                else {
                    lblLimit.text = sg.translate("无限量");
                    lblLimit.color = mgr.toolsMgr.getColor3("green").stringColor;
                }
            }
        }
