                        lb.stroke = 3;
                        lb.strokeColor = "#363636";
                        lb.x = 0;
                        lb.y = currItem.y + currItem.height / 2 - 12;
                        lb.text = mgr.UIAssist.$(sg.translate("- {1}里"), currItem.getData().getRouteDistance());
                        ;
