                this.boxLog.visible = false;
                this.imgSelect.visible = false;
                let aniStopIndex = 0;
                this.imgIndicator.rotation %= 360;
                this._curRewards = rewards;
                if (this._vo.isGuaranteeById(rewards[0].id)) {
                    aniStopIndex = 12;
                }
                else {
                    let arr = this._vo.getUnTopReward();
                    for (let i = 1; i < 12; i++) {
                        let info = arr[i - 1];
                        if (info.item_id == rewards[0][0]) {
                            aniStopIndex = i;
                            break;
                        }
                    }
                }
                let curIndex = this.imgIndicator.rotation / 30;
                let changeIndex = 0;
                if (aniStopIndex - curIndex > 0) {
                    changeIndex = aniStopIndex - curIndex;
                }
                else {
                    changeIndex = 12 - Math.abs(aniStopIndex - curIndex);
                }
                let angle = this.imgIndicator.rotation + 360 * 3 + changeIndex * 30;
