var mvc;
(function (mvc) {
    class UnitDsqqTaskItem extends ui.view.bgActivity10.unit_dsqq_taskItemUI {
        initView(vo, type = null) {
            this._vo = vo;
            this._model = mvc.bgLotteryModel;
            this._ctrl = mvc.bgLotteryCtrl;
            this._updateView();
        }
        initCtrlEvent() {
            this.btnGetReward.on(Laya.Event.CLICK, this, this._onBtnGetReward);
            this.btnGo.on(Laya.Event.CLICK, this, this._onBtnGo);
        }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
        }
        _updateView() {
            this.lblTitle.text = this._vo.name;
            let progress = this._model.getTaskProgById(this._vo.id);
            let isFinish = this._model.getTaskStateById(this._vo.id);
            let target = this._vo.need[this._vo.need.length - 1];
            if (isFinish)
                progress = target;
            progress = Math.min(progress, target);
            this.progTask.value = progress / target;
            this.lblTaskNum.text = `${progress}/${target}`;
            let vos = mvc.ItemVo.createItemVos(this._vo.reward);
            this.itemReward.initView(vos[0]);
            let isComplete = progress >= target;
            this.btnGo.visible = !isComplete;
            this.btnGetReward.visible = isComplete;
            this.unitRedotTask.visible = false;
            if (isComplete) {
                this.btnGetReward.disabled = isFinish;
                if (isFinish)
                    this.btnGetReward.label = sg.translate("已领取");
                else {
                    this.unitRedotTask.visible = true;
                    this.btnGetReward.label = sg.translate("领取");
                }
            }
        }
        _onBtnGetReward() {
            let task_id = this._vo.id;
            this._ctrl.reqTaskReward(task_id);
        }
        _onBtnGo() {
            if (this._vo.tips.length > 0) {
                sg.uimgr.showNotice(this._vo.tips);
            }
            else {
                if (this._vo.link == "pop_guildHunting") {
                    if (mvc.roleModel.roleInfo.guildId == 0) {
                        sg.uimgr.showNotice(sg.translate("请先加入仙盟"));
                        return;
                    }
                }
                sg.uimgr.jumpUI(this._vo.link[1], { layer: this._vo.link[2], funId: this._vo.link[3] });
            }
        }
    }
    mvc.UnitDsqqTaskItem = UnitDsqqTaskItem;
})(mvc || (mvc = {}));

