            if (mvc.roleModel.roleInfo.guildId == 0) {
                sg.uimgr.showNotice(sg.translate("未加入仙盟"));
                return;
            }
            let time = mgr.toolsMgr.getGlobalVoById("chat_newslimit_cd", 1) * 1000 + 200;
            if (this.giftLastSendTime && (this.giftLastSendTime + time) > sg.time.getTime()) {
                sg.uimgr.showNotice(sg.translate("请稍后重试分享"));
                return;
            }
            this.giftLastSendTime = sg.time.getTime();
