(function (mvc) {
    class BgCharmRankModel extends sg.ModelBase {
        constructor() {
            super(...arguments);
            this.giveNum = 0;
        }
        initModel() {
        }
        willEnterGame() {
            if (this.cacheReward && this.cacheReward.length > 0) {
                this.showReward(this.cacheReward);
                this.cacheReward.length = 0;
            }
        }
        registerEvents() {
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.BG_ACT_CHARM_RANK_ITEM, this.checkRed, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.BG_ACT_CHARM_RANK_SHARE, this.checkRedShare, this);
            this.bindEvent(mvc.activityModel, mvc.ActivityConst.EVT.CHANGE_ICON, this._onActUpdate);
            this.bindEvent(mvc.activityModel, mvc.ActivityConst.EVT.END, this._onActUpdate);
            this.bindEvent(mvc.bagModel, mvc.BagConst.EVT.ITEM_NUM_CHANGE, this._onItemChange);
        }
        checkRed() {
            if (!this.cfgInfo)
                return 0;
            let vo = mvc.activityModel.openActivityVo.get(mvc.FUNC_ID.BG_ACT_CHARM_RANK);
            if (!vo || vo.state != mvc.ActivityConst.STATE.NORMAL)
                return 0;
            for (let cfg of this.cfgInfo.lure_data) {
                if (mvc.bagModel.getItemNumById(cfg.owner_cost[0][0]))
                    return 1;
            }
            return 0;
        }
        checkRedShare() {
            if (!this.shareInfo)
                return;
            let vo = mvc.activityModel.openActivityVo.get(mvc.FUNC_ID.BG_ACT_CHARM_RANK);
            if (!vo || vo.state != mvc.ActivityConst.STATE.NORMAL)
                return 0;
            for (let d of this.shareInfo) {
                if (d.is_reward == 0) {
                    return 1;
                }
            }
            return 0;
        }
        _onActUpdate() {
            mgr.redotMgr.check(mvc.REDOT_ID.BG_ACT_CHARM_RANK_ITEM);
            mgr.redotMgr.check(mvc.REDOT_ID.BG_ACT_CHARM_RANK_SHARE);
        }
        _onItemChange() {
            mgr.redotMgr.check(mvc.REDOT_ID.BG_ACT_CHARM_RANK_ITEM);
        }
        showReward(reward) {
            sg.uimgr.showUI("pop_getReward", sg.translate("仙宫庆典专属奖励"), reward);
        }
        setInviteCode(data) {
            this.inviteCode = data;
            this.inviteInfo = data.invite_info;
            this.hasInvite = data.has_invite;
        }
    }
    mvc.BgCharmRankModel = BgCharmRankModel;
})(mvc || (mvc = {}));

