(function (mvc) {
    class SysBgCharmRank extends ui.view.bgActivity2.sys_charmRankUI {
        initView() {
            this._model = mvc.bgCharmRankModel;
            this._ctrl = mvc.bgCharmRankCtrl;
        }
        initSendMsg() {
            mvc.rankCtrl.reqRankInfo(mvc.RankConst.RANK_TYPE.bg_charm_rank);
            let vo = mvc.activityModel.openActivityVo.get(mvc.FUNC_ID.BG_ACT_CHARM_RANK);
            if (vo && vo.state == mvc.ActivityConst.STATE.NORMAL) {
                this._ctrl.reqGiverTips(mvc.BgCharmRankConst.BgCharmRankType.BgCharmRank);
            }
        }
        initModelEvent() {
            this.bindModelEvent(mvc.rankModel, mvc.RankConst.EVT.UPDATE_RANK_INFO, this._updateView);
            this.bindModelEvent(this._model, mvc.BgCharmRankConst.EVT.UPDATE_GIVE_SUCC, this._onGiveSucc);
            this.bindModelEvent(mvc.activityModel, mvc.ActivityConst.EVT.CHANGE_ICON, this._updateState);
        }
        initCtrlEvent() {
            this.list.vScrollBarSkin = "";
            this.btnGift.on(Laya.Event.CLICK, this, this._onBtnGift);
            this.btnGet.on(Laya.Event.CLICK, this, this._onBtnGet);
            this.btnShare.on(Laya.Event.CLICK, this, this._onBtnShare);
            for (let i = 0; i < 6; i++) {
                let head = this["imgHead" + i];
                head.on(Laya.Event.CLICK, this, this._onHeadClick, [Number(head.name)]);
            }
            this.redTips.id = mvc.REDOT_ID.BG_ACT_CHARM_RANK_ITEM;
            this.redShare.id = mvc.REDOT_ID.BG_ACT_CHARM_RANK_SHARE;
        }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            this._updateTime();
            this._updateState();
        }
        onDisable() {
            super.onDisable();
        }
        _onGiveSucc() {
            mvc.rankCtrl.reqRankInfo(mvc.RankConst.RANK_TYPE.bg_charm_rank);
        }
        _updateView(type, rankInfo) {
            if (type != mvc.RankConst.RANK_TYPE.bg_charm_rank) {
                return;
            }
            let vos = [];
            for (let data of rankInfo.getRankItemVos()) {
                let vo = new mvc.BgCharmRankRankVo();
                vo.init(data);
                vos.push(vo);
            }
            this.list.array = vos;
            this.lblEmpty.visible = false;
            let myRank = new mvc.BgCharmRankRankVo();
            myRank.initMyRank(rankInfo);
            this.unitMy.dataSource = myRank;
        }
        _updateTime() {
            this.stopTimer(this._actTimer);
            this.repeats(1000, this._actTimer, true);
        }
        _actTimer() {
            let vo = mvc.activityModel.openActivityVo.get(mvc.FUNC_ID.BG_ACT_CHARM_RANK);
            let t;
            if (!vo || (t = vo.getTime()) <= 0) {
                this.stopTimer(this._actTimer);
                this.lblTime.text = sg.translate("活动已结束");
                return;
            }
            let timeStr = sg.time.formatTimeStrT("F10", t);
            let stateStr = vo.state == mvc.ActivityConst.STATE.NORMAL ? sg.translate("活动时间: ") : sg.translate("展示时间: ");
            this.lblTime.text = `${stateStr}${timeStr}` + sg.translate("后结束");
        }
        _updateState() {
            let vo = mvc.activityModel.openActivityVo.get(mvc.FUNC_ID.BG_ACT_CHARM_RANK);
            let isShowBtn = vo && vo.state == mvc.ActivityConst.STATE.NORMAL;
            this.btnGet.visible = isShowBtn;
            this.btnGift.visible = isShowBtn;
            this.btnShare.visible = isShowBtn;
        }
        _onBtnGift() {
            sg.uimgr.showUI("pop_bgCharmRankHandsel");
        }
        _onBtnGet() {
            sg.uimgr.showUI("pop_bgCharmRankFlowerGet");
        }
        _onBtnShare() {
            sg.uimgr.showUI("pop_bgCharmRankShare");
        }
        _onHeadClick(id) {
            sg.uimgr.showUI("pop_itemTips", id);
        }
    }
    mvc.SysBgCharmRank = SysBgCharmRank;
})(mvc || (mvc = {}));

