(function (mvc) {
    let EVT = mvc.BgCharmRankConst.EVT;
    let BgCharmShareType = mvc.BgCharmRankConst.BgCharmShareType;
    class BgCharmRankCtrl extends sg.CtrlBase {
        constructor() {
            super(...arguments);
            this._inviteTryCount = 0;
        }
        initCtrl() {
            this._model = mvc.bgCharmRankModel;
        }
        registerMsg() {
            this.onMsg(Proto.BG_LURE_SEND_FLOWER, this._onMsgHandsel);
            this.onMsg(Proto.BG_LURE_TIME_GIVERS, this._onMsgGiverTips);
            this.onMsg(Proto.BG_LURE_INFO, this._onMsgGiverInfo);
            this.onMsg(Proto.BG_LURE_SEARCH_INFO, this._onMsgSearchPlayer);
            this.onMsg(Proto.BG_LURE_INIT_INFO, this._onMsgCfgInfo);
            this.onMsg(Proto.BG_LURE_GUILD_MEMBER_LIST, this._onMsgGuildRank);
            this.onMsg(Proto.BG_LURE_CHARGE_EXTRA_REWARD, this._onMsgChargeReward);
            this.onMsg(Proto.BG_LURE_PET_YY_EXTRA_REWARD, this._onMsgEggReward);
            this.onMsg(Proto.BG_LURE_SOME_TIMES_INFO, this._onMsgTimeInfo);
            this.onMsg(Proto.BG_INVITE_INFO, this._onMsgInviInfo);
            this.onMsg(Proto.BG_INVITE_INIT_INFO, this._onMsgInviInitInfo);
            this.onMsg(Proto.BG_INVITE_RECEIVE, this._onMsgInviReceive);
        }
        reqCfgInfo(type) {
            let req = this.createProto(Proto.bg_lure_init_info_request);
            req.type = type;
            this.sendMsg(Proto.BG_LURE_INIT_INFO, req);
        }
        _onMsgCfgInfo(data) {
            this._model.cfgInfo = this.markProtoNotRecycle(data);
            data.lure_data.reverse();
            this._model.giveNum = data.send_flower_num;
            this._model.limitEgg = data.pet_egg_drop_day_limit;
            this._model.limitTreasure = data.yy_drop_day_limit;
            this._model.limitRechange = data.charge_reward_day_limit;
            mgr.redotMgr.check(mvc.REDOT_ID.BG_ACT_CHARM_RANK_ITEM);
        }
        reqGuildRank(type) {
            let req = this.createProto(Proto.bg_lure_guild_member_list_request);
            req.type = type;
            this.sendMsg(Proto.BG_LURE_GUILD_MEMBER_LIST, req);
        }
        _onMsgGuildRank(data) {
            let vos = [];
            data.member_list.sort((a, b) => {
                if (a.position != b.position) {
                    return a.position - b.position;
                }
                return b.level - a.level;
            });
            for (let mem of data.member_list) {
                let vo = new mvc.BgCharmRankPlayerVo();
                vo.initGuild(mem);
                vos.push(vo);
            }
            this._model.fireEvent(EVT.UPDATE_GUILD_RANK, vos);
        }
        reqSearchPlayer(type, pid) {
            let req = this.createProto(Proto.bg_lure_search_info_request);
            req.type = type;
            req.player_id = pid;
            this.sendMsg(Proto.BG_LURE_SEARCH_INFO, req);
        }
        _onMsgSearchPlayer(data) {
            let vo = new mvc.BgCharmRankPlayerVo();
            vo.initSearch(data);
            this._model.fireEvent(EVT.UPDATE_SEARCH_INFO, vo);
            sg.uimgr.showNotice(sg.translate("搜索成功"), "green");
        }
        reqHandsel(actType, pid, itemId, num) {
            let req = this.createProto(Proto.bg_lure_send_flower_request);
            req.type = actType;
            req.item_id = itemId;
            req.item_num = num;
            req.player_id = pid;
            this.sendMsg(Proto.BG_LURE_SEND_FLOWER, req);
        }
        _onMsgHandsel(data) {
            this._model.giveNum = data.send_flower_num;
            if (data.reward && data.reward.length > 0) {
                mvc.PopItemEffect.showEff(data.reward, null, new Laya.Point(Laya.stage.width / 2, Laya.stage.height / 2 + 200));
            }
            else {
                sg.uimgr.showNotice(sg.translate("赠送成功"), "green");
            }
            this._model.fireEvent(EVT.UPDATE_GIVE_SUCC, data.player_id, data.lure_value);
        }
        reqGiverInfo(type, pid) {
            let req = this.createProto(Proto.bg_lure_info_request);
            req.type = type;
            req.player_id = pid;
            this.sendMsg(Proto.BG_LURE_INFO, req);
        }
        _onMsgGiverInfo(data) {
            this._model.fireEvent(EVT.UPDATE_GIVER_INFO, data);
        }
        reqGiverTips(type) {
            let req = this.createProto(Proto.bg_lure_time_givers_request);
            req.type = type;
            this.sendMsg(Proto.BG_LURE_TIME_GIVERS, req);
        }
        _onMsgGiverTips(data) {
            if (data.time_givers.length > 0) {
                let vos = [];
                for (let d of data.time_givers) {
                    let vo = new mvc.BgCharmRankPlayerVo();
                    vo.init(d);
                    vos.push(vo);
                }
                sg.uimgr.showUI("pop_bgCharmRankTips", vos);
            }
        }
        _onMsgChargeReward(data) {
            sg.uimgr.showUI("pop_getReward", sg.translate("仙宫庆典专属奖励"), data.reward);
        }
        _onMsgEggReward(data) {
            if (mvc.mainModel.isInGame())
                this._model.showReward(data.reward);
            else {
                this._model.cacheReward = data.reward;
            }
        }
        reqTimeInfo(type) {
            let req = this.createProto(Proto.bg_lure_some_times_info_request);
            req.type = type;
            this.sendMsg(Proto.BG_LURE_SOME_TIMES_INFO, req);
        }
        _onMsgTimeInfo(data) {
            this._model.fireEvent(EVT.TIME_INFO, data);
        }
        reqInviInfo() {
            let req = this.createProto(Proto.bg_invite_info_request);
            req.type = BgCharmShareType;
            this.sendMsg(Proto.BG_INVITE_INFO, req);
        }
        _onMsgInviInfo(data) {
            if (data.type != BgCharmShareType)
                return;
            this._model.shareInfo = data.received;
            mgr.redotMgr.check(mvc.REDOT_ID.BG_ACT_CHARM_RANK_SHARE);
        }
        reqInviInitInfo() {
            let req = this.createProto(Proto.bg_invite_init_info_request);
            req.type = BgCharmShareType;
            this.sendMsg(Proto.BG_INVITE_INIT_INFO, req);
        }
        _onMsgInviInitInfo(data) {
            if (data.type != BgCharmShareType)
                return;
            this._model.day_share_limit = data.day_share_limit;
        }
        reqInviReceive(id) {
            let req = this.createProto(Proto.bg_invite_receive_request);
            req.type = BgCharmShareType;
            req.player_id = id;
            this.sendMsg(Proto.BG_INVITE_RECEIVE, req);
        }
        _onMsgInviReceive(data) {
            if (data.type != BgCharmShareType)
                return;
            this._model.shareInfo = data.received;
            this._model.fireEvent(EVT.UPDATE_SHARE_INFO, data);
            sg.uimgr.showUI("pop_getReward", sg.translate("领取成功"), data.reward);
            mgr.redotMgr.check(mvc.REDOT_ID.BG_ACT_CHARM_RANK_SHARE);
        }
        getInviteCode() {
            let gVo = mgr.gplatform.gVo;
            let phpVo = mgr.gplatform.accountPhpVo;
            let gameVo = mgr.gplatform.accountGameVo;
            let sdkParams = mgr.gplatform.sdkParams;
            mgr.gplatform.sdkParams.php_invite_sign = "k0QvzBECQMZ1bKcA5WBuMz8fRm2u3DOV";
            let info = {};
            info["account"] = phpVo.account;
            info["player_id"] = gameVo.playerId;
            info["agent_id"] = gVo.agentId;
            if (gVo.sourceFrom && gVo.sourceFrom != "")
                info["source"] = gVo.sourceFrom;
            info["key"] = sdkParams.php_invite_sign;
            info["type"] = mvc.INVITE_CODE.ACT_COMMON;
            info["act_type"] = mvc.INVITE_ACTIVITY_TYPE.CHARM;
            let sign = mgr.toolsMgr.getSign(info, false);
            delete info["key"];
            window["MyGame"].openLog && mgr.gplatform.log("getInviteCode", info);
            sign = mgr.toolsMgr.toMd5(sign);
            info["sign"] = sign;
            mvc.netCtrl.connectHttpByType(mvc.PHPInterface.INVITE_CODE, info, this._onGetInviteCode.bind(this), this._onGetInviteCodeError.bind(this));
        }
        _onGetInviteCode(data) {
            this._inviteTryCount = 0;
            sg.Logger.openLog && sg.logm("charmInvite", "_onGetInviteCode", data);
            this._model.setInviteCode(data);
        }
        _onGetInviteCodeError() {
            this._inviteTryCount++;
            if (this._inviteTryCount > 3)
                return;
            this.getInviteCode();
        }
        useInviteCode(code) {
            let gVo = mgr.gplatform.gVo;
            let phpVo = mgr.gplatform.accountPhpVo;
            let gameVo = mgr.gplatform.accountGameVo;
            let sdkParams = mgr.gplatform.sdkParams;
            let info = {};
            info["agent_id"] = gVo.agentId;
            info["account"] = phpVo.account;
            info["server_id"] = gameVo.serverId;
            info["player_id"] = gameVo.playerId;
            info["key"] = sdkParams.php_invite_sign;
            info["invite_code"] = code;
            info["act_type"] = mvc.INVITE_ACTIVITY_TYPE.CHARM;
            let sign = mgr.toolsMgr.getSign(info, false);
            delete info["key"];
            window["MyGame"].openLog && mgr.gplatform.log("sendInvitedInfo", info);
            sign = mgr.toolsMgr.toMd5(sign);
            info["sign"] = sign;
            mvc.netCtrl.connectHttpByType(mvc.PHPInterface.COMMON_ACT_REWARD, info, this._onUseInviteCode.bind(this), this._onUseInviteCodeError.bind(this));
        }
        _onUseInviteCode(data) {
            sg.Logger.openLog && sg.logm("charmInvite", "_onUseInviteCode", data);
            if (data.code == 1) {
                this._model.hasInvite = true;
                this._model.inviteInfo = data.invite_info;
                this._model.fireEvent(mvc.BgCharmRankConst.EVT.UPDATE_CODE_VIEW);
            }
            else {
                let tip = "";
                if (data.code == -1) {
                    tip = sg.translate("邀请码错误");
                }
                else if (data.code == 0) {
                    tip = sg.translate("已被邀请，不可重复操作");
                }
                else if (data.code == -3) {
                    tip = sg.translate("不可将自己作为邀请人");
                }
                sg.uimgr.showNotice(tip);
            }
        }
        _onUseInviteCodeError(data) {
            sg.Logger.openLog && sg.logm("charmInvite", "_onUseInviteCodeError", data);
            sg.uimgr.showNotice(sg.translate("出现异常错误，请稍后重试"));
        }
    }
    mvc.BgCharmRankCtrl = BgCharmRankCtrl;
})(mvc || (mvc = {}));

