(function (mvc) {
    var BgActTaskComConst;
    (function (BgActTaskComConst) {
        BgActTaskComConst.EVT = {
            UPDATE_VIEW: 'UPDATE_VIEW',
            UPDATE_BOX: 'UPDATE_BOX',
            UPDATE_TASK: 'UPDATE_TASK',
        };
        let BgActTaskType;
        (function (BgActTaskType) {
            BgActTaskType[BgActTaskType["TASK_ANN"] = 10050] = "TASK_ANN";
        })(BgActTaskType = BgActTaskComConst.BgActTaskType || (BgActTaskComConst.BgActTaskType = {}));
    })(BgActTaskComConst = mvc.BgActTaskComConst || (mvc.BgActTaskComConst = {}));
})(mvc || (mvc = {}));

var mvc;
(function (mvc) {
    class BgActTaskComVo extends sg.VoBase {
        constructor() {
            super(...arguments);
            this.haveReward = false;
            this._isInit = false;
        }
        isActOpen() {
            let activity = mvc.activityModel.openActivityVo.get(this.funId);
            if (activity && this._isInit) {
                return (activity.end_time - sg.time.getSecondTime()) > 0;
            }
            else {
                return false;
            }
        }
        ;
        setBgTaskInfo(data) {
            this.type = data.type;
            this.phase = data.phase;
            this.accepted = data.accepted;
            this.finished = data.finished;
            this.integral = data.integral;
            this.reward = data.reward;
            this._isInit = true;
            this.funId = mvc.bgActTaskComModel.getFunIdByActType(data.type);
            this.taskList = [];
            let cfg = sg.dbmgr.getArray("backgroundActive_activeTask", { round: this.phase });
            for (let i = 0, len = cfg.length; i < len; i++) {
                let info = cfg[i];
                if (info.firstTask == 1) {
                    if (this.finished.indexOf(info.id) == -1) {
                        this.taskList.push(info);
                    }
                    else {
                        this.taskList.push(this._getNextTask(info));
                    }
                }
            }
            this.boxList = [];
            let boxCfg = sg.dbmgr.getArray("backgroundActive_pointsReward", { round: this.phase });
            this.boxList = boxCfg;
            this.updateRewardState();
        }
        updateTaskListById(id) {
            for (let i = 0, len = this.taskList.length; i < len; i++) {
                let task = this.taskList[i];
                if (task.id == id) {
                    this.taskList[i] = this._getNextTask(task);
                    break;
                }
            }
        }
        _getNextTask(data) {
            let info = null;
            if (data.nextTask && this.finished.indexOf(data.id) != -1) {
                info = this._getNextTask(sg.dbmgr.get("backgroundActive_activeTask", data.nextTask));
            }
            else {
                info = data;
            }
            return info;
        }
        submitTask(data) {
            this.integral = data.integral;
            this.finished.push(data.id);
            let tip = sg.dbmgr.get("funcOpen", this.funId);
            sg.uimgr.showUI("pop_getReward", tip.name, data.reward);
            this.updateTaskListById(data.id);
            this.updateRewardState();
        }
        getBoxReward(data) {
            this.reward.push(data.id);
            let cfg = sg.dbmgr.get("backgroundActive_pointsReward", data.id);
            let tip = sg.dbmgr.get("funcOpen", this.funId);
            sg.uimgr.showUI("pop_getReward", tip.name, cfg.reward);
            this.updateRewardState();
        }
        updateTaskPro(data) {
            if (!this.accepted) {
                return;
            }
            for (let i = 0, len = this.accepted.length; i < len; i++) {
                let task = this.accepted[i];
                if (task.id == data.task.id) {
                    this.accepted[i] = data.task;
                    break;
                }
            }
            this.updateRewardState();
        }
        getTaskProById(id) {
            let pro = 0;
            if (this.finished.indexOf(id) != -1) {
                let cfg = sg.dbmgr.get("backgroundActive_activeTask", id);
                pro = cfg.condition[1];
            }
            else {
                for (let i = 0, len = this.accepted.length; i < len; i++) {
                    let task = this.accepted[i];
                    if (task.id == id) {
                        pro = task.progress;
                        break;
                    }
                }
            }
            return pro;
        }
        getTaskStateById(id) {
            let complete_id = this.finished;
            let isComplete = false;
            for (let i = 0; i < complete_id.length; i++) {
                if (id == complete_id[i]) {
                    isComplete = true;
                    break;
                }
            }
            return isComplete;
        }
        updateRewardState() {
            if (this.taskList && this.taskList.length) {
                for (let i = 0, len = this.taskList.length; i < len; i++) {
                    let task = this.taskList[i];
                    let pro = this.getTaskProById(task.id);
                    let maxPro = task.condition[1];
                    if (pro >= maxPro && this.finished.indexOf(task.id) == -1) {
                        this.haveReward = true;
                        return;
                    }
                }
            }
            if (this.boxList && this.boxList.length) {
                for (let i = 0, len = this.boxList.length; i < len; i++) {
                    let boxInfo = this.boxList[i];
                    let point = boxInfo.point;
                    if (this.integral >= point && this.reward.indexOf(boxInfo.id) == -1) {
                        this.haveReward = true;
                        return;
                    }
                }
            }
            this.haveReward = false;
        }
        sortTaskList() {
            this.taskList.sort((a, b) => {
                let isFinishA = this.getTaskStateById(a.id);
                let isFinishB = this.getTaskStateById(b.id);
                if (isFinishA && isFinishB) {
                    return a.id - b.id;
                }
                else if (!isFinishA && !isFinishB) {
                    let progA = this.getTaskProById(a.id);
                    let progB = this.getTaskProById(b.id);
                    let targetA = a.condition[1];
                    let targetB = b.condition[1];
                    let valueA = Math.min(progA, targetA) / targetA;
                    let valueB = Math.min(progB, targetB) / targetB;
                    if (valueA > valueB)
                        return -1;
                    else if (valueA == valueB)
                        return a.id - b.id;
                    return 1;
                }
                return isFinishA ? 1 : -1;
            });
        }
        checkTaskRed() {
            return (this.isActOpen() && mgr.conditionMgr.checkFunc(this.funId, false) && this.haveReward) ? 1 : 0;
        }
    }
    mvc.BgActTaskComVo = BgActTaskComVo;
})(mvc || (mvc = {}));

var mvc;
(function (mvc) {
    class BgActTaskComModel extends sg.ModelBase {
        initModel() {
            this.taskInfoMap = {};
        }
        registerEvents() {
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.BG_ACT_ANN_TASK, this._checkTaskRed.bind(this, mvc.BgActTaskComConst.BgActTaskType.TASK_ANN), this);
        }
        getFunIdByActType(type) {
            switch (type) {
                case mvc.BgActTaskComConst.BgActTaskType.TASK_ANN:
                    return mvc.FUNC_ID.BG_ANN_TASK;
            }
        }
        getActTypeByFunId(funcId) {
            switch (funcId) {
                case mvc.FUNC_ID.BG_ANN_TASK:
                    return mvc.BgActTaskComConst.BgActTaskType.TASK_ANN;
            }
        }
        onMsgBgTaskInfo(data) {
            if (!this.getFunIdByActType(data.type))
                return;
            let vo = this.taskInfoMap[data.type];
            if (!vo) {
                vo = new mvc.BgActTaskComVo();
                this.taskInfoMap[data.type] = vo;
            }
            vo.setBgTaskInfo(data);
            mgr.redotMgr.check(mvc.REDOT_ID.BG_ACT_ANN_TASK);
        }
        onMsgBgTaskSubmit(data) {
            let vo = this.taskInfoMap[data.type];
            if (!vo)
                return;
            vo.submitTask(data);
            mgr.redotMgr.check(mvc.REDOT_ID.BG_ACT_ANN_TASK);
            this.fireEvent(mvc.BgActTaskComConst.EVT.UPDATE_VIEW);
        }
        onMsgBgTaskReward(data) {
            let vo = this.taskInfoMap[data.type];
            if (!vo)
                return;
            vo.getBoxReward(data);
            mgr.redotMgr.check(mvc.REDOT_ID.BG_ACT_ANN_TASK);
            this.fireEvent(mvc.BgActTaskComConst.EVT.UPDATE_BOX);
        }
        onMsgBgTaskProgress(data) {
            let vo = this.taskInfoMap[data.type];
            if (!vo)
                return;
            vo.updateTaskPro(data);
            mgr.redotMgr.check(mvc.REDOT_ID.BG_ACT_ANN_TASK);
            this.fireEvent(mvc.BgActTaskComConst.EVT.UPDATE_TASK);
        }
        _checkTaskRed(type) {
            let vo = this.taskInfoMap[type];
            if (!vo)
                return 0;
            return vo.haveReward ? 1 : 0;
        }
    }
    mvc.BgActTaskComModel = BgActTaskComModel;
})(mvc || (mvc = {}));

var mvc;
(function (mvc) {
    class PopBgActTaskComView extends ui.view.bgActivity9.pop_znqTaskUI {
        initView(funcId) {
            this._model = mvc.bgActTaskComModel;
            let type = this._model.getActTypeByFunId(funcId);
            this._vo = this._model.taskInfoMap[type];
            this._funId = funcId;
            let cfg = sg.dbmgr.getDB("backgroundActive_pointsReward", true);
            this._boxMaxPoint = cfg[cfg.length - 1].point;
        }
        initSendMsg() {
        }
        initModelEvent() {
            this.bindModelEvent(this._model, mvc.BgActTaskComConst.EVT.UPDATE_VIEW, this._updateView);
            this.bindModelEvent(this._model, mvc.BgActTaskComConst.EVT.UPDATE_BOX, this._updateBox);
            this.bindModelEvent(this._model, mvc.BgActTaskComConst.EVT.UPDATE_TASK, this._updateTask);
        }
        initCtrlEvent() {
            this.taskList.vScrollBarSkin = "";
            this.taskList.itemRender = mvc.UnitBgActTaskComItem;
            this.taskList.renderHandler = this.createHandler(this, this._onTaskList, null, false);
            this.boxList.renderHandler = this.createHandler(this, this._onBoxList, null, false);
        }
        onJumpInit(param) {
            this.initView(param.funId);
            this.onEnable();
        }
        onEnable() {
            super.onEnable();
            this._endTime = 0;
            if (this._vo == null || this._vo.isActOpen() == false) {
                return;
            }
            this._updateView();
            if (mvc.activityModel.openActivityVo.get(this._funId)) {
                this._endTime = mvc.activityModel.openActivityVo.get(this._funId).end_time;
            }
            let time = this._endTime - sg.time.getSecondTime();
            if (time < 0)
                time = 0;
            let v1 = sg.time.formatTimeStrT("F9", time);
            this.lblTime.text = StringEx.format(sg.translate("活动时间：${v1}后结束"), {"v1":v1});
            this._updateTime();
        }
        onDisable() {
            super.onDisable();
            this.stopTimer(this._onTimer);
        }
        _onTaskList(cell, idx) {
            let data = cell.dataSource;
            if (!data)
                return;
            cell.initView(data, this._vo);
        }
        _onBoxList(cell, idx) {
            let data = cell.dataSource;
            if (!data)
                return;
            let clipLight = cell.getChildByName("clipLight");
            let clipBox = cell.getChildByName("clipBox");
            let lblIntegral = cell.getChildByName("lblIntegral");
            let boxRedot = cell.getChildByName("boxRedot");
            let proIntegral = cell.getChildByName("proIntegral");
            boxRedot.visible = false;
            clipLight.visible = false;
            clipBox.index = 1;
            clipBox.offAll(Laya.Event.CLICK);
            let point = data.point;
            let curPoint = Math.min(this._vo.integral, this._boxMaxPoint);
            let lastPoint = data.lastPoint;
            let canGet = false;
            lblIntegral.text = point + "";
            if (curPoint >= point) {
                proIntegral.value = 1;
                if (this._vo.reward.indexOf(data.id) == -1) {
                    boxRedot.visible = true;
                    clipLight.visible = true;
                    canGet = true;
                }
                else {
                    clipBox.index = 0;
                }
            }
            else {
                proIntegral.value = curPoint <= lastPoint ? 0 : (curPoint - lastPoint) / (point - lastPoint);
            }
            clipBox.on(Laya.Event.CLICK, this, this._onBoxClick, [data, canGet]);
        }
        _updateView() {
            this._updateTask();
            this._updateBox();
        }
        _updateBox() {
            this.lblAllIntergral.value = this._vo.integral + "";
            this.boxList.array = this._vo.boxList;
        }
        _updateTask() {
            this._vo.sortTaskList();
            this.taskList.array = this._vo.taskList;
        }
        _updateTime() {
            this.repeats(1000, this._onTimer, true);
        }
        _onTimer() {
            let time = this._endTime - sg.time.getSecondTime();
            if (time <= 0) {
                this.stopTimer(this._onTimer);
                time = 0;
            }
            let v1 = sg.time.formatTimeStrT("F9", time);
            this.lblTime.text = StringEx.format(sg.translate("活动时间：${v1}后结束"), {"v1":v1});
        }
        _onBoxClick(data, canGet) {
            if (!this._vo.isActOpen()) {
                sg.uimgr.showNotice(sg.translate("活动已结束"));
                return;
            }
            if (canGet) {
                mvc.bgActTaskComCtrl.reqBgTaskReward(data.id, this._vo.type);
            }
            else {
                sg.uimgr.showUI("pop_guildRewardPre", data.reward, sg.translate("积分好礼"));
            }
        }
    }
    mvc.PopBgActTaskComView = PopBgActTaskComView;
})(mvc || (mvc = {}));

