var mvc;
(function (mvc) {
    class BgBattlePassVo extends sg.VoBase {
        init(data) {
            this.type = data.type;
            this.level = data.level;
            this.exp = data.exp;
            this.is_unlock = data.is_unlock;
            this.skybook_infos = data.skybook_infos;
            this.round = data.round;
            this.accepted = data.accepted;
            this.finished = data.finished;
        }
        updateTaskPro(data) {
            if (!this.accepted) {
                return;
            }
            for (let i = 0, len = this.accepted.length; i < len; i++) {
                let task = this.accepted[i];
                if (task.id == data.progress.id) {
                    this.accepted[i] = data.progress;
                    break;
                }
            }
        }
        submitTask(data) {
            this.level = data.level;
            this.exp = data.exp;
            this.finished = data.finished;
        }
        getTaskProById(id) {
            let pro = 0;
            if (this.finished.indexOf(id) != -1) {
                let cfg = sg.dbmgr.get("backgroundActive_battlePassTask", id);
                pro = cfg.need[cfg.need.length - 1];
            }
            else {
                for (let i = 0, len = this.accepted.length; i < len; i++) {
                    let task = this.accepted[i];
                    if (task.id == id) {
                        pro = task.progress;
                        break;
                    }
                }
            }
            return pro;
        }
        getTaskStateById(id) {
            let complete_id = this.finished;
            let isComplete = false;
            for (let i = 0; i < complete_id.length; i++) {
                if (id == complete_id[i]) {
                    isComplete = true;
                    break;
                }
            }
            return isComplete;
        }
        sortTaskList(taskList) {
            taskList.sort((a, b) => {
                let isFinishA = this.getTaskStateById(a.id);
                let isFinishB = this.getTaskStateById(b.id);
                if (isFinishA && isFinishB) {
                    return a.id - b.id;
                }
                else if (!isFinishA && !isFinishB) {
                    let progA = this.getTaskProById(a.id);
                    let progB = this.getTaskProById(b.id);
                    let targetA = a.need[a.need.length - 1];
                    let targetB = b.need[b.need.length - 1];
                    let valueA = Math.min(progA, targetA) / targetA;
                    let valueB = Math.min(progB, targetB) / targetB;
                    if (valueA > valueB)
                        return -1;
                    else if (valueA == valueB)
                        return a.id - b.id;
                    return 1;
                }
                return isFinishA ? 1 : -1;
            });
        }
        getRewardInfoById(id) {
            if (!this.skybook_infos)
                return null;
            for (let i = 0, len = this.skybook_infos.length; i < len; i++) {
                let info = this.skybook_infos[i];
                if (info.id == id) {
                    return info;
                }
            }
            return null;
        }
    }
    mvc.BgBattlePassVo = BgBattlePassVo;
})(mvc || (mvc = {}));

var mvc;
(function (mvc) {
    let EVT = mvc.BgBattlePassConst.EVT;
    class BgBattlePassModel extends sg.ModelBase {
        initModel() {
            this.vo = new mvc.BgBattlePassVo();
        }
        registerEvents() {
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.BG_ACT_BATTLE_PASS_REWARD, this.checkRewardRed, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.BG_ACT_BATTLE_PASS_TASK, this.checkTaskRed, this);
        }
        setSkyBookInfo(data) {
            if (this.vo) {
                this.vo.init(data);
                this._curLv = this.vo.level;
                this.fireEvent(EVT.UPDATE_VIEW);
                mgr.redotMgr.check(mvc.REDOT_ID.BG_ACT_BATTLE_PASS_REWARD);
                mgr.redotMgr.check(mvc.REDOT_ID.BG_ACT_BATTLE_PASS_TASK);
            }
        }
        updateTaskPro(data) {
            if (this.vo) {
                this.vo.updateTaskPro(data);
                mgr.redotMgr.check(mvc.REDOT_ID.BG_ACT_BATTLE_PASS_TASK);
                this.fireEvent(EVT.UPDATE_TASK);
            }
        }
        submitTask(data) {
            if (this.vo) {
                this.vo.submitTask(data);
                if (this.vo.level > this._curLv)
                    this.fireEvent(EVT.PLAY_LVUP_ANI);
                this._curLv = this.vo.level;
                mvc.PopItemEffect.showEff([[141019, data.add_exp]], null, new Laya.Point(Laya.stage.width / 2, Laya.stage.height / 2));
                mgr.redotMgr.check(mvc.REDOT_ID.BG_ACT_BATTLE_PASS_REWARD);
                mgr.redotMgr.check(mvc.REDOT_ID.BG_ACT_BATTLE_PASS_TASK);
                this.fireEvent(EVT.UPDATE_VIEW);
            }
        }
        skyBookReward(data) {
            if (this.vo) {
                this.vo.skybook_infos = data.skybook_infos;
                sg.uimgr.showUI("pop_getReward", sg.translate("天书奥卷"), data.reward);
                mgr.redotMgr.check(mvc.REDOT_ID.BG_ACT_BATTLE_PASS_REWARD);
                this.fireEvent(EVT.UPDATE_REWARD);
            }
        }
        skyBookPay(data) {
            if (this.vo) {
                this.vo.skybook_infos = data.skybook_infos;
                sg.uimgr.showUI("pop_getReward", sg.translate("天书奥卷"), data.reward);
                mgr.redotMgr.check(mvc.REDOT_ID.BG_ACT_BATTLE_PASS_REWARD);
                this.fireEvent(EVT.UPDATE_GIFT);
            }
        }
        unlock(data) {
            if (this.vo) {
                this.vo.is_unlock = data.is_unlock;
                this.vo.level = data.level;
                this.vo.exp = data.exp;
                if (this.vo.level > this._curLv)
                    this.fireEvent(EVT.PLAY_LVUP_ANI);
                this._curLv = this.vo.level;
                sg.uimgr.showUI("pop_getReward", sg.translate("天书奥卷"), data.reward);
                mgr.redotMgr.check(mvc.REDOT_ID.BG_ACT_BATTLE_PASS_REWARD);
                this.fireEvent(EVT.UPDATE_VIEW);
            }
        }
        buyLevel(data) {
            let vo = this.vo;
            if (!vo) {
                return;
            }
            this._curLv = vo.level;
            vo.level = data.level;
            vo.exp = 0;
            if (vo.level > this._curLv)
                this.fireEvent(mvc.DeifyOrderConst.EVT.PLAY_LVUP_ANI);
            this.fireEvent(EVT.UPDATE_VIEW);
        }
        getCurIndex() {
            if (!this._rewardCfgs) {
                this._rewardCfgs = sg.dbmgr.getArray("backgroundActive_battlePassReward", { type: this.vo.round });
            }
            for (let i = 0, len = this._rewardCfgs.length; i < len; i++) {
                let reward = this._rewardCfgs[i];
                if (this.vo.level >= reward.level) {
                    let info = this.vo.getRewardInfoById(reward.id);
                    if (!info)
                        return i;
                    if (info.free_get_tims < 1 || (this.vo.is_unlock == 1 && info.bp_get_tims < 1))
                        return i;
                }
            }
            return this.vo.level - 1;
        }
        checkRewardRed() {
            if (!mgr.conditionMgr.checkFunc(mvc.FUNC_ID.BG_ACT_BATTLE_PASS, false))
                return 0;
            if (!this._rewardCfgs) {
                this._rewardCfgs = sg.dbmgr.getArray("backgroundActive_battlePassReward", { type: this.vo.round });
            }
            for (let i = 0, len = this._rewardCfgs.length; i < len; i++) {
                let reward = this._rewardCfgs[i];
                if (this.vo.level >= reward.level) {
                    let info = this.vo.getRewardInfoById(reward.id);
                    if (!info)
                        return 1;
                    if (info.free_get_tims < 1)
                        return 1;
                    if (this.vo.is_unlock == 1 && info.bp_get_tims < 1)
                        return 1;
                }
            }
            return 0;
        }
        checkTaskRed() {
            if (!mgr.conditionMgr.checkFunc(mvc.FUNC_ID.BG_ACT_BATTLE_PASS, false))
                return 0;
            if (!this._taskCfgs) {
                this._taskCfgs = sg.dbmgr.getArray("backgroundActive_battlePassTask", { type: this.vo.round });
            }
            for (let i = 0, len = this._taskCfgs.length; i < len; i++) {
                let task = this._taskCfgs[i];
                let pro = this.vo.getTaskProById(task.id);
                let maxPro = task.need[task.need.length - 1];
                if (pro >= maxPro && this.vo.finished.indexOf(task.id) == -1) {
                    return 1;
                }
            }
            return 0;
        }
        getBuyLevelOfReward(type, toLv) {
            let vo = this.vo;
            let items = [];
            if (vo) {
                let configs = sg.dbmgr.getArray("backgroundActive_battlePassReward", { type: this.vo.round });
                for (let i = 1; i <= toLv; i++) {
                    let cfg = configs[i - 1];
                    if (cfg) {
                        let info = vo.getRewardInfoById(cfg.id);
                        if (!info || info.free_get_tims < 1)
                            mvc.mainModel.addItemNumforArray(items, cfg.levelReward);
                        if (vo.is_unlock == 1 && (!info || info.bp_get_tims < 1))
                            mvc.mainModel.addItemNumforArray(items, cfg.bp);
                    }
                }
            }
            return items;
        }
        getCostNum(type, curLv, toLv) {
            let info = mgr.toolsMgr.getGlobalVoById("book_order_buy_level", 1);
            if (info) {
                let a0 = info[0] + curLv * info[1];
                let an = info[0] + (toLv - 1) * info[1];
                let costNum = (a0 + an) * (toLv - curLv) / 2;
                return costNum;
            }
            return 0;
        }
        getMaxLevel(type) {
            let vo = this.vo;
            if (vo) {
                let configs = sg.dbmgr.get("backgroundActive_bpType", this.vo.round);
                if (configs) {
                    return configs.maxLv;
                }
            }
            return 0;
        }
    }
    mvc.BgBattlePassModel = BgBattlePassModel;
})(mvc || (mvc = {}));

