(function (mvc) {
    class PopBgActivityTask extends ui.view.backgroundActivity.pop_taskUI {
        initView(...args) {
            this._model = mvc.bgActivityTaskModel;
            let cfg = sg.dbmgr.getArray("backgroundActive_pointsReward", { round: this._model.phase });
            this._boxMaxPoint = cfg[cfg.length - 1].point;
        }
        initModelEvent() {
            this.bindModelEvent(this._model, mvc.BgActivityTaskConst.EVT.UPDATE_VIEW, this._updateView);
            this.bindModelEvent(this._model, mvc.BgActivityTaskConst.EVT.UPDATE_BOX, this._updateBox);
            this.bindModelEvent(this._model, mvc.BgActivityTaskConst.EVT.UPDATE_TASK, this._updateTask);
        }
        initCtrlEvent() {
            this.taskList.vScrollBarSkin = "";
            this.taskList.renderHandler = this.createHandler(this, this._onTaskList, null, false);
            this.boxList.renderHandler = this.createHandler(this, this._onBoxList, null, false);
        }
        updateWhenNetReConn() {
            this._updateView();
        }
        onEnable() {
            super.onEnable();
            this._updateView();
            this._endTime = 0;
            if (mvc.activityModel.openActivityVo.get(mvc.FUNC_ID.BG_ACTIVITY_TASK)) {
                this._endTime = mvc.activityModel.openActivityVo.get(mvc.FUNC_ID.BG_ACTIVITY_TASK).end_time;
            }
            let time = this._endTime - sg.time.getSecondTime();
            if (time < 0)
                time = 0;
            let v1 = sg.time.formatTimeStrT("F9", time);
            this.lblTime.text = StringEx.format(sg.translate("活动时间：${v1}后结束"), {"v1":v1});
            this._updateTime();
        }
        onDisable() {
            super.onDisable();
            this.stopTimer(this._onTimer);
        }
        _onTaskList(cell, idx) {
            let data = cell.dataSource;
            if (!data)
                return;
            cell.initView(data);
        }
        _onBoxList(cell, idx) {
            let data = cell.dataSource;
            if (!data)
                return;
            let clipLight = cell.getChildByName("clipLight");
            let clipBox = cell.getChildByName("clipBox");
            let lblIntegral = cell.getChildByName("lblIntegral");
            let boxRedot = cell.getChildByName("boxRedot");
            let proIntegral = cell.getChildByName("proIntegral");
            boxRedot.visible = false;
            clipLight.visible = false;
            clipBox.index = 1;
            clipBox.offAll(Laya.Event.CLICK);
            let point = data.point;
            let curPoint = Math.min(this._model.integral, this._boxMaxPoint);
            let lastPoint = data.lastPoint;
            let canGet = false;
            lblIntegral.text = point + "";
            if (curPoint >= point) {
                proIntegral.value = 1;
                if (this._model.reward.indexOf(data.id) == -1) {
                    boxRedot.visible = true;
                    clipLight.visible = true;
                    canGet = true;
                }
                else {
                    clipBox.index = 0;
                }
            }
            else {
                proIntegral.value = curPoint <= lastPoint ? 0 : (curPoint - lastPoint) / (point - lastPoint);
            }
            clipBox.on(Laya.Event.CLICK, this, this._onBoxClick, [data, canGet]);
        }
        _updateView() {
            this._updateTask();
            this._updateBox();
        }
        _updateBox() {
            this.lblAllIntergral.value = this._model.integral + "";
            this.boxList.array = this._model.boxList;
        }
        _updateTask() {
            this._model.sortTaskList();
            this.taskList.array = this._model.taskList;
        }
        _updateTime() {
            this.repeats(1000, this._onTimer, true);
        }
        _onTimer() {
            let time = this._endTime - sg.time.getSecondTime();
            if (time <= 0) {
                this.stopTimer(this._onTimer);
                time = 0;
            }
            let v1 = sg.time.formatTimeStrT("F9", time);
            this.lblTime.text = StringEx.format(sg.translate("活动时间：${v1}后结束"), {"v1":v1});
        }
        _onBoxClick(data, canGet) {
            if (this._model.isPassAct) {
                sg.uimgr.showNotice(sg.translate("活动已结束"));
                return;
            }
            if (canGet) {
                mvc.bgActivityTaskCtrl.reqBgTaskReward(data.id, this._model.type);
            }
            else {
                sg.uimgr.showUI("pop_guildRewardPre", data.reward, sg.translate("积分豪礼"));
            }
        }
    }
    mvc.PopBgActivityTask = PopBgActivityTask;
})(mvc || (mvc = {}));

