            let maxPro = this._vo.condition[1];
            this.proTask.value = Math.min(1, pro / maxPro);
            this.lblPro.text = `${pro}/${maxPro}`;
            let vos = mvc.ItemVo.createItemVos(this._vo.rewards);
            this.viewReward.initView(vos[0]);
