(function (mvc) {
    class UnitBgMarketTaskItem extends ui.view.bgActivity.unit_bgTaskItemUI {
        onAwake() {
            super.onAwake();
            this.listReward.renderHandler = this.createHandler(this, this._listRender, undefined, false);
        }
        onEnable() {
            super.onEnable();
            this.btnRefresh.on(Laya.Event.CLICK, this, this._onBtnRefresh);
            this.btnGet.on(Laya.Event.CLICK, this, this._onBtnGet);
        }
        onDisable() {
            this.btnRefresh.off(Laya.Event.CLICK, this, this._onBtnRefresh);
            this.btnGet.off(Laya.Event.CLICK, this, this._onBtnGet);
            super.onDisable();
        }
        get dataSource() {
            return super.dataSource;
        }
        set dataSource(data) {
            super.dataSource = data;
            if (!data)
                return;
            this.lblName.text = data.cond;
            mgr.toolsMgr.setLabelByQua(data.quality, this.lblName);
            let cur = data.cur;
            let max = data.max;
            this.lblProg.text = `(${cur}/${max})`;
            this.listReward.array = data.rewards;
            if (data.isGet) {
                this.btnRefresh.visible = false;
                this.btnGet.disabled = true;
                this.btnGet.label = sg.translate("已领取");
                this.red.visible = false;
            }
            else {
                this.btnRefresh.visible = true;
                this.btnGet.disabled = data.cur < data.max;
                this.red.visible = data.cur >= data.max;
                this.btnGet.label = sg.translate("领取");
            }
        }
        _listRender(cell) {
            let data = cell.dataSource;
            if (!data)
                return;
            cell.initView(data, true);
        }
        _onBtnRefresh() {
            let data = this.dataSource;
            if (!data || data.isGet)
                return;
            let cost = mvc.bgMarketModel.initInfo.task_refresh_cost;
            let func = () => {
                if (mgr.toolsMgr.checkConsume([cost], true)) {
                    if (data.quality == 6) {
                        sg.uimgr.showConfirm({
                            content: sg.translate("您已刷新到最高品质的任务是否继续刷新？"),
                            btnCancelVisible: true,
                            enterFunc: () => {
                                mvc.bgMarketCtrl.reqRefreshTask(mvc.BgMarketConst.BgMarketType.BgMarket, data.id);
                            }
                        });
                    }
                    else {
                        mvc.bgMarketCtrl.reqRefreshTask(mvc.BgMarketConst.BgMarketType.BgMarket, data.id);
                    }
                }
            };
            if (!mvc.mainModel.getSacrificeTip(mvc.FirstTipsID.BG_MARKET_TASK)) {
                let name = mgr.toolsMgr.getNameById(cost[0]);
                let num = cost[1];
                let v1 = num;
                let v2 = name;
                sg.uimgr.showConfirm({
                    btnCancelVisible: true,
                    content: StringEx.format(sg.translate("是否消耗${v1}${v2}刷新任务？"), {"v1":v1,"v2":v2}),
                    sacrificeTipVisible: true,
                    sacrificeTipFunc: () => {
                        mvc.mainModel.showSacrificeTip = mvc.FirstTipsID.BG_MARKET_TASK;
                    },
                    enterFunc: func
                });
            }
            else {
                func();
            }
        }
        _onBtnGet() {
            let data = this.dataSource;
            if (!data || data.isGet)
                return;
            if (data.cur >= data.max) {
                mvc.bgMarketCtrl.reqGetTaskReward(mvc.BgMarketConst.BgMarketType.BgMarket, data.id);
            }
        }
    }
    mvc.UnitBgMarketTaskItem = UnitBgMarketTaskItem;
})(mvc || (mvc = {}));

