(function (mvc) {
    class BgStoreModel extends sg.ModelBase {
        initModel() {
            this.dataMap = new Map();
            this.itemMap = new Map();
        }
        registerEvents() {
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.BG_ACT_TASK, this.redTipsStore, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.BG_ACT_AUTUMN_STORE, this.redTipsAutuStore, this);
        }
        setBgStoreInfo(msg) {
            if (!msg)
                return;
            this.curType = msg.type;
            let item_id = [];
            for (let i = 0; i < msg.shop_data.length; i++) {
                item_id.push(msg.shop_data[i].item_id);
            }
            this.itemId = item_id;
            if (!this.itemMap.has(msg.type)) {
                this.itemMap.set(msg.type, item_id);
            }
            let arr = this.dataMap.get(msg.type);
            if (!arr) {
                this.dataMap.set(msg.type, new Map());
            }
            let itemList;
            let shopType;
            for (let i = 0; i < msg.shop_data.length; i++) {
                shopType = msg.shop_data[i].shop_type;
                let tempData = this.dataMap.get(msg.type) ? this.dataMap.get(msg.type).get(shopType) : null;
                if (!tempData) {
                    tempData = new mvc.BGTypeStoreVo();
                    tempData.shopName = msg.shop_data[i].shop_name;
                    tempData.shopType = msg.shop_data[i].shop_type;
                    tempData.item_list = [];
                    this.dataMap.get(msg.type).set(shopType, tempData);
                }
                itemList = msg.shop_data[i].item_list;
                let offseNum = tempData.item_list.length - itemList.length;
                if (offseNum > 0) {
                    tempData.item_list.splice(itemList.length, offseNum);
                }
                for (let i = 0; i < itemList.length; i++) {
                    let vo = tempData.item_list[i];
                    if (!vo) {
                        vo = new mvc.BgStoreVo();
                        tempData.item_list.push(vo);
                    }
                    vo.updateData(itemList[i], shopType);
                }
            }
            this.fireEvent(mvc.BgStoreConst.EVT.UPDATE_INFO);
            mgr.redotMgr.check(mvc.REDOT_ID.BG_ACT_TASK);
            mgr.redotMgr.check(mvc.REDOT_ID.BG_ACT_AUTUMN_STORE);
        }
        setCommodityBuy(msg) {
            if (msg) {
                let arr = this.dataMap.get(msg.type).get(msg.shop_type);
                let item;
                for (let i = 0; i < arr.item_list.length; i++) {
                    if (arr.item_list[i].id == msg.id) {
                        arr.item_list[i].bought_count = msg.bought_count;
                        item = arr.item_list[i];
                        break;
                    }
                }
                if (item) {
                    sg.uimgr.showUI("pop_getReward", sg.translate("购买成功"), [[item.shop_item[0][0], item.shop_item[0][1] * msg.num]]);
                }
                this.fireEvent(mvc.BgStoreConst.EVT.UPDATE_INFO);
                mgr.redotMgr.check(mvc.REDOT_ID.BG_ACT_TASK);
                mgr.redotMgr.check(mvc.REDOT_ID.BG_ACT_AUTUMN_STORE);
            }
        }
        redTipsStore() {
            if (!mgr.conditionMgr.checkFunc(mvc.FUNC_ID.BG_ACTIVITY_STORE, false))
                return 0;
            let vos = this.dataMap.get(mvc.BgStoreConst.BgStoreType.LIMIT_STORE);
            for (let key in vos) {
                let vo = vos[key];
                if (vo) {
                    for (let i = 0; i < vo.length; i++) {
                        let cost = vo[i].cost_item;
                        if (cost && mgr.toolsMgr.checkConsume(cost, false))
                            return 1;
                    }
                }
            }
            return 0;
        }
        redTipsStoreTwo() {
            if (!mgr.conditionMgr.checkFunc(mvc.FUNC_ID.BG_ACT_STORE_TWO, false))
                return 0;
            let vos = this.dataMap.get(mvc.BgStoreConst.BgStoreType.LIMIT_STORE_TWO);
            for (let key in vos) {
                let vo = vos[key];
                if (vo) {
                    for (let i = 0; i < vo.length; i++) {
                        let cost = vo[i].cost_item;
                        if (cost && mgr.toolsMgr.checkConsume(cost, false))
                            return 1;
                    }
                }
            }
            return 0;
        }
        redTipsMarketStore() {
            if (!mgr.conditionMgr.checkFunc(mvc.FUNC_ID.BG_ACT_TASK, false))
                return 0;
            let vos = this.dataMap.get(mvc.BgStoreConst.BgStoreType.LIMIT_STORE_TWO);
            for (let key in vos) {
                let vo = vos[key];
                if (vo) {
                    for (let i = 0; i < vo.length; i++) {
                        let cost = vo[i].cost_item;
                        if (cost && mgr.toolsMgr.checkConsume(cost, false))
                            return 1;
                    }
                }
            }
            return 0;
        }
        redTipsAutuStore() {
            return 0;
        }
    }
    mvc.BgStoreModel = BgStoreModel;
})(mvc || (mvc = {}));

