(function (mvc) {
    class PopRaceTask extends ui.view.bgActivity4.pop_dailyTask4UI {
        initView(...args) {
            this._model = mvc.bgRaceModel;
        }
        initModelEvent() {
            this.bindModelEvent(this._model, mvc.BgRaceConst.EVT.UPDATE_TASK_VIEW, this._updateView);
        }
        initCtrlEvent() {
            this.listTask.vScrollBarSkin = "";
            this.listTask.renderHandler = this.createHandler(this, this._onListTask, null, false);
        }
        onEnable() {
            super.onEnable();
            this.listTask.scrollBar.value = this.listTask.scrollBar.min;
            this._updateView();
        }
        updateWhenNetReConn() {
            this._updateView();
        }
        _updateView() {
            if (this._model.taskVo) {
                if (!this._cfg) {
                    let cfg = sg.dbmgr.getArray("backgroundActive_bgActive3Task", { activityType: this._model.taskVo.type });
                    this._cfg = cfg;
                }
                this.taskSort();
                this.listTask.array = this._cfg;
            }
        }
        taskSort() {
            this._cfg.sort((a, b) => {
                let isFinishA = this._model.getTaskStateById(a.id);
                let isFinishB = this._model.getTaskStateById(b.id);
                if (isFinishA && isFinishB) {
                    return a.id - b.id;
                }
                else if (!isFinishA && !isFinishB) {
                    let progA = this._model.getTaskProgById(a.id);
                    let progB = this._model.getTaskProgById(b.id);
                    let targetA = a.need[1];
                    let targetB = b.need[1];
                    let valueA = Math.min(progA, targetA) / targetA;
                    let valueB = Math.min(progB, targetB) / targetB;
                    if (valueA > valueB)
                        return -1;
                    else if (valueA == valueB)
                        return a.id - b.id;
                    return 1;
                }
                return isFinishA ? 1 : -1;
            });
        }
        _onListTask(cell, idx) {
            let data = cell.dataSource;
            if (!data)
                return;
            cell.initView(data);
        }
    }
    mvc.PopRaceTask = PopRaceTask;
})(mvc || (mvc = {}));

