(function (mvc) {
    class UnitWindow extends ui.view.bgActivity4.unit_windowUI {
        onEnable() {
            super.onEnable();
            this.lblTime.text = "00:00";
        }
        onDisable() {
            super.onDisable();
            this._startTime = this._endTime = null;
        }
        startMove(data, startTime, endTime) {
            this.cfg = data;
            this._startTime = startTime;
            this._endTime = endTime;
            this.repeats(1000, this._onTime, true);
        }
        updatePos(posArr, isStart = false) {
            let destination = mvc.bgRaceModel.raceVo.destination;
            let quickIndex = 0;
            let qucikY = 0;
            for (let i = 0; i < 5; i++) {
                this[`img${i + 1}`].y = 140 - (posArr[i] / destination) * 140 + 5;
                if (!qucikY) {
                    qucikY = this[`img${i + 1}`].y;
                    quickIndex = i;
                }
                else {
                    if (this[`img${i + 1}`].y < qucikY) {
                        qucikY = this[`img${i + 1}`].y;
                        quickIndex = i;
                    }
                }
            }
            if (this._endTime && sg.time.getTime() >= this._endTime) {
                let rank_infos = this.cfg.rank_infos;
                rank_infos.sort((a, b) => {
                    return a.rid - b.rid;
                });
                quickIndex = rank_infos[0].id - 1;
            }
            if (isStart)
                quickIndex = -1;
            for (let i = 0; i < 5; i++) {
                if (i == quickIndex) {
                    mgr.icon.drawTexture("ui/bgActivity4/img_ldg_jingdudian1.png", this[`img${i + 1}`]);
                }
                else {
                    mgr.icon.drawTexture("ui/bgActivity4/img_ldg_jingdudian2.png", this[`img${i + 1}`]);
                }
            }
        }
        _onTime() {
            let curTime = sg.time.getTime();
            if (curTime > this._endTime) {
                curTime = this._endTime;
                this.stopTimer(this._onTime);
            }
            let time = curTime - this._startTime;
            this.lblTime.text = sg.time.formatTimeStrT("F1", time / 1000);
        }
    }
    mvc.UnitWindow = UnitWindow;
})(mvc || (mvc = {}));

