var mvc;
(function (mvc) {
    class BloodVo extends sg.VoBase {
        constructor() {
            super(...arguments);
            this.idxToQuaList = [4, 5, 6];
        }
        updateData(info) {
            this.type = info.type;
            this.level = info.level;
            this.grade = info.grade;
            this.exp = info.exp;
            this.sec_attrs = info.sec_attrs;
        }
        getCfg() {
            let cfg = sg.dbmgr.getArray("blood_blood", { bloodLevel: this.level, type: this.type, grade: this.grade })[0];
            if (cfg)
                return cfg;
            return null;
        }
        getNextCfg() {
            let cfg = this.getCfg();
            if (cfg) {
                let id = cfg.next;
                if (id)
                    return sg.dbmgr.get("blood_blood", id);
            }
            return null;
        }
        getBloodProps() {
            let props = [];
            let cfg = sg.dbmgr.getArray("blood_blood", { bloodLevel: this.level, type: this.type, grade: this.grade })[0];
            if (cfg) {
                props = mvc.PropertyModel.prasePropByCfg(cfg.mainAttr);
            }
            let props2 = this.getBloodPropByPurify();
            props = mvc.PropertyModel.getMixPropertysMerge(props, props2, true);
            return props;
        }
        getBloodPropByPurify() {
            let props2 = [];
            for (let i = 0; i < this.sec_attrs.length; i++) {
                if (this.sec_attrs[i]) {
                    props2.push([this.sec_attrs[i].key, this.sec_attrs[i].value]);
                }
            }
            props2 = mvc.PropertyModel.prasePropByIds(props2);
            return props2;
        }
        updatePurifyProp(id, isLock) {
            for (let i = 0; i < this.sec_attrs.length; i++) {
                if (this.sec_attrs[i].key == id)
                    this.sec_attrs[i].is_lock = isLock;
            }
        }
        getPurifyInfoByPos(pos) {
            for (let i = 0; i < this.sec_attrs.length; i++) {
                if (this.sec_attrs[i].pos == pos)
                    return this.sec_attrs[i];
            }
            return null;
        }
        getLockNum() {
            let num = 0;
            for (let i = 0; i < this.sec_attrs.length; i++) {
                if (this.sec_attrs[i].is_lock == 1)
                    num += 1;
            }
            return num;
        }
        getUnLockSecProp() {
            let idx = sg.varmgr.getUserVar("blood_purify_set_qua");
            if (idx == undefined)
                idx = 0;
            let qua = this.idxToQuaList[idx];
            for (let i = 0; i < this.sec_attrs.length; i++) {
                if (this.sec_attrs[i].is_lock == 0) {
                    let cfg = sg.dbmgr.get("blood_secAttrGear", this.sec_attrs[i].gear);
                    if (cfg && cfg.gearQuality >= qua) {
                        return true;
                    }
                }
            }
            return false;
        }
    }
    mvc.BloodVo = BloodVo;
})(mvc || (mvc = {}));

var mvc;
(function (mvc) {
    class BloodModel extends sg.ModelBase {
        initModel() {
            this.bloodMap = {};
        }
        registerEvents() {
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.BLOOD, this.redTipsBloods, this);
        }
        setBloodInfos(msg) {
            this.bloodMap = this.setBloodMap(msg.beast_blood_infos);
            this.typeGradeing = msg.type_grade_ing;
            this.finishTime = msg.finish_time;
            this.adTime = msg.ad_time;
            this.canSeekhelp = msg.can_seek_help;
            this.fireEvent(mvc.BloodConst.EVT.UPDATE_INFO);
        }
        updateBloodInfo(msg) {
            this.typeGradeing = msg.type_grade_ing;
            this.finishTime = msg.finish_time;
            let vo = msg.beast_blood_info && this.bloodMap[msg.beast_blood_info.type];
            if (vo) {
                vo.updateData(msg.beast_blood_info);
            }
            this.fireEvent(mvc.BloodConst.EVT.UPDATE_INFO);
        }
        updateBlood(type, data) {
            let vo = this.bloodMap[type];
            if (vo) {
                if (typeof data.exp == "number")
                    vo.exp = data.exp;
                if (data.sec_attrs) {
                    vo.sec_attrs = data.sec_attrs;
                    let cost = mgr.toolsMgr.getGlobalVoById("quenching", 1);
                    if (!mgr.toolsMgr.checkConsume(cost, false, false))
                        mvc.rechargeLimitCtrl.reqRechargeTrigger(mvc.RechargeLimitConst.EventType.BLOOD);
                }
                if (data.grade)
                    vo.grade = data.grade;
                if (data.level)
                    vo.level = data.level;
                this.fireEvent(mvc.BloodConst.EVT.UPDATE_INFO);
            }
        }
        updateBloodPurifyProp(type, id, isLock) {
            let vo = this.bloodMap[type];
            if (vo) {
                vo.updatePurifyProp(id, isLock);
                this.fireEvent(mvc.BloodConst.EVT.UPDATE_INFO);
            }
        }
        isUpLevl(msg) {
            let vo = this.bloodMap[msg.type];
            let lastLv = vo.level;
            let lastExp = vo.exp;
            let exp = 0;
            if (msg.exp - lastExp > 0)
                exp = msg.exp - lastExp;
            else {
                let cfg = sg.dbmgr.getArray("blood_blood", { bloodLevel: lastLv, type: msg.type, grade: vo.grade })[0];
                if (cfg)
                    exp = cfg.exp - lastExp;
            }
            this.fireEvent(mvc.BloodConst.EVT.UPDATE_EXP, exp);
            if (lastLv < msg.level) {
                this.fireEvent(mvc.BloodConst.EVT.LEVEL_UP);
            }
            let cost = vo.getCfg().cost[0];
            if (!mgr.toolsMgr.checkConsume([cost], false, false))
                mvc.rechargeLimitCtrl.reqRechargeTrigger(mvc.RechargeLimitConst.EventType.MERITS);
        }
        bloodGradeUp(msg) {
            this.canSeekhelp = msg.can_seek_help;
            this.finishTime = msg.finish_time;
            this.typeGradeing = msg.type_grade_ing;
            this.fireEvent(mvc.BloodConst.EVT.UPDATE_INFO);
        }
        setBloodMap(infos) {
            let bloodMap = {};
            for (let i = 0; i < infos.length; i++) {
                let data = infos[i];
                let vo = bloodMap[data.type];
                if (!vo) {
                    vo = new mvc.BloodVo();
                }
                vo.updateData(data);
                bloodMap[data.type] = vo;
            }
            return bloodMap;
        }
        getAllPropInfos(map) {
            let props = [];
            if (map) {
                for (let key in map) {
                    let vo = map[key];
                    if (vo) {
                        props = mvc.PropertyModel.getMixPropertysMerge(props, vo.getBloodProps(), true);
                    }
                }
            }
            for (let i = props.length - 1; i >= 0; i--) {
                let cfg = props[i].getCfg();
                if (cfg) {
                    if (cfg.show_priority != 1 && props[i].value == 0) {
                        props.splice(i, 1);
                    }
                }
            }
            props.sort(function (a, b) {
                let cfg1 = a.getCfg();
                let cfg2 = b.getCfg();
                if (cfg1 && cfg2) {
                    if (cfg1.show_priority == cfg2.show_priority)
                        return a.id - b.id;
                    else
                        return cfg1.show_priority - cfg2.show_priority;
                }
                return a.id - b.id;
            });
            return props;
        }
        getPropByPriority(props, priority, b = false) {
            let arr = [];
            for (let i = 0; i < props.length; i++) {
                let cfg = props[i].getCfg();
                if (b) {
                    if (cfg.show_priority >= priority) {
                        arr.push(props[i]);
                    }
                }
                else {
                    if (cfg.show_priority == priority) {
                        arr.push(props[i]);
                    }
                }
            }
            return arr;
        }
        getBloodPurifyDatas(bloodType) {
            let arr = sg.dbmgr.getArray("blood_lock", { type: bloodType });
            arr.sort(function (a, b) {
                return a.article - b.article;
            });
            return arr;
        }
        showGradeSuccTips(grade, type) {
            let cfgs = this.getBloodPurifyDatas(type);
            let v1 = cfgs && cfgs[0] && cfgs[0].bloodName;
            let v2 = grade;
            let str = StringEx.format(sg.translate("恭喜${v1}升阶到${v2}阶"), {"v1":v1,"v2":v2});
            sg.uimgr.showUI("pop_getReward", "", [], false, str, null, "cg");
        }
        getUserVarByType(type) {
            let ty = parseInt(type);
            let obj = sg.varmgr.getUserVar("blood_purify_redTips_obj");
            if (!obj) {
                obj = {};
            }
            if (obj[ty])
                return obj[ty];
            else
                return false;
        }
        setUserVarByType(type) {
            let ty = parseInt(type);
            let obj = sg.varmgr.getUserVar("blood_purify_redTips_obj");
            if (!obj) {
                obj = {};
            }
            obj[ty] = true;
            sg.varmgr.setUserVar("blood_purify_redTips_obj", obj);
            mgr.redotMgr.check(mvc.REDOT_ID.BLOOD);
            this.fireEvent(mvc.BloodConst.EVT.UPDATE_PURIFY_RED);
        }
        getNeedLvToGrade(type) {
            let lv = 0;
            let bloodType = parseInt(type);
            let vo = this.bloodMap[bloodType];
            if (vo) {
                let cfgs = sg.dbmgr.getArray("blood_blood", { type: bloodType, grade: vo.grade });
                cfgs.sort(function (a, b) {
                    return a.bloodLevel - b.bloodLevel;
                });
                let cfg = cfgs[cfgs.length - 1];
                if (cfg) {
                    lv = cfg.bloodLevel - vo.level;
                }
            }
            return lv;
        }
        redTipsBloods() {
            if (!mgr.conditionMgr.checkFunc(mvc.FUNC_ID.BLOOD, false))
                return 0;
            for (let key in this.bloodMap) {
                if (this.redTipsBlood(key) == 1)
                    return 1;
            }
            return 0;
        }
        redTipsBlood(type) {
            let bloodVo = this.bloodMap[type];
            if (bloodVo) {
                let cfg = bloodVo.getCfg();
                if (cfg && cfg.cost && mgr.toolsMgr.checkConsume(cfg.cost, false) && bloodVo.getNextCfg()) {
                    return 1;
                }
                if (cfg && cfg.break && this.typeGradeing == 0)
                    return 1;
                if (!this.getUserVarByType(bloodVo.type) && bloodVo.sec_attrs.length > 0) {
                    return 1;
                }
            }
            return 0;
        }
    }
    mvc.BloodModel = BloodModel;
})(mvc || (mvc = {}));

