(function (mvc) {
    class BoxEventPresenter extends Laya.Box {
        constructor() {
            super(...arguments);
            this.isShowNow = true;
        }
        onEnable() {
            this.pr = this.getChildAt(0);
            this.divEvent = this.pr.getChildByName("divEvent");
            this.txtEventRound = this.pr.getChildByName("txtEventRound");
            this.lblNext = this.pr.getChildByName("lblNext");
            this.imgEventNow = this.pr.getChildByName("imgEventNow");
            this._strMap = new Map();
            this.divEvent.style.family = "SimHei";
            this.divEvent.style.color = "#323232";
            this.divEvent.style.fontSize = 22;
            this.divEvent.style.width = 360;
            this.divEvent.style.height = 52;
            this.divEvent.style.leading = 10;
            this.divEvent.style.align = "center";
            this.divEvent.style.valign = "middle";
            this.divEvent.style.wordWrap = true;
            this.divEvent.style.padding = [0, 10, 0, 0];
            this.divEvent.x = (this.pr.width - 360) / 2;
            this.divEvent.y = (this.pr.height - 52) / 2;
            this.pr.on(Laya.Event.CLICK, this, this._clickBox);
            this.lblNext.on(Laya.Event.CLICK, this, this._clickNext);
        }
        _clickBox(e) {
            e.stopPropagation();
        }
        _clickNext(e) {
            this.showEvent(!this.isShowNow);
        }
        onDisable() {
            this._strMap.clear();
            this.pr.off(Laya.Event.CLICK, this, this._clickBox);
            this.lblNext.off(Laya.Event.CLICK, this, this._clickNext);
            this.divEvent.innerHTML = "";
            Laya.loader.clearTextureRes("ui_langs/cn/ui/cardBattle/img_title_dqsj.png");
            Laya.loader.clearTextureRes("ui_langs/cn/ui/cardBattle/img_title_xcsj.png");
            this.imgEventNow.skin = null;
        }
        showEvent(isNow) {
            this.isShowNow = isNow;
            this.visible = true;
            this.lblNext.text = this.isShowNow ? sg.translate("下次事件") : sg.translate("当前事件");
            this.imgEventNow.skin = this.isShowNow ? "ui_langs/cn/ui/cardBattle/img_title_dqsj.png" : "ui_langs/cn/ui/cardBattle/img_title_xcsj.png";
            let event = isNow ? mvc.cardBattleModel.getNowEvent() : mvc.cardBattleModel.getNextEvent();
            let str = this.makeEventText(event);
            this.divEvent.innerHTML = str;
            let nowRound = mvc.cardBattleModel.getNowRound();
            let len = 3;
            if (isNow) {
                len = event.end_round - nowRound + 1;
            }
            else {
                len = event.end_round - event.begin_round + 1;
            }
            this.txtEventRound.text = sg.translate("（剩余") + len + sg.translate("回合）");
        }
        makeEventText(event) {
            let str = this._strMap.get(event.event_id);
            if (!str) {
                let eventMsg = sg.dbmgr.get("cardbattle_cardEvent", event.event_id);
                str = this.replaceTextWithArray(eventMsg.evenText, eventMsg.evenParm);
                str = `<span>${str}</span>`;
                this._strMap.set(event.event_id, str);
            }
            return str;
        }
        replaceTextWithArray(text, arr) {
            return text.replace(/\{(\d+):(\d+)\}/g, (match, p1, p2) => {
                let color = sg.dbmgr.get("color", Number(p2));
                let str = arr[Number(p1) - 1];
                return `<span style="color:${color.stringColor}">${str}</span>`;
            });
        }
        hideEvent() {
            this.visible = false;
        }
    }
    mvc.BoxEventPresenter = BoxEventPresenter;
})(mvc || (mvc = {}));

