            this._currency.x = 0;
            this._currency.y = 0;
            let num = mgr.toolsMgr.getGlobalVoById("card_battle_reward_daily", 1);
            this.lblCount.text = `${num - mvc.cardBattleModel.battleNum}/${num}`;
