(function (mvc) {
    class AliPayCtrl extends sg.CtrlBase {
        initCtrl() {
            this._model = mvc.aliPayModel;
        }
        registerMsg() {
            this.onMsg(Proto.ALIPAY_GIFT_INFO, this.onMsgAliPayGiftInfo);
            this.onMsg(Proto.ALIPAY_GIFT_REWARD, this.onMsgAliPayGiftReward);
            this.onMsg(Proto.ONE_GIFT_INFO, this._onMsgOneGiftInfo);
            this.onMsg(Proto.ONE_GIFT_REWARD, this._onMsgOneGiftReward);
        }
        getGiftInfo() {
            let msg = this.createProto(Proto.alipay_gift_info_request);
            this.sendMsg(Proto.ALIPAY_GIFT_INFO, msg);
        }
        onMsgAliPayGiftInfo(msg) {
            this._model.updateAliPayGiftInfo(msg);
        }
        getAliPayPoint() {
            let info = { token: this._model.token };
            mvc.netCtrl.connectHttpByType(mvc.PHPInterface.GET_ALIPAY_POINT, info, (data) => {
                if (data.code == 0) {
                    this._model.updateAliPayPoint(data.point);
                }
                else {
                    this._model.updateAliPayPoint(0);
                }
            }, (err) => {
                console.warn(err);
            });
        }
        buyAliPayGift(id) {
            mgr.gplatform.getAlipayAuthPointCode(this, (token) => {
                if (token) {
                    let info = { token: token, pid: mgr.gplatform.accountGameVo.playerId, gift_id: id, agent_id: mgr.gplatform.gVo.agentId, server_id: mgr.gplatform.accountGameVo.serverId };
                    mvc.netCtrl.connectHttpByType(mvc.PHPInterface.CHANGE_ALIPAY_POINT, info, (data) => {
                        if (data.code == 0) {
                            this._model.updateAliPayPoint(data.point);
                        }
                        else if (data.code == 3) {
                            sg.uimgr.showNotice(sg.translate("操作过于频繁,请稍后再试"));
                        }
                    }, (err) => {
                        console.warn(err);
                    });
                }
            });
        }
        onMsgAliPayGiftReward(msg) {
            sg.uimgr.showUI("pop_getReward", sg.translate("购买成功"), msg.reward);
            this._model.buyGift(msg.id, msg.count);
        }
        reqOneGiftInfo() {
            let req = this.createProto(Proto.one_gift_info_request);
            this.sendMsg(Proto.ONE_GIFT_INFO, req);
        }
        _onMsgOneGiftInfo(data) {
            mvc.aliPayModel.oneGiftIsBuy = data.is_buy;
            if (data.is_buy == 1)
                mvc.activityModel.removeActivityVo(mvc.FUNC_ID.ALI_ONE_GIFT, false);
        }
        _onMsgOneGiftReward(data) {
            mvc.aliPayModel.oneGiftIsBuy = data.is_buy;
            sg.uimgr.showUI("pop_getReward", sg.translate("充值奖励"), data.reward, false, "", Laya.Handler.create(this, () => {
                let vo = mvc.petModel.getNoHandelPet();
                let curPet = mvc.petModel.getCurPetByType(vo.type);
                sg.uimgr.showUI("pop_choicePet", curPet, vo);
            }));
            mvc.activityModel.removeActivityVo(mvc.FUNC_ID.ALI_ONE_GIFT, false);
            sg.uimgr.closeUI("pop_aliOneGift");
        }
    }
    mvc.AliPayCtrl = AliPayCtrl;
})(mvc || (mvc = {}));

