(function (mvc) {
    class AnniversaryRedBagVo extends sg.VoBase {
        updatePhpData(data) {
            this.day_limit = data.day_limit;
            this.item_id = data.item_id;
            this.rewards = data.rewards;
        }
        updateData(data) {
            this.only_id = data.only_id;
            this.stage = data.stage;
            this.stage_finish_time = data.stage_finish_time;
            this.turn_info = data.turn_info;
            this.totalTimes = data.total_limit;
            this.dayTimes = data.day_limit;
        }
        getDayAllTimes() {
            let time = 0;
            for (let info of this.dayTimes) {
                time += info[1];
            }
            return time;
        }
        getRedBagNum(id, isAll) {
            if (isAll) {
                for (let info of this.totalTimes) {
                    if (info[0] == id)
                        return info[1];
                }
                return 0;
            }
            else {
                for (let info of this.dayTimes) {
                    if (info[0] == id)
                        return info[1];
                }
                return 0;
            }
        }
        getRedBagRewardNum(id, isAll) {
            if (isAll) {
                for (let info of this.totalTimes) {
                    if (info[0] == id)
                        return info[2];
                }
                return 0;
            }
            else {
                for (let info of this.dayTimes) {
                    if (info[0] == id)
                        return info[2];
                }
                return 0;
            }
        }
        getRewardNum(isAll) {
            let num = 0;
            if (isAll) {
                for (let info of this.totalTimes) {
                    num += info[2];
                }
            }
            else {
                for (let info of this.dayTimes) {
                    num += info[2];
                }
            }
            return num;
        }
        getRedBagGetNum(id) {
            if (!this.turn_info)
                return 0;
            for (let info of this.turn_info.info) {
                if (info[0] == id)
                    return info[1];
            }
            return 0;
        }
        getRedbagShowNum(id) {
            for (let reward of this.rewards) {
                if (reward[0] == id)
                    return reward[2];
            }
            return 0;
        }
        getRedbgResidueNum() {
            return this.day_limit - this.getDayAllTimes();
        }
        getRedBagMaxNum(id) {
            for (let reward of this.rewards) {
                if (reward[0] == id)
                    return reward[3];
            }
            return 0;
        }
    }
    mvc.AnniversaryRedBagVo = AnniversaryRedBagVo;
})(mvc || (mvc = {}));

var mvc;
(function (mvc) {
    class AnniversaryRememberVo extends sg.VoBase {
        constructor() {
            super();
            this.dataMap = new Map();
        }
        initData(data) {
            this.isGetReward = data.is_reward == 1;
            this.msg = data.msg;
            this.titleArr = data.title_ids;
            this.titleId = data.title_id;
            this.datas = data.c_data;
            this.isShow = data.is_show == 0;
            this.titleArr.sort((a, b) => {
                let cfgA = this.getTitleCfgById(a);
                let cfgB = this.getTitleCfgById(b);
                if ((cfgA.titleRange > 0 && cfgB.titleRange > 0) || (cfgA.titleRange == 0 && cfgB.titleRange == 0)) {
                    if (cfgA.titleType == cfgB.titleType) {
                        return cfgA.ID - cfgB.ID;
                    }
                    else {
                        if (cfgB.titleType == 0)
                            return -1;
                        else if (cfgA.titleType == 0)
                            return 1;
                        else
                            return cfgA.titleType - cfgB.titleType;
                    }
                }
                else {
                    return cfgA.titleRange > 0 ? -1 : 1;
                }
            });
            this.dataMap.clear();
            for (let data of this.datas) {
                this.dataMap.set(data.sys_id, data);
            }
        }
        getTitleCfgById(id) {
            return sg.dbmgr.get("backgroundActive_active9RecoredTitile", id);
        }
        getAllDataById(id) {
            let cfg = sg.dbmgr.get("backgroundActive_active9RecoredClass", id);
            let arr = [];
            for (let text of cfg.text) {
                arr.push(this.getDataById(text));
            }
            return arr;
        }
        getDataById(id) {
            let cfg = sg.dbmgr.get("backgroundActive_active9RecoredCount", id);
            let val;
            if (this.dataMap.has(id)) {
                val = this.dataMap.get(id).value;
            }
            else {
                val = 0;
            }
            if (cfg.id == 32) {
                return sg.time.formatTimeStrT("F13", val);
            }
            else {
                return cfg.isPer ? (val / cfg.max / 10000).toFixed(2) + "%" : val.toString();
            }
        }
        getIsSkipById(id) {
            let cfg = sg.dbmgr.get("backgroundActive_active9RecoredClass", id);
            return !this.dataMap.has(cfg.passData);
        }
    }
    mvc.AnniversaryRememberVo = AnniversaryRememberVo;
})(mvc || (mvc = {}));

