var mvc;
(function (mvc) {
    let EVT = mvc.AnniversaryConst.EVT;
    class AnniversaryModel extends sg.ModelBase {
        initModel() {
            this.loginVo = new mvc.AnniversarySignVo();
            this.redbagVo = new mvc.AnniversaryRedBagVo();
            this.rememberVo = new mvc.AnniversaryRememberVo();
            this.isOpenWindow = false;
            this.msgTime = 0;
        }
        registerEvents() {
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.BG_ACT_ANN_SIGN, this._redSign, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.BG_ACT_ANN_RECORD, this._redRecord, this);
        }
        updateSignInfo(data) {
            this.loginVo.updateData(data);
            mgr.redotMgr.check(mvc.REDOT_ID.BG_ACT_ANN_SIGN);
        }
        signReward(data) {
            this.loginVo.received = data.day;
            if (data.day == 7) {
                this.fireEvent(EVT.PLAY_SIGN_ANI, data.reward);
            }
            else {
                sg.uimgr.showUI("pop_getReward", sg.translate('签到获得'), data.reward);
            }
            this.loginVo.select_infos.push(data.select_info);
            mgr.redotMgr.check(mvc.REDOT_ID.BG_ACT_ANN_SIGN);
            this.fireEvent(EVT.UPDATE_SIGN_VIEW);
        }
        _redSign() {
            if (!mgr.conditionMgr.checkFunc(mvc.FUNC_ID.BG_ANN_SIGN, false))
                return 0;
            let openDay = this.loginVo.day;
            return (openDay > this.loginVo.received && this.loginVo.received < 7) ? 1 : 0;
        }
        _redRecord() {
            if (!mgr.conditionMgr.checkFunc(mvc.FUNC_ID.BG_ANN_RECORD, false))
                return 0;
            return this.rememberVo.isGetReward ? 0 : 1;
        }
        initRedBagPhpInfo(data) {
            if (!this.isOpenWindow && mgr.conditionMgr.checkFunc(mvc.FUNC_ID.BG_ANN_LOTTERY, false))
                sg.uimgr.showUI("pop_annWindow");
            this.redbagVo.updatePhpData(data);
        }
        initRedBagInfo(data) {
            this.redbagVo.updateData(data);
            if (data.stage == 1) {
                if (!this._errorTime)
                    this._errorTime = mgr.toolsMgr.getGlobalVoById("bgActivity_redbagrain_err", 1);
                let curTime = sg.time.getSecondTime();
                if (data.stage_finish_time - curTime > this._errorTime) {
                    let residue = this.redbagVo.getRedbgResidueNum();
                    if (residue > 0)
                        sg.uimgr.showUI("pop_redBagRain");
                }
            }
        }
        redbagBob(data) {
            if (data.rob_type == 1) {
                this.redbagVo.turn_info = data.turn_info;
                this.redbagVo.dayTimes = data.day_limit;
                this.redbagVo.totalTimes = data.total_limit;
            }
            else if (data.rob_type == 2) {
                if (data.flag == 1) {
                    this.redbagVo.turn_info = data.turn_info;
                    this.redbagVo.dayTimes = data.day_limit;
                    this.redbagVo.totalTimes = data.total_limit;
                }
            }
            if (this.redbagVo.getRedbgResidueNum() <= 0) {
                if (sg.uimgr.isUIShow("pop_redBagRain"))
                    sg.uimgr.closeUI("pop_redBagRain");
            }
            this.fireEvent(EVT.OPEN_REDBAG, data);
        }
        stageNotify(data) {
            this.redbagVo.only_id = data.only_id;
            this.redbagVo.stage = data.stage;
            this.redbagVo.stage_finish_time = data.stage_finish_time;
            if (data.stage == 1) {
                this.redbagVo.turn_info = null;
                if (this.redbagVo.getRedbgResidueNum() > 0) {
                    sg.uimgr.showUI("pop_redBagRain");
                }
            }
            else if (data.stage == 2) {
                this.fireEvent(EVT.REDBAG_RAIN_END);
            }
        }
        blessNotify(data) {
            this.redbagVo.special_end_time = data.special_end_time;
            this.fireEvent(EVT.SHOW_BLESS);
        }
        initRememberData(data) {
            this.rememberVo.initData(data);
            mgr.redotMgr.check(mvc.REDOT_ID.BG_ACT_ANN_RECORD);
        }
        initLikeInfo(data) {
            this.rememberVo.like = data.like;
            this.fireEvent(EVT.UPDATE_LIKE, true);
        }
        rememberLike(data) {
            if (data.player_id == mvc.roleModel.roleInfo.playerId) {
                this.rememberVo.like = data.like;
                this.fireEvent(EVT.UPDATE_LIKE, true);
            }
            else {
                this.fireEvent(EVT.UPDATE_LIKE, false, data.like);
            }
        }
        rememberReward(data) {
            this.rememberVo.isGetReward = data.is_reward == 1;
            this.fireEvent(EVT.PLAY_RECORD_ANI, data.rewards);
            mgr.redotMgr.check(mvc.REDOT_ID.BG_ACT_ANN_RECORD);
        }
        rememberTitle(data) {
            this.rememberVo.titleId = data.title_id;
            this.fireEvent(EVT.UPDATE_TITLE);
        }
        rememberShow(data) {
            this.rememberVo.isShow = data.is_show == 0;
            this.fireEvent(EVT.UPDATE_TITLE);
        }
        rememberMsg(data) {
            this.rememberVo.msg = data.msg;
            this.fireEvent(EVT.UPDATE_MSG);
        }
        otherInfo(data) {
            sg.uimgr.showUI("pop_annFigure", data.head.player_id, data);
        }
        initSayInfo(data) {
            if (!data.msg)
                this.msg = "";
            else
                this.msg = data.msg;
        }
    }
    mvc.AnniversaryModel = AnniversaryModel;
})(mvc || (mvc = {}));

