var mvc;
(function (mvc) {
    class PopAnnRecord extends ui.view.bgActivity9.pop_znqRecordUI {
        initView(...args) {
            this._cfgs = sg.dbmgr.getDB("backgroundActive_active9RecoredClass", true);
        }
        initModelEvent() {
        }
        initCtrlEvent() {
            this.on(Laya.Event.CLICK, this, this._click);
        }
        onEnable() {
            super.onEnable();
            this._inAni = false;
            this._initModel();
            this._setData();
            this._updateView();
        }
        _initModel() {
            this.unitModel.setEndHandle(null, (isLoop, name) => {
                if (name == "stand2") {
                    this.unitModel.play("stand3", true);
                    this._idx = 1;
                    this._setIdx();
                    this._updatePage();
                }
                else if (name == "stand4") {
                    this._setIdx();
                    this._updatePage();
                }
            });
            this.unitModel.loadedHandle = () => {
                this.unitModel.play("stand", true);
            };
            this.unitModel.loadRole(9122, "PopAnnRecord");
        }
        _updateView() {
            this.lblName.visible = true;
            this.btnGet.visible = this.btnNext.visible = this.boxEnd.visible = false;
            for (let i = 0; i < this._cfgs.length; i++) {
                this[`boxPage${i + 1}`].visible = false;
            }
            this.lblName.text = mvc.roleModel.roleInfo.name + sg.translate(" 亲启");
        }
        _setIdx() {
            if (this._idx < this._cfgs.length + 1) {
                while (mvc.anniversaryModel.rememberVo.getIsSkipById(this._idx)) {
                    this._idx++;
                    if (this._idx == this._cfgs.length + 1)
                        break;
                }
            }
        }
        _setData() {
            for (let i = 0; i < this._cfgs.length; i++) {
                let cfg = this._cfgs[i];
                let datas = mvc.anniversaryModel.rememberVo.getAllDataById(cfg.titleType);
                for (let j = 0; j < datas.length; j++) {
                    this[`lblTxt${i + 1}_${j + 1}`].text = datas[j];
                }
            }
        }
        _updatePage() {
            for (let i = 0; i < this._cfgs.length; i++) {
                this[`boxPage${i + 1}`].visible = (i + 1) == this._idx;
            }
            if (this._idx == this._cfgs.length + 1) {
                this.btnGet.visible = true;
                this.btnNext.visible = false;
                this.boxEnd.visible = true;
                let curIdx = 0;
                let maxIdx = this.boxEnd1.numChildren;
                for (let i = 0; i < maxIdx; i++) {
                    this.boxEnd1.getChildAt(i).alpha = 0;
                }
                this.boxEnd2.alpha = 0;
                this.btnGet.alpha = 0;
                let fun = () => {
                    this.tweenTo(this.boxEnd1.getChildAt(curIdx), { alpha: 1 }, 500, null, Laya.Handler.create(this, () => {
                        curIdx++;
                        if (curIdx == maxIdx) {
                            this.tweenTo(this.boxEnd2, { alpha: 1 }, 500, null, Laya.Handler.create(this, () => {
                                this.tweenTo(this.btnGet, { alpha: 1 }, 500);
                            }));
                        }
                        else {
                            fun();
                        }
                    }));
                };
                fun();
            }
            else {
                this.btnGet.visible = false;
                this.boxEnd.visible = false;
                this.btnNext.visible = true;
                this.btnNext.alpha = 0;
                this.btnNext.mouseEnabled = false;
                this[`box${this._idx}_1`].alpha = this[`box${this._idx}_2`].alpha = 0;
                this.tweenTo(this[`box${this._idx}_1`], { alpha: 1 }, 500, null, Laya.Handler.create(this, () => {
                    this.tweenTo(this[`box${this._idx}_2`], { alpha: 1 }, 500, null, Laya.Handler.create(this, () => {
                        this.tweenTo(this.btnNext, { alpha: 1 }, 500, null, Laya.Handler.create(this, () => {
                            this.btnNext.mouseEnabled = true;
                        }));
                    }));
                }));
            }
        }
        _click(e) {
            switch (e.target) {
                case this.btnGet:
                    this.closeSelf();
                    sg.uimgr.showUI("pop_annFigure", mvc.roleModel.roleInfo.playerId);
                    if (!mvc.anniversaryModel.rememberVo.isGetReward) {
                        sg.uimgr.showUI("pop_annGift");
                    }
                    break;
                case this.btnNext:
                    this._idx++;
                    for (let i = 0; i < this._cfgs.length; i++) {
                        this[`boxPage${i + 1}`].visible = false;
                    }
                    this.btnNext.visible = false;
                    this.unitModel.play("stand4", false);
                    break;
                default:
                    if (!this._inAni) {
                        this.lblName.visible = false;
                        this.unitModel.play("stand2", false);
                        this._inAni = true;
                    }
                    break;
            }
        }
    }
    mvc.PopAnnRecord = PopAnnRecord;
})(mvc || (mvc = {}));

