                if (this._info.flag == 1) {
                    this.lblAllIntergral.visible = this.imgQuickenIcon.visible = true;
                    this.lblAllIntergral.value = this._info.rewards[0][1].toString();
                    this.playEff();
                    this.lblCutState.visible = true;
                    let curNum = this._info.redbag_info.num;
                    this.lblCutState.text = StringEx.format(sg.translate("已领取${curNum}/${maxNum}"), {"curNum":curNum,"maxNum":maxNum});
                    this.listPlayer.array = this._info.redbag_info.rob_info;
                }
                else if (this._info.flag == 2) {
                    this.lblNull.visible = true;
                    this.lblNull.text = sg.translate("手慢了，福袋被抢光了");
                    this.lblCutState.visible = true;
                    let curNum = this._info.redbag_info.num;
                    this.lblCutState.text = StringEx.format(sg.translate("已领取${curNum}/${maxNum}"), {"curNum":curNum,"maxNum":maxNum});
                    this.listPlayer.array = this._info.redbag_info.rob_info;
                }
