var mvc;
(function (mvc) {
    class PopRedBagRain extends ui.view.bgActivity9.pop_redbagRainUI {
        constructor() {
            super(...arguments);
            this._redbagImgPoolStr = "_redbagImgPoolStr";
        }
        initView(isTest = false) {
            this._isTest = isTest;
        }
        initModelEvent() {
            this.bindModelEvent(mvc.anniversaryModel, mvc.AnniversaryConst.EVT.SHOW_BLESS, this._showBless);
            this.bindModelEvent(mvc.anniversaryModel, mvc.AnniversaryConst.EVT.REDBAG_RAIN_END, this._rainEnd);
            this.bindModelEvent(mvc.anniversaryModel, mvc.AnniversaryConst.EVT.OPEN_REDBAG, this._openRedbag);
        }
        initCtrlEvent() {
            this.imgBless.on(Laya.Event.CLICK, this, this._clickBless);
        }
        onEnable() {
            super.onEnable();
            if (!mgr.conditionMgr.checkShowCondition(mvc.FUNC_ID.BG_ANN_REDBAG)) {
                this.closeSelf();
                return;
            }
            this.imgBless.visible = false;
            this._getRedBagNum = 0;
            this.clipNum.value = this._getRedBagNum.toString();
            this.initRedBag();
            if (sg.uimgr.isUIShow("sys_miniGameBeat")) {
                mvc.miniGameModel.fireEvent(mvc.MiniGameConst.EVT.SHOW_PAUSE_UI);
            }
        }
        onDisable() {
            super.onDisable();
            this.stopTimer(this.createNormalRedBag);
            this.stopTimer(this.createSpeRedBag);
            this.stopTimer(this._hideBlesss);
            this.boxNormal.destroyChildren();
            this.boxSpec.destroyChildren();
            if (sg.uimgr.isUIShow("pop_annRedbagOpen")) {
                sg.uimgr.closeUI("pop_annRedbagOpen");
            }
        }
        initRedBag() {
            if (this._isTest) {
                this._speRedbagNum = 15;
            }
            else {
                this._speRedbagNum = mvc.anniversaryModel.redbagVo.getRedbagShowNum(2) - mvc.anniversaryModel.redbagVo.getRedBagGetNum(2);
                if (this._speRedbagNum < 0)
                    this._speRedbagNum = 0;
            }
            let normalCfg = sg.dbmgr.get("backgroundActive_active9RedbagCount", 1);
            let speCfg = sg.dbmgr.get("backgroundActive_active9RedbagCount", 2);
            this._normalPos = normalCfg.rbBirth;
            this._spePos = speCfg.rbBirth;
            this._normalTime = normalCfg.rbCD;
            this._speTime = speCfg.rbCD;
            this._normalIcon = normalCfg.iconPath;
            this._speIcon = speCfg.iconPath;
            this._normalNum = normalCfg.rbNum;
            this._speNum = speCfg.rbNum;
            this._normalY = normalCfg.rbPos;
            this._speY = speCfg.rbPos;
            this._normalFall = normalCfg.rbTime;
            this._speFall = speCfg.rbTime;
            this.createNormalRedBag();
            this.createSpeRedBag();
        }
        createNormalRedBag() {
            let num = Math.random() * (this._normalNum[1] - this._normalNum[0]) + this._normalNum[0];
            for (let i = 0; i < num; i++) {
                let redbagImg = Laya.Pool.getItemByClass(this._redbagImgPoolStr, Laya.Image);
                mgr.icon.drawTexture(this._normalIcon, redbagImg);
                let y = Math.random() * (this._normalY[1] - this._normalY[0]) + this._normalY[0];
                redbagImg.anchorX = redbagImg.anchorY = 0.5;
                redbagImg.y = -44 - y;
                redbagImg.x = Math.random() * (this._normalPos[1] - this._normalPos[0]) + this._normalPos[0];
                redbagImg.rotation = Math.random() * 360;
                redbagImg.offAll();
                redbagImg.on(Laya.Event.CLICK, this, this._clickRedbag, [1, redbagImg]);
                let moveTime = Math.random() * (this._normalFall[1] - this._normalFall[0]) + this._normalFall[0];
                this.tweenTo(redbagImg, { y: this.height }, moveTime, null, Laya.Handler.create(this, () => {
                    Laya.Pool.recover(this._redbagImgPoolStr, redbagImg);
                    redbagImg.removeSelf();
                }));
                this.tweenTo(redbagImg, { rotation: moveTime / 2000 * 360 }, moveTime);
                this.boxNormal.addChild(redbagImg);
            }
            let randomTime = Math.random() * (this._normalTime[1] - this._normalTime[0]) + this._normalTime[0];
            this.after(randomTime, this.createNormalRedBag);
        }
        createSpeRedBag() {
            let num = Math.random() * (this._speNum[1] - this._speNum[0]) + this._speNum[0];
            for (let i = 0; i < num; i++) {
                if (this._speRedbagNum <= 0)
                    return;
                this._speRedbagNum--;
                let redbagImg = Laya.Pool.getItemByClass(this._redbagImgPoolStr, Laya.Image);
                mgr.icon.drawTexture(this._speIcon, redbagImg);
                let y = Math.random() * (this._speY[1] - this._speY[0]) + this._speY[0];
                redbagImg.anchorX = redbagImg.anchorY = 0.5;
                redbagImg.y = -44 - y;
                redbagImg.x = Math.random() * (this._spePos[1] - this._spePos[0]) + this._spePos[0];
                redbagImg.offAll();
                redbagImg.on(Laya.Event.CLICK, this, this._clickRedbag, [2, redbagImg]);
                let moveTime = Math.random() * (this._speFall[1] - this._speFall[0]) + this._speFall[0];
                this.tweenTo(redbagImg, { y: this.height }, moveTime, null, Laya.Handler.create(this, () => {
                    Laya.Pool.recover(this._redbagImgPoolStr, redbagImg);
                    redbagImg.removeSelf();
                }));
                this.tweenTo(redbagImg, { rotation: moveTime / 2000 * 360 }, moveTime);
                this.boxSpec.addChild(redbagImg);
            }
            let randomTime = Math.random() * (this._speTime[1] - this._speTime[0]) + this._speTime[0];
            this.after(randomTime, this.createSpeRedBag);
        }
        _showBless() {
            this.imgBless.visible = true;
            this.imgBless.y = -this.imgBless.height * this.imgBless.scaleY / 2;
            let endTime = mvc.anniversaryModel.redbagVo.special_end_time;
            let curTime = sg.time.getSecondTime();
            this.tweenTo(this.imgBless, { y: this.height }, (endTime - curTime) * 1000);
            this.after((endTime - curTime) * 1000, this._hideBlesss);
        }
        _clickRedbag(id, img) {
            let eff = new mvc.UnitRedBagEff();
            let pos = new Laya.Point(img.x, img.y);
            img.parent.localToGlobal(pos, false, this);
            eff.pos(pos.x + img.width / 2, pos.y + img.height / 2);
            this.addChild(eff);
            Laya.Pool.recover(this._redbagImgPoolStr, img);
            img.removeSelf();
            this.clearTweenByTarget(img);
            sg.uimgr.showUI("pop_annRedbagOpen", id);
        }
        _clickBless() {
            sg.uimgr.showUI("pop_annRedbagOpen", 3);
            this.imgBless.visible = false;
        }
        _hideBlesss() {
            this.imgBless.visible = false;
        }
        _rainEnd() {
            this.mouseEnabled = false;
            this.tweenTo(this, { alpha: 0 }, 700, null, Laya.Handler.create(this, () => {
                this.closeSelf();
                if (sg.uimgr.isUIShow("pop_annRedbagOpen")) {
                    sg.uimgr.closeUI("pop_annRedbagOpen");
                }
                this.alpha = 1;
                this.mouseEnabled = true;
            }));
        }
        _openRedbag(data) {
            if (data.rob_type == 1 || (data.rob_type == 2 && data.flag == 1)) {
                this._getRedBagNum++;
                this.clipNum.value = this._getRedBagNum.toString();
            }
        }
    }
    mvc.PopRedBagRain = PopRedBagRain;
})(mvc || (mvc = {}));

