(function (mvc) {
    let EVT = mvc.BgActivityGiftConst.EVT;
    class PopBgActivityGift extends ui.view.backgroundActivity.pop_giftUI {
        initView(funId) {
            this._funId = funId;
            this._model = mvc.bgActivityGiftModel;
        }
        initModelEvent() {
            this.bindModelEvent(this._model, EVT.UPDATE_VIEW, this._updateView);
        }
        initCtrlEvent() {
            this.giftList.vScrollBarSkin = "";
            this.giftList.renderHandler = this.createHandler(this, this._onGiftList, null, false);
        }
        updateWhenNetReConn() {
            this._updateView();
        }
        onEnable() {
            super.onEnable();
            this._endTime = 0;
            let actVo = mvc.activityModel.openActivityVo.get(this._funId);
            if (!actVo) {
                return;
            }
            this._endTime = actVo.end_time;
            this._type = mvc.activityModel.getActTypeByFuncopenId(this._funId);
            let time = this._endTime - sg.time.getSecondTime();
            if (time < 0)
                time = 0;
            let v1 = sg.time.formatTimeStrT("F9", time);
            this.lblTime.text = StringEx.format(sg.translate("活动时间：${v1}后结束"), {"v1":v1});
            this._updateView();
            this._updateTime();
        }
        onDisable() {
            super.onDisable();
            this.stopTimer(this._onTimer);
        }
        onAwake() {
            super.onAwake();
            this.boxKrChargeTips.visible = mgr.gplatform.isIceBird();
        }
        onJumpInit(param) {
            this._funId = param.funId;
            this.onEnable();
        }
        _updateView() {
            let vo = this._model.giftInfoMap[this._type];
            if (vo) {
                vo.sort();
                this.giftList.array = vo.gift_list;
            }
        }
        _onGiftList(cell, idx) {
            let data = cell.dataSource;
            if (!data)
                return;
            cell.initView(data);
        }
        _updateTime() {
            this.repeats(1000, this._onTimer, true);
        }
        _onTimer() {
            let time = this._endTime - sg.time.getSecondTime();
            if (time <= 0) {
                this.stopTimer(this._onTimer);
                time = 0;
            }
            let v1 = sg.time.formatTimeStrT("F9", time);
            this.lblTime.text = StringEx.format(sg.translate("活动时间：${v1}后结束"), {"v1":v1});
        }
    }
    mvc.PopBgActivityGift = PopBgActivityGift;
})(mvc || (mvc = {}));

