(function (mvc) {
    class UnitAccuReward extends ui.view.bgActivityCommon.unit_accuRewardUI {
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            this.btnGet.on(Laya.Event.CLICK, this, this._onBtnGet);
            this.listReward.renderHandler = this.createHandler(this, this._listRenderer, undefined, false);
        }
        onDisable() {
            this.btnGet.off(Laya.Event.CLICK, this, this._onBtnGet);
            super.onDisable();
        }
        get dataSource() {
            return super.dataSource;
        }
        set dataSource(data) {
            super.dataSource = data;
            if (!data)
                return;
            let vo = mvc.bgActivityGiftModel.accuInfoMap[data.type];
            let need = mgr.gplatform.getLangPrice(data.need_charge);
            let now = vo.accu_value;
            let v1 = mgr.gplatform.showLangPrice(data.need_charge);
            this.lblName.text = StringEx.format(sg.translate("活动累计充值${v1}"), {"v1":v1});
            this.prog.maxValue = need;
            this.prog.value = now;
            this.prog.label = `${now}/${need}`;
            let vos = mvc.ItemVo.createItemVos(data.item_list);
            this.listReward.array = vos;
            this.redTips.visible = false;
            if (vo.received.indexOf(data.id) == -1) {
                this.btnGet.disabled = false;
                if (need > now) {
                    this.btnGet.label = sg.translate("去购买");
                }
                else {
                    this.btnGet.label = sg.translate("领取");
                    this.redTips.visible = true;
                }
            }
            else {
                this.btnGet.disabled = true;
                this.btnGet.label = sg.translate("已领取");
            }
        }
        _listRenderer(cell) {
            let data = cell.dataSource;
            if (!data)
                return;
            cell.initView(data);
        }
        _onBtnGet() {
            let data = this.dataSource;
            if (!data)
                return;
            let vo = mvc.bgActivityGiftModel.accuInfoMap[data.type];
            if (vo.received.indexOf(data.id) == -1) {
                let need = mgr.gplatform.getLangPrice(data.need_charge);
                if (vo.accu_value >= need) {
                    mvc.bgActivityGiftCtrl.reqAccuReceiveReward(data.type, data.id);
                }
                else {
                    mvc.bgActivityGiftModel.fireEvent(mvc.BgActivityGiftConst.EVT.UPDATE_TAB);
                }
            }
        }
    }
    mvc.UnitAccuReward = UnitAccuReward;
})(mvc || (mvc = {}));

var mvc;
(function (mvc) {
    class UnitBgActivityGiftItem extends ui.view.backgroundActivity.unit_gift_itemUI {
        initView(vo) {
            this._vo = vo;
            this._model = mvc.bgActivityGiftModel;
            this.updateView();
        }
        initCtrlEvent() {
            this.rewardList.renderHandler = this.createHandler(this, this._onRewardList, null, false);
            this.btnBuy.on(Laya.Event.CLICK, this, this._onBtnBuy);
        }
        onEnable() {
            super.onEnable();
            this._limit = 0;
            this._buyCount = 0;
            this.boxPrice.visible = mgr.gplatform.showOldPrice();
        }
        updateView() {
            if (this._vo) {
                this.lblTitle.text = this._vo.name;
                let info = this._model.giftInfoMap[this._vo.type];
                let limitStr = "";
                if (info) {
                    if (this._vo.day_buy_limit > 0) {
                        this._buyCount = info.getBuyNumOfDay(this._vo.id);
                        limitStr = sg.translate("每日限购");
                        this._limit = this._vo.day_buy_limit;
                    }
                    else if (this._vo.buy_limit > 0) {
                        this._buyCount = info.getBuyNum(this._vo.id);
                        this._limit = this._vo.buy_limit;
                        limitStr = sg.translate("限购");
                    }
                    else {
                        limitStr = sg.translate("无限购");
                        this._limit = 0;
                    }
                }
                this.imgIcon.visible = this.lblGoldNum.visible = this.lblOldPrice.visible = this.imgLine.visible = false;
                this.btnBuy.label = "";
                this.redotBuy.visible = false;
                if (this._vo.product_id == 0) {
                    if (this._vo.gold_num == 0) {
                        this.btnBuy.label = sg.translate("免费");
                        this.redotBuy.visible = this._buyCount < this._limit;
                    }
                    else {
                        this.imgIcon.visible = true;
                        this.lblGoldNum.visible = true;
                        mgr.icon.drawTexture(mgr.icon.getIconPath(mgr.toolsMgr.getIconById(1)), this.imgIcon);
                        this.lblGoldNum.text = "" + this._vo.gold_num;
                        this.redotBuy.visible = this._buyCount < this._limit && mgr.toolsMgr.getCountById(1) >= this._vo.gold_num;
                    }
                }
                else {
                    this.lblOldPrice.visible = true;
                    this.imgLine.visible = true;
                    let v1 = this._vo.original_price;
                    this.lblOldPrice.text = StringEx.format(sg.translate("原价${v1}元"), {"v1":v1});
                    this.btnBuy.label = mgr.gplatform.showPriceByGearId(this._vo.product_id);
                }
                let str = this._limit == 0 ? limitStr : (limitStr + (this._limit - this._buyCount) + "/" + this._limit);
                this.lblLimit.text = str;
                this.lblLimit.color = (this._limit == 0 || this._limit - this._buyCount > 0) ? mgr.toolsMgr.getColor2("green") : mgr.toolsMgr.getColor2("red");
                this.btnBuy.disabled = (this._limit > 0 && this._limit - this._buyCount <= 0);
                let vos = mvc.ItemVo.createItemVos(this._vo.item_list);
                this.rewardList.array = vos;
            }
        }
        _onRewardList(cell, idx) {
            let data = cell.dataSource;
            if (!data)
                return;
            cell.initView(data);
        }
        _onBtnBuy() {
            if (this._vo) {
                let funId = mvc.bgActivityGiftModel.getFunIdByType(this._vo.type);
                let actVo = mvc.activityModel.openActivityVo.get(funId);
                if (!actVo) {
                    sg.uimgr.showNotice(sg.translate("活动已结束"));
                    return;
                }
                if (this._limit != 0 && this._limit - this._buyCount <= 0) {
                    sg.uimgr.showNotice(sg.translate("限购次数不足"));
                    return;
                }
                if (this._vo.product_id == 0) {
                    if (this._vo.gold_num == 0 || mgr.toolsMgr.checkConsume([[1, this._vo.gold_num]], true)) {
                        mvc.bgActivityGiftCtrl.reqReceiveReward(this._vo.id, this._vo.type);
                    }
                }
                else {
                    if (this._vo.price > 0)
                        mvc.rechargeCtrl.reqRechargeByPhpEx(this._vo.product_id);
                }
            }
        }
    }
    mvc.UnitBgActivityGiftItem = UnitBgActivityGiftItem;
})(mvc || (mvc = {}));

