(function (mvc) {
    class ArenaModel extends sg.ModelBase {
        initModel() {
            this.fristRed = true;
            this.tempDate = new Date();
            this.isShowIcon = true;
        }
        registerEvents() {
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.ARENA_REWARD, this.rewardRed, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.ARENA_RECORD, this.recodeRed, this);
        }
        getArenaCfg(type) {
            return sg.dbmgr.get("arena_arena", type);
        }
        getRankReward(arenaType, type) {
            let cfgs = sg.dbmgr.getDB("arena_rankReward");
            let arr = [];
            for (let key in cfgs) {
                let v = cfgs[key];
                if (arenaType == v.type && v.resultType == type) {
                    arr.push(v);
                }
            }
            return arr;
        }
        getDayTime() {
            this.tempDate.setTime(sg.time.getTime());
            let time = this.tempDate;
            time.setHours(22, 0, 0, 0);
            let end = time.getTime();
            time.setHours(0);
            let start = time.getTime();
            let cur = sg.time.getTime();
            if (end > cur && start <= cur) {
                return end - cur;
            }
            else {
                return (end + 86400000) - cur;
            }
        }
        arenaOpen() {
            if (this.getDayTime() <= 0) {
                sg.uimgr.showNotice(sg.translate("新赛季0点开始"));
                return false;
            }
            let act = mvc.activityModel.openActivityVo.get(mvc.FUNC_ID.ARENA);
            if (!act) {
                sg.uimgr.showNotice(sg.translate("赛季未开"));
                return false;
            }
            if (mgr.conditionMgr.checkFunc(mvc.FUNC_ID.ARENA, true))
                return true;
            return false;
        }
        arenaRed() {
            return mgr.toolsMgr.getCountById(mvc.MainConst.ITEM_ID.ARENA_COUPON);
        }
        rewardRed() {
            if (this.arenaInfo) {
                if (this.arenaInfo.day_reward || this.arenaInfo.week_reward)
                    return 1;
            }
            return 0;
        }
        recodeRed() {
            return mvc.redotCtrl.getCheckRed(mvc.REDOT_ID.ARENA_RECORD);
        }
    }
    mvc.ArenaModel = ArenaModel;
})(mvc || (mvc = {}));

