(function (mvc) {
    class ArenaCtrl extends sg.CtrlBase {
        initCtrl() {
            this._model = mvc.arenaModel;
        }
        registerMsg() {
            this.onMsg(Proto.ARENA_INFO, this.onArenaInfo);
            this.onMsg(Proto.ARENA_COMBAT, this.onArenaCombat);
            this.onMsg(Proto.ARENA_FINISH_COMBAT, this.onCombatFinish);
            this.onMsg(Proto.ARENA_RECORD, this.onRecord);
            this.onMsg(Proto.ARENA_REFRESH, this.onArenaRefresh);
            this.onMsg(Proto.ARENA_RECEIVE_REWARD, this.onArenaGetReward);
        }
        reqArenaInfo() {
            let req = this.createProto(Proto.arena_info_request);
            this.sendMsg(Proto.ARENA_INFO, req);
        }
        onArenaInfo(info) {
            mvc.arenaModel.refreshTime = info.refresh_time;
            mvc.arenaModel.arenaInfo = info;
            mgr.redotMgr.check(mvc.REDOT_ID.ARENA_REWARD);
            this._model.fireEvent(mvc.ArenaConst.EVT.ARENA_INFO);
        }
        reqArenaCombat(pid, time = 0) {
            let req = this.createProto(Proto.arena_combat_request);
            req.player_id = pid;
            req.revenge_time = time;
            this.sendMsg(Proto.ARENA_COMBAT, req);
        }
        onArenaCombat(info) {
            this._lastReport = info.combat_notify;
            mvc.battleModel.startBattle(info.combat_notify, Proto.COMBAT_TYPE.ARENA, () => {
                this.reqCombatFinish();
            });
        }
        reqCombatFinish() {
            let req = this.createProto(Proto.arena_finish_combat_request);
            this.sendMsg(Proto.ARENA_FINISH_COMBAT, req);
        }
        onCombatFinish(info) {
            sg.uimgr.showUI("pop_rankResult", info, this._lastReport, mvc.ArenaConst.ArenaType.arena);
            this._lastReport = null;
            this._model.fireEvent(mvc.ArenaConst.EVT.ARENA_COMBAT);
        }
        reqRecord() {
            let req = this.createProto(Proto.arena_record_request);
            this.sendMsg(Proto.ARENA_RECORD, req);
        }
        onRecord(info) {
            this._model.fireEvent(mvc.ArenaConst.EVT.ARENA_RECORD, info.records);
        }
        reqArenaRefresh() {
            let req = this.createProto(Proto.arena_refresh_request);
            this.sendMsg(Proto.ARENA_REFRESH, req);
        }
        onArenaRefresh(info) {
            mvc.arenaModel.refreshTime = info.refresh_time;
            if (mvc.arenaModel.arenaInfo) {
                mvc.arenaModel.arenaInfo.refresh_time = info.refresh_time;
                mvc.arenaModel.arenaInfo.opponents = info.opponents;
                this._model.fireEvent(mvc.ArenaConst.EVT.ARENA_INFO);
            }
        }
        reqArenaGetReward(type) {
            let req = this.createProto(Proto.arena_receive_reward_request);
            req.type = type;
            this.sendMsg(Proto.ARENA_RECEIVE_REWARD, req);
        }
        onArenaGetReward(info) {
            if (mvc.arenaModel.arenaInfo) {
                if (info.type == Proto.ARENA_REWARD.DAY) {
                    mvc.arenaModel.arenaInfo.day_reward = 0;
                }
                else if (info.type == Proto.ARENA_REWARD.WEEK) {
                    mvc.arenaModel.arenaInfo.week_reward = 0;
                }
            }
            mgr.redotMgr.check(mvc.REDOT_ID.ARENA_REWARD);
            this._model.fireEvent(mvc.ArenaConst.EVT.ARENA_INFO);
            sg.uimgr.showUI("pop_getReward", sg.translate("领取成功"), info.reward);
        }
    }
    mvc.ArenaCtrl = ArenaCtrl;
})(mvc || (mvc = {}));

