(function (mvc) {
    class BoxRoleHp extends Laya.Box {
        constructor() {
            super(...arguments);
            this._subHpUnits = [];
            this.hideSelf = false;
        }
        onAwake() {
            super.onAwake();
            this.proHp = this.getChildByName("proHp");
            this.boxBuff = this.getChildByName("boxBuff");
        }
        _showTestHp() {
            let lblHp = new Laya.Label();
            lblHp.fontSize = 18;
            lblHp.y = 16;
            lblHp.color = "#ffffff";
            lblHp.stroke = 1;
            lblHp.strokeColor = "#000000";
            lblHp.centerX = 0;
            lblHp.centerY = 0;
            this.proHp.addChild(lblHp);
            this.lblHp = lblHp;
        }
        onEnable() {
            super.onEnable();
            this.boxBuff.removeChildren();
        }
        registerSubHp(unit) {
            this._subHpUnits.push(unit);
        }
        callSubHp(cmd, ...args) {
            for (let unit of this._subHpUnits) {
                unit.onRoleSubHpCall(cmd, ...args);
            }
        }
        initUnit(vo) {
            this.callSubHp("initUnit", vo);
            if (this.hideSelf)
                return;
            this.proHp.value = vo.hp / vo.hpMax;
            this.lblHp && this.lblHp.changeText(vo.hp / vo.hpMax + "");
            if (vo.isDefender) {
                this.boxBuff.dir = "R2L";
            }
        }
        setHp(percent, diff) {
            this.callSubHp("setHp", percent, diff);
            if (this.hideSelf)
                return;
            this.proHp.value = percent;
            this.lblHp && this.lblHp.changeText(percent + "");
        }
        addBuff(dbuff) {
            this.callSubHp("addBuff", dbuff);
            if (this.hideSelf)
                return;
            let cfg = sg.dbmgr.get("skill_buff", dbuff.cfgId);
            if (!cfg || !cfg.icon || cfg.icon == "")
                return;
            if (cfg.notShow == 1)
                return;
            this.addBuffIcon(dbuff, cfg.icon);
        }
        removeBuff(dbuff) {
            this.callSubHp("removeBuff", dbuff);
            if (this.hideSelf)
                return;
            let icon = this._getBuffIcon(dbuff.id);
            if (!icon)
                return;
            icon.destroy();
        }
        updateBuff(dbuff) {
            this.callSubHp("updateBuff", dbuff);
            if (this.hideSelf)
                return;
            let icon = this._getBuffIcon(dbuff.id);
            if (!icon)
                return;
            icon.updateCount(dbuff);
        }
        addBuffIcon(dbuff, icon) {
            this.callSubHp("addBuffIcon", dbuff, icon);
            if (this.hideSelf)
                return;
            let unit = new mvc.UnitBuffItem();
            unit.initView(dbuff, icon);
            this.boxBuff.addChild(unit);
            return unit;
        }
        _getBuffIcon(id) {
            for (let i = 0; i < this.boxBuff.numChildren; i++) {
                let unit = this.boxBuff.getChildAt(i);
                if (unit.id == id) {
                    return unit;
                }
            }
            return null;
        }
    }
    mvc.BoxRoleHp = BoxRoleHp;
})(mvc || (mvc = {}));

