(function (mvc) {
    class SysBattle extends ui.view.battle.sys_battleUI {
        initView(combatType) {
            this._combatType = combatType;
        }
        initSendMsg() { }
        initModelEvent() {
            mvc.battleModel.setUIDelegate(this._uiDelegateCall.bind(this));
        }
        initCtrlEvent() {
            this.btnDebug.on(Laya.Event.CLICK, this, this._onBtnDebug);
            this.boxSkip.on(Laya.Event.CLICK, this, this._onSkipBattle);
            this.clipSpeed.on(Laya.Event.CLICK, this, this._onClipSpeed);
        }
        onAwake() {
            super.onAwake();
            this.boxDebug.visible = false;
            this.btnDebug.visible = mgr.gplatform.isDebug;
            this.boxScene.setParentUI(this);
            this.boxScene.transmitHpBox(this.boxHpL, this.boxHpR);
            this.boxSkip.visible = false;
        }
        onEnable() {
            super.onEnable();
            this.boxSkip.visible = false;
            this.boxHead.alpha = 0;
            this.boxReport2D.alpha = 0;
            this._refreshtUnitByCombatType();
            sg.sound.playMusic("res/sound/bg/bg_battle.mp3");
            this.clipSpeed.index = mvc.battleModel.playSpeed - 1;
            this.clipSpeed.mouseEnabled = true;
        }
        onDisable() {
            super.onDisable();
            this._disableUnitByCombatType();
            mvc.battleModel.setUIDelegate(null);
            sg.sound.playMusic("res/sound/bg/bg_main.mp3");
        }
        _refreshtUnitByCombatType() {
            let combatType = this._combatType;
            if (combatType == Proto.COMBAT_TYPE.GUILD_HUNTING_CHALLENGE) {
                let unit = this.boxOthersHp.getChildByName("boxHpHunting");
                if (unit) {
                    unit.x = unit.y = 0;
                    this.boxHpHunting.addChild(unit);
                    this.boxHpR.registerSubHp(unit);
                }
                else {
                    let unit = this.boxHpHunting.getChildByName("boxHpHunting");
                    if (unit) {
                        unit.visible = false;
                    }
                }
                this.boxHpR.hideSelf = true;
                this.boxRoleHeadR.visible = false;
            }
            else {
                this.boxHpR.hideSelf = false;
                this.boxRoleHeadR.visible = true;
            }
        }
        _disableUnitByCombatType() {
            let combatType = this._combatType;
            if (combatType == Proto.COMBAT_TYPE.GUILD_HUNTING_CHALLENGE) {
                let unit = this.boxHpHunting.getChildByName("boxHpHunting");
                if (unit) {
                    unit.visible = false;
                }
            }
        }
        _uiDelegateCall(types, ...args) {
            switch (types) {
                case "scene":
                    {
                        let time = 1000;
                        this.tweenTo(this.boxReport2D, { alpha: 1 }, time, Laya.Ease["stongIn"]);
                        this.tweenTo(this.boxHead, { alpha: 1 }, time, Laya.Ease["stongIn"]);
                    }
                    return this.boxScene.onBattleCall(...args);
                case "role_head_left":
                    this.boxPetsHeadL.onBattleCall(...args);
                    this.boxRuleL.onBattleCall(...args);
                    return this.boxRoleHeadL.onBattleCall(...args);
                case "role_head_right":
                    this.boxPetsHeadR.onBattleCall(...args);
                    this.boxRuleR.onBattleCall(...args);
                    return this.boxRoleHeadR.onBattleCall(...args);
                case "report_2d":
                    return this.boxReport2D.onBattleCall(...args);
                case "pet_play_skill":
                    {
                        let idPet = args[0];
                        let isDefender = args[1];
                        let head = isDefender ? this.boxPetsHeadR : this.boxPetsHeadL;
                        head.petPlaySkill(idPet);
                    }
                    break;
                case "rule_play_skill":
                    {
                        let idRule = args[0];
                        let isDefender = args[1];
                        let head = isDefender ? this.boxRuleR : this.boxRuleL;
                        head.rulePlaySkill(idRule);
                    }
                    break;
                case "clear_all":
                    {
                        this.boxScene.clear();
                        this.boxRoleHeadL.clear();
                        this.boxRoleHeadR.clear();
                        this.boxPetsHeadR.clear();
                        this.boxPetsHeadL.clear();
                        this.boxReport2D.clear();
                    }
                    break;
                default:
                    sg.Logger.openLog && sg.log("_uiDelegateCall lost", types, ...args);
                    break;
            }
        }
        _onBtnDebug() {
            this.boxDebug.visible = !this.boxDebug.visible;
        }
        showSkipRounds(v) {
            this.boxSkip.visible = true;
            let lbl = this.boxSkip.getChildAt(0);
            this.boxSkip.mouseEnabled = v <= 0;
            if (v <= 0) {
                lbl.text = sg.translate("点击跳过战斗");
            }
            else {
                lbl.text = StringEx.format(sg.translate("${v}回合后可跳过战斗"), {"v":v});
            }
        }
        _onSkipBattle() {
            let mgr = mvc.battleModel.battleMgr;
            mgr.terminalBattle();
        }
        _onClipSpeed() {
            let info = mgr.toolsMgr.getGlobalVoById("battle_speedup_unlock", 1);
            if (info && mgr.conditionMgr.check(info)) {
                this.clipSpeed.index = this.clipSpeed.index == 0 ? 1 : 0;
                mvc.battleModel.playSpeed = this.clipSpeed.index + 1;
                mvc.battleModel.battleMgr.setSpeed(mvc.battleModel.playSpeed);
            }
        }
        _initChatIconView() {
            if (this["BoxChat"] && sg.ViewBase.chatIconType && Proto.COMBAT_TYPE.TOWER == this._combatType) {
                let icon = this.createUnit("unit_chatIcon", sg.ViewBase.chatIconType);
                this["BoxChat"].addChild(icon);
            }
        }
    }
    mvc.SysBattle = SysBattle;
})(mvc || (mvc = {}));

