(function (mvc) {
    class UnitDamage extends ui.view.battle.unit_popDamageUI {
        static create() {
            return Laya.Pool.getItemByClass("POOL_UNIT_DAMAGE", UnitDamage);
        }
        recycle() {
            this.clearSelf();
            this.removeSelf();
            Laya.Pool.recover("POOL_UNIT_DAMAGE", this);
        }
        initView(pos, mode, data) {
            this.anchorX = this.anchorY = 0.5;
            this._pos = pos;
            this._mode = mode;
            this._data = data;
        }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            this.setPosition(this._pos);
            this._initByMode();
        }
        _initByMode() {
            if (this._mode == 1) {
                this._initModeNumber();
            }
            else if (this._mode == 2) {
                this._initModeImage();
            }
            else if (this._mode == 3) {
                this._initModeLabel();
            }
            let ani = this[this._data.ani];
            this._curAni = ani;
            this._curAni.on(Laya.Event.COMPLETE, this, this._onAniEnd);
            ani.play(0, false);
        }
        _initModeNumber() {
            let value = this._data.value;
            mgr.icon.drawTexture(this._data.font, this.fontNum);
            if (this._data.sign) {
                mgr.icon.drawTexture(this._data.sign, this.imgSign);
                this.imgSign.visible = true;
            }
            else {
                this.imgSign.visible = false;
            }
            this.fontNum.value = Math.abs(value).toString();
            this.fontNum.spaceX = this._data.spaceX || -5;
            this.boxNum.visible = true;
            this.imgTemp.visible = false;
            this.lblTemp.changeText("");
        }
        _initModeImage() {
            mgr.icon.drawTexture(this._data.skin, this.imgTemp);
            this.boxNum.visible = false;
            this.imgTemp.visible = true;
            this.lblTemp.changeText("");
        }
        _initModeLabel() {
            this.lblTemp.changeText(this._data.value);
            if (this._data.color) {
                this.lblTemp.color = this._data.color;
            }
            this.boxNum.visible = false;
            this.imgTemp.visible = false;
        }
        setPosition(pos) {
            this.x = pos.x;
            this.y = pos.y;
        }
        _onAniEnd() {
            this.recycle();
        }
        clearSelf() {
            this.alpha = 1;
            this.scaleX = this.scaleY = 1;
            this.aniBox.scaleX = this.aniBox.scaleY = 1;
            this.fontNum.value = "";
            this.fontNum.skin = "";
            this.imgSign.skin = "";
            this.imgSign.x = -26;
            this.imgTemp.skin = "";
            if (this._curAni) {
                this._curAni.off(Laya.Event.COMPLETE, this, this._onAniEnd);
                this._curAni.stop();
                this._curAni = null;
            }
            Laya.Tween.clearAll(this.aniBox);
            Laya.Tween.clearAll(this);
        }
    }
    mvc.UnitDamage = UnitDamage;
})(mvc || (mvc = {}));

