(function (mvc) {
    class BattleCtrl extends sg.CtrlBase {
        initCtrl() {
            this.model = mvc.battleModel;
        }
        registerMsg() {
            this.onMsg(Proto.COMBAT_TEST, this._onMsgTestBattle);
            this.onMsg(Proto.CLEAN_COMBAT_STATUS, this._onMsgCleanCombatStatus);
            this.onMsg(Proto.WATCH_COMBAT_VIDEO, this._onMsgWatchVideo);
            this.onMsg(Proto.QUERY_COMBAT_FORMATION, this._onMsgFormation);
            this.onMsg(Proto.SAVE_COMBAT_FORMATION, this._onMsgSaveFormation);
            this.onMsg(Proto.GOD_ON_BATTLE_ELEMENT_IN_FORMATION, this._onMsgChangeGodUseSlot);
        }
        _onMsgTestBattle(data) {
            this.model.startBattle(data.combat_notify, Proto.COMBAT_TYPE.TEST);
        }
        reqCleanBattleStatus() {
            let req = this.createProto(Proto.clean_combat_status_request);
            this.sendMsg(Proto.CLEAN_COMBAT_STATUS, req);
        }
        _onMsgCleanCombatStatus() {
        }
        reqWatchVideo(id, type) {
            let req = this.createProto(Proto.watch_combat_video_request);
            req.id = id;
            req.type = type;
            this.sendMsg(Proto.WATCH_COMBAT_VIDEO, req);
        }
        _onMsgWatchVideo(data) {
            if (data.type == 1) {
                this.model.startBattle(data.combat_notify, data.combat_notify.type, () => {
                    this.model.clearBattle();
                });
            }
            else {
                sg.uimgr.showUI("pop_battleRecord", data.combat_notify);
            }
        }
        reqFormation(type) {
            let req = this.createProto(Proto.query_combat_formation_request);
            req.type = type;
            this.sendMsg(Proto.QUERY_COMBAT_FORMATION, req);
        }
        _onMsgFormation(data) {
            this.model.fireEvent(mvc.BattleConst.EVT.FORMATION_INFO, data.info);
        }
        reqSaveFormation(type, artifact, formation, sword, rules, pets, gods) {
            let req = this.createProto(Proto.save_combat_formation_request);
            req.type = type;
            req.artifact_id = artifact;
            req.formation_id = formation;
            req.sword_id = sword;
            req.rules = rules;
            req.pets = pets;
            req.gods = gods;
            this.sendMsg(Proto.SAVE_COMBAT_FORMATION, req);
        }
        reqChangeGodUseSlot(arenaType, id, combat_soul) {
            let req = this.createProto(Proto.god_on_battle_element_in_formation_request);
            req.type = arenaType;
            req.id = id;
            req.combat_soul = combat_soul;
            this.sendMsg(Proto.GOD_ON_BATTLE_ELEMENT_IN_FORMATION, req);
        }
        _onMsgChangeGodUseSlot(data) {
            let info;
            if (data.type == mvc.BattleConst.FormationType.TopArena) {
                info = mvc.topArenaModel.vo.myFormation;
            }
            else if (data.type == mvc.BattleConst.FormationType.SuperArena) {
                info = mvc.athleticPalaceModel.athleticPalaceVo.myFormation;
            }
            else if (data.type == mvc.BattleConst.FormationType.GvgDefend || data.type == mvc.BattleConst.FormationType.GvgBattle) {
                info = mvc.readyFormationModel.getFormationByType(data.type);
            }
            if (info == null) {
                return;
            }
            for (let i = 0; i < info.gods.length; i++) {
                if (info.gods[i].god_id == data.id) {
                    info.gods[i].combat_element = data.combat_soul;
                    break;
                }
            }
            mvc.battleModel.fireEvent(mvc.BattleConst.EVT.FORMATION_INFO_SAVE_UPDATE, info);
        }
        _onMsgSaveFormation(data) {
            switch (data.info.type) {
                case mvc.BattleConst.FormationType.TopArena:
                    mvc.topArenaModel.vo.myFormation = data.info;
                    mvc.battleModel.fireEvent(mvc.BattleConst.EVT.FORMATION_INFO_SAVE, data.info);
                    sg.uimgr.showNotice(sg.translate("布阵成功"), "green");
                    break;
                case mvc.BattleConst.FormationType.SuperArena:
                    mvc.athleticPalaceModel.athleticPalaceVo.myFormation = data.info;
                    mvc.battleModel.fireEvent(mvc.BattleConst.EVT.FORMATION_INFO_SAVE, data.info);
                    sg.uimgr.showNotice(sg.translate("布阵成功"), "green");
                    break;
                case mvc.BattleConst.FormationType.GvgDefend:
                    mvc.readyFormationModel.updateFormation(data.info);
                    mvc.battleModel.fireEvent(mvc.BattleConst.EVT.FORMATION_INFO_SAVE, data.info);
                    sg.uimgr.showNotice(sg.translate("布阵成功"), "green");
                    break;
                case mvc.BattleConst.FormationType.GvgBattle:
                    mvc.readyFormationModel.updateFormation(data.info);
                    mvc.battleModel.fireEvent(mvc.BattleConst.EVT.FORMATION_INFO_SAVE, data.info);
                    sg.uimgr.showNotice(sg.translate("布阵成功"), "green");
                    break;
            }
        }
    }
    mvc.BattleCtrl = BattleCtrl;
})(mvc || (mvc = {}));

