(function (mvc) {
    class PopAddCoinsSuperPanel extends ui.view.superArena.pop_addCoinsSuperUI {
        constructor() {
            super(...arguments);
            this._bet_count = 0;
        }
        initView(data) {
            this._model = mvc.athleticPalaceModel;
            this._ctrl = mvc.athleticPalaceCtrl;
            this._data = data;
        }
        initCtrlEvent() {
            this.btnOk.on(Laya.Event.CLICK, this, this._onBtnOK);
            this.btnAddTen.on(Laya.Event.CLICK, this, this._onBtnAddTen);
            this.btnSubTen.on(Laya.Event.CLICK, this, this._onBtnSubTen);
        }
        onAwake() {
            super.onAwake();
            let icon = mgr.toolsMgr.getIconById(mvc.MainConst.ITEM_ID.SUPER_ARENA_COIN);
            icon = mgr.icon.getIconPath(icon);
            mgr.icon.drawTexture(icon, this.imgCoinIcon);
        }
        onEnable() {
            super.onEnable();
            let vo = this._model.athleticPalaceVo;
            let data = this._data;
            this.lblCoin.text = vo.coin + "";
            let limitCount = 0;
            if (data.type == 1) {
                let data1 = this._data.data1;
                this._radio = data1.radio;
                limitCount = data1.maxLimit - data1.have;
                this._callArgs = { type: data.type, pid: null, coinCount: 0 };
                this.lblName.visible = false;
                this.lblStage.text = sg.translate('组合竞猜');
                this.lblGetText.text = sg.translate('猜中最高获得竞猜币：');
                this.limit.text = mgr.UIAssist.$(sg.translate('(本场最大竞猜额度：{1})'), data1.maxLimit);
                this._bet_count = data1.have;
            }
            else {
                let rateInfo = data.data2.rateInfo, site = data.data2.site, have = data.data2.have;
                let head = site == 1 ? vo.betInfo.group.head1 : vo.betInfo.group.head2;
                this.lblName.visible = true;
                this.lblName.text = `[S${head.svr_id}]${head.name}`;
                this._callArgs = { type: data.type, pid: head.player_id, coinCount: 0 };
                let limitData = mgr.toolsMgr.getGlobalVoById('superarena_guess_limit2', 1);
                if (rateInfo.stage == mvc.AthleticPalaceConst.RaceState.Pre) {
                    limitCount = limitData[0][1];
                    this.lblStage.text = sg.translate('盲猜');
                }
                else {
                    limitCount = limitData[1][1];
                    this.lblStage.text = sg.translate('常规竞猜');
                }
                this.lblGetText.text = sg.translate('猜中约可获得竞猜币：');
                this.limit.text = mgr.UIAssist.$(sg.translate('(本场最大竞猜额度：{1})'), limitCount);
                limitCount -= have;
                this._bet_count = have;
                let f = mgr.toolsMgr.getGlobalVoById("superarena_lossper_coefficient", 1);
                let bet_count1 = rateInfo.bet_player1, bet_count2 = rateInfo.bet_player2;
                if (site == 1) {
                    if (rateInfo.stage == mvc.AthleticPalaceConst.RaceState.Pre) {
                        this._radio = rateInfo.rate1 / 100;
                    }
                    else {
                        let r_count = bet_count1 - bet_count2, r_br_Limit = r_count / Math.max(bet_count1 + bet_count2, 1) * f;
                        this._radio = rateInfo.rate1 / 100 - r_br_Limit;
                        this._radio = Math.round(this._radio * 100) / 100;
                    }
                }
                else {
                    if (rateInfo.stage == mvc.AthleticPalaceConst.RaceState.Pre) {
                        this._radio = rateInfo.rate2 / 100;
                    }
                    else {
                        let r_count = bet_count1 - bet_count2, r_br_Limit = r_count / Math.max(bet_count1 + bet_count2, 1) * f;
                        this._radio = rateInfo.rate2 / 100 + r_br_Limit;
                        this._radio = Math.round(this._radio * 100) / 100;
                    }
                }
            }
            this.unitNum.minValue = 0;
            this.unitNum.maxValue = Math.min(limitCount, vo.coin);
            this.unitNum.openEditable(this.unitNum.maxValue);
            this.unitNum.textFunc = this._onValueChange.bind(this);
            this.unitNum.value = 0;
        }
        _onBtnAddTen() {
            this.unitNum.value = this.unitNum.value + 10;
        }
        _onBtnSubTen() {
            this.unitNum.value = this.unitNum.value - 10;
        }
        _onValueChange(v) {
            this.lblAll.text = Math.floor(v + this._bet_count) + "";
            this.lblGet.text = Math.floor((v + this._bet_count) * this._radio) + "";
            return v + "";
        }
        _onBtnOK() {
            let v = this.unitNum.value;
            if (v <= 0) {
                sg.uimgr.showNotice(sg.translate("请选择确认数量"));
                return;
            }
            if (this._data.call) {
                this._callArgs.coinCount = v;
                this._data.call.runWith(this._callArgs);
            }
            this.closeSelf();
        }
    }
    mvc.PopAddCoinsSuperPanel = PopAddCoinsSuperPanel;
})(mvc || (mvc = {}));

