(function (mvc) {
    class PopMyRaceCrossBoxPanel extends ui.view.superArena.pop_myRaceCrossBoxUI {
        initView() {
            this._model = mvc.athleticPalaceModel;
        }
        initSendMsg() {
            if (!this._model.severs || this._model.severs.length == 0) {
                mvc.athleticPalaceCtrl.reqSeverList();
            }
        }
        initModelEvent() {
            this.bindModelEvent(this._model, mvc.AthleticPalaceConst.EVT.UPDATE_SEVERS, this._updateSeverList);
        }
        initCtrlEvent() {
            this.btnClose.on(Laya.Event.CLICK, this, this.closeSelf);
        }
        onEnable() {
            super.onEnable();
            this._updateSeverList();
        }
        _updateSeverList() {
            if (!this._model.severs || this._model.severs.length == 0) {
                return;
            }
            this._updateCompetitionArea();
        }
        _updateCompetitionArea() {
            let count = 4;
            let severs = [], tsevers = this._model.severs, mySever = mvc.roleModel.roleInfo.serverId;
            for (let i = 0; i < tsevers.length; i++) {
                let ismy = false;
                for (let j = 0; j < tsevers[i].length; j++) {
                    if (tsevers[i][j] == mySever) {
                        ismy = true;
                        break;
                    }
                }
                if (ismy) {
                    severs.unshift(tsevers[i]);
                }
                else {
                    severs.push(tsevers[i]);
                }
            }
            for (let i = 1; i <= count; i++) {
                let zone = this['zone' + i];
                let severData = severs[i - 1];
                this._updateCompetitionAreaInfoBox(zone, severData);
            }
        }
        _updateCompetitionAreaInfoBox(zone, data) {
            if (data == null) {
                zone.visible = false;
                return;
            }
            let title = zone.getChildByName('title');
            let listCross = zone.getChildByName('listCross');
            zone.visible = true;
            if (title) {
                let severInfo, idx = 0;
                while (severInfo == null && idx < data.length) {
                    severInfo = this._model.getCompetitionAreaInfoToSeverId(data[idx]);
                    idx++;
                }
                title.text = severInfo ? severInfo.name : sg.translate('赛区名字：');
            }
            if (listCross) {
                if (listCross.renderHandler == null) {
                    listCross.renderHandler = this.createHandler(this, this._onListCrossRender, null, false);
                    listCross.vScrollBarSkin = "";
                }
                listCross.array = data;
            }
        }
        _onListCrossRender(cell, index) {
            if (cell.dataSource == null) {
                return;
            }
            let lblSever = cell.getChildByName('lblSever');
            if (lblSever) {
                lblSever.text = "[S" + cell.dataSource + "]";
            }
        }
    }
    mvc.PopMyRaceCrossBoxPanel = PopMyRaceCrossBoxPanel;
})(mvc || (mvc = {}));

