(function (mvc) {
    class PopSuperArenaChangeArtifact extends ui.view.topArena.pop_artifactArrangeUI {
        initView() {
            this._model = mvc.athleticPalaceModel;
            this._ctrl = mvc.athleticPalaceCtrl;
        }
        initSendMsg() {
        }
        initModelEvent() {
        }
        initCtrlEvent() {
            this.list.renderHandler = this.createHandler(this, this._listRender, undefined, false);
            this.list.selectHandler = this.createHandler(this, this._onListSelect, undefined, false);
            this.list.vScrollBarSkin = "";
            this.btnEquip.on(Laya.Event.CLICK, this, this._onBtnEquip);
        }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            let f = this._model.athleticPalaceVo.myFormation;
            this._cur = f.artifact.unique_id;
            let vos = mvc.bagModel.getItemsByType(mvc.BagConst.BagType.Artifact);
            vos.sort((a, b) => {
                let acfg = a.getCfg();
                let bcfg = b.getCfg();
                if (acfg.quality != bcfg.quality) {
                    return bcfg.quality - acfg.quality;
                }
                if (a.level != b.level) {
                    return b.level - a.level;
                }
                return a.id - b.id;
            });
            this.list.array = vos;
            if (vos.length > 0) {
                let idx = 0;
                for (let i = 0; i < vos.length; i++) {
                    if (vos[i].bagId == f.artifact.unique_id) {
                        idx = i;
                        break;
                    }
                }
                this.list.selectedIndex = idx;
            }
            else {
                this.list.selectedIndex = -1;
            }
        }
        onDisable() {
            this.list.selectedIndex = -1;
            this.list.array = undefined;
            super.onDisable();
            mvc.athleticPalaceModel.fireEvent(mvc.AthleticPalaceConst.EVT.FORMATION_NUM_CLEAR);
        }
        _onListSelect() {
            let data = this.list.selectedItem;
            if (!data) {
                this.unitIcon.visible = false;
                this.listAttr.array = undefined;
                this.imgSecret.visible = false;
                return;
            }
            this.unitIcon.visible = true;
            this.listAttr.array = mvc.PropertyModel.generateListData(data.attr);
            this.unitIcon.initView(data, false);
            if (data.level >= 0) {
                this.unitIcon.lblNum.text = "Lv." + data.level;
            }
            if (mvc.artifactModel.getIsInSecret(data.bagId)) {
                this.imgSecret.visible = true;
                let id = mvc.artifactModel.getSecretIdByBagId(data.bagId);
                let cfg = sg.dbmgr.get("artifact_secret", id);
                mgr.icon.drawTexture(mgr.icon.getIconPath(cfg.icon), this.imgSecret);
            }
            else {
                this.imgSecret.visible = false;
            }
            if (data.bagId == this._cur) {
                this.btnEquip.label = sg.translate("已装备");
                this.btnEquip.disabled = true;
            }
            else {
                this.btnEquip.label = sg.translate("更换");
                this.btnEquip.disabled = false;
            }
        }
        _listRender(cell) {
            let data = cell.dataSource;
            if (!data)
                return;
            let icon = cell.getChildByName("icon");
            let imgSecret = cell.getChildByName("imgSecret");
            icon.initView(data, false);
            if (data.level >= 0) {
                icon.lblNum.text = "Lv." + data.level;
            }
            if (mvc.artifactModel.getIsInSecret(data.bagId)) {
                imgSecret.visible = true;
                let id = mvc.artifactModel.getSecretIdByBagId(data.bagId);
                let cfg = sg.dbmgr.get("artifact_secret", id);
                mgr.icon.drawTexture(mgr.icon.getIconPath(cfg.icon), imgSecret);
            }
            else {
                imgSecret.visible = false;
            }
        }
        _onBtnEquip() {
            let item = this.list.selectedItem;
            if (!item || item.bagId == this._cur)
                return;
            this._model.reqSetArtifact(item.bagId);
            this.closeSelf();
        }
    }
    mvc.PopSuperArenaChangeArtifact = PopSuperArenaChangeArtifact;
})(mvc || (mvc = {}));

