var mvc;
(function (mvc) {
    class PopSuperArenaChangePet extends ui.view.topArena.pop_petArrangeUI {
        constructor() {
            super(...arguments);
            this._cbIdxs = [];
        }
        initView() {
            this._model = mvc.athleticPalaceModel;
            this._ctrl = mvc.athleticPalaceCtrl;
        }
        initCtrlEvent() {
            this.listPet.renderHandler = this.createHandler(this, this._listPetRender, undefined, false);
            this.listPet.selectHandler = this.createHandler(this, this._onListPetSelect, undefined, false);
            this.cbType.selectHandler = this.createHandler(this, this._onCbTypeSelect, undefined, false);
            this.cbType.scrollBarSkin = "";
            this.listSkill.renderHandler = this.createHandler(this, this._listSkillRender, undefined, false);
            this.listSkill.mouseHandler = this.createHandler(this, this._onListSkillClick, undefined, false);
            this.listSkill.vScrollBarSkin = "";
            this.btnSave.on(Laya.Event.CLICK, this, this._onBtnSave);
        }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            let f = this._model.athleticPalaceVo.myFormation;
            this._cur = [];
            for (let type of f.pet.combat_type) {
                let pet;
                let skill;
                for (let p of f.pet.pets) {
                    if (p.type == type) {
                        pet = p;
                        break;
                    }
                }
                for (let s of f.pet.skills) {
                    if (s[0] == type) {
                        skill = s;
                        break;
                    }
                }
                this._cur.push([skill[0], skill[1]]);
            }
            while (this._cur.length < 3) {
                this._cur.push([0, 0]);
            }
            this.listPet.array = this._cur;
            this.listPet.selectedIndex = 0;
        }
        onDisable() {
            this._cur = null;
            this.listPet.array = null;
            this.listPet.selectedIndex = -1;
            this.listSkill.array = null;
            this.listSkill.selectedIndex = -1;
            this.cbType.labels = null;
            this.cbType.selectedIndex = -1;
            super.onDisable();
            mvc.athleticPalaceModel.fireEvent(mvc.AthleticPalaceConst.EVT.FORMATION_NUM_CLEAR);
        }
        _listPetRender(cell) {
            let data = cell.dataSource;
            if (!data)
                return;
            let itemPet = cell.getChildByName("itemPet");
            let petvo = mvc.petModel.getCurPetByType(data[0]);
            itemPet.directUpdate(petvo, false);
        }
        _onListPetSelect(idx) {
            if (idx < 0) {
                this.cbType.labels = "";
                this.listSkill.array = undefined;
                this.listSkill.selectedIndex = -1;
                return;
            }
            let typeMap = {};
            for (let i = 0; i < this._cur.length; i++) {
                if (i != idx && this._cur[i]) {
                    typeMap[this._cur[i][0]] = true;
                }
            }
            let allType = mvc.petModel.getAllPetType();
            this._cbIdxs.length = 0;
            let lbls = "";
            let selectIdx = 0;
            let curType = this._cur[idx][0];
            for (let t of allType) {
                if (typeMap[t])
                    continue;
                this._cbIdxs.push(t);
                if (lbls)
                    lbls += ",";
                let cfg = sg.dbmgr.get("pet_petRace", t);
                lbls += cfg.raceName;
                if (t == curType) {
                    selectIdx = this._cbIdxs.length - 1;
                }
            }
            this.cbType.labels = lbls;
            this.cbType.selectedIndex = selectIdx;
        }
        _onCbTypeSelect(idx) {
            if (idx < 0) {
                this.listSkill.array = undefined;
                this.listSkill.selectedIndex = -1;
                return;
            }
            let type = this._cbIdxs[idx];
            let cfg = sg.dbmgr.get("skill_skillGroup", type);
            let skills = [];
            for (let s of cfg.group) {
                let skillVo = mvc.petModel.getSkillVOByGroup(type, s);
                if (skillVo)
                    skills.push(skillVo);
            }
            for (let s of cfg.groupSenior) {
                let skillVo = mvc.petModel.getSkillVOByGroup(type, s);
                if (skillVo)
                    skills.push(skillVo);
            }
            for (let s of cfg.groupChaos) {
                let skillVo = mvc.petModel.getSkillVOByGroup(type, s);
                if (skillVo)
                    skills.push(skillVo);
            }
            this.listSkill.array = skills;
            let curPet = this.listPet.selectedItem;
            let select = -1;
            if (type == curPet[0]) {
                for (let i = 0; i < skills.length; i++) {
                    if (skills[i].id == curPet[1]) {
                        select = i;
                        break;
                    }
                }
            }
            this.listSkill.selectedIndex = select;
            this.listSkill.scrollTo(select);
        }
        _listSkillRender(item) {
            let data = item.dataSource;
            if (!data)
                return;
            let lblName = item.getChildByName("lblName");
            let lblLv = item.getChildByName("lblLv");
            let icon = item.getChildByName("imgIcon");
            let lblDesc = item.getChildByName("lblDesc");
            let imgLineup = item.getChildByName("imgLineup");
            lblName.text = sg.translate("天赋技能：") + data.name;
            lblLv.text = "Lv." + data.Lv;
            mgr.icon.drawTexture(mgr.icon.getIconPath(data.getImgPath()), icon);
            lblDesc.text = data.cfg.desc;
            let curPet = this.listPet.selectedItem;
            imgLineup.visible = data.id == curPet[1];
        }
        _onListSkillClick(evt, idx) {
            if (evt.type != Laya.Event.CLICK || idx < 0)
                return;
            let data = this.listSkill.getItem(idx);
            if (!data)
                return;
            let skillCfg = sg.dbmgr.get("skill_skillGroup", 1);
            let group = sg.dbmgr.get("skill_skill", data.id).group;
            if (skillCfg.groupChaos.indexOf(group) != -1) {
                let cur = mvc.petModel.getSkillGroupById(this._cur);
                if (mvc.petModel.getEliminateIsBattleChaosSkillByGroup2(group, this.listPet.selectedIndex, cur)) {
                    sg.uimgr.showNotice(sg.translate("该混沌系技能已出战"));
                    return;
                }
            }
            let curPet = this.listPet.selectedItem;
            curPet[0] = this._cbIdxs[this.cbType.selectedIndex];
            curPet[1] = data.id;
            this.listPet.refresh();
            this.listSkill.refresh();
        }
        _onBtnSave() {
            if (!this._cur)
                return;
            let pet = [];
            for (let p of this._cur) {
                if (p[0]) {
                    pet.push(p);
                }
            }
            this._model.reqSetPet(pet);
            this.closeSelf();
        }
        _checkHaveChaosSkill() {
            for (let cur of this._cur) {
                if (cur[1] == 0)
                    continue;
                let skillCfg = sg.dbmgr.get("skill_skillGroup", 1);
                let group = sg.dbmgr.get("skill_skill", cur[1]).group;
                if (skillCfg.groupChaos.indexOf(group) != -1) {
                    return true;
                }
            }
            return false;
        }
        _getChaosSkillType() {
            for (let type of this._cur) {
                let skillCfg = sg.dbmgr.get("skill_skillGroup", 1);
                let group = sg.dbmgr.get("skill_skill", type[1]).group;
                if (skillCfg.groupChaos.indexOf(group) != -1) {
                    return type[0];
                }
            }
            return 0;
        }
    }
    mvc.PopSuperArenaChangePet = PopSuperArenaChangePet;
})(mvc || (mvc = {}));

var mvc;
(function (mvc) {
    class PopSuperArenaChangeRule extends ui.view.topArena.pop_ruleArrangeUI {
        constructor() {
            super(...arguments);
            this._typeArr = [];
        }
        initView() {
            this._model = mvc.athleticPalaceModel;
        }
        initSendMsg() {
        }
        initModelEvent() {
            this.bindModelEvent(mvc.battleModel, mvc.BattleConst.EVT.FORMATION_INFO_SAVE, this._onEquipSucc);
        }
        initCtrlEvent() {
            this.list.renderHandler = this.createHandler(this, this._listRender, undefined, false);
            this.list.selectHandler = this.createHandler(this, this._onListSelect, undefined, false);
            this.list.vScrollBarSkin = "";
            this.tabType.selectHandler = this.createHandler(this, this._onTabSelect, undefined, false);
            this.btnEquip.on(Laya.Event.CLICK, this, this._onBtnEquip);
        }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            this._initData();
        }
        onDisable() {
            this.list.array = null;
            this.list.selectedIndex = -1;
            this.tabType.selectedIndex = -1;
            super.onDisable();
            mvc.athleticPalaceModel.fireEvent(mvc.AthleticPalaceConst.EVT.FORMATION_NUM_CLEAR);
        }
        _initData() {
            this._typeArr.length = 0;
            this._curIn = null;
            this._curOut = null;
            this._equipInId = 0;
            this._equipOutId = 0;
            let f = this._model.athleticPalaceVo.myFormation;
            let equipMap = {};
            for (let e of f.rule_pos_infos) {
                equipMap[e[0]] = e[1];
            }
            for (let i = 1; i <= 2; i++) {
                let cfgs = sg.dbmgr.getArray("rule_rule", { battleType: i });
                let arr = [];
                for (let cfg of cfgs) {
                    let lv = mvc.ruleModel.getRuleLv(cfg.id);
                    if (!lv)
                        continue;
                    let lvCfg = sg.dbmgr.getUnique("rule_ruleLvUp", cfg.id, lv);
                    let skillCfg = sg.dbmgr.get("skill_skill", lvCfg.skillId);
                    let obj = {
                        id: cfg.id,
                        lblName: cfg.name,
                        lblType: cfg.typeName,
                        clipQua: cfg.quality - 1,
                        imgIcon: mgr.icon.getIconPath(cfg.icon),
                        itemId: cfg.itemId,
                        maxLv: cfg.maxLv,
                        desc: skillCfg.desc
                    };
                    arr.push(obj);
                    if (equipMap[i] == obj.id) {
                        if (i == 1) {
                            this._curIn = obj;
                            this._equipInId = obj.id;
                        }
                        else {
                            this._curOut = obj;
                            this._equipOutId = obj.id;
                        }
                    }
                }
                arr.sort((a, b) => {
                    return b.clipQua - a.clipQua;
                });
                this._typeArr.push(arr);
            }
            this.tabType.selectedIndex = 0;
        }
        _updateIn() {
            let data = this._curIn;
            if (data) {
                this.boxIconIn.visible = true;
                this.clipQuaIn.index = data.clipQua;
                mgr.icon.drawTexture(data.imgIcon, this.imgIconIn);
                this.lblLevelIn.text = "Lv." + mvc.ruleModel.getRuleLv(data.id);
                this.lblNameIn.text = data.lblName;
                this.lblDescIn.text = data.desc;
            }
            else {
                this.boxIconIn.visible = false;
                this.lblNameIn.text = "";
                this.lblDescIn.text = "";
            }
        }
        _updateOut() {
            let data = this._curOut;
            if (data) {
                this.boxIconOut.visible = true;
                this.clipQuaOut.index = data.clipQua;
                mgr.icon.drawTexture(data.imgIcon, this.imgIconOut);
                this.lblLvOut.text = "Lv." + mvc.ruleModel.getRuleLv(data.id);
                this.lblNameOut.text = data.lblName;
                this.lblDescOut.text = data.desc;
            }
            else {
                this.boxIconOut.visible = false;
                this.lblNameOut.text = "";
                this.lblDescOut.text = "";
            }
        }
        _onTabSelect(idx) {
            if (idx < 0)
                return;
            let arr = this._typeArr[idx];
            this.list.array = arr;
            if (arr.length > 0) {
                let index = 0;
                let cur = idx == 0 ? this._equipInId : this._equipOutId;
                for (let i = 0; i < arr.length; i++) {
                    if (arr[i].id == cur) {
                        index = i;
                        break;
                    }
                }
                this.list.selectedIndex = index;
            }
            else {
                this.list.selectedIndex = -1;
                idx == 0 ? this._updateIn() : this._updateOut();
            }
            if (idx == 0) {
                for (let d of this._typeArr[1]) {
                    if (d.id == this._equipOutId) {
                        this._curOut = d;
                        break;
                    }
                }
                this._updateOut();
            }
            else {
                for (let d of this._typeArr[0]) {
                    if (d.id == this._equipInId) {
                        this._curIn = d;
                        break;
                    }
                }
                this._updateIn();
            }
        }
        _listRender(cell) {
            let data = cell.dataSource;
            if (!data)
                return;
            let lblLevel = cell.getChildByName("lblLevel");
            let imgWear = cell.getChildByName("imgWear");
            let equiped = this.tabType.selectedIndex == 0 ? this._equipInId : this._equipOutId;
            imgWear.visible = data.id == equiped;
            lblLevel.text = "Lv." + mvc.ruleModel.getRuleLv(data.id);
        }
        _onListSelect(idx) {
            if (idx < 0)
                return;
            let data = this.list.selectedItem;
            let equip;
            if (this.tabType.selectedIndex == 0) {
                this._curIn = data;
                this._updateIn();
                equip = this._equipInId;
            }
            else {
                this._curOut = data;
                this._updateOut();
                equip = this._equipOutId;
            }
            if (data.id == equip) {
                this.btnEquip.disabled = true;
                this.btnEquip.label = sg.translate("已装备");
            }
            else {
                this.btnEquip.disabled = false;
                this.btnEquip.label = sg.translate("装备");
            }
        }
        _onEquipSucc() {
            let f = this._model.athleticPalaceVo.myFormation;
            let equipMap = {};
            for (let e of f.rule_pos_infos) {
                equipMap[e[0]] = e[1];
            }
            let arr = this._typeArr[0];
            for (let obj of arr) {
                if (equipMap[1] == obj.id) {
                    this._curIn = obj;
                    this._equipInId = obj.id;
                    break;
                }
            }
            arr = this._typeArr[1];
            for (let obj of arr) {
                if (equipMap[2] == obj.id) {
                    this._curOut = obj;
                    this._equipOutId = obj.id;
                    break;
                }
            }
            this._onListSelect(this.list.selectedIndex);
            this.list.refresh();
        }
        _onBtnEquip() {
            let posInfo = [];
            if (this._curIn) {
                posInfo.push([1, this._curIn.id]);
            }
            if (this._curOut) {
                posInfo.push([2, this._curOut.id]);
            }
            if (posInfo.length > 0) {
                this._model.reqSetRule(posInfo);
            }
            else {
                sg.uimgr.showNotice(sg.translate("请选择天地法则"));
            }
        }
    }
    mvc.PopSuperArenaChangeRule = PopSuperArenaChangeRule;
})(mvc || (mvc = {}));

