            let vo = this._model.athleticPalaceVo;
            if (vo == null) {
                return;
            }
            let count = vo.top_three.length;
            for (let i = 0; i < 3; i++) {
                let p;
                if (i < count) {
                    p = vo.top_three[i];
                }
                this._setShowBox(i + 1, p);
            }
            this.stopTimer(this._onTimer);
