(function (mvc) {
    class PopSuperArenaZoneMessageView extends ui.view.superArena.pop_superArenaZoneMessageUI {
        constructor() {
            super();
            this._model = mvc.athleticPalaceModel;
            this._ctrl = mvc.athleticPalaceCtrl;
            this._vo = this._model.athleticPalaceVo;
            this._arenaId = this._model.getMyAreaId();
        }
        initSendMsg() {
        }
        initModelEvent() {
            this.bindModelEvent(this._model, mvc.AthleticPalaceConst.EVT.UPDATE_RIDGE_DIVSION, this.closeSelf);
        }
        initCtrlEvent() {
            this.btnActivation.on(Laya.Event.CLICK, this, this._onBtnActivation);
            this.list.selectEnable = true;
            this.list.renderHandler = this.createHandler(this, this._onListRender, null, false);
            this.list.selectHandler = this.createHandler(this, this._onListSelect, null, false);
            this.inputName.on(Laya.Event.INPUT, this, this._onInputNameInput);
        }
        onEnable() {
            super.onEnable();
            this._currData = this._model.getMyCompetitionAreaInfo();
            this._changeData = { id: this._currData.id, name: this._currData.name, iconId: this._currData.icon_id, icon: this._currData.icon };
            this._updataView();
        }
        onDisable() {
            super.onDisable();
        }
        _updataView() {
            this.btnActivation.visible = this._currData.count == 0;
            this.lblEmpty.visible = !this.btnActivation.visible;
            if (this._config == null) {
                this._config = this._model.getArenaConfig();
            }
            this.list.array = this._config;
        }
        _onListSelect(idx) {
            let info = this.list.array[idx];
            let style = this._vo.getIsSelectIcon(info.id);
            if (style) {
                sg.uimgr.showNotice(sg.translate('该图标已被其他赛区选择'));
                return;
            }
            this._changeData.iconId = info.id;
            this._changeData.icon = info.image;
            this.list.refresh();
        }
        _onListRender(cell, index) {
            if (cell.dataSource == null) {
                return;
            }
            let config = cell.dataSource;
            let bg = cell.getChildByName('bg');
            let flagImage = cell.getChildByName('flagImage');
            let select = cell.getChildByName('select');
            let url = 'ui/superArena/' + config.image + '.png';
            mgr.icon.drawTexture(url, flagImage);
            let style = this._model.getArenaIconGary(config.id, this._arenaId);
            select.visible = style == 2 || config.id == this._changeData.iconId;
            flagImage.disabled = style == 1;
        }
        _onBtnActivation(e) {
            if (this._currData.count > 0) {
                return;
            }
            if (this._changeData.name == this._currData.name && this._changeData.iconId == this._currData.icon_id) {
                sg.uimgr.showNotice(sg.translate('未作任何修改'));
                return;
            }
            if (this._vo.isExistAreaName(this._changeData)) {
                return sg.uimgr.showNotice(sg.translate('赛区名已存在'));
            }
            if (this._callBack == null) {
                this._callBack = this.createHandler(this, this._secondaryConfirmationCall, null, false);
            }
            sg.uimgr.showUI("pop_superArenaZoneMessageSurePanel", this._currData, this._changeData, this._callBack);
        }
        _secondaryConfirmationCall(data) {
            this._ctrl.reqRidgeDivision(data.id, data.iconId, data.name);
        }
        _onInputNameInput() {
            this._changeData.name = this.inputName.text;
        }
    }
    mvc.PopSuperArenaZoneMessageView = PopSuperArenaZoneMessageView;
})(mvc || (mvc = {}));

var mvc;
(function (mvc) {
    class UnitCombinatorialGuessingItem extends ui.view.superArena.unit_combinatorialGuessingUI {
        constructor() {
            super(...arguments);
            this._index = 0;
        }
        onEnable() {
            super.onEnable();
            this.btnOn1.on(Laya.Event.CLICK, this, this._onBtnClick);
            this.btnOn2.on(Laya.Event.CLICK, this, this._onBtnClick);
            this.btnOff1.on(Laya.Event.CLICK, this, this._onBtnClick);
            this.btnOff2.on(Laya.Event.CLICK, this, this._onBtnClick);
        }
        onDisable() {
            super.onDisable();
            this.ani1.stop();
            this.clipBattle.stop();
        }
        setData(betPlayer, cell, index, title, showRes, playAni) {
            let data = this.dataSource;
            this._setPlayerInfo(this.box1, data.head1);
            this._setPlayerInfo(this.box2, data.head2);
            this.btnOn1.visible = betPlayer == data.head1.player_id;
            this.btnOn2.visible = betPlayer == data.head2.player_id;
            if (betPlayer) {
                this.btnOff1.mouseEnabled = !this.btnOn1.visible;
                this.btnOff2.mouseEnabled = !this.btnOn2.visible;
            }
            else {
                this.btnOff1.mouseEnabled = this.btnOff2.mouseEnabled = true;
            }
            this._touchCell = cell;
            this._index = index;
            this.title.text = title;
            if (data.winner != 0 && betPlayer != 0 && showRes) {
                this.true.visible = data.winner == betPlayer;
                this.wrong.visible = !this.true.visible;
            }
            else {
                this.true.visible = this.wrong.visible = false;
            }
            if (playAni) {
                this.clipBattle.visible = true;
                this.wrong.visible = this.true.visible = false;
                this.clipBattle.play();
            }
            else {
                this.clipBattle.visible = false;
                this.clipBattle.stop();
            }
        }
        _setPlayerInfo(box, head) {
            if (!head || head.player_id <= 0) {
                box.visible = false;
                return;
            }
            box.visible = true;
            let player = box.getChildByName('player');
            let lblName = box.getChildByName('lblName');
            let flag = box.getChildByName('flag');
            if (player) {
                let iconPath = mgr.ComFunMgr.getHeadIcon(head.head_icon, head.sex);
                player.initView({ iconPath: iconPath, headFrameId: head.head_frame_id, level: head.level }, head.player_id);
            }
            if (lblName) {
                lblName.text = '[' + head.svr_id + ']' + head.name;
                this._setLabColor(lblName, head.ridge_division == mvc.athleticPalaceModel.getMyAreaId());
            }
            if (flag) {
                let areaInfo = mvc.athleticPalaceModel.athleticPalaceVo.getArenaIcon(head.ridge_division);
                if (areaInfo != '')
                    mgr.icon.drawTexture(areaInfo, flag);
            }
        }
        _setLabColor(lb, isMy) {
            if (isMy) {
                lb.color = '#3bb544';
                lb.strokeColor = '#0d2809';
            }
            else {
                lb.color = '#ffffff';
                lb.strokeColor = '#000000';
            }
        }
        _onBtnClick(evt) {
            let data = this.dataSource;
            let player_id;
            switch (evt.target) {
                case this.btnOn1:
                case this.btnOff1:
                    player_id = data.head1.player_id;
                    break;
                case this.btnOn2:
                case this.btnOff2:
                    player_id = data.head2.player_id;
                    break;
            }
            if (this._touchCell) {
                this._touchCell.runWith({ id: player_id, idx: this._index, name: this.title.text });
            }
            this.btnOn1.visible = player_id == data.head1.player_id;
            this.btnOn2.visible = !this.btnOn1.visible;
        }
        playAni() {
            this.ani1.play(0, false);
        }
    }
    mvc.UnitCombinatorialGuessingItem = UnitCombinatorialGuessingItem;
})(mvc || (mvc = {}));

