            this.lblName2.text = `[S${head.svr_id}]${head.name}`;
            this.lblGuild2.text = head.guild_id ? head.guild_name : "";
            divisionInfo = vo.getPlayerAreaInfo(head.ridge_division);
            if (divisionInfo) {
                this.flag2.visible = true;
                mgr.icon.drawTexture(divisionInfo.getArenaIcon(), this.flag2);
                this.lblGuild2.text = divisionInfo.name;
            }
            else {
                this.lblGuild2.text = '';
            }
            if (curState == mvc.AthleticPalaceConst.RaceState.End && info.group.winner) {
                this.imgRst1.visible = true;
                this.imgRst2.visible = true;
                let is1Win = info.group.winner == info.group.head1.player_id;
                let url = is1Win ? "ui_langs/cn/ui/topArena/img_font_com_shengli.png" : "ui_langs/cn/ui/topArena/img_font_com_shibai.png";
                mgr.icon.drawTexture(url, this.imgRst1);
                url = is1Win ? "ui_langs/cn/ui/topArena/img_font_com_shibai.png" : "ui_langs/cn/ui/topArena/img_font_com_shengli.png";
                mgr.icon.drawTexture(url, this.imgRst2);
            }
            else {
                this.imgRst1.visible = false;
                this.imgRst2.visible = false;
            }
            let rateInfo;
            for (let i in info.rate_list) {
                if (info.rate_list[i].stage == curState) {
                    rateInfo = info.rate_list[i];
                    break;
                }
            }
            if (rateInfo == null) {
                rateInfo = info.rate_list[0];
            }
            this._rateInfo = rateInfo;
            if (rateInfo) {
                let bet_count1 = 0, bet_count2 = 0;
                if (rateInfo.stage != mvc.AthleticPalaceConst.RaceState.Pre) {
                    bet_count1 = rateInfo.bet_player1, bet_count2 = rateInfo.bet_player2;
                }
                let f = mgr.toolsMgr.getGlobalVoById("superarena_lossper_coefficient", 1);
                let r_count = bet_count1 - bet_count2, r_br_Limit = r_count / Math.max(bet_count1 + bet_count2, 1) * f;
                let ra = rateInfo.rate1 / 100 - r_br_Limit;
                let rb = rateInfo.rate2 / 100 + r_br_Limit;
                ra = Math.round(ra * 100) / 100;
                rb = Math.round(rb * 100) / 100;
                if (info.group.head1.player_id != rateInfo.player_id1) {
                    let ta = ra;
                    ra = rb;
                    rb = ta;
                }
                this.proBet.value = ra / (ra + rb);
                this.lblOdds1.text = ra + "";
                this.lblOdds2.text = rb + "";
            }
            else {
                this.lblOdds1.text = "";
                this.lblOdds2.text = "";
            }
            let curRound = this._model.getCurrRound();
            let betRound = this._model.getRound(info.group.type, info.group.group_id);
            this.btnRecord.visible = info.group.replay_list && info.group.replay_list.length > 0 && curState >= mvc.AthleticPalaceConst.RaceState.Battle && curRound > betRound;
            this.listResult1.visible = false;
            this.listResult2.visible = false;
            this.btnBet1.disabled = true;
