(function (mvc) {
    class UnitSuperArenaRace32Panel extends ui.view.superArena.unit_superArenaRace32UI {
        constructor() {
            super();
            this._group = 1;
            this.grayFilter = new Laya.ColorFilter([0.3086, 0.6094, 0.082, 0, 0, 0.3086, 0.6094, 0.082, 0, 0, 0.3086, 0.6094, 0.082, 0, 0, 0, 0, 0, 1, 0]);
            this._model = mvc.athleticPalaceModel;
        }
        initCtrlEvent() {
            let TYPE = mvc.AthleticPalaceConst.RaceType;
            this.btnVideo1.on(Laya.Event.CLICK, this, this._onBtnReplay, [TYPE.Race32, 1]);
            this.btnVideo2.on(Laya.Event.CLICK, this, this._onBtnReplay, [TYPE.Race32, 2]);
            this.btnVideo3.on(Laya.Event.CLICK, this, this._onBtnReplay, [TYPE.Race32, 3]);
            this.btnVideo4.on(Laya.Event.CLICK, this, this._onBtnReplay, [TYPE.Race32, 4]);
            this.btnVideo5.on(Laya.Event.CLICK, this, this._onBtnReplay, [TYPE.Race16, 1]);
            this.btnVideo6.on(Laya.Event.CLICK, this, this._onBtnReplay, [TYPE.Race16, 2]);
            this.btnVideo7.on(Laya.Event.CLICK, this, this._onBtnReplay, [TYPE.Race8, 1]);
            this.listGroup.selectHandler = this.createHandler(this, this._onListSelect, undefined, false);
            this.btnLeft.on(Laya.Event.CLICK, this, this._onBtnLeft);
            this.btnRight.on(Laya.Event.CLICK, this, this._onBtnRight);
        }
        onAwake() {
            super.onAwake();
            this.listGroup.array = [
                { lblGroup: sg.translate("甲") },
                { lblGroup: sg.translate("乙") },
                { lblGroup: sg.translate("丙") },
                { lblGroup: sg.translate("丁") },
            ];
            this.listGroup.selectedIndex = 0;
        }
        setGroup(group) {
            this._group = group;
            this.updateView();
        }
        updateView() {
            if (!this._group)
                return;
            let model = this._model;
            let TYPE = mvc.AthleticPalaceConst.RaceType;
            let raceInfo;
            for (let i = 1; i <= 14; i++) {
                this._setHead(i, null, null);
            }
            for (let i = 1; i <= 4; i++) {
                raceInfo = model.getRace(TYPE.Race32, this._group, i);
                this._setRace(i, raceInfo);
                let i2 = 8 + i;
                let idx1 = i * 2 - 1, idx2 = i * 2;
                if (raceInfo) {
                    this._setHead(idx1, raceInfo.head1, raceInfo.head2);
                    this._setHead(idx2, raceInfo.head2, raceInfo.head1);
                    if (raceInfo.winner != 0 && this._model.isShowRaceRst(raceInfo)) {
                        let head1, head2;
                        if (raceInfo.winner == raceInfo.head1.player_id) {
                            head1 = raceInfo.head1;
                            head2 = raceInfo.head2;
                        }
                        else {
                            head1 = raceInfo.head2;
                            head2 = raceInfo.head1;
                        }
                        this["btnVideo" + i].visible = head1 && head1.player_id > 0 && head2 && head2.player_id > 0;
                        this._setHead(i2, head1, head2);
                        this._setGray(idx1, raceInfo.winner == raceInfo.head2.player_id);
                        this._setGray(idx2, raceInfo.winner == raceInfo.head1.player_id);
                    }
                    else {
                        this["btnVideo" + i].visible = false;
                        this._setHead(i2, null, null);
                        this._setGray(idx1, false);
                        this._setGray(idx2, false);
                    }
                }
                else {
                    this._setHead(idx1, null, null);
                    this._setHead(idx2, null, null);
                    this._setHead(i2, null, null);
                    this["btnVideo" + i].visible = false;
                    this._setGray(idx1, false);
                    this._setGray(idx2, false);
                }
            }
            for (let i = 1; i <= 2; i++) {
                raceInfo = model.getRace(TYPE.Race16, this._group, i);
                let idx = i + 4;
                this._setRace(idx, raceInfo);
                let i2 = 12 + i;
                let idx1 = i * 2 + 7, idx2 = i * 2 + 8;
                if (raceInfo) {
                    this._setHead(idx1, raceInfo.head1, raceInfo.head2);
                    this._setHead(idx2, raceInfo.head2, raceInfo.head1);
                    if (raceInfo.winner != 0 && this._model.isShowRaceRst(raceInfo)) {
                        let head1, head2;
                        if (raceInfo.winner == raceInfo.head1.player_id) {
                            head1 = raceInfo.head1;
                            head2 = raceInfo.head2;
                        }
                        else {
                            head1 = raceInfo.head2;
                            head2 = raceInfo.head1;
                        }
                        this["btnVideo" + idx].visible = head1 && head1.player_id > 0 && head2 && head2.player_id > 0;
                        this._setHead(i2, head1, head2);
                        this._setGray(idx1, raceInfo.winner == raceInfo.head2.player_id);
                        this._setGray(idx2, raceInfo.winner == raceInfo.head1.player_id);
                    }
                    else {
                        this["btnVideo" + idx].visible = false;
                        this._setHead(i2, null, null);
                        this._setHead(idx1, raceInfo.head1, raceInfo.head2);
                        this._setHead(idx2, raceInfo.head2, raceInfo.head1);
                        this._setGray(idx1, false);
                        this._setGray(idx2, false);
                    }
                }
                else {
                    this["btnVideo" + idx].visible = false;
                }
            }
            let zone = this.flagWin;
            raceInfo = model.getRace(TYPE.Race8, this._group, 1);
            this._setRace(7, raceInfo);
            if (raceInfo && raceInfo.winner && this._model.isShowRaceRst(raceInfo)) {
                let head = raceInfo.winner == raceInfo.head1.player_id ? raceInfo.head1 : raceInfo.head2;
                let iconPath = mgr.ComFunMgr.getHeadIcon(head.head_icon, head.sex);
                this.unitHeadWin.initView({ iconPath: iconPath, headFrameId: head.head_frame_id, level: head.level }, head.player_id);
                this.lblNameWin.text = `[S${head.svr_id}]${head.name}`;
                this.unitHeadWin.visible = true;
                this.lblNameWin.visible = true;
                this.btnVideo7.visible = true;
                let areaInfo = this._model.athleticPalaceVo.getPlayerAreaInfo(head.ridge_division);
                if (areaInfo) {
                    mgr.icon.drawTexture(areaInfo.getArenaIcon(), zone);
                    zone.visible = true;
                }
                else {
                    zone.visible = false;
                }
                this._setLabColor(this.lblNameWin, head.ridge_division == this._model.getMyAreaId());
                this._setGray(13, raceInfo.winner == raceInfo.head2.player_id);
                this._setGray(14, raceInfo.winner == raceInfo.head1.player_id);
            }
            else {
                this.unitHeadWin.visible = false;
                this.lblNameWin.visible = false;
                this.btnVideo7.visible = false;
                zone.visible = false;
                this._setGray(13, false);
                this._setGray(14, false);
            }
            if (raceInfo) {
                this._setHead(13, raceInfo.head1, raceInfo.head2);
                this._setHead(14, raceInfo.head2, raceInfo.head1);
            }
            this.unitTop.updateView();
        }
        _setRace(idx, raceInfo) {
            if (!raceInfo || !raceInfo.winner || !this._model.isShowRaceRst(raceInfo)) {
                this[`imgLine${idx}_1`].visible = false;
                this[`imgLine${idx}_2`].visible = false;
                return;
            }
            let is1Win = raceInfo.winner == raceInfo.head1.player_id;
            this[`imgLine${idx}_1`].visible = is1Win;
            this[`imgLine${idx}_2`].visible = !is1Win;
        }
        _setHead(idx, head, head2) {
            let unitHead = this[`unitHead${idx}`];
            let lblName = this[`lblName${idx}`];
            let zone = this[`flag${idx}`];
            let lblTips = this[`lblTips${idx}`];
            unitHead.visible = lblName.visible = zone.visible = !!head && head.player_id > 0;
            if (lblTips) {
                lblTips.visible = false;
            }
            if (unitHead.visible) {
                let iconPath = mgr.ComFunMgr.getHeadIcon(head.head_icon, head.sex);
                unitHead.initView({ iconPath: iconPath, headFrameId: head.head_frame_id, level: head.level }, head.player_id);
                lblName.text = `[S${head.svr_id}]${head.name}`;
                let areaInfo = this._model.athleticPalaceVo.getPlayerAreaInfo(head.ridge_division);
                if (areaInfo) {
                    mgr.icon.drawTexture(areaInfo.getArenaIcon(), zone);
                    zone.visible = true;
                }
                else {
                    zone.visible = false;
                }
                this._setLabColor(lblName, head.ridge_division == this._model.getMyAreaId());
                if (lblTips) {
                    lblTips.visible = head2 && head2.player_id <= 0;
                }
            }
        }
        _setLabColor(lb, isMy) {
            if (isMy) {
                lb.color = '#3bb544';
                lb.strokeColor = '#0d2809';
            }
            else {
                lb.color = '#f9ff9a';
                lb.strokeColor = '#392904';
            }
        }
        _setGray(idx, isGray) {
            let unitHead = this[`unitHead${idx}`];
            let lblName = this[`lblName${idx}`];
            unitHead.filters = isGray ? [this.grayFilter] : [];
            lblName.gray = isGray;
        }
        _onListSelect(idx) {
            this.setGroup(idx + 1);
        }
        _onBtnReplay(type, round) {
            let raceInfo = this._model.getRace(type, this._group, round);
            if (!raceInfo || !raceInfo.replay_list || raceInfo.replay_list.length == 0 || raceInfo.head2.player_id == 0 || raceInfo.replay_list.length == 0)
                return;
            sg.uimgr.showUI("pop_superArenaRelplay", raceInfo);
        }
        _onBtnLeft() {
            let idx = this.listGroup.selectedIndex;
            if (idx == 0)
                return;
            this.listGroup.selectedIndex = idx - 1;
        }
        _onBtnRight() {
            let idx = this.listGroup.selectedIndex;
            if (idx == 3)
                return;
            this.listGroup.selectedIndex = idx + 1;
        }
    }
    mvc.UnitSuperArenaRace32Panel = UnitSuperArenaRace32Panel;
})(mvc || (mvc = {}));

