(function (mvc) {
    class UnitSuperArenaStoreItem extends ui.view.superArena.unit_superArenaStoreItemUI {
        onAwake() {
            super.onAwake();
            this._buyCount = 0;
            this.btnBuy.on(Laya.Event.CLICK, this, this._onClick);
        }
        setData(data, buyCount, costId, hveCostCount) {
            if (!data)
                return;
            this._vo = data;
            this._buyCount = buyCount;
            this._costId = costId;
            this._haveCosetCount = 100;
            let itemVo = new mvc.ItemVo();
            itemVo.initData(this._vo.reward[0][0], this._vo.reward[0][1]);
            this.item.initView(itemVo);
            this.lblItemName.text = mgr.toolsMgr.getNameById(this._vo.reward[0][0]);
            let buyLimit = this._vo.limit || 0;
            if (buyLimit == 0) {
                this.lblLimit.text = sg.translate("无限制");
            }
            else {
                this.lblLimit.text = sg.translate("限购:") + (buyLimit - buyCount) + "/" + this._vo.limit;
            }
            if (buyLimit == 0 || buyCount < buyLimit) {
                this.boxLock.visible = false;
                this.lblLimit.color = mgr.toolsMgr.getColor3("green").stringColor;
            }
            else {
                this.lblLimit.color = mgr.toolsMgr.getColor3("red").stringColor;
                this.boxLock.visible = true;
            }
            this.lblPrice.text = this._vo.cost + "";
            mgr.icon.drawTexture(mgr.icon.getIconPath(mgr.toolsMgr.getIconById(costId)), this.imgIcon);
            this.redTIps.visible = buyCount < buyLimit && hveCostCount >= data.cost;
        }
        _onClick() {
            if (!this._vo) {
                return;
            }
            let buyLimit = this._vo.limit || 0;
            if ((buyLimit == 0 || this._buyCount < buyLimit) && this.checkConsume(true)) {
                let itemVo = new mvc.BgStoreVo();
                itemVo.id = this._vo.id;
                itemVo.max_count = this._vo.limit;
                itemVo.bought_count = this._buyCount;
                itemVo.shop_item = this._vo.reward;
                itemVo.cost_item = [[this._costId, this._vo.cost]];
                itemVo['haveCount'] = this._haveCosetCount;
            }
        }
        checkConsume(showTip) {
            if (this._haveCosetCount >= this._vo.cost) {
                return true;
            }
            else {
                showTip && mgr.toolsMgr.checkConsume([[this._costId, this._vo.cost]], true);
                return false;
            }
        }
    }
    mvc.UnitSuperArenaStoreItem = UnitSuperArenaStoreItem;
})(mvc || (mvc = {}));

