(function (mvc) {
    class ArtifactRoughVo extends sg.VoBase {
        constructor() {
            super();
        }
        init(data) {
            this.cloneProtoData(data);
            if (!data.base_id)
                return;
            this.cfgId = data.base_id;
            let cfg = sg.dbmgr.get("artifact_stone", data.base_id);
            this.quality = cfg.quality;
            this.name = cfg.artifactName;
            this.maxLayer = cfg.skinNum;
            this.imgTitle = "ui_langs/cn/ui/artifact/" + cfg.namePic;
            let idx = 0;
            let per = 1 - this.layer / cfg.skinNum;
            if (per > 0 && per <= 0.25) {
                idx = 1;
            }
            else if (per > 0.25 && per <= 0.50) {
                idx = 2;
            }
            else if (per > 0.50 && per < 1) {
                idx = 3;
            }
            else if (per == 1) {
                idx = 4;
            }
            let skinCfg = sg.dbmgr.get("artifact_stoneSkin", cfg.iconGroup[idx]);
            this.icon = mgr.icon.getIconPath(skinCfg.icon);
            this.artifact = data.artifact_id;
            if (this.artifact) {
                let cfg = sg.dbmgr.get("vitem", this.artifact);
                this.artifactIcon = mgr.icon.getIconPath(cfg.icon);
            }
            else {
                this.artifactIcon = undefined;
            }
        }
    }
    mvc.ArtifactRoughVo = ArtifactRoughVo;
})(mvc || (mvc = {}));

var mvc;
(function (mvc) {
    class ArtifactVo extends sg.VoBase {
        constructor() {
            super();
            this.refreshInfo = new Map();
            this.mining = new Map();
            this.secret_infos = new Map();
        }
        init(data) {
            this.equipped = data.equipped;
            this.atlas = data.atlas;
            this.gotArtifact = data.artifacts;
            this.secret_open = data.secret_open;
            this.mining.clear();
            for (let m of data.mining) {
                this.mining.set(m[0], m[1]);
            }
            for (let info of data.refresh_info) {
                this._updateRefreshInfo(info);
            }
            let arr = [];
            for (let r of data.rough) {
                let vo = new mvc.ArtifactRoughVo();
                vo.init(r);
                arr.push(vo);
            }
            this.rough = arr;
            this._updateAtlasAttr();
        }
        initSecretInfo(data) {
            this.secret_infos.clear();
            for (let info of data) {
                this._updateSecretInfo(info);
            }
            this.updateSecretAttr();
        }
        updateMiningInfo(data) {
            let arr = [];
            for (let r of data.warehouse) {
                let vo = new mvc.ArtifactRoughVo();
                vo.init(r);
                arr.push(vo);
            }
            this.warehouseRough = arr;
            this.profit = data.profit;
            this.nextTime = data.refresh_time;
            this.miningEfficiency = data.profit_ratio;
        }
        openRough(data) {
            let arr;
            let ret = 0;
            if (data.is_warehouse == 1) {
                arr = this.warehouseRough;
            }
            else {
                arr = this.rough;
            }
            for (let vo of arr) {
                if (vo.id == data.info.id) {
                    ret = vo.layer - data.info.layer;
                    if (data.artifact) {
                        if (data.is_warehouse) {
                            arr.splice(arr.indexOf(vo), 1);
                        }
                        else {
                            data.info.id = 0;
                        }
                    }
                    vo.init(data.info);
                    break;
                }
            }
            return ret;
        }
        discardRough(id) {
            for (let i = 0; i < this.warehouseRough.length; i++) {
                if (this.warehouseRough[i].id == id) {
                    this.warehouseRough.splice(i, 1);
                    break;
                }
            }
        }
        getNewArtifact(id) {
            if (this.gotArtifact.indexOf(id) != -1)
                return;
            let arr = sg.varmgr.getUserVar("artifactNew");
            if (!arr)
                arr = [];
            arr.push(id);
            sg.varmgr.setUserVar("artifactNew", arr);
            this.gotArtifact.push(id);
            let artifactCfg = sg.dbmgr.get("item_artifact", id);
            let atlasCfg = sg.dbmgr.get("artifact_artifactAtlas", artifactCfg.contractId);
            let active = true;
            for (let i of atlasCfg.group) {
                if (this.gotArtifact.indexOf(i) == -1) {
                    active = false;
                    break;
                }
            }
            if (active) {
                this.atlas.push(artifactCfg.contractId);
                this._updateAtlasAttr();
            }
        }
        _updateAtlasAttr() {
            let attrMap = {};
            for (let a of this.atlas) {
                let cfg = sg.dbmgr.get("artifact_artifactAtlas", a);
                for (let add of cfg.contract) {
                    if (attrMap[add[0]]) {
                        attrMap[add[0]] += add[1];
                    }
                    else {
                        attrMap[add[0]] = add[1];
                    }
                }
            }
            let arr = [];
            for (let key in attrMap) {
                let attr = attrMap[key];
                let cfg = mvc.PropertyModel._getCfg(key);
                if (!cfg) {
                    sg.loge("read prop cfg fail, key" + key);
                    continue;
                }
                arr.push({
                    cfg: cfg,
                    lblName: cfg.show_name,
                    lblValue: cfg.is_per == 1 ? (attrMap[key] / 100) + "%" : attr.toString(),
                    value: attr,
                    isPer: cfg.is_per == 1
                });
            }
            arr.sort((a, b) => {
                if (a.cfg.show_priority != b.cfg.show_priority) {
                    return a.cfg.show_priority - b.cfg.show_priority;
                }
                return a.cfg.id - b.cfg.id;
            });
            this.atlasAttr = arr;
        }
        refreshRough(data) {
            let arr = [];
            for (let r of data.rough) {
                let vo = new mvc.ArtifactRoughVo();
                vo.init(r);
                arr.push(vo);
            }
            this.rough = arr;
            this._updateRefreshInfo(data.info);
        }
        _updateRefreshInfo(data) {
            if (!this.refreshInfo.has(data.type)) {
                this.refreshInfo.set(data.type, {
                    free: data.free_count,
                    item: data.item_count
                });
            }
            else {
                let item = this.refreshInfo.get(data.type);
                item.free = data.free_count;
                item.item = data.item_count;
            }
        }
        updateSecretAttr() {
            let arr = [];
            if (this.secret_infos) {
                let baseProp = [];
                this.secret_infos.forEach((value, key) => {
                    if (value.item_id != 0) {
                        let addProp = mvc.PropertyModel.prasePropByIds(value.select_attr);
                        baseProp = mvc.PropertyModel.getMixPropertysMerge(baseProp, addProp, true);
                    }
                });
                for (let key in baseProp) {
                    let info = baseProp[key];
                    arr.push({
                        lblName: info.showPropertyName(),
                        lblValue: info.is_per == 1 ? (info.value / 100) + "%" : info.value.toString(),
                        value: info.value,
                        isPer: info.is_per == 1
                    });
                }
            }
            this.secretAttr = arr;
        }
        secretLvUp(data) {
            if (!this.secret_infos.has(data.secret_id)) {
                this.secret_infos.set(data.secret_id, {
                    secret_level: 1,
                    process: 0,
                    item_id: 0,
                    select_attr: []
                });
            }
            else {
                let info = this.secret_infos.get(data.secret_id);
                info.secret_level = data.secret_level;
                info.select_attr = data.attr;
                info.process = data.process;
            }
        }
        _updateSecretInfo(data) {
            if (!this.secret_infos.has(data.id)) {
                this.secret_infos.set(data.id, {
                    secret_level: data.secret_level,
                    process: data.process,
                    item_id: data.item_id,
                    select_attr: data.select_attr
                });
            }
            else {
                let item = this.secret_infos.get(data.id);
                item.secret_level = data.secret_level;
                item.process = data.process;
                item.item_id = data.item_id;
                item.select_attr = data.select_attr;
            }
        }
        getSecretAttrById(item_id) {
            let bagItemVo = mvc.bagModel.getItem(item_id);
            if (bagItemVo) {
                let arr = [];
                let cfg = mgr.toolsMgr.getGlobalVoById("artifact_exclude_attr", 1);
                for (let i = 0; i < bagItemVo.attr.length; i++) {
                    let attr = bagItemVo.attr[i];
                    if (cfg.indexOf(attr[0]) == -1) {
                        arr.push(attr);
                    }
                }
                return arr;
            }
            else {
                return [];
            }
        }
    }
    mvc.ArtifactVo = ArtifactVo;
})(mvc || (mvc = {}));

var mvc;
(function (mvc) {
    class ArtifactModel extends sg.ModelBase {
        initModel() {
        }
        registerEvents() {
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.ARTIFACT_ATLAS, this._checkRed, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.ARTIFACT_MINE_LINEUP, this._checkRedLineup, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.ARTIFACT_MINE_REWARD, this._checkRedMineReward, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.ARTIFACT_SECRET, this._checkRedSecret, this);
            this.bindEvent(mvc.mainModel, mvc.MainConst.EVT.ZERO_UPDATE, this._onZeroTime);
        }
        willEnterGame() {
        }
        getArtifactModelId(idMagicGoods) {
            let cfg = sg.dbmgr.get("item_artifact", idMagicGoods);
            return cfg ? cfg.model : 0;
        }
        _checkRed() {
            if (!mgr.conditionMgr.checkFunc(mvc.FUNC_ID.ARTIFACT, false))
                return 0;
            if (!this.vo)
                return 0;
            let cfgs = sg.dbmgr.getDB("artifact_artifactAtlas");
            let arr = sg.varmgr.getUserVar("artifactNew");
            for (let key in cfgs) {
                let cfg = cfgs[key];
                for (let item of cfg.group) {
                    if (arr && arr.indexOf(item) != -1)
                        return 1;
                }
            }
            return 0;
        }
        _checkRedLineup() {
            if (!mgr.conditionMgr.checkFunc(mvc.FUNC_ID.ARTIFACT, false))
                return 0;
            if (!this.vo)
                return 0;
            let mining = this.vo.mining;
            let hadNull = false;
            for (let item of mining) {
                if (item[1] == 0) {
                    hadNull = true;
                    break;
                }
            }
            let max = this.miningMaxNum;
            let items = this.getMineArr();
            if (items.length > 0 && (hadNull || max > mining.size))
                return 1;
            return 0;
        }
        _checkRedMineReward() {
            if (!mgr.conditionMgr.checkFunc(mvc.FUNC_ID.ARTIFACT, false))
                return 0;
            if (!this.vo)
                return 0;
            if (this.vo.profit > 0)
                return 1;
            return 0;
        }
        _checkRedSecret() {
            if (!this.vo)
                return 0;
            if (this.vo.secret_open == 0)
                return 0;
            let cfg = sg.dbmgr.getDB("artifact_secret", true);
            for (let i = 0, len = cfg.length; i < len; i++) {
                let data = cfg[i];
                if (!this.vo.secret_infos.has(data.id)) {
                    if (data.state == 1 && mgr.conditionMgr.func_role_up_lv(data.unlock[0], false))
                        return 1;
                }
                else {
                    if (this.vo.secret_infos.get(data.id).item_id != 0) {
                        let lv = this.vo.secret_infos.get(data.id).secret_level;
                        let levelCfg = sg.dbmgr.getArray("artifact_secretLevel", { id: data.id, level: lv })[0];
                        if (levelCfg.condition) {
                            if (mgr.toolsMgr.checkConsume(levelCfg.condition, false))
                                return 1;
                        }
                    }
                    else {
                        if (this.getSecretArtifact().length > 0)
                            return 1;
                    }
                }
            }
            return 0;
        }
        _onZeroTime() {
            if (!this.vo)
                return;
            for (let info of this.vo.refreshInfo.values()) {
                info.free = 0;
                info.item = 0;
            }
            this.fireEvent(mvc.ArtifactConst.EVT.UPDATE_ROUGH_INFO);
        }
        updateInfo(data) {
            this.vo = new mvc.ArtifactVo();
            this.vo.init(data);
            mgr.redotMgr.check(mvc.REDOT_ID.ARTIFACT_ATLAS);
            mgr.redotMgr.check(mvc.REDOT_ID.ARTIFACT_MINE_LINEUP);
            mgr.redotMgr.check(mvc.REDOT_ID.ARTIFACT_MINE_REWARD);
        }
        equipArtifact(id) {
            this.vo.equipped = id;
            if (this.getIsInSecret(id)) {
                mvc.artifactCtrl.reqSecretInfo();
            }
            this.fireEvent(mvc.ArtifactConst.EVT.UPDATE_INFO);
            mgr.redotMgr.check(mvc.REDOT_ID.ARTIFACT_ATLAS);
            mgr.redotMgr.check(mvc.REDOT_ID.ARTIFACT_MINE_LINEUP);
            mgr.redotMgr.check(mvc.REDOT_ID.ARTIFACT_MINE_REWARD);
        }
        openRough(data) {
            let layer = this.vo.openRough(data);
            this.fireEvent(mvc.ArtifactConst.EVT.KNOCK_ROUGH, layer, data.artifact ? data.artifact.id : 0);
        }
        discardRough(data) {
            this.vo.discardRough(data.id);
            this.fireEvent(mvc.ArtifactConst.EVT.UPDATE_ROUGH_INFO);
            sg.uimgr.closeUI("pop_artifactKnock");
        }
        refreshRough(data) {
            this.vo.refreshRough(data);
            this.fireEvent(mvc.ArtifactConst.EVT.REFRESH_ROUGH);
        }
        getMiningProfit() {
            this.vo.profit = 0;
            this.fireEvent(mvc.ArtifactConst.EVT.UPDATE_MINING_INFO);
            sg.uimgr.showNotice(sg.translate("领取成功"), "green");
            mgr.redotMgr.check(mvc.REDOT_ID.ARTIFACT_MINE_REWARD);
        }
        updateMiningInfo(data) {
            this.vo.updateMiningInfo(data);
            this.fireEvent(mvc.ArtifactConst.EVT.UPDATE_MINING_INFO);
            mgr.redotMgr.check(mvc.REDOT_ID.ARTIFACT_MINE_REWARD);
        }
        setMining(data) {
            this.vo.mining.set(data.pos, data.id);
            this.vo.nextTime = data.refresh_time;
            this.vo.miningEfficiency = data.profit_ratio;
            this.fireEvent(mvc.ArtifactConst.EVT.UPDATE_MINING_INFO);
            mgr.redotMgr.check(mvc.REDOT_ID.ARTIFACT_MINE_LINEUP);
        }
        getMineArr() {
            let all = mvc.bagModel.getItemsByType(mvc.BagConst.BagType.Artifact);
            let values = this.vo.mining.values();
            let map = {};
            for (let v of values) {
                map[v] = true;
            }
            let arr = [];
            for (let item of all) {
                if (!map[item.bagId]) {
                    arr.push(item);
                }
            }
            return arr;
        }
        artifactChange() {
            sg.timer.callLater(this, this._onArtifactChange);
        }
        _onArtifactChange() {
            this.fireEvent(mvc.ArtifactConst.EVT.UPDATE_ALL);
            mgr.redotMgr.check(mvc.REDOT_ID.ARTIFACT_ATLAS);
            mgr.redotMgr.check(mvc.REDOT_ID.ARTIFACT_MINE_LINEUP);
            mgr.redotMgr.check(mvc.REDOT_ID.ARTIFACT_MINE_REWARD);
        }
        get miningMaxNum() {
            if (!this._miningCfg) {
                this._miningCfg = mgr.toolsMgr.getGlobalVoById("artifact_mining_unlock", 1);
            }
            let ret = 0;
            for (let cond of this._miningCfg) {
                if (mgr.conditionMgr.checkSingle(cond, false)) {
                    ret++;
                }
            }
            return ret;
        }
        get miningOpenConds() {
            if (!this._miningCfg) {
                this._miningCfg = mgr.toolsMgr.getGlobalVoById("artifact_mining_unlock", 1);
            }
            return this._miningCfg;
        }
        getMiningEff(qua, lv) {
            if (!this._effMap) {
                this._effMap = {};
                let cfg = mgr.toolsMgr.getGlobalVoById("artifact_mining_output", 1);
                for (let data of cfg) {
                    this._effMap[data[0]] = data[1];
                }
            }
            let cfg = mgr.toolsMgr.getGlobalVoById("artifact_mining_extra", 1);
            return this._effMap[qua] + Math.floor(lv / cfg[0]) * cfg[1];
        }
        updateSecretInfo(data) {
            if (this.vo) {
                this.vo.initSecretInfo(data.secret_infos);
                this.fireEvent(mvc.ArtifactConst.EVT.UPDATE_SECRET_VIEW);
                mgr.redotMgr.check(mvc.REDOT_ID.ARTIFACT_SECRET);
            }
        }
        updateSecretEntry(data) {
            this.vo.secret_open = data.secret_open;
            this.fireEvent(mvc.ArtifactConst.EVT.UPDATE_SECRET_ENTRY);
        }
        secretLvUp(data) {
            this.fireEvent(mvc.ArtifactConst.EVT.PLAY_LVUP_ANI, data.is_success, data.secret_level);
            this.vo.secretLvUp(data);
            if (data.is_success) {
                this.vo.updateSecretAttr();
                if (data.secret_level == 1 && data.process == 0) {
                    sg.uimgr.showNotice(sg.translate("解锁成功"), "green");
                    this.fireEvent(mvc.ArtifactConst.EVT.PLAY_LOCK_ANI, data.secret_id);
                }
            }
            this.fireEvent(mvc.ArtifactConst.EVT.UPDATE_SECRET_VIEW);
            this.fireEvent(mvc.ArtifactConst.EVT.UPDATE_SECRET_SELECT);
            mgr.redotMgr.check(mvc.REDOT_ID.ARTIFACT_SECRET);
        }
        secretPlace(data) {
            if (this.vo)
                this.vo.initSecretInfo(data.secret_infos);
            this.fireEvent(mvc.ArtifactConst.EVT.UPDATE_INFO);
            this.fireEvent(mvc.ArtifactConst.EVT.UPDATE_SECRET_VIEW);
            this.fireEvent(mvc.ArtifactConst.EVT.PLAY_CHANGE_ANI, data.secret_id);
            mgr.redotMgr.check(mvc.REDOT_ID.ARTIFACT_SECRET);
        }
        getSecretArtifact() {
            let all = mvc.bagModel.getItemsByType(mvc.BagConst.BagType.Artifact);
            let values = this.vo.secret_infos.values();
            let lvLimit = mgr.toolsMgr.getGlobalVoById("secret_artifact_limit", 1);
            let map = {};
            for (let v of values) {
                map[v.item_id] = true;
            }
            let arr = [];
            for (let item of all) {
                if (!map[item.bagId] && item.level >= lvLimit && item.bagId != this.vo.equipped) {
                    arr.push(item);
                }
            }
            return arr;
        }
        getSecretArtifactChange(secret_id) {
            let all = mvc.bagModel.getItemsByType(mvc.BagConst.BagType.Artifact);
            let lvLimit = mgr.toolsMgr.getGlobalVoById("secret_artifact_limit", 1);
            let arr = [];
            let id = this.vo.secret_infos.get(secret_id).item_id;
            for (let item of all) {
                if (item.bagId != id && item.level >= lvLimit && item.bagId != this.vo.equipped) {
                    arr.push(item);
                }
            }
            return arr;
        }
        getIsInSecret(bagId) {
            if (this.vo && this.vo.secret_infos) {
                let isInSecret = false;
                this.vo.secret_infos.forEach((value, key) => {
                    if (value.item_id == bagId) {
                        isInSecret = true;
                        return;
                    }
                });
                return isInSecret;
            }
            else {
                return false;
            }
        }
        getSecretIdByBagId(id) {
            let secret_id = 0;
            if (this.vo.secret_infos) {
                this.vo.secret_infos.forEach((value, key) => {
                    if (value.item_id == id)
                        secret_id = key;
                    return;
                });
            }
            return secret_id;
        }
    }
    mvc.ArtifactModel = ArtifactModel;
})(mvc || (mvc = {}));

var mvc;
(function (mvc) {
    class PopArtifact extends ui.view.artifact.pop_artifactUI {
        initView() {
            this._model = mvc.artifactModel;
            this._ctrl = mvc.artifactCtrl;
        }
        initSendMsg() {
        }
        initModelEvent() {
            this.bindModelEvent(this._model, mvc.ArtifactConst.EVT.UPDATE_INFO, this._updateInfo);
            this.bindModelEvent(this._model, mvc.ArtifactConst.EVT.STAGE_UP, this._onStageUp);
            this.bindModelEvent(this._model, mvc.ArtifactConst.EVT.LEVEL_UP, this._onLvUp);
            this.bindModelEvent(mvc.bagModel, mvc.BagConst.EVT.ITEM_NUM_CHANGE, this._updateAll);
        }
        initCtrlEvent() {
            this.listBg.vScrollBarSkin = "";
            this.list.vScrollBarSkin = "";
            this.list.scrollBar.on(Laya.Event.CHANGE, this, this._onListScroll);
            this.list.renderHandler = this.createHandler(this, this._listRenderer, undefined, false);
            this.list.selectHandler = this.createHandler(this, this._updateArtifact, undefined, false);
            this.btnEquip.on(Laya.Event.CLICK, this, this._onBtnEquip);
            this.btnDecompose.on(Laya.Event.CLICK, this, this._onBtnDecompose);
            this.btnUp.on(Laya.Event.CLICK, this, this._onBtnUp);
            this.btnDig.on(Laya.Event.CLICK, this, this._onBtnDig);
            this.btnCollect.on(Laya.Event.CLICK, this, this._onBtnCollect);
            this.btnOpen.on(Laya.Event.CLICK, this, this._onBtnOpen);
            this.btnSecret.on(Laya.Event.CLICK, this, this._onBtSecret);
            this.unitCurrency.updateData("", [mvc.MainConst.ITEM_ID.ARTIFACT_MINING, mvc.MainConst.ITEM_ID.ARTIFACT_UPSTAGE], true);
        }
        onAwake() {
            super.onAwake();
            this.redTipsAtlas.id = mvc.REDOT_ID.ARTIFACT_ATLAS;
            this.redTipsMine.id = mvc.REDOT_ID.ARTIFACT_MINE;
            this.redSecret.id = mvc.REDOT_ID.ARTIFACT_SECRET;
            this.lblEmpty.text = this.lblListEmpty.text = sg.translate("暂无法宝");
        }
        onEnable() {
            super.onEnable();
            this._updateAll();
        }
        onDisable() {
            super.onDisable();
        }
        _updateInfo() {
            this.list.refresh();
            this._updateArtifact();
        }
        _onLvUp() {
            this._updateInfo();
            this._showAttrEff();
            if (!mgr.toolsMgr.checkConsume(this._lvUpCost, false, false))
                mvc.rechargeLimitCtrl.reqRechargeTrigger(mvc.RechargeLimitConst.EventType.STONE);
        }
        _onStageUp() {
            this._showUpEff();
            this._updateInfo();
            this._showAttrEff();
        }
        _showAttrEff() {
            for (let cell of this.listAttr.cells) {
                cell.getChildByName("clipEff").visible = true;
            }
        }
        _showUpEff() {
            let eff = sg.Effect2D.create("eff_ui_shenjiechengong", true, false, true);
            eff.x = 20;
            eff.y = 84;
            eff.name = "eff_ui_shenjiechengong";
            eff.on(Laya.Event.STOPPED, this, this._onStageAniEnd);
            this.addChild(eff);
        }
        _onStageAniEnd() {
            this.removeChildByName("eff_ui_shenjiechengong");
        }
        _updateAll() {
            let vos = mvc.bagModel.getItemsByType(mvc.BagConst.BagType.Artifact);
            vos.sort((a, b) => {
                let acfg = a.getCfg();
                let bcfg = b.getCfg();
                if (acfg.quality != bcfg.quality) {
                    return bcfg.quality - acfg.quality;
                }
                if (a.level != b.level) {
                    return b.level - a.level;
                }
                return a.id - b.id;
            });
            this.list.array = vos;
            if (vos.length > 0) {
                if (this.list.selectedIndex <= 0) {
                    this.list.selectedIndex = 0;
                }
                else {
                    let idx = 0;
                    for (let i = 0; i < vos.length; i++) {
                        if (vos[i].bagId == this._lastSelect) {
                            idx = i;
                            break;
                        }
                    }
                    this.list.selectedIndex = idx;
                }
            }
            else {
                this.list.selectedIndex = -1;
            }
            this.lblListEmpty.visible = false;
            let len = Math.max(15, Math.ceil(vos.length / 5) * 5);
            let arr = [];
            for (let i = 0; i < len; i++) {
                arr.push(null);
            }
            this.listBg.array = arr;
            this._updateArtifact();
        }
        _updateArtifact() {
            let selectItem = this.list.selectedItem;
            if (!selectItem) {
                this.lblName.text = "";
                this.listAttr.array = [];
                this.unitModel.visible = false;
                this.btnDecompose.visible = false;
                this.btnEquip.visible = false;
                this.boxLvUp.visible = false;
                this.lblEmpty.visible = true;
                return;
            }
            this._lastSelect = selectItem.bagId;
            this.unitModel.visible = true;
            this.btnDecompose.visible = true;
            this.btnEquip.visible = true;
            this.boxLvUp.visible = true;
            this.lblEmpty.visible = false;
            let cfg = selectItem.getCfg();
            this.unitModel.changeShowMode(false, cfg.model);
            this.unitModel.loadedHandle = () => {
                this.unitModel.play("stand", true);
            };
            this.unitModel.loadRole(cfg.model, "PopArtifact");
            this.lblName.text = cfg.name;
            mgr.toolsMgr.setLabelByQua(cfg.quality, this.lblName);
            this.listAttr.array = mvc.PropertyModel.generateListData(selectItem.attr);
            let stage = selectItem.itemStage;
            let lv = selectItem.level;
            let v1 = stage;
            let v2 = lv;
            this.lblStage.text = StringEx.format(sg.translate("${v1}阶${v2}级"), {"v1":v1,"v2":v2});
            if (this._model.vo.equipped == selectItem.bagId) {
                this.btnEquip.label = sg.translate("已祭出");
                this.btnEquip.disabled = true;
            }
            else {
                this.btnEquip.label = sg.translate("祭出");
                this.btnEquip.disabled = false;
            }
            let lvCfg = sg.dbmgr.get("artifact_artifactUpLv", lv);
            let next = sg.dbmgr.get("artifact_artifactUpLv", lv + 1);
            if (!next) {
                this.progUp.updateView(1, 1);
                this.btnUp.visible = false;
                this.lblLvMax.visible = true;
            }
            else {
                this.btnUp.visible = true;
                this.lblLvMax.visible = false;
                this.progUp.updateView(selectItem.process / lvCfg.allSchedule, lvCfg.allSchedule);
                let isBreak = this._isBreak = lvCfg.break == 1 && lvCfg.allSchedule == selectItem.process;
                this.lblLvUpBtn.text = isBreak ? sg.translate("升阶") : sg.translate("升级");
                this.lblLvUpBtn.y = isBreak ? 17 : 31;
                this.lblCoinNum.visible = this.imgCoin.visible = !isBreak;
                if (!isBreak) {
                    let url = mgr.toolsMgr.getIconById(lvCfg.partConsume[0][0]);
                    mgr.icon.drawTexture(mgr.icon.getIconPath(url), this.imgCoin);
                    this.lblCoinNum.text = lvCfg.partConsume[0][1];
                    this._lvUpCost = lvCfg.partConsume;
                    this._updateBtnColor();
                }
            }
        }
        _updateBtnColor() {
            if (!this._lvUpCost)
                return;
            this.lblCoinNum.color = mgr.toolsMgr.checkConsume(this._lvUpCost, false, false) ? "#239f44" : "#e2341d";
        }
        _listRenderer(cell) {
            let data = cell.dataSource;
            if (!data)
                return;
            let icon = cell.getChildByName("icon");
            let imgWear = cell.getChildByName("imgWear");
            let imgSecret = cell.getChildByName("imgSecret");
            icon.initView(data, false);
            if (data.level >= 0) {
                icon.lblNum.text = "Lv." + data.level;
            }
            imgWear.visible = this._model.vo.equipped == data.bagId;
            if (this._model.getIsInSecret(data.bagId)) {
                imgSecret.visible = true;
                let id = this._model.getSecretIdByBagId(data.bagId);
                let cfg = sg.dbmgr.get("artifact_secret", id);
                mgr.icon.drawTexture(mgr.icon.getIconPath(cfg.icon), imgSecret);
            }
            else {
                imgSecret.visible = false;
            }
        }
        _onListScroll() {
            this.listBg.scrollBar.value = this.list.scrollBar.value;
        }
        _onBtnEquip() {
            let data = this.list.selectedItem;
            if (!data)
                return;
            if (this._model.getIsInSecret(data.bagId)) {
                sg.uimgr.showConfirm({
                    content: sg.translate("该法宝正在秘藏温养中，是否继续操作？"),
                    btnCancelVisible: true,
                    enterFunc: () => {
                        this._ctrl.reqEquip(data.bagId);
                    }
                });
                return;
            }
            this._ctrl.reqEquip(data.bagId);
        }
        _onBtnDecompose() {
            let data = this.list.selectedItem;
            if (!data)
                return;
            if (this._model.vo.equipped == data.bagId) {
                sg.uimgr.showNotice(sg.translate("已祭出的法宝无法分解"));
                return;
            }
            let quaCheckFun = () => {
                sg.uimgr.showConfirm({
                    content: sg.translate("您正在分解鸿蒙至宝级别的法宝，该法宝十分稀有，是否继续？"),
                    btnCancelVisible: true,
                    enterFunc: () => {
                        this._ctrl.reqDecompose(data.bagId);
                    }
                });
            };
            if (this._model.getIsInSecret(data.bagId)) {
                sg.uimgr.showConfirm({
                    content: sg.translate("该法宝正在秘藏温养中，是否继续操作？"),
                    btnCancelVisible: true,
                    enterFunc: () => {
                        if (data.getCfg().quality >= 6) {
                            quaCheckFun();
                            return;
                        }
                        else {
                            this._ctrl.reqDecompose(data.bagId);
                        }
                    }
                });
                return;
            }
            if (data.getCfg().quality >= 6) {
                quaCheckFun();
                return;
            }
            let isNoShow = mvc.mainModel.getSacrificeTip(mvc.FirstTipsID.ARTIFACT_DECOMPOSE);
            if (isNoShow) {
                this._ctrl.reqDecompose(data.bagId);
            }
            else {
                let tipsFun = () => {
                    mvc.mainModel.showSacrificeTip = mvc.FirstTipsID.ARTIFACT_DECOMPOSE;
                };
                sg.uimgr.showConfirm({
                    content: sg.translate("是否将当前法宝分解，分解后将返回80%培养材料"),
                    btnCancelVisible: true,
                    enterFunc: () => {
                        this._ctrl.reqDecompose(data.bagId);
                    },
                    sacrificeTipVisible: true,
                    sacrificeTipFunc: tipsFun
                });
            }
        }
        _onBtnUp() {
            let data = this.list.selectedItem;
            if (!data)
                return;
            if (this._isBreak) {
                sg.uimgr.showUI("pop_artifactLvUp", data);
            }
            else {
                if (mgr.toolsMgr.checkConsume(this._lvUpCost, true)) {
                    this._ctrl.reqUpLevel(data.bagId);
                }
            }
        }
        _onBtnDig() {
            sg.uimgr.showUI("pop_artifactMining");
        }
        _onBtnCollect() {
            sg.uimgr.showUI("pop_artifactAtlas");
        }
        _onBtnOpen() {
            sg.uimgr.showUI("pop_artifactGambling");
        }
        _onBtSecret() {
            if (mgr.conditionMgr.checkFunc(mvc.FUNC_ID.ARTIFACT_SECRET, true)) {
                sg.uimgr.showUI("pop_secret");
                mvc.artifactCtrl.reqSecretInfo();
            }
        }
    }
    mvc.PopArtifact = PopArtifact;
})(mvc || (mvc = {}));

