(function (mvc) {
    class PopArtifactAtlas extends ui.view.artifact.pop_artifactAtlasUI {
        initView() {
            this._model = mvc.artifactModel;
            this._ctrl = mvc.artifactCtrl;
        }
        initSendMsg() {
        }
        initModelEvent() {
            this.bindModelEvent(this._model, mvc.ArtifactConst.EVT.LOOK_ALLAS, this._updateView);
        }
        initCtrlEvent() {
            this.listNormal.vScrollBarSkin = "";
            this.listAdv.vScrollBarSkin = "";
            this.lblTotal.on(Laya.Event.CLICK, this, this._onLblTotal);
            this.tab.selectHandler = this.createHandler(this, this._onTab, undefined, false);
        }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            this._updateView();
        }
        onDisable() {
            super.onDisable();
        }
        _updateView() {
            let arrNormal = [];
            let arrAdv = [];
            let arrSub = [];
            let cfgs = sg.dbmgr.getDB("artifact_artifactAtlas");
            for (let key in cfgs) {
                let cfg = cfgs[key];
                let time = new Date(cfg.timeShow).getTime();
                let passTime = sg.time.getTime() - time >= 0;
                if (!passTime)
                    continue;
                let vos = [];
                for (let item of cfg.group) {
                    let vo = new mvc.ItemVo();
                    vo.initData(item, 1);
                    vos.push(vo);
                }
                let attrs = [];
                for (let attr of cfg.contract) {
                    let cfg = mvc.PropertyModel._getCfg(attr[0]);
                    attrs.push({
                        lblName: cfg.show_name,
                        lblValue: cfg.is_per == 1 ? (attr[1] / 100) + "%" : attr[1].toString()
                    });
                }
                let colorCfg = sg.dbmgr.get("color", cfg.quality);
                let arr = cfg.type == 1 ? arrNormal : arrSub;
                arr.push({
                    atlasName: cfg.name,
                    color: colorCfg.stringColor,
                    strokeColor: colorCfg.strokeColor,
                    vos: vos,
                    attrs: attrs
                });
                if (cfg.type == 2 && arrSub.length == 3) {
                    arrAdv.push({ vos: arrSub });
                    arrSub = [];
                }
            }
            if (arrSub.length) {
                arrAdv.push({ vos: arrSub });
            }
            this.listNormal.array = arrNormal;
            this.listAdv.array = arrAdv;
        }
        _onLblTotal() {
            sg.uimgr.showUI("pop_artifactAtlasAttr");
        }
        _onTab(idx) {
            if (idx < 0)
                return;
            this.boxNormal.visible = idx == 0;
            this.boxAdv.visible = idx == 1;
        }
    }
    mvc.PopArtifactAtlas = PopArtifactAtlas;
})(mvc || (mvc = {}));

