(function (mvc) {
    class PopArtifactKnock extends ui.view.artifact.pop_knockUI {
        constructor() {
            super(...arguments);
            this._isAutoKnocking = false;
        }
        initView(vo, isWarehouse) {
            this._model = mvc.artifactModel;
            this._ctrl = mvc.artifactCtrl;
            this._vo = vo;
            this._isWarehouse = isWarehouse;
            this._isAutoKnocking = false;
            this._artifactId = 0;
        }
        initSendMsg() {
        }
        initModelEvent() {
            this.bindModelEvent(this._model, mvc.ArtifactConst.EVT.KNOCK_ROUGH, this._onKnock);
        }
        initCtrlEvent() {
            this.imgIcon.on(Laya.Event.CLICK, this, this._onClickIcon);
            this.effKnock.ani1.on(Laya.Event.COMPLETE, this, this._onKnockAniEnd);
            this.ani1.on(Laya.Event.COMPLETE, this, this._onFloatTxtAniEnd);
            this.btnDiscard.on(Laya.Event.CLICK, this, this._onBtnDisard);
            this.btnTen.on(Laya.Event.CLICK, this, this._onBtnTen);
            this.btnFive.on(Laya.Event.CLICK, this, this._onBtnFive);
        }
        onAwake() {
            super.onAwake();
            this._baseInterval = this.effKnock.ani1.interval;
        }
        onEnable() {
            super.onEnable();
            this.btnDiscard.visible = this._isWarehouse;
            this._updateView();
            this._updateBtn();
        }
        onDisable() {
            super.onDisable();
        }
        updateWhenNetReConn() {
            let vo = this._model.vo;
            let roughs = this._isWarehouse ? vo.warehouseRough : vo.rough;
            let isFind = false;
            for (let rough of roughs) {
                if (rough.id == this._vo.id) {
                    this._vo = rough;
                    isFind = true;
                }
            }
            if (isFind) {
                this._updateView();
                this._updateBtn();
            }
            else {
                this.closeSelf();
            }
        }
        _onKnock(layer, artifactId) {
            this._artifactId = artifactId;
            this._setBtnMouseEnable(false);
            this.lblRst.text = sg.translate("石皮") + `-${layer}`;
            this.effKnock.visible = true;
            this.effKnock.ani1.interval = this._baseInterval / 2;
            this.effKnock.ani1.play(0, false);
            sg.sound.playSoundByID(mvc.UISound.WK);
            this._updateBtn();
        }
        _onKnockAniEnd() {
            this._setBtnMouseEnable(true);
            this.effKnock.visible = false;
            this.ani1.play(0, false);
            this._updateView();
            if (this._isAutoKnocking) {
                this._autoKnockNum--;
                if (this._autoKnockNum > 0 && this._vo.layer > 0) {
                    this.effKnock.ani1.gotoAndStop(0);
                    this._ctrl.reqOpenStone(this._vo.id, this._isWarehouse);
                }
                else {
                    this._isAutoKnocking = false;
                }
            }
        }
        _onFloatTxtAniEnd() {
            if (this._artifactId) {
                this.closeSelf();
                sg.uimgr.showUI("pop_artifactKnockSucc", mvc.bagModel.getVoById(this._artifactId));
            }
        }
        _updateView() {
            let vo = this._vo;
            mgr.icon.drawTexture(vo.imgTitle, this.imgTitle);
            mgr.icon.drawTexture(vo.icon, this.imgIcon);
            this.lblProg.text = sg.translate("所需剥离层数：") + vo.layer + "/" + vo.maxLayer;
            if (vo.artifact) {
                this.imgArtifact.visible = true;
                mgr.icon.drawTexture(vo.artifactIcon, this.imgArtifact);
            }
            else {
                this.imgArtifact.visible = false;
            }
        }
        _setBtnMouseEnable(v) {
            this.imgIcon.mouseEnabled = v;
            this.btnDiscard.mouseEnabled = v;
            this.btnTen.mouseEnabled = v;
            this.btnFive.mouseEnabled = v;
        }
        _updateBtn() {
            let cost = mgr.toolsMgr.getGlobalVoById("artifact_knock_stone_cost", 1);
            let num = mgr.toolsMgr.getCountById(cost[0]);
            this.btnFive.disabled = num < 5;
            this.btnTen.disabled = num < 10;
            if (num <= 0)
                mvc.rechargeLimitCtrl.reqRechargeTrigger(mvc.RechargeLimitConst.EventType.HAMMER);
        }
        _onClickIcon() {
            if (this._vo.layer == 0 || this._isAutoKnocking)
                return;
            let cost = mgr.toolsMgr.getGlobalVoById("artifact_knock_stone_cost", 1);
            if (mgr.toolsMgr.checkConsume([cost], true)) {
                this._ctrl.reqOpenStone(this._vo.id, this._isWarehouse);
            }
        }
        _onBtnDisard() {
            if (this._artifactId)
                return;
            sg.uimgr.showConfirm({
                content: sg.translate("是否丢弃这颗原石？有可能浪费已消耗的锤子"),
                btnCancelVisible: true,
                enterFunc: () => {
                    this._ctrl.reqDiscardStone(this._vo.id);
                }
            });
        }
        _onBtnTen() {
            if (this._isAutoKnocking || this._artifactId)
                return;
            this._autoKnock(10);
        }
        _onBtnFive() {
            if (this._isAutoKnocking || this._artifactId)
                return;
            this._autoKnock(5);
        }
        _autoKnock(time) {
            let cost = mgr.toolsMgr.getGlobalVoById("artifact_knock_stone_cost", 1);
            let num = mgr.toolsMgr.getCountById(cost[0]);
            if (num < time)
                return;
            this._autoKnockNum = time;
            this._isAutoKnocking = true;
            this._ctrl.reqOpenStone(this._vo.id, this._isWarehouse);
        }
    }
    mvc.PopArtifactKnock = PopArtifactKnock;
})(mvc || (mvc = {}));

