var mvc;
(function (mvc) {
    class PopArtifactLvUp extends ui.view.artifact.pop_upGradeUI {
        initView(vo) {
            this._model = mvc.artifactModel;
            this._ctrl = mvc.artifactCtrl;
            this._vo = vo;
        }
        initSendMsg() {
        }
        initModelEvent() {
        }
        initCtrlEvent() {
            this.progExp.maxValue = 1;
            this.progExp.label = "";
            this.list.renderHandler = this.createHandler(this, this._listRenderer, undefined, false);
            this.list.mouseHandler = this.createHandler(this, this._onItemClick, undefined, false);
            this.list.vScrollBarSkin = "";
            this.btnOk.on(Laya.Event.CLICK, this, this._onBtnOk);
        }
        onAwake() {
            super.onAwake();
            this.LabelTitle.text = sg.translate("选择升阶材料");
            this.lblEmpty.text = sg.translate("暂无法宝");
        }
        onEnable() {
            super.onEnable();
            let vo = this._model.vo;
            let arr = [];
            this._curExp = 0;
            this._itemNum = 0;
            this._curSelect = [];
            this.progExp.value = 0;
            let lvCfg = sg.dbmgr.get("artifact_artifactUpLv", this._vo.level);
            this._needExp = lvCfg.exp;
            this._itemCfg = mgr.toolsMgr.getGlobalVoById("artifact_up_grade_exp", 1);
            let num = this._itemMaxNum = mvc.bagModel.getItemNumById(this._itemCfg[0]);
            if (num > 0) {
                let vo = new mvc.ItemVo();
                vo.initData(this._itemCfg[0], num);
                arr.push(vo);
            }
            let artifacts = mvc.bagModel.getItemsByType(mvc.BagConst.BagType.Artifact);
            artifacts.sort((a, b) => {
                return b.getCfg().quality - a.getCfg().quality;
            });
            for (let a of artifacts) {
                if (a.bagId != this._vo.bagId && vo.equipped != a.bagId && a.getCfg().quality < 6) {
                    arr.push(a);
                }
            }
            this.list.array = arr;
            this.lblEmpty.visible = arr.length == 0;
            this.progExp.label = this._curExp + "/" + this._needExp;
        }
        onDisable() {
            super.onDisable();
        }
        _listRenderer(cell) {
            let data = cell.dataSource;
            if (!data)
                return;
            cell.initView(data, false);
            if (data.id == this._itemCfg[0]) {
                cell.imgSelect.visible = this._itemNum > 0;
                cell.lblNum.text = this._itemNum + "/" + data.count;
            }
            else {
                cell.imgSelect.visible = this._curSelect.indexOf(data.bagId) != -1;
                cell.lblNum.text = "Lv." + data.level;
            }
        }
        _onItemClick(evt, idx) {
            if (evt.type != Laya.Event.CLICK)
                return;
            let data = this.list.getItem(idx);
            if (!data)
                return;
            if (data.id == this._itemCfg[0]) {
                if (this._itemNum > 0) {
                    let exp = this._itemNum * this._itemCfg[1];
                    this._itemNum = 0;
                    this._curExp -= exp;
                }
                else {
                    if (this._curExp >= this._needExp)
                        return;
                    let exp = this._needExp - this._curExp;
                    let num = Math.min(this._itemMaxNum, Math.ceil(exp / this._itemCfg[1]));
                    this._itemNum = num;
                    this._curExp += num * this._itemCfg[1];
                }
            }
            else {
                let exp = data.getCfg().upGrdExp;
                let i = this._curSelect.indexOf(data.bagId);
                if (i >= 0) {
                    this._curSelect.splice(i, 1);
                    this._curExp -= exp;
                }
                else {
                    if (this._curExp >= this._needExp)
                        return;
                    this._curSelect.push(data.bagId);
                    this._curExp += exp;
                }
            }
            this.list.refresh();
            this.progExp.value = this._curExp / this._needExp;
            this.progExp.label = this._curExp + "/" + this._needExp;
        }
        _onBtnOk() {
            if (!this._curExp) {
                sg.uimgr.showNotice(sg.translate("请选择道具或法宝"));
                return;
            }
            let over = this._curExp - this._needExp;
            if (over < 0) {
                sg.uimgr.showNotice(sg.translate("升阶经验不足"));
                return;
            }
            for (let i = 0, len = this._curSelect.length; i < len; i++) {
                let id = this._curSelect[i];
                if (this._model.getIsInSecret(id)) {
                    sg.uimgr.showConfirm({
                        content: sg.translate("该法宝正在秘藏温养中，是否继续操作？"),
                        btnCancelVisible: true,
                        enterFunc: () => {
                            this._ctrl.reqUpStage(this._vo.bagId, this._curSelect, this._itemNum);
                            this.closeSelf();
                        }
                    });
                    return;
                }
            }
            if (over > 0) {
                sg.uimgr.showConfirm({
                    content: sg.translate("本次升阶有部分经验溢出，是否继续升阶"),
                    btnCancelVisible: true,
                    enterFunc: () => {
                        this._ctrl.reqUpStage(this._vo.bagId, this._curSelect, this._itemNum);
                        this.closeSelf();
                    }
                });
                return;
            }
            this._ctrl.reqUpStage(this._vo.bagId, this._curSelect, this._itemNum);
            this.closeSelf();
        }
    }
    mvc.PopArtifactLvUp = PopArtifactLvUp;
})(mvc || (mvc = {}));

