(function (mvc) {
    class UnitArtifactMiningItem extends ui.view.artifact.unit_artifactMiningItemUI {
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            this.on(Laya.Event.CLICK, this, this._onClick);
        }
        onDisable() {
            super.onDisable();
            this.off(Laya.Event.CLICK, this, this._onClick);
        }
        setData(data, idx) {
            this._data = data;
            this._idx = idx;
            this.redTips.visible = false;
            if (!data) {
                this.boxEmpty.visible = true;
                this.boxPlace.visible = false;
                let isLock = idx >= mvc.artifactModel.miningMaxNum;
                this.imgLock.visible = isLock;
                this.imgAdd.visible = !isLock;
                let arr = mvc.artifactModel.getMineArr();
                this.redTips.visible = arr.length > 0 && this.imgAdd.visible;
            }
            else {
                this.boxEmpty.visible = false;
                this.boxPlace.visible = true;
                let cfg = data.getCfg();
                let url = mgr.icon.getIconPath(cfg.icon);
                mgr.icon.drawTexture(url, this.sprIcon);
                this.clipQua.index = cfg.quality - 1;
                this.lblAdd.text = "+" + mvc.artifactModel.getMiningEff(data.getCfg().quality, data.level);
            }
        }
        _onClick() {
            if (this._idx >= mvc.artifactModel.miningMaxNum) {
                let cfg = mvc.artifactModel.miningOpenConds[this._idx];
                mgr.conditionMgr.checkSingle(cfg, true);
                return;
            }
            sg.uimgr.showUI("pop_artifactChoose", this._idx + 1);
        }
    }
    mvc.UnitArtifactMiningItem = UnitArtifactMiningItem;
})(mvc || (mvc = {}));

var mvc;
(function (mvc) {
    class UnitSecretItem extends ui.view.artifact.unit_SecretItemUI {
        initView(cfg) {
            this._cfg = cfg;
            this._model = mvc.artifactModel;
            this._updateView();
        }
        initModelEvent() {
        }
        initCtrlEvent() {
            this.on(Laya.Event.CLICK, this, this._onClick);
            this.listLevel.renderHandler = this.createHandler(this, this._onListLevel, null, false);
        }
        onEnable() {
            super.onEnable();
            this._lv = 1;
        }
        _updateView() {
            if (this._cfg) {
                if (this._model.vo && this._model.vo.secret_infos.has(this._cfg.id)) {
                    this._lv = this._model.vo.secret_infos.get(this._cfg.id).secret_level;
                }
                this.boxPlace.visible = false;
                this.boxEmpty.visible = false;
                this.listLevel.visible = false;
                if (this._model.vo.secret_infos.has(this._cfg.id)) {
                    let info = this._model.vo.secret_infos.get(this._cfg.id);
                    if (info.item_id != 0) {
                        this.boxPlace.visible = true;
                        let bagItemVo = mvc.bagModel.getItem(info.item_id);
                        let cfg = bagItemVo.getCfg();
                        this.unitModel.changeShowMode(false, cfg.model);
                        this.unitModel.loadedHandle = () => {
                            this.unitModel.play("stand", true);
                        };
                        this.unitModel.loadRole(cfg.model, "PopArtifact");
                        let levelCfg = sg.dbmgr.getArray("artifact_secretLevel", { id: this._cfg.id, level: this._lv })[0];
                        if (levelCfg.condition) {
                            this.redTips.visible = mgr.toolsMgr.checkConsume(levelCfg.condition, false);
                        }
                        else {
                            this.redTips.visible = false;
                        }
                    }
                    else {
                        this.boxEmpty.visible = true;
                        this.imgLock.visible = false;
                        this.imgAdd.visible = true;
                        this.redTips.visible = this._model.getSecretArtifact().length > 0;
                    }
                    this.listLevel.visible = true;
                    this.listLevel.array = [];
                    this.listLevel.array.length = this._cfg.lvMax - 1;
                }
                else {
                    this.boxEmpty.visible = true;
                    this.imgLock.visible = true;
                    this.imgAdd.visible = false;
                    let canUnlock = mgr.conditionMgr.func_role_up_lv(this._cfg.unlock[0], false);
                    this.redTips.visible = canUnlock;
                    if (canUnlock)
                        this.ani1.play(0, true);
                }
            }
        }
        _onClick() {
            if (this._cfg) {
                if (this._model.vo.secret_infos.has(this._cfg.id)) {
                    let info = this._model.vo.secret_infos.get(this._cfg.id);
                    if (!info.item_id) {
                        sg.uimgr.showUI("pop_secretArtifact", this._cfg);
                    }
                    else {
                        let bagItemVo = mvc.bagModel.getItem(info.item_id);
                        sg.uimgr.showUI("pop_attrSelect", this._cfg, bagItemVo.bagId);
                    }
                }
                else {
                    if (mgr.conditionMgr.func_role_up_lv(this._cfg.unlock[0], false)) {
                        mvc.artifactCtrl.reqSecretLvUp(this._cfg.id);
                    }
                }
            }
        }
        _onListLevel(clip, idx) {
            if (this._lv <= this._cfg.lvMax) {
                if (idx < this._lv - 1)
                    clip.index = 1;
                else
                    clip.index = 0;
            }
            else {
                if (idx < this._lv - this._cfg.lvMax)
                    clip.index = 2;
                else
                    clip.index = 1;
            }
        }
        playLockAni() {
            this.clipLock.visible = true;
            this.mouseEnabled = false;
            let end = () => {
                this.clipLock.visible = false;
                this.mouseEnabled = true;
            };
            this.clipLock.offAll(Laya.Event.COMPLETE);
            this.clipLock.on(Laya.Event.COMPLETE, null, end);
            this.clipLock.play(0, 7);
        }
        playChangeAni() {
            this.clipChange.visible = true;
            let end = () => {
                this.clipChange.visible = false;
            };
            this.clipChange.offAll(Laya.Event.COMPLETE);
            this.clipChange.on(Laya.Event.COMPLETE, null, end);
            this.clipChange.play(0, 7);
        }
    }
    mvc.UnitSecretItem = UnitSecretItem;
})(mvc || (mvc = {}));

