(function (mvc) {
    class ViZaloShareModel extends sg.ModelBase {
        constructor() {
            super(...arguments);
            this.rewardInfo = { 1001: 1, 1002: 1, 1003: 1 };
        }
        get reward1() {
            if (!this._reward1) {
                this._reward1 = mgr.toolsMgr.getGlobalVoById("vi_zalo_focus_reward", 1);
            }
            return this._reward1;
        }
        get reward2() {
            if (!this._reward2) {
                this._reward2 = mgr.toolsMgr.getGlobalVoById("vi_zalo_join_reward", 1);
            }
            return this._reward2;
        }
        get reward3() {
            if (!this._reward3) {
                this._reward3 = mgr.toolsMgr.getGlobalVoById("vi_zalo_friend_reward", 1);
            }
            return this._reward3;
        }
        get isGetReward1() {
            return this.rewardInfo && this.rewardInfo[0] && this.rewardInfo[0][0] == 2;
        }
        get isGetReward2() {
            return this.rewardInfo && this.rewardInfo[1] && this.rewardInfo[1][0] == 2;
        }
        get isGetReward3() {
            return this.rewardInfo && this.rewardInfo[2] && this.rewardInfo[2][0] == 2;
        }
        updateRewardInfo(data) {
            for (let i = 0; i < data.length; i++) {
                let id = data[i][0];
                let status = data[i][1];
                if (!this.rewardInfo) {
                    this.rewardInfo = {};
                }
                this.rewardInfo[id] = status;
            }
            this.fireEvent(mvc.ViZaloConst.EVT.UPDATE_VIEW);
        }
        onGetReward(id, status) {
            if (!this.rewardInfo) {
                this.rewardInfo = [];
            }
            if (status == 2) {
                this.rewardInfo[id] = 2;
            }
            else {
                this.rewardInfo[id] = 1;
            }
            switch (id) {
                case 1001:
                    sg.uimgr.showUI("pop_getReward", sg.translate("恭喜获得"), this._reward1);
                    break;
                case 1002:
                    sg.uimgr.showUI("pop_getReward", sg.translate("恭喜获得"), this._reward2);
                    break;
                case 1003:
                    sg.uimgr.showUI("pop_getReward", sg.translate("恭喜获得"), this._reward3);
                    break;
            }
            this.fireEvent(mvc.ViZaloConst.EVT.UPDATE_VIEW);
        }
    }
    mvc.ViZaloShareModel = ViZaloShareModel;
})(mvc || (mvc = {}));

