            vo.params = msgParam;
            vo.protoMsg = msg;
            vo.channel = channel;
            vo.headIcon = model.wxHeadIconUrl;
            vo.sex = model.sex;
            vo.sid = mgr.gplatform.accountGameVo.serverId;
            vo.title = model.title_id;
            vo.lv = model.level;
            vo.guildPost = mvc.guildModel.playerVo ? mvc.guildModel.playerVo.position : 0;
            vo.msg_type = msg_type;
            vo.chatFrame = model["chat_frame_id"];
