        stringSame(str1, str2) {
            if (str1.length > str2.length) {
                let t = str2;
                str2 = str1;
                str1 = t;
            }
            let str1Len = str1.length;
            let str2Len = str2.length;
            let mp = [];
            let i, j, k, lt, tmp;
            for (i = 0; i <= str2Len; i++) {
                mp[i] = i;
            }
            for (i = 1; i <= str1Len; i++) {
                k = str1.charAt(i - 1);
                lt = mp[0];
                mp[0] = mp[0] + 1;
                for (j = 1; j <= str2Len; j++) {
                    tmp = Math.min(mp[j] + 1, mp[j - 1] + 1, lt + (k == str2.charAt(j - 1) ? 0 : 1));
                    lt = mp[j];
                    mp[j] = tmp;
                }
            }
            return (1 - (mp[str2Len] / str2Len));
        }
