var mvc;
(function (mvc) {
    class PopMoveBoard extends ui.view.chat.pop_moveboardUI {
        constructor() {
            super(...arguments);
            this.speed = 4;
        }
        initView(vo) {
        }
        initSendMsg() { }
        initModelEvent() { }
        initCtrlEvent() { }
        updateData(type, vos) {
            if (!vos)
                return;
            this.setContent(vos[0]);
        }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            let [vo] = this.openParams;
            if (!vo)
                return;
            this._pauseTime = 0;
            this.setContent(vo);
        }
        setContent(vo) {
            if (!this.textList)
                this.textList = [];
            if (!vo)
                return;
            this.textList.push(vo);
            this.textList.sort(this.sortList.bind(this));
            this.repeats(20, this.countdown, true);
            if (!this.isPlaying) {
                this.play();
            }
            if (this.textList.length > 10) {
                this.textList.splice(0, this.textList.length - 10);
            }
        }
        play() {
            this._pauseTime = 1000;
            this.isPlaying = true;
            let obj = this.textList.shift();
            mgr.UIAssist.initHtml(this.divContent, { size: 20, color: "#d2ca80", wordWrap: false, stroke: 2, strokeColor: "#000000" });
            this.divContent.innerHTML = obj.rollMsg;
            this.divContent.x = this.showBox.width;
            this.divContent.width = this.divContent.contextWidth;
        }
        countdown() {
            if (!this.divContent) {
                return;
            }
            if (this._pauseTime && this._pauseTime > 0) {
                this._pauseTime -= 20;
            }
            else {
                this.divContent.x -= this.speed;
                if (this.divContent.x + this.divContent.width <= 0) {
                    this.isPlaying = false;
                    if (this.textList.length > 0) {
                        this.play();
                    }
                    else {
                        this.stopTimer(this.countdown);
                        sg.uimgr.hidePermanentUI("perm_moveBroad");
                    }
                }
            }
        }
        sortList(a, b) {
            if (a.msgId === b.msgId)
                return a.time - b.time;
            else
                return b.msgId - a.msgId;
        }
        selectBg(index = 0) {
            let i = index;
            let bg = this.imgBg;
            if (this["imgBg_" + i]) {
                bg = this["imgBg_" + i];
            }
            if (this._lastBg)
                this._lastBg.visible = false;
            bg.visible = true;
            this._lastBg = bg;
            return bg;
        }
        onClosed() {
            super.onClosed();
        }
    }
    mvc.PopMoveBoard = PopMoveBoard;
})(mvc || (mvc = {}));

