(function (mvc) {
    class GodRecycleModel extends sg.ModelBase {
        initModel() {
            this._decomposeItems = [];
        }
        registerEvents() {
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.GOD_RECYCLE, this.redTipsGod, this);
        }
        setInfo(data) {
            if (!this._vo) {
                this._vo = new mvc.GodRecycleVo();
            }
            this._vo.init(data);
            this.fireEvent(mvc.GodRecycleConst.EVT.UPDATE_INFO);
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_RECYCLE);
            mvc.godModel.updateOtherAttr();
        }
        getGodRecycleVo() {
            return this._vo;
        }
        godRecycleGradeUp(data) {
            if (!this._vo) {
                this._vo = new mvc.GodRecycleVo();
            }
            this._vo.grade = data.stage;
            this._vo.level = data.level;
            this._vo.process = data.process;
            this._vo.attr = data.attr;
            this.fireEvent(mvc.GodRecycleConst.EVT.GRADE_UP);
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_RECYCLE);
        }
        godRecycleLevelUp(data) {
            if (!this._vo) {
                this._vo = new mvc.GodRecycleVo();
            }
            this._vo.finish_time = data.finish_time;
            this.fireEvent(mvc.GodRecycleConst.EVT.UPDATE_INFO);
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_RECYCLE);
        }
        godRecycleProces(data) {
            if (!this._vo) {
                this._vo = new mvc.GodRecycleVo();
            }
            this._vo.process = data.process;
            this.fireEvent(mvc.GodRecycleConst.EVT.ADD_PROCESS);
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_RECYCLE);
        }
        godRecycleAdver(data) {
            if (!this._vo) {
                this._vo = new mvc.GodRecycleVo();
            }
            this._vo.ad_time = data.ad_time;
            this.fireEvent(mvc.GodRecycleConst.EVT.UPDATE_INFO);
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_RECYCLE);
        }
        godRecycleChange(data) {
            if (!this._vo) {
                this._vo = new mvc.GodRecycleVo();
            }
            let lastLv = -1;
            lastLv = this._vo.level;
            this._vo.finish_time = data.finish_time;
            this._vo.grade = data.stage;
            this._vo.level = data.level;
            this._vo.process = data.process;
            this._vo.attr = data.attr;
            this.fireEvent(mvc.GodRecycleConst.EVT.UPDATE_INFO);
            if (lastLv != -1 && this._vo.level > lastLv) {
                this.fireEvent(mvc.GodRecycleConst.EVT.LEVEL_UP);
            }
            else
                this.fireEvent(mvc.GodRecycleConst.EVT.UPDATE_INFO);
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_RECYCLE);
        }
        set decomposeItems(arr) {
            this._decomposeItems = arr;
        }
        get decomposeItems() {
            return this._decomposeItems;
        }
        deconposeReward(reward) {
            sg.uimgr.showUI("pop_getReward", sg.translate("分解奖励"), reward);
            this.fireEvent(mvc.GodRecycleConst.EVT.DECOMPOSE);
            mvc.godRecycleCtrl.reqGodRecycleDecompInfo();
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_RECYCLE);
        }
        getGodRecycleCfgs(garde) {
            let arr = sg.dbmgr.getArray("god_godRecovery", { world: garde });
            arr.sort(function (a, b) {
                return a.level - b.level;
            });
            arr.shift();
            return arr;
        }
        getDecompItemNum(items) {
            let num = 0;
            let cfg;
            for (let i = 0; i < this._decomposeItems.length; i++) {
                if (this._decomposeItems[i][0] == mvc.GodRecycleConst.DECOM_ID || this._decomposeItems[i][0] == mvc.GodRecycleConst.DECOM_ID2)
                    continue;
                cfg = sg.dbmgr.get("god_godRecoveryCost", this._decomposeItems[i][0]);
                if (cfg)
                    num += Math.floor(cfg.item_num * this._decomposeItems[i][1] / cfg.item_need);
            }
            if (items) {
                for (let i = 0; i < items.length; i++) {
                    if (items[i][1] == 0)
                        continue;
                    cfg = sg.dbmgr.get("god_godRecoveryCost", items[i][0]);
                    if (cfg)
                        num += Math.floor(cfg.item_num * items[i][1] / cfg.item_need);
                }
            }
            return num;
        }
        redTipsDecomp() {
            if (!this._decomposeItems)
                return 0;
            if (this._decomposeItems.length > 0)
                return 1;
            return 0;
        }
        redTipsGod() {
            if (!this._vo)
                return 0;
            if (!mgr.conditionMgr.checkFunc(mvc.FUNC_ID.GOD_RECYCLE, false))
                return 0;
            let cfg = sg.dbmgr.getArray("god_godRecovery", { world: this._vo.grade, level: this._vo.level })[0];
            if (cfg) {
                if (this._vo.process < cfg.grade && mgr.toolsMgr.checkConsume(cfg.cost, false))
                    return 1;
                if (this._vo.process >= cfg.grade && cfg.grade > 0 && this._vo.finish_time == 0)
                    return 1;
                if (cfg.break == 1)
                    return 1;
            }
            return this.redTipsDecomp();
        }
    }
    mvc.GodRecycleModel = GodRecycleModel;
})(mvc || (mvc = {}));

