            this.btnAccess2.on(Laya.Event.CLICK, this, this._onBtnAccess2);
            this.btnAdd1.on(Laya.Event.MOUSE_DOWN, this, this._mouseHandle, [1, mvc.GodRecycleConst.DECOM_ID]);
            this.btnAdd1.on(Laya.Event.MOUSE_MOVE, this, this._mouseHandle, [1, mvc.GodRecycleConst.DECOM_ID]);
            this.btnAdd1.on(Laya.Event.MOUSE_UP, this, this._mouseHandle, [1, mvc.GodRecycleConst.DECOM_ID]);
            this.btnAdd1.on(Laya.Event.MOUSE_OUT, this, this._mouseHandle, [1, mvc.GodRecycleConst.DECOM_ID]);
            this.btnReduce1.on(Laya.Event.MOUSE_DOWN, this, this._mouseHandle, [2, mvc.GodRecycleConst.DECOM_ID]);
            this.btnReduce1.on(Laya.Event.MOUSE_MOVE, this, this._mouseHandle, [2, mvc.GodRecycleConst.DECOM_ID]);
            this.btnReduce1.on(Laya.Event.MOUSE_UP, this, this._mouseHandle, [2, mvc.GodRecycleConst.DECOM_ID]);
            this.btnReduce1.on(Laya.Event.MOUSE_OUT, this, this._mouseHandle, [2, mvc.GodRecycleConst.DECOM_ID]);
            this.btnAdd2.on(Laya.Event.MOUSE_DOWN, this, this._mouseHandle, [1, mvc.GodRecycleConst.DECOM_ID2]);
            this.btnAdd2.on(Laya.Event.MOUSE_MOVE, this, this._mouseHandle, [1, mvc.GodRecycleConst.DECOM_ID2]);
            this.btnAdd2.on(Laya.Event.MOUSE_UP, this, this._mouseHandle, [1, mvc.GodRecycleConst.DECOM_ID2]);
            this.btnAdd2.on(Laya.Event.MOUSE_OUT, this, this._mouseHandle, [1, mvc.GodRecycleConst.DECOM_ID2]);
            this.btnReduce2.on(Laya.Event.MOUSE_DOWN, this, this._mouseHandle, [2, mvc.GodRecycleConst.DECOM_ID2]);
            this.btnReduce2.on(Laya.Event.MOUSE_MOVE, this, this._mouseHandle, [2, mvc.GodRecycleConst.DECOM_ID2]);
            this.btnReduce2.on(Laya.Event.MOUSE_UP, this, this._mouseHandle, [2, mvc.GodRecycleConst.DECOM_ID2]);
            this.btnReduce2.on(Laya.Event.MOUSE_OUT, this, this._mouseHandle, [2, mvc.GodRecycleConst.DECOM_ID2]);
