(function (mvc) {
    class UnitGodRecycle extends ui.view.godRecycle.unit_godRecycleUI {
        initView() {
            this._model = mvc.godRecycleModel;
        }
        initSendMsg() {
            mvc.godRecycleCtrl.reqGodRecycleInfo();
            mvc.godRecycleCtrl.reqGodRecycleDecompInfo();
        }
        initModelEvent() {
            this.bindModelEvent(this._model, mvc.GodRecycleConst.EVT.UPDATE_INFO, this._updateView);
            this.bindModelEvent(this._model, mvc.GodRecycleConst.EVT.ADD_PROCESS, this._addProess);
            this.bindModelEvent(this._model, mvc.GodRecycleConst.EVT.GRADE_UP, this._gardeUp);
            this.bindModelEvent(this._model, mvc.GodRecycleConst.EVT.LEVEL_UP, this._levelUp);
            this.bindModelEvent(mvc.bagModel, mvc.BagConst.EVT.ITEM_NUM_CHANGE, this._itemNumChange);
            this.bindModelEvent(this._model, mvc.GodRecycleConst.EVT.UPDATE_DECOM_INFO, this._updateDecomRed);
        }
        initCtrlEvent() {
            this.on(Laya.Event.CLICK, this, this._onClick);
            this.btnAccess.on(Laya.Event.CLICK, this, this._onBtnAccess);
            this.listAttr.vScrollBarSkin = "";
            this.listAttr.renderHandler = this.createHandler(this, this._renderListAttr, null, false);
            this.listRules.itemRender = mvc.UnitGodRecycleItem;
            this.listRules.selectEnable = true;
            this.listRules.selectHandler = this.createHandler(this, this._selectListRule, null, false);
            this.unitEffLvUp.ani1.on(Laya.Event.COMPLETE, this, this._ruleEffEnd);
            this.effChonggou.ani1.on(Laya.Event.COMPLETE, this, this._gardeUpAniEnd);
        }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            this.unitEffLvUp.visible = false;
            this.effChonggou.visible = false;
        }
        onJumpInit(jumpParams) {
        }
        onDisable() {
            this._senceSpine && this._senceSpine.recycle();
            this._senceSpine = null;
            this.boxUI.visible = true;
            super.onDisable();
        }
        _updateView() {
            this._vo = this._model.getGodRecycleVo();
            if (this._vo) {
                let arr = this._model.getGodRecycleCfgs(this._vo.grade);
                this.listRules.array = arr;
                if (arr && arr.length > 0)
                    this.listRules.selectedIndex = this._vo.level <= arr.length - 1 ? this._vo.level : arr.length - 1;
                this.boxBreak.visible = this.boxLvUp.visible = this.btnEvolution.visible = this.boxEnd.visible = false;
                let cfg = sg.dbmgr.getArray("god_godRecovery", { world: this._vo.grade, level: this._vo.level })[0];
                if (cfg) {
                    this._cfg = cfg;
                    if (this._vo.finish_time > 0) {
                        this.boxBreak.visible = true;
                        this.repeats(1000, this._onTimer, true);
                        let adCd = mgr.toolsMgr.getGlobalVoById("speed_up_god_recovery_ad", 1)[1] * 60;
                        this._adTime = this._vo.ad_time + adCd;
                        let now = sg.time.getSecondTime();
                        if (this._adTime > now) {
                            this.repeats(1000, this._onTimerAd, true);
                        }
                        else {
                            this.lblAdTime.text = "";
                        }
                        this._updateAccItemNum();
                    }
                    else if (cfg.break == 1) {
                        this.btnEvolution.visible = true;
                    }
                    else if (!cfg.grade && !cfg.break) {
                        this.boxEnd.visible = true;
                    }
                    else {
                        this.boxLvUp.visible = true;
                        this.progLv.updateView(this._vo.process / cfg.grade, cfg.grade);
                        this.btnBreak.visible = this._vo.process >= cfg.grade;
                        this.btnLvUp.visible = !this.btnBreak.visible;
                        this.lblUpTime.text = sg.time.formatTimeStr(cfg.time);
                    }
                    let cfg2 = sg.dbmgr.get("god_godRecoveryShow", this._vo.grade);
                    if (cfg2) {
                        mgr.icon.drawTexture(mgr.icon.getIconPath(cfg2.world), this.imgGodBg);
                        mgr.icon.drawTexture(mgr.icon.getIconPath(cfg2.level), this.imgGod);
                        mgr.icon.drawTexture(mgr.icon.getIconPath(cfg2.ruleName), this.imgTitle);
                    }
                    this._updateLvUpCost();
                }
            }
            this._updateDecomRed();
        }
        _itemNumChange() {
            this._updateAccItemNum();
            this._updateLvUpCost();
        }
        _updateAccItemNum() {
            let id = mgr.toolsMgr.getGlobalVoById("speed_up_god_recovery", 1)[0];
            let num = mgr.toolsMgr.getCountById(id);
            let url = mgr.toolsMgr.getIconById(id);
            url = mgr.icon.getIconPath(url);
            mgr.icon.drawTexture(url, this.imgAccIcon);
            this.lblAccNum.text = num + "";
            this.lblAccNum.color = num > 0 ? mvc.COLOR.GREEN : mvc.COLOR.RED;
        }
        _updateLvUpCost() {
            if (!this._cfg || !this._cfg.cost)
                return;
            let cost = this._cfg.cost;
            let num = mgr.toolsMgr.getCountById(cost[0][0]);
            let url = mgr.toolsMgr.getIconById(cost[0][0]);
            url = mgr.icon.getIconPath(url);
            mgr.icon.drawTexture(url, this.imgCoin);
            this.lblCoinNum.text = cost[0][1] + "";
            this.lblCoinNum.color = num >= cost[0][1] ? mvc.COLOR.GREEN : mvc.COLOR.RED;
            this.redStageUp.visible = num >= cost[0][1];
            mgr.icon.drawTexture(url, this.imgIcon);
            this.lblTotal.text = "" + num;
        }
        _selectListRule(index) {
            let cfg = this.listRules.array[index];
            if (cfg) {
                this.listAttr.array = mvc.PropertyModel.generateListData2(cfg.attribute);
                this.lblRuleName.text = cfg.ruleName;
            }
        }
        _renderListAttr(cell, index) {
            let data = this.listRules.selectedItem;
            if (!data)
                return;
            let lblName = cell.getChildByName("lblName");
            let lblValue = cell.getChildByName("lblValue");
            let vo = this._vo;
            if (vo.level >= data.level) {
                lblName.color = "#ffffff";
                lblValue.color = "#60ffb6";
            }
            else if (vo.level + 1 == data.level) {
                lblName.color = "#ffffff";
                lblValue.color = "#ffffff";
            }
            else {
                lblName.color = "#97a4b2";
                lblValue.color = "#97a4b2";
            }
        }
        _updateDecomRed() {
            this.redTipsDecom.visible = mvc.godRecycleModel.decomposeItems.length > 0;
        }
        _addProess() {
            this.clipEffStageUp.visible = true;
            this.clipEffStageUp.play(0, this.clipEffStageUp.total - 1);
            this._updateView();
        }
        _levelUp() {
            this.mouseEnabled = false;
            this.clipRuleEff1.visible = true;
            this.clipRuleEff1.play(0, this.clipRuleEff1.total - 1);
            this.clipRuleEff2.visible = true;
            this.clipRuleEff2.play(0, this.clipRuleEff1.total - 1);
            this.unitEffLvUp.visible = true;
            this.listAttr.scrollTo(0);
            this.unitEffLvUp.ani1.play(0, false);
        }
        _ruleEffEnd() {
            this.mouseEnabled = true;
            this.unitEffLvUp.visible = false;
            this._updateView();
        }
        _gardeUp() {
            this.boxUI.visible = false;
            let spine = sg.SpineSprite.create("9101", true, false, false, "stand");
            let self = this;
            spine.on(Laya.Event.STOPPED, null, () => {
                self.effChonggou.visible = true;
                self.effChonggou.ani1.play(0, false);
            });
            this.boxEff.addChild(spine);
            spine.x = this.boxEff.width / 2;
            spine.y = this.boxEff.height / 2;
            this._senceSpine = spine;
        }
        _gardeUpAniEnd() {
            this._updateView();
            this.boxUI.visible = true;
            this.effChonggou.visible = false;
        }
        _onTimer() {
            let last = this._vo && this._vo.finish_time - sg.time.getSecondTime();
            if (last > 0) {
                this.lblUpCountTime.text = sg.time.formatTimeStr(last);
            }
            else {
                this.stopTimer(this._onTimer);
            }
        }
        _onTimerAd() {
            let last = this._adTime - sg.time.getSecondTime();
            if (last > 0) {
                this.lblAdTime.text = sg.time.formatTimeStr(last);
            }
            else {
                this.lblAdTime.text = "";
                this.stopTimer(this._onTimerAd);
            }
        }
        _onBtnAccess() {
            if (!this._cfg)
                return;
            let cost = this._cfg.cost;
            sg.uimgr.showAccess(cost[0][0]);
        }
        _onClick(e) {
            switch (e.target) {
                case this.btnAttr:
                    {
                        if (this._vo)
                            sg.uimgr.showUI("pop_godRecycleAttr", this._vo.attr);
                    }
                    break;
                case this.btnLvUp:
                    {
                        if (this._cfg && this._cfg.cost && mgr.toolsMgr.checkConsume(this._cfg.cost, true))
                            mvc.godRecycleCtrl.reqGodRecycleAddProcess();
                    }
                    break;
                case this.btnBreak:
                    {
                        if (this._cfg && this._vo && this._vo.process >= this._cfg.grade)
                            mvc.godRecycleCtrl.reqGodRecycleLvUp();
                    }
                    break;
                case this.btnEvolution:
                    {
                        if (this._cfg && this._cfg.break)
                            mvc.godRecycleCtrl.reqGodRecycleStageUp();
                    }
                    break;
                case this.btnAcc:
                    {
                        if (this._vo && this._vo.finish_time > 0)
                            sg.uimgr.showUI("pop_accComplate", this._vo.finish_time, 4);
                    }
                    break;
                case this.btnDecomp:
                    {
                        sg.uimgr.showUI("pop_godRecycleDecom");
                    }
                    break;
                case this.btnLookAd:
                    {
                        if (!this._vo || this._vo.finish_time <= 0)
                            return;
                        let now = sg.time.getSecondTime();
                        if (now < this._adTime)
                            return;
                        mgr.gplatform.showAdvertVideo(sdk.ADVERT_VIDEO_SRC.GODRECYCLE, (suc) => {
                            if (suc) {
                                mvc.godRecycleCtrl.reqGodRecycleAd();
                            }
                        });
                    }
                    break;
                case this.btnUnionHelp:
                    {
                        if (!this._vo || this._vo.finish_time <= 0)
                            return;
                        if (mvc.roleModel.roleInfo.guildId <= 0) {
                            sg.uimgr.showNotice(sg.translate("您还没加入仙盟"));
                            return;
                        }
                        mvc.guildCtrl.reqGuildSeekHelp(mvc.GuildConst.HELP_TYPE.GOD_RECYCLE, this._vo.level + 1, this._vo.grade);
                    }
                    break;
            }
        }
    }
    mvc.UnitGodRecycle = UnitGodRecycle;
})(mvc || (mvc = {}));

