(function (mvc) {
    class GodVo extends sg.VoBase {
        constructor() {
            super();
            this.soulMap = new Map();
        }
        init(data) {
            this.cloneProtoData(data);
            this.useSlot = data.combat_soul;
            this.cfg = sg.dbmgr.get("god_god", this.id);
            this.soulMap.clear();
            for (let s of data.soul) {
                this.soulMap.set(s.type, s);
            }
        }
        getClipNum() {
            return mgr.toolsMgr.getCountById(this.cfg.itemId);
        }
        getWuxing() {
            return this.getSlotWuxing(this.useSlot);
        }
        getSlotWuxing(type) {
            if (!this.cfg)
                return 0;
            for (let d of this.cfg.soulElement) {
                if (d[0] == type) {
                    return d[1];
                }
            }
            return 0;
        }
        isSoulAttrActive(type) {
            let soul = this.soulMap.get(type);
            if (!soul || !soul.bead)
                return false;
            let vo = mvc.bagModel.getVoById(soul.bead);
            for (let s of this.soulMap.values()) {
                if (s.type == soul.type)
                    continue;
                if (s.bead) {
                    let vo2 = mvc.bagModel.getVoById(s.bead);
                    if (vo.attr[0][0] == vo2.attr[0][0] && (vo.attr[0][1] < vo2.attr[0][1] || (vo.attr[0][1] == vo2.attr[0][1] && soul.type > s.type))) {
                        return false;
                    }
                }
            }
            return true;
        }
        isShowRedLvUp() {
            if (mvc.godModel.isLineup(this.id)) {
                let breakCfg = sg.dbmgr.get("god_break", this.break + 1);
                if (breakCfg && this.level == breakCfg.condition) {
                    return mgr.toolsMgr.checkConsume(breakCfg.breakConsume);
                }
                else {
                    let lvCfg = sg.dbmgr.get("god_godLvUp", this.level + 1);
                    if (lvCfg) {
                        lvCfg = sg.dbmgr.get("god_godLvUp", this.level);
                        return mgr.toolsMgr.checkConsume(lvCfg.consume);
                    }
                }
            }
            else {
                return false;
            }
        }
        isShowRedSoul() {
            let balls = mvc.bagModel.getItemsByType(mvc.BagConst.BagType.ELEMENT_BEAD);
            let haveOne = false;
            for (let ball of balls) {
                if (!ball.bead.god_id) {
                    haveOne = true;
                    break;
                }
            }
            let cfgs = sg.dbmgr.getDB("god_godSoul");
            for (let type in cfgs) {
                let soulInfo = this.soulMap.get(Number(type));
                if (!soulInfo || !soulInfo.is_unlock) {
                    if (this.grade >= cfgs[type].condition[1]) {
                        return true;
                    }
                }
                else {
                    if (!soulInfo.bead && haveOne) {
                        return true;
                    }
                }
            }
            return false;
        }
        canStarUp() {
            let nextCfg = sg.dbmgr.get("god_godStarUp", this.grade + 1);
            if (nextCfg) {
                let curNum = mgr.toolsMgr.getCountById(this.cfg.itemId);
                return curNum >= nextCfg.cost;
            }
            else {
                return false;
            }
        }
        getGodSoulVos() {
            let ret = [];
            let cfgs = sg.dbmgr.getDB("god_godSoul");
            for (let key in cfgs) {
                let cfg = cfgs[key];
                let vo = new mvc.GodSoulItemVo();
                vo.init(this, cfg.id);
                ret.push(vo);
            }
            return ret;
        }
        get skillCfg() {
            if (this.fashion) {
                let vo = mvc.godModel.skinMap.get(this.fashion);
                return sg.dbmgr.get("skill_skill", vo.skillId);
            }
            else {
                let starCfg = sg.dbmgr.get("god_godStarUp", this.grade);
                return sg.dbmgr.getUnique("skill_skill", this.cfg.skill, starCfg.skillLv);
            }
        }
        get skillName() {
            if (this.fashion) {
                let fcfg = sg.dbmgr.get("god_godFashion", this.fashion);
                return fcfg.skillName;
            }
            else {
                return this.skillCfg.name;
            }
        }
        get model() {
            if (this.fashion) {
                let skinCfg = sg.dbmgr.get("god_godFashion", this.fashion);
                return skinCfg.avatar;
            }
            else {
                return this.cfg.model;
            }
        }
        get icon() {
            if (this.fashion) {
                let skinCfg = sg.dbmgr.get("god_godFashion", this.fashion);
                return skinCfg.icon;
            }
            else {
                return this.cfg.icon;
            }
        }
    }
    mvc.GodVo = GodVo;
})(mvc || (mvc = {}));

var mvc;
(function (mvc) {
    let EVT = mvc.GodConst.EVT;
    class GodModel extends sg.ModelBase {
        constructor() {
            super(...arguments);
            this.skipAni = false;
        }
        initModel() {
            this.godMap = new Map();
            this.lastGodMap = new Map();
            this.lineup = new Map();
            this.atlasMap = new Map();
            this.selectBall = new Map();
            this.lottteryVoMap = {};
            this.skinMap = new Map();
            this.newSkins = [];
        }
        registerEvents() {
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.GOD_LOTTERY_ONE, this._redotLottery.bind(this, mvc.GodConst.GodLotteryType.LOTTERY_ONE), this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.GOD_LOTTERY_TWO, this._redotLottery.bind(this, mvc.GodConst.GodLotteryType.LOTTERY_TWO), this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.GOD_LOTTERY_THREE, this._redotLottery.bind(this, mvc.GodConst.GodLotteryType.LOTTERY_THREE), this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.GOD_ATLAS_ONE, this._redotAtlas.bind(this, mvc.GodConst.GodAtlasType.NORMAL), this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.GOD_ATLAS_TWO, this._redotAtlas.bind(this, mvc.GodConst.GodAtlasType.SPECIAL), this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.GOD_STAR_UP, this._checkRedStarUp, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.GOD_LINEUP, this._checkRedLineup, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.GOD_LV_UP, this._checkRedLvUp, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.GOD_EQIUP_SOUL, this._checkRedEquipSoul, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.GOD_COMPOSE, this._checkRedCompose, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.GOD_UNLOCK_SOUL, this._checkRedSoulUnlock, this);
        }
        willEnterGame() {
        }
        setGodLotteryInfo(data) {
            let vo = this.lottteryVoMap[data.lottery_id];
            if (!vo) {
                vo = new mvc.GodLotteryVo();
                this.lottteryVoMap[data.lottery_id] = vo;
            }
            vo.updateData(data);
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_LOTTERY_ONE);
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_LOTTERY_TWO);
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_LOTTERY_THREE);
        }
        godLottery(data) {
            this.lottteryVoMap[data.lottery_id].lastFreeTime = data.last_free_lottery_time;
            this.lottteryVoMap[data.lottery_id].bottom_times = data.bottom_times;
            this.lottteryVoMap[data.lottery_id].is_big_bottom = data.is_big_bottom;
            this.fireEvent(EVT.LOTTERY_PLAY_ANI, data);
            this.fireEvent(EVT.UPDATE_LOTTERY_VIEW);
            if (data.lottery_id == mvc.GodConst.GodLotteryType.LOTTERY_ONE)
                mgr.redotMgr.check(mvc.REDOT_ID.GOD_LOTTERY_ONE);
            else if (data.lottery_id == mvc.GodConst.GodLotteryType.LOTTERY_TWO) {
                mgr.redotMgr.check(mvc.REDOT_ID.GOD_LOTTERY_TWO);
            }
            else
                mgr.redotMgr.check(mvc.REDOT_ID.GOD_LOTTERY_THREE);
        }
        _redotLottery(type) {
            if (!mgr.conditionMgr.checkFunc(mvc.FUNC_ID.GOD, false))
                return 0;
            let vo = this.lottteryVoMap[type];
            if (!vo)
                return 0;
            let cfg = sg.dbmgr.get("god_draw", type);
            if (!vo.status)
                return 0;
            if (cfg.freeTimes > 0) {
                let haveFree = vo.lastFreeTime == 0 || sg.time.getSecondTime() - vo.lastFreeTime >= cfg.freeTimes;
                if (haveFree)
                    return 1;
            }
            let itemId = cfg.singleDraw[0][0];
            let cost = cfg.singleDraw[0][1];
            let count = mgr.toolsMgr.getCountById(itemId);
            if (count >= cost)
                return 1;
            else
                return 0;
        }
        setAtlasInfo(data) {
            for (let info of data.atlas_info) {
                let vo = new mvc.GodAtlasVo();
                vo.init(info[0], info[1]);
                this.atlasMap.set(info[0], vo);
            }
            this._updateAtlasAttr();
            this.updateOtherAttr();
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_ATLAS_ONE);
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_ATLAS_TWO);
        }
        activeOrUp(data) {
            let vo = new mvc.GodAtlasVo();
            vo.init(data.atlas_id, data.class);
            this.atlasMap.set(data.atlas_id, vo);
            this._updateAtlasAttr();
            this.updateOtherAttr();
            this.fireEvent(EVT.UPDATE_ATLAS_VIEW);
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_ATLAS_ONE);
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_ATLAS_TWO);
            this.fireEvent(EVT.PLAY_UP_ANI, data.atlas_id, data.class);
        }
        canActive(data) {
            let canActive = true;
            for (let id of data) {
                if (!this.isHaveGod(id)) {
                    canActive = false;
                    return canActive;
                }
            }
            return canActive;
        }
        canUp(data, consume) {
            let canUp = true;
            for (let id of data) {
                if (this.godMap.get(id).grade < consume) {
                    canUp = false;
                    return canUp;
                }
            }
            return canUp;
        }
        getAlreadyActiveNum(data) {
            let num = 0;
            for (let id of data) {
                if (this.isHaveGod(id))
                    num++;
            }
            return num;
        }
        getMeetUpNum(data, atlasClass) {
            let num = 0;
            for (let id of data) {
                if (this.isHaveGod(id) && this.godMap.get(id).grade >= atlasClass)
                    num++;
            }
            return num;
        }
        _updateAtlasAttr() {
            let attrMap = {};
            this.atlasMap.forEach((key, val) => {
                let cfg = sg.dbmgr.getArray("god_contractClassUp", { contractId: key.id, class: key.class })[0];
                if (attrMap[cfg.allGodAttr[0][0]]) {
                    attrMap[cfg.allGodAttr[0][0]] += cfg.allGodAttr[0][1];
                }
                else {
                    attrMap[cfg.allGodAttr[0][0]] = cfg.allGodAttr[0][1];
                }
            });
            let arr = [];
            for (let key in attrMap) {
                let attr = attrMap[key];
                let cfg = mvc.PropertyModel._getCfg(key);
                if (!cfg) {
                    sg.loge("read prop cfg fail, key" + key);
                    continue;
                }
                arr.push({
                    cfg: cfg,
                    lblName: cfg.show_name,
                    lblValue: cfg.is_per == 1 ? (attrMap[key] / 100) + "%" : attr.toString(),
                    value: attr,
                    isPer: cfg.is_per == 1
                });
            }
            arr.sort((a, b) => {
                if (a.cfg.show_priority != b.cfg.show_priority) {
                    return a.cfg.show_priority - b.cfg.show_priority;
                }
                return a.cfg.id - b.cfg.id;
            });
            this.atlasAttr = arr;
        }
        updateOtherAttr() {
            let arr = [];
            for (let key in this.atlasAttr) {
                let data = this.atlasAttr[key];
                arr.push({
                    cfg: data.cfg,
                    lblName: data.lblName,
                    lblValue: data.lblValue,
                    value: parseInt(data.value),
                    isPer: data.isPer
                });
            }
            let vo = mvc.godRecycleModel.getGodRecycleVo();
            if (vo && vo.attr) {
                for (let i = 0; i < vo.attr.length; i++) {
                    let cfg = sg.dbmgr.get("attribute", vo.attr[i][0]);
                    if (cfg) {
                        let isNew = true;
                        for (let n = 0; n < arr.length; n++) {
                            if (arr[n].cfg.id == vo.attr[i][0]) {
                                isNew = false;
                                arr[n].value += vo.attr[i][1];
                                arr[n].lblValue = arr[n].isPer == 1 ? (arr[n].value / 100) + "%" : arr[n].value.toString();
                                break;
                            }
                        }
                        if (isNew) {
                            let cfg = sg.dbmgr.get("attribute", vo.attr[i][0]);
                            if (cfg) {
                                arr.push({
                                    cfg: cfg,
                                    lblName: cfg.show_name,
                                    lblValue: cfg.is_per == 1 ? (vo.attr[i][1] / 100) + "%" : vo.attr[i][1].toString(),
                                    value: vo.attr[i][1],
                                    isPer: cfg.is_per == 1
                                });
                            }
                        }
                    }
                }
            }
            arr.sort((a, b) => {
                if (a.cfg.show_priority != b.cfg.show_priority) {
                    return a.cfg.show_priority - b.cfg.show_priority;
                }
                return a.cfg.id - b.cfg.id;
            });
            this.otherAttr = arr;
        }
        _redotAtlas(type) {
            if (!mgr.conditionMgr.checkFunc(mvc.FUNC_ID.GOD, false))
                return 0;
            let cfg = sg.dbmgr.getArray("god_contractList", { type: type });
            for (let info of cfg) {
                if (this.atlasMap.has(info.id)) {
                    let vo = this.atlasMap.get(info.id);
                    let nextUpCfg = sg.dbmgr.getArray("god_contractClassUp", { contractId: vo.id, class: vo.class + 1 })[0];
                    if (nextUpCfg && this.canUp(info.group[0], nextUpCfg.consume))
                        return 1;
                }
                else {
                    if (this.canActive(info.group[0]))
                        return 1;
                }
            }
            return 0;
        }
        _checkRedStarUp() {
            if (!mgr.conditionMgr.checkFunc(mvc.FUNC_ID.GOD, false))
                return 0;
            for (let god of this.godMap.values()) {
                let nextCfg = sg.dbmgr.get("god_godStarUp", god.grade + 1);
                if (nextCfg) {
                    let curNum = mgr.toolsMgr.getCountById(god.cfg.itemId);
                    if (curNum >= nextCfg.cost) {
                        return 1;
                    }
                }
            }
            return 0;
        }
        _checkRedLineup() {
            if (!mgr.conditionMgr.checkFunc(mvc.FUNC_ID.GOD, false))
                return 0;
            let emptyNum = 0;
            let lineupGod = 0;
            if (!this.lineup.get(1)) {
                emptyNum++;
            }
            else {
                lineupGod++;
            }
            if (this.isPos2Open()) {
                if (this.lineup.get(2)) {
                    lineupGod++;
                }
                else {
                    emptyNum++;
                }
            }
            return emptyNum > 0 && ((this.godMap.size - lineupGod) >= emptyNum) ? 1 : 0;
        }
        _checkRedLvUp() {
            if (!mgr.conditionMgr.checkFunc(mvc.FUNC_ID.GOD, false))
                return 0;
            for (let i = 1; i <= 2; i++) {
                let id = this.lineup.get(i);
                if (!id)
                    continue;
                let vo = this.godMap.get(id);
                let breakCfg = sg.dbmgr.get("god_break", vo.break + 1);
                if (breakCfg && vo.level == breakCfg.condition) {
                    if (mgr.toolsMgr.checkConsume(breakCfg.breakConsume))
                        return 1;
                }
                else {
                    let lvCfg = sg.dbmgr.get("god_godLvUp", vo.level + 1);
                    if (lvCfg) {
                        lvCfg = sg.dbmgr.get("god_godLvUp", vo.level);
                        if (mgr.toolsMgr.checkConsume(lvCfg.consume))
                            return 1;
                    }
                }
            }
            return 0;
        }
        _checkRedEquipSoul() {
            if (!mgr.conditionMgr.checkFunc(mvc.FUNC_ID.GOD, false))
                return 0;
            let balls = mvc.bagModel.getItemsByType(mvc.BagConst.BagType.ELEMENT_BEAD);
            let haveOne = false;
            for (let ball of balls) {
                if (!ball.bead.god_id) {
                    haveOne = true;
                    break;
                }
            }
            if (!haveOne)
                return 0;
            let cfgs = sg.dbmgr.getDB("god_godSoul");
            for (let i = 1; i <= 2; i++) {
                let id = this.lineup.get(i);
                if (!id)
                    continue;
                let vo = this.godMap.get(id);
                for (let type in cfgs) {
                    let soulInfo = vo.soulMap.get(Number(type));
                    if (!soulInfo || !soulInfo.is_unlock)
                        continue;
                    if (!soulInfo.bead)
                        return 1;
                }
            }
            return 0;
        }
        _checkRedSoulUnlock() {
            if (!mgr.conditionMgr.checkFunc(mvc.FUNC_ID.GOD, false))
                return 0;
            let cfgs = sg.dbmgr.getDB("god_godSoul");
            for (let id of this.lineup.values()) {
                let vo = this.godMap.get(id);
                if (!vo)
                    continue;
                for (let type in cfgs) {
                    let soulInfo = vo.soulMap.get(Number(type));
                    if (!soulInfo || !soulInfo.is_unlock) {
                        if (vo.grade >= cfgs[type].condition[1]) {
                            return 1;
                        }
                    }
                }
            }
            return 0;
        }
        _checkRedCompose() {
            if (!mgr.conditionMgr.checkFunc(mvc.FUNC_ID.GOD, false))
                return 0;
            let cfgs = sg.dbmgr.getDB("god_ god");
            for (let key in cfgs) {
                if (this.godMap.has(Number(key)))
                    continue;
                let cfg = cfgs[key];
                let starCfg = sg.dbmgr.get("god_godStarUp", 0);
                let num = mgr.toolsMgr.getCountById(cfg.itemId);
                if (num >= starCfg.cost[1])
                    return 1;
            }
            return 0;
        }
        updateGodsInfo(data) {
            this.godMap.clear();
            for (let g of data.gods) {
                let vo = new mvc.GodVo();
                vo.init(g);
                this.godMap.set(vo.id, vo);
            }
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_STAR_UP);
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_LINEUP);
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_EQIUP_SOUL);
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_LV_UP);
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_COMPOSE);
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_UNLOCK_SOUL);
            this.newGodMap = sg.varmgr.getUserVar("new_god_map") || {};
        }
        updateLineupInfo(data) {
            this.lineup.clear();
            for (let l of data.on_battle) {
                this.lineup.set(l[0], l[1]);
            }
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_LINEUP);
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_EQIUP_SOUL);
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_LV_UP);
        }
        godAttrChange(data) {
            let vo = this.godMap.get(data.id);
            if (!vo)
                return;
            vo.attr = data.attr;
        }
        godCompose(data) {
            let vo = new mvc.GodVo();
            vo.init(data.god);
            this.godMap.set(vo.id, vo);
            this.fireEvent(mvc.GodConst.EVT.GOD_COMPOSE);
            if (data.is_compose) {
                sg.uimgr.showNotice(sg.translate("合成成功"), "green");
            }
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_ATLAS_ONE);
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_ATLAS_TWO);
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_STAR_UP);
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_LINEUP);
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_COMPOSE);
            this.newGodMap[data.god.id] = true;
            sg.varmgr.setUserVar("new_god_map", this.newGodMap);
            if (data.is_compose)
                sg.uimgr.showUI("pop_godLotteryResultSpc", null, [data.god.id], true);
        }
        godLvUp(data) {
            let vo = this.godMap.get(data.id);
            let isten = data.level - vo.level > 1;
            vo.level = data.level;
            this.fireEvent(mvc.GodConst.EVT.GOD_LEVEL_UP, data.id, isten);
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_LV_UP);
        }
        godBreak(data) {
            let vo = this.godMap.get(data.id);
            vo.break = data.break;
            this.fireEvent(mvc.GodConst.EVT.GOD_BREAK, data.id);
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_LV_UP);
        }
        godUpGrade(data) {
            let vo = this.godMap.get(data.id);
            vo.grade = data.grade;
            this.fireEvent(mvc.GodConst.EVT.GOD_UP_GRADE, data.id);
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_STAR_UP);
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_ATLAS_ONE);
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_ATLAS_TWO);
        }
        godTrans(data) {
            let vo = this.godMap.get(data.god.id);
            vo.init(data.god);
            vo = this.godMap.get(data.to_god.id);
            vo.init(data.to_god);
            this.fireEvent(mvc.GodConst.EVT.GOD_TRANS, data.god.id);
            sg.uimgr.showNotice(sg.translate("传承成功"), "green");
        }
        soulUnlock(data) {
            let vo = this.godMap.get(data.id);
            vo.soulMap.set(data.soul.type, data.soul);
            this.fireEvent(mvc.GodConst.EVT.SOUL_UNLOCK, data.id, data.soul.type);
            sg.uimgr.showNotice(sg.translate("解锁成功"), "green");
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_EQIUP_SOUL);
        }
        soulEquip(data) {
            let vo = this.godMap.get(data.id);
            vo.soulMap.set(data.soul.type, data.soul);
            if (data.to_id) {
                let toVo = this.godMap.get(data.to_id);
                toVo.soulMap.set(data.to_soul.type, data.to_soul);
            }
            this.fireEvent(mvc.GodConst.EVT.SOUL_EQUIP, data.id, data.soul.type);
            sg.uimgr.showNotice(sg.translate("镶嵌成功"), "green");
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_EQIUP_SOUL);
        }
        soulUnequip(data) {
            let vo = this.godMap.get(data.id);
            vo.soulMap.set(data.soul.type, data.soul);
            this.fireEvent(mvc.GodConst.EVT.SOUL_UNEQUIP, data.id, data.soul.type);
            sg.uimgr.showNotice(sg.translate("剥离成功"), "green");
            mgr.redotMgr.check(mvc.REDOT_ID.GOD_EQIUP_SOUL);
            this.updataBallList();
        }
        useSlot(data) {
            let vo = this.godMap.get(data.id);
            vo.useSlot = data.type;
            this.fireEvent(mvc.GodConst.EVT.USE_SLOT, data.id, data.type);
            if (!this.lastSlot) {
                sg.uimgr.showNotice(sg.translate("设置成功"), "green");
            }
            else if (data.id == this.lastSlot) {
                sg.uimgr.showNotice(sg.translate("切换成功！"), "green");
                this.fireEvent(mvc.GodConst.EVT.GOD_SET_WUXING_SKILL, data.id);
                this.lastSlot = 0;
            }
        }
        godLineup(data) {
            this.lineup.clear();
            for (let l of data.on_battle) {
                this.lineup.set(l[0], l[1]);
            }
            this.fireEvent(mvc.GodConst.EVT.GOD_LINEUP, this.lineupPos);
            this.lineupPos = 0;
            sg.uimgr.showNotice(sg.translate("上阵成功"), "green");
            sg.uimgr.closeUI("pop_godLineup");
        }
        isHaveGod(id) {
            return this.godMap.has(id);
        }
        getWuxingSkill(type1, type2) {
            if (!this._wuxingMap) {
                this._wuxingMap = new Map();
                let cfgs = sg.dbmgr.getDB("god_elementGroup");
                for (let key in cfgs) {
                    let cfg = cfgs[key];
                    this._wuxingMap.set(cfg.group[0] + "_" + cfg.group[1], cfg);
                    if (cfg.group[0] != cfg.group[1]) {
                        this._wuxingMap.set(cfg.group[1] + "_" + cfg.group[0], cfg);
                    }
                }
            }
            return this._wuxingMap.get(type1 + "_" + type2);
        }
        isLineup(id) {
            for (let v of this.lineup.values()) {
                if (v == id)
                    return true;
            }
            return false;
        }
        viewNewGod(id) {
            if (this.newGodMap[id]) {
                delete this.newGodMap[id];
                sg.varmgr.setUserVar("new_god_map", this.newGodMap);
                this.fireEvent(mvc.GodConst.EVT.NEW_GOD_CHANGE);
            }
        }
        viewAllNewGod() {
            this.newGodMap = {};
            sg.varmgr.setUserVar("new_god_map", this.newGodMap);
            this.fireEvent(mvc.GodConst.EVT.NEW_GOD_CHANGE);
        }
        isPos2Open() {
            return this.godMap.size >= 2;
        }
        updataBallList() {
            this.fireEvent(mvc.GodConst.EVT.GOD_BALL_UPDATA);
        }
        onMsgSoulMerge(data) {
            this.selectBall.set(1, null);
            this.selectBall.set(2, null);
            if (data.item.length == 1 && this.ballSandLeve > 0) {
                if (data.level > this.ballSandLeve) {
                    sg.uimgr.showUI("pop_BallForgeResult", data.item[0]);
                }
                else {
                    sg.uimgr.showUI("pop_BallForgeResultFalse", data.item[0]);
                }
            }
            else {
                sg.uimgr.showUI("pop_BallQuicklyForgeResult", data.item);
            }
            if (this.ballSandLeve <= 4) {
                let num = 0;
                let vos = mvc.bagModel.getItemsByType(mvc.BagConst.BagType.ELEMENT_BEAD);
                for (let i of vos) {
                    if (i.level == this.ballSandLeve) {
                        num++;
                    }
                }
                if (num < 2) {
                    mvc.rechargeLimitCtrl.reqRechargeTrigger(mvc.RechargeLimitConst.EventType.SOUL_BEAD);
                }
            }
            this.ballSandLeve = 0;
            this.updataBallList();
        }
        onMsgSoulRecast(data) {
            this.updataBallList();
        }
        onMsgSoulUseRecast(data) {
            this.updataBallList();
        }
        ballAttrColor(data, type = 1) {
            let level = data.level;
            let sec_attr = data.bead.sec_attr;
            if (type == 0 && data.bead.sec_attr1) {
                sec_attr = data.bead.sec_attr1;
            }
            let quality = 2;
            if (level >= 7) {
                let attrName = sg.dbmgr.get("attribute", sec_attr[0][0]).name;
                let attrUpArr = sg.dbmgr.getArray("god_beadLvAttr", { beadLv: level })[0].extraAtt2;
                let attrUp = 0;
                for (let i of attrUpArr) {
                    if (i[0] == attrName) {
                        attrUp = i[2];
                    }
                }
                let percentage = 0;
                if (attrUp) {
                    percentage = sec_attr[0][1] / attrUp * 10000;
                }
                let attrArr = sg.dbmgr.getDB("god_ramdomAttrGear");
                for (let i = 1; i <= 5; i++) {
                    if (attrArr[i].perMin <= percentage && attrArr[i].perMax >= percentage) {
                        quality = attrArr[i].gearQuality;
                    }
                }
            }
            let returnArr = [];
            returnArr.push(sg.dbmgr.get("color", quality).stringColor);
            returnArr.push(sg.dbmgr.get("color", quality).strokeColor);
            return returnArr;
        }
        updateSkinInfo(data) {
            this.skinMap.clear();
            for (let s of data.list) {
                let vo = new mvc.GodSkinVo();
                vo.init(s);
                this.skinMap.set(vo.id, vo);
            }
            let newSkins = sg.varmgr.getUserVar("new_godSkin_map");
            if (!newSkins) {
                this.newSkins = [];
            }
            else {
                this.newSkins = newSkins;
            }
        }
        skinActive(data) {
            let vo = new mvc.GodSkinVo();
            vo.init(data.fashion);
            this.skinMap.set(vo.id, vo);
            this.newSkins.push(vo.id);
            sg.varmgr.setUserVar("new_godSkin_map", this.newSkins);
            this.fireEvent(mvc.GodConst.EVT.GOD_SKIN_UPDATE, vo.id);
            sg.uimgr.showNotice(sg.translate("激活成功"), "green");
            let cfg = sg.dbmgr.get("god_godFashion", vo.id);
            let godVo = this.godMap.get(cfg.godId);
            if (!godVo.fashion) {
                mvc.godCtrl.reqSkinEquip(cfg.godId, cfg.id);
            }
        }
        skinLvUp(data) {
            let vo = this.skinMap.get(data.fashion.id);
            vo.init(data.fashion);
            this.fireEvent(mvc.GodConst.EVT.GOD_SKIN_UPDATE, vo.id);
            this.fireEvent(mvc.GodConst.EVT.GOD_SKIN_LV_UP);
        }
        equipSkin(data) {
            let godVo = this.godMap.get(data.id);
            godVo.fashion = data.fashion;
            this.fireEvent(mvc.GodConst.EVT.GOD_SKIN_EQUIP_CHANGE);
            sg.uimgr.showNotice(sg.translate("幻化成功"), "green");
        }
        unEquipSkin(data) {
            let godVo = this.godMap.get(data.id);
            godVo.fashion = 0;
            this.fireEvent(mvc.GodConst.EVT.GOD_SKIN_EQUIP_CHANGE);
            sg.uimgr.showNotice(sg.translate("卸下成功"), "green");
        }
        removeNewSkin(id) {
            let idx = this.newSkins.indexOf(id);
            if (idx == -1)
                return;
            this.newSkins.splice(idx, 1);
            sg.varmgr.setUserVar("new_godSkin_map", this.newSkins);
        }
        get godToSkinMap() {
            if (!this._godToSkinMap) {
                this._godToSkinMap = new Map();
                let cfgs = sg.dbmgr.getDB("god_godFashion");
                for (let key in cfgs) {
                    let cfg = cfgs[key];
                    if (!this._godToSkinMap.has(cfg.godId)) {
                        this._godToSkinMap.set(cfg.godId, []);
                    }
                    this._godToSkinMap.get(cfg.godId).push(cfg.id);
                }
            }
            return this._godToSkinMap;
        }
        isHaveSkin(godId) {
            return this.godToSkinMap.has(godId);
        }
        getGodSkins(godId) {
            return this.godToSkinMap.get(godId);
        }
        getSkinState(skinId) {
            let cfg = sg.dbmgr.get("god_godFashion", skinId);
            let godVo = this.godMap.get(cfg.godId);
            if (godVo && godVo.fashion == skinId)
                return mvc.GodConst.GodSkinState.EQUIP;
            let skinVo = this.skinMap.get(skinId);
            if (!skinVo) {
                if (mgr.toolsMgr.checkConsume(cfg.consume, false, false)) {
                    return mvc.GodConst.GodSkinState.CAN_ACTIVE;
                }
                else {
                    return mvc.GodConst.GodSkinState.NO_GET;
                }
            }
            return mvc.GodConst.GodSkinState.ACTIVE;
        }
        getSkinAttr(skinId, level) {
            let cfg = sg.dbmgr.get("god_godFashion", skinId);
            let addMap = {};
            for (let add of cfg.lvUpArr) {
                addMap[add[0]] = add[1];
            }
            let ret = [];
            for (let base of cfg.baseAttr) {
                let add = addMap[base[0]] || 0;
                ret.push([base[0], base[1] + (level - 1) * add]);
            }
            return ret;
        }
    }
    mvc.GodModel = GodModel;
})(mvc || (mvc = {}));

