var mvc;
(function (mvc) {
    class PopGodAtlas extends ui.view.god.pop_godAtlasUI {
        constructor() {
            super(...arguments);
            this._lastIdx = -1;
        }
        initView() {
            this._model = mvc.godModel;
        }
        initSendMsg() {
        }
        initModelEvent() {
            this.bindModelEvent(this._model, mvc.GodConst.EVT.UPDATE_ATLAS_VIEW, this._updateView);
            this.bindModelEvent(this._model, mvc.GodConst.EVT.PLAY_UP_ANI, this._playAni);
        }
        initCtrlEvent() {
            this.listNormal.vScrollBarSkin = "";
            this.listAdv.vScrollBarSkin = "";
            this.lblTotal.on(Laya.Event.CLICK, this, this._onLblTotal);
            this.tab.selectHandler = this.createHandler(this, this._onTab, undefined, false);
            this.unitRedot1.id = mvc.REDOT_ID.GOD_ATLAS_ONE;
            this.unitRedot2.id = mvc.REDOT_ID.GOD_ATLAS_TWO;
            this.unitRedot3.id = mvc.REDOT_ID.GOD_RECYCLE;
        }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            this._updateView();
            this.tab.selectedIndex = 0;
            this._lastIdx = 0;
            this._scrollTar(this.tab.selectedIndex);
        }
        onDisable() {
            super.onDisable();
            this.tab.selectedIndex = -1;
            this._lastIdx = -1;
            this.activeEffBox.removeChildByName("eff");
        }
        _updateView() {
            this.arrNormal = [];
            this.arrAdv = [];
            let cfgs = sg.dbmgr.getDB("god_contractList");
            for (let key in cfgs) {
                let cfg = cfgs[key];
                let vos = [];
                for (let item of cfg.group[0]) {
                    vos.push(item);
                }
                let isActive;
                let atlasClass;
                if (this._model.atlasMap.has(cfg.id)) {
                    isActive = true;
                    atlasClass = this._model.atlasMap.get(cfg.id).class;
                }
                else {
                    isActive = false;
                    atlasClass = 1;
                }
                let classCfg = sg.dbmgr.getArray("god_contractClassUp", { contractId: cfg.id, class: atlasClass })[0];
                let attrs = [];
                let attrCfg = mvc.PropertyModel._getCfg(classCfg.allGodAttr[0][0]);
                attrs.push({
                    lblName: attrCfg.show_name,
                    lblValue: attrCfg.is_per == 1 ? (classCfg.allGodAttr[0][1] / 100) + "%" : classCfg.allGodAttr[0][1].toString()
                });
                let arr = cfg.type == 1 ? this.arrNormal : this.arrAdv;
                arr.push({
                    id: cfg.id,
                    class: atlasClass,
                    isActive: isActive,
                    atlasName: cfg.name + StringEx.format(sg.translate("·${atlasClass}级"), {"atlasClass":atlasClass}),
                    vos: vos,
                    attrs: attrs,
                    sort: cfg.sort
                });
            }
            this.arrNormal.sort((a, b) => { return a.sort - b.sort; });
            this.arrAdv.sort((a, b) => { return a.sort - b.sort; });
            this.listNormal.array = this.arrNormal;
            this.listAdv.array = this.arrAdv;
            let child = this.tab.getChildAt(2);
            if (child)
                child.visible = false;
        }
        _onLblTotal() {
            sg.uimgr.showUI("pop_godAtlasAttr");
        }
        _onTab(idx) {
            if (idx < 0)
                return;
            this.boxNormal.visible = idx == 0;
            this.boxAdv.visible = idx == 1;
            let vo = mvc.godRecycleModel.getGodRecycleVo();
            this.boxRecycle.visible = false;
            if (idx == 2) {
                if (vo && vo.is_open == 1) {
                    this.boxRecycle.visible = true;
                    let unit = this.boxRecycle.getChildAt(0);
                    if (this.boxRecycle.numChildren == 0) {
                        unit = new mvc.UnitGodRecycle();
                        this.boxRecycle.addChild(unit);
                    }
                    if (unit)
                        unit.init("");
                }
                else {
                    sg.uimgr.showNotice(sg.translate("暂未有任意神仙达到满阶或满级"));
                    this.tab.selectedIndex = this._lastIdx;
                    return;
                }
            }
            this._scrollTar(idx);
            this._lastIdx = idx;
        }
        _scrollTar(idx) {
            let arr = [];
            if (idx == 0)
                arr = this.arrNormal;
            else
                arr = this.arrAdv;
            let scrollIdx = 0;
            for (let i = 0, len = arr.length; i < len; i++) {
                let info = arr[i];
                if (info.isActive) {
                    let nextCfg = sg.dbmgr.getArray("god_contractClassUp", { contractId: info.id, class: info.class + 1 })[0];
                    if (nextCfg) {
                        if (this._model.canUp(info.vos, nextCfg.consume)) {
                            scrollIdx = i;
                            break;
                        }
                    }
                }
                else {
                    if (this._model.canActive(info.vos)) {
                        scrollIdx = i;
                        break;
                    }
                }
            }
            if (idx == 0)
                this.listNormal.tweenTo(scrollIdx);
            else
                this.listAdv.tweenTo(scrollIdx);
        }
        _playAni(atlas_id, atlasClass) {
            if (atlasClass == 1) {
                this._showUpEff("eff_ui_shenjietiandao", this.activeEffBox);
            }
            else {
            }
        }
        _showUpEff(clipName, parent) {
            let eff = sg.Effect2D.create(clipName, true, false, true);
            eff.x = 0;
            eff.y = 0;
            eff.name = "eff";
            parent.addChild(eff);
            eff.on(Laya.Event.STOPPED, this, () => {
                parent.removeChildByName("eff");
            });
        }
    }
    mvc.PopGodAtlas = PopGodAtlas;
})(mvc || (mvc = {}));

