(function (mvc) {
    class PopGodBag extends ui.view.god.pop_godBagUI {
        initView() {
            this._model = mvc.godModel;
            this._ctrl = mvc.godCtrl;
        }
        initSendMsg() {
        }
        initModelEvent() {
            this.bindModelEvent(this._model, mvc.GodConst.EVT.GOD_COMPOSE, this._updateList);
            this.bindModelEvent(this._model, mvc.GodConst.EVT.GOD_LEVEL_UP, this._godChange);
            this.bindModelEvent(this._model, mvc.GodConst.EVT.GOD_BREAK, this._godChange);
            this.bindModelEvent(this._model, mvc.GodConst.EVT.GOD_UP_GRADE, this._godChange);
            this.bindModelEvent(this._model, mvc.GodConst.EVT.GOD_TRANS, this._godChange);
            this.bindModelEvent(this._model, mvc.GodConst.EVT.GOD_BAG_CLICK, this._onListClick);
            this.bindModelEvent(this._model, mvc.GodConst.EVT.NEW_GOD_CHANGE, this._godChange);
        }
        initCtrlEvent() {
            this.list.vScrollBarSkin = "";
        }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            this._updateList();
        }
        _godChange() {
            this.list.refresh();
        }
        _updateList() {
            let all = [];
            let cfgs = sg.dbmgr.getDB("god_god");
            for (let id in cfgs) {
                let cfg = cfgs[id];
                let canCompose = false;
                if (!this._model.isHaveGod(cfg.id)) {
                    let num = mgr.toolsMgr.getCountById(cfg.itemId);
                    let scfg = sg.dbmgr.get("god_godStarUp", 0);
                    canCompose = num >= scfg.cost;
                }
                all.push({
                    id: cfg.id,
                    cfg: cfg,
                    canCompose: canCompose,
                    vo: this._model.godMap.get(cfg.id)
                });
            }
            all.sort((a, b) => {
                if (a.canCompose != b.canCompose) {
                    return a.canCompose ? -1 : 1;
                }
                if ((!a.vo) != (!b.vo)) {
                    return a.vo != undefined ? -1 : 1;
                }
                let lineupA = this._model.isLineup(a.id);
                let lineupB = this._model.isLineup(b.id);
                if (lineupA != lineupB) {
                    return lineupA ? -1 : 1;
                }
                if (a.vo && a.vo.level != b.vo.level) {
                    return b.vo.level - a.vo.level;
                }
                if (a.cfg.quality != b.cfg.quality) {
                    return b.cfg.quality - a.cfg.quality;
                }
                if (a.vo && a.vo.grade != b.vo.grade) {
                    return b.vo.grade - a.vo.grade;
                }
                return a.id - b.id;
            });
            this._all = all;
            let idx = 0;
            let isSetIdx = false;
            let arr = [];
            let sub = [];
            for (let d of all) {
                sub.push(d);
                if (!isSetIdx) {
                    if (d.vo) {
                        let nextCfg = sg.dbmgr.get("god_godStarUp", d.vo.grade + 1);
                        if (nextCfg) {
                            let curNum = mgr.toolsMgr.getCountById(d.cfg.itemId);
                            if (curNum >= nextCfg.cost) {
                                isSetIdx = true;
                                idx = arr.length;
                            }
                        }
                    }
                    else {
                        let num = mgr.toolsMgr.getCountById(d.cfg.itemId);
                        let starCfg = sg.dbmgr.get("god_godStarUp", 0);
                        if (num >= starCfg.cost) {
                            isSetIdx = true;
                            idx = arr.length;
                        }
                    }
                }
                if (sub.length == 3) {
                    arr.push(sub);
                    sub = [];
                }
            }
            if (sub.length > 0) {
                arr.push(sub);
            }
            this.list.array = arr;
            this.list.scrollTo(idx);
        }
        onDisable() {
            this._model.viewAllNewGod();
            super.onDisable();
        }
        _onListClick(data) {
            if (data.vo) {
                let arr = [];
                let idx = 0;
                let gods = this._all;
                for (let i = 0; i < gods.length; i++) {
                    if (gods[i] == data) {
                        idx = arr.length;
                    }
                    if (gods[i].vo) {
                        arr.push(gods[i].vo);
                    }
                }
                sg.uimgr.showUI("pop_godBringUp", arr, idx);
                this._model.viewNewGod(data.vo.id);
            }
            else {
                let num = mgr.toolsMgr.getCountById(data.cfg.itemId);
                let starCfg = sg.dbmgr.get("god_godStarUp", 0);
                if (num >= starCfg.cost) {
                    mvc.godCtrl.reqGodCompose(data.id);
                }
            }
        }
    }
    mvc.PopGodBag = PopGodBag;
})(mvc || (mvc = {}));

