(function (mvc) {
    class PopGodBreak extends ui.view.god.pop_godBreakUI {
        constructor() {
            super();
            this._perAddMap = {
                hp_upper_per: 1,
                attack_per: 2,
                defense_per: 3,
                speed_per: 4,
                25: 1,
                26: 2,
                27: 3,
                28: 4,
            };
            this._model = mvc.godModel;
            this._ctrl = mvc.godCtrl;
        }
        initView(god) {
            this._god = god;
        }
        initSendMsg() {
        }
        initModelEvent() {
        }
        initCtrlEvent() {
            this.btnBreak.on(Laya.Event.CLICK, this, this._onBtnBreak);
        }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            let vo = this._god;
            let breakCfg = sg.dbmgr.get("god_break", vo.break + 1);
            let starCfg = sg.dbmgr.get("god_godStarUp", vo.grade);
            let perMap = {};
            if (starCfg.ratio) {
                for (let ratio of starCfg.ratio) {
                    let id = this._perAddMap[ratio[0]];
                    perMap[id] = ratio[1] / 10000;
                }
            }
            for (let soul of vo.soulMap.values()) {
                if (!soul.bead)
                    continue;
                let ball = mvc.bagModel.getVoById(soul.bead);
                for (let attr of ball.attr) {
                    let id = this._perAddMap[attr[0]];
                    if (perMap[id]) {
                        perMap[id] += attr[1] / 10000;
                    }
                    else {
                        perMap[id] = attr[1] / 10000;
                    }
                }
                for (let attr of ball.bead.sec_attr) {
                    let id = this._perAddMap[attr[0]];
                    if (perMap[id]) {
                        perMap[id] += attr[1] / 10000;
                    }
                    else {
                        perMap[id] = attr[1] / 10000;
                    }
                }
            }
            let arr = [];
            arr.push({
                lblPropName: sg.translate("等级上限："),
                lblCurPropValue: "Lv." + breakCfg.condition,
                lblNextPropValue: "Lv." + breakCfg.maxLv
            });
            for (let add of breakCfg.breakAttr) {
                let acfg = mvc.PropertyModel._getCfg(add[0]);
                let cur = 0;
                for (let attr of vo.attr) {
                    if (attr[0] == acfg.id) {
                        cur = attr[1];
                        break;
                    }
                }
                let per = 1 + (perMap[acfg.id] || 0);
                let next = Math.floor(cur + add[1] * per);
                arr.push({
                    lblPropName: acfg.god_show_name2 + sg.translate("："),
                    lblCurPropValue: acfg.is_per ? (cur / 100) + "%" : cur + "",
                    lblNextPropValue: acfg.is_per ? (next / 100) + "%" : next + "",
                });
            }
            this.listProp.array = arr;
            let url = mgr.toolsMgr.getIconById(breakCfg.breakConsume[0][0]);
            url = mgr.icon.getIconPath(url);
            mgr.icon.drawTexture(url, this.sprCost);
            this.lblCost.text = breakCfg.breakConsume[0][1];
            this.lblCost.color = mvc.COLOR.GREEN;
        }
        onDisable() {
            super.onDisable();
        }
        _onBtnBreak() {
            this._ctrl.reqGodBreak(this._god.id);
            this.closeSelf();
        }
    }
    mvc.PopGodBreak = PopGodBreak;
})(mvc || (mvc = {}));

