var mvc;
(function (mvc) {
    class PopGodChangeSkill extends ui.view.god.pop_wuxingChangeUI {
        constructor() {
            super();
            this._model = mvc.godModel;
            this._ctrl = mvc.godCtrl;
        }
        initView() {
        }
        initSendMsg() {
        }
        initModelEvent() {
            this.bindModelEvent(this._model, mvc.GodConst.EVT.GOD_SET_WUXING_SKILL, this._updateView);
        }
        initCtrlEvent() {
            this.list.renderHandler = this.createHandler(this, this._listRenderer, undefined, false);
            this.list.selectHandler = this.createHandler(this, this._listSelectHandle, undefined, false);
            this.list.vScrollBarSkin = "";
            this.btnSwitch.on(Laya.Event.CLICK, this, this._onBtnSwitch);
            this.btnPreview.on(Laya.Event.CLICK, this, this._onBtnSkillPre);
        }
        onAwake() {
            super.onAwake();
            this.lblSkillEmpty.text = sg.translate("无激活魂技");
        }
        onEnable() {
            super.onEnable();
            this._updateView();
        }
        _updateView() {
            let gods = [];
            let skillMap = {};
            for (let pos = 1; pos <= 2; pos++) {
                let id = this._model.lineup.get(pos);
                if (id) {
                    let vo = this._model.godMap.get(id);
                    gods.push(vo);
                }
            }
            let cur;
            if (gods.length == 2) {
                this.lblSkillEmpty.visible = false;
                this.boxSkill.visible = true;
                cur = this._model.getWuxingSkill(gods[0].getWuxing(), gods[1].getWuxing());
                if (cur) {
                    let cfgSkill = sg.dbmgr.get("skill_skill", cur.skill);
                    let skillName = cfgSkill.name;
                    this.lblCurSkill.text = StringEx.format(sg.translate("当前魂技：${skillName}"), {"skillName":skillName});
                    this.lblSkillDesc.text = cfgSkill.desc;
                    let wuxingCfg = sg.dbmgr.get("god_element", cur.group[0]);
                    this.lblWuxing1.text = wuxingCfg.name;
                    this.lblWuxing1.color = wuxingCfg.stringColor;
                    this.lblWuxing1.strokeColor = wuxingCfg.strokeColor;
                    wuxingCfg = sg.dbmgr.get("god_element", cur.group[1]);
                    this.lblWuxing2.text = wuxingCfg.name;
                    this.lblWuxing2.color = wuxingCfg.stringColor;
                    this.lblWuxing2.strokeColor = wuxingCfg.strokeColor;
                }
                else {
                    this.lblCurSkill.text = StringEx.format(sg.translate("当前魂技：无"));
                    this.boxSkill.visible = false;
                    this.lblSkillEmpty.visible = true;
                }
                for (let ele1 of gods[0].cfg.soulElement) {
                    for (let ele2 of gods[1].cfg.soulElement) {
                        let skill = this._model.getWuxingSkill(ele1[1], ele2[1]);
                        if (!skill)
                            continue;
                        let isUnlock = true;
                        let slot1 = gods[0].soulMap.get(ele1[0]);
                        if (!slot1 || !slot1.is_unlock) {
                            isUnlock = false;
                        }
                        let slot2 = gods[1].soulMap.get(ele2[0]);
                        if (!slot2 || !slot2.is_unlock) {
                            isUnlock = false;
                        }
                        if (skillMap[skill.id] && skillMap[skill.id].isUnlock == true)
                            continue;
                        skillMap[skill.id] = {
                            god1: gods[0],
                            god2: gods[1],
                            slot1: ele1,
                            slot2: ele2,
                            skill: skill,
                            isUnlock: isUnlock
                        };
                    }
                }
            }
            else {
                this.lblCurSkill.text = StringEx.format(sg.translate("当前魂技：无"));
                this.boxSkill.visible = false;
                this.lblSkillEmpty.visible = true;
            }
            let arr = [];
            let cfgs = sg.dbmgr.getDB("god_elementGroup");
            for (let key in cfgs) {
                let cfg = cfgs[key];
                if (cur && cfg.id == cur.id)
                    continue;
                let sort = 2;
                let gInfo = skillMap[cfg.id];
                if (gInfo) {
                    sort = gInfo.isUnlock ? 0 : 1;
                }
                arr.push({
                    cfg: cfg,
                    godInfo: gInfo,
                    sort: sort
                });
                arr.sort((a, b) => {
                    return a.sort - b.sort;
                });
            }
            this.list.array = arr;
            this.list.selectedIndex = -1;
        }
        onDisable() {
            super.onDisable();
        }
        _listRenderer(cell) {
            let data = cell.dataSource;
            if (!data)
                return;
            let boxMain = cell.getChildByName("boxMain");
            let lblWuxing1 = boxMain.getChildByName("lblWuxing1");
            let lblWuxing2 = boxMain.getChildByName("lblWuxing2");
            let lblDesc = boxMain.getChildByName("lblDesc");
            let cfgWuxing = sg.dbmgr.get("god_element", data.cfg.group[0]);
            lblWuxing1.text = cfgWuxing.name;
            lblWuxing1.color = cfgWuxing.stringColor;
            lblWuxing1.strokeColor = cfgWuxing.strokeColor;
            cfgWuxing = sg.dbmgr.get("god_element", data.cfg.group[1]);
            lblWuxing2.text = cfgWuxing.name;
            lblWuxing2.color = cfgWuxing.stringColor;
            lblWuxing2.strokeColor = cfgWuxing.strokeColor;
            let skillCfg = sg.dbmgr.get("skill_skill", data.cfg.skill);
            lblDesc.text = skillCfg.desc;
            boxMain.gray = !data.godInfo || !data.godInfo.isUnlock;
        }
        _listSelectHandle(idx) {
            if (idx == -1) {
                this.btnSwitch.disabled = true;
                this.lblSwitch.text = sg.translate("选择五行组合方案切换后，神仙会自动设置相应的出战五行属性");
            }
            let data = this.list.getItem(idx);
            if (!data)
                return;
            if (!data.godInfo) {
                this.btnSwitch.disabled = true;
                this.lblSwitch.text = sg.translate("当前上阵神仙无法激活本技能");
            }
            else if (!data.godInfo.isUnlock) {
                this.btnSwitch.disabled = true;
                this.lblSwitch.text = sg.translate("神仙解锁更高阶命魂后，获得新五行属性可激活本技能");
            }
            else {
                this.btnSwitch.disabled = false;
                this.lblSwitch.text = sg.translate("选择五行组合方案切换后，神仙会自动设置相应的出战五行属性");
            }
        }
        _onBtnSwitch() {
            let data = this.list.selectedItem;
            if (!data || !data.godInfo || !data.godInfo.isUnlock)
                return;
            let godInfo = data.godInfo;
            let last = 0;
            if (godInfo.god1.useSlot != godInfo.slot1[0]) {
                this._ctrl.reqUseSlot(godInfo.god1.id, godInfo.slot1[0]);
                last = godInfo.god1.id;
            }
            if (godInfo.god2.useSlot != godInfo.slot2[0]) {
                this._ctrl.reqUseSlot(godInfo.god2.id, godInfo.slot2[0]);
                last = godInfo.god2.id;
            }
            this._model.lastSlot = last;
        }
        _onBtnSkillPre() {
            sg.uimgr.showUI("pop_godSkillPre");
        }
    }
    mvc.PopGodChangeSkill = PopGodChangeSkill;
})(mvc || (mvc = {}));

