(function (mvc) {
    class PopGodEnter extends ui.view.god.pop_godEntranceUI {
        initView(data) {
            this._model = mvc.godModel;
            this._ctrl = mvc.godCtrl;
            this._data = data;
        }
        initSendMsg() {
        }
        initModelEvent() {
            this.bindModelEvent(this._model, mvc.GodConst.EVT.GOD_LINEUP, this._updateGodInfo);
            this.bindModelEvent(this._model, mvc.GodConst.EVT.GOD_LEVEL_UP, this._onGodInfoChange);
            this.bindModelEvent(this._model, mvc.GodConst.EVT.GOD_BALL_UPDATA, this._onGodInfoChange);
            this.bindModelEvent(this._model, mvc.GodConst.EVT.GOD_UP_GRADE, this._onGodInfoChange);
            this.bindModelEvent(this._model, mvc.GodConst.EVT.GOD_BREAK, this._onGodInfoChange);
            this.bindModelEvent(this._model, mvc.GodConst.EVT.GOD_TRANS, this._onGodTrans);
        }
        initCtrlEvent() {
            this.panelEff1.vScrollBarSkin = "";
            this.panelEff2.vScrollBarSkin = "";
            this.listAtlasAttr.vScrollBarSkin = "";
            this.listProp.vScrollBarSkin = "";
        }
        onAwake() {
            super.onAwake();
            this.lblPropEmpty.text = sg.translate("暂无属性加成");
            this.lblAltasEmpty.text = sg.translate("暂无属性加成");
        }
        onEnable() {
            super.onEnable();
            this._updateGodInfo();
        }
        onDisable() {
            this.unitModel1.stop();
            this.unitModel2.stop();
            super.onDisable();
        }
        _onGodInfoChange(id) {
            if (this._model.isLineup(id)) {
                this._updateGodInfo();
            }
        }
        _onGodTrans() {
            this._updateGodInfo();
        }
        _updateGodInfo() {
            let types = [0, 0];
            let attrMap = {};
            let lineup = {};
            for (let g of this._data.gods) {
                lineup[g.pos] = g;
            }
            for (let i = 1; i <= 2; i++) {
                let god = lineup[i];
                if (god) {
                    this._updateGodPos(i, god);
                    types[i - 1] = god.element;
                }
                else {
                    this._updateGodPos(i, null);
                }
            }
            let arr = mvc.PropertyModel.generateListDataGod(this._data.god_attr);
            this.listProp.array = arr;
            this.lblPropEmpty.visible = arr.length == 0;
            arr = mvc.PropertyModel.generateListData(this._data.atlas_attr);
            this.listAtlasAttr.array = arr;
            this.lblAltasEmpty.visible = arr.length == 0;
            let wuxing = this._model.getWuxingSkill(types[0], types[1]);
            if (wuxing) {
                this.lblSkill.visible = true;
                let skillCfg = sg.dbmgr.get("skill_skill", wuxing.skill);
                this.lblSkill.text = skillCfg.desc;
                this.lblSkillName.text = skillCfg.name;
            }
            else {
                this.lblSkill.visible = false;
                this.lblSkillName.text = sg.translate("未激活羁绊");
            }
        }
        _updateGodPos(pos, data) {
            let boxGod = this["boxGod" + pos];
            let imgEmpty = this["imgEmpty" + pos];
            let lblEff = this["lblEff" + pos];
            let lblWuxing = this["lblWuxing" + pos];
            let unitModel = this["unitModel" + pos];
            if (data) {
                boxGod.visible = true;
                imgEmpty.visible = false;
                let lblLv = this["lblLv" + pos];
                let lblName = this["lblName" + pos];
                let unitStar = this["unitStar" + pos];
                let cfg = sg.dbmgr.get("god_god", data.id);
                lblLv.text = "Lv." + data.level;
                lblName.text = cfg.name;
                mgr.toolsMgr.setLabelByQua(cfg.quality, lblName);
                unitModel.visible = true;
                if (data.fashion) {
                    let skinCfg = sg.dbmgr.get("god_godFashion", data.fashion);
                    unitModel.loadRole(skinCfg.avatar, "PopGodEnter", true);
                }
                else {
                    unitModel.loadRole(cfg.model, "PopGodEnter", true);
                }
                unitStar.setStar(data.star);
                let wx = data.element;
                if (wx) {
                    let cfg = sg.dbmgr.get("god_element", wx);
                    lblWuxing.text = cfg.name;
                    lblWuxing.color = cfg.stringColor;
                    lblWuxing.strokeColor = cfg.strokeColor;
                }
                else {
                    lblWuxing.text = sg.translate("无");
                    lblWuxing.color = "#ffffff";
                    lblWuxing.strokeColor = "#000000";
                }
                let skill = sg.dbmgr.get("skill_skill", data.skill);
                lblEff.text = skill.desc;
            }
            else {
                boxGod.visible = false;
                imgEmpty.visible = true;
                unitModel.stop();
                unitModel.visible = false;
                lblWuxing.text = "";
                lblEff.text = sg.translate("仙人以自身为炉鼎，沟通天地，已达天人合一之境。法则神通信手拈来，幻妙无穷，具有掌控乾坤，扭转战局之效用。");
            }
        }
    }
    mvc.PopGodEnter = PopGodEnter;
})(mvc || (mvc = {}));

