            baseProp = mvc.PropertyModel.getMixPropertysMerge(baseProp, addProp, true);
            let breakCfg = sg.dbmgr.getDB("god_break", true);
            for (let cfg of breakCfg) {
                addProp = mvc.PropertyModel.prasePropByCfg(cfg.breakAttr);
                baseProp = mvc.PropertyModel.getMixPropertysMerge(baseProp, addProp, true);
            }
            let gradeCfg = sg.dbmgr.get("god_godStarUp", this._cfg.maxGrade);
            for (let ratio of gradeCfg.ratio) {
                let cfgName = ratio[0];
                let cfgVal = ratio[1];
                for (let prop of baseProp) {
                    if (prop.name + "_per" == cfgName) {
                        prop.value *= 1 + cfgVal / 10000;
                        break;
                    }
                }
            }
