(function (mvc) {
    class PopGodLineup extends ui.view.god.pop_godLineupChooseUI {
        constructor() {
            super();
            this._model = mvc.godModel;
            this._ctrl = mvc.godCtrl;
        }
        initView(pos) {
            this._pos = pos;
        }
        initSendMsg() {
        }
        initModelEvent() {
        }
        initCtrlEvent() {
            this.btnOk.on(Laya.Event.CLICK, this, this._onBtnOk);
            this.list.vScrollBarSkin = "";
        }
        onAwake() {
            super.onAwake();
            this.LabelTitle.text = sg.translate("选择上阵神仙");
            this.lblEmpty.text = sg.translate("暂无神仙，可去请神获取");
        }
        onEnable() {
            super.onEnable();
            let arr = [];
            let lineuped = {};
            for (let v of this._model.lineup.values()) {
                lineuped[v] = true;
            }
            for (let god of this._model.godMap.values()) {
                if (!lineuped[god.id]) {
                    arr.push(god);
                }
            }
            arr.sort((a, b) => {
                if (a.level != b.level) {
                    return b.level - a.level;
                }
                if (a.cfg.quality != b.cfg.quality) {
                    return b.cfg.quality - a.cfg.quality;
                }
                if (a.grade != b.grade) {
                    return b.grade - a.grade;
                }
                return a.id - b.id;
            });
            this.list.array = arr;
            this.lblEmpty.visible = arr.length == 0;
        }
        onDisable() {
            this.list.selectedIndex = -1;
            super.onDisable();
        }
        _onBtnOk() {
            let item = this.list.selectedItem;
            if (!item)
                return;
            let lineup = [];
            for (let i = 1; i <= 2; i++) {
                if (i == this._pos) {
                    lineup.push([i, item.id]);
                }
                else {
                    let gid = this._model.lineup.get(i) || 0;
                    lineup.push([i, gid]);
                }
            }
            this._model.lineupPos = this._pos;
            this._ctrl.reqGodLineup(lineup);
        }
    }
    mvc.PopGodLineup = PopGodLineup;
})(mvc || (mvc = {}));

