(function (mvc) {
    class PopGodLottery extends ui.view.god.pop_godLotteryUI {
        initView(...args) {
            this._model = mvc.godModel;
            this._cfgs = sg.dbmgr.getDB("god_draw", true);
        }
        initModelEvent() {
            this.bindModelEvent(this._model, mvc.GodConst.EVT.UPDATE_LOTTERY_VIEW, this._updateView);
            this.bindModelEvent(this._model, mvc.GodConst.EVT.LOTTERY_PLAY_ANI, this._playAni);
            this.bindModelEvent(this._model, mvc.GodConst.EVT.LOTTERY_END, this._lotteryEnd);
        }
        initSendMsg() {
        }
        initCtrlEvent() {
            this.on(Laya.Event.CLICK, this, this._onClick);
            this.lblStonePer.on(Laya.Event.CLICK, this, this._onClickShow);
            this._tabTable = new mvc.TabTable(this.tab, undefined, this.tabChange.bind(this));
            let arr = [];
            for (let cfg of this._cfgs) {
                if (this._model.lottteryVoMap[cfg.id] && this._model.lottteryVoMap[cfg.id].status == 1) {
                    arr.push(cfg.singleDraw[0][0]);
                }
            }
            this.unitCurrency.updateData("", arr, true);
            this.redLottery1.id = mvc.REDOT_ID.GOD_LOTTERY_ONE;
            this.redLottery2.id = mvc.REDOT_ID.GOD_LOTTERY_TWO;
            this.redLottery3.id = mvc.REDOT_ID.GOD_LOTTERY_THREE;
        }
        onAwake() {
            super.onAwake();
            this.lblStonePer.text = sg.translate("请神概率");
        }
        onEnable() {
            super.onEnable();
            this._setShowArr();
            this._setItemOpen();
            this._tabTable.setTabColor();
            this.tab.selectedIndex = this._selectIdx = 0;
            this._model.playing = false;
            this._initModel(this._cfgs[this.tab.selectedIndex].imgAnimation);
            this.cboxNotAni.selected = this._model.skipAni;
        }
        onDisable() {
            super.onDisable();
            this.stopTimer(this._onTime);
        }
        closeSelf() {
            if (this._model.playing) {
                sg.uimgr.showNotice(sg.translate("正在请神中"));
                return;
            }
            super.closeSelf();
        }
        _initModel(id) {
            this.unitModel.changeShowMode(false, id);
            this.unitModel.loadedHandle = () => {
                this.unitModel.play("stand", true);
            };
            this.unitModel.setEndHandle("", (isLoop, name) => {
                if (name == "open") {
                    this.unitModel.play("stand", true);
                }
            });
            if (!this.unitModel.lableHandle) {
                this.unitModel.lableHandle = (obj) => {
                    if (obj.name == "tan") {
                        this._aniEnd();
                    }
                };
            }
            this.unitModel.loadRole(id, "PopGodLottery");
        }
        _onTabSelect(idx) {
            if (idx < 0)
                return;
            if (this._model.playing) {
                sg.uimgr.showNotice(sg.translate("正在请神中"));
                this.tab.selectedIndex = this._selectIdx;
                return;
            }
            this._selectIdx = this.tab.selectedIndex;
            this._initModel(this._cfgs[idx].imgAnimation);
            this._updateView();
            this.repeats(1000, this._onTime, true);
        }
        _updateView() {
            this._vo = this._model.lottteryVoMap[this._cfgs[this.tab.selectedIndex].id];
            if (this._vo) {
                this._itemId = this._cfgs[this.tab.selectedIndex].singleDraw[0][0];
                if (this._cfgs[this.tab.selectedIndex].type) {
                    this.timeBox.visible = true;
                    let activityVo = mvc.activityModel.openActivityVo.get(mvc.FUNC_ID.GOD_LOTTERY);
                    let openDate = sg.time.formatTimeStrT("F6", activityVo.start_time);
                    let closeDate = sg.time.formatTimeStrT("F6", activityVo.end_time);
                    this.lblOpenTime.text = `${openDate}-${closeDate}`;
                }
                else {
                    this.timeBox.visible = false;
                }
                let path = this._vo.is_big_bottom == 1 ? this._cfgs[this.tab.selectedIndex].drawImge2 : this._cfgs[this.tab.selectedIndex].drawImge;
                mgr.icon.drawTexture(mgr.icon.getIconPath(path), this.fontImg);
                this.fontClip.value = this._vo.bottom_times.toString();
                this._updateBtn();
            }
        }
        _updateBtn() {
            if (!this._vo)
                return;
            this.imgIcon1.visible = true;
            this.lblLotterNum1.visible = true;
            this.redTipsOne.visible = this.redTIpsTen.visible = false;
            this.btnLotterOne.label = sg.translate("请神1次");
            let green = "#0b7d13";
            let red = mgr.toolsMgr.getColor3("red").stringColor;
            this._cost1 = [];
            this._cost2 = [];
            this._cost1 = [[this._itemId, this._cfgs[this.tab.selectedIndex].singleDraw[0][1]]];
            this._cost2 = [[this._itemId, this._cfgs[this.tab.selectedIndex].multipleDraw[0][1]]];
            mgr.icon.drawTexture(mgr.icon.getIconPath(mgr.toolsMgr.getIconById(this._cost1[0][0])), this.imgIcon1);
            mgr.icon.drawTexture(mgr.icon.getIconPath(mgr.toolsMgr.getIconById(this._cost2[0][0])), this.imgIcon2);
            this.lblLotterNum1.text = this._cost1[0][1] + "";
            this.lblLotterNumTwo.text = this._cost2[0][1] + "";
            this.lblLotterNum1.color = mgr.toolsMgr.checkConsume(this._cost1) ? green : red;
            this.lblLotterNumTwo.color = mgr.toolsMgr.checkConsume(this._cost2) ? green : red;
            this.redTipsOne.visible = mgr.toolsMgr.checkConsume(this._cost1);
            this.redTIpsTen.visible = mgr.toolsMgr.checkConsume(this._cost2);
            if (this._cfgs[this.tab.selectedIndex].freeTimes > 0) {
                let haveFree = this._vo.lastFreeTime == 0 || sg.time.getSecondTime() - this._vo.lastFreeTime >= this._cfgs[this.tab.selectedIndex].freeTimes;
                if (haveFree) {
                    this.imgIcon1.visible = this.lblLotterNum1.visible = false;
                    this.redTipsOne.visible = true;
                    this.btnLotterOne.label = sg.translate("免费请神");
                }
            }
        }
        _onTime() {
            let curTime = sg.time.getSecondTime();
            let freeTimes = this._cfgs[this.tab.selectedIndex].freeTimes;
            if (this._cfgs[this.tab.selectedIndex].freeTimes < 0 || this._vo.lastFreeTime == 0 || curTime - this._vo.lastFreeTime >= freeTimes) {
                this.lblTime.visible = false;
                this.stopTimer(this._onTime);
            }
            else {
                this.lblTime.visible = true;
                let time = this._vo.lastFreeTime + freeTimes - curTime;
                this.lblTime.text = sg.time.formatTimeStrT("F0", time) + sg.translate("后免费");
            }
        }
        onLottery(type) {
            let curTime = sg.time.getSecondTime();
            let freeTimes = this._cfgs[this.tab.selectedIndex].freeTimes;
            let id = this._cfgs[this.tab.selectedIndex].id;
            if (this._vo && freeTimes > 0 && curTime - this._vo.lastFreeTime >= freeTimes && type == 1) {
                mvc.godCtrl.reqGodLottery(id, 1);
                return;
            }
            let cost = type == 2 ? this._cost2 : this._cost1;
            if ((cost && cost.length > 0)) {
                if (mgr.toolsMgr.checkConsume(cost, true)) {
                    mvc.godCtrl.reqGodLottery(id, type);
                }
            }
        }
        _playAni(data) {
            if (this.cboxNotAni.selected) {
                this._showReward(data);
            }
            else {
                mvc.godModel.playing = true;
                this._curLotteryData = data;
                this.unitModel.play("open", false);
            }
        }
        _aniEnd() {
            this._showReward(this._curLotteryData);
        }
        _showReward(data) {
            let spcArr = [];
            for (let reward of data.god_reward_infos) {
                if (this.cboxNotAni.selected) {
                    if (reward[1] == 2) {
                        let cfg = sg.dbmgr.get("god_god", reward[0]);
                        if (cfg.quality >= 6)
                            spcArr.push(reward);
                    }
                }
                else {
                    if (reward[1] == 2)
                        spcArr.push(reward);
                }
            }
            this._showSpcReward(spcArr, data);
        }
        _showSpcReward(spcArr, data) {
            if (spcArr.length == 0) {
                sg.uimgr.showUI("pop_godLotteryResult", data);
            }
            else {
                let handler = Laya.Handler.create(this, () => {
                    spcArr.shift();
                    this._showSpcReward(spcArr, data);
                });
                sg.uimgr.showUI("pop_godLotteryResultSpc", handler, spcArr[0]);
            }
        }
        _onClick(e) {
            if (this._model.playing) {
                sg.uimgr.showNotice(sg.translate("正在请神中"));
                return;
            }
            switch (e.target) {
                case this.btnLotterOne:
                    {
                        this.onLottery(1);
                    }
                    break;
                case this.btnLotterTen:
                    {
                        this.onLottery(2);
                    }
                    break;
                case this.cboxNotAni:
                    {
                        this._model.skipAni = this.cboxNotAni.selected;
                    }
                    break;
            }
        }
        _onClickShow() {
            sg.uimgr.showUI("pop_godLotteryShow", this._cfgs[this.tab.selectedIndex]);
        }
        _lotteryEnd() {
            if (this.tab.selectedIndex == 2)
                this.tab.selectedIndex = 1;
            this.tab.getChildAt(2).visible = mvc.activityModel.openActivityVo.has(mvc.FUNC_ID.GOD_LOTTERY);
        }
        tabChange(index, lastIndex) {
            if (this._model.playing) {
                sg.uimgr.showNotice(sg.translate("正在请神中"));
                this.tab.selectedIndex = this._selectIdx;
                return;
            }
            switch (index) {
                case 0:
                case 1:
                case 2:
                    {
                        this.boxLottery.visible = true;
                        this.boxDecompose.visible = false;
                        this._selectIdx = this.tab.selectedIndex;
                        this._initModel(this._cfgs[index].imgAnimation);
                        this._updateView();
                        this.repeats(1000, this._onTime, true);
                    }
                    break;
                case 3:
                    {
                    }
                    break;
            }
        }
        _setShowArr() {
            let arr = [];
            if (this._model.lottteryVoMap[this._cfgs[0].id].status == 1)
                arr.push(0);
            if (this._model.lottteryVoMap[this._cfgs[1].id].status == 1)
                arr.push(1);
            if (mvc.activityModel.openActivityVo.has(mvc.FUNC_ID.GOD_LOTTERY))
                arr.push(2);
            let vo = mvc.godRecycleModel.getGodRecycleVo();
            this._tabTable.resetPos(arr);
        }
        _setItemOpen() {
        }
    }
    mvc.PopGodLottery = PopGodLottery;
})(mvc || (mvc = {}));

