var mvc;
(function (mvc) {
    class PopGodLotteryShow extends ui.view.god.pop_drawShowUI {
        initView(cfg) {
            this._cfg = cfg;
        }
        initModelEvent() {
        }
        initCtrlEvent() {
            this.listLottery.vScrollBarSkin = "";
            this.listLottery.renderHandler = this.createHandler(this, this._renderList, null, false);
            this.listLottery.mouseHandler = this.createHandler(this, this._mouseList, null, false);
        }
        onEnable() {
            super.onEnable();
            this.lblName.text = this._cfg.drawName;
            let arr = sg.dbmgr.getArray("god_drawReward", { drawType: this._cfg.id, poolType: 1 });
            arr.sort((a, b) => {
                let typeA = a.rewardType;
                let typeB = b.rewardType;
                if (typeA != typeB) {
                    return typeB - typeA;
                }
                else {
                    if (typeA == 2) {
                        let quaA = sg.dbmgr.get("god_god", a.rewardCollection).quality;
                        let quaB = sg.dbmgr.get("god_god", b.rewardCollection).quality;
                        return quaB - quaA;
                    }
                    else {
                        let cfgA = sg.dbmgr.get("vitem", a.rewardCollection);
                        let cfgB = sg.dbmgr.get("vitem", b.rewardCollection);
                        if (cfgA.mainclass == cfgB.mainclass) {
                            return cfgB.quality - cfgA.quality;
                        }
                        else {
                            return cfgB.mainclass - cfgA.mainclass;
                        }
                    }
                }
                return 1;
            });
            this.listLottery.array = arr;
        }
        _renderList(cell, idx) {
            let data = cell.dataSource;
            if (!data)
                return;
            let item = cell.getChildByName("item");
            let lblProbability = cell.getChildByName("lblProbability");
            let godBox = cell.getChildByName("godBox");
            let rate = (data.weightShow / 100).toFixed(2);
            lblProbability.text = `${rate}%`;
            item.visible = godBox.visible = false;
            if (data.rewardType == 1) {
                item.visible = true;
                let itemVo = new mvc.ItemVo();
                itemVo.initData(data.rewardCollection, data.rewardNum);
                item.initView(itemVo);
            }
            else {
                godBox.visible = true;
                let icon = godBox.getChildByName("icon");
                let num = godBox.getChildByName("num");
                let cfg = sg.dbmgr.get("god_god", data.rewardCollection);
                mgr.icon.drawTexture(mgr.icon.getIconPath(cfg.icon), icon);
                num.text = data.rewardNum.toString();
            }
        }
        _mouseList(evt, idx) {
            if (evt.type != Laya.Event.CLICK)
                return;
            let data = this.listLottery.getItem(idx);
            if (!data)
                return;
            if (data.rewardType == 2) {
                if (!mvc.godModel.isHaveGod(data.rewardCollection)) {
                    sg.uimgr.showNotice(sg.translate("神仙尚未收集"));
                    return;
                }
                else {
                    let cfg = sg.dbmgr.get("god_god", data.rewardCollection);
                    sg.uimgr.showUI("pop_godInfo", cfg);
                }
            }
        }
    }
    mvc.PopGodLotteryShow = PopGodLotteryShow;
})(mvc || (mvc = {}));

var mvc;
(function (mvc) {
    class PopGodMain extends ui.view.god.pop_godArrayUI {
        initView() {
            this._model = mvc.godModel;
            this._ctrl = mvc.godCtrl;
        }
        initSendMsg() {
        }
        initModelEvent() {
            this.bindModelEvent(this._model, mvc.GodConst.EVT.GOD_LINEUP, this._updateLineup);
            this.bindModelEvent(this._model, mvc.GodConst.EVT.GOD_LEVEL_UP, this._onGodInfoChange);
            this.bindModelEvent(this._model, mvc.GodConst.EVT.GOD_BALL_UPDATA, this._onBallUpdate);
            this.bindModelEvent(this._model, mvc.GodConst.EVT.GOD_UP_GRADE, this._onGodInfoChange);
            this.bindModelEvent(this._model, mvc.GodConst.EVT.GOD_BREAK, this._onGodInfoChange);
            this.bindModelEvent(this._model, mvc.GodConst.EVT.GOD_TRANS, this._onGodTrans);
            this.bindModelEvent(this._model, mvc.GodConst.EVT.USE_SLOT, this._onGodInfoChange);
            this.bindModelEvent(this._model, mvc.GodConst.EVT.SOUL_EQUIP, this._onGodInfoChange);
            this.bindModelEvent(this._model, mvc.GodConst.EVT.SOUL_UNEQUIP, this._onGodInfoChange);
            this.bindModelEvent(this._model, mvc.GodConst.EVT.GOD_SKIN_EQUIP_CHANGE, this._updateLineup);
            this.bindModelEvent(this._model, mvc.GodConst.EVT.SOUL_UNLOCK, this._onSoulUnlock);
            this.bindModelEvent(this._model, mvc.GodConst.EVT.GOD_COMPOSE, this._onGodCompose);
        }
        initCtrlEvent() {
            this.btnAtlas.on(Laya.Event.CLICK, this, this._onBtnAtlas);
            this.btnDraw.on(Laya.Event.CLICK, this, this._onBtnDraw);
            this.btnBag.on(Laya.Event.CLICK, this, this._onBtnBag);
            this.btnLineup1.on(Laya.Event.CLICK, this, this._onBtnLineup, [1]);
            this.btnLineup2.on(Laya.Event.CLICK, this, this._onBtnLineup, [2]);
            this.btnChange1.on(Laya.Event.CLICK, this, this._onBtnLineup, [1]);
            this.btnChange2.on(Laya.Event.CLICK, this, this._onBtnLineup, [2]);
            this.btnUp1.on(Laya.Event.CLICK, this, this._onBtnUp, [1]);
            this.btnUp2.on(Laya.Event.CLICK, this, this._onBtnUp, [2]);
            this.btnAttrOverview.on(Laya.Event.CLICK, this, this._onLblAttr);
            this.redTipsLottery.id = mvc.REDOT_ID.GOD_LOTTERY;
            this.redTipsAtlas.id = mvc.REDOT_ID.GOD_ATLAS;
            this.panelSkill1.vScrollBarSkin = "";
            this.panelSkill2.vScrollBarSkin = "";
            this.listProp1.vScrollBarSkin = "";
            this.listProp2.vScrollBarSkin = "";
            this.boxWuxingSkill.on(Laya.Event.CLICK, this, this._onBoxSkill);
            this.unitRedBag.id = mvc.REDOT_ID.GOD_BAG;
        }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            this._updateLineup();
            this.effWuxing.ani1.play(0, true);
        }
        onDisable() {
            this.effWuxing.ani1.stop();
            this.unitModel1.stop();
            this.unitModel2.stop();
            super.onDisable();
        }
        _onGodInfoChange(id) {
            if (this._model.isLineup(id)) {
                this._updateLineup();
            }
        }
        _onBallUpdate() {
            this._updateLineup();
        }
        _onGodTrans() {
            this._updateLineup();
        }
        _onGodCompose() {
            for (let i = 1; i <= 2; i++) {
                if (!this._model.lineup.get(i)) {
                    this._updateGodPos(i, null);
                }
            }
        }
        _onSoulUnlock(id, type) {
            for (let pos = 1; pos <= 2; pos++) {
                let lid = this._model.lineup.get(pos);
                if (lid && lid == id) {
                    let vo = this._model.godMap.get(id);
                    if (!vo || vo.id != id)
                        return;
                    let listSoul = this["listSoul" + pos];
                    for (let i = 0; i < listSoul.length; i++) {
                        let item = listSoul.getItem(i);
                        if (item.type == type) {
                            let cell = listSoul.getCell(i);
                            if (!cell)
                                return;
                            cell.clipEff.visible = true;
                            cell.clipEff.play(0, cell.clipEff.total - 1);
                        }
                    }
                    this._updateGodPos(pos, vo);
                }
            }
        }
        _updateLineup(pos) {
            for (let i = 1; i <= 2; i++) {
                let id = this._model.lineup.get(i);
                if (id) {
                    let vo = this._model.godMap.get(id);
                    this._updateGodPos(i, vo);
                }
                else {
                    this._updateGodPos(i, null);
                }
            }
            this._updateSkill();
            if (this["ani" + pos]) {
                this["ani" + pos].play(0, false);
            }
        }
        _updateGodPos(pos, data) {
            if (pos == 2) {
                if (!this._model.isPos2Open()) {
                    this.boxEmpty2.visible = false;
                    this.boxGod2.visible = false;
                    this.boxLock2.visible = true;
                    return;
                }
                else {
                    this.boxLock2.visible = false;
                }
            }
            let boxGod = this["boxGod" + pos];
            let boxEmpty = this["boxEmpty" + pos];
            let unitModel = this["unitModel" + pos];
            let clipQua = this["clipQua" + pos];
            let lblQua = this["lblQua" + pos];
            let lblName = this["lblName" + pos];
            let lblLv = this["lblLv" + pos];
            let unitStar = this["unitStar" + pos];
            let listProp = this["listProp" + pos];
            let boxSkill = this["boxSkill" + pos];
            let lblSkillLv = this["lblSkillLv" + pos];
            let lblSkillName = this["lblSkillName" + pos];
            let lblSkillDesc = this["lblSkillDesc" + pos];
            let lblWuxing = this["lblWuxing" + pos];
            let imgRedLineup = this["imgRedLineup" + pos];
            let imgRedUp = this["imgRedUp" + pos];
            let listSoul = this["listSoul" + pos];
            let btnUp = this["btnUp" + pos];
            let btnChange = this["btnChange" + pos];
            let btnLineup = this["btnLineup" + pos];
            if (data) {
                boxGod.visible = true;
                boxEmpty.visible = false;
                btnUp.visible = true;
                btnChange.visible = true;
                btnLineup.visible = false;
                unitStar.visible = true;
                unitStar.setStar(data.grade);
                clipQua.visible = true;
                clipQua.index = data.cfg.quality - 2;
                let colorCfg = sg.dbmgr.get("color", data.cfg.quality);
                lblQua.text = colorCfg.godQualityName;
                mgr.toolsMgr.setLabelByQua(data.cfg.quality, lblQua);
                unitModel.visible = true;
                unitModel.loadRole(data.model.toString(), "PopGodMain", true);
                lblLv.text = "Lv." + data.level;
                lblName.text = data.cfg.name;
                mgr.toolsMgr.setLabelByQua(data.cfg.quality, lblName);
                listProp.array = mvc.PropertyModel.generateListDataGod(data.attr);
                boxSkill.visible = true;
                let skill = data.skillCfg;
                lblSkillLv.text = "Lv." + skill.level;
                lblSkillName.text = data.skillName;
                lblSkillDesc.text = skill.desc;
                let wx = data.getWuxing();
                if (wx) {
                    let cfg = sg.dbmgr.get("god_element", wx);
                    lblWuxing.text = cfg.name;
                    lblWuxing.color = cfg.stringColor;
                    lblWuxing.strokeColor = cfg.strokeColor;
                }
                else {
                    lblWuxing.text = sg.translate("无");
                    lblWuxing.color = "#ffffff";
                    lblWuxing.strokeColor = "#000000";
                }
                imgRedUp.visible = data.isShowRedLvUp() || data.isShowRedSoul() || data.canStarUp();
                listSoul.array = data.getGodSoulVos();
            }
            else {
                let haveGod = false;
                for (let vo of this._model.godMap.values()) {
                    if (!this._model.isLineup(vo.id)) {
                        haveGod = true;
                        break;
                    }
                }
                imgRedLineup.visible = haveGod;
                boxGod.visible = false;
                boxEmpty.visible = true;
                unitModel.stop();
            }
        }
        _updateSkill() {
            let types = [0, 0];
            for (let i = 1; i <= 2; i++) {
                let id = this._model.lineup.get(i);
                if (id) {
                    let vo = this._model.godMap.get(id);
                    types[i - 1] = vo.getWuxing();
                }
            }
            let wuxing = this._model.getWuxingSkill(types[0], types[1]);
            if (wuxing) {
                this.boxWuxingSkill.gray = false;
                let skillCfg = sg.dbmgr.get("skill_skill", wuxing.skill);
                this.lblWuxingSkill.text = skillCfg.name;
            }
            else {
                this.lblWuxingSkill.text = sg.translate("魂技未激活");
                this.boxWuxingSkill.gray = true;
            }
        }
        _onBtnLineup(pos) {
            if (pos == 2) {
                if (!this._model.isPos2Open()) {
                    return;
                }
            }
            sg.uimgr.showUI("pop_godLineup", pos);
        }
        _onBtnUp(pos) {
            let id = this._model.lineup.get(pos);
            if (!id)
                return;
            let vo = this._model.godMap.get(id);
            sg.uimgr.showUI("pop_godBringUp", [vo], 0);
        }
        _onBtnAtlas() {
            sg.uimgr.showUI("pop_godAtlas");
        }
        _onBtnDraw() {
            sg.uimgr.showUI("pop_godLottery");
        }
        _onBtnBag() {
            sg.uimgr.showUI("pop_godBag");
        }
        _onLblAttr() {
            sg.uimgr.showUI("pop_godAttrOverview");
        }
        _onBoxSkill() {
            sg.uimgr.showUI("pop_godChangeSkill");
        }
    }
    mvc.PopGodMain = PopGodMain;
})(mvc || (mvc = {}));

