                this.progNum.value = num / starCfg.cost;
                this.boxCompose.visible = num >= starCfg.cost;
                this.lblClipName.text = data.cfg.name;
                mgr.toolsMgr.setLabelByQua(data.cfg.quality, this.lblClipName);
