(function (mvc) {
    class UnitGodBallBag2 extends ui.view.god.unit_godBallBag2UI {
        initView() {
            this._model = mvc.godModel;
            this._ctrl = mvc.godCtrl;
        }
        initSendMsg() {
        }
        initModelEvent() {
            this.bindModelEvent(this._model, mvc.GodConst.EVT.GOD_BALL_UPDATA, this._update);
        }
        initCtrlEvent() {
            this.listBg.vScrollBarSkin = "";
            this.list.vScrollBarSkin = "";
            this.list.scrollBar.on(Laya.Event.CHANGE, this, this._onListScroll);
            this.list.renderHandler = this.createHandler(this, this._listRenderer, undefined, false);
            this.list.mouseHandler = this.createHandler(this, this._updateArtifact, undefined, false);
        }
        updateData(types, ...args) { }
        updateWhenNetReConn() { }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            this._update();
        }
        onDisable() {
            super.onDisable();
        }
        onClosed() {
            super.onClosed();
        }
        _update() {
            let vos = mvc.bagModel.getItemsByType(mvc.BagConst.BagType.ELEMENT_BEAD);
            vos.sort((a, b) => {
                let acfg = a.getCfg();
                let bcfg = b.getCfg();
                if (acfg.quality != bcfg.quality) {
                    return bcfg.quality - acfg.quality;
                }
                return a.id - b.id;
            });
            this.list.array = vos;
            if (vos.length > 0) {
                if (this.list.selectedIndex <= 0) {
                    this.list.selectedIndex = 0;
                }
                else {
                    let idx = 0;
                    for (let i = 0; i < vos.length; i++) {
                        if (vos[i].bagId == this._lastSelect) {
                            idx = i;
                            break;
                        }
                    }
                    this.list.selectedIndex = idx;
                }
            }
            else {
                this.list.selectedIndex = -1;
            }
            this.lblEmpty.visible = vos.length == 0;
            let len = Math.max(0, Math.ceil(vos.length / 5) * 5);
            let arr = [];
            for (let i = 0; i < len; i++) {
                arr.push(null);
            }
            this.listBg.array = arr;
        }
        _listRenderer(cell) {
            let data = cell.dataSource;
            let cfg = data.getCfg();
            if (!data)
                return;
            let item = cell.getChildByName("item");
            let imgWear = cell.getChildByName("imgWear");
            let imgSelect = cell.getChildByName("imgSelect");
            item.initView(data, false);
            item.changeClip("ui/common/Clip/Clip_pzdb02.png", cfg.quality - 1, 1, 10);
            let level = cfg.level;
            if (level >= 0) {
                item.lblNum.text = "Lv." + level;
            }
            imgSelect.visible = false;
            imgWear.visible = false;
            if (this._lastSelect == data.bagId) {
                imgSelect.visible = true;
            }
            if (data.isLock) {
                imgWear.visible = true;
            }
            let lblTake = cell.getChildByName("lblTake");
            lblTake.visible = false;
            if (data.bead.god_id) {
                let name = sg.dbmgr.get("god_god", data.bead.god_id).name;
                lblTake.text = name;
                lblTake.visible = true;
            }
        }
        _onListScroll() {
            this.listBg.scrollBar.value = this.list.scrollBar.value;
        }
        _updateArtifact(e, idx) {
            if (e.type != Laya.Event.CLICK || typeof idx !== "number")
                return;
            let selectItem = this.list.getItem(idx);
            if (!selectItem) {
                return;
            }
            this._lastSelect = selectItem.bagId;
            this.list.refresh();
            sg.uimgr.showUI("pop_ballTips", selectItem);
        }
    }
    mvc.UnitGodBallBag2 = UnitGodBallBag2;
})(mvc || (mvc = {}));

