(function (mvc) {
    class UnitGodBallRebuild2 extends ui.view.god.unit_godBallBagRebuild2UI {
        constructor() {
            super(...arguments);
            this._viewClick = false;
            this._onView = false;
        }
        initView() {
            this._model = mvc.godModel;
            this._ctrl = mvc.godCtrl;
            this._arrData = [];
            this._temPo = new Laya.Point(0, 0);
            this._select = new Map();
            this._select.set(1, null);
            this._select.set(2, null);
            this._select.set(3, null);
            this._curShow = 0;
            this._updateView();
            this.renderSymbolBox(null);
        }
        initSendMsg() {
        }
        initModelEvent() {
            this.bindModelEvent(this._model, mvc.GodConst.EVT.GOD_BALL_UPDATA, this._fireEvent);
        }
        initCtrlEvent() {
            this.on(Laya.Event.CLICK, this, this._onClick);
            this.list.vScrollBarSkin = "";
            this.list.renderHandler = this.createHandler(this, this._listRenderer, undefined, false);
        }
        updateData(types, ...args) { }
        updateWhenNetReConn() { }
        onAwake() {
            super.onAwake();
            this.on(Laya.UIEvent.MOUSE_UP, this, this.onMouseUp);
            this.unitEff.ani1.on(Laya.Event.COMPLETE, this, this.playEff);
        }
        onEnable() {
            super.onEnable();
        }
        onDisable() {
            super.onDisable();
            this._onView = false;
            this._viewClick = false;
        }
        onClosed() {
            super.onClosed();
            this._select.clear();
        }
        _updateView() {
            this._arrData = [];
            let vos = mvc.bagModel.getItemsByType(mvc.BagConst.BagType.ELEMENT_BEAD);
            for (let i of vos) {
                if (i.isLock == 0 && i.bead.god_id == 0) {
                    this._arrData.push(i);
                }
            }
            this._arrData.sort((a, b) => {
                let acfg = a.getCfg();
                let bcfg = b.getCfg();
                if (acfg.quality != bcfg.quality) {
                    return bcfg.quality - acfg.quality;
                }
                return a.id - b.id;
            });
            this.boxNull.visible = false;
            this.list.visible = true;
            if (this._arrData.length) {
                this.list.array = this._arrData;
            }
            else {
                this.list.visible = false;
                this.boxNull.visible = true;
            }
            let level = 0;
            let btn = true;
            for (let [key, value] of this._select) {
                if (value) {
                    this["unitItem" + key].visible = true;
                    this["unitItem" + key].initView(value);
                    this["unitItem" + key].changeClip("ui/common/Clip/Clip_pzdb02.png", value.getCfg().quality - 1, 1, 10);
                    this["unitItem" + key].lblNum.text = "Lv." + value.level;
                }
                else {
                    this["unitItem" + key].visible = false;
                    btn = false;
                }
                if (level == 0) {
                    level = value ? value.level : 0;
                }
            }
            this.btnCompose.mouseEnabled = btn;
            this.btnCompose.gray = !btn;
            if (level) {
                this.lblLvRst.text = "lv." + (level + 1);
                let probability = sg.dbmgr.get("god_beadForge", level + 1).probability / 100;
                this.lblComPer.text = sg.translate("合成成功率：") + probability + "%";
                this.lblLvRst.visible = true;
                this.lblComPer.visible = true;
            }
            else {
                this.lblLvRst.visible = false;
                this.lblComPer.visible = false;
            }
        }
        _fireEvent() {
            this._select.set(1, null);
            this._select.set(2, null);
            this._select.set(3, null);
            this._updateView();
        }
        renderSymbolBox(data, x = 0, y = 0) {
            if (data) {
                this.boxSymbolProp.visible = true;
                x = Math.min(x, this.width - this.boxSymbolProp.width + 20);
                y = Math.min(y, this.boxSymbolProp.parent["height"]);
                this.boxSymbolProp.pos(x, y - this.boxSymbolProp.height - 20);
                this.unitSymbolTip.initView(data, false);
            }
            else {
                this.boxSymbolProp.visible = false;
            }
        }
        onMouseUp(event) {
            if (this._mouseDownTar) {
                this._mouseDownTar = null;
                this._temPo.reset();
                this.stopTimer(this.onMousePress);
                if (this._viewClick) {
                    this._viewClick = false;
                }
                else {
                    this._onView = false;
                    this.renderSymbolBox(null);
                }
            }
            else {
                this.renderSymbolBox(null);
                this._onView = false;
            }
        }
        onMouseDown(data) {
            let target = data.getBoxItemVo();
            this._mouseDownTar = target;
            this.after(800, this.onMousePress);
            this._temPo.setTo(Laya.stage.mouseX, Laya.stage.mouseY);
        }
        onMousePress() {
            let parent = this.list.parent;
            parent.globalToLocal(this._temPo, false);
            this.renderSymbolBox(this._mouseDownTar, this._temPo.x, this._temPo.y);
            this._viewClick = true;
            this._onView = true;
        }
        _listRenderer(cell) {
            let data = cell.dataSource;
            let cfg = data.getCfg();
            if (!data)
                return;
            let item = cell.getChildByName("item");
            let imgWear = cell.getChildByName("imgWear");
            let imgSelect = cell.getChildByName("imgSelect");
            item.initView(data, false);
            item.changeClip("ui/common/Clip/Clip_pzdb02.png", cfg.quality - 1, 1, 10);
            item.on(Laya.Event.CLICK, this, this._updateArtifact, [item]);
            item.on(Laya.UIEvent.MOUSE_DOWN, this, this.onMouseDown, [item]);
            let level = cfg.level;
            if (level >= 0) {
                item.lblNum.text = "Lv." + level;
            }
            imgSelect.visible = false;
            imgWear.visible = false;
            for (let [key, value] of this._select) {
                if (value && value.bagId == data.bagId) {
                    imgSelect.visible = true;
                }
            }
            if (data.isLock) {
                imgWear.visible = true;
            }
            let lblTake = cell.getChildByName("lblTake");
            lblTake.visible = false;
            if (data.bead.god_id) {
                let name = sg.dbmgr.get("god_god", data.bead.god_id).name;
                lblTake.text = name;
                lblTake.visible = true;
            }
        }
        _updateArtifact(data) {
            if (this._onView) {
                return;
            }
            let selectItem = data.getBoxItemVo();
            if (!selectItem) {
                return;
            }
            if (selectItem.level == 10) {
                sg.uimgr.showNotice(sg.translate("魂珠已满级"));
                return;
            }
            if (selectItem.isLock) {
                sg.uimgr.showNotice(sg.translate("魂珠已锁定，无法融合"));
                return;
            }
            if (selectItem.bead.god_id) {
                sg.uimgr.showNotice(sg.translate("魂珠已镶嵌，无法融合"));
                return;
            }
            let handle = false;
            for (let [key, value] of this._select) {
                if (value && value.bagId == selectItem.bagId) {
                    this._select.set(key, null);
                    handle = true;
                }
            }
            if (!handle) {
                let level = 0;
                for (let [key, value] of this._select) {
                    if (level == 0) {
                        level = value ? value.level : 0;
                    }
                }
                if (level == 0 || level == selectItem.level) {
                    for (let [key, value] of this._select) {
                        if (!handle && !value) {
                            this._select.set(key, selectItem);
                            handle = true;
                        }
                    }
                }
                else {
                    sg.uimgr.showNotice(sg.translate("请选择同等级魂珠"));
                    handle = true;
                }
            }
            if (!handle) {
                sg.uimgr.showNotice(sg.translate("已选满"));
            }
            this._updateView();
        }
        _onClick(e) {
            if (this._onView) {
                return;
            }
            switch (e.target) {
                case this.btnCompose:
                    {
                        if (this._curShow + mgr.toolsMgr.getGlobalVoById("button_currency_cd", 1) <= sg.time.getSecondTime()) {
                            this._curShow = sg.time.getSecondTime();
                            this.unitEff.visible = true;
                            this.unitEff.ani1.play(0, false);
                        }
                        else {
                            sg.uimgr.showNotice(sg.translate("操作太快了，请稍后再尝试"));
                        }
                    }
                    break;
                case this.btnOneKeyCom:
                    {
                        sg.uimgr.showUI("pop_godBallQuick");
                    }
                    break;
            }
        }
        playEff() {
            let arr = [];
            for (let [key, value] of this._select) {
                if (value) {
                    arr.push(value.bagId);
                }
                else {
                    return;
                }
            }
            mvc.godModel.ballSandLeve = this._select.get(1).level;
            mvc.godCtrl.reqSoulMerge(this._select.get(1).level + 1, arr);
            this._select.set(1, null);
            this._select.set(2, null);
            this._select.set(3, null);
            this.unitEff.visible = false;
        }
    }
    mvc.UnitGodBallRebuild2 = UnitGodBallRebuild2;
})(mvc || (mvc = {}));

