            if (!this._lock[0] && !this._lock[1]) {
                use = this._use.normalCost[0];
            }
            else {
                use = this._use.lockCost[0];
            }
            mgr.icon.drawTexture(mgr.icon.getIconPath(mgr.toolsMgr.getIconById(use[0])), this.imgCostOne);
            this.lblCostOne.text = use[1] + "";
            if (mgr.toolsMgr.checkConsume([use], false)) {
                this.lblCostOne.color = "#0b7d13";
            }
            else {
                this.lblCostOne.color = "#ea3e09";
            }
