(function (mvc) {
    class UnitGodBallShopItem extends ui.view.god.unit_ballShopItemUI {
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            this.btnBuy.on(Laya.Event.CLICK, this, this._onBtnBuy);
        }
        onDisable() {
            super.onDisable();
        }
        get dataSource() {
            return super.dataSource;
        }
        set dataSource(data) {
            super.dataSource = data;
            if (!data)
                return;
            this.clipQua.index = data.quality - 1;
            let url = mgr.icon.getIconPath(data.icon);
            mgr.icon.drawTexture(url, this.imgIcon);
            this.lblName.text = data.shopName;
            url = mgr.toolsMgr.getIconById(data.cost[0][0]);
            url = mgr.icon.getIconPath(url);
            mgr.icon.drawTexture(url, this.imgCost);
            this.lblCost.text = data.cost[0][1];
            this.lblCost.color = mgr.toolsMgr.checkConsume(data.cost, false) ? mvc.COLOR.GREEN : mvc.COLOR.RED;
        }
        _onBtnBuy() {
            let data = this.dataSource;
            if (!data)
                return;
            if (!mgr.toolsMgr.checkConsume(data.cost, true)) {
                return;
            }
            let fun = (id, num) => {
                if (data.cost[0] == mvc.MainConst.ITEM_ID.GOLD) {
                    mvc.mainModel.consumeJade(data.cost, num, () => {
                        mvc.godCtrl.reqBuyBall(id, num);
                    });
                }
                else {
                    mvc.godCtrl.reqBuyBall(id, num);
                }
            };
            sg.uimgr.showUI("pop_buyTips", data.id, { name: data.shopName, quality: data.quality, icon: data.icon }, data.cost[0], false, fun, this);
        }
    }
    mvc.UnitGodBallShopItem = UnitGodBallShopItem;
})(mvc || (mvc = {}));

