var mvc;
(function (mvc) {
    class UnitGodItem extends ui.view.god.unit_godInheritItemUI {
        constructor() {
            super(...arguments);
            this._canDrop = false;
        }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
        }
        onDisable() {
            this.off(Laya.Event.MOUSE_MOVE, this, this._dropMove);
            this.off(Laya.Event.MOUSE_UP, this, this._dropEnd);
            this.off(Laya.Event.MOUSE_OUT, this, this._dropEnd);
            this._canDrop = false;
            super.onDisable();
        }
        get dataSource() {
            return super.dataSource;
        }
        set dataSource(data) {
            super.dataSource = data;
            if (!data)
                return;
            this.off(Laya.Event.MOUSE_MOVE, this, this._dropMove);
            this.off(Laya.Event.MOUSE_UP, this, this._dropEnd);
            this.off(Laya.Event.MOUSE_OUT, this, this._dropEnd);
            let url = mgr.icon.getIconPath(data.cfg.icon);
            mgr.icon.drawTexture(url, this.imgIcon);
            this.unitStar.setStar(data.grade);
            this.lblLv.text = "LV." + data.level;
            this.lblName.text = data.cfg.name;
            mgr.toolsMgr.setLabelByQua(data.cfg.quality, this.lblName);
            this.imgLineup.visible = mvc.godModel.isLineup(data.id);
            let wx = data.getWuxing();
            if (wx) {
                let cfg = sg.dbmgr.get("god_element", wx);
                this.lblWuxing.text = cfg.name;
                this.lblWuxing.color = cfg.stringColor;
                this.lblWuxing.strokeColor = cfg.strokeColor;
            }
            else {
                this.lblWuxing.text = sg.translate("无");
                this.lblWuxing.color = "#ffffff";
                this.lblWuxing.strokeColor = "#000000";
            }
        }
        setDrop() {
            if (this._canDrop)
                return;
            this._canDrop = true;
            this.on(Laya.Event.MOUSE_DOWN, this, this._startDrop);
        }
        _startDrop(evt) {
            if (!this.dataSource)
                return;
            this._startX = this.x;
            this._startY = this.y;
            this._lastX = evt.stageX;
            this._lastY = evt.stageY;
            this.zOrder = 1;
            this.on(Laya.Event.MOUSE_MOVE, this, this._dropMove);
            this.on(Laya.Event.MOUSE_UP, this, this._dropEnd);
            this.on(Laya.Event.MOUSE_OUT, this, this._dropEnd);
        }
        _dropMove(evt) {
            this.x += evt.stageX - this._lastX;
            this.y += evt.stageY - this._lastY;
            this._lastX = evt.stageX;
            this._lastY = evt.stageY;
        }
        _dropEnd(evt) {
            let pos = Laya.Point.TEMP;
            pos.setTo(this.width / 2, this.height / 2);
            this.localToGlobal(pos);
            this.x = this._startX;
            this.y = this._startY;
            this.zOrder = 0;
            this.off(Laya.Event.MOUSE_MOVE, this, this._dropMove);
            this.off(Laya.Event.MOUSE_UP, this, this._dropEnd);
            this.off(Laya.Event.MOUSE_OUT, this, this._dropEnd);
            mvc.godModel.fireEvent(mvc.GodConst.EVT.DROP_END, pos, this.dataSource);
        }
    }
    mvc.UnitGodItem = UnitGodItem;
})(mvc || (mvc = {}));

