(function (mvc) {
    class UnitGodSoul extends ui.view.god.unit_godSoulUI {
        constructor() {
            super();
            this._imgMap = {
                101: "ui_langs/cn/ui/god/clip_soul_name1.png",
                201: "ui_langs/cn/ui/god/clip_soul_name2.png",
                301: "ui_langs/cn/ui/god/clip_soul_name3.png",
            };
            this._model = mvc.godModel;
            this._ctrl = mvc.godCtrl;
        }
        initView(god) {
            this._god = god;
        }
        initSendMsg() {
        }
        initModelEvent() {
            this.bindModelEvent(this._model, mvc.GodConst.EVT.SOUL_UNLOCK, this._onUnlock);
            this.bindModelEvent(this._model, mvc.GodConst.EVT.SOUL_EQUIP, this._soulChange);
            this.bindModelEvent(this._model, mvc.GodConst.EVT.SOUL_UNEQUIP, this._soulChange);
            this.bindModelEvent(this._model, mvc.GodConst.EVT.USE_SLOT, this._onUseSlot);
        }
        initCtrlEvent() {
            this.box101.on(Laya.Event.CLICK, this, this._onBoxClick, [101]);
            this.box201.on(Laya.Event.CLICK, this, this._onBoxClick, [201]);
            this.box301.on(Laya.Event.CLICK, this, this._onBoxClick, [301]);
            this.btnBall.on(Laya.Event.CLICK, this, this._onBtnBall);
            this.boxChangeSkill.on(Laya.Event.CLICK, this, this._onBtnChange);
            this.btnSkillPre.on(Laya.Event.CLICK, this, this._onBtnSkillPre);
            this.clipEff201.on(Laya.Event.COMPLETE, this, this._onUnlockAniEnd, [this.clipEff201]);
            this.clipEff301.on(Laya.Event.COMPLETE, this, this._onUnlockAniEnd, [this.clipEff301]);
        }
        onAwake() {
            super.onAwake();
            this.lblUse101.text = sg.translate("（已出战）");
            this.lblUse201.text = sg.translate("（已出战）");
            this.lblUse301.text = sg.translate("（已出战）");
        }
        onEnable() {
            super.onEnable();
            this._updateSoul(101);
            this._updateSoul(201);
            this._updateSoul(301);
            this._updateWuxing();
        }
        onDisable() {
            this.ani201.stop();
            this.ani301.stop();
            super.onDisable();
        }
        _onUseSlot(id, type) {
            if (!this._god || !(this._god.id == id))
                return;
            this._updateSoul(101);
            this._updateSoul(201);
            this._updateSoul(301);
            this._updateWuxing();
        }
        _onUnlock(id, type) {
            if (!this._god || !(this._god.id == id))
                return;
            let ani = this["clipEff" + type];
            if (ani) {
                ani.visible = true;
                ani.play(0, ani.total - 1);
            }
            this._soulChange(id, type);
        }
        _onUnlockAniEnd(ani) {
            ani.visible = false;
        }
        _updateWuxing() {
            let type = [0, 0];
            for (let i = 1; i <= 2; i++) {
                let id = this._model.lineup.get(i);
                if (id) {
                    let vo = this._model.godMap.get(id);
                    type[i - 1] = vo.getWuxing();
                }
            }
            let wuxing = this._model.getWuxingSkill(type[0], type[1]);
            if (wuxing) {
                this.boxHaveSkill.visible = true;
                this.boxNoSkill.visible = false;
                let cfg = sg.dbmgr.get("skill_skill", wuxing.skill);
                this.lblSkillName.text = cfg.name;
                this.lblSkillDesc.text = cfg.desc;
            }
            else {
                this.boxHaveSkill.visible = false;
                this.boxNoSkill.visible = true;
            }
        }
        _soulChange(id, type) {
            if (!this._god || !(this._god.id == id))
                return;
            this._updateSoul(type);
        }
        _updateSoul(type) {
            let clipType = this["clipType" + type];
            mgr.icon.drawTexture(this._imgMap[type], clipType);
            clipType.index = this._god.getSlotWuxing(type) - 1;
            let lblUse = this["lblUse" + type];
            let unitRed = this["unitRed" + type];
            unitRed.visible = false;
            let ani = this["ani" + type];
            if (ani)
                ani.gotoAndStop(0);
            let soul = this._god.soulMap.get(type);
            if (!soul || !soul.is_unlock) {
                this["imgBall" + type].visible = false;
                this["imgLock" + type].visible = true;
                lblUse.visible = false;
                let scfg = sg.dbmgr.get("god_godSoul", type);
                if (this._god.grade >= scfg.condition[1]) {
                    unitRed.visible = true;
                    if (ani)
                        ani.play(0, true);
                }
            }
            else {
                this["imgLock" + type].visible = false;
                if (soul.bead) {
                    this["imgBall" + type].visible = true;
                    let vo = mvc.bagModel.getVoById(soul.bead);
                    let url = mgr.icon.getIconPath(vo.iconUrl);
                    mgr.icon.drawTexture(url, this["imgBall" + type]);
                }
                else {
                    this["imgBall" + type].visible = false;
                    if (this._model.isLineup(this._god.id)) {
                        let balls = mvc.bagModel.getItemsByType(mvc.BagConst.BagType.ELEMENT_BEAD);
                        let haveOne = false;
                        for (let ball of balls) {
                            if (!ball.bead.god_id) {
                                haveOne = true;
                                break;
                            }
                        }
                        unitRed.visible = haveOne;
                    }
                }
                lblUse.visible = this._god.useSlot == type;
            }
        }
        _onBoxClick(type) {
            let soul = this._god.soulMap.get(type);
            if (!soul || !soul.is_unlock) {
                let scfg = sg.dbmgr.get("god_godSoul", type);
                if (this._god.grade >= scfg.condition[1]) {
                    this._ctrl.reqSoulUnlock(this._god.id, type);
                }
                else {
                    let grade = scfg.condition[1];
                    sg.uimgr.showNotice(StringEx.format(sg.translate("神仙达到${grade}阶解锁"), {"grade":grade}));
                }
            }
            else {
                sg.uimgr.showUI("pop_godSoulTips", this._god, type);
            }
        }
        _onBtnBall() {
            sg.uimgr.showUI("pop_godBallBag");
        }
        _onBtnChange() {
            sg.uimgr.showUI("pop_godChangeSkill");
        }
        _onBtnSkillPre() {
            sg.uimgr.showUI("pop_godSkillPre");
        }
    }
    mvc.UnitGodSoul = UnitGodSoul;
})(mvc || (mvc = {}));

