            this._colorMap = [
                "ui/god/sx_x1.png",
                "ui/god/sx_x2.png",
                "ui/god/sx_x3.png",
                "ui/god/sx_x4.png",
                "ui/god/sx_x5.png",
                "ui/god/sx_x6.png",
            ];
