var mvc;
(function (mvc) {
    class PopFomationEngraveView extends ui.view.formation.pop_fomationEngraveUI {
        initView(curVo) {
            this._engravevo = curVo;
            this._currLevel = curVo.getLv();
        }
        initModelEvent() {
            this.bindModelEvent(mvc.formationModel, mvc.FormationConst.EVT.UPDATE_FORMATION_ENGRAVE, this._onFormationEngrave);
        }
        initCtrlEvent() {
            this.btnEngrave.on(Laya.Event.CLICK, this, this._onClick);
            this.effEngraveUpgrade.ani1.on(Laya.Event.COMPLETE, this, this._onEngraveUpgradeEffEnd);
        }
        onAwake() {
            super.onAwake();
            this.lblName.text = sg.translate("全忽视加成");
        }
        onEnable() {
            super.onEnable();
            this.updateView();
            this._aniEnd();
        }
        onClose() {
            super.onClose();
            this.ani1.stop();
            this.effExpChange.stop();
        }
        _onFormationEngrave() {
            this._engravevo = mvc.formationModel.getEngrave();
            this.effExpChange.visible = true;
            this.effExpChange.play(0, this.effExpChange.total);
            if (this._engravevo.getLv() > this._currLevel) {
                this._currLevel = this._engravevo.getLv();
                this._playLvUpAni();
                if (this._currLevel <= this.boxAttribute.numChildren) {
                    this.effEngraveUpgrade.visible = true;
                    this.effEngraveUpgrade.ani1.play(0, false);
                    this.effEngraveUpgrade.parent.visible = true;
                    this.effEngraveUpgrade.parent.rotation = this._getAngleToLv(this._currLevel - 1, this.boxAttribute.numChildren);
                }
                this.timerOnce(667, this, this.updateView);
            }
            else {
                this.updateView();
            }
        }
        updateView() {
            if (this._engravevo == null) {
                return;
            }
            let currLv = this._engravevo.getLv();
            let nextLv = currLv + 1;
            let currConfig = sg.dbmgr.get("formation_engrave", currLv + 1);
            let nextConfig = sg.dbmgr.get("formation_engrave", nextLv + 1);
            let experience = 100;
            if (currConfig) {
                this._setLblTextToAttr(currConfig, this.lblCurrAtr, this.lblCurrBaseAttr);
            }
            let BaseAttrShow = true;
            if (nextConfig) {
                experience = nextConfig.experience;
                this._setLblTextToAttr(nextConfig, this.lblNextAtr, this.lblNextBaseAttr);
                BaseAttrShow = !(nextConfig.levelAttr2 == null || nextConfig.levelAttr2[0][1] == 0);
                this.lblBaseAttrName.visible = this.lblCurrBaseAttr.visible = this.lblNextBaseAttr.visible = BaseAttrShow;
                this._isMax = false;
            }
            else {
                this.lblNextAtr.visible = false;
                this._isMax = true;
            }
            this._showMaxLv(this._isMax, BaseAttrShow);
            this._setEngraveExpProgress(this._isMax ? experience : this._engravevo.gteExp(), experience);
            this.lblLv.text = mgr.UIAssist.$(sg.translate("镌刻等级：Lv.{1}"), this._engravevo.getLv());
            this._showActivateAttributeImge(this._engravevo.getLv());
        }
        _setLblTextToAttr(config, lb1, lb2) {
            if (config == null) {
                return;
            }
            let attrData1 = config.levelAttr[0];
            let attrData2 = config.levelAttr2;
            let cfg1 = mvc.PropertyModel._getCfg(attrData1[0]);
            lb1.text = cfg1.is_per ? attrData1[1] / 100 + "%" : attrData1[1];
            if (attrData2 == null) {
                lb2.text = `0%`;
            }
            else {
                let cfg2 = mvc.PropertyModel._getCfg(attrData2[0][0]);
                lb2.text = cfg2.is_per ? attrData2[0][1] / 100 + "%" : attrData1[0][1];
            }
        }
        _setEngraveExpProgress(cur, max) {
            this.boxUnitCellProgress.updateView(cur / max, max);
            this.boxUnitCellProgress.getChildByName('boxBar').visible = false;
            this.boxUnitCellProgress.getChildByName('lblValue').text = `${cur}/${max}`;
        }
        _showMaxLv(isMax, BaseAttrShow) {
            let show = !isMax;
            this.boxUnitCellProgress.getChildByName('lblValue').visible = show;
            this.lblNextBaseAttr.visible = this.imgBaseNext.visible = this.imgBaseUpLogo.visible = show && BaseAttrShow;
            this.lblNextLv.visible = this.ImgNext.visible = this.imgUpLogo.visible = this.lblNextAtr.visible = show;
            if (isMax) {
                if (!this.ani1.isPlaying) {
                    this.ani1.play(0, true);
                }
                this.btnEngrave.label = mgr.UIAssist.$(sg.translate("已满级"));
                this.btnEngrave.disabled = true;
            }
            else {
                this.ani1.stop();
                this.btnEngrave.label = mgr.UIAssist.$(sg.translate("镌刻法阵"));
            }
        }
        _showActivateAttributeImge(lv) {
            if (!this.boxAttribute || this.boxAttribute.numChildren == 0) {
                return;
            }
            for (let i = 0; i < this.boxAttribute.numChildren; i++) {
                this.boxAttribute.getChildAt(i).visible = i < lv;
            }
        }
        _getAngleToLv(lv, max) {
            return Math.floor(lv / max * 360);
            ;
        }
        _onClick(event) {
            let target = event.target;
            switch (target) {
                case this.btnEngrave:
                    if (this._isMax) {
                        sg.uimgr.showNotice(sg.translate('已达到最大镌刻等级'));
                    }
                    else {
                        sg.uimgr.showUI("pop_EngraveSelectView", this._engravevo);
                    }
                    break;
            }
        }
        _playLvUpAni() {
            let eff = sg.Effect2D.create("eff_ui_shenjichengong", true, false, true);
            eff.x = 193;
            eff.y = 736;
            eff.name = "eff_ui_shenjichengong";
            eff.on(Laya.Event.STOPPED, this, this._aniEnd);
            this.addChild(eff);
        }
        _aniEnd() {
            this.removeChildByName("eff_ui_shenjichengong");
            this.effExpChange.visible = false;
        }
        _onEngraveUpgradeEffEnd() {
            this.effEngraveUpgrade.visible = false;
        }
    }
    mvc.PopFomationEngraveView = PopFomationEngraveView;
})(mvc || (mvc = {}));

