(function (mvc) {
    class PopFormationInfo extends ui.view.formation.pop_formationEntranceUI {
        initView(info) {
            this._formation = info;
        }
        onAwake() {
            super.onAwake();
            this.btnEnter.on(Laya.Event.CLICK, this, this._onEnterClick);
            this.listAttr1.vScrollBarSkin = null;
            this.listAttr2.vScrollBarSkin = null;
            this.listSecretAttr.vScrollBarSkin = null;
            this.listAttr1.renderHandler = Laya.Handler.create(this, this.renderList, null, false);
            this.listAttr2.renderHandler = Laya.Handler.create(this, this.renderList, null, false);
            this.listSecretAttr.renderHandler = Laya.Handler.create(this, this.renderList, null, false);
            this.listForShow.renderHandler = Laya.Handler.create(this, this.renderEyeList, null, false);
            this.lblEmpty.text = sg.translate("暂未布阵");
            this.lblEmptyEye.text = sg.translate("暂无加成");
            this.lblEmptyEngrave.text = sg.translate("暂无加成");
        }
        onEnable() {
            super.onEnable();
            this.updateView();
        }
        updateView() {
            let bsaeAttr;
            let eyeAttr;
            let engraveAttr;
            if (this._formation) {
                let cfg = sg.dbmgr.get("formation_formation", this._formation.id);
                this.unitFormation.initView(cfg, false, false);
                bsaeAttr = [];
                let bAttr = this._formation.base_attr;
                for (let v of bAttr) {
                    let cfg = sg.dbmgr.get("attribute", v[0]);
                    if (cfg) {
                        let arr = [cfg.name, v[1]];
                        bsaeAttr.push(arr);
                    }
                }
                eyeAttr = [];
                let eAttr = this._formation.eye_attr;
                for (let v of eAttr) {
                    let cfg = sg.dbmgr.get("attribute", v[0]);
                    if (cfg) {
                        eyeAttr.push([cfg.name, v[1]]);
                    }
                }
                engraveAttr = [];
                let egAttr = this._formation.engrave_attr;
                for (let v of egAttr) {
                    let cfg = sg.dbmgr.get("attribute", v[0]);
                    if (cfg) {
                        engraveAttr.push([cfg.name, v[1]]);
                    }
                }
                this.btnEnter.visible = false;
                this.listForShow.array = this._formation.eyes.sort((a, b) => {
                    return a[0] - b[0];
                });
                this.lblEngraveLv.text = `Lv.${this._formation.engrave_level}`;
            }
            else {
                bsaeAttr = mvc.formationModel.getFormationBaseAttr(mvc.formationModel.curFormationVo);
                eyeAttr = mvc.formationModel.getFormationEyeArrAttr();
                engraveAttr = mvc.formationModel.getFormationEngraveAttr();
                let cfg = mvc.formationModel.curFormationVo.cfg;
                this.unitFormation.initView(cfg, false, false);
                this.btnEnter.visible = true;
                this.listForShow.array = mvc.formationModel.mapEyeArr;
                this.lblEngraveLv.text = `Lv.${mvc.formationModel.getEngrave().getLv().toString()}`;
            }
            bsaeAttr.sort((a, b) => {
                let aCfg = mvc.PropertyModel._getCfg(a[0]);
                let bCfg = mvc.PropertyModel._getCfg(b[0]);
                if (aCfg.show_priority == bCfg.show_priority) {
                    return aCfg.id - bCfg.id;
                }
                return aCfg.show_priority - bCfg.show_priority;
            });
            this.listAttr1.array = bsaeAttr;
            this.listAttr2.array = eyeAttr;
            this.listSecretAttr.array = engraveAttr;
            this.lblEmpty.visible = bsaeAttr.length == 0;
            this.lblEmptyEye.visible = eyeAttr.length == 0;
            this.lblEmptyEngrave.visible = engraveAttr.length == 0;
        }
        renderList(item, index) {
            let one = item.getChildAt(0);
            let two = item.getChildAt(1);
            let cfg = mvc.PropertyModel._getCfg(item.dataSource[0]);
            one.text = cfg.show_name;
            two.text = cfg.is_per ? item.dataSource[1] / 100 + "%" : item.dataSource[1];
        }
        renderEyeList(item, index) {
            let data = item.dataSource;
            let imgBg = item.getChildByName("imgBg");
            let imgLock = item.getChildByName("imgLock");
            let cfg;
            let is_active = false;
            if (data.id) {
                cfg = data.cfg;
                is_active = data.isActive;
            }
            else {
                cfg = sg.dbmgr.get("formation_arrayEye", data[0]);
                is_active = data[1] == 1;
            }
            imgLock.visible = !is_active;
            if (is_active) {
                imgBg.filters = null;
            }
            else {
                imgBg.filters = [mvc.formationModel.tempFilter._filter];
            }
            mgr.icon.drawTexture(mgr.icon.getIconPath(cfg.icon), imgBg);
        }
        _onEnterClick() {
            sg.uimgr.showUI("sys_formationMainView");
            this.closeSelf();
        }
    }
    mvc.PopFormationInfo = PopFormationInfo;
})(mvc || (mvc = {}));

