(function (mvc) {
    class PopFormationOneKey extends ui.view.formation.pop_forgeOneKeyResultUI {
        initView(item) {
            this._titleSkin = "gxhd";
            this._data = item;
        }
        initModelEvent() { }
        initCtrlEvent() {
            this.listReward.vScrollBarSkin = "";
            this.listReward.renderHandler = this.createHandler(this, this.renderBox, null, false);
            this.listReward.selectEnable = true;
            this.listReward.selectHandler = this.createHandler(this, this.selectBox, null, false);
        }
        onAwake() {
            super.onAwake();
            this.boxResultSuc.skin = this._titleSkin;
        }
        onEnable() {
            super.onEnable();
            sg.sound.playSoundByID(mvc.UISound.GXHD);
            let items = [];
            for (let key in this._data) {
                let data = this._data[key];
                if (data) {
                    let v = new mvc.BagItemVo();
                    v.updateData(data);
                    items.push(v);
                }
            }
            this.listReward.array = items;
        }
        onClosed() {
            super.onClosed();
            if (this._unitFormation && !this._unitFormation.parent)
                this._unitFormation.destroy();
            this._unitFormation = null;
        }
        renderBox(box, idx) {
            let data = box.dataSource;
            if (!data)
                return;
            let cell = box.getChildByName("unitIcon");
            let lblName = box.getChildByName("lblName");
            let clip = box.getChildByName("clipShow");
            let ecfg = sg.dbmgr.get("formation_extraAttGear", mvc.formationModel.getSymbolAttrGear(data));
            clip.visible = ecfg && ecfg.luminous == 1;
            let str = null;
            let index = 0;
            if (ecfg && ecfg.luminous == 2) {
                str = "ui/common/Clip/Clip_5pin_di.png";
                index = 0;
            }
            else if (ecfg && ecfg.luminous == 1) {
                str = "ui/common/Clip/Clip_5pin_di.png";
                index = 1;
            }
            cell.changeClip(str, index, 1, 2);
            cell.initView(data, false);
            data.getCfg() && lblName.changeText(data.getCfg().name);
        }
        selectBox(idx) {
            let item = this.listReward.getCell(idx);
            if (item) {
                if (!this._tempVo) {
                    this._tempVo = new Laya.Point();
                }
                this._tempVo.setTo(item.mouseX, item.mouseY);
                item.localToGlobal(this._tempVo, false, this);
                if (!this._unitFormation)
                    this._unitFormation = new mvc.UnitSymbolTip();
                this._unitFormation.initView(item.dataSource);
                this.addChild(this._unitFormation);
                this._unitFormation.pos(this._tempVo.x, this._tempVo.y);
                this.off(Laya.Event.CLICK, this, this.onClick);
                this.callLater(() => {
                    this.on(Laya.Event.CLICK, this, this.onClick);
                });
            }
        }
        onClick() {
            if (this._unitFormation && this._unitFormation.parent) {
                this._unitFormation.removeSelf();
            }
            this.off(Laya.Event.CLICK, this, this.onClick);
        }
        getProp(data) {
            for (let key in data) {
                if (data[key].value != 0)
                    return data[key];
            }
        }
    }
    mvc.PopFormationOneKey = PopFormationOneKey;
})(mvc || (mvc = {}));

