                let lblMoneyNum = btnBuy.getChildByName("lblMoneyNum");
                let lblItemName = boxItem.getChildByName("lblItemName");
                let sprMoneyType = btnBuy.getChildByName("sprMoneyType");
                let clipQua = boxItem.getChildByName("clipQua");
                let sprIcon = boxItem.getChildByName("sprIcon");
                btnBuy.on(Laya.Event.CLICK, this, this.onbtnBuy, [data]);
                sprIcon.on(Laya.Event.CLICK, this, this.onbtnShowTip, [data.id]);
                lblMoneyNum.text = data.cost[0][1];
                lblMoneyNum.color = mgr.toolsMgr.checkConsume(data.cost, false) ? "#0b7d13" : "#ea3e09";
                mgr.icon.drawTexture(mgr.icon.getIconPath(mgr.toolsMgr.getIconById(data.cost[0][0])), sprMoneyType);
                clipQua.index = data.quality - 1;
