                imgMask.visible = lblUse.visible = mvc.formationModel.getCurFormation().checkUsedSymbol(data.bagId);
                unitItem.initView(data, false);
                let ecfg = sg.dbmgr.get("formation_extraAttGear", mvc.formationModel.getSymbolAttrGear(data));
                clip.visible = ecfg && ecfg.luminous == 1;
