(function (mvc) {
    class GameStoryModel extends sg.ModelBase {
        constructor() {
            super(...arguments);
            this.mConst = mvc.GameStoryConst;
            this.OPEN = true;
        }
        initModel() {
            this.vo = new mvc.GameStoryInfoVo();
            this.isRewardState = 0;
        }
        registerEvents() {
        }
        willEnterGame() {
        }
        startStory(id, guideId = 0, sCallback = null) {
            this.vo.id = id;
            let ui = sg.uimgr.getPermanentUI("perm_gameStory");
            if (ui)
                ui.updateData("perm_gameStory", guideId);
            else
                sg.uimgr.showPermanentUI("perm_gameStory", guideId, sCallback);
        }
        excute(vo) {
            if (!vo)
                return;
            let type = vo.finishDo.split(":")[0];
            let comment = vo.finishDo.split(":")[1];
            switch (type) {
                case "view":
                    sg.uimgr.showUI(comment, vo);
                    break;
            }
        }
        getStartIndex(strs) {
            if (!strs)
                return 0;
            for (let i = 0; i < strs.length; i++) {
                if (strs[i]) {
                    return i;
                }
            }
            return 0;
        }
        delEmptyString(strs) {
            if (!strs)
                return undefined;
            for (let i = 0; i < strs.length; i++) {
                if (!strs[i])
                    strs.splice(i, 1);
            }
            return strs;
        }
        delZero(nums) {
            if (!nums)
                return undefined;
            for (let i = 0; i < nums.length; i++) {
                if (nums[i] == 0)
                    nums.splice(i, 1);
            }
            return nums;
        }
        getNode(id) {
            return sg.dbmgr.get(mvc.GameStoryConst.node, id);
        }
        getStory(ids) {
            return sg.dbmgr.filter(mvc.GameStoryConst.gameStory, (id, info) => {
                return ids.indexOf(parseInt(id)) > -1;
            });
        }
    }
    mvc.GameStoryModel = GameStoryModel;
})(mvc || (mvc = {}));

