(function (mvc) {
    class PopGameStory extends ui.view.gameStory.pop_gameStoryUI {
        constructor() {
            super(...arguments);
            this._lastMan = false;
            this.words = '';
            this._isFirst = true;
            this._isEnd = true;
            this._gsCallback = null;
        }
        initView(gsCallback = null) {
            this._model = mvc.gameStoryModel;
            this._ctrl = mvc.gameStoryCtrl;
            this._gsCallback = gsCallback;
        }
        initSendMsg() { }
        initModelEvent() { }
        initCtrlEvent() {
            this.btnJump.on(Laya.Event.CLICK, this, this.onBtnJump);
            this.box.on(Laya.Event.CLICK, this, this.onClickBox);
        }
        updateData() {
            if (this.hasLoaded()) {
                this.initDefault();
            }
        }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            this.initDefault();
        }
        onDisable() {
            let cfg = sg.dbmgr.get("gameStory_node", this._model.vo.id);
            if (cfg.type == 4 && !this._isEnd) {
                this.onStoryEnd();
            }
            super.onDisable();
        }
        initDefault() {
            let vo = this._model.vo;
            let nodeVo = this._model.getNode(vo.id);
            this.storys = this._model.getStory(nodeVo.storyID);
            this.imgMask.visible = nodeVo.isShowMask;
            if (this.storys)
                this.startStroy();
        }
        onClickBox() {
            mgr.toolsMgr.disabledButtonTimeout(this.box, 100);
            this.excute();
        }
        onBtnJump(evt) {
            evt.stopPropagation();
            this.excute();
        }
        startStroy() {
            this._isEnd = false;
            if (this.isEnd()) {
                this.onStoryEnd();
            }
            else {
                this.story = this.storys.shift();
                let bansheng = mvc.roleModel.roleInfo.sex == 1 ? this.story.girlFaces : this.story.headFaces;
                if (bansheng[1]) {
                    let url = mgr.icon.getIconPath(bansheng[1] + ".png");
                    mgr.icon.drawTexture(url, this.imgMan1);
                }
                else {
                    this.imgMan1.skin = null;
                }
                if (bansheng[0]) {
                    let url2 = mgr.icon.getIconPath(bansheng[0] + ".png");
                    mgr.icon.drawTexture(url2, this.imgMan2);
                }
                else {
                    this.imgMan2.skin = null;
                }
                this.lblName1.text = this.story.names[1];
                this.lblName2.text = this.story.names[0];
                this.lblPreName1.text = this.story.names[1];
                this.lblPreName2.text = this.story.names[0];
                this.btnJump.visible = this.story.jump == 1;
                this.contents = this.story.contents.concat();
                let voices = mvc.roleModel.roleInfo.sex == 0 ? this.story.girlSound : this.story.sound;
                if (voices) {
                    this.voices = voices.concat();
                }
                else {
                    this.voices = null;
                }
                this.startContents();
            }
        }
        startContents() {
            if (!this.contents)
                return;
            let content = this.contents.shift();
            this._startIndex = mvc.gameStoryModel.getStartIndex(content);
            this.content = mvc.gameStoryModel.delEmptyString(content);
            if (this.voices) {
                this.voice = mvc.gameStoryModel.delZero(this.voices.shift());
            }
            else {
                this.voice = null;
            }
            if (this.content) {
                this.content_index = 0;
                this.startContent();
            }
            else {
                this.startStroy();
            }
        }
        startContent() {
            if (!this.content)
                return;
            this.words = this.content[this.content_index];
            if (this.voice) {
                let voice = this.voice[this.content_index];
                if (voice && voice > 0) {
                    sg.sound.playVoice(voice);
                }
            }
            if (this.words && this.words != '') {
                this.startTween();
                if (this.words != undefined)
                    this.content_index++;
            }
            else {
                this.startContents();
            }
        }
        startTween() {
            if (this.words && this.words != '') {
                this.box.visible = true;
                let v = this.content_index + this._startIndex == 1;
                this.imgMan1.visible = v;
                this.lblName1.visible = v;
                this.imgMan2.visible = !v;
                this.lblName2.visible = !v;
                this.tweenWordLeft();
            }
            else {
                this.startContent();
            }
        }
        tweenWordLeft() {
            this.lblContent.text = this.words;
            this.down.gotoAndStop(this.down.count);
        }
        excute() {
            this.stopTimer(this.excute);
            sg.sound.stopCurVoice();
            if (!this.content || (this.content_index >= this.content.length && this.story.finishDo)) {
                if (!this.contents || this.contents.length == 0) {
                    this._model.excute(this.story);
                    sg.uimgr.removePermanentUI("perm_gameStory");
                }
                else {
                    this.startContents();
                }
            }
            else {
                this.startContent();
            }
        }
        isEnd() {
            return !this.storys || this.storys.length == 0;
        }
        onStoryEnd() {
            this._isEnd = true;
            if (this._gsCallback)
                this._gsCallback.method();
        }
    }
    mvc.PopGameStory = PopGameStory;
})(mvc || (mvc = {}));

