(function (mvc) {
    class ForbiAreaTaskModel extends sg.ModelBase {
        initModel() {
            this.tasksMap = {};
            this.refreshCount = 0;
            this.redTip = true;
        }
        registerEvents() {
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.FORBIAREATASK_REWARD, this.redTipsReward, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.FORBIAREATASK_REFRESH, this.redTipsRefresh, this);
        }
        setTaskInfo(data) {
            this._setTaskInfo(data.tasks);
            this.refreshCount = data.count;
            mgr.redotMgr.check(mvc.REDOT_ID.FORBIAREATASK_REWARD);
            mgr.redotMgr.check(mvc.REDOT_ID.FORBIAREATASK_REFRESH);
            this.fireEvent(mvc.ForbiAreaTaskConst.EVT.UPDATE);
        }
        _setTaskInfo(data) {
            for (let i = 0; i < data.length; i++) {
                let taskVo = this.tasksMap[data[i].id];
                if (!taskVo) {
                    taskVo = new mvc.ForbiAreaTaskVo();
                    this.tasksMap[data[i].id] = taskVo;
                }
                this.tasksMap[data[i].id].id = data[i].id;
                this.tasksMap[data[i].id].order = data[i].order;
                this.tasksMap[data[i].id].small_task = data[i].small_task;
                this.tasksMap[data[i].id].is_received = data[i].is_received;
            }
        }
        taskReward(data) {
            this.tasksMap[data.id].is_received = 1;
            let tip = sg.translate("委托奖励");
            sg.uimgr.showUI("pop_getReward", tip, data.reward);
            mvc.forbiAreaTaskCtrl.reqForbiAreaTaskInfo();
        }
        taskRefresh(data) {
            this._setTaskInfo(data.tasks);
            this.refreshCount = data.count;
            this.fireEvent(mvc.ForbiAreaTaskConst.EVT.UPDATE);
        }
        taskCombat(data) {
            this._lastReport = data.combat_notify;
            mvc.battleModel.startBattle(data.combat_notify, Proto.COMBAT_TYPE.SLG_TASK, () => {
                mvc.forbiAreaTaskCtrl.reqForbiAreaTaskFinishCombat();
            });
        }
        taskFinishCombat(data) {
            if (data.result == 1) {
                this.tasksMap[data.tasks.id].id = data.tasks.id;
                this.tasksMap[data.tasks.id].order = data.tasks.order;
                this.tasksMap[data.tasks.id].small_task = data.tasks.small_task;
                this.tasksMap[data.tasks.id].is_received = data.tasks.is_received;
            }
            let closeFun = null;
            let tip = sg.translate("委托奖励");
            sg.uimgr.showFbResult({ result: data.result, desc: tip, reward: data.reward, closeFunc: closeFun }, this._lastReport);
            this._lastReport = null;
            mgr.redotMgr.check(mvc.REDOT_ID.FORBIAREATASK_REWARD);
            this.fireEvent(mvc.ForbiAreaTaskConst.EVT.UPDATE);
        }
        taskCollect(data) {
            if (data.tasks) {
                this.tasksMap[data.tasks.id].id = data.tasks.id;
                this.tasksMap[data.tasks.id].order = data.tasks.order;
                this.tasksMap[data.tasks.id].small_task = data.tasks.small_task;
                this.tasksMap[data.tasks.id].is_received = data.tasks.is_received;
            }
            let tip = sg.translate("委托奖励");
            sg.uimgr.showUI("pop_getReward", tip, data.reward);
            mgr.redotMgr.check(mvc.REDOT_ID.FORBIAREATASK_REWARD);
            this.fireEvent(mvc.ForbiAreaTaskConst.EVT.UPDATE);
        }
        redTipsReward() {
            if (!this.tasksMap) {
                return 0;
            }
            for (let i in this.tasksMap) {
                if (this.tasksMap[i].small_task.is_finish == 1 && this.tasksMap[i].is_received != 1) {
                    return 1;
                }
            }
            return 0;
        }
        redTipsRefresh() {
            if (this.redTip && this.refreshCount > 0) {
                return 1;
            }
            return 0;
        }
    }
    mvc.ForbiAreaTaskModel = ForbiAreaTaskModel;
})(mvc || (mvc = {}));

