var mvc;
(function (mvc) {
    class GuidePhaseVo extends sg.VoBase {
        static create(data) {
            let vo = new GuidePhaseVo();
            vo.cloneProtoData(data);
            if (vo.view == "sys_main") {
                vo.view = "perm_main";
            }
            let obj = {};
            let str = vo.params;
            let params = str.split(";");
            let comm = [];
            for (let param of params) {
                if (!param)
                    continue;
                comm = param.split(":");
                obj[comm[0]] = comm[1];
            }
            vo.paramsObj = obj;
            return vo;
        }
    }
    mvc.GuidePhaseVo = GuidePhaseVo;
})(mvc || (mvc = {}));

var mvc;
(function (mvc) {
    class GuideVo extends sg.VoBase {
        static create(data) {
            let vo = new GuideVo();
            vo.cloneProtoData(data);
            vo.phasesMap = new Map();
            for (let i = 0; i < vo.phases.length; i++) {
                let id = vo.phases[i];
                let cfg = sg.dbmgr.get("guide_guidePhase", id);
                if (!cfg) {
                    sg.loge("找不到guidePhase: " + id);
                    continue;
                }
                let pVo = mvc.GuidePhaseVo.create(cfg);
                if (vo.phasesMap.has(pVo.view)) {
                    let arr = vo.phasesMap.get(pVo.view);
                    arr.push(pVo);
                }
                else {
                    let arr = [pVo];
                    vo.phasesMap.set(pVo.view, arr);
                }
                pVo.isLast = i == vo.phases.length - 1;
                pVo.guideID = vo.id;
            }
            return vo;
        }
    }
    mvc.GuideVo = GuideVo;
})(mvc || (mvc = {}));

var mvc;
(function (mvc) {
    class GuideModel extends sg.ModelBase {
        initModel() {
            this._allGuides = [];
        }
        registerEvents() {
            sg.uimgr.on(mvc.UIMGR_EVT.UI_ENABLE, this, this._onUIOpen);
            sg.uimgr.on(mvc.UIMGR_EVT.CLOSE_UI, this, this._onUIClose);
            sg.uimgr.on(mvc.UIMGR_EVT.CLOSE_ALL_UI, this, this._onAllUIClose);
            this.bindEvent(mvc.roleModel, mvc.RoleConst.EVT.PO_JING, this._onBreak);
        }
        willEnterGame() {
        }
        addGuide(id) {
            let cfg = sg.dbmgr.get("guide_guide", id);
            let vo = mvc.GuideVo.create(cfg);
            this._allGuides.length = 0;
            this._allGuides.push(vo);
            sg.timer.callLater(this, this._startGuide);
        }
        delGuide(id) {
            for (let i = 0; i < this._allGuides.length; i++) {
                let vo = this._allGuides[i];
                if (vo.id == id) {
                    this._allGuides.splice(i, 1);
                    break;
                }
            }
            sg.timer.callLater(this, this._startGuide);
        }
        skipCurGuide() {
            if (this._allGuides.length > 0) {
                for (let guide of this._allGuides) {
                    if (guide.skip) {
                        mvc.guideCtrl.reqSkip(guide.id);
                    }
                }
            }
        }
        judgeViewToFireEvent(configName, isAll = false) {
            if (!this._curGuide)
                return;
            if (this._isIgnoreView(configName))
                return;
            if (sg.ViewBase.ViewConfig[configName] || isAll) {
                this._updateVoState();
                this.fireEvent(mvc.GuideConst.EVT.GUIDE_CHANGE);
            }
        }
        getCurPhase() {
            return this._curPhase;
        }
        onGuideClick() {
            let arr = this._curGuide.phasesMap.get(this._curPhase.view);
            if (!arr)
                return;
            this._curIdx++;
            if (this._curIdx < arr.length) {
                this._updateVoState();
                this.fireEvent(mvc.GuideConst.EVT.GUIDE_CHANGE);
            }
        }
        _onBreak(isBreak) {
            if (isBreak) {
                if (mvc.roleModel.roleInfo.level <= 41) {
                    this.addGuide(27);
                }
                else {
                    this.delGuide(27);
                }
            }
        }
        _startGuide() {
            let vo = this._allGuides[0];
            if (!vo) {
                this._curGuide = null;
                sg.uimgr.hidePermanentUI("perm_guide");
                return;
            }
            this._curGuide = vo;
            this._preTopView = "";
            this._curIdx = 0;
            this._updateVoState();
            sg.uimgr.showPermanentUI("perm_guide");
        }
        _updateVoState() {
            let rootUINode = sg.uimgr.getRootUINode();
            let views = rootUINode["_children"];
            let topView = 'perm_main';
            if (views && views.length > 0) {
                for (let i = views.length - 1; i >= 0; i--) {
                    if (views[i].viewConfig.wtype == mvc.WIN_TYPE.LAYER || this._isIgnoreView(views[i].configName))
                        continue;
                    topView = views[i].configName;
                    break;
                }
            }
            let vo = this._curGuide;
            if (vo.phasesMap.has(topView)) {
                if (topView != this._preTopView) {
                    this._curIdx = 0;
                }
                this._curPhase = vo.phasesMap.get(topView)[this._curIdx];
            }
            else {
                this._curPhase = null;
            }
            this._preTopView = topView;
        }
        _onUIOpen(configName) {
            sg.timer.callLater(this, this.judgeViewToFireEvent, [configName]);
        }
        _onUIClose(configName) {
            sg.timer.callLater(this, this.judgeViewToFireEvent, [configName]);
        }
        _onAllUIClose(configName) {
            sg.timer.callLater(this, this.judgeViewToFireEvent, [configName, true]);
        }
        _isIgnoreView(configName) {
            switch (configName) {
                case "perm_guide":
                    return true;
                default:
                    return false;
            }
        }
    }
    mvc.GuideModel = GuideModel;
})(mvc || (mvc = {}));

var mvc;
(function (mvc) {
    class PermGuide extends ui.view.guide.perm_guideUI {
        initView() {
            this._ctrl = mvc.guideCtrl;
            this._model = mvc.guideModel;
        }
        initModelEvent() {
            this.bindModelEvent(this._model, mvc.GuideConst.EVT.GUIDE_CHANGE, this._updateGuide);
            this.bindModelEvent(this._model, mvc.GuideConst.EVT.GUIDE_FUNC_CHANGE, this._onFuncUpdate);
        }
        initCtrlEvent() {
            this.btnSkip.on(Laya.Event.CLICK, this, this._onBtnSkip);
        }
        _onBtnSkip() {
            mvc.guideModel.skipCurGuide();
        }
        onEnable() {
            super.onEnable();
            this._updateGuide();
            this.unitFinger.ani1.play(0, true);
        }
        onDisable() {
            this._clearTarget();
            this._clearList();
            this._clearFunc();
            super.onDisable();
        }
        set_visible(value) {
            super.set_visible(value);
            if (!value) {
                this._clearTarget();
                this._clearList();
            }
        }
        _updateGuide() {
            let pVo = this._model.getCurPhase();
            if (!pVo) {
                sg.uimgr.hidePermanentUI("perm_guide");
                return;
            }
            let ui = sg.uimgr.getUI(pVo.view);
            if (!ui) {
                console.error("ui:" + pVo.view + "不存在");
                sg.uimgr.hidePermanentUI("perm_guide");
                return;
            }
            this._clearTarget();
            this._clearList();
            this._clearFunc();
            if (pVo.paramsObj["func"]) {
                this._funcUI = ui;
                let funcCfg = pVo.paramsObj["func"].split(",");
                let funcName = funcCfg[0];
                let funcParams = funcCfg.splice(1, funcCfg.length - 1);
                this._funcName = funcName;
                this._funcParams = funcParams;
                if (ui["GuideFunc_" + funcName + "_start"]) {
                    ui["GuideFunc_" + funcName + "_start"]();
                }
                if (ui["GuideFunc_" + funcName]) {
                    let comp = ui["GuideFunc_" + funcName](funcParams);
                    if (comp) {
                        this._setTarget(comp);
                    }
                }
                else {
                    console.error("ui:" + pVo.view + "未实现func: " + funcName);
                    sg.uimgr.hidePermanentUI("perm_guide");
                }
                return;
            }
            let target;
            if (pVo.paramsObj["comp"]) {
                let params = pVo.paramsObj["comp"].split(",");
                let tmp = ui;
                for (let n of params) {
                    tmp = tmp[n];
                    if (!tmp) {
                        break;
                    }
                }
                target = tmp;
                if (!target) {
                    console.error("ui" + pVo.view + "控件" + pVo.paramsObj["comp"] + "不存在");
                    sg.uimgr.hidePermanentUI("perm_guide");
                    return;
                }
            }
            if (pVo.paramsObj["list"]) {
                if (target) {
                    ui = target;
                }
                let params = pVo.paramsObj["list"].split(",");
                let listName = params[0];
                let list = ui[listName];
                if (!list) {
                    console.error("ui" + pVo.view + ", List：" + listName + "不存在");
                    sg.uimgr.hidePermanentUI("perm_guide");
                    return;
                }
                this._curList = list;
                this._idx = Number(params[1]);
                this._listComp = params[2];
                list.on(Laya.Event.RENDER, this, this._onListItemRender);
                this._onListItemRender();
            }
            else {
                this._setTarget(target);
            }
            this._updatePointBox(pVo);
        }
        _onFuncUpdate() {
            this._clearTarget();
            if (this._funcName) {
                let funcName = "GuideFunc_" + this._funcName;
                if (this._funcUI[funcName]) {
                    let comp = this._funcUI[funcName](this._funcParams);
                    if (comp) {
                        this._curTarget = comp;
                        this._updatePos();
                        this.frameLoop(5, this, this._updatePos);
                    }
                }
            }
        }
        _updatePos() {
            let target = this._curTarget;
            let bounds = target.getBounds();
            Laya.Point.TEMP.x = bounds.x + bounds.width / 2;
            Laya.Point.TEMP.y = bounds.y + bounds.height / 2;
            target.parent.localToGlobal(Laya.Point.TEMP);
            this.globalToLocal(Laya.Point.TEMP);
            this.boxGuide.x = Laya.Point.TEMP.x - this.boxGuide.width / 2;
            this.boxGuide.y = Laya.Point.TEMP.y - this.boxGuide.height / 2;
        }
        _onListItemRender() {
            this.callLater(this._onListChange);
        }
        _setTarget(target) {
            target.on(Laya.Event.CLICK, this, this._onClick);
            this._curTarget = target;
            this._updatePos();
            this.frameLoop(5, this, this._updatePos);
            sg.uimgr.setPermanentUIVisibleTrue("perm_guide");
        }
        _onListChange() {
            if (!this._curList)
                return;
            this._clearTarget();
            let cell = this._curList.getCell(this._idx);
            if (!cell)
                return;
            let target = cell;
            if (this._listComp) {
                let tmp = cell[this._listComp];
                if (tmp) {
                    target = tmp;
                }
                else {
                    if (cell.getChildByName) {
                        tmp = cell.getChildByName(this._listComp);
                    }
                }
                if (tmp)
                    target = tmp;
            }
            this._setTarget(target);
        }
        _clearTarget() {
            this.clearTimer(this, this._updatePos);
            if (this._curTarget) {
                this._curTarget.off(Laya.Event.CLICK, this, this._onClick);
                this._curTarget.off(Laya.Event.CLICK, this, this._onClick);
                this._curTarget = null;
            }
        }
        _clearList() {
            if (this._curList) {
                this._curList.off(Laya.Event.RENDER, this, this._onListItemRender);
                this._curList = null;
            }
            this._idx = -1;
            this._listComp = null;
        }
        _clearFunc() {
            if (this._funcUI) {
                let funcName = "GuideFunc_" + this._funcName + "_end";
                if (this._funcUI[funcName]) {
                    this._funcUI[funcName]();
                }
            }
            this._funcUI = null;
            this._funcName = null;
            this._funcParams = null;
        }
        _updatePointBox(vo) {
            this.lblContent1.text = vo.arrowContent;
            this.lblContent1.align = this.lblContent1.textField.lines.length > 1 ? "left" : "center";
            this.boxText.width = this.imgBg1.width = Math.max(160, this.lblContent1.textField.textWidth + 30);
            this.boxText.height = this.imgBg1.height = this.lblContent1.textField.textHeight + 50;
            let px = this.boxText.width - 31;
            let posY = 0;
            switch (vo.arrowDir) {
                case "up":
                    this.imgBg1.anchorX = 0;
                    this.imgBg1.anchorY = 1;
                    this.imgBg1.scale(1, -1);
                    this.boxText.pivot(31, 0);
                    this.boxText.anchorX = 0;
                    this.boxText.anchorY = 1;
                    this.lblContent1.y = 30;
                    posY = this.boxGuide.height;
                    break;
                case "down":
                    this.imgBg1.anchorX = 0;
                    this.imgBg1.anchorY = 0;
                    this.imgBg1.scale(1, 1);
                    this.boxText.pivot(31, 0);
                    this.boxText.anchorX = 0;
                    this.boxText.anchorY = 1;
                    this.lblContent1.y = 15;
                    break;
                case "left":
                    this.imgBg1.anchorX = 1;
                    this.imgBg1.anchorY = 1;
                    this.imgBg1.scale(-1, -1);
                    this.boxText.pivot(px, 0);
                    this.boxText.anchorX = 0;
                    this.boxText.anchorY = 1;
                    this.lblContent1.y = 30;
                    posY = this.boxGuide.height;
                    break;
                case "right":
                    this.imgBg1.anchorX = 1;
                    this.imgBg1.anchorY = 0;
                    this.imgBg1.scale(-1, 1);
                    this.boxText.pivot(px, 0);
                    this.boxText.anchorX = 0;
                    this.boxText.anchorY = 1;
                    this.lblContent1.y = 15;
                    break;
            }
            this.boxText.pos(this.boxGuide.width / 2, posY);
            this.unitFinger.pos(this.boxGuide.width / 2, this.boxGuide.height / 2);
            if (vo.arrowOffset) {
                this.boxText.x += vo.arrowOffset[0][0];
                this.boxText.y += vo.arrowOffset[0][1];
                this.unitFinger.x += vo.arrowOffset[1][0];
                this.unitFinger.y += vo.arrowOffset[1][1];
            }
            switch (vo.styles) {
                case 1:
                    this.unitFinger.visible = false;
                    this.boxText.visible = true;
                    break;
                case 2:
                    this.unitFinger.visible = true;
                    this.boxText.visible = true;
                    break;
                default:
                    this.unitFinger.visible = true;
                    this.boxText.visible = false;
                    break;
            }
        }
        _onClick() {
            let pVo = this._model.getCurPhase();
            if (pVo.isLast) {
                this._ctrl.reqFinish(pVo.guideID);
            }
            else {
                this._model.onGuideClick();
            }
        }
    }
    mvc.PermGuide = PermGuide;
})(mvc || (mvc = {}));

