            this.vo.guild_idx = data.info.guild_idx;
            this.vo.sur_blocking_times = data.info.sur_blocking_times;
            this.vo.sur_blocking_cd = data.info.sur_blocking_cd;
            this.vo.sur_challenge_times = data.info.sur_challenge_times;
            this.vo.sur_challenge_cd = data.info.sur_challenge_cd;
            this.vo.log = data.info.log;
            this.vo.top_rank = data.info.top_rank;
            this.vo.top_rank_guild = data.info.top_rank_guild;
            this.vo.top_rank_guild_inside = data.info.top_rank_guild_inside;
            this.vo.is_received = data.info.is_received;
