var mvc;
(function (mvc) {
    class PopGHHinder extends ui.view.guildHunting.pop_ghHinderUI {
        initView() {
            this._model = mvc.guildHuntingModel;
            this._ctrl = mvc.guildHuntingCtrl;
            this.page = 0;
            this.pageNum = 5;
        }
        initSendMsg() {
            this._ctrl.reqGHBlockingList();
        }
        initModelEvent() {
            this.bindModelEvent(mvc.guildHuntingModel, mvc.GuildHuntingConst.EVT.UPDATE_HIN, this.updateView);
        }
        initCtrlEvent() {
            this.listHinder.itemRender = mvc.UnitGHHinderItem;
            this.listHinder.renderHandler = this.createHandler(this, this._onRenderHinder, null, false);
            this.btnBuy.on(Laya.Event.CLICK, this, this._onAddItemClick);
            this.btnLast.on(Laya.Event.CLICK, this, this._onBtnLast);
            this.btnNext.on(Laya.Event.CLICK, this, this._onBtnNext);
            this.btnRefresh.on(Laya.Event.CLICK, this, this._onRefresh);
        }
        updateData(types, ...args) { }
        onAwake() {
            super.onAwake();
            this.lblTip.text = sg.translate("暂无可阻击对象");
        }
        onEnable() {
            super.onEnable();
        }
        updateView() {
            let guildArr = this._model.blocking_list;
            if (guildArr && guildArr.length > 0) {
                this.listHinder.visible = true;
                this.listHinder.array = this.getListData();
                this.lblTip.visible = false;
            }
            else {
                this.listHinder.visible = false;
                this.lblTip.visible = true;
            }
            let vo = this._model.vo;
            if (!vo)
                return;
            let cfg = sg.dbmgr.get("timeRecover", 4);
            let max = cfg ? cfg.limit : 0;
            this.lblHinderNum.text = `${vo.sur_blocking_times}/${max}`;
            this.lblHinderNum.color = vo.sur_blocking_times > 0 ? "#36d626" : "#f81e1e";
            this.lblFraction.text = mgr.toolsMgr.getMoneyValueText(vo.personal_integral);
            if (vo.sur_blocking_cd > 0) {
                this.repeats(1000, this.onChallengeTime, true);
                this.lblCD.visible = true;
            }
            else {
                this.lblCD.visible = false;
            }
            if (vo.sur_blocking_recover_time > 0) {
                this.repeats(1000, this.onRecoverTime, true);
                this.lblRecoverTime.visible = true;
            }
            else {
                this.lblRecoverTime.visible = false;
            }
            if (vo.refresh_bl_cd > 0) {
                this.lblRefreshTime.visible = true;
                this.btnRefresh.disabled = true;
                this.repeats(1000, this.onRefreshTime, true);
            }
            else {
                this.lblRefreshTime.visible = false;
                this.btnRefresh.disabled = false;
            }
            let v1 = 1;
            if (this.page > 0)
                v1 = Math.floor(this.page / this.pageNum) + 1;
            let v2 = Math.floor(this._model.blocking_list.length / this.pageNum);
            if (this._model.blocking_list.length % this.pageNum > 0) {
                v2 += 1;
            }
            if (v2 == 0)
                v2 = 1;
            this.lblCurPage.text = StringEx.format(sg.translate("第${v1}/${v2}页"), {"v1":v1,"v2":v2});
        }
        _onRenderHinder(cell, index) {
            cell.initView(cell.dataSource);
        }
        getListData() {
            let guildArr = this._model.blocking_list;
            let dataList = [];
            for (let i = this.page; i < this.page + this.pageNum; i++) {
                if (guildArr[i])
                    dataList.push(guildArr[i]);
            }
            return dataList;
        }
        onChallengeTime() {
            if (this._model.vo.sur_blocking_cd <= 0) {
                this.stopTimer(this.onChallengeTime);
                this.lblCD.visible = false;
            }
            else {
                this.lblCD.visible = true;
                this.lblCD.text = sg.time.formatTimeStr(this._model.vo.sur_blocking_cd) + sg.translate("后可阻击");
            }
            this._model.vo.sur_blocking_cd--;
        }
        onRecoverTime() {
            if (this._model.vo.sur_blocking_recover_time <= 0) {
                this.stopTimer(this.onRecoverTime);
                this.lblRecoverTime.visible = false;
            }
            else {
                this.lblRecoverTime.visible = true;
                this.lblRecoverTime.text = sg.time.formatTimeStr(this._model.vo.sur_blocking_recover_time) + sg.translate("后恢复");
            }
            this._model.vo.sur_blocking_recover_time--;
        }
        onRefreshTime() {
            if (this._model.vo.refresh_bl_cd <= 0) {
                this.stopTimer(this.onRefreshTime);
                this.lblRefreshTime.visible = false;
                this.btnRefresh.disabled = false;
            }
            else {
                this.lblRefreshTime.visible = true;
                this.lblRefreshTime.text = sg.time.formatTimeStr(this._model.vo.refresh_bl_cd) + sg.translate("后可刷新");
            }
            this._model.vo.refresh_bl_cd--;
        }
        _onRefresh() {
            if (this._model.vo.refresh_bl_cd <= 0) {
                mvc.guildHuntingCtrl.reqGHrefresh();
            }
        }
        _onBtnLast() {
            if (this.page <= 0) {
                sg.uimgr.showNotice(sg.translate("已经是第一页了"));
                this.page = 0;
                return;
            }
            this.page = this.page - this.pageNum;
            this.updateView();
        }
        _onBtnNext() {
            let len = 0;
            let guildArr = this._model.blocking_list;
            if (guildArr && guildArr.length > 0)
                len = guildArr.length;
            let curPage = 1;
            if (this.page > 0)
                curPage = Math.floor(this.page / this.pageNum) + 1;
            let maxPage = Math.floor(len / this.pageNum);
            if (len % this.pageNum > 0) {
                maxPage += 1;
            }
            if (curPage >= maxPage) {
                sg.uimgr.showNotice(sg.translate("已经是最后一页了"));
                return;
            }
            this.page = this.page + this.pageNum;
            this.updateView();
        }
        _onAddItemClick() {
            let vo = this._model.vo;
            if (!vo)
                return;
            let cfg = sg.dbmgr.get("timeRecover", 4);
            let maxCount = cfg ? cfg.limit : 0;
            if (vo.sur_blocking_times >= maxCount) {
                sg.uimgr.showNotice(sg.translate("阻击次数已满"));
                return;
            }
            let arr = mgr.toolsMgr.getGlobalVoById("guild_Interdiction_consume", 1);
            let max = mgr.toolsMgr.getGlobalVoById("guild_hunting_block_buy_time", 1);
            let num = this._model.vo.blocking_buy_count;
            if (num >= max) {
                sg.uimgr.showNotice(sg.translate("今日购买上限了，请明日再来"));
                return;
            }
            let v1 = arr[0] + num * arr[1];
            let cost = [[1, v1]];
            let str = "";
            let v2 = mgr.toolsMgr.getNameById(1);
            str = StringEx.format(sg.translate("是否花费${v1}${v2}购买一次阻击次数?"), {"v1":v1,"v2":v2});
            let color = max > num ? mvc.COLOR.GREEN : mvc.COLOR.RED;
            let v3 = `<font color='${color}'>${max - num}/${max}</font>`;
            sg.uimgr.showUI("pop_confirmTwo", {
                enterFunc: () => {
                    if (mgr.toolsMgr.checkConsume(cost, true)) {
                        mvc.mainModel.consumeJade(cost, 1, () => {
                            mvc.guildHuntingCtrl.reqGHBlockingBuy();
                        });
                    }
                }, content: str, content2: StringEx.format(sg.translate("剩余购买次数:${v3}"), {"v3":v3}),
            });
        }
    }
    mvc.PopGHHinder = PopGHHinder;
})(mvc || (mvc = {}));

