var mvc;
(function (mvc) {
    class PopGHRank extends ui.view.guildHunting.pop_ghRankUI {
        initView(type) {
            this._type = type;
            this._model = mvc.guildHuntingModel;
        }
        initSendMsg() {
            mvc.rankCtrl.reqRankInfo(mvc.RankConst.RANK_TYPE.guild_hunting_single);
        }
        initModelEvent() {
            this.bindModelEvent(mvc.rankModel, mvc.RankConst.EVT.UPDATE_RANK_INFO, this.updateView);
            this.bindModelEvent(this._model, this._model.mConst.EVT.UPDATE_RANK, this.updateView);
        }
        initCtrlEvent() {
            this.manItemList.vScrollBarSkin = this.guildItemList.vScrollBarSkin = this.selfItemList.vScrollBarSkin = null;
            this.manItemList.itemRender = mvc.UnitManRankItem;
            this.guildItemList.itemRender = mvc.UnitGuildRankItem;
            this.selfItemList.itemRender = mvc.UnitSelfRankItem;
            this.manItemList.renderHandler = this.createHandler(this, this._onRenderManList, null, false);
            this.guildItemList.renderHandler = this.createHandler(this, this._onRenderGuildList, null, false);
            this.selfItemList.renderHandler = this.createHandler(this, this._onRenderSelfList, null, false);
            this.btnManRank.on(Laya.Event.CLICK, this, this._onManRankClick);
            this.btnGuildRank.on(Laya.Event.CLICK, this, this._onGuildRankClick);
            this.btnSelfRank.on(Laya.Event.CLICK, this, this._onSelfRankClick);
            this.btnSvrRank.on(Laya.Event.CLICK, this, this._onSvrRankClick);
            this.btnManRank.selected = true;
            this.btnGuildRank.selected = false;
        }
        updateData(types, ...args) { }
        onAwake() {
            super.onAwake();
            this.lblNotSelf.text = sg.translate("暂无人上榜");
            this.lblNotMan.text = sg.translate("暂无人上榜");
            this.lblNotGuild.text = sg.translate("暂无仙盟上榜");
        }
        onEnable() {
            super.onEnable();
        }
        onClosed() {
            super.onClosed();
            mvc.guildHuntingModel.fireEvent(mvc.guildHuntingModel.mConst.EVT.UPDATE);
        }
        _onRenderManList(cell, index) {
            cell.initView(cell.dataSource);
        }
        _onRenderGuildList(cell, index) {
            cell.initView(cell.dataSource);
        }
        _onRenderSelfList(cell, index) {
            cell.initView(cell.dataSource);
        }
        updateView(type, rankVo) {
            this.grp_man.visible = this.grp_guild.visible = this.grp_self.visible = false;
            switch (this._type) {
                case 0:
                    {
                        let item = this.boxItem.getChildByName("man");
                        if (!item) {
                            this.boxItem.removeChildren(0, this.boxItem.numChildren - 1);
                            item = new mvc.UnitManRankItem();
                            item.name = "man";
                            this.boxItem.addChild(item);
                        }
                        item.initView(rankVo.myValue);
                        this.grp_man.visible = true;
                        let type = mvc.RankConst.RANK_TYPE.guild_hunting_single;
                        this.manItemList.array = this.getListData(type);
                        if (this.manItemList.array.length == 0) {
                            this.lblNotMan.visible = true;
                        }
                        else {
                            this.lblNotMan.visible = false;
                        }
                    }
                    break;
                case 1:
                    {
                        let item = this.boxItem.getChildByName("guild");
                        if (!item) {
                            this.boxItem.removeChildren(0, this.boxItem.numChildren - 1);
                            item = new mvc.UnitGuildRankItem();
                            item.name = "guild";
                            this.boxItem.addChild(item);
                        }
                        item.initView(rankVo.myValue);
                        this.grp_guild.visible = true;
                        let type = mvc.RankConst.RANK_TYPE.guild_hunting;
                        this.guildItemList.array = this.getListData(type);
                        if (this.guildItemList.array.length == 0) {
                            this.lblNotGuild.visible = true;
                        }
                        else {
                            this.lblNotGuild.visible = false;
                        }
                    }
                    break;
                case 2:
                    {
                        let item = this.boxItem.getChildByName("self");
                        if (!item) {
                            this.boxItem.removeChildren(0, this.boxItem.numChildren - 1);
                            item = new mvc.UnitSelfRankItem();
                            item.name = "self";
                            this.boxItem.addChild(item);
                        }
                        let itemVo = { not: true };
                        this.grp_self.visible = true;
                        this.selfItemList.refresh();
                        let arr = rankVo.rank_list;
                        this.selfItemList.array = arr;
                        if (this.selfItemList.array.length == 0) {
                            this.lblNotSelf.visible = true;
                        }
                        else {
                            this.lblNotSelf.visible = false;
                            for (let i = 0; i < arr.length; i++) {
                                if (arr[i].idx == this._model.my_self_idx) {
                                    itemVo = arr[i];
                                    break;
                                }
                            }
                        }
                        item.initView(itemVo);
                    }
                    break;
                case 3:
                    {
                        let item = this.boxItem.getChildByName("man");
                        if (!item) {
                            this.boxItem.removeChildren(0, this.boxItem.numChildren - 1);
                            item = new mvc.UnitManRankItem();
                            item.name = "man";
                            this.boxItem.addChild(item);
                        }
                        this.grp_man.visible = true;
                        let arr = this.getListData2();
                        this.manItemList.array = arr;
                        if (this.manItemList.array.length == 0) {
                            this.lblNotMan.visible = true;
                        }
                        else {
                            this.lblNotMan.visible = false;
                        }
                        let vo = mvc.guildHuntingModel.findSelfRankVo(arr, rankVo.myValue);
                        item.initView(vo);
                    }
                    break;
            }
        }
        getListData(type) {
            let cfg = mvc.rankModel.getItemByCnfId(type);
            let showCount = cfg.showCount;
            this.manItemList.refresh();
            let listIdx = [];
            let itemList = mvc.rankModel.getRankItemsVo(type, showCount);
            let rank_cfg = sg.dbmgr.get("rank_ranklist", type);
            for (let man_item of itemList) {
                listIdx.push(man_item.idx);
            }
            for (let i = 1; i < 4; i++) {
                if (listIdx.indexOf(i) == -1) {
                    let topRankVo = new mvc.RankItemVo;
                    topRankVo["idx"] = i;
                    topRankVo["integral"] = rank_cfg.fCondition[i - 1];
                    itemList.unshift(topRankVo);
                }
            }
            itemList.sort((a, b) => {
                return a.idx - b.idx;
            });
            return itemList;
        }
        getListData2() {
            let type = mvc.RankConst.RANK_TYPE.guild_hunting_single;
            let cfg = mvc.rankModel.getItemByCnfId(type);
            let showCount = cfg.showCount;
            this.manItemList.refresh();
            let itemList = mvc.rankModel.getRankItemsVo(type, showCount);
            let selfSvrList = [];
            let mySvrId = mvc.roleModel.roleInfo.serverId;
            itemList.sort((a, b) => {
                return a.idx - b.idx;
            });
            for (let i = 0; i < itemList.length; i++) {
                let data = itemList[i];
                if (data.sId == mySvrId) {
                    let vo = new mvc.RankItemVo();
                    vo.pid = data.pid;
                    vo.pName = data.pName;
                    vo.sex = data.sex;
                    vo.sId = data.sId;
                    vo.level = data.level;
                    vo.guild_id = data.guild_id;
                    vo.guild_name = data.guild_name;
                    vo.headIcon = data.headIcon;
                    vo.headFrame = data.headFrame;
                    vo.titleId = data.titleId;
                    vo.isRobot = data.isRobot;
                    vo._value = data._value;
                    selfSvrList.push(vo);
                    vo.idx = selfSvrList.length;
                }
            }
            return selfSvrList;
        }
        _onManRankClick() {
            this._type = 0;
            this.btnManRank.selected = true;
            this.btnGuildRank.selected = this.btnSelfRank.selected = this.btnSvrRank.selected = false;
            mvc.rankCtrl.reqRankInfo(mvc.RankConst.RANK_TYPE.guild_hunting_single);
        }
        _onGuildRankClick() {
            this._type = 1;
            this.btnManRank.selected = this.btnSelfRank.selected = this.btnSvrRank.selected = false;
            this.btnGuildRank.selected = true;
            mvc.rankCtrl.reqRankInfo(mvc.RankConst.RANK_TYPE.guild_hunting);
        }
        _onSelfRankClick() {
            this._type = 2;
            this.btnManRank.selected = this.btnGuildRank.selected = this.btnSvrRank.selected = false;
            this.btnSelfRank.selected = true;
            mvc.guildHuntingCtrl.reqGHRankInside();
        }
        _onSvrRankClick() {
            this._type = 3;
            this.btnManRank.selected = this.btnGuildRank.selected = this.btnSelfRank.selected = false;
            this.btnSvrRank.selected = true;
            mvc.rankCtrl.reqRankInfo(mvc.RankConst.RANK_TYPE.guild_hunting_single);
        }
    }
    mvc.PopGHRank = PopGHRank;
})(mvc || (mvc = {}));

