(function (mvc) {
    class PopGHRecord extends ui.view.guildHunting.pop_ghRecordUI {
        initView(data) {
            this._data = data;
            this._model = mvc.guildHuntingModel;
            this._ctrl = mvc.guildHuntingCtrl;
            this._type = 1;
        }
        initSendMsg() {
            this._ctrl.reqGHBlockingRec();
        }
        initModelEvent() {
            this.bindModelEvent(mvc.guildHuntingModel, mvc.GuildHuntingConst.EVT.UPDATE_BLOCKINGREC, this.updateView);
        }
        initCtrlEvent() {
            this.listRecord.vScrollBarSkin = "";
            this.listRecord.itemRender = mvc.UnitGHRecordItem;
            this.listRecord.renderHandler = this.createHandler(this, this._onRenderItem, null, false);
            this.tab.selectHandler = this.createHandler(this, this._onSelecteTab, null, false);
        }
        updateData(types, ...args) { }
        onAwake() {
            super.onAwake();
            this.lblBlank.text = sg.translate("暂无记录");
        }
        onEnable() {
            super.onEnable();
            this.tab.selectedIndex = this._type - 1;
        }
        updateView() {
            let rec_list = this._model.rec;
            if (!rec_list)
                return;
            if (rec_list.length > 0) {
                this.listRecord.visible = true;
                let rec_tot_list = [];
                let rec_obj = {};
                for (let i = 0; i < rec_list.length; i++) {
                    let b = false;
                    switch (this._type) {
                        case 2:
                            if (rec_list[i].result == 1 || rec_list[i].result == 2)
                                b = true;
                            break;
                        case 1:
                            if (rec_list[i].result == 3 || rec_list[i].result == 4)
                                b = true;
                            break;
                    }
                    if (!b)
                        continue;
                    rec_obj = {
                        rec_list: rec_list[i],
                    };
                    rec_tot_list.push(rec_obj);
                }
                this.listRecord.array = rec_tot_list;
                this.lblBlank.visible = rec_tot_list.length <= 0;
            }
            else {
                this.lblBlank.visible = true;
                this.listRecord.visible = false;
            }
            this.lblBlank.text = this._type == 1 ? sg.translate("暂无防守记录") : sg.translate("暂无阻击记录");
        }
        _onSelecteTab(index) {
            this._type = index + 1;
            this.updateView();
        }
        _onRenderItem(cell, index) {
            cell.initView(cell.dataSource);
        }
    }
    mvc.PopGHRecord = PopGHRecord;
})(mvc || (mvc = {}));

