var mvc;
(function (mvc) {
    class PopHeavenShow extends ui.view.heaven.pop_heavenShowUI {
        initView(info, id) {
            this._info = info;
            this._id = id;
        }
        initSendMsg() {
        }
        initModelEvent() {
            this.bindModelEvent(mvc.heavenModel, mvc.HeavenConst.EVT.CLICK_LIKE, this._updateLike);
            this.bindModelEvent(mvc.heavenModel, mvc.HeavenConst.EVT.UPDATE_RECORD_RED, this._updateRecordRed);
        }
        initCtrlEvent() {
            this.on(Laya.Event.CLICK, this, this._onClick);
        }
        updateData(types, args) {
            this._info = args[0];
            this._id = args[1];
            this._updateView();
        }
        onAwake() {
            super.onAwake();
            this.redTips.id = mvc.REDOT_ID.HEAVEN_LIKE;
        }
        onEnable() {
            super.onEnable();
            this._model = mvc.heavenModel;
            this._updateView();
        }
        onJumpInit(jumpParams) {
        }
        onDisable() {
            super.onDisable();
        }
        onClosed() {
            super.onClosed();
        }
        _updateLike(like) {
            this.lblNum.text = "" + like;
            let max = mgr.toolsMgr.getGlobalVoById("heaven_likes_num", 1);
            this.btn.disabled = mvc.heavenModel.likeCount >= max;
        }
        _updateView() {
            this.imgNull.visible = this.boxRole.visible = this.lblLastTime.visible = false;
            this.btn.visible = this.lblNum.visible = false;
            if (this._info) {
                let max = mgr.toolsMgr.getGlobalVoById("heaven_likes_num", 1);
                if (this._info.player_id == 0) {
                    this.imgNull.visible = true;
                    this.btn.visible = this.lblNum.visible = false;
                }
                else {
                    this.boxRole.visible = true;
                    this.lblLastTime.visible = true;
                    this.btn.visible = this.lblNum.visible = true;
                    this.btn.disabled = mvc.heavenModel.likeCount >= max;
                    this.lblNum.text = "" + this._info.like;
                    let head = this._info.head;
                    if (head) {
                        this.lblMasterName.text = `[s${this._info.head.svr_id}]${this._info.head.name}`;
                        this.lblGuildName.text = this._info.head.guild_name;
                        this._showRoleModel(head);
                    }
                    this.stopTimer(this._offsetTime);
                    if (this._info.end_time > sg.time.getSecondTime()) {
                        this._targetTime = this._info.end_time;
                        this.repeats(1000, this._offsetTime, true);
                    }
                    else {
                        this.lblLastTime.text = "";
                    }
                }
            }
            let cfg = sg.dbmgr.get("heaven_palaceLevel", this._id);
            if (cfg) {
                mgr.icon.drawTexture(mgr.icon.getIconPath(cfg.title), this.imgTitle2);
                let cfg2 = sg.dbmgr.get("heaven_position", cfg.position[0]);
                if (cfg2) {
                    this.lblAccess.text = cfg2.conditionDesc;
                    this.title.updateTitle(cfg2.title);
                }
            }
            this._updateRecordRed();
        }
        _updateRecordRed() {
            this.unitRedotTitle.visible = this._info.player_id && mvc.heavenModel.canLike(this._id);
        }
        _showRoleModel(info) {
            let skinCfg = sg.dbmgr.get("fashion_fashion", info.skin_id);
            let role = skinCfg.avatar[info.sex];
            this.roleModel.changeShowMode(false, role);
            this.roleModel.loadedHandle = () => {
                this.roleModel.play("stand", true);
            };
            this.roleModel.loadRole(role, "PopHeavenShow");
        }
        _offsetTime() {
            let lastTime = this._targetTime - sg.time.getSecondTime();
            if (lastTime > 0) {
                this.lblLastTime.text = sg.translate("展示倒计时：") + sg.time.formatTimeStrT("F10", lastTime);
            }
            else {
                this.lblLastTime.text = "";
                if (this._info)
                    mvc.heavenCtrl.reqHeavenRoomInfo(this._info.id);
            }
        }
        _onClick(e) {
            switch (e.target) {
                case this.btn:
                    {
                        if (this._info) {
                            if (!this._info.id) {
                                sg.loge(`天庭的职位ID找不到,info:${this._info},id:${this._info.id}`);
                                return;
                            }
                            let max = mgr.toolsMgr.getGlobalVoById("heaven_likes_num", 1);
                            if (this._model.likeCount >= max) {
                                sg.uimgr.showNotice(sg.translate("今日点赞次数已用完"));
                                return;
                            }
                            mvc.heavenCtrl.reqHeavenLike(this._info.id);
                        }
                    }
                    break;
                case this.btnTips:
                    {
                        if (this._info) {
                            let cfg2 = sg.dbmgr.get("heaven_position", this._info.id);
                            if (cfg2) {
                                if (!cfg2.title) {
                                    sg.uimgr.showNotice(cfg2.conditionDesc);
                                    return;
                                }
                                sg.uimgr.showUI("pop_heavenTips", this._info.id);
                            }
                        }
                    }
                    break;
                case this.boxClickRole:
                    {
                        if (this._info && this._info.head && this._info.head.player_id > 0 && this._info.head.player_id != mvc.roleModel.roleInfo.playerId)
                            mvc.mainCtrl.reqPlayerInfo(this._info.head.player_id);
                    }
                    break;
                case this.btnRecord:
                    {
                        if (this._info) {
                            if (!this._info.id) {
                                sg.loge(`天庭的职位ID找不到,info:${this._info},id:${this._info.id}`);
                                return;
                            }
                            mvc.heavenCtrl.reqHeavenRecordRoomInfo(this._id);
                        }
                    }
                    break;
            }
        }
    }
    mvc.PopHeavenShow = PopHeavenShow;
})(mvc || (mvc = {}));

