(function (mvc) {
    class SysHeaven extends ui.view.heaven.sys_heavenUI {
        constructor() {
            super(...arguments);
            this._selectIndex = 0;
        }
        initView() {
            this._selectIndex = 0;
        }
        initSendMsg() {
            mvc.heavenCtrl.reqHeavenInfo();
            mvc.boundlessWorldCtrl.updateReq();
        }
        initModelEvent() {
            this.bindModelEvent(mvc.heavenModel, mvc.HeavenConst.EVT.UPDATE_INFO, this._updateView);
        }
        initCtrlEvent() {
            this.vScroBar.on(Laya.Event.CHANGE, this, this._move);
            this.list.itemRender = mvc.UnitHeavenItem;
            this.btnBoundlessWorld.on(Laya.Event.CLICK, this, this._onbtnBoundlessWorld);
            this.btnHeaven.on(Laya.Event.CLICK, this, this._onbtnHeaven);
        }
        onAwake() {
            super.onAwake();
            this.setContentSize(mvc.HeavenConst.CONST.VIEW_WIDTH, this.height, this.boxContent);
            this.setContentSize(mvc.HeavenConst.CONST.VIEW_WIDTH, this.height, this.boxContent2);
        }
        onEnable() {
            super.onEnable();
            this.vScroBar.target = this.boxContent2;
            this.vScroBar.hide = true;
            this.startY = this.vScroBar.value;
            this._model = mvc.heavenModel;
            this._initListDatas();
            this._updateInfoBox();
            this.redHeaven.id = mvc.REDOT_ID.HEAVEN_MAIN;
            this.redBoundlessWorld.id = mvc.REDOT_ID.BOUNDLESS_WORLD;
        }
        _initListDatas() {
            let cfgs = sg.dbmgr.getDB("heaven_palaceLevel", true);
            cfgs.sort(function (a, b) {
                return a.order - b.order;
            });
            this.item1.dataSource = cfgs.shift();
            this.list.array = cfgs;
            this.list.height = Math.ceil(this.list.array.length / 2) * (mvc.HeavenConst.CONST.ITEM_HEIGHT + this.list.spaceY) - this.list.spaceY;
            this._addBg(0);
        }
        _addBg(height) {
            if (height < this.list.y + this.list.height) {
                let img = new Laya.Image();
                mgr.icon.drawTexture("ui/heaven/img_heaven_bg.jpg", img);
                img.y = height;
                img.height = 1128;
                this.boxContent.addChild(img);
                return this._addBg(img.y + img.height);
            }
            else {
                this.vScroBar.setScroll(0, (this.list.y + this.list.height) - this.height, this.vScroBar.value);
                return;
            }
        }
        _updateView() {
            let cfgs = sg.dbmgr.getDB("heaven_palaceLevel", true);
            cfgs.sort(function (a, b) {
                return a.order - b.order;
            });
            this.item1.dataSource = cfgs.shift();
            this.list.refresh();
        }
        _updateInfoBox() {
            this.boxHeaven.visible = this._selectIndex == 0;
            this.gvgWorld.visible = this._selectIndex == 1;
            this.btnBoundlessWorld.selected = this.gvgWorld.visible;
            this.btnHeaven.selected = this.boxHeaven.visible;
        }
        _move(d) {
            let offseValue = this.vScroBar.value - this.startY;
            let rect = this.boxContent.scrollRect;
            if (rect) {
                rect.y += offseValue;
                this.boxContent.scrollRect = rect;
            }
            let rect2 = this.boxContent2.scrollRect;
            if (rect2) {
                rect2.y += offseValue * 1.15;
                this.boxContent2.scrollRect = rect2;
            }
            this.startY = this.vScroBar.value;
        }
        setContentSize(width, height, box) {
            var content = box;
            content.width = width;
            content.height = height;
            content[`scrollRect`] || (content.scrollRect = Laya.Rectangle.create());
            content.scrollRect.setTo(0, 0, width, height);
        }
        _onbtnBoundlessWorld(e) {
            this._selectIndex = 1;
            this._updateInfoBox();
        }
        _onbtnHeaven(e) {
            this._selectIndex = 0;
            this._updateInfoBox();
        }
    }
    mvc.SysHeaven = SysHeaven;
})(mvc || (mvc = {}));

