(function (mvc) {
    class HeavenCtrl extends sg.CtrlBase {
        initCtrl() {
            this._model = mvc.heavenModel;
        }
        registerMsg() {
            this.onMsg(Proto.HEAVEN_INFO, this._onMsgHeavenInfo);
            this.onMsg(Proto.HEAVEN_ROOM_INFO, this._onMsgHeavenRoomInfo);
            this.onMsg(Proto.HEAVEN_LIKE, this._onMsgHeavenLike);
            this.onMsg(Proto.HEAVEN_RECORD_INFO, this._onMsgHeavenRecordInfo);
            this.onMsg(Proto.HEAVEN_RECORD_ROOM_INFO, this._onMsgHeavenRecordRoomInfo);
            this.onMsg(Proto.HEAVEN_RECORD_LIKE, this._onMsgHeavenRecordLike);
            this.onMsg(Proto.HEAVEN_RECORD_ROUND, this._onMsgHeavenRecordNotify);
        }
        reqHeavenInfo() {
            let msg = this.createProto(Proto.heaven_info_request);
            this.sendMsg(Proto.HEAVEN_INFO, msg);
        }
        _onMsgHeavenInfo(data) {
            this._model.setHeavens(data.like, data.heavens);
        }
        reqHeavenRoomInfo(id) {
            let msg = this.createProto(Proto.heaven_room_info_request);
            msg.id = id;
            this.sendMsg(Proto.HEAVEN_ROOM_INFO, msg);
        }
        _onMsgHeavenRoomInfo(data) {
            this._model.showHeavenRoom(data);
        }
        reqHeavenLike(id) {
            let msg = this.createProto(Proto.heaven_like_request);
            msg.id = id;
            this.sendMsg(Proto.HEAVEN_LIKE, msg);
        }
        _onMsgHeavenLike(data) {
            this._model.likeCount = data.like;
            sg.uimgr.showUI("pop_getReward", sg.translate("恭喜获得"), data.reward);
            this._model.fireEvent(mvc.HeavenConst.EVT.CLICK_LIKE, data.like);
            mgr.redotMgr.check(mvc.REDOT_ID.HEAVEN_LIKE);
        }
        reqHeavenRecordInfo() {
            let req = this.createProto(Proto.heaven_record_info_request);
            this.sendMsg(Proto.HEAVEN_RECORD_INFO, req);
        }
        _onMsgHeavenRecordInfo(data) {
            this._model.palaceRound = data.palace_round;
            this._model.likeIds = data.like_ids;
            mgr.redotMgr.check(mvc.REDOT_ID.HEAVEN_RECORD);
        }
        reqHeavenRecordRoomInfo(id) {
            let req = this.createProto(Proto.heaven_record_room_info_request);
            req.id = id;
            this.sendMsg(Proto.HEAVEN_RECORD_ROOM_INFO, req);
        }
        _onMsgHeavenRecordRoomInfo(data) {
            sg.uimgr.showUI("pop_heavenRecord", data.id, data.players);
        }
        reqHeavenRecordLike(id) {
            let req = this.createProto(Proto.heaven_record_like_request);
            req.id = id;
            this.sendMsg(Proto.HEAVEN_RECORD_LIKE, req);
        }
        _onMsgHeavenRecordLike(data) {
            this._model.likeIds = data.like_ids;
            sg.uimgr.showUI("pop_getReward", sg.translate("恭喜获得"), data.reward);
            this._model.fireEvent(mvc.HeavenConst.EVT.UPDATE_RECORD_VIEW);
            this._model.fireEvent(mvc.HeavenConst.EVT.UPDATE_INFO);
            this._model.fireEvent(mvc.HeavenConst.EVT.UPDATE_RECORD_RED);
            mgr.redotMgr.check(mvc.REDOT_ID.HEAVEN_RECORD);
        }
        _onMsgHeavenRecordNotify(data) {
            this.reqHeavenRecordInfo();
        }
    }
    mvc.HeavenCtrl = HeavenCtrl;
})(mvc || (mvc = {}));

