            arr.sort(function (a, b) {
                if (a.position == b.position) {
                    return b.level - a.level;
                }
                return a.position - b.position;
            });
            this.list.array = arr;
            this.lblNum1.text = `${this._model.getPositionNum(arr, 1)}/1`;
            let max = mgr.toolsMgr.getGlobalVoById("guild_post", 1);
