            let unit = this.getChildByName("Operate");
            if (!unit) {
                unit = new mvc.UnitGuildMemOperate();
                unit.name = "Operate";
                this.addChild(unit);
            }
            unit.visible = true;
            unit.setData(vo);
            unit.x = pos.x - 50;
            unit.y = pos.y;
