            let cost = mgr.toolsMgr.getGlobalVoById("guild_rename", 1);
            this.lblCostNum1.text = cost[0][1];
            this.lblCostNum1.color = mgr.toolsMgr.checkConsume(cost, false) ? mvc.COLOR.GREEN : mvc.COLOR.RED;
            mgr.icon.drawTexture(mgr.icon.getIconPath(mgr.toolsMgr.getIconById(cost[0][0])), this.sprCostIcon1);
