(function (mvc) {
    class UnitGuildHelpItem extends ui.view.guild.unit_helpListItemUI {
        initView(vo) {
            this._vo = vo;
        }
        initSendMsg() {
        }
        initModelEvent() {
        }
        initCtrlEvent() {
            this.on(Laya.Event.CLICK, this, this._onClick);
            this.divDesc.style.width = 350;
            this.divDesc.style.fontSize = 22;
        }
        updateData(types, ...args) { }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            if (this._vo)
                this.setData(this._vo);
        }
        onDisable() {
            super.onDisable();
        }
        setData(data) {
            if (!data)
                return;
            this._vo = data;
            let cfg = sg.dbmgr.get("guild_guildHelp", this._vo.type);
            if (cfg) {
                let icon = cfg.icon;
                let scale = 1, offx = 0, offy = 10;
                this.btnHelp.label = cfg.button;
                this.btnHelp.disabled = false;
                let str = "";
                let _const = mvc.GuildConst.HELP_TYPE;
                switch (this._vo.type) {
                    case _const.DUNGEON_EQUIP:
                        {
                            let cfg2 = sg.dbmgr.get("dungeonEquipment_dungeonEquipment", this._vo.data[1]);
                            if (cfg2)
                                str = mvc.mainModel.analyzeNotic(cfg.color, [[this._vo.name], [cfg2.starLevel], [cfg2.rewardName]]);
                        }
                        break;
                    case 2:
                        {
                        }
                        break;
                    case _const.SUIT_FURNACE:
                    case _const.EGG_ACC:
                    case _const.MINE_SWEEP:
                    case _const.GhostHunt:
                        {
                            str = mvc.mainModel.analyzeNotic(cfg.color, [[this._vo.name]]);
                        }
                        break;
                    case _const.MANOR:
                        {
                            str = mvc.mainModel.analyzeNotic(cfg.color, [[this._vo.name]]);
                        }
                        break;
                    case _const.BREAK:
                        {
                            str = mvc.mainModel.analyzeNotic(cfg.color, [[this._vo.name], [4, this._vo.data[1]]]);
                        }
                        break;
                    case _const.BLOOD_GRADE_UP:
                        {
                            let arr = sg.dbmgr.getArray("blood_lock", { type: this._vo.data[1] });
                            let name = "";
                            if (arr && arr[0]) {
                                name = arr[0].bloodName;
                            }
                            str = mvc.mainModel.analyzeNotic(cfg.color, [[this._vo.name], [name]]);
                        }
                        break;
                    case _const.LATTICE_TRAP:
                        {
                            str = mvc.mainModel.analyzeNotic(cfg.color, [[this._vo.name]]);
                        }
                        break;
                    case _const.LATTICE_MONSTER:
                        {
                            let cfg2 = sg.dbmgr.get("monster_monster", this._vo.data[1]);
                            if (cfg2)
                                str = mvc.mainModel.analyzeNotic(cfg.color, [[this._vo.name], [cfg2.name]]);
                        }
                        break;
                    case _const.PLANT_BOSS:
                        {
                            let cfg2 = sg.dbmgr.get("monster_monster", this._vo.data[1]);
                            if (cfg2)
                                str = mvc.mainModel.analyzeNotic(cfg.color, [[this._vo.name], [cfg2.name]]);
                        }
                        break;
                    case _const.RULE_WORLD:
                        {
                            let cfg2 = sg.dbmgr.getUnique("rule_worldUp", this._vo.data[1], this._vo.data[0]);
                            if (cfg2)
                                str = mvc.mainModel.analyzeNotic(cfg.color, [[this._vo.name], [cfg2.ruleName]]);
                        }
                        break;
                    case _const.FASHION_SHARE:
                        let shinConfig = sg.dbmgr.get("fashion_fashion", this._vo.data[0]);
                        if (shinConfig) {
                            str = mvc.mainModel.analyzeNotic(cfg.color, [[this._vo.name], [shinConfig.name]]);
                            icon = mgr.toolsMgr.getIconById(shinConfig.consume[0][0]);
                            scale = 1.2;
                            offx = 5;
                            offy = 15;
                        }
                        break;
                    case _const.GOD_RECYCLE:
                        {
                            let cfg2 = sg.dbmgr.getArray("god_godRecovery", { world: this._vo.data[1], level: this._vo.data[0] })[0];
                            if (cfg2)
                                str = mvc.mainModel.analyzeNotic(cfg.color, [[this._vo.name], [cfg2.ruleName]]);
                        }
                        break;
                    case _const.DSQQ_SPECIALTY_SPEED:
                        str = str = mvc.mainModel.analyzeNotic(cfg.color, [[this._vo.name]]);
                        break;
                }
                mgr.icon.drawTexture(mgr.icon.getIconPath(icon), this.imgType);
                this.imgType.scaleX = this.imgType.scaleY = scale;
                this.imgType.x = offx;
                this.imgType.y = offy;
                if (cfg.helpMem) {
                    this.cellProgress.visible = true;
                    this.cellProgress.updateView(this._vo.process / cfg.helpMem, cfg.helpMem);
                }
                else {
                    this.cellProgress.visible = false;
                }
                this.divDesc.innerHTML = str;
                this.btnHelp.visible = !mvc.roleModel.isSelf(this._vo.player_id);
                if (this._vo.checkPlayerHelp(mvc.roleModel.roleInfo.playerId, this._vo.data)) {
                    this.btnHelp.label = sg.translate("已协助");
                    this.btnHelp.disabled = true;
                }
            }
        }
        _onClick(e) {
            switch (e.target) {
                case this.btnHelp:
                    {
                        let vo = this._vo;
                        if (vo) {
                            if (vo.player_id == mvc.roleModel.roleInfo.playerId) {
                                sg.uimgr.showNotice(sg.translate("无法帮助自己"));
                                return;
                            }
                            if (this._vo.type == mvc.GuildConst.HELP_TYPE.FASHION_SHARE) {
                                let shinConfig = sg.dbmgr.get("fashion_fashion", this._vo.data[0]);
                                if (shinConfig && mvc.equipModel.vo.skinLevelMap.has(shinConfig.id)) {
                                    sg.uimgr.showNotice(sg.translate("您已拥有该时装！"));
                                    return;
                                }
                                if (mvc.equipModel.vo.tryOnSkinLimit()) {
                                    sg.uimgr.showNotice(sg.translate("当前你已拥有试穿资格，机会留给别人吧~"));
                                    return;
                                }
                            }
                            let cfg = sg.dbmgr.get("guild_guildHelp", vo.type);
                            if (cfg) {
                                let isSer = true;
                                if (vo.type == mvc.GuildConst.HELP_TYPE.BREAK) {
                                    let max = mgr.toolsMgr.getGlobalVoById("brokenboss_to_help_time", 1);
                                    if (mvc.roleModel.helpTime >= max) {
                                        sg.uimgr.showNotice(sg.translate("您已达到今日帮助上限！"));
                                        isSer = false;
                                    }
                                }
                                else {
                                    if (cfg.helpMem > 0) {
                                        isSer = cfg.helpMem >= vo.process;
                                        if (!isSer) {
                                            sg.uimgr.showNotice(sg.translate("帮助已满"));
                                        }
                                    }
                                }
                                if (isSer) {
                                    mvc.guildCtrl.reqGuildHelp(vo.player_id, vo.type, vo.data);
                                }
                            }
                        }
                    }
                    break;
            }
        }
    }
    mvc.UnitGuildHelpItem = UnitGuildHelpItem;
})(mvc || (mvc = {}));

