var mvc;
(function (mvc) {
    class UnitGuildMemOperate extends ui.view.guild.unit_memOperateUI {
        initView(vo) {
            this._vo = vo;
        }
        initSendMsg() {
        }
        initModelEvent() {
        }
        initCtrlEvent() {
            this.list.selectEnable = true;
            this.list.selectHandler = this.createHandler(this, this._onSelectList, null, false);
            this.list.renderHandler = this.createHandler(this, this._onRenderList, null, false);
        }
        updateData(types, ...args) { }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            if (this._vo)
                this.setData(this._vo);
        }
        onJumpInit(jumpParams) {
        }
        onDisable() {
            super.onDisable();
        }
        onClosed() {
            super.onClosed();
        }
        setData(data) {
            if (!data)
                return;
            this._vo = data;
            let myGuildInfo = mvc.guildModel.playerVo;
            if (this._vo && myGuildInfo) {
                let arr = [];
                let cfg = sg.dbmgr.get("guild_guildPost", myGuildInfo.position);
                let playerId = mvc.roleModel.roleInfo.playerId;
                if (cfg) {
                    if (playerId != this._vo.player_id) {
                        arr.push(1);
                        if (cfg.appoint && myGuildInfo.position < this._vo.position)
                            arr.push(2);
                        if (cfg.kickout && myGuildInfo.position < this._vo.position)
                            arr.push(3);
                        if (cfg.transfer && myGuildInfo.position < this._vo.position)
                            arr.push(4);
                    }
                    else {
                        if (cfg.quit)
                            arr.push(6);
                        if (cfg.dissolve)
                            arr.push(5);
                    }
                }
                arr.sort(function (a, b) {
                    return a - b;
                });
                this.list.array = arr;
            }
        }
        _onSelectList(index) {
            let data = this.list.array[index];
            let playerId = mvc.roleModel.roleInfo.playerId;
            switch (data) {
                case 1:
                    {
                        if (playerId == this._vo.player_id)
                            return;
                        mvc.mainCtrl.reqPlayerInfo(this._vo.player_id);
                    }
                    break;
                case 2:
                    {
                        if (playerId == this._vo.player_id)
                            return;
                        if (this._vo.position == 3) {
                            mvc.guildCtrl.reqGuildAppoint(this._vo.player_id, 2);
                        }
                        else {
                            mvc.guildCtrl.reqGuildAppoint(this._vo.player_id, 3);
                        }
                    }
                    break;
                case 3:
                    {
                        if (playerId == this._vo.player_id)
                            return;
                        if (this._vo)
                            mvc.guildCtrl.reqGuildKickMember(this._vo.player_id);
                    }
                    break;
                case 4:
                    {
                        if (playerId == this._vo.player_id)
                            return;
                        if (this._vo) {
                            let vo = this._vo;
                            let v1 = this._vo.name;
                            let str = StringEx.format(sg.translate("确定将仙盟禅让给${v1}吗?"), {"v1":v1});
                            sg.uimgr.showConfirm({
                                content: str, enterFunc: () => {
                                    mvc.guildCtrl.reqGuildTransfer(vo.player_id);
                                }
                            });
                        }
                    }
                    break;
                case 5:
                    {
                        let str = "";
                        str = StringEx.format(sg.translate("仙盟解散后不可恢复，确定解散吗?"));
                        sg.uimgr.showConfirm({
                            enterFunc: () => {
                                mvc.guildCtrl.reqGuildDisband();
                                sg.uimgr.closeUI("pop_guildMain");
                            }, content: str, btnCancelVisible: true,
                        });
                    }
                    break;
                case 6:
                    {
                        let cd = mgr.toolsMgr.getGlobalVoById("guild_quit_cd", 1);
                        let str = "";
                        let v1 = sg.time.formatTimeStrT("F10", cd);
                        str = StringEx.format(sg.translate("退出仙盟${v1}后才能加入仙盟，确定退出吗?"), {"v1":v1});
                        sg.uimgr.showConfirm({
                            enterFunc: () => {
                                mvc.guildCtrl.reqGuildQuit();
                                sg.uimgr.closeUI("pop_guildMain");
                            }, content: str, btnCancelVisible: true,
                        });
                    }
                    break;
            }
        }
        _onRenderList(cell, index) {
            if (!cell.dataSource)
                return;
            switch (cell.dataSource) {
                case 1:
                    {
                        cell.label = sg.translate("查看信息");
                    }
                    break;
                case 2:
                    {
                        if (this._vo.position < 3)
                            cell.label = sg.translate("撤销职务");
                        else
                            cell.label = sg.translate("任命职务");
                    }
                    break;
                case 3:
                    {
                        cell.label = sg.translate("请离仙盟");
                    }
                    break;
                case 4:
                    {
                        cell.label = sg.translate("禅让仙盟");
                    }
                    break;
                case 5:
                    {
                        cell.label = sg.translate("解散仙盟");
                    }
                    break;
                case 6:
                    {
                        cell.label = sg.translate("退出仙盟");
                    }
                    break;
            }
        }
    }
    mvc.UnitGuildMemOperate = UnitGuildMemOperate;
})(mvc || (mvc = {}));

