var mvc;
(function (mvc) {
    class HeadFrameModel extends sg.ModelBase {
        initModel() {
            this.framMap = {};
            this.framCfgMap = {};
            this._activeNumMap = {};
            this.isNewIds = new Array();
        }
        registerEvents() {
            let type = mvc.HeadFrameConst.FramType;
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.ROLE_CHAT, this.framRed.bind(this, type.CHAT), this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.ROLE_HEAD, this.framRed.bind(this, type.HEAD), this);
        }
        getActiveNum(type) {
            return this._activeNumMap[type] == undefined ? 0 : this._activeNumMap[type];
        }
        addActiveFram(type) {
            let num = this.getActiveNum(type);
            this._activeNumMap[type] = ++num;
        }
        getCfg(type, id) {
            let str = type == mvc.HeadFrameConst.FramType.CHAT ? "fashion_chatFrame" : "fashion_headFrame";
            return sg.dbmgr.get(str, id);
        }
        getLvCfg(type, id) {
            let str = type == mvc.HeadFrameConst.FramType.CHAT ? "fashion_chatFrameLevel" : "fashion_headFrameLevel";
            return sg.dbmgr.get(str, id);
        }
        getFrameCfgs(type, isSort = false) {
            let id = this.getEquipFrameId(type);
            if (!this.framCfgMap[type]) {
                let arr = [];
                let str = type == mvc.HeadFrameConst.FramType.CHAT ? "fashion_chatFrame" : "fashion_headFrame";
                let cfgs = sg.dbmgr.getDB(str);
                for (let key in cfgs) {
                    let time = new Date(cfgs[key].timeShow).getTime();
                    let passTime = sg.time.getTime() - time >= 0;
                    if (mgr.conditionMgr.check(cfgs[key].showlock, false) && mgr.gplatform.checkChannel(cfgs[key].condition) && passTime) {
                        arr.push(cfgs[key]);
                    }
                }
                this.framCfgMap[type] = arr;
            }
            if (isSort) {
                return this.framCfgMap[type].sort((a, b) => {
                    if (a.id == id) {
                        return -1;
                    }
                    if (b.id == id) {
                        return 1;
                    }
                    return a.id - b.id;
                });
            }
            return this.framCfgMap[type];
        }
        getFrameVo(type, id) {
            let map = this.framMap[type];
            if (map) {
                return map[id];
            }
            return null;
        }
        updateArrayFrame(type, framArr) {
            let map = this.framMap[type] || {};
            this.framMap[type] = map;
            if (framArr) {
                for (let v of framArr) {
                    if (v) {
                        this.addFrame(type, v);
                    }
                }
            }
        }
        addFrame(type, v, isNew = false) {
            let map = this.framMap[type] || {};
            this.framMap[type] = map;
            if (v) {
                let vo = map[v.id] || new mvc.FramBaseVo();
                if (!map[v.id]) {
                    this.addActiveFram(type);
                }
                vo.cloneProtoData(v);
                vo.framType = type;
                map[v.id] = vo;
            }
            if (isNew) {
                this.isNewIds.push(v.id);
            }
        }
        getEquipFrameId(type) {
            if (type == mvc.HeadFrameConst.FramType.CHAT) {
                return mvc.roleModel.roleInfo["chat_frame_id"] || 142001;
            }
            else {
                return mvc.roleModel.roleInfo.head_frame_id || 143001;
            }
        }
        getFrameAttributeById(type, id) {
            let baseProp = [];
            let cfg = this.getCfg(type, id);
            if (!cfg)
                return baseProp;
            baseProp = mvc.PropertyModel.prasePropByCfg(cfg.prop);
            if (cfg.lvup == 1) {
                let vo = this.getFrameVo(type, id);
                if (vo) {
                    let addLevel = vo.level - 1;
                    if (addLevel > 0) {
                        let levelCfg = this.getLvCfg(type, id);
                        let addProp = mvc.PropertyModel.prasePropByCfg(levelCfg.prop, addLevel);
                        baseProp = mvc.PropertyModel.getMixPropertysMerge(baseProp, addProp, true);
                    }
                }
            }
            return baseProp;
        }
        getAllFrameAttribute(type) {
            let baseProp = [];
            let map = this.framMap[type];
            if (map) {
                for (let key in map) {
                    let vo = map[key];
                    let addProp = this.getFrameAttributeById(type, vo.id);
                    baseProp = mvc.PropertyModel.getMixPropertysMerge(baseProp, addProp, true);
                }
            }
            return baseProp;
        }
        isCanActive(type, id) {
            if (this.getFrameVo(type, id)) {
                return 0;
            }
            else {
                let cfg = this.getCfg(type, id);
                if (cfg.unlock && mgr.conditionMgr.check(cfg.unlock, false)) {
                    return 1;
                }
                else if (cfg.consume && mgr.toolsMgr.checkConsume(cfg.consume, false)) {
                    return 1;
                }
                return 0;
            }
        }
        isCanUpLv(type, id) {
            let vo = this.getFrameVo(type, id);
            if (vo && vo.getCfg().lvup) {
                let cfgLv = this.getLvCfg(type, id);
                if (cfgLv && cfgLv.consume && mgr.toolsMgr.checkConsume(cfgLv.consume, false)) {
                    return 1;
                }
            }
            return 0;
        }
        getFramRedById(type, id) {
            if (this.isCanActive(type, id)) {
                return 1;
            }
            if (this.isCanUpLv(type, id)) {
                return 1;
            }
            if (this.isNewIds.indexOf(id) != -1) {
                return 1;
            }
            return 0;
        }
        framRed(type) {
            let str = type == mvc.HeadFrameConst.FramType.CHAT ? "fashion_chatFrame" : "fashion_headFrame";
            let cfgs = sg.dbmgr.getDB(str);
            for (let key in cfgs) {
                if (this.getFramRedById(type, cfgs[key].id)) {
                    return 1;
                }
            }
            return 0;
        }
    }
    mvc.HeadFrameModel = HeadFrameModel;
})(mvc || (mvc = {}));

