            let tabInfo = this._tabInfo;
            for (let i = 0, len = this.tab.numChildren; i < len; i++) {
                let btn = this.tab.getChildAt(i);
                if (i >= tabInfo.length) {
                    btn.visible = false;
                }
                else {
                    btn.visible = true;
                    let unitRedotAch = btn.getChildByName("unitRedotAch");
                    btn.label = tabInfo[i];
                }
            }
