                let config = sg.dbmgr.get(str, this._curFrame.id);
                let exp = config ? config.collectExp : 0;
                if (exp == 0) {
                    this.expText.text = sg.translate('不提供收藏经验');
                }
                else {
                    this.expText.text = StringEx.format(sg.translate("激活获取${exp}点收藏经验"), {"exp":exp});
                }
                this.attrList.array = this._model.getFrameAttributeById(this._frameType, this._curFrame.id);
                if (this._frameType == mvc.HeadFrameConst.FramType.CHAT) {
                    mgr.icon.drawTexture(mgr.icon.getIconPath(mgr.UIAssist.$("{1}{2}.png", this._curFrame.asset, 2)), this.imgTitle);
                }
