(function (mvc) {
    class PopGvgBattleResult extends ui.view.gvgActivity.pop_resultUI {
        constructor() {
            super(...arguments);
            this._isOnce = false;
            this._isClose = true;
        }
        initView(info, report, type, isOnce) {
            this.info = info;
            this._battleInfo = report;
            this._type = type;
            this._isOnce = isOnce;
            this._isClose = true;
        }
        onAwake() {
            super.onAwake();
            this.boxResultSuc.skin = "cg";
            this.boxLose.skin = "sb";
            this.btnRecord.on(Laya.Event.CLICK, this, this.onBtnRecord);
            this.btnVideo.on(Laya.Event.CLICK, this, this.onBtnVideo);
            this.btnShare.on(Laya.Event.CLICK, this, this.onBtnShare);
            this.listReward.vScrollBarSkin = null;
            this.listReward.renderHandler = Laya.Handler.create(this, this.renderList, null, false);
        }
        onEnable() {
            super.onEnable();
            if (this.info.result > 0) {
                this.boxResultSuc.visible = true;
                this.boxLose.visible = false;
            }
            else {
                this.boxResultSuc.visible = false;
                this.boxLose.visible = true;
            }
            this.updateBoxWin();
            this.updateBoxPlayer();
        }
        onDisable() {
            super.onDisable();
            mvc.battleModel.clearBattle();
            if (this._isClose && this._battleInfo.fort_death) {
                mvc.gvgModel.fireEvent(mvc.GvgConst.EVT.GVG_STRONGHOLD_DEATH, { guid: this._battleInfo.fort_death.dguild_info.guild_id, fortId: this._battleInfo.fort_death.fort_id });
            }
            this.info = null;
            this._battleInfo = null;
        }
        updateBoxWin() {
            if (this._isOnce) {
                this.listReward.visible = true;
                let reward = this.info.reward || [];
                reward.push([140126, this._battleInfo.add_guild_score]);
                this.listReward.array = reward;
                if (this.info.reward.length >= 6) {
                    this.listReward.width = 435;
                }
                else
                    this.listReward.width = 69 * this.info.reward.length + this.listReward.spaceX * (this.info.reward.length - 1);
            }
            else {
                this.listReward.visible = false;
            }
        }
        updateBoxPlayer() {
            let info = this._battleInfo;
            if (this._battleInfo == null)
                return;
            this.updatePlayer(this.playerOne, info.combat_notify.group_a.head, info.combat_notify.result == 1);
            this.updatePlayer(this.playerTwo, info.combat_notify.group_b.head, info.combat_notify.result == 0);
            if (info.reduce_hp != null) {
                this.lbDec.visible = true;
                this.lbDec.text = mgr.UIAssist.$(sg.translate("造成{1}%生命伤害{2}"), (info.reduce_hp / 100).toFixed(2), this._battleInfo.fort_death ? sg.translate(",成功击溃敌人") : "");
            }
            else {
                this.lbDec.visible = false;
            }
        }
        updatePlayer(box, player, isWin) {
            let sprHeadIcon = box.getChildByName("sprHeadIcon");
            let headFrame = box.getChildByName("headFrame");
            let lblName = box.getChildByName("lblName");
            let lblGuildName = box.getChildByName("lblGuildName");
            let imgWin = box.getChildByName("imgWin");
            imgWin.visible = isWin;
            lblName.text = player.name;
            lblGuildName.text = mgr.UIAssist.$("[S{1}]{2}", player.svr_id, player.guild_name);
            mgr.ComFunMgr.drawHeadFrame(player.head_frame_id, headFrame);
            mgr.icon.drawTexture(mgr.ComFunMgr.getHeadIcon(player.head_icon, player.sex), sprHeadIcon);
        }
        renderList(unit) {
            unit.initViewCfg(unit.dataSource);
        }
        onBtnRecord() {
            if (this._battleInfo && this.info) {
                sg.uimgr.showUI("pop_battleRecord", this._battleInfo.combat_notify, this.info);
            }
        }
        onBtnVideo() {
            let info = this.info;
            let type = this._type;
            let battleInfo = this._battleInfo;
            if (battleInfo) {
                mvc.battleModel.clearBattle();
                this._isClose = false;
                this.closeSelf();
                this.timerOnce(20, this, () => {
                    mvc.battleModel.startBattle(battleInfo.combat_notify, type, () => {
                        sg.uimgr.showUI('pop_gvgBattleResult', info, battleInfo, type, false);
                    });
                });
            }
        }
        onBtnShare() {
            let info = this._battleInfo;
            if (info == null) {
                return;
            }
            let combat = info.combat_notify;
            sg.uimgr.showUI('pop_gvgShareView', 1, { data1: { heada: combat.group_a.head, headb: combat.group_b.head, only_id: info.only_id, result: combat.result } });
        }
    }
    mvc.PopGvgBattleResult = PopGvgBattleResult;
})(mvc || (mvc = {}));

