(function (mvc) {
    class PopGvgbuffChooseView extends ui.view.gvgActivity.pop_buffChooseUI {
        initView() {
            this._box = [this.box1, this.box2];
            this._selectId = mvc.gvgModel.gvgPlayerVo.buffId;
        }
        initModelEvent() {
            this.bindModelEvent(mvc.gvgModel, mvc.GvgConst.EVT.GVG_BUFF_CHANGE, this._updateView);
        }
        initCtrlEvent() {
            this.btnSelect.on(Laya.Event.CLICK, this, this._onbtnSelect);
            this.btnAdd.on(Laya.Event.CLICK, this, this._onbtnAdd);
        }
        onEnable() {
            super.onEnable();
            this._updateView();
        }
        _updateView() {
            let configs = sg.dbmgr.getDB("GVGActivity_GVGBuff");
            let idx = 0;
            for (let i in configs) {
                if (idx >= this._box.length) {
                    break;
                }
                let config = configs[i];
                this._updateBox(this._box[idx], config);
                idx++;
            }
            this.lbAtkTimeCount.text = (1 - mvc.gvgModel.gvgPlayerVo.buff_times) + "/1";
            this.btnAdd.visible = mvc.gvgModel.gvgPlayerVo.canBuyBuff();
            let buy_times = mvc.gvgModel.gvgPlayerVo.buff_buy_times, buff_times = mvc.gvgModel.gvgPlayerVo.buff_times;
            if (buy_times == 0 || (buy_times > 0 && buff_times == 0)) {
                this.btnSelect.disabled = false;
                if (mvc.gvgModel.gvgPlayerVo.buff_times == 0 && this._selectId > 0 && this._selectId == mvc.gvgModel.gvgPlayerVo.buffId) {
                    this.btnSelect.label = sg.translate("取消");
                }
                else {
                    this.btnSelect.label = sg.translate("选择");
                }
            }
            else {
                this.btnSelect.disabled = true;
                this.btnSelect.label = sg.translate("选择");
            }
        }
        _updateBox(box, config) {
            let btnBuff = box.getChildByName("btnBuff");
            let lbName = box.getChildByName("lbName");
            let lbDec = box.getChildByName("lbDec");
            let imgSelect = box.getChildByName("imgSelect");
            let imgSelected = box.getChildByName("imgSelected");
            let imgIcon = btnBuff.getChildByName("imgIcon");
            btnBuff.off(Laya.Event.CLICK, this, this._onbtnBuff);
            btnBuff.on(Laya.Event.CLICK, this, this._onbtnBuff, [config.id]);
            imgSelected.visible = config.id == mvc.gvgModel.gvgPlayerVo.buffId && mvc.gvgModel.gvgPlayerVo.buff_times == 0;
            imgSelect.visible = config.id == this._selectId;
            mgr.icon.drawTexture(mgr.icon.getIconPath(config.image), imgIcon);
            lbName.text = config.name;
            lbDec.text = config.desc;
        }
        _onbtnBuff(id) {
            if (id == null) {
                return;
            }
            let config = sg.dbmgr.get("GVGActivity_GVGBuff", id);
            if (config == null) {
                return;
            }
            this._selectId = id;
            this._updateView();
        }
        _onbtnSelect() {
            let id = this._selectId;
            if (mvc.gvgModel.gvgPlayerVo.buff_times == 0 && this._selectId == mvc.gvgModel.gvgPlayerVo.buffId) {
                id = 0;
            }
            if (mvc.gvgModel.gvgPlayerVo.setBuffId(id)) {
                this.closeSelf();
            }
            else {
                sg.uimgr.showNotice(sg.translate("没有这个buff"));
            }
        }
        _onbtnAdd() {
            if (mvc.gvgModel.gvgPlayerVo.canBuyBuff()) {
                let buyData = mgr.toolsMgr.getGlobalVoById("gvg_buff_buyCost", 1);
                let str = mgr.UIAssist.$(sg.translate("是否花费{1}仙玉购买{2}次增益使用次数"), buyData[0][1], 1);
                sg.uimgr.showUI("pop_gvgBuyBuffTimesView", str, 1, () => {
                    mvc.gvgCtrl.reqGuildSlapBuyBuffTimes();
                }, this);
            }
        }
    }
    mvc.PopGvgbuffChooseView = PopGvgbuffChooseView;
})(mvc || (mvc = {}));

