(function (mvc) {
    class PopGvgRankView extends ui.view.gvgActivity.pop_gvgRankUI {
        constructor() {
            super(...arguments);
            this._selectIndex = 0;
        }
        initView(typeInfo, selectIndex = 0) {
            this._types = typeInfo || [];
            this._infoReq = {};
            this._selectIndex = selectIndex;
        }
        initSendMsg() {
            if (this._types) {
                let type = this._types[this._selectIndex];
                if (type != null) {
                    this._infoReq[type.type] = 1;
                    mvc.rankCtrl.reqRankInfo(type.type);
                }
            }
        }
        initModelEvent() {
            this.bindModelEvent(mvc.rankModel, mvc.RankConst.EVT.UPDATE_RANK_INFO, this._updateView);
        }
        initCtrlEvent() {
            this.guildItemList.itemRender = mvc.UnitGvgGuildRankItem;
            this.guildItemList.vScrollBarSkin = "";
            this.guildItemList.renderHandler = this.createHandler(this, this._onGuildItemListRender, null, false);
            this.manItemList.itemRender = mvc.UnitGvgManRankItem;
            this.manItemList.vScrollBarSkin = "";
            this.manItemList.renderHandler = this.createHandler(this, this._onManItemListRender, null, false);
            this.cbox.selectHandler = this.createHandler(this, this._onCBoxSelect, null, false);
            if (this._manRankItem == null) {
                this._manRankItem = new mvc.UnitGvgManRankItem();
                this.boxItem.addChild(this._manRankItem);
                this._manRankItem.x = (this.boxItem.width - this._manRankItem.width) / 2;
                this._manRankItem.y = (this.boxItem.height - this._manRankItem.height) / 2;
            }
            if (this._guildRankItem == null) {
                this._guildRankItem = new mvc.UnitGvgGuildRankItem();
                this.boxItem.addChild(this._guildRankItem);
                this._guildRankItem.x = (this.boxItem.width - this._guildRankItem.width) / 2;
                this._guildRankItem.y = (this.boxItem.height - this._guildRankItem.height) / 2;
            }
        }
        onEnable() {
            super.onEnable();
            this._btns = [this.btnGuildRank, this.btnManRank];
            for (let i = 0; i < this._btns.length; i++) {
                let btn = this._btns[i];
                let type = this._types[i];
                btn.on(Laya.Event.CLICK, this, this._onBtnClick, [i]);
                if (type) {
                    btn.visible = true;
                    if (type.btnDesc)
                        btn.label = type.btnDesc;
                }
                else {
                    btn.visible = false;
                }
            }
            this.cbox.labels = sg.translate("战功榜,摧毁榜,杀敌榜");
            this.cbox.selectedIndex = 0;
            this._updateView();
        }
        _updateView() {
            this._updateSelectIndexInfo(this._selectIndex);
        }
        updatePersonalRankInfo() {
            if (!this._types || !this._types[1]) {
                return;
            }
            let vo = mvc.rankModel.getRankVo(this._types[1].type);
            window["MyGame"].openLog && console.log("个人排行榜：", vo);
            let cboxIndex = this.cbox.selectedIndex;
            if (vo == null || cboxIndex == -1) {
                this.manItemList.visible = this._manRankItem.visible = false;
                this.lblNotMan.visible = true;
                return;
            }
            let arr = vo.getRankItemVos();
            arr.sort((a, b) => {
                if (cboxIndex == 0) {
                    if (a.getValue(0) != b.getValue(0)) {
                        return b.getValue(0) - a.getValue(0);
                    }
                    if (a.getValue(1) != b.getValue(1)) {
                        return b.getValue(1) - a.getValue(1);
                    }
                    return b.getValue(2) - a.getValue(2);
                }
                else if (cboxIndex == 1) {
                    if (a.getValue(1) != b.getValue(1)) {
                        return b.getValue(1) - a.getValue(1);
                    }
                    if (a.getValue(0) != b.getValue(0)) {
                        return b.getValue(0) - a.getValue(0);
                    }
                    return b.getValue(2) - a.getValue(2);
                }
                else {
                    if (a.getValue(2) != b.getValue(2)) {
                        return b.getValue(2) - a.getValue(2);
                    }
                    if (a.getValue(0) != b.getValue(0)) {
                        return b.getValue(0) - a.getValue(0);
                    }
                    return b.getValue(1) - a.getValue(1);
                }
            });
            this.manItemList.visible = this._manRankItem.visible = true;
            this.manItemList.array = vo.getRankItemVos();
            let myVo = vo.getSelfVo();
            let myRank = 0;
            for (let i = 0; i < this.manItemList.array.length; i++) {
                let arr = this.manItemList.array[i];
                if (arr.headPid == myVo.headPid) {
                    myRank = i + 1;
                    break;
                }
            }
            this._manRankItem.steData(myVo, cboxIndex, myRank);
            this.lblNotMan.visible = !this.manItemList.array || this.manItemList.array.length <= 0;
        }
        updateGuildRankInfo() {
            if (!this._types || !this._types[0]) {
                return;
            }
            let vo = mvc.rankModel.getRankVo(this._types[0].type);
            window["MyGame"].openLog && console.log("仙盟排行榜", vo, this._types[0].type);
            if (vo == null) {
                this.guildItemList.visible = this._guildRankItem.visible = false;
                this.lblNotGuild.visible = true;
                return;
            }
            this.guildItemList.visible = this._guildRankItem.visible = true;
            this.guildItemList.array = vo.getRankItemVos();
            this._guildRankItem.steData(vo.getSelfVo());
            this.lblNotGuild.visible = !this.guildItemList.array || this.guildItemList.array.length <= 0;
        }
        _updateSelectIndexInfo(selectedIndex) {
            if (selectedIndex < 0) {
                return;
            }
            let type = this._types[selectedIndex];
            if (type && !this._infoReq[type.type]) {
                this._infoReq[type.type] = 1;
                mvc.rankCtrl.reqRankInfo(type.type);
            }
            if (selectedIndex == 1) {
                this.grp_guild.visible = false;
                this.grp_man.visible = true;
                this.updatePersonalRankInfo();
            }
            else if (selectedIndex == 0) {
                this.grp_man.visible = false;
                this.grp_guild.visible = true;
                this.updateGuildRankInfo();
            }
            this._manRankItem.visible = this.btnManRank.selected = selectedIndex == 1;
            this._guildRankItem.visible = this.btnGuildRank.selected = selectedIndex == 0;
            this._selectIndex = selectedIndex;
        }
        _onGuildItemListRender(box, index) {
            if (box.dataSource) {
                box.steData(box.dataSource);
            }
        }
        _onManItemListRender(box, index) {
            if (box.dataSource) {
                box.steData(box.dataSource, this.cbox.selectedIndex, index + 1);
            }
        }
        _onCBoxSelect(index) {
            window["MyGame"].openLog && console.log("_onCBoxSelect", index);
            if (this._selectIndex !== 1) {
                return;
            }
            this.updatePersonalRankInfo();
        }
        _onBtnClick(index, evt) {
            if (index != null) {
                this._updateSelectIndexInfo(index);
            }
        }
    }
    mvc.PopGvgRankView = PopGvgRankView;
})(mvc || (mvc = {}));

