(function (mvc) {
    class PopGvgRecordView extends ui.view.gvgActivity.pop_gvgRecordUI {
        constructor() {
            super(...arguments);
            this._typesReq = {};
        }
        initView(selectIndx, types, guildId) {
            this._selectIndx = selectIndx || 0;
            this._typesReq = {};
            this._types = types || [mvc.GvgConst.GvgReport.atk, mvc.GvgConst.GvgReport.def, mvc.GvgConst.GvgReport.guild_atk, mvc.GvgConst.GvgReport.guild_def];
            this._guildId = guildId || mvc.gvgModel.gvgPlayerVo.getSelfGuidId();
        }
        initSendMsg() {
            if (this._types && this._types[this._selectIndx] != null) {
                mvc.gvgModel.reqGuildSlapRecordByType(this._types[this._selectIndx], this._guildId);
            }
        }
        initCtrlEvent() {
            this.listRecord.itemRender = mvc.UnitGvgRecordItem;
            this.listRecord.renderHandler = this.createHandler(this, this._onListRecordRender, null, false);
            this.listLog.itemRender = mvc.UnitGvgGuildRecordItem;
            this.listLog.renderHandler = this.createHandler(this, this._onListLogRender, null, false);
            this.listLog.vScrollBarSkin = "";
            this.listRecord.vScrollBarSkin = "";
            this.tab.selectHandler = this.createHandler(this, this._onTabSelect, null, false);
        }
        initModelEvent() {
            this.bindModelEvent(mvc.gvgModel, mvc.GvgConst.EVT.GVG_RECORD_INFO, this._updateView);
            this.bindModelEvent(mvc.gvgModel, mvc.GvgConst.EVT.GVG_GUILD_RECORD_INFO, this._updateView);
        }
        onEnable() {
            super.onEnable();
            let selectedIndex = this._selectIndx || 0;
            if (this._selectIndx >= 0 && this.tab.selectedIndex == selectedIndex) {
                this._updateView();
            }
            else {
                this.tab.selectedIndex = selectedIndex;
            }
        }
        _updateView() {
            if (this.tab.getChildAt(this._selectIndx)) {
                this.tab.getChildAt(this._selectIndx).selected = false;
            }
            this._selectIndx = this.tab.selectedIndex;
            if (this.tab.getChildAt(this._selectIndx)) {
                this.tab.getChildAt(this._selectIndx).selected = true;
            }
            for (let i = 0; i < this.tab.numChildren; i++) {
                let box = this["box" + i];
                if (box) {
                    box.visible = i == this._selectIndx;
                }
            }
            if (this._selectIndx >= 2) {
                this.listRecord.visible = false;
                let record = mvc.gvgModel.getGvgGuildVo(this._guildId).getRecordByType(mvc.gvgModel.getGuildRecordType(this._types[this._selectIndx]));
                if (record && record.length > 0) {
                    this.lblBlank.visible = false;
                    this.listLog.visible = true;
                    this.listLog.array = record;
                }
                else {
                    this.lblBlank.visible = true;
                    this.listLog.visible = false;
                }
            }
            else {
                this.listLog.visible = false;
                let record = mvc.gvgModel.gvgPlayerVo.getRecordByType(this._types[this._selectIndx]);
                if (record && record.length > 0) {
                    this.lblBlank.visible = false;
                    this.listRecord.visible = true;
                    this.listRecord.array = record;
                }
                else {
                    this.lblBlank.visible = true;
                    this.listRecord.visible = false;
                }
            }
        }
        _onTabSelect(index) {
            if (index < 0) {
                return;
            }
            if (this._types && this._types[index] && this._typesReq[this._types[index]] == null) {
                this._typesReq[this._types[index]] = 1;
                mvc.gvgModel.reqGuildSlapRecordByType(this._types[index], this._guildId);
            }
            this._updateView();
        }
        _onListRecordRender(cell, index) {
            if (cell.dataSource) {
                cell.updateView(cell.dataSource, this._types[this._selectIndx]);
            }
        }
        _onListLogRender(cell, index) {
            if (cell.dataSource) {
                cell.setData(cell.dataSource);
            }
        }
    }
    mvc.PopGvgRecordView = PopGvgRecordView;
})(mvc || (mvc = {}));

