            let stronghold = gVo.getStrongholdById(data.id);
            this.lbName.text = stronghold.getPanelConfig().strongholdName;
            this.listPlayer.array = stronghold.getNoRobotPlayer();
            this.btnArrange.parent.visible = this.listPlayer.array.length == 0;
            this.btnGarrison.visible = this.listPlayer.array.length < 3 && this.listPlayer.array.length > 0;
            this._setStarNum(data.star);
