var mvc;
(function (mvc) {
    class UnitGvgGiftItem extends ui.view.gvgActivity.unit_gvgGiftItemUI {
        onEnable() {
            super.onEnable();
            this.lblGoldNum.visible = false;
            this._initItem();
            this.boxPrice.visible = mgr.gplatform.showOldPrice();
        }
        _initItem() {
            this.btnBuy.on(Laya.Event.CLICK, this, this._onBuyGiftClick);
            this.rewardList.renderHandler = this.createHandler(this, this._renderRewardList, null, false);
        }
        dataChange() {
            let data = this.dataSource;
            if (!data) {
                return;
            }
            let info = mvc.slgActivityModel.getGiftVo(data.id, data.type, data.round);
            let buyCount = 0;
            let limit = 0;
            let limitStr = "";
            this.lblTitle.text = data.name;
            if (data.dayTime > 0) {
                buyCount = info ? info.limtTime : buyCount;
                limit = data.dayTime;
                limitStr = sg.translate("每日限购");
            }
            else {
                if (data.limitTime > 0) {
                    limitStr = sg.translate("限购");
                    buyCount = info ? info.buyTime : buyCount;
                    limit = data.limitTime;
                }
                else {
                    limitStr = sg.translate("无限购");
                }
            }
            this.imgIcon.visible = this.lblGoldNum.visible = this.lblOldPrice.visible = this.imgLine.visible = false;
            this.btnBuy.label = "";
            this.redotBuy.visible = false;
            if (data.set_id == 0) {
                if (data.gold == 0) {
                    this.btnBuy.label = sg.translate("免费");
                    this.redotBuy.visible = buyCount < data.dayTime;
                }
                else {
                    this.imgIcon.visible = true;
                    this.lblGoldNum.visible = true;
                    mgr.icon.drawTexture(mgr.icon.getIconPath(mgr.toolsMgr.getIconById(1)), this.imgIcon);
                    this.lblGoldNum.text = "" + data.gold;
                    if (!mvc.gvgModel.isApply) {
                        this.redotBuy.visible = false;
                    }
                    else {
                        this.redotBuy.visible = buyCount < data.limitTime && mgr.toolsMgr.getCountById(1) >= data.gold;
                    }
                }
            }
            else {
                this.lblOldPrice.visible = true;
                this.imgLine.visible = true;
                let v1 = data.originalPrice;
                this.lblOldPrice.text = StringEx.format(sg.translate("原价${v1}元"), {"v1":v1});
                this.btnBuy.label = mgr.gplatform.showPriceByGearId(data.set_id);
            }
            let str = limit == 0 ? limitStr : (limitStr + (limit - buyCount) + "/" + limit);
            this.lblLimit.text = str;
            this.lblLimit.color = (limit == 0 || limit - buyCount > 0) ? mgr.toolsMgr.getColor2("green") : mgr.toolsMgr.getColor2("red");
            this.btnBuy.disabled = (limit > 0 && limit - buyCount <= 0);
            this.rewardList.array = data.reward;
        }
        _renderRewardList(item, index) {
            if (item.dataSource == null) {
                return;
            }
            item.initViewCfg(item.dataSource);
        }
        _onBuyGiftClick(event) {
            let data = this.dataSource;
            if (!data) {
                return;
            }
            if (data) {
                if (mvc.slgActivityCtrl.getActIsOpen(data.type) == false) {
                    sg.uimgr.showNotice(sg.translate("活动已结束"));
                    return;
                }
                if (!mvc.slgActivityModel.getCanBuyGift(data.id, data.type, data.round)) {
                    sg.uimgr.showNotice(sg.translate("限购次数不足"));
                    return;
                }
                if (data.set_id == 0) {
                    if (data.money == 0 && data.gold == 0) {
                        mvc.slgActivityCtrl.reqReceiveReward(data.id, data.type);
                    }
                    else if (!mvc.gvgModel.isApply) {
                        sg.uimgr.showNotice(sg.translate("您未参赛，无法购买礼包"));
                    }
                    else if (data.money == 0 && mgr.toolsMgr.checkConsume([[1, data.gold]], true)) {
                        mvc.mainModel.consumeJade([[1, data.gold]], 1, () => {
                            mvc.slgActivityCtrl.reqReceiveReward(data.id, data.type);
                        });
                    }
                }
                else {
                    if (!mvc.gvgModel.isApply) {
                        sg.uimgr.showNotice(sg.translate("您未参赛，无法购买礼包"));
                    }
                    else {
                        mvc.rechargeCtrl.reqRechargeByPhpEx(data.set_id);
                    }
                }
            }
        }
    }
    mvc.UnitGvgGiftItem = UnitGvgGiftItem;
})(mvc || (mvc = {}));

