(function (mvc) {
    class UnitGvgRecordItem extends ui.view.gvgActivity.unit_gvgRecordItemUI {
        onEnable() {
            super.onEnable();
            this.btnRevenge.on(Laya.Event.CLICK, this, this._onbtnRevenge);
            this.btnDetails.on(Laya.Event.CLICK, this, this._onbtnDetails);
            this.btnDfeDetails.on(Laya.Event.CLICK, this, this._onbtnDetails);
            this.imgHeadIcon.on(Laya.Event.CLICK, this, this._onClick);
        }
        onDisable() {
            super.onDisable();
        }
        updateView(data, type) {
            this.rankVo = data;
            if (this.rankVo) {
                let ahead;
                this.btnRevenge.visible = false;
                if (this.rankVo.ahead) {
                    ahead = this.rankVo.ahead;
                }
                else {
                    ahead = this.rankVo.dhead;
                }
                if (ahead == null) {
                    return;
                }
                if (type == mvc.GvgConst.GvgReport.atk) {
                    this.btnDfeDetails.visible = false;
                    this.btnDetails.visible = this.imgWin.visible = this.lblIntegral.visible = true;
                    if (data.result > 0) {
                        this.lbRes.text = sg.translate("进攻成功");
                        this.lbRes.color = mgr.toolsMgr.getColor2("green");
                    }
                    else {
                        this.lbRes.text = sg.translate("进攻失败");
                        this.lbRes.color = mgr.toolsMgr.getColor2("red");
                    }
                }
                else {
                    this.btnDfeDetails.visible = true;
                    this.btnDetails.visible = this.imgWin.visible = this.lblIntegral.visible = false;
                    if (data.result <= 0) {
                        this.lbRes.text = sg.translate("防守成功");
                        this.lbRes.color = mgr.toolsMgr.getColor2("green");
                    }
                    else {
                        this.lbRes.text = sg.translate("防守失败");
                        this.btnRevenge.visible = true;
                        this.lbRes.color = mgr.toolsMgr.getColor2("red");
                    }
                }
                this.lblLvName.text = mgr.toolsMgr.getLevelName(ahead.level);
                this.lblName.text = ahead.name;
                if (this.lblIntegral.visible) {
                    this.lblIntegral.text = mgr.UIAssist.$("+{1}", data.score);
                    this.lblIntegral.color = mgr.toolsMgr.getColor2("green");
                }
                mgr.ComFunMgr.drawHeadFrame(ahead.head_frame_id, this.imgFrame);
                mgr.icon.drawTexture(mgr.ComFunMgr.getHeadIcon(ahead.head_icon, ahead.sex), this.imgHeadIcon);
                this.lblGuildName.text = ahead.guild_name;
            }
        }
        _onbtnRevenge(evt) {
            if (this.rankVo && mvc.gvgModel.isSignUp()) {
                if (mvc.gvgModel.getGvgIsBattleState()) {
                    let guildVo = mvc.gvgModel.getGvgGuildVo(this.rankVo.ahead.guild_id);
                    let strongholdInfo = guildVo.isHaveGarrisonStrongholdPos(this.rankVo.ahead.player_id);
                    if (strongholdInfo == null) {
                        sg.uimgr.showUI("pop_gvgStrongholdView", guildVo);
                    }
                    else {
                        sg.uimgr.showUI("pop_gvgDefendersView", strongholdInfo);
                    }
                }
                else {
                    sg.uimgr.showNotice(sg.translate("该阶段无法挑战"), "green");
                }
            }
        }
        _onbtnDetails(evt) {
            mvc.compareCtrl.reqDuelVideo(this.rankVo.replay_id);
        }
        _onClick() {
            if (this.rankVo) {
                let ahead;
                if (this.rankVo.ahead) {
                    ahead = this.rankVo.ahead;
                }
                else {
                    ahead = this.rankVo.dhead;
                }
                if (ahead == null) {
                    return;
                }
                mvc.mainCtrl.reqPlayerInfo(ahead.player_id);
            }
        }
    }
    mvc.UnitGvgRecordItem = UnitGvgRecordItem;
})(mvc || (mvc = {}));

