(function (mvc) {
    class UnitGvgTaskItem extends ui.view.gvgActivity.unit_gvgTaskItemUI {
        initView() {
        }
        initCtrlEvent() {
            this.listRwd.hScrollBarSkin = "";
            this.listRwd.renderHandler = this.createHandler(this, this._listRender, null, false);
            this.on(Laya.Event.CLICK, this, this._onClick);
        }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
        }
        onDisable() {
            super.onDisable();
        }
        onClosed() {
            super.onClosed();
        }
        setData(data, progress, isFinished, type) {
            this.data = data;
            this.type = type;
            this.lblTitle.text = data.name;
            this.listRwd.array = data.reward;
            if (isFinished) {
                this.btnGo.visible = this.unitRedotTask.visible = false;
                this.btnGetReward.visible = true;
                this.btnGetReward.gray = true;
                this.btnGetReward.disabled = true;
                this.progTask.value = 1;
                this.lblTaskNum.text = `${data.need[1]}/${data.need[1]}`;
            }
            else {
                this.btnGetReward.gray = false;
                this.btnGetReward.disabled = false;
                this.progTask.value = progress / data.need[1];
                this.lblTaskNum.text = `${progress}/${data.need[1]}`;
                if (progress >= data.need[1]) {
                    this.btnGo.visible = false;
                    this.btnGetReward.visible = this.unitRedotTask.visible = true;
                }
                else {
                    this.btnGo.visible = true;
                    this.btnGetReward.visible = this.unitRedotTask.visible = false;
                }
            }
        }
        _onClick(e) {
            switch (e.target) {
                case this.btnGo:
                    {
                        if (this.data.tips) {
                            sg.uimgr.showNotice(this.data.tips);
                        }
                        else if (this.data.link) {
                            sg.uimgr.jumpUI(this.data.link[1], { layer: this.data.link[2] });
                        }
                    }
                    break;
                case this.btnGetReward:
                    {
                        this.type ? mvc.gvgCtrl.reqTaskReward(this.type, this.data.id) : mvc.gvgCtrl.reqTaskRewardGuild(this.data.id);
                    }
                    break;
                default:
                    break;
            }
        }
        _listRender(cell, index) {
            let data = cell.dataSource;
            if (!data)
                return;
            cell.initViewCfg(data);
        }
    }
    mvc.UnitGvgTaskItem = UnitGvgTaskItem;
})(mvc || (mvc = {}));

