(function (mvc) {
    class UnitStrongholdItem extends ui.view.gvgActivity.unit_strongholdUI {
        onEnable() {
            super.onEnable();
            this.listPlayer.renderHandler = this.createHandler(this, this._onListPlayerRender, null, false);
            this.on(Laya.Event.CLICK, this, this._onBtnAtkClick);
            this.ani1.on(Laya.Event.COMPLETE, this, this._onAniComplete);
        }
        onDisable() {
            super.onDisable();
            this.clearTimer(this, this._onUpdateTime);
            this.clearTimer(this, this._onUpdateScore);
            this.clearTimer(this, this._updateAtkShowTime);
        }
        playAni(data1) {
            let data = this._data;
            if (data1 == null || data == null || data1.fortId != data.id) {
                return;
            }
            let time = data.getDestroyTime();
            if (time > 0) {
                let senceSpine = this.setSpineScene(9155, "stand", [this.width / 2, this.height / 2]);
                senceSpine.once(Laya.Event.LABEL, this, this._onAniLabelEvent);
            }
        }
        _onAniPlayComplete() {
            if (this._senceSpine) {
                this._senceSpine.stop();
                this._senceSpine.recycle();
                this._senceSpine = null;
            }
        }
        _onAniLabelEvent(eventData) {
            if (eventData.name == "switch") {
                if (this._data) {
                    this._data.playDeatAni = false;
                    this.setData(this._data);
                }
                let tempBattleInfo = mvc.gvgModel._tempBattleInfo;
                if (tempBattleInfo && tempBattleInfo.fort_death && tempBattleInfo.fort_death.fort_id > 0) {
                    let data = {
                        guild_id: tempBattleInfo.duelB.head.guild_id,
                        fort_id: tempBattleInfo.fort_death.fort_id,
                        ahead: tempBattleInfo.fort_death.ahead,
                        aguild_info: tempBattleInfo.fort_death.aguild_info,
                        dguild_info: tempBattleInfo.fort_death.dguild_info,
                        score: tempBattleInfo.fort_death.score,
                        dead_num: tempBattleInfo.fort_death.dead_num,
                        addScore: mvc.gvgModel.getStrongholdDestroyScore(tempBattleInfo.fort_death.fort_id),
                    };
                    sg.uimgr.showUI("pop_gvgStronggoldDestroyView", data);
                }
                this.clearTimer(this, this._onUpdateTime);
                this.timerLoop(1000, this, this._onUpdateTime);
            }
        }
        setData(data) {
            this._data = data;
            this.clearTimer(this, this._onUpdateTime);
            this.clearTimer(this, this._onUpdateScore);
            if (data == null)
                return;
            if (this._data.guildVo.getIsSelf()) {
                mgr.icon.drawTexture("ui/gvgActivity/progress__self.png", this.proHp);
                this.lbTime.visible = false;
                this.imgArrow.visible = data.id == mvc.gvgModel.gvgPlayerVo.strongholdId;
                this.ani2.play(0, true);
                this.lbDec.color = mgr.toolsMgr.getColor2("green");
            }
            else {
                mgr.icon.drawTexture("ui/gvgActivity/progress__enemy.png", this.proHp);
                this.lbTime.visible = true;
                this.imgArrow.visible = false;
                this.lbDec.color = mgr.toolsMgr.getColor2("red");
            }
            this.lbDec.text = mgr.UIAssist.$(sg.translate("仙盟积分+{1}"), data.getMinSoce());
            let config = data.getConfig();
            let value = data.getHpPercentage();
            let value1 = value * 100;
            if (value1 > 100) {
                value1 = 100;
            }
            if (value1 > 0 && value1 < 0.01) {
                value1 = 0.01;
            }
            this.proHp.value = value;
            this.lblPro.text = value1.toFixed(2) + "%";
            this.listPlayer.array = data.getPlayers();
            let config2 = data.getPanelConfig();
            this._steStarColor(config.star);
            this._setStarNum(config.star);
            this.lbName.text = mvc.gvgModel.getStrongholdNameById(data.id, data.guildVo.id);
            this.timerLoop(1000, this, this._onUpdateTime);
            this.timerLoop(60000, this, this._onUpdateScore);
            this.lbDec.visible = false;
            let time = data.getDestroyTime();
            if (time > 0) {
                this.lbTime.visible = true;
                if (this._data.playDeatAni) {
                    mgr.icon.drawTexture(mgr.icon.getIconPath(config2.strongholdImage[0]), this.imgBg);
                }
                else {
                    mgr.icon.drawTexture(mgr.icon.getIconPath(config2.brokenImage[0]), this.imgBg);
                }
            }
            else {
                this.lbTime.visible = false;
                mgr.icon.drawTexture(mgr.icon.getIconPath(config2.strongholdImage[0]), this.imgBg);
            }
            let hitinfo = this._data.getHitInfo();
            this.clearTimer(this, this._updateAtkShowTime);
            this.clipAtk.visible = false;
            this.clipAtk.stop();
            if (hitinfo) {
                let interval = sg.time.getNow() / 1000 - hitinfo;
                if (interval < this._data.getAtkShowTime()) {
                    this.clipAtk.visible = true;
                    this.clipAtk.play(0, -1);
                    this.timerLoop(1000, this, this._updateAtkShowTime);
                }
            }
            this._updateAtkShowTime();
        }
        _setStarNum(num) {
            for (let i = 0; i < this.boxStar.numChildren; i++) {
                this.boxStar.getChildAt(i).gray = i >= num;
            }
        }
        _steStarColor(num) {
            this.lbName.color = mgr.toolsMgr.getColor(num);
            this.lbName.strokeColor = mgr.toolsMgr.getStrokeColor(num);
        }
        _onListPlayerRender(cell, index) {
            let data = cell.dataSource;
            if (data) {
                cell.initView({ iconPath: mgr.ComFunMgr.getHeadIcon(data.head.head_icon, data.head.sex), headFrameId: data.head.head_frame_id, level: data.head.level });
            }
        }
        _updateAtkShowTime() {
            let hitinfo = this._data.getHitInfo();
            let interval = sg.time.getNow() / 1000 - hitinfo;
            if (this._data.getAllCurrHp() <= 0 || interval >= this._data.getAtkShowTime() || !mvc.gvgModel.getGvgIsBattleState()) {
                this.clipAtk.visible = false;
                this.clipAtk.stop();
                this.clearTimer(this, this._updateAtkShowTime);
                return;
            }
            this.clipAtk.visible = true;
        }
        _onUpdateScore() {
            if (mvc.gvgModel.getGvgIsBattleState()) {
                let destroyTime = this._data.getDestroyTime();
                if (destroyTime <= 0) {
                    this.lbDec.visible = true;
                    this.ani1.play();
                }
            }
        }
        _onUpdateTime() {
            let destroyTime = this._data.getDestroyTime();
            if (destroyTime <= 0 || this._data.playDeatAni) {
                this.lbTime.visible = false;
                return;
            }
            this.lbTime.visible = true;
            this.lbTime.text = mgr.UIAssist.$(sg.translate("灵脉恢复时间：{1}"), sg.time.formatTimeStrT("F2", destroyTime));
        }
        _onAniComplete() {
            this.lbDec.visible = false;
        }
        _onBtnAtkClick(evt) {
            if (this._data == null) {
                return;
            }
            let isSelf = this._data.guildVo.getIsSelf();
            if (!isSelf && !mvc.gvgModel.getGvgIsBattleState()) {
                sg.uimgr.showNotice(sg.translate("休战中无法窥探其他仙盟"));
                return;
            }
            if (this._data.getDestroyTime() > 0) {
                mvc.gvgCtrl.reqGuildSlapDeathFortInfo(this._data.guildVo.id, this._data.id);
                return;
            }
            sg.uimgr.showUI("pop_gvgDefendersView", this._data);
        }
        setSpineScene(id, aniStr = "stand", pos, autoPlay = true, loop = false) {
            let spine = sg.SpineSprite.create(id, autoPlay, loop, true, aniStr);
            spine.name = "UnitStrongholdItem111";
            this.addChild(spine);
            if (pos) {
                spine.x = pos[0];
                spine.y = pos[1];
            }
            return spine;
        }
    }
    mvc.UnitStrongholdItem = UnitStrongholdItem;
})(mvc || (mvc = {}));

