var mvc;
(function (mvc) {
    class PopCollectorRewardView extends ui.view.collector.pop_collectorRewardUI {
        initView() {
            this._model = mvc.collectorModel;
            this._vo = this._model.getCollectorVo();
        }
        initModelEvent() {
            this.bindModelEvent(this._model, mvc.CollectorConst.EVT.COLLECTOR_LV_UP_ANI, this._onUpgrades);
        }
        initCtrlEvent() {
            this.itemRewardnew.itemRender = this.itemReward.itemRender = mvc.UnitItemBox;
            this.itemRewardnew.renderHandler = this.itemReward.renderHandler = this.createHandler(this, this._onItemRewardListRender, null, false);
            this.btnLeft.on(Laya.Event.CLICK, this, this._onBtnClick);
            this.btnRight.on(Laya.Event.CLICK, this, this._onBtnClick);
            this.btnLvlup.on(Laya.Event.CLICK, this, this._onBtnClick);
        }
        onAwake() {
            super.onAwake();
            this.introduce2.text = sg.translate("我的收藏等级：");
        }
        onEnable() {
            super.onEnable();
            this.reward.visible = this.rewardnew.visible = false;
            this._selectLv = this._vo.level + 1;
            this._showItemIndex = 0;
            this._twPlay = false;
            this._updateView();
        }
        _updateView() {
            this._updateLevelInfo();
            this._chengeSelectLv(0, true);
        }
        _onUpgrades() {
            this._updateLevelInfo();
            this._chengeSelectLv(1);
        }
        _updateLevelInfo() {
            let lvInfo = this._vo.getConfigToLevel();
            if (lvInfo == null) {
                return;
            }
            this.levelNum.text = this._vo.exp + "/" + lvInfo.exp;
            this.proLevel.value = Math.min(this._vo.exp / lvInfo.exp, 1);
            this.time.text = this._vo.level.toString();
            mgr.icon.drawTexture("ui/" + lvInfo.inletImage + '.png', this.collectorBg);
            mgr.icon.drawTexture("ui/" + lvInfo.inletImageBg + '.png', this.bgbox);
            this._shouRed = this._vo.canUpgrades();
        }
        _updateSelectLevel(dir = 0, change = true) {
            let lvInfo = this._vo.getConfigToLevel(this._selectLv);
            if (lvInfo == null) {
                return;
            }
            this.lvlNeed.text = mgr.UIAssist.$(sg.translate("等级{1}奖励"), lvInfo.lvl);
            this.redLeft.visible = this.redRight.visible = this.redTips.visible = false;
            this.btnRight.visible = true;
            this.btnLeft.visible = this._selectLv > 1;
            let lv = this._vo.level;
            if (this._selectLv <= 0) {
                this.btnLvlup.visible = false;
            }
            else {
                this.btnLvlup.disabled = true;
                this.btnLvlup.visible = true;
                let currLv = lv + 1;
                if (this._selectLv > currLv) {
                    this.btnLvlup.label = sg.translate('升级');
                    this.redLeft.visible = this._shouRed;
                }
                else if (this._selectLv == currLv) {
                    this.btnLvlup.label = sg.translate('升级');
                    this.redTips.visible = this._shouRed;
                    this.btnLvlup.disabled = false;
                }
                else {
                    this.btnLvlup.label = sg.translate('已领取');
                    this.redRight.visible = this._shouRed;
                }
                this.btnRight.visible = this._selectLv < this._vo.getMaxLevel();
            }
            if (change == false) {
                return;
            }
            if (dir != 0) {
                this._showItemIndex += dir;
                this._showItemIndex = this._showItemIndex % 2;
                let reward, reward1;
                if (this._showItemIndex == 0) {
                    reward = this.reward;
                    reward1 = this.rewardnew;
                }
                else {
                    reward1 = this.reward;
                    reward = this.rewardnew;
                }
                this._setSelectInfo(reward, lvInfo);
                this._twPlay = true;
                reward.visible = reward1.visible = true;
                let endX1 = 148, endX2;
                if (dir == 1) {
                    reward.x = reward.parent.width;
                    endX2 = -reward1.width;
                }
                else {
                    reward.x = -reward.width;
                    endX2 = reward.parent.width;
                }
                this.clearTweenByTarget(reward);
                this.clearTweenByTarget(reward1);
                let rewardClear = this.createHandler(this, () => {
                    this.clearTweenByTarget(reward);
                });
                let reward1Clear = this.createHandler(this, () => {
                    this.clearTweenByTarget(reward1);
                    this._twPlay = false;
                    reward1.visible = false;
                });
                this.tweenTo(reward, { x: endX1 }, 500, null, rewardClear);
                this.tweenTo(reward1, { x: endX2 }, 500, null, reward1Clear);
            }
            else {
                this.rewardnew.visible = false;
                this.reward.visible = true;
                this.reward.x = 148;
                this.reward.y = 61;
                this._setSelectInfo(this.reward, lvInfo);
            }
        }
        _setSelectInfo(rewardBox, lvInfo) {
            let rewardbg = rewardBox.getChildByName('rewardbg');
            let itemReward = rewardBox.getChildByName('itemReward');
            let priviegesBox = rewardBox.getChildByName('priviegesBox');
            let priviegesText = rewardBox.getChildByName('priviegesText');
            priviegesBox.visible = lvInfo.rewardType == 2;
            itemReward.visible = !priviegesBox.visible;
            let show = false;
            if (priviegesBox && priviegesBox.visible) {
                let priviegesReward = priviegesBox.getChildByName('priviegesReward');
                if (priviegesReward) {
                    mgr.icon.drawTexture('ui/collector/' + lvInfo.privilegeImage + '.png', priviegesReward);
                    window["MyGame"].openLog && console.log("lvInfo:222,", lvInfo.inletImage, lvInfo.inletImageBg);
                }
                show = true;
            }
            if (itemReward && itemReward.visible) {
                itemReward.array = lvInfo.itemReward;
                show = lvInfo.itemReward != null && lvInfo.itemReward.length > 0;
            }
            rewardbg.visible = show;
            if (priviegesText) {
                priviegesText.visible = true;
                priviegesText.text = lvInfo.text;
            }
        }
        _chengeSelectLv(lv, change1 = false) {
            let change = true;
            this._selectLv += lv;
            if (this._selectLv < 1) {
                this._selectLv = 1;
                change = false;
            }
            if (this._selectLv > this._vo.getMaxLevel()) {
                this._selectLv = this._vo.getMaxLevel();
                change = false;
            }
            this._updateSelectLevel(lv, change || change1);
        }
        _onItemRewardListRender(item, index) {
            if (item.dataSource == null) {
                return;
            }
            item.initViewCfg(item.dataSource);
        }
        _onBtnClick(event) {
            switch (event.target) {
                case this.btnLeft:
                    if (this._twPlay == false) {
                        this._chengeSelectLv(-1);
                    }
                    break;
                case this.btnRight:
                    if (this._twPlay == false) {
                        this._chengeSelectLv(1);
                    }
                    break;
                case this.btnLvlup:
                    if (this._selectLv == 0) {
                        break;
                    }
                    let lv = this._vo.level + 1;
                    if (this._selectLv > lv) {
                        sg.uimgr.showNotice(sg.translate('请先提升上一级'));
                    }
                    else if (this._selectLv == lv) {
                        if (this._vo.canUpgrades()) {
                            mvc.collectorCtrl.reqCollectorLvUp();
                        }
                        else {
                            sg.uimgr.showNotice(sg.translate("未达到提升等级的经验要求"));
                        }
                    }
                    break;
            }
        }
    }
    mvc.PopCollectorRewardView = PopCollectorRewardView;
})(mvc || (mvc = {}));

