(function (mvc) {
    class PopFashionShareChoiceView extends ui.view.collector.pop_shareChoiceUI {
        initView(handler, vo) {
            this._model = mvc.collectorModel;
            this._callHandler = handler;
            this._vo = vo;
        }
        initCtrlEvent() {
            this.rewardList.renderHandler = this.createHandler(this, this._onRewardListRender, undefined, false);
            this.rewardList.selectHandler = this.createHandler(this, this._updateSkinInfo, undefined, false);
            this.btnSure.on(Laya.Event.CLICK, this, this._onBtnSureClick);
            this.btnCancel.on(Laya.Event.CLICK, this, this.closeSelf);
        }
        onEnable() {
            super.onEnable();
            this.boxFashionSelect.visible = false;
            this._updateView();
        }
        _updateView() {
            let selectedIndex = 0;
            let arr = [];
            if (this._vo) {
                let idx = 0;
                let array = mvc.equipModel.vo.getSkinShowByType(1) || [];
                for (let i = 0; i < array.length; i++) {
                    let data = array[i];
                    let skinInfo = mvc.equipModel.vo.getSkinInfo(data.id);
                    if (skinInfo && skinInfo.from_id == 0) {
                        let shareSkin = mvc.equipModel.vo.getShareSkinInfo(data.id);
                        if (shareSkin && (shareSkin.end_time == 0 || (shareSkin.end_time > 0 && (shareSkin.end_time - sg.time.getSecondTime()) > 0))) {
                            continue;
                        }
                        arr.push(data);
                        if (data.id == this._vo.id) {
                            selectedIndex = idx;
                        }
                        idx++;
                    }
                }
            }
            this.rewardList.selectedIndex = selectedIndex;
            this.rewardList.array = arr;
            this._updateSkinInfo(this.rewardList.selectedIndex);
        }
        _updateSkinInfo(index) {
            if (index == -1 || this.rewardList.selectedItem == null)
                return;
            let selectItem = this.rewardList.selectedItem;
            this.boxFashionSelect.visible = true;
            mgr.icon.drawTexture(mgr.icon.getIconPath(selectItem.iconArr[mvc.roleModel.roleInfo.sex]), this.imgFashionIcon);
        }
        _onRewardListRender(cell, index) {
            let data = cell.dataSource;
            if (!data)
                return;
            let icon = cell.getChildByName("icon");
            mgr.icon.drawTexture(mgr.icon.getIconPath(data.iconArr[mvc.roleModel.roleInfo.sex]), icon);
            let shareInfo = mvc.equipModel.vo.getShareSkinInfo(data.id);
        }
        _onBtnSureClick(event) {
            if (this._callHandler && this.rewardList.selectedItem) {
                this._callHandler.runWith(this.rewardList.selectedItem);
            }
            this.closeSelf();
        }
    }
    mvc.PopFashionShareChoiceView = PopFashionShareChoiceView;
})(mvc || (mvc = {}));

