(function (mvc) {
    class PopFashionshareView extends ui.view.collector.pop_shareUI {
        initView(vo) {
            this._vo = vo;
            this._callHandler = this.createHandler(this, this._updateSkinSelectInfo, undefined, false);
        }
        initModelEvent() {
            this.bindModelEvent(mvc.equipModel, mvc.EquipConst.EVT.SKIN_SHARE_UPDATE, this._updateView);
        }
        initCtrlEvent() {
            this.boxItem.on(Laya.Event.CLICK, this, this._onBoxShareItemClick);
            this.btnSure.on(Laya.Event.CLICK, this, this._onBtnShareClick);
        }
        onEnable() {
            super.onEnable();
            mgr.UIAssist.initHtml(this.times, { size: 16, color: "#323232", wordWrap: true, align: "left" });
            this._info = mvc.equipModel.vo.getSkinInfo(this._vo.id);
            this._updateView();
        }
        onDisable() {
            super.onDisable();
            this.stopTimer(this._onTime);
        }
        _updateView() {
            if (this._info.from_id != 0) {
                return;
            }
            let info = mvc.equipModel.vo.getShareSkinInfo(this._info.id);
            this._shareInfo = info;
            if (info && ((info.head == null && info.end_time == 0) || (info.head && (info.end_time - sg.time.getSecondTime()) > 0))) {
                this.lbDec.text = sg.translate('剩余试穿时长：');
                this.boxShareShow.x = 0;
                this.boxShareplayer.visible = true;
                let imgPlayerHead = this.boxShareplayer.getChildByName('imgPlayerHead');
                let showBtn = false;
                if (info.head) {
                    imgPlayerHead.sizeGrid = null;
                    mgr.icon.drawTexture(mgr.ComFunMgr.getHeadIcon(info.head.head_icon, info.head.sex), imgPlayerHead);
                    this.playerName.text = info.head.name;
                    this.lbTime.text = sg.time.formatTimeStrT("F9", info.end_time);
                    if (!this.hasTimer(this._onTime)) {
                        this.repeats(1000, this._onTime, true);
                    }
                }
                else {
                    this.playerName.text = '';
                    this.lbTime.text = mgr.toolsMgr.getGlobalVoById('skin_share_time', 1) / 60 + sg.translate('小时');
                    mgr.icon.drawTexture('ui/main/img_main_cell_01.png', imgPlayerHead);
                    imgPlayerHead.sizeGrid = "21,28,29,28";
                    showBtn = true;
                }
                this.btnPlayerHead.visible = showBtn;
                this.btnSure.label = sg.translate('结束分享');
                this._shareState = 1;
            }
            else {
                let time = mgr.toolsMgr.getGlobalVoById('skin_share_time', 1) / 60;
                this.lbDec.text = sg.translate('单次试穿时长：');
                this.lbTime.text = StringEx.format(sg.translate("${time}小时"), {"time":time});
                this.boxShareShow.x = 127;
                this.boxShareplayer.visible = false;
                this.btnSure.label = sg.translate('分享');
                this._shareState = 2;
            }
            this._skinItemInfo(this.boxItem, this._vo);
            let time = mvc.equipModel.vo.getShareTime();
            let shareLimt = mvc.collectorModel.getCollectorVo().getConfigToLevel();
            let limitTime = shareLimt ? shareLimt.condition[0] : 0;
            let haveTime = Math.max(0, limitTime - time);
            let color = haveTime == 0 ? '#e31e1e' : '#268e5e';
            this.times.innerHTML = this.times.innerHTML = mgr.UIAssist.setColor(haveTime + "/" + limitTime, color);
        }
        _skinItemInfo(cell, vo) {
            let data = vo;
            if (!data)
                return;
            let icon = cell.getChildByName("icon");
            mgr.icon.drawTexture(mgr.icon.getIconPath(data.iconArr[mvc.roleModel.roleInfo.sex]), icon);
        }
        _updateSkinSelectInfo(vo) {
            this._vo = vo;
            this._skinItemInfo(this.boxItem, this._vo);
        }
        _onTime() {
            if (this._shareInfo) {
                let time = this._shareInfo.end_time - sg.time.getSecondTime();
                this.lbTime.text = sg.time.formatTimeStrT("F9", time);
                if (time <= 0) {
                    this.stopTimer(this._onTime);
                    this._updateView();
                }
            }
        }
        _onBtnShareClick(event) {
            if (this._info == null && this._info.from_id != 0) {
                return;
            }
            if (this._shareState == 1) {
                mvc.equipCtrl.reqCancelSkinShare(this._info.id);
            }
            else if (this._shareState == 2) {
                if (mvc.equipModel.vo.isSkinShare(this._info.id)) {
                    mvc.guildCtrl.reqGuildSeekHelp(mvc.GuildConst.HELP_TYPE.FASHION_SHARE, this._info.id);
                }
                else {
                    sg.uimgr.showNotice(sg.translate('剩余分享次数不足'));
                }
            }
            this.closeSelf();
        }
        _onBoxShareItemClick(event) {
            sg.uimgr.showUI("pop_fashionShareChoiceView", this._callHandler, this._vo);
        }
    }
    mvc.PopFashionshareView = PopFashionshareView;
})(mvc || (mvc = {}));

