var mvc;
(function (mvc) {
    class CrossArenaModel extends sg.ModelBase {
        initModel() {
            this.tempDate = new Date();
            this.isShowIcon = true;
        }
        registerEvents() {
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.CROSS_ARENA_REWARD, this.rewardRed, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.CROSS_ARENA_RECORD, this.recodeRed, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.CROSS_ARENA_RED, this.arenaRed, this);
        }
        getArenaCfg(type) {
            return sg.dbmgr.get("arena_arena", type);
        }
        getRankReward(arenaType, type) {
            let cfgs = sg.dbmgr.getDB("arena_rankReward");
            let arr = [];
            for (let key in cfgs) {
                let v = cfgs[key];
                if (arenaType == v.type && v.resultType == type) {
                    arr.push(v);
                }
            }
            return arr;
        }
        getDayTime() {
            this.tempDate.setTime(sg.time.getTime());
            let time = this.tempDate;
            time.setHours(22, 0, 0, 0);
            let end = time.getTime();
            time.setHours(0);
            let start = time.getTime();
            let cur = sg.time.getTime();
            if (end > cur && start <= cur) {
                return end - cur;
            }
            else {
                return (end + 86400000) - cur;
            }
        }
        arenaOpen(isOpenTime = true, isTip = true) {
            if (isOpenTime && this.getDayTime() <= 0) {
                sg.uimgr.showNotice(sg.translate("新赛季0点开始"));
                return false;
            }
            let act = mvc.activityModel.openActivityVo.get(mvc.FUNC_ID.CROSS_ARENA);
            if (!act) {
                isTip && sg.uimgr.showNotice(sg.translate("赛季未开"));
                return false;
            }
            if (mgr.conditionMgr.checkFunc(mvc.FUNC_ID.CROSS_ARENA, isTip))
                return true;
            return false;
        }
        arenaRed() {
            if (!mgr.conditionMgr.checkFunc(mvc.FUNC_ID.CROSS_ARENA, false))
                return 0;
            let act = mvc.activityModel.openActivityVo.get(mvc.FUNC_ID.CROSS_ARENA);
            if (!act) {
                return 0;
            }
            return mgr.toolsMgr.getCountById(mvc.MainConst.ITEM_ID.CROSS_ARENA_COUPON) >= mvc.crossArenaModel.getMaxChallenge() ? 1 : 0;
        }
        rewardRed() {
            if (!mgr.conditionMgr.checkFunc(mvc.FUNC_ID.CROSS_ARENA, false))
                return 0;
            if (this.arenaInfo) {
                if (this.arenaInfo.day_reward || this.arenaInfo.week_reward)
                    return 1;
            }
            return 0;
        }
        recodeRed() {
            return mvc.redotCtrl.getCheckRed(mvc.REDOT_ID.CROSS_ARENA_RECORD);
        }
        getMaxChallenge() {
            return mgr.toolsMgr.getGlobalVoById("egg_drop_max_cross", 1);
        }
    }
    mvc.CrossArenaModel = CrossArenaModel;
})(mvc || (mvc = {}));

