var mvc;
(function (mvc) {
    class PopCrossChallengList extends ui.view.faArena.pop_faChallengeListUI {
        initView() {
        }
        initModelEvent() {
            this.bindModelEvent(mvc.crossArenaModel, mvc.CrossArenaConst.EVT.ARENA_INFO, this.updateView);
            this.bindModelEvent(mvc.crossArenaModel, mvc.CrossArenaConst.EVT.ARENA_COMBAT, this.initSendMsg);
            this.bindModelEvent(mvc.bagModel, mvc.BagConst.EVT.ITEM_NUM_CHANGE, this.redChangeShow);
        }
        initCtrlEvent() {
        }
        initSendMsg() {
            mvc.crossArenaCtrl.reqArenaInfo();
        }
        onAwake() {
            super.onAwake();
            this.listShow.itemRender = mvc.UnitCrossChallengeItem;
            this.listShow.renderHandler = Laya.Handler.create(this, this.renderList, null, false);
            this.btnRefresh.on(Laya.Event.CLICK, this, this._onRefresh);
            this.updateCoin();
        }
        updateCoin() {
            let type = mvc.MainConst.ITEM_ID;
            let num = mvc.crossArenaModel.getMaxChallenge();
            this.unitCur.updateData("", [type.CROSS_ARENA_COUPON], true, [num]);
        }
        updateView() {
            this.listShow.array = mvc.crossArenaModel.arenaInfo.opponents;
            let cfg = mgr.toolsMgr.getGlobalVoById("arena_refresh_cost_cross", 1);
            this.lblMoney.text = cfg[0][1];
            mgr.icon.drawTexture(mgr.icon.getIconPath(mgr.toolsMgr.getIconById(cfg[0][0])), this.imgIcon);
            if (mvc.crossArenaModel.arenaInfo.refresh_time) {
                this.repeats(1000, this.onCdTime, true);
            }
            else {
                this.lblTime.visible = false;
            }
        }
        onCdTime() {
            let time = mvc.crossArenaModel.arenaInfo.refresh_time - sg.time.getSecondTime();
            this.btnRefresh.disabled = this.lblTime.visible = time > 0;
            if (time > 0) {
                this.lblTime.text = mgr.UIAssist.$(sg.translate("{1}后可刷新"), sg.time.formatTimeStrT("F0", time));
            }
            else {
                this.stopTimer(this.onCdTime);
            }
        }
        renderList(unit) {
            unit.updateView(unit.dataSource);
        }
        redChangeShow() {
            mgr.redotMgr.check(mvc.REDOT_ID.CROSS_ARENA_RED);
        }
        _onRefresh() {
            let cfg = mgr.toolsMgr.getGlobalVoById("arena_refresh_cost_cross", 1);
            if (!mgr.toolsMgr.checkConsume(cfg, true)) {
                return;
            }
            if (mvc.crossArenaModel.refreshTime == 0 || mvc.crossArenaModel.refreshTime - sg.time.getSecondTime() <= 0) {
                mvc.mainModel.consumeJade(cfg, 1, () => {
                    mvc.crossArenaCtrl.reqArenaRefresh();
                });
            }
            else {
                sg.uimgr.showNotice(sg.translate("cd时间"));
            }
        }
    }
    mvc.PopCrossChallengList = PopCrossChallengList;
})(mvc || (mvc = {}));

