var mvc;
(function (mvc) {
    class PopCrossRewardPre extends ui.view.faArena.pop_faRewardPreUI {
        initView() {
            this._curIndex = 0;
            this._curRoleIndex = 0;
        }
        initModelEvent() {
            this.bindModelEvent(mvc.crossArenaModel, mvc.CrossArenaConst.EVT.ARENA_INFO, this.updateInfo);
        }
        initCtrlEvent() {
        }
        initSendMsg() {
            mvc.crossArenaCtrl.reqArenaInfo();
        }
        onAwake() {
            super.onAwake();
            this.listGuild.vScrollBarSkin = this.listReward.vScrollBarSkin = null;
            this.listGuild.itemRender = this.listReward.itemRender = mvc.UnitCrossPreItem;
            this.listReward.renderHandler = this.createHandler(this, this.renderList, null, false);
            this.listGuild.renderHandler = Laya.Handler.create(this, this.renderGuildList, null, false);
            this.btnGet.on(Laya.Event.CLICK, this, this._onGetClick);
            this.btnDay.on(Laya.Event.CLICK, this, this._onBtnSelect, [0]);
            this.btnWeek.on(Laya.Event.CLICK, this, this._onBtnSelect, [1]);
            this.tab.selectHandler = Laya.Handler.create(this, this.onTabSelect, null, false);
        }
        updateInfo() {
            if (this.tab.selectedIndex == this._curIndex) {
                this.updateView();
            }
            else {
                this.tab.selectedIndex = this._curIndex;
            }
        }
        updateView() {
            this.boxGuild.visible = this.boxMan.visible = false;
            if (this._curIndex == 0) {
                this.boxMan.visible = true;
                let info = mvc.crossArenaModel.arenaInfo;
                this.listReward.array = mvc.crossArenaModel.getRankReward(mvc.ArenaConst.ArenaType.arena_cross, this._curRoleIndex + 1);
                this.red0.visible = info.day_reward == 1 || info.week_reward == 1;
                let index = info.week_rank ? info.week_rank : 0;
                this.sprDay.visible = info.day_reward == 1;
                this.sprWeek.visible = info.week_reward == 1;
                if (this._curRoleIndex == 1) {
                    this.btnDay.selected = false;
                    this.btnWeek.selected = true;
                    this.lblTimeTitle.text = sg.translate("每周奖励倒计时：");
                    this.btnGet.disabled = info.week_reward == 0;
                    this.lblNotice.text = sg.translate("每周日22:00将根据排名发放奖励，奖励如下：");
                }
                else {
                    this.btnDay.selected = true;
                    this.btnWeek.selected = false;
                    index = info.day_rank ? info.day_rank : 0;
                    this.lblTimeTitle.text = sg.translate("每日奖励倒计时：");
                    this.btnGet.disabled = info.day_reward == 0;
                    this.lblNotice.text = sg.translate("每日22:00将根据排名发放奖励，奖励如下：");
                }
                this.fontClip.visible = index > 0;
                this.imgNo.visible = index <= 0;
                this.fontClip.value = index.toString();
                this.redGot.visible = !this.btnGet.disabled;
                this.repeats(1000, this.loopUpdateTime, true);
            }
            else {
                this.boxGuild.visible = true;
                this.stopTimer(this.loopUpdateTime);
                this.listGuild.array = mvc.crossArenaModel.getRankReward(mvc.ArenaConst.ArenaType.arena_cross, this._curIndex + 2);
            }
        }
        loopUpdateTime() {
            let act = mvc.activityModel.openActivityVo.get(mvc.FUNC_ID.CROSS_ARENA);
            if (this._curRoleIndex == 1) {
                let time = act ? act.end_time - sg.time.getSecondTime() : 0;
                if (time > 0) {
                    this.lblTime.text = sg.time.formatTimeStrT("F0_1", time);
                }
                else {
                    this.lblTime.text = sg.translate("已结束");
                    this.stopTimer(this.loopUpdateTime);
                }
            }
            else {
                let time = mvc.crossArenaModel.getDayTime();
                if (time > 0) {
                    this.lblTime.text = sg.time.formatTimeStrT("F0_1", time / 1000);
                }
                else {
                    this.lblTime.text = sg.translate("已结束");
                    this.stopTimer(this.loopUpdateTime);
                }
            }
        }
        renderList(unit) {
            unit.updateView(unit.dataSource, this._curIndex);
        }
        renderGuildList(unit) {
            unit.updateView(unit.dataSource, this._curIndex);
        }
        onTabSelect(index) {
            this._curIndex = index;
            this.updateView();
        }
        _onBtnSelect(index) {
            this._curRoleIndex = index;
            this.updateView();
        }
        _onGetClick() {
            if (this._curRoleIndex == 0) {
                mvc.crossArenaCtrl.reqArenaGetReward(Proto.ARENA_REWARD.DAY);
            }
            else {
                mvc.crossArenaCtrl.reqArenaGetReward(Proto.ARENA_REWARD.WEEK);
            }
        }
    }
    mvc.PopCrossRewardPre = PopCrossRewardPre;
})(mvc || (mvc = {}));

