var mvc;
(function (mvc) {
    let EVT = mvc.CrossActiveConst.EVT;
    class CrossActiveModel extends sg.ModelBase {
        initModel() {
        }
        registerEvents() {
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.CROSS_TASK, this._checkRedTask, this);
        }
        initTaskInfo(data) {
            this.is_enter = data.is_enter;
            this.is_show_cross = data.is_show_cross;
            this.curTask = data.current_task;
            this.finished = data.finished;
            this.received = data.received;
            this.curOwnTask = new Proto.task_accepted();
            let cfg = sg.dbmgr.getDB("crossActive_crossTask", true);
            if (this.received.length < cfg.length) {
                for (let i = 0, len = cfg.length; i < len; i++) {
                    let id = cfg[i].id;
                    if (this.received.indexOf(id) == -1) {
                        this.curOwnTask.id = id;
                        if (this.curTask && this.curOwnTask.id == this.curTask.id)
                            this.curOwnTask.progress = this.curTask.progress;
                        else
                            this.curOwnTask.progress = cfg[i].need[2];
                        break;
                    }
                }
            }
            else {
                this.curOwnTask = this.curTask;
            }
            this.updateRewardState();
            this.fireEvent(EVT.UPDATE_VIEW);
            this.fireEvent(EVT.UPDATE_TASK_BTN);
            mgr.redotMgr.check(mvc.REDOT_ID.CROSS_TASK);
        }
        initCrossInfo(data) {
            this.is_cross_succeed = data.is_cross_succeed;
            this.is_open_activity = data.is_open_activity;
            this.svr_list = data.svr_list;
            this.score = data.score;
            this.fireEvent(EVT.UPDATE_VIEW);
        }
        getTaskReward(data) {
            sg.uimgr.showUI("pop_getReward", sg.translate("任务奖励"), data.reward);
            mvc.crossActiveCtrl.reqTaskInfo();
        }
        updateRewardState() {
            if (!mgr.conditionMgr.checkFunc(mvc.FUNC_ID.FAIRYLAND, false)) {
                this.haveReward = false;
                return;
            }
            if (this.curOwnTask) {
                let cfg = sg.dbmgr.get("crossActive_crossTask", this.curOwnTask.id);
                this.haveReward = this.curOwnTask.progress >= cfg.need[2];
            }
            else {
                this.haveReward = false;
            }
        }
        taskFinish() {
            mvc.crossActiveCtrl.reqTaskInfo();
        }
        _checkRedTask() {
            return this.haveReward ? 1 : 0;
        }
        getServerNameById(id) {
            let sevList = mvc.loginModel.gameServerList;
            let name = "";
            for (let i = 0, len = sevList.length; i < len; i++) {
                if (id == sevList[i].id) {
                    name = sevList[i].name;
                    break;
                }
            }
            return name;
        }
        crossReset(data) {
            this.is_show_cross = 0;
            this.fireEvent(EVT.UPDATE_VIEW);
            this.fireEvent(EVT.CROSS_RESET);
            this.fireEvent(EVT.UPDATE_SERVER_VIEW);
            mvc.manorModel.crossShowInfo();
        }
        checkMergeServe(funcId) {
            let act = mvc.activityModel.openActivityVo.get(funcId);
            if (!act) {
                let time = sg.time.subtractDate(mvc.roleModel.roleInfo.mergeServeTime * 1000, sg.time.getTime());
                if (time < 7) {
                    sg.uimgr.showNotice(StringEx.format(sg.translate("合服位面变化 活动周一0点10分重新开启")));
                    return false;
                }
            }
            return true;
        }
    }
    mvc.CrossActiveModel = CrossActiveModel;
})(mvc || (mvc = {}));

