(function (mvc) {
    class PopCrossTask extends ui.view.crossActive.pop_crossTaskUI {
        initView(isInCross = false) {
            this._model = mvc.crossActiveModel;
            this._ctrl = mvc.crossActiveCtrl;
            this._isInCross = isInCross;
        }
        initSendMsg() {
        }
        initModelEvent() {
            this.bindModelEvent(this._model, mvc.CrossActiveConst.EVT.UPDATE_VIEW, this._updateView);
        }
        initCtrlEvent() {
            this.rewardList.renderHandler = this.createHandler(this, this._onRewardList, null, false);
            this.serverList.renderHandler = this.createHandler(this, this._onServerList, null, false);
            this.btnGet.on(Laya.Event.CLICK, this, this._onBtnGet);
            this.btnJoin.on(Laya.Event.CLICK, this, this._onBtnJoin);
            this.redotTask.id = mvc.REDOT_ID.CROSS_TASK;
        }
        onAwake() {
            super.onAwake();
            this.lblFailTip.text = sg.translate("位面能量过高,没有位面世界可以匹配");
        }
        onEnable() {
            super.onEnable();
        }
        onDisable() {
            super.onDisable();
            this.stopTimer(this._updateTime);
        }
        _updateView() {
            this.taskBox.visible = this.matchBox.visible = this.successBox.visible = false;
            if (this._model.is_open_activity) {
                if (this._model.haveReward) {
                    this.taskBox.visible = true;
                    this._updateTaskBox();
                }
                else {
                    if (this._isInCross) {
                        if (this._model.curOwnTask) {
                            this.taskBox.visible = true;
                            this._updateTaskBox();
                        }
                        else {
                            this.closeSelf();
                        }
                    }
                    else {
                        this.successBox.visible = true;
                        this._updateSuccessBox();
                    }
                }
            }
            else {
                if (this._model.curOwnTask) {
                    this.taskBox.visible = true;
                    this._updateTaskBox();
                }
                else {
                    this.matchBox.visible = true;
                    this._updateMatchBox();
                }
            }
        }
        _updateTaskBox() {
            let cfg = sg.dbmgr.get("crossActive_crossTask", this._model.curOwnTask.id);
            this.lblStage.text = cfg.taskTitle;
            this.lblTitle.text = cfg.name;
            let progress = this._model.curOwnTask.progress;
            this.proTask.value = progress / cfg.need[2];
            this.lblTaskVal.text = `${progress}/${cfg.need[2]}`;
            let vo = mvc.ItemVo.createItemVos(cfg.rewardItem);
            this.rewardList.array = vo;
            let isDone = progress >= cfg.need[2];
            this.btnGet.label = isDone ? sg.translate("领取") : sg.translate("未完成");
            this.btnGet.disabled = !isDone;
            this.imgDone.visible = isDone;
            this.redotTask.visible = isDone;
        }
        _updateMatchBox() {
            let maxEnergy = mgr.toolsMgr.getGlobalVoById("cross_match_limit", 1);
            let energy = Math.min(this._model.score, maxEnergy);
            this.proEnergy.value = energy / maxEnergy;
            this.lblEnergyVal.text = `${energy}/${maxEnergy}`;
            this.repeats(1000, this._updateTime, true);
        }
        _updateSuccessBox() {
            if (this._model.svr_list.length > 0) {
                this.serverList.visible = true;
                this.lblFailTip.visible = false;
                this.lblMatch.text = sg.translate("匹配成功");
                this.serverList.array = this._model.svr_list;
                if (this.serverList.array.length > 2)
                    this.serverList.hScrollBarSkin = "";
                let condition = mgr.toolsMgr.getGlobalVoById("cross_enter_state", 1);
                let cfg = sg.dbmgr.get("role_roleLevel", condition[0][1]);
                let v1 = cfg.state;
                this.lblTip.text = StringEx.format(sg.translate("境界达到${v1}可进入"), {"v1":v1});
                this.lblTip.color = mgr.conditionMgr.check(condition, false) ? mvc.COLOR.GREEN : mvc.COLOR.RED;
            }
            else {
                this.lblMatch.text = sg.translate("匹配失败");
                this.serverList.visible = false;
                this.lblFailTip.visible = true;
            }
        }
        _onRewardList(cell, idx) {
            let data = cell.dataSource;
            if (!data)
                return;
            cell.initView(data);
        }
        _onServerList(cell, idx) {
            let data = cell.dataSource;
            if (!data)
                return;
            let lblServerName = cell.getChildByName("lblServerName");
            let imgVs = cell.getChildByName("imgVs");
            lblServerName.text = this._model.getServerNameById(data[0]);
            imgVs.visible = idx != this.serverList.length - 1;
        }
        _onBtnGet() {
            if (this._model.curOwnTask)
                this._ctrl.reqTeskReceiveReward(this._model.curOwnTask.id);
        }
        _updateTime() {
            let crossTime = mgr.toolsMgr.getGlobalVoById("cross_time", 1);
            let openDay = mvc.roleModel.roleInfo.openDayServer;
            let targetTime = sg.time.getTimeZeroToDay() - 86400 + (crossTime - openDay) * 86400;
            let time = targetTime - sg.time.getSecondTime();
            if (time <= 0) {
                this.stopTimer(this._updateTime);
                this.lblTime.text = sg.translate("正在扩大范围查找中");
            }
            else {
                if (time < 86400) {
                    let v1 = sg.time.formatTimeStrT("F2", time);
                    this.lblTime.text = StringEx.format(sg.translate("预计${v1}后匹配成功"), {"v1":v1});
                }
                else {
                    let v1 = Math.floor(time / (24 * 60 * 60));
                    this.lblTime.text = StringEx.format(sg.translate("预计${v1}天后匹配成功"), {"v1":v1});
                }
            }
        }
        _onBtnJoin() {
            let condition = mgr.toolsMgr.getGlobalVoById("cross_enter_state", 1);
            if (mgr.conditionMgr.check(condition, true)) {
                mvc.crossActiveCtrl.reqTaskEnter();
                sg.uimgr.showUI("sys_crossScene", true);
                this.closeSelf();
            }
        }
    }
    mvc.PopCrossTask = PopCrossTask;
})(mvc || (mvc = {}));

