(function (mvc) {
    class CrossActiveCtrl extends sg.CtrlBase {
        initCtrl() {
            this._model = mvc.crossActiveModel;
        }
        registerMsg() {
            this.onMsg(Proto.GLOBAL_TASK_INFO, this._onMsgTaskInfo);
            this.onMsg(Proto.GLOBAL_TASK_RECEIVE_REWARD, this._onMsgTaskReceiveReward);
            this.onMsg(Proto.GLOBAL_TASK_ENTER, this._onMsgTaskEnter);
            this.onMsg(Proto.GLOBAL_TASK_OPEN, this._onMsgTaskOpen);
            this.onMsg(Proto.GLOBAL_TASK_FINISH, this._onMsgTaskFinish);
            this.onMsg(Proto.QUERY_CROSS_INFO, this._onMsgCrossInfo);
            this.onMsg(Proto.CROSS_GROUP_RESET, this._onMsgCrossReset);
        }
        reqAllInfo() {
            this.reqCrossInfo();
            this.reqTaskInfo();
        }
        reqTaskInfo() {
            let req = this.createProto(Proto.global_task_info_request);
            this.sendMsg(Proto.GLOBAL_TASK_INFO, req);
        }
        _onMsgTaskInfo(data) {
            this._model.initTaskInfo(data);
        }
        reqTeskReceiveReward(task_id) {
            let req = this.createProto(Proto.global_task_receive_reward_request);
            req.task_id = task_id;
            this.sendMsg(Proto.GLOBAL_TASK_RECEIVE_REWARD, req);
        }
        _onMsgTaskReceiveReward(data) {
            this._model.getTaskReward(data);
        }
        reqTaskEnter() {
            let req = this.createProto(Proto.global_task_enter_request);
            this.sendMsg(Proto.GLOBAL_TASK_ENTER, req);
        }
        _onMsgTaskEnter(data) {
            this._model.is_enter = 1;
        }
        reqTaskOpen() {
            let req = this.createProto(Proto.global_task_open_request);
            this.sendMsg(Proto.GLOBAL_TASK_OPEN, req);
        }
        _onMsgTaskOpen(data) {
            this._model.is_show_cross = 1;
        }
        _onMsgTaskFinish(data) {
            this._model.taskFinish();
        }
        reqCrossInfo() {
            let req = this.createProto(Proto.query_cross_info_request);
            this.sendMsg(Proto.QUERY_CROSS_INFO, req);
        }
        _onMsgCrossInfo(data) {
            this._model.initCrossInfo(data);
        }
        _onMsgCrossReset(data) {
            this._model.crossReset(data);
        }
    }
    mvc.CrossActiveCtrl = CrossActiveCtrl;
})(mvc || (mvc = {}));

