(function (mvc) {
    class EquipAttrVo extends sg.VoBase {
        constructor() {
            super();
            this.mainAttr = [];
            for (let i = 1; i <= 4; i++) {
                let cfg = sg.dbmgr.get("attribute", i);
                this.mainAttr.push({
                    lblName: cfg.show_name,
                    lblValue: "0",
                    value: 0,
                    isPer: cfg.is_per == 1
                });
            }
            this.subAttr = [];
        }
        updateData(data) {
            for (let attr of this.mainAttr) {
                attr.value = 0;
            }
            this.subAttr.length = 0;
            for (let key in data) {
                let attr = data[key];
                if (isNaN(attr) || attr == 0)
                    continue;
                let cfg = mvc.PropertyModel._getCfg(key);
                if (!cfg)
                    continue;
                if (cfg.show_priority != 1) {
                    this.subAttr.push({
                        lblName: cfg.show_name,
                        lblValue: cfg.is_per == 1 ? (attr / 100) + "%" : attr.toString(),
                        value: attr,
                        isPer: cfg.is_per == 1
                    });
                }
                else {
                    this.mainAttr[cfg.id - 1].value = attr;
                    this.mainAttr[cfg.id - 1].lblValue = attr.toString();
                }
            }
        }
        updateDataByArray(data) {
            for (let attr of this.mainAttr) {
                attr.value = 0;
            }
            this.subAttr.length = 0;
            for (let item of data) {
                let attr = item[1];
                let cfg = sg.dbmgr.get("attribute", item[0]);
                if (!cfg)
                    continue;
                if (cfg.show_priority != 1) {
                    this.subAttr.push({
                        lblName: cfg.show_name,
                        lblValue: cfg.is_per == 1 ? (attr / 100) + "%" : attr.toString(),
                        value: attr,
                        isPer: cfg.is_per == 1
                    });
                }
                else {
                    this.mainAttr[cfg.id - 1].value = attr;
                    this.mainAttr[cfg.id - 1].lblValue = attr.toString();
                }
            }
        }
    }
    mvc.EquipAttrVo = EquipAttrVo;
})(mvc || (mvc = {}));

