                    let attrs = [];
                    for (let attr of cfg.preview) {
                        let attrCfg = mvc.PropertyModel._getCfg(attr[0]);
                        attrs.push({
                            lblName: attrCfg.show_name,
                            lblAttrMin: attrCfg.is_per ? (attr[1] / 100) + "%" : attr[1].toString(),
                            lblAttrMax: attrCfg.is_per ? (attr[2] / 100) + "%" : attr[2].toString()
                        });
                    }
