(function (mvc) {
    class PopEquipAutoDecompose extends ui.view.equipment.pop_autoDecomposeUI {
        initView() {
            this._model = mvc.equipModel;
            this._ctrl = mvc.equipCtrl;
        }
        initSendMsg() {
        }
        initModelEvent() {
        }
        initCtrlEvent() {
            this.btnDecompose.on(Laya.Event.CLICK, this, this._onBtn);
        }
        onAwake() {
            super.onAwake();
            let quas = sg.varmgr.getUserVar("equip_auto_decompose_quas") || [];
            for (let qua of quas) {
                let cb = this.boxSelect.getChildAt(qua);
                cb.selected = true;
            }
        }
        onEnable() {
            super.onEnable();
        }
        onDisable() {
            super.onDisable();
        }
        _onBtn() {
            let selectQua = [];
            for (let i = 1; i < this.boxSelect.numChildren; i++) {
                let cb = this.boxSelect.getChildAt(i);
                if (cb.selected) {
                    selectQua.push(i);
                }
            }
            if (selectQua.length == 0) {
                sg.uimgr.showNotice(sg.translate("没有勾选需要分解的装备品阶"));
            }
            else {
                let allEquip = this._model.getAllEquip();
                let ids = [];
                for (let e of allEquip) {
                    if (selectQua.indexOf(e.getCfg().quality) != -1) {
                        ids.push(e.bagId);
                    }
                }
                if (ids.length > 0) {
                    this._ctrl.reqDecomposeEquip(ids);
                }
                else {
                    sg.uimgr.showNotice(sg.translate("没有此品阶的装备可以分解"));
                }
                sg.varmgr.setUserVar("equip_auto_decompose_quas", selectQua);
                this.closeSelf();
            }
        }
    }
    mvc.PopEquipAutoDecompose = PopEquipAutoDecompose;
})(mvc || (mvc = {}));

