(function (mvc) {
    class PopFashionUpgrade extends ui.view.equipment.pop_fashionUpgradeUI {
        initView(id) {
            this._model = mvc.equipModel;
            this._id = id;
        }
        initModelEvent() {
        }
        initCtrlEvent() {
            this.listProp.vScrollBarSkin = "";
            this.btnLvUp.on(Laya.Event.CLICK, this, this._onClick);
        }
        onEnable() {
            super.onEnable();
            this._updateView();
        }
        updateWhenNetReConn() {
            this._updateView();
        }
        _updateView() {
            if (this._model.vo) {
                let level = this._model.vo.skinLevelMap.get(this._id);
                this._cfg = sg.dbmgr.getArray("fashion_fashionLevel", { fashion: this._id, level: level })[0];
                mgr.icon.drawTexture(mgr.icon.getIconPath(mgr.toolsMgr.getIconById(this._cfg.consume[0][0])), this.sprCost);
                this.lblCost.text = `${mgr.toolsMgr.getCountById(this._cfg.consume[0][0])}/${this._cfg.consume[0][1]}`;
                let isEnough = mgr.toolsMgr.checkConsume(this._cfg.consume, false);
                this.lblCost.color = isEnough ? mvc.COLOR.GREEN : mvc.COLOR.RED;
                this.redotLvUp.visible = isEnough;
                let lastAttrs = this._model.getSkinAttrById(this._cfg.fashion, level);
                let nextAttrs = this._model.getSkinAttrById(this._cfg.fashion, level + 1);
                this._setAttrs(lastAttrs, nextAttrs);
            }
        }
        _setAttrs(lastAttrs, nextAttrs) {
            let attrs = [];
            for (let i = 0, len = lastAttrs.length; i < len; i++) {
                let attr = lastAttrs[i];
                let nextAttr = nextAttrs[i];
                attrs.push({
                    id: sg.dbmgr.getArray("attribute", { show_name: attr.lblName })[0].id,
                    lblPropName: attr.lblName + ":",
                    lblCurPropValue: attr.lblValue,
                    lblNextPropValue: nextAttr.lblValue,
                });
            }
            attrs.sort((a, b) => {
                return a.id - b.id;
            });
            this.listProp.array = attrs;
        }
        _onClick() {
            if (mgr.toolsMgr.checkConsume(this._cfg.consume, true)) {
                mvc.equipCtrl.reqSkinLvUp(this._cfg.fashion);
                this.closeSelf();
            }
        }
    }
    mvc.PopFashionUpgrade = PopFashionUpgrade;
})(mvc || (mvc = {}));

