            this._vo = vo;
            let cfg = vo.getCfg();
            this.unitIcon.initView(vo);
            let scfg = sg.dbmgr.get("color", cfg.quality);
            this.lblState.text = "[" + scfg.qualityName + "]";
            this.lblState.color = scfg.stringColor;
            this.lblName.text = cfg.name;
            this.lblName.color = scfg.stringColor;
            this.lblName.strokeColor = scfg.strokeColor;
