(function (mvc) {
    class BoxPerformanceSpine extends Laya.Box {
        constructor() {
            super(...arguments);
            this._spines = [];
            this._skeletons = [];
            this._createMode = 1;
            this._id = "9001";
            this._allData = [];
            this._lastSelModelIdx = 0;
            this._isPause = false;
        }
        onAwake() {
            super.onAwake();
            let Event = Laya.Event;
            let btnAdd = this.getChildByName("btnAdd");
            btnAdd.on(Event.CLICK, this, this._onBtnAdd);
            let btnSub = this.getChildByName("btnSub");
            btnSub.on(Event.CLICK, this, this._onBtnSub);
            let btnPause = this.getChildByName("btnPause");
            btnPause.on(Event.CLICK, this, this._onBtnPause);
            let btnRandom = this.getChildByName("btnRandom");
            btnRandom.on(Event.CLICK, this, this._btnRandom);
            let btnClear = this.getChildByName("btnClear");
            btnClear.on(Event.CLICK, this, this._btnClear);
            this._boxContent = this.getChildByName("boxContent");
            let combIds = this.getChildByName("combIds");
            combIds.selectHandler = Laya.Handler.create(this, this.onSelectComboIds, null, false);
            combIds.scrollBarSkin = "";
            this._combIds = combIds;
            let btnLeftId = this.getChildByName("btnLeftId");
            btnLeftId.on(Laya.Event.CLICK, this, this.onBtnLeftId);
            let btnRightId = this.getChildByName("btnRightId");
            btnRightId.on(Laya.Event.CLICK, this, this.onBtnRightId);
            this._initIds();
        }
        onDisable() {
            super.onDisable();
            for (let spine of this._spines) {
                spine.recycle();
            }
            this._spines.length = 0;
            for (let skeleton of this._skeletons) {
                skeleton.destroy();
            }
            this._skeletons.length = 0;
        }
        _initIds() {
            let labels = [];
            let cfgs = sg.dbmgr.getDB("skModel");
            for (let key in cfgs) {
                let cfg = cfgs[key];
                labels.push(`${cfg["id"]} ${cfg["name"]}`);
                this._allData.push(cfg);
            }
            this._combIds.labels = labels.join(",");
            this._combIds.selectedIndex = this._lastSelModelIdx;
        }
        _onBtnAdd(e) {
            if (this._createMode == 1) {
                this._createSpine();
            }
            else if (this._createMode == 2) {
                this._createLaysSpine();
            }
        }
        _onBtnSub() {
            if (this._createMode == 1) {
                this._delSpine();
            }
            else if (this._createMode == 2) {
                this._delLayaSpine();
            }
        }
        _onBtnPause(e) {
            this._isPause = !this._isPause;
            let btn = e.target;
            if (this._isPause) {
                btn.label = "resume";
            }
            else {
                btn.label = "pause";
            }
            this._change();
        }
        _change() {
            for (let spine of this._spines) {
                if (this._isPause) {
                    spine.pause();
                }
                else {
                    spine.resume();
                }
            }
        }
        _btnRandom() {
            for (let i = 1; i <= 10; i++) {
                let number = this._allData.length;
                let index = Math.floor(Math.random() * number);
                let cfg = this._allData[index];
                let id = '';
                if (cfg) {
                    id = cfg.id;
                }
                this._createSpine(id);
            }
            this._change();
        }
        _btnClear() {
            super.onDisable();
            for (let spine of this._spines) {
                spine.recycle();
            }
            this._spines.length = 0;
            for (let skeleton of this._skeletons) {
                skeleton.destroy();
            }
            this._skeletons.length = 0;
        }
        _createSpine(id) {
            let spine;
            if (id) {
                spine = sg.SpineSprite.create(id, true, true);
            }
            else {
                spine = sg.SpineSprite.create(this._id, true, true);
            }
            let x = Math.ceil(Math.random() * (this._boxContent.width - 10)) + 10;
            let y = Math.ceil(Math.random() * (this._boxContent.height - 30)) + 30;
            spine.x = x;
            spine.y = y;
            this._boxContent.addChild(spine);
            this._spines.push(spine);
        }
        _delSpine() {
            if (this._spines.length == 0)
                return;
            let spine = this._spines.pop();
            spine.recycle();
        }
        _createLaysSpine() {
            var skeleton = new Laya.Skeleton();
            skeleton.load("res/sk_test/v3_7/9001/show.sk", Laya.Handler.create(null, () => {
                skeleton.play(0, true);
            }));
            let x = Math.ceil(Math.random() * (this._boxContent.width - 10)) + 10;
            let y = Math.ceil(Math.random() * (this._boxContent.height - 30)) + 30;
            skeleton.x = x;
            skeleton.y = y;
            this._boxContent.addChild(skeleton);
            this._skeletons.push(skeleton);
        }
        _delLayaSpine() {
            if (this._skeletons.length == 0)
                return;
            let skeleton = this._skeletons.pop();
            skeleton.destroy();
        }
        onSelectComboIds(index) {
            if (index === -1)
                return;
            this._lastSelModelIdx = index;
            let cfg = this._allData[index];
            if (cfg) {
                this._id = cfg.id;
            }
        }
        onBtnLeftId() {
            this._combIds.selectedIndex = (this._lastSelModelIdx - 1) > 0 ? this._lastSelModelIdx - 1 : 0;
        }
        onBtnRightId() {
            this._combIds.selectedIndex = (this._lastSelModelIdx + 1) < this._allData.length ? this._lastSelModelIdx + 1 : this._lastSelModelIdx;
        }
    }
    mvc.BoxPerformanceSpine = BoxPerformanceSpine;
})(mvc || (mvc = {}));

