(function (mvc) {
    class PopMoveTest extends ui.view.demo.pop_moveTestUI {
        constructor() {
            super(...arguments);
            this._cache = {};
            this._bgSpeed = 1136 / 5000;
            this._monsterSpeed = 1136 / 4000;
            this._runMonster = [];
        }
        onAwake() {
            super.onAwake();
            this._init();
            Laya.Stat.show(0, 100);
            Laya.stage.frameRate = Laya.Stage.FRAME_FAST;
        }
        onEnable() {
            super.onEnable();
        }
        onDisable() {
            super.onDisable();
            Laya.timer.clear(this, this._loop);
            Laya.stage.frameRate = Laya.Stage.FRAME_SLOW;
        }
        _init() {
            let skels = [
                9022,
                9024,
                9025,
            ];
            for (let id of skels) {
                this._cache[id] = sg.SpineSprite.create(id + "");
            }
            let bgUrl = "ui/innerGame/img_cg_bf.png";
            let bulletUrl = "uieffect/common/jian_all.png";
            let monsters = [
                "res/uidata/innerGame/1001.png",
                "res/uidata/innerGame/1002.png",
                "res/uidata/innerGame/1003.png",
                "res/uidata/innerGame/1004.png",
                "res/uidata/innerGame/1005.png",
                "res/uidata/innerGame/1006.png",
            ];
            let count = 3;
            let loadEnd = (flag) => {
                count--;
                if (count == 0) {
                    this._cache["bg"] = new Laya.Image(bgUrl);
                    this._cache["bg2"] = new Laya.Image(bgUrl);
                    this._cache["bullet"] = new Laya.Clip(bulletUrl, 3, 1);
                    this._initScene();
                }
            };
            Laya.loader.load(bgUrl, Laya.Handler.create(null, loadEnd, ["bg"]));
            Laya.loader.load(bulletUrl, Laya.Handler.create(null, loadEnd, ["bullet"]));
            Laya.loader.load(monsters, Laya.Handler.create(null, loadEnd, ["monsters"]));
        }
        _initScene() {
            let root = this.boxMap;
            {
                let boxBg = new Laya.Box();
                root.addChild(boxBg);
                this._boxBg = boxBg;
                let bg = this._cache["bg"];
                boxBg.addChild(bg);
                let pos = bg.height;
                let bg2 = this._cache["bg2"];
                boxBg.addChild(bg2);
                bg2.y = pos;
                boxBg.width = bg.width;
                boxBg.height = bg.height * 2;
                boxBg.x = 0;
                boxBg.y = -bg.height;
            }
            {
                let hero = this._cache[9022];
                hero.x = root.width / 2;
                hero.y = root.height - 20;
                hero.play(0, true);
                root.addChild(hero);
            }
            Laya.timer.frameLoop(1, this, this._loop);
            Laya.timer.loop(1000, this, this._nextMonster);
        }
        _loop() {
            this._moveBg();
            this._moveMonster();
        }
        _moveBg() {
            let diff = Laya.timer.delta * this._bgSpeed;
            let pos = this._boxBg.y + diff;
            if (pos >= 0) {
                pos -= this._boxBg.height / 2;
            }
            this._boxBg.y = pos;
        }
        _moveMonster() {
            let diff = Laya.timer.delta * this._monsterSpeed;
            let h = this._boxBg.height;
            for (let m of this._runMonster) {
                let pos = m.y + diff;
                if (pos > h) {
                    m.destroy();
                }
                else {
                    m.y = pos;
                }
            }
        }
        _nextMonster() {
            let monsters = [
                "res/uidata/innerGame/1001.png",
                "res/uidata/innerGame/1002.png",
                "res/uidata/innerGame/1003.png",
                "res/uidata/innerGame/1004.png",
                "res/uidata/innerGame/1005.png",
                "res/uidata/innerGame/1006.png",
            ];
            let idx = Math.floor((Math.random() * 10) % monsters.length);
            let url = monsters[idx];
            let monster = new Laya.Image(url);
            this.boxMap.addChild(monster);
            monster.x = Math.random() * 640;
            monster.y = 0;
            this._runMonster.push(monster);
        }
    }
    mvc.PopMoveTest = PopMoveTest;
})(mvc || (mvc = {}));

