(function (mvc) {
    class DungeonEquBossVo extends sg.VoBase {
        updateData(info) {
            this.refresh_count = info.refresh_count;
            this.refresh_time = info.refresh_time;
            this.combat_count = info.combat_count;
            this.total_combat_count = info.total_combat_count;
            this.combat_time = info.combat_time;
            this.combat_count_buy = info.combat_count_buy;
            this.seek_count = info.seek_count;
            this.bosses = info.bosses;
            this.notices = info.notices;
        }
        hadTips() {
            if (!this.bosses)
                return 0;
            let star = 0;
            for (let i = 0; i < this.bosses.length; i++) {
                if (this.bosses[i] && this.bosses[i].star >= 4 && this.bosses[i].status == 1 && this.bosses[i].star > star) {
                    star = this.bosses[i].star;
                }
            }
            return star;
        }
        hadReward() {
            if (!this.bosses)
                return -1;
            for (let i = 0; i < this.bosses.length; i++) {
                if (this.bosses[i].status == 3) {
                    return i;
                }
            }
            return -1;
        }
        getBossIdx() {
            if (!this.bosses)
                return 0;
            for (let i = 0; i < this.bosses.length; i++) {
                if (this.bosses[i].status == 1) {
                    return i;
                }
            }
            return 0;
        }
    }
    mvc.DungeonEquBossVo = DungeonEquBossVo;
})(mvc || (mvc = {}));

