var mvc;
(function (mvc) {
    class DungeonDailyModel extends sg.ModelBase {
        initModel() {
            this._dailyDungeonMap = new Map();
        }
        registerEvents() {
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.DUNGEON_DAILY_SWEEP, this.checkMaterialSweep, this);
            mgr.redotMgr.onCheckFunc(mvc.REDOT_ID.DUNGEON_FLY_SWEEP, this.checkFlySweep, this);
        }
        setDailyDungeonInfos(msg) {
            for (let index = 0; index < msg.info.length; index++) {
                this._setDailyDungeonInfo(msg.info[index]);
            }
            this.fireEvent(mvc.DungeonDailyConst.EVT.UPDATE_INFO);
            mgr.redotMgr.check(mvc.REDOT_ID.DUNGEON_DAILY_SWEEP);
            mgr.redotMgr.check(mvc.REDOT_ID.DUNGEON_FLY_SWEEP);
        }
        _setDailyDungeonInfo(info) {
            let vo = this._dailyDungeonMap.get(info.type);
            if (!vo) {
                vo = new mvc.DungeonDailyVo();
                this._dailyDungeonMap.set(info.type, vo);
            }
            vo.updateData(info);
        }
        getDailyDungeonInfo(type) {
            return this._dailyDungeonMap.get(type);
        }
        dungeonDailyChallenge(msg) {
            this._lastReport = msg.combat_notify;
            mvc.battleModel.startBattle(msg.combat_notify, Proto.COMBAT_TYPE.DAILY, () => {
                mvc.dungeonDailyCtrl.reqDailyDungeonFinishCombat();
            });
        }
        dungeonDailyFinishCombat(msg) {
            let tip = "";
            if (msg.info) {
                this._setDailyDungeonInfo(msg.info);
                let cfg = sg.dbmgr.get("dailyBattle_dailyBattle", msg.info.id);
                tip = cfg.name;
            }
            sg.uimgr.showFbResult({ result: msg.result, desc: tip, reward: msg.reward }, this._lastReport);
            this._lastReport = null;
            this.fireEvent(mvc.DungeonDailyConst.EVT.UPDATE_INFO);
            mgr.redotMgr.check(mvc.REDOT_ID.DUNGEON_DAILY_SWEEP);
            mgr.redotMgr.check(mvc.REDOT_ID.DUNGEON_FLY_SWEEP);
        }
        dungeonDailySweep(msg) {
            this._setDailyDungeonInfo(msg.info);
            let cfg = sg.dbmgr.get("dailyBattle_dailyBattle", msg.info.id);
            sg.uimgr.showUI("pop_getReward", cfg.name, msg.reward);
            this.fireEvent(mvc.DungeonDailyConst.EVT.UPDATE_INFO);
            mgr.redotMgr.check(mvc.REDOT_ID.DUNGEON_DAILY_SWEEP);
            mgr.redotMgr.check(mvc.REDOT_ID.DUNGEON_FLY_SWEEP);
        }
        getInitId(fbType) {
            let arr = sg.dbmgr.getArray("dailyBattle_dailyBattle", { type: fbType });
            arr.sort(function (a, b) {
                return a.id - b.id;
            });
            return arr[0].id;
        }
        checkMaterialSweep() {
            if (!mgr.conditionMgr.checkFunc(mvc.FUNC_ID.DUNGEON_DAILY, false))
                return 0;
            let vo = this.getDailyDungeonInfo(mvc.DungeonDailyConst.FbType.NORMAL);
            if (vo && vo.free_count == 0 && vo.id > 0) {
                return 1;
            }
            return 0;
        }
        checkFlySweep() {
            if (!mgr.conditionMgr.checkFunc(mvc.FUNC_ID.DUNGEON_FLY, false))
                return 0;
            let vo = this.getDailyDungeonInfo(mvc.DungeonDailyConst.FbType.FLY);
            if (vo && vo.free_count == 0 && vo.id > 0) {
                return 1;
            }
            return 0;
        }
    }
    mvc.DungeonDailyModel = DungeonDailyModel;
})(mvc || (mvc = {}));

