(function (mvc) {
    class PopDungeonDaily extends ui.view.dungeonDaily.pop_dungeonDailyUI {
        constructor() {
            super(...arguments);
            this._funcIds = [mvc.FUNC_ID.DUNGEON_DAILY, mvc.FUNC_ID.DUNGEON_FLY];
        }
        initView() {
            this._tabIdx = 0;
        }
        initSendMsg() {
            mvc.dungeonDailyCtrl.reqDailyDungeonInfo();
        }
        initModelEvent() {
            this.bindModelEvent(mvc.dungeonDailyModel, mvc.DungeonDailyConst.EVT.UPDATE_INFO, this._updateView);
            this.bindModelEvent(mvc.roleModel, mvc.RoleConst.EVT.LEVEL_UP, this._updateTab);
        }
        initCtrlEvent() {
            this.tabDungeon.selectHandler = this.createHandler(this, this._onSelectTab, null, false);
            this.listPass.vScrollBarSkin = null;
            this.listPass.itemRender = mvc.UnitDungeonDailyItem;
            this.listPass.renderHandler = this.createHandler(this, this._onRenderList, null, false);
        }
        updateData(types, ...args) { }
        onAwake() {
            super.onAwake();
            this.redTipsDaily.id = mvc.REDOT_ID.DUNGEON_DAILY_SWEEP;
            this.redTipsFly.id = mvc.REDOT_ID.DUNGEON_FLY_SWEEP;
        }
        onEnable() {
            super.onEnable();
            this.tabDungeon.selectedIndex = 0;
            this._updateTab();
            this._updateView();
        }
        onJumpInit(jumpParams) {
            let funcId = jumpParams.funcId;
            switch (funcId) {
                case mvc.FUNC_ID.DUNGEON_DAILY:
                    {
                        this._tabIdx = 0;
                    }
                    break;
                case mvc.FUNC_ID.DUNGEON_FLY:
                    {
                        this._tabIdx = 1;
                    }
                    break;
            }
        }
        onDisable() {
            super.onDisable();
        }
        onClosed() {
            super.onClosed();
        }
        _updateTab() {
            for (let index = 0; index < this.tabDungeon.numChildren; index++) {
                if (!this._funcIds[index])
                    continue;
                let child = this.tabDungeon.getChildAt(index);
                if (child)
                    child.visible = mgr.conditionMgr.checkFunc(this._funcIds[index], false);
            }
        }
        _updateView() {
            if (this.tabDungeon.selectedIndex == this._tabIdx) {
                this._onSelectTab(this._tabIdx);
            }
            else {
                this.tabDungeon.selectedIndex = this._tabIdx;
                this._onSelectTab(this._tabIdx);
            }
        }
        _onSelectTab(index) {
            if (index == null) {
                return;
            }
            let arr = sg.dbmgr.getArray("dailyBattle_dailyBattle", { type: index + 1 });
            if (arr == null || arr.length == 0) {
                this.listPass.array = [];
                return;
            }
            arr.sort(function (a, b) {
                return a.id - b.id;
            });
            this.listPass.array = arr;
            let vo = mvc.dungeonDailyModel.getDailyDungeonInfo(index + 1);
            let idx = 0;
            for (let i = 0; i < arr.length; i++) {
                if (vo && arr[i].id == vo.id) {
                    idx = i;
                    break;
                }
            }
            this.listPass.scrollTo(idx);
            this._tabIdx = index;
        }
        _onSelectList(index) {
        }
        _onRenderList(cell, index) {
            if (!cell.dataSource)
                return;
            cell.setData(cell.dataSource);
        }
    }
    mvc.PopDungeonDaily = PopDungeonDaily;
})(mvc || (mvc = {}));

