(function (mvc) {
    class PopDungeonSweep extends ui.view.dungeonDaily.pop_dungeonDailyMopUI {
        initView(c) {
            this._cfg = c;
        }
        initSendMsg() {
        }
        initModelEvent() {
            this.bindModelEvent(mvc.dungeonDailyModel, mvc.DungeonDailyConst.EVT.UPDATE_INFO, this._updateView);
        }
        initCtrlEvent() {
            this.btnSweep.on(Laya.Event.CLICK, this, this._onBtnSweep);
            this.listItem.renderHandler = this.createHandler(this, this._onRenderList, null, false);
        }
        updateData(types, ...args) { }
        onAwake() {
            super.onAwake();
        }
        onEnable() {
            super.onEnable();
            this._updateView();
        }
        onJumpInit(jumpParams) {
        }
        onDisable() {
            super.onDisable();
        }
        onClosed() {
            super.onClosed();
        }
        _updateView() {
            if (this._cfg) {
                this.listItem.array = mvc.ItemVo.createItemVos(this._cfg.sweepRewards);
                let vo = mvc.dungeonDailyModel.getDailyDungeonInfo(this._cfg.type);
                if (vo) {
                    this.sprCostIcon.visible = this.lblCostNum.visible = false;
                    let str = "";
                    if (vo.free_count == 0) {
                        str = sg.translate("本次免费");
                    }
                    else if (vo.free_count > 0) {
                        if (vo.pay_count < this._cfg.jadeConsume.length) {
                            this.sprCostIcon.visible = this.lblCostNum.visible = true;
                            let needCount = this._cfg.jadeConsume[vo.pay_count];
                            this.lblCostNum.text = needCount;
                            this.lblCostNum.color = mgr.toolsMgr.checkConsume([[1, needCount]]) ? mgr.toolsMgr.getColor2("green") : mgr.toolsMgr.getColor2("red");
                            let url = mgr.toolsMgr.getIconById(1);
                            mgr.icon.drawTexture(mgr.icon.getIconPath(url), this.sprCostIcon);
                        }
                        str = sg.translate("今日剩余购买次数：") + (this._cfg.jadeConsume.length - vo.pay_count) + "/" + this._cfg.jadeConsume.length;
                    }
                    this.lblLastNum.text = str;
                    this.redTIps.visible = vo.free_count == 0;
                }
            }
        }
        _onRenderList(cell, index) {
            if (!cell.dataSource)
                return;
            cell.initView(cell.dataSource);
        }
        _onBtnSweep() {
            let vo = mvc.dungeonDailyModel.getDailyDungeonInfo(this._cfg.type);
            if (this._cfg && vo) {
                if (vo.free_count > 0) {
                    if (vo.pay_count >= this._cfg.jadeConsume.length) {
                        sg.uimgr.showNotice(sg.translate("今日可购买次数已用完"));
                        return;
                    }
                    let cost = [[1, this._cfg.jadeConsume[vo.pay_count]]];
                    if (mgr.toolsMgr.checkConsume(cost, false))
                        mvc.mainModel.consumeJade(cost, 1, () => {
                            mvc.dungeonDailyCtrl.reqDailyDungeonSweep(this._cfg.type);
                        });
                    else {
                        sg.uimgr.showNotice(sg.translate("仙玉不足"));
                    }
                }
                else
                    mvc.dungeonDailyCtrl.reqDailyDungeonSweep(this._cfg.type);
            }
        }
    }
    mvc.PopDungeonSweep = PopDungeonSweep;
})(mvc || (mvc = {}));

