(function (mvc) {
    let LOG_MODEL_CONFIG = {
        socket: false,
        net: false,
        msg: false,
        netctrl: false,
        view: false,
        uimgr: false,
        login: true,
        battle: false,
        music: false,
    };
    mvc.setLogConfigSwitch = (name, value) => {
        let varName = "log_conifg_" + name;
        sg.varmgr.setSysVar(varName, value);
        sg.Logger.registerLogOpen(name, value || LOG_MODEL_CONFIG[name]);
    };
    mvc.getLogConfigSwitch = (name) => {
        let varName = "log_conifg_" + name;
        let valueVar = sg.varmgr.getSysVar(varName);
        return valueVar != undefined ? valueVar : false;
    };
    mvc.registerLogConfig = () => {
        for (var name in LOG_MODEL_CONFIG) {
            let value = LOG_MODEL_CONFIG[name];
            let valueVar = mvc.getLogConfigSwitch(name);
            sg.Logger.registerLogOpen(name, valueVar || value);
        }
    };
})(mvc || (mvc = {}));

