(function (mvc) {
    mvc.initMvcLogin = function () {
        sg.UIMgr.UIMGR_EVT = mvc.UIMGR_EVT;
        sg.UIMgr.WIN_TYPE = mvc.WIN_TYPE;
        sg.Sound.UISound = mvc.UISound;
        mvc.registerViewConfigLogin();
        mvc.registerModels(mvc.MVC_CONFIG_LOGIN());
        mvc.registerUILoginCls();
    };
    mvc.initMvcGame = function () {
        mvc.registerViewConfigGame();
        mvc.registerModels(mvc.MVC_CONFIG_GAME());
        mvc.registerUIGameCls();
    };
    mvc.registerModels = function (cfg) {
        let ctrlN;
        let modelN;
        let ctrl;
        let model;
        for (let elment of cfg) {
            ctrlN = elment[0] + "Ctrl";
            ctrl = new elment[1];
            if (elment[2]) {
                model = new elment[2];
                model.init();
                ctrl.model = model;
                modelN = elment[0] + "Model";
                mvc[modelN] = model;
            }
            mvc[ctrlN] = ctrl;
            ctrl.init();
        }
    };
    mvc.resetModule = function (cfg) {
        let ctrlN;
        let modelN;
        for (let elment of cfg) {
            ctrlN = elment[0] + "Ctrl";
            let ctrl = mvc[ctrlN];
            ctrl.reset();
            ctrl.init();
            if (ctrl.model) {
                ctrl.model.init();
            }
        }
    };
    mvc.reloadGame = function () {
        mvc.resetModule(mvc.MVC_CONFIG_LOGIN());
        mvc.resetModule(mvc.MVC_CONFIG_GAME());
    };
})(mvc || (mvc = {}));

