var mvc;
(function (mvc) {
    class TabTable {
        constructor(tab, tabView, cBack) {
            this._lastIndex = -1;
            this.isOpen = [];
            this._tab = tab;
            if (tab) {
                this._lastIndex = tab.selectedIndex;
                tab.selectHandler = Laya.Handler.create(this, this.onTabSelect, null, false);
            }
            this._tabView = tabView;
            if (cBack)
                this._cBack = cBack;
            this._posx = tab.x;
        }
        setTabColor() {
            for (let i = 0; i < this._tab.numChildren; i++) {
                let ct = this._tab.getChildAt(i);
                let img = ct && ct.getChildByName("imgLock");
                let clip = ct && ct.getChildByName("clipEff");
                if (clip)
                    clip.visible = false;
                let b = false;
                for (let key in this.isOpen) {
                    if (parseInt(key) == i) {
                        if (this.isOpen[key].isOpen == false) {
                            b = true;
                        }
                        break;
                    }
                }
                if (b) {
                    ct.gray = true;
                    if (img)
                        img.visible = true;
                }
                else {
                    ct.gray = false;
                    if (img)
                        img.visible = false;
                }
            }
        }
        playEff(idx, isPlay) {
            for (let i = 0; i < this._tab.numChildren; i++) {
                if (i != idx)
                    continue;
                let ct = this._tab.getChildAt(i);
                let clip = ct && ct.getChildByName("clipEff");
                if (clip)
                    clip.visible = isPlay;
            }
        }
        resetPos(arr, isV = false) {
            this._arr = arr;
            this._tab.x = this._posx;
            if (!this._arr || this._arr.length <= 0) {
                this._tab.selectedIndex = -1;
                return;
            }
            let x = 0;
            for (let i = 0; i < this._tab.numChildren; i++) {
                let ct = this._tab.getChildAt(i);
                let idx = this._arr.indexOf(i);
                ct.visible = idx != -1;
                if (ct.visible) {
                    if (!isV) {
                        ct.x = x;
                        if (ct.anchorX == 0.5 && ct.anchorY == 0.5) {
                            ct.x = x + ct.width / 2;
                        }
                        x += ct.width;
                    }
                    else {
                        ct.y = x;
                        if (ct.anchorX == 0.5 && ct.anchorY == 0.5) {
                            ct.y = x + ct.height / 2;
                        }
                        x += ct.height;
                    }
                }
            }
        }
        initRedTipsId(arr) {
            for (let i = 0; i < this._tab.numChildren; i++) {
                let ct = this._tab.getChildAt(i);
                let redTips;
                if (ct)
                    redTips = ct.getChildByName("redTips");
                if (redTips) {
                    redTips.id = arr[i];
                }
            }
        }
        _changeClipIndex(index, state) {
            if (index == -1)
                return;
            let ct = this._tab.getChildAt(index);
            if (ct) {
                let clip = ct.getChildByName("clip");
                if (clip == null) {
                    clip = ct.getChildAt(0);
                }
                if (clip && clip.clipY == 2 && clip.clipX > 1) {
                    clip.index = state == 1 ? (clip.index % clip.clipX) : (clip.index % clip.clipX) + clip.clipX;
                }
                else if (clip && clip.clipY == 2 && clip.clipX === 1) {
                    clip.index = state == 1 ? 0 : 1;
                }
            }
        }
        onTabSelect(index) {
            if (index == -1) {
                this._tabView.hideView(this._lastIndex);
                this._lastIndex = -1;
                return;
            }
            if (this.isOpen[index] && this.isOpen[index].isOpen == false) {
                sg.uimgr.showNotice(this.isOpen[index].str);
                this._tab.selectedIndex = this._lastIndex;
                return;
            }
            this._changeClipIndex(this._lastIndex, 1);
            this._changeClipIndex(index, 2);
            let lastIndex = this._lastIndex;
            this._lastIndex = index;
            if (this._cBack)
                this._cBack(index, lastIndex);
            if (this._tabView)
                this._tabView.changeShowView(index, lastIndex);
        }
        clear() {
            if (this._tabView)
                this._tabView.clear();
            if (this._tab) {
                this._tab.selectHandler && this._tab.selectHandler.recover();
                this._tab.selectedIndex = -1;
            }
            this._cBack = null;
            this._lastIndex = -1;
        }
        onDisable() {
            if (this._tab) {
                this._tab.selectedIndex = -1;
            }
            this._lastIndex = -1;
        }
    }
    mvc.TabTable = TabTable;
})(mvc || (mvc = {}));

var mvc;
(function (mvc) {
    class TabView {
        constructor(tabViewCls, viewContent) {
            this._tabView = new Map();
            if (viewContent && viewContent.length > 0) {
                this._tabViewCls = tabViewCls;
                this._viewContent = viewContent;
            }
        }
        getTabView(index) {
            if (index == -1)
                return;
            let view = this._tabView.get(index);
            if (view == null) {
                for (let key in this._tabViewCls) {
                    let num = parseInt(key);
                    if (index == num) {
                        let cls = this._tabViewCls[key] || sg.ViewBase;
                        view = new cls();
                        this._tabView.set(num, view);
                        if (sg.Logger.isLogmOpen("uimgr")) {
                            sg.timer.after(1, null, () => {
                                sg.Logger.openLog && sg.logm("uimgr", "TabView Unit:" + view.configName);
                            });
                        }
                        break;
                    }
                }
            }
            view = this._tabView.get(index);
            if (!view && index >= 0) {
                sg.loge("没找到下标:" + index);
            }
            return view;
        }
        showView(index) {
            let view = this.getTabView(index);
            let node = this._viewContent[index] || this._viewContent[this._viewContent.length - 1];
            if (view) {
                if (node) {
                    let viewCls = this._tabViewCls[index];
                    if (viewCls && viewCls["checkCanOpen"]) {
                        let isCanOpen = viewCls["checkCanOpen"]();
                        if (isCanOpen) {
                            node.addChild(view);
                        }
                    }
                    else {
                        node.addChild(view);
                    }
                }
            }
        }
        hideView(index) {
            let view = this.getTabView(index);
            if (view && view.parent) {
                view.removeSelf();
            }
        }
        changeShowView(index, lastIndex) {
            if (index == lastIndex)
                return;
            this.hideView(lastIndex);
            this.showView(index);
        }
        setViewData(index, ...args) {
            if (this._tabView) {
                let params = Array.prototype.slice.call(args);
                params.unshift("");
                if (index == -2) {
                    this._tabView.forEach(function (value, key, map) {
                        if (value) {
                            value.init.apply(value, params);
                        }
                    });
                }
                else {
                    let view = this.getTabView(index);
                    if (view) {
                        view.init.apply(view, params);
                    }
                }
            }
        }
        updateViewData(index, ...args) {
            if (this._tabView) {
                let params = Array.prototype.slice.call(args);
                if (index == -2) {
                    this._tabView.forEach(function (value, key, map) {
                        if (value) {
                            value.updateData.apply(value, params);
                        }
                    });
                }
                else {
                    let view = this.getTabView(index);
                    if (view) {
                        view.updateData.apply(view, params);
                    }
                }
            }
        }
        clear() {
            this._tabView.forEach((value, key, map) => {
                value.destroy();
            });
            this._tabView.clear();
        }
    }
    mvc.TabView = TabView;
})(mvc || (mvc = {}));

